const SUKAFIGS = {};
let FIGS_READY = false;
function FIGS_LOAD() {
  if (FIGS_READY) return; FIGS_READY = true;
  ["figs-suka", "figs-te", "figs-asu", "figs-nas"].forEach(function (id) {
    const el = document.getElementById(id);
    if (el) { try { Object.assign(SUKAFIGS, JSON.parse(el.textContent)); } catch (e) {} }
  });
}
/* =================== ตัวโหลดเนื้อหา ===================
   เนื้อหาของแต่ละหัวข้ออยู่ในไฟล์ JSON ข้าง ๆ หน้านี้ และโหลดเมื่อผู้อ่าน
   เลื่อนไปถึงหัวข้อนั้นจริง ๆ ส่วนรูปเป็นไฟล์ .webp แยกที่เบราว์เซอร์
   จัดการแคชเอง — หน้าเว็บจึงเบาและเพิ่มวิชาได้ไม่จำกัด                  */
const DBCACHE = new Map();
let DB_FAILED = false;

function dbGet(coll, name) {
  const key = coll + "/" + name;
  if (DBCACHE.has(key)) return DBCACHE.get(key);
  const p = fetch("data/" + coll + "/" + name + ".json")
    .then(r => r.ok ? r.json() : null)
    .catch(() => { DB_FAILED = true; return null; });
  DBCACHE.set(key, p);
  return p;
}

function loadFigs() { return Promise.resolve(true); }
async function figReady() {}

async function topicHtml(sid, t) {
  if (typeof t.html === "string" && t.html) return t.html;
  const d = await dbGet("t", sid + "__" + t.id);
  return d && typeof d.html === "string" ? d.html : null;
}

/* ---- СУ КА: ленивая подстановка рисунков + лайтбокс ---- */
window.SUKAFIG = function (root) {
  if (typeof SUKAFIGS === "undefined") return;
  FIGS_LOAD();
  let lb = document.getElementById("figlb");
  if (!lb) {
    lb = document.createElement("div");
    lb.id = "figlb";
    lb.innerHTML = '<button class="x" aria-label="закрыть">&times;</button><img alt=""><div class="cap"></div>';
    document.body.appendChild(lb);
    const close = () => lb.classList.remove("on");
    lb.addEventListener("click", close);
    document.addEventListener("keydown", e => { if (e.key === "Escape") close(); });
  }
  const open = fg => {
    const img = fg.querySelector("img"), cap = fg.querySelector("figcaption");
    if (!img || !img.src) return;
    lb.querySelector("img").src = img.src;
    lb.querySelector(".cap").textContent = cap ? cap.textContent : "";
    lb.classList.add("on");
  };
  const io = new IntersectionObserver(es => {
    es.forEach(e => {
      if (!e.isIntersecting) return;
      const fg = e.target, id = fg.dataset.fig, img = fg.querySelector("img");
      io.unobserve(fg);
      if (img && !img.src) img.src = "figs/" + id + ".webp";
    });
  }, { rootMargin: "800px 0px" });
  root.querySelectorAll("figure.ifig[data-fig]").forEach(fg => {
    io.observe(fg);
    fg.tabIndex = 0;
    fg.addEventListener("click", () => open(fg));
    fg.addEventListener("keydown", e => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); open(fg); } });
  });
};

