    ctx.save();
    ctx.font = (weight ? weight + " " : "") + sz + 'px ' + MONO;
    const tw = ctx.measureText(s).width, th = sz + 3;
    let x0 = x; if (align === "center") x0 = x - tw / 2; else if (align === "right") x0 = x - tw;
    let y0 = y; if (base === "middle") y0 = y - th / 2; else if (base === "bottom") y0 = y - th;
