      controls: [
        { id: "lgf", label: "lg Δ f — ความไม่เสถียรสัมพัทธ์ (เลขชี้กำลัง)", min: -14, max: -8, step: 0.1, value: -13, fmt: v => "Δ f = " + sci(Math.pow(10, v), 1) },
        { id: "lgT", label: "lg T — ช่วงเวลาทำงานอิสระ, ч (log)", min: 0, max: Math.log10(T_MAXH), step: 0.01, value: Math.log10(24), fmt: v => fmtDur(Math.pow(10, v) * 3600) }
      ],
