        { id: "T1", label: "T<sub>1</sub><sup>П</sup> — เวลาเตรียม РТС, ч", min: 0.1, max: 1.5, step: 0.1, value: 0.7, fmt: v => n2(v, 1) + " ч" },
        { id: "l2", label: "l<sub>2</sub> — จำนวน СА (КО)", min: 1, max: 7, step: 1, value: 2, fmt: v => v },
        { id: "T2", label: "T<sub>2</sub><sup>П</sup> — เวลาเตรียม СА, ч", min: 0.1, max: 1.5, step: 0.1, value: 0.7, fmt: v => n2(v, 1) + " ч" },
        { id: "Tp", label: "T<sup>Р</sup> — ระยะเวลาสื่อสาร (сеанс), ч", min: 0.1, max: 0.5, step: 0.05, value: 0.2, fmt: v => n2(v, 2) + " ч" }
