              ok = CV("--ok"), crit = CV("--crit"), ln = CV("--line"), ln2 = CV("--line-2"), wash = CV("--wash"), wash2 = CV("--wash-2"), grid = CV("--grid");
        const phi = s.phi, dl = s.dl, emin = s.emin;
