        for (let m = 1; m <= nOk; m++) blocks.push({ okik: m, a: t, b: t + tItnp, kind: "ИТНП" });
        t += tItnp;
        const sv = (k === 2);                                   // 3-й сеанс — СВ вместо ТМИ
