        { id: "tmi", label: "τ<sub>ТМИ</sub> — ระยะเวลา ТМИ, мин", min: 20, max: 90, step: 5, value: 60, fmt: v => v + " мин" },
        { id: "Ti", label: "T<sub>и</sub> — ช่วงห่างระหว่าง сеанс (จากต้นถึงต้น), ч", min: 2, max: 8, step: 0.5, value: 4, fmt: v => n2(v, 1) + " ч" }
