        const x0 = labW, x1 = w - padR, pw = x1 - x0;
        const top = 16, axisH = 20;
        const rows = nOk + 1;
        const rowH = Math.min(Math.round((h - top - axisH) * (narrow ? 0.5 : 0.52)) / rows, narrow ? 34 : 46);
        const hTop = rowH * rows;                       // верх: суточная циклограмма (не выше 46 px на строку)
