        const Nvit = 86400 / T;
        const dL = 2 * Math.PI * RE * T / TSID;                       // км
        const days = dL / B;
        const detail = L <= 1;

        const narrow = w < 560, tiny = w < 420, fs = narrow ? 9 : 10.5;
        const pad = 6, gap = narrow ? 26 : 40;
        const LW = Math.round((w - pad * 2 - gap) * 0.55);
        const LX = pad, RX = LX + LW + gap, RW = w - pad - RX;
        const top = 14, bot = hgt - 6;

        /* ---------- ЛЕВО-ВЕРХ: КА над кривой поверхностью, конус поля зрения ---------- */
        const sceneH = Math.round((bot - top) * 0.58), sy0 = top, sy1 = top + sceneH;
        TX(ctx, "съёмка в надир (км)", LX, 1, ink3, "left", "top", 10);
        // масштаб: по вертикали 0…1,3h, по горизонтали не уже 1,6B (или 200 км)
        const sc = Math.min((sceneH - 30) / (h * 1.3), (LW - 10) / Math.max(B * 1.6, 200));
        const gx = LX + LW / 2, gy = sy1 - 12;                        // точка надира на поверхности
        const P = (x, y) => [gx + x * sc, gy - y * sc];               // x вдоль поверхности, y — высота
        ctx.save(); ctx.beginPath(); ctx.rect(LX, sy0 + 10, LW, sceneH - 10); ctx.clip();
        // поверхность Земли (дуга радиуса R⊕ с центром в (0, −R⊕))
        const O = P(0, -RE);
        ctx.fillStyle = wash; ctx.strokeStyle = ac; ctx.lineWidth = 1.4;
        ctx.beginPath(); ctx.arc(O[0], O[1], RE * sc, 0, 7); ctx.fill(); ctx.stroke();
        // конус поля зрения
        const Sxy = P(0, h);
        const halfB = B / 2, sag = halfB * halfB / (2 * RE);
        const A1 = P(-halfB, -sag), A2 = P(halfB, -sag);
        ctx.fillStyle = ac; ctx.globalAlpha = 0.14; ctx.beginPath(); ctx.moveTo(Sxy[0], Sxy[1]); ctx.lineTo(A1[0], A1[1]); ctx.lineTo(A2[0], A2[1]); ctx.closePath(); ctx.fill(); ctx.globalAlpha = 1;
        ctx.strokeStyle = ac; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(Sxy[0], Sxy[1]); ctx.lineTo(A1[0], A1[1]); ctx.moveTo(Sxy[0], Sxy[1]); ctx.lineTo(A2[0], A2[1]); ctx.stroke();
        // ось визирования
        ctx.setLineDash([3, 3]); ctx.strokeStyle = line2; ctx.beginPath(); ctx.moveTo(Sxy[0], Sxy[1]); ctx.lineTo(gx, gy); ctx.stroke(); ctx.setLineDash([]);
        // полоса захвата на поверхности
        ctx.strokeStyle = ac; ctx.lineWidth = 4; ctx.lineCap = "butt"; ctx.beginPath(); ctx.moveTo(A1[0], A1[1]); ctx.lineTo(A2[0], A2[1]); ctx.stroke();
        ctx.restore();
