        if (!narrow) {
          const bw = 148, bh = 24, gap = 130, gy = h - 52;
          const gx = Math.max(24, (w - 2 * bw - gap) / 2 + 30), gx2 = gx + bw + gap;
          rect(ctx, gx, gy, bw, bh, wash, ac, 1.4);
          TX(ctx, "0 — работоспособна", gx + bw / 2, gy + bh / 2, ink, "center", "middle", fs, "600");
          rect(ctx, gx2, gy, bw, bh, wash, ac2, 1.4);
          TX(ctx, "1 — ремонт", gx2 + bw / 2, gy + bh / 2, ink, "center", "middle", fs, "600");
          arc(ctx, gx + bw + 4, gx2 - 4, gy + 6, -16, ac, "λ = 1/T_ср = " + n2(lam, lam >= 0.01 ? 3 : 5) + " 1/сут", fs);
          arc(ctx, gx2 - 4, gx + bw + 4, gy + bh - 6, 16, ac2, "μ = 1/T_в = " + n2(mu, 2) + " 1/сут", fs);
          TX(ctx, "граф состояний:", 14, h - 17, ink3, "left", "bottom", fs);
          TX(ctx, "вывод — учебник §8.1.2.1", 14, h - 5, ink3, "left", "bottom", fs);
        }

