  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
  /* биномиальные вероятности через логарифмы — без переполнения C(50, 25) */
  function lnFact(k) { let s = 0; for (let i = 2; i <= k; i++) s += Math.log(i); return s; }
