          if (s.paths) { sch.push({ kind: "paths", x: 10, y: yy, w: colW - 20, h: schH - 6 }); yy += schH; }
          if (s.cuts) { sch.push({ kind: "cuts", x: 10, y: yy, w: colW - 20, h: schH - 6 }); }
