              ok = CV("--ok"), crit = CV("--crit"), grid = CV("--grid"), line2 = CV("--line-2"), panel = CV("--panel"), wash = CV("--wash");
        const narrow = w < 520;
        const wantRatio = narrow ? 0.9 : 0.56;
        if (spec.ratio !== wantRatio) { spec.ratio = wantRatio; requestAnimationFrame(() => { if (rec) rec.draw(); }); return; }
        const N = Math.round(s.N);
