        const rows = s.tab6 ? SITES : CAUSES;
        const nR = rows.length;
        const rowH = ph / nR, barH = Math.min(rowH * 0.62, 30);

        /* заголовок + шкала */
        const vmax = s.tab6 ? 14 : 60;  /* % */
        TX(ctx, s.tab6 ? "сл. 6: вероятность отказа q = m/n по площадкам, %" : "сл. 10: доля причины d = m/243, %", 8, 8, ink2, "left", "top", fs, "600");
        ctx.save(); ctx.strokeStyle = grid; ctx.lineWidth = 1;
        const nt = s.tab6 ? (narrow ? 2 : 7) : (narrow ? 3 : 6);
        for (let i = 0; i <= nt; i++) {
          const v = vmax * i / nt, px = Math.round(x0 + pw * v / vmax) + .5;
          ctx.beginPath(); ctx.moveTo(px, y0); ctx.lineTo(px, y0 + ph); ctx.stroke();
          TX(ctx, String(Math.round(v)), px, y0 + ph + 4, ink3, "center", "top", fs - 1);
        }
        ctx.restore();
        seg(ctx, Math.round(x0) + .5, y0, Math.round(x0) + .5, y0 + ph, line2, 1);
        TX(ctx, "%", x0 + pw + 16, y0 + ph + 4, ink3, "left", "top", fs - 1);

        let sumPct = 0, sumM = 0, sumExp = 0;
        rows.forEach((r, i) => {
          const cy = y0 + rowH * (i + 0.5);
          let pct, col, expN, sub;
          if (s.tab6) {
            pct = (s.asSlide ? r.slide : 100 * r.m / r.n);
            col = i === 0 ? ink3 : ac;
            expN = N * pct / 100;
            sub = r.m + " / " + r.n;
          } else {
            pct = 100 * r.m / TOTAL;
            col = r.grp === 0 ? ac : (r.grp === 1 ? ac2 : ink3);
            expN = N * q * r.m / TOTAL;
            sub = r.m + " из " + TOTAL;
            sumPct += pct; sumM += r.m; sumExp += expN;
          }
          const bw = pw * pct / vmax;
          const tx = (s.tab6 && s.asSlide && i === 0) ? Math.max(bw, pw * 100 * qCalc / vmax) + 4 : bw;
          rect(ctx, x0 + 1, cy - barH / 2, bw, barH, col);
          TX(ctx, narrow ? r.short : r.name, x0 - 8, cy - (narrow ? 0 : 6), ink, "right", "middle", fs, "600");
          if (!narrow) TX(ctx, sub, x0 - 8, cy + 7, ink3, "right", "middle", fs - 1);
          TX(ctx, n2(pct, 1) + " %", x0 + tx + 6, cy - (narrow ? 5 : 0), ink, "left", "middle", fs, "600");
          TX(ctx, "→ " + n2(expN, 1) + (narrow ? "" : " отк. при N=" + N), x0 + tx + 6, cy + (narrow ? 6 : 11), ink2, "left", "middle", fs - 1);
        });
        if (s.tab6 && s.asSlide) {
          /* пометка расхождения 6,8 vs 7,1 */
          const cy = y0 + rowH * 0.5, bw71 = pw * (100 * qCalc) / vmax;
          seg(ctx, Math.round(x0 + bw71) + .5, cy - barH / 2 - 3, Math.round(x0 + bw71) + .5, cy + barH / 2 + 3, crit, 1.5);
          TX(ctx, "243/3421 = 7,1", x0 + bw71 + 3, cy - barH / 2 - 4, crit, "left", "bottom", fs - 1, "600");
        }

