        { id: "age", label: "интенсивность старения b — во сколько ω₀ вырастает ω к 25 годам", min: 0, max: 5, step: 0.1, value: 2, fmt: v => n2(v, 1) },
        { id: "run", label: "длительность приработки τ₁, лет", min: 0.1, max: 4, step: 0.1, value: 0.5, fmt: v => n2(v, 1) },
        { id: "g", label: "γ — вероятность, %", min: 50, max: 99.9, step: 0.1, value: 95, fmt: v => n2(v, 1) }
