    if (m) { const v = parseInt(m[1], 16); return "rgba(" + (v >> 16) + "," + ((v >> 8) & 255) + "," + (v & 255) + "," + a + ")"; }
    const r = /rgba?\(([^)]+)\)/.exec(col);
