          if (t <= tmax) {
            seg(ctx, Math.round(p.X(t / tk)) + .5, p.y, Math.round(p.X(t / tk)) + .5, p.y + p.h, line2, 1, [2, 3]);
            p.dots([[t / tk, lamR / unit]], ac, 3.5);
          }
          const bxw = narrow ? 122 : 150;
          rect(ctx, p.x + 4, p.y + 4, bxw, fs * 2 + 10, panel);
