          /* какие блоки показывать */
          let items;
          const maxShow = narrow ? 8 : 12;
          if (n <= maxShow) { items = []; for (let i = 1; i <= n; i++) items.push(String(i)); }
          else items = ["1", "2", "3", "…", String(n - 1), String(n)];
