        const fs = narrow ? 9 : 10, fs2 = narrow ? 8 : 9;
        const Pa = s.Pa, sg = Math.pow(10, s.lg), Q = 1 - Pa;
        const Nv = Nreq(Pa, sg), Ni = Nint(Nv);
        const c = sg / Q;                                   // коэффициент относительной точности
        const LG = v => Math.log10(Math.max(v, 1e-3));      // безопасный log10 для оси

