          for (let e = YMIN; e <= YMAX; e++) { seg(ctx, p.x, p.Y(e), p.x + p.w, p.Y(e), grid, 1); if (!narrow || e % 2 === 0) TX(ctx, pow10(e), p.x - 6, p.Y(e), ink3, "right", "middle", fs2); }
