        const narrow = w < 520;
        const wantRatio = narrow ? 1.0 : 0.56;
        if (spec.ratio !== wantRatio) { spec.ratio = wantRatio; requestAnimationFrame(() => { if (rec) rec.draw(); }); return; }
        const lam = s.lam * 1e-5, r = s.r, lamB = r * lam, t = s.t;
        const T = 1 / lam;
        const T0 = T, T1 = 1.5 * T, T2 = (r < 1e-6) ? 2 * T : (2 * lam + lamB) / (lam * (lam + lamB)), T3 = 2 * T;
