    let x0 = x; if (align === "center") x0 = x - tw / 2; else if (align === "right") x0 = x - tw;
    let y0 = y - th; if (base === "top") y0 = y; else if (base === "middle") y0 = y - th / 2;
    ctx.globalAlpha = 0.85; ctx.fillStyle = bg; ctx.fillRect(x0 - 3, y0 - 2, tw + 6, th + 4); ctx.globalAlpha = 1;
    ctx.fillStyle = col; ctx.textAlign = align || "left"; ctx.textBaseline = base || "alphabetic";
