          for (let mm = 0; mm <= MMAX; mm++) {
            const u = (narrow ? 2.0 : 2.4) + mm * (narrow ? 0.9 : 0.75), v = pc(u, mm);
            if (u < UM) TX(ctx, "m=" + mm, p.X(u) + 3, p.Y(v) - 3, mm === m ? ac : ink3, "left", "bottom", narrow ? 7.5 : 8.5, mm === m ? "600" : undefined);
          }
