        const P = [0, s.p1, s.p2, s.p3, s.p4, s.p5], Q = P.map(v => 1 - v);
        const allEq = [2, 3, 4, 5].every(i => Math.abs(P[i] - P[1]) < 1e-9);
        const A1 = P[2] + P[5] - P[2] * P[5];                                   // P(A/H₁)
        const A2 = P[1] * P[2] + P[4] * P[5] - P[1] * P[2] * P[4] * P[5];       // P(A/H₂)
        const T1 = P[3] * A1, T2 = Q[3] * A2, PA = T1 + T2;
        const PE = enum62(P);

        /* ---- геометрия ---- */
