      p[16] = 1 - q(1) * q(2) * q(3);
      p[17] = 1 - q(4) * q(5) * q(6) * q(7);
      p[18] = bookMode ? 1 - q(8) * q(9) : 1 - q(9) * q(10);
      p[19] = 1 - q(13) * q(14);
      p[20] = p[17] * p[18] * p[12];
      p[21] = p[8] * p[11] * p[19];
