        { id: "base", label: "контроль (все λ равны)", act() { syncSliders([20, 1000, 1]); } },
        { id: "step", label: "свернуть ▸", act(s) { s.st = ((s.st === undefined ? 0 : s.st) + 1) % 5; } },
        { id: "book", label: "блок 18 как в книге", toggle: true, value: false }
