            const bx0 = x + W * (narrow ? 0.31 : 0.26), bx1 = x + W * (narrow ? 0.80 : 0.78);
            const cx15 = x + W * (narrow ? 0.93 : 0.88);
            const colX = [];
            for (let i = 0; i < cols; i++) colX.push(bx0 + (bx1 - bx0) * (cols === 1 ? 0.5 : i / (cols - 1)));
