  function sci(v, d) { if (!isFinite(v)) return "—"; return v === 0 ? "0" : (v >= 1e-4 && v < 1e5 ? n2(v, d === undefined ? 6 : d) : v.toExponential(d === undefined ? 3 : d).replace(".", ",")); }
