        { id: "lg", label: "γ = μ/ω — во сколько раз ремонт быстрее отказов (лог. шкала)", min: 0, max: 3, step: 0.05, value: 2, fmt: v => String(Math.round(Math.pow(10, v))) },
        { id: "s", label: "s — число ремонтных бригад (1 = вариант № 1, m+1 = вариант № 2)", min: 1, max: 6, step: 1, value: 2, fmt: v => String(Math.round(v)) },
        { id: "om", label: "ω — параметр потока отказов элемента, 10⁻³ 1/ч", min: 1, max: 50, step: 1, value: 10, fmt: v => String(Math.round(v)) }
