  /* ---------- утилиты в замыкании (глобальных переменных не создаём) ---------- */
  const MONO = '"IBM Plex Mono", monospace';
  function TX(ctx, s, x, y, col, align, base, size, weight) {
    ctx.save();
    ctx.font = (weight ? weight + " " : "") + (size || 11) + 'px ' + MONO;
    ctx.fillStyle = col; ctx.textAlign = align || "left"; ctx.textBaseline = base || "alphabetic";
    ctx.fillText(s, x, y);
    ctx.restore();
  }
  function rect(ctx, x, y, w, h, fill, stroke, lw) {
    ctx.save();
    if (fill) { ctx.fillStyle = fill; ctx.fillRect(x, y, w, h); }
    if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 1; ctx.strokeRect(Math.round(x) + .5, Math.round(y) + .5, Math.round(w), Math.round(h)); }
    ctx.restore();
  }
  function fillA(ctx, x, y, w, h, col, a) {
    ctx.save(); ctx.globalAlpha = a; ctx.fillStyle = col; ctx.fillRect(x, y, w, h); ctx.restore();
  }
  function seg(ctx, x1, y1, x2, y2, col, lw, dash) {
    ctx.save(); ctx.strokeStyle = col; ctx.lineWidth = lw || 1;
    if (dash) ctx.setLineDash(dash);
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke(); ctx.restore();
  }
  function n2(v, d) { d = (d === undefined) ? 2 : d; if (!isFinite(v)) return "—"; return (Math.abs(v) < Math.pow(10, -d - 1) ? 0 : v).toFixed(d).replace(".", ","); }
  function ru(v) { return Math.round(v).toLocaleString("ru-RU"); }
