          seg(ctx, xC, yC, x0, y0, ink3, 1.3);
          seg(ctx, xB, yB, x0, y0, ink3, 1.3);
          dot(ctx, x0, y0, 3, ink);
          const bw = Math.min(28, W * 0.19), bh = Math.min(17, H * 0.11);
