    const A4 = [[[1, 4], [2, 2], [3, 3], [4, 4]], [[1, 2], [2, 3], [3, 3], [4, 2]], [[1, 2], [2, 2], [3, 2], [4, 2]],
                [[1, 2], [2, 3], [3, 4]], [[1, 2], [2, 3], [3, 2]], [[1, 2], [2, 2], [3, 2]], [[1, 3], [2, 4]],
                [[1, 2], [2, 3]], [[1, 2], [2, 2]], [[1, 3], [2, 4]], [[1, 3], [2, 2], [3, 3]],
                [[1, 3], [2, 2], [3, 3], [4, 3]]];
    /* рис. А.5: [тип, n основных, m резервных] · рис. А.6: [тип, n элементов, k мажоритарного органа] */
    const A5 = [[1, 5, 4], [2, 5, 3], [3, 5, 5], [4, 4, 5], [5, 5, 2], [4, 4, 4], [4, 4, 3], [2, 4, 2], [3, 3, 2], [3, 3, 3], [2, 3, 4], [1, 3, 5]];
    const A6 = [[1, 5, 3], [6, 6, 3], [5, 5, 2], [2, 6, 2], [4, 5, 4], [1, 6, 5], [1, 3, 2], [2, 3, 2], [3, 4, 3], [1, 4, 2], [1, 6, 4], [1, 3, 2]];
