        if (fig === 1) { R.Pc = 1 - Math.pow(1 - pc, k); let g = 0; for (let i = 0; i < k; i++) g += 1 / (i + 1); R.Gt = g; R.Tc = g / lc; }
        else { R.Pc = erlang(lc * t, k); R.Gt = k; R.Tc = k / lc; }
