/* ===== /ТАУ: демонстрации ===== */
Object.assign(DEMOS, window.NASDEMOS || {});
Object.assign(DEMOS, window.TAUDEMOS || {});
/* ================= ЭОЛА: демонстрации (window.EODEMOS) ================= */
/* ================= ЭОЛА — กลุ่ม A · Тема 1 · แหล่งพลังงานบนยาน =================
   ไฟล์นี้มีแบบจำลองโต้ตอบ 9 ตัวของบรรยาย Л1 (ФЭП/СБ) และ Л2 (ТЭП, ТЭ/ЭХГ, АБ)
   ทุกเส้นโค้งคำนวณจากสมการของภาควิชาที่บันทึกไว้ใน notes/L01.md และ notes/L02.md
   (อ้างเลขแผ่นกำกับไว้เหนือทุกฟังก์ชัน) — ไม่มีเส้นที่วาดด้วยตาเปล่า
   สีทั้งหมดอ่านผ่าน CV() ภายใน draw() เท่านั้น                                    */

/* ---------- ค่าอ้างอิงร่วม (ตัวเลขจริงจากต้นฉบับ) ---------- */

/* ---- ป้ายค่าบนแกนแบบเลขกลม (แทนการส่ง min/max ดิบเข้า ticks) ---- */
function eoaNiceStep(span, n) {
  var raw = Math.abs(span) / Math.max(1, n);
  if (!(raw > 0) || !isFinite(raw)) return 1;
  var e = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), f = raw / e;
  return (f < 1.5 ? 1 : f < 3.5 ? 2 : f < 7.5 ? 5 : 10) * e;
}
function eoaTicksN(a, b, n) {
  if (!isFinite(a) || !isFinite(b) || b <= a) return [a, b];
  /* เอนจินพิมพ์ป้ายด้วย toFixed(2) — ก้าวต่ำกว่า 0,01 จะได้ป้ายซ้ำ จึงยกพื้นไว้ */
  var st = Math.max(eoaNiceStep(b - a, n), 0.01), out = [], seen = {}, lab,
    k = Math.ceil((a - st * 1e-6) / st), guard = 0, v;
  for (; k * st <= b + st * 1e-6 && guard < 400; k++, guard++) {
    v = +(k * st).toPrecision(12);
    lab = String(+v.toFixed(2));
    if (seen[lab]) continue;
    seen[lab] = 1; out.push(v);
  }
  return out.length >= 2 ? out : [a, b];
}

var EOA = {
  k: 8.617333262e-5,   /* k/q — постоянная Больцмана на заряд электрона, В/К */
  Eg: 1.12,            /* ширина запрещённой зоны кремния, эВ (ผู้เรียบเรียง) */
  bI: 6e-4,            /* температурный коэффициент I_кз, 1/К (ผู้เรียบเรียง) */
  Tref: 268.15,        /* T = −5 °C — режим программы кафедры, Л1 сл. 27      */
  Eref: 1373,          /* солнечная постоянная у Земли, Вт/м² — Л1 сл. 20     */
  Nref: 80,            /* N — число СЭ в программе кафедры, Л1 сл. 27         */
  Sref: 16,            /* S, м² — там же                                     */
  Isc: 74.60758306,    /* I_кз, А — Л1 сл. 27                                */
  Uoc: 50.3893,        /* U_хх, В — Л1 сл. 27                                */
  Um: 39.42592344,     /* U_м, В — Л1 сл. 27                                 */
  Im: 66.27968273,     /* I_м, А — Л1 сл. 27                                 */
  Pm: 2613.137697,     /* P_м, Вт — Л1 сл. 27                                */
  Aref: 2.70           /* A — коэффициент идеальности, подобран так, чтобы    */
};                     /* модель сл. 23 давала точки сл. 27 (см. eoSolarPoint) */
EOA.UocC = EOA.Uoc / EOA.Nref;          /* U_хх одного СЭ, В  = 0.6299 В      */
EOA.Scell = EOA.Sref / EOA.Nref;        /* площадь одного СЭ, м² = 0.2 м²     */

/* แบบจำลองสมมูลของ СЭ — Л1 сл. 23:  I = I_ф − I_нас·[exp(qU/(A·K·T_c)) − 1]
   สไลด์ไม่มี A (คือ A = 1) — โน้ต Замечание сл. 23 บอกว่ารูปทั่วไปมี A จึงเปิดเป็นสไลเดอร์
   I_нас ปรับเทียบให้ที่สภาวะอ้างอิง (E = 1373 Вт/м², T = −5 °C) ได้ U_хх และ I_кз ตรง сл. 27 */
function eoaCell(E, TK, A) {
  var vtR = EOA.k * EOA.Tref;
  var vRef = EOA.UocC / (A * vtR);
  var I0ref = EOA.Isc / (Math.exp(vRef) - 1);
  var I0 = I0ref * Math.pow(TK / EOA.Tref, 3) *
           Math.exp(-(EOA.Eg / (A * EOA.k)) * (1 / TK - 1 / EOA.Tref));
  var Iph = EOA.Isc * (E / EOA.Eref) * (1 + EOA.bI * (TK - EOA.Tref));
  if (Iph < 1e-6) Iph = 1e-6;
  var aVt = A * EOA.k * TK;
  return { Iph: Iph, I0: I0, aVt: aVt, Uoc: aVt * Math.log(Iph / I0 + 1) };
}
function eoaI(c, U) { return c.Iph - c.I0 * (Math.exp(U / c.aVt) - 1); }
/* จุดกำลังสูงสุด — ค้นแบบสามส่วน (P(U) เป็นฟังก์ชันโหนกเดียวบน [0, U_хх]) */
function eoaMPPu(c) {
  var lo = 0, hi = c.Uoc, i, a, b;
  for (i = 0; i < 70; i++) {
    a = lo + (hi - lo) / 3; b = hi - (hi - lo) / 3;
    if (a * eoaI(c, a) < b * eoaI(c, b)) lo = a; else hi = b;
  }
  return (lo + hi) / 2;
}
/* แรงดันคร่อม СЭ หนึ่งตัวเมื่อบังคับกระแส I ผ่าน — ใช้กับการต่ออนุกรม (Л1 сл. 25, 29)
   I ≥ I_ф → เซลล์เข้าสู่ обратное смещение ผ่าน R_ш จนถึง напряжение пробоя */
function eoaCellU(c, I, Rsh, Ubd, bypass, Ud) {
  var U;
  if (I < c.Iph) U = c.aVt * Math.log((c.Iph - I) / c.I0 + 1);
  else U = -(I - c.Iph) * Rsh;
  if (U < -Ubd) U = -Ubd - (I - c.Iph - Ubd / Rsh) * 0.02;
  if (bypass && U < -Ud) U = -Ud;
  return U;
}
/* ---------- เครื่องมือช่วยวาด ---------- */
function eoaNice(v) {
  if (!isFinite(v) || v <= 0) return 1;
  var e = Math.pow(10, Math.floor(Math.log10(v))), m = v / e;
  /* ขั้นละเอียดขึ้น — เดิมกระโดดจาก 5 ไป 10 ทำให้แกนยาวเป็นสองเท่าของข้อมูล */
  var s = m <= 1 ? 1 : m <= 1.2 ? 1.2 : m <= 1.5 ? 1.5 : m <= 2 ? 2 : m <= 2.5 ? 2.5
    : m <= 3 ? 3 : m <= 4 ? 4 : m <= 5 ? 5 : m <= 6 ? 6 : m <= 8 ? 8 : 10;
  return s * e;
}
function eoaTxt(ctx, s, x, y, color, size, align, base, bold) {
  ctx.save();
  ctx.fillStyle = color;
  ctx.font = (bold ? "600 " : "") + size + 'px "IBM Plex Mono", monospace';
  ctx.textAlign = align || "left"; ctx.textBaseline = base || "top";
  ctx.fillText(s, x, y); ctx.restore();
}
function eoaFs(w) { return w < 430 ? 9 : w < 560 ? 10 : 11; }
function eoaMark(ctx, p, x, y, color, r) {
  ctx.save(); ctx.strokeStyle = color; ctx.fillStyle = color; ctx.lineWidth = 1;
  ctx.beginPath(); ctx.arc(p.X(x), p.Y(y), r || 4, 0, 7); ctx.fill();
  ctx.globalAlpha = 0.55; ctx.setLineDash([3, 3]);
  ctx.beginPath(); ctx.moveTo(p.X(x), p.Y(y)); ctx.lineTo(p.X(x), p.y + p.h); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(p.X(x), p.Y(y)); ctx.lineTo(p.x, p.Y(y)); ctx.stroke();
  ctx.restore();
}
function eoaHLine(ctx, p, y, color, dash) {
  ctx.save(); ctx.strokeStyle = color; ctx.lineWidth = 1.2;
  if (dash) ctx.setLineDash(dash);
  ctx.beginPath(); ctx.moveTo(p.x, p.Y(y)); ctx.lineTo(p.x + p.w, p.Y(y)); ctx.stroke();
  ctx.restore();
}

/* ==== 1. eoSolarIV — ВАХ ФЭП · Л1 сл. 23–27 =================================
   I(U) = I_ф − I_нас·[exp(U/(A·k·T_c/q)) − 1]   (сл. 23)
   I = I_ф − I_D  (сл. 23, 24) · P = U·I · U(I) ของแผงอนุกรม = N_с·U(I)  (сл. 25)
   ผลของอุณหภูมิ: I_нас ~ T³·exp(−E_g/(A·k·T)) → U_хх ลด, I_кз เพิ่มเล็กน้อย (сл. 26) */
function eoSolarIV(host) {
  buildDemo(host, {
    label: "Лекция 1 · сл. 23–27",
    title: "เลื่อนความเข้มแสงและอุณหภูมิ แล้วดูจุดกำลังสูงสุด M ขยับ — เทียบกับตัวเลขโปรแกรมของภาควิชา",
    ratio: 0.60,
    legend: '<span><i style="background:var(--accent)"></i>ВАХ I(U)</span>' +
            '<span><i style="background:var(--accent-2)"></i>P(U) (в масштабе)</span>' +
            '<span><i style="background:var(--ok)"></i>точка M</span>' +
            '<span><i style="background:var(--ink-3)"></i>расчёт программы сл. 27</span>',
    controls: [
      { id: "E", label: "E — плотность потока излучения, Вт/м²", min: 100, max: 1400, step: 10, value: 1373, fmt: function (v) { return v.toFixed(0); } },
      { id: "T", label: "T<sub>c</sub> — температура СЭ, °C", min: -100, max: 60, step: 1, value: -5, fmt: function (v) { return v.toFixed(0); } },
      { id: "N", label: "N<sub>с</sub> — число СЭ в последовательной цепи", min: 1, max: 120, step: 1, value: 80, fmt: function (v) { return v.toFixed(0); } },
      { id: "A", label: "A — коэффициент идеальности диода", min: 1, max: 3, step: 0.02, value: 2.70, fmt: function (v) { return v.toFixed(2); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
          ink2 = CV("--ink-2"), ink3 = CV("--ink-3"), fs = eoaFs(w);
      var c = eoaCell(s.E, s.T + 273.15, s.A), N = s.N;
      var Uoc = c.Uoc * N, Isc = eoaI(c, 0);
      var um = eoaMPPu(c), Um = um * N, Im = eoaI(c, um), Pm = Um * Im;
      var ff = (Um * Im) / (Uoc * Isc);
      var xmax = eoaNice(Uoc * 1.15), ymax = eoaNice(Isc * 1.18);

      var iv = [], pw = [], i, U, Ii, P, Pmax = Pm;
      for (i = 0; i <= 320; i++) {
        U = c.Uoc * i / 320; Ii = eoaI(c, U); P = U * N * Ii;
        if (Ii < 0) Ii = 0;
        iv.push([U * N, Ii]); pw.push([U * N, P / Pmax * ymax * 0.94]);
      }
      var p = new Plot(ctx, 48, 18, w - 64, h - 54, 0, xmax, 0, ymax);
      p.frame(eoaTicksN(0, xmax, 6), eoaTicksN(0, ymax, 4), "U, В", "I, А");
      /* рабочая зона — штриховка ของ рис. 2.4 (сл. 24) */
      var bandPts = [];
      for (i = 0; i < iv.length; i++) bandPts.push([iv[i][0], iv[i][1], 0]);
      ctx.globalAlpha = 0.12; p.band(bandPts, acc); ctx.globalAlpha = 1;
      p.clip(function () {
        p.line(pw, acc2, 1.8, [5, 4]);
        p.line(iv, acc, 2.2);
        eoaMark(ctx, p, Um, Im, ok, 4.5);
        if (Math.abs(s.N - EOA.Nref) < 0.5) {
          ctx.save(); ctx.strokeStyle = ink3; ctx.lineWidth = 1.4;
          ctx.beginPath();
          ctx.moveTo(p.X(EOA.Um) - 5, p.Y(EOA.Im)); ctx.lineTo(p.X(EOA.Um) + 5, p.Y(EOA.Im));
          ctx.moveTo(p.X(EOA.Um), p.Y(EOA.Im) - 5); ctx.lineTo(p.X(EOA.Um), p.Y(EOA.Im) + 5);
          ctx.stroke(); ctx.restore();
        }
      });
      eoaTxt(ctx, "M", p.X(Um) + 6, p.Y(Im) - 6, ok, fs + 1, "left", "bottom", true);
      eoaTxt(ctx, "P_м = " + Pm.toFixed(0) + " Вт", p.x + p.w - 4, p.y + 2, acc2, fs, "right", "top");
      eoaTxt(ctx, "U_хх = " + Uoc.toFixed(2) + " В", p.X(Uoc) - 4, p.y + p.h - 4, ink2, fs, "right", "bottom");
      eoaTxt(ctx, "I_кз = " + Isc.toFixed(2) + " А", p.x + 4, p.Y(Isc) - 4, ink2, fs, "left", "bottom");

      var ud = Um / Uoc, id = Im / Isc, sp = Pm / (N * EOA.Scell);
      readout.innerHTML =
        'U<sub>хх</sub> = <b>' + Uoc.toFixed(2) + ' В</b>' +
        '<span>I<sub>кз</sub> = <b>' + Isc.toFixed(2) + ' А</b></span>' +
        '<span>U<sub>м</sub> = <b>' + Um.toFixed(2) + ' В</b></span>' +
        '<span>I<sub>м</sub> = <b>' + Im.toFixed(2) + ' А</b></span>' +
        '<span>P<sub>м</sub> = <b>' + Pm.toFixed(1) + ' Вт</b></span>' +
        '<span>K<sub>зап</sub> = <b>' + ff.toFixed(3) + '</b> (сл. 24 → 0.81 · программа сл. 27 → 0.695)</span>' +
        '<span>U<sub>м</sub>/U<sub>хх</sub> = <b>' + ud.toFixed(3) + '</b> · I<sub>м</sub>/I<sub>кз</sub> = <b>' + id.toFixed(3) + '</b></span>' +
        '<span>удельная мощность = <b class="' + (sp >= 165 ? "good" : "bad") + '">' + sp.toFixed(0) + ' Вт/м²</b> ' +
        '(табл. НПП «Квант» сл. 35: 200 при 25 °C, 165–170 при 60 °C)</span>' +
        '<span>เทียบ сл. 27 (E = 1373, T = −5 °C, N<sub>с</sub> = 80): U<sub>хх</sub> 50.39 В · I<sub>кз</sub> 74.61 А · P<sub>м</sub> 2613 Вт</span>';
    }
  });
}

/* ==== 2. eoSolarPoint — 0,9 หรือไม่ 0,9 · Л1 сл. 24 vs сл. 27 ================
   จากแบบจำลอง сл. 23 ที่จุด M ได้เงื่อนไข (1 + u)·e^u = e^v, u = U_м/(A·U_T), v = U_хх/(A·U_T)
   → U_м/U_хх และ I_м/I_кз ขึ้นกับ v เท่านั้น · เส้นอ้างอิง 0,9 (сл. 24) กับ 0,888 / 0,782 (сл. 27) */
function eoSolarPoint(host) {
  buildDemo(host, {
    label: "Лекция 1 · сл. 24 ↔ сл. 27",
    title: "อัตราส่วนที่จุด M เทียบกับค่าประมาณ 0,9 ของสไลด์ 24 และค่าจริงของโปรแกรมภาควิชา (สไลด์ 27)",
    ratio: 0.60,
    legend: '<span><i style="background:var(--accent)"></i>U<sub>м</sub>/U<sub>хх</sub></span>' +
            '<span><i style="background:var(--accent-2)"></i>I<sub>м</sub>/I<sub>кз</sub></span>' +
            '<span><i style="background:var(--ok)"></i>K<sub>зап</sub> = U<sub>м</sub>I<sub>м</sub>/(U<sub>хх</sub>I<sub>кз</sub>)</span>' +
            '<span><i style="background:var(--ink-3)"></i>значения источника</span>',
    controls: [
      { id: "A", label: "A — коэффициент идеальности диода", min: 1, max: 3, step: 0.02, value: 2.70, fmt: function (v) { return v.toFixed(2); } },
      { id: "T", label: "T<sub>c</sub> — температура СЭ, °C", min: -100, max: 60, step: 1, value: -5, fmt: function (v) { return v.toFixed(0); } },
      { id: "E", label: "E — плотность потока излучения, Вт/м²", min: 100, max: 1400, step: 10, value: 1373, fmt: function (v) { return v.toFixed(0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
          ink3 = CV("--ink-3"), ink2 = CV("--ink-2"), fs = eoaFs(w);
      var cu = [], ci = [], cf = [], i, A, c, um, Uo, Is, Um, Im;
      for (i = 0; i <= 120; i++) {
        A = 1 + 2 * i / 120;
        c = eoaCell(s.E, s.T + 273.15, A);
        um = eoaMPPu(c); Uo = c.Uoc; Is = eoaI(c, 0); Um = um; Im = eoaI(c, um);
        cu.push([A, Um / Uo]); ci.push([A, Im / Is]); cf.push([A, Um * Im / (Uo * Is)]);
      }
      var p = new Plot(ctx, 48, 18, w - 64, h - 54, 1, 3, 0.6, 1);
      p.frame(ticks(1, 3, 4), eoaTicksN(0.6, 1, 4), "A","отношение");
      eoaHLine(ctx, p, 0.9, ink3, [6, 4]);
      eoaHLine(ctx, p, 0.888, acc2, [3, 3]);
      eoaHLine(ctx, p, 0.782, acc, [3, 3]);
      eoaHLine(ctx, p, 0.81, ink3, [2, 4]);
      eoaHLine(ctx, p, 0.695, ok, [3, 3]);
      eoaTxt(ctx, "0.900 — сл. 24", p.x + 4, p.Y(0.9) - 3, ink3, fs, "left", "bottom");
      eoaTxt(ctx, "0.888 — сл. 27", p.x + p.w - 4, p.Y(0.888) + 3, acc2, fs, "right", "top");
      eoaTxt(ctx, "0.810 — K_зап по сл. 24", p.x + p.w - 4, p.Y(0.81) - 3, ink3, fs, "right", "bottom");
      eoaTxt(ctx, "0.782 — сл. 27", p.x + 4, p.Y(0.782) + 3, acc, fs, "left", "top");
      eoaTxt(ctx, "0.695 — K_зап по сл. 27", p.x + p.w - 4, p.Y(0.695) + 3, ok, fs, "right", "top");
      p.clip(function () {
        p.line(cu, acc, 2.2); p.line(ci, acc2, 2.2); p.line(cf, ok, 2);
      });
      var cc = eoaCell(s.E, s.T + 273.15, s.A), u0 = eoaMPPu(cc);
      var UO = cc.Uoc, IS = eoaI(cc, 0), UM = u0, IM = eoaI(cc, u0);
      var ru = UM / UO, ri = IM / IS, ff = ru * ri;
      ctx.save(); ctx.fillStyle = ink2;
      [ru, ri, ff].forEach(function (v) {
        ctx.beginPath(); ctx.arc(p.X(s.A), p.Y(v), 3.5, 0, 7); ctx.fill();
      });
      ctx.strokeStyle = ink2; ctx.globalAlpha = 0.5; ctx.setLineDash([3, 3]);
      ctx.beginPath(); ctx.moveTo(p.X(s.A), p.y); ctx.lineTo(p.X(s.A), p.y + p.h); ctx.stroke();
      ctx.restore();

      var errU = Math.abs(ru - 0.9) / 0.9 * 100, errI = Math.abs(ri - 0.9) / 0.9 * 100;
      readout.innerHTML =
        'U<sub>м</sub>/U<sub>хх</sub> = <b>' + ru.toFixed(3) + '</b>' +
        '<span>I<sub>м</sub>/I<sub>кз</sub> = <b>' + ri.toFixed(3) + '</b></span>' +
        '<span>K<sub>зап</sub> = <b>' + ff.toFixed(3) + '</b></span>' +
        '<span>отклонение от оценки сл. 24: по напряжению <b class="' + (errU > 5 ? "bad" : "good") + '">' + errU.toFixed(1) + ' %</b>' +
        ' · по току <b class="' + (errI > 5 ? "bad" : "good") + '">' + errI.toFixed(1) + ' %</b></span>' +
        '<span>ที่ A = 2.70 แบบจำลองสไลด์ 23 ให้ 0.782 / 0.888 ตรงกับโปรแกรมภาควิชา (สไลด์ 27) พอดี · ที่ A = 1 (รูปที่พิมพ์บนสไลด์) ได้ ≈ 0.88 / 0.96 คือ K<sub>зап</sub> ≈ 0.85</span>' +
        '<span class="bad">จุดขัดแย้งของต้นฉบับ: สไลด์ 24 ให้ U<sub>м</sub> ≈ 0,9·U<sub>хх</sub> และ I<sub>м</sub> ≈ 0,9·I<sub>кз</sub> (K<sub>зап</sub> = 0,81) แต่โปรแกรมของภาควิชาเอง (สไลด์ 27) ให้ 0,782 / 0,888 (K<sub>зап</sub> = 0,695) — ค่าประมาณ 0,9 ใช้ได้ดีกับกระแส แต่ไม่ดีกับแรงดัน</span>';
    }
  });
}

/* ==== 3. eoSolarArray — ต่ออนุกรม/ขนาน · เงา · ไดโอดบายพาส · Л1 сл. 25, 29, 32
   อนุกรม: U(I) = ΣU_i(I) (сл. 25) · ขนาน: I(U) = ΣI_j(U) (сл. 25)
   เซลล์ที่ถูกบัง I_ф ลดลง → เมื่อ I สายเกิน I_ф ของมัน มันเข้าสู่ обратное смещение
   ผ่าน R_ш จนถึง напряжение пробоя U_проб (сл. 24, 29) และร้อนจนไหม้ (สาเหตุ деградация ข้อ 1, сл. 30)
   ไดโอดบายพาส (обходной/шунтирующий) หนีบแรงดันเซลล์ไว้ที่ −U_д              */
function eoSolarArray(host) {
  buildDemo(host, {
    label: "Лекция 1 · сл. 25, 29, 30",
    title: "บังเซลล์เดียวในสายอนุกรม แล้วกดปุ่มไดโอดบายพาส — ดูกำลังที่หายไปและความร้อนในเซลล์ที่ถูกบัง",
    ratio: 0.64,
    legend: '<span><i style="background:var(--accent)"></i>ВАХ с обходными диодами</span>' +
            '<span><i style="background:var(--accent-2)"></i>ВАХ без диодов</span>' +
            '<span><i style="background:var(--ok)"></i>P(U) активного варианта</span>' +
            '<span><i style="background:var(--crit)"></i>затенённый СЭ</span>',
    buttons: [
      { id: "byp", label: "обходные (шунтирующие) диоды", toggle: true, value: true }
    ],
    controls: [
      { id: "Ns", label: "N<sub>с</sub> — число СЭ в цепи", min: 2, max: 40, step: 1, value: 12, fmt: function (v) { return v.toFixed(0); } },
      { id: "Np", label: "N<sub>п</sub> — число параллельных цепей", min: 1, max: 8, step: 1, value: 1, fmt: function (v) { return v.toFixed(0); } },
      { id: "sh", label: "затенение одного СЭ, %", min: 0, max: 100, step: 1, value: 60, fmt: function (v) { return v.toFixed(0); } },
      { id: "Rsh", label: "R<sub>ш</sub> — сопротивление утечки СЭ, Ом", min: 0.05, max: 2, step: 0.05, value: 0.4, fmt: function (v) { return v.toFixed(2); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
          crit = CV("--crit"), ink2 = CV("--ink-2"), ink3 = CV("--ink-3"),
          line2 = CV("--line-2"), fs = eoaFs(w);
      var Ud = 0.7, Ubd = 20, TK = EOA.Tref;
      var lit = eoaCell(EOA.Eref, TK, EOA.Aref);
      var shd = eoaCell(EOA.Eref * (1 - s.sh / 100), TK, EOA.Aref);
      var Ns = s.Ns, Np = s.Np, Imax = lit.Iph * 1.02;

      function curve(byp) {
        var out = [], i, I, U;
        for (i = 0; i <= 400; i++) {
          I = Imax * i / 400;
          U = (Ns - 1) * eoaCellU(lit, I, s.Rsh, Ubd, byp, Ud) + eoaCellU(shd, I, s.Rsh, Ubd, byp, Ud);
          out.push([U, I * Np]);
        }
        return out;
      }
      function best(byp) {
        var i, I, U, P, bp = 0, bI = 0, bU = 0;
        for (i = 1; i <= 800; i++) {
          I = Imax * i / 800;
          U = (Ns - 1) * eoaCellU(lit, I, s.Rsh, Ubd, byp, Ud) + eoaCellU(shd, I, s.Rsh, Ubd, byp, Ud);
          P = U * I * Np;
          if (P > bp) { bp = P; bI = I; bU = U; }
        }
        return { P: bp, I: bI, U: bU };
      }
      var cOn = curve(true), cOff = curve(false), mOn = best(true), mOff = best(false);
      var act = s.byp ? mOn : mOff, aCur = s.byp ? cOn : cOff;
      /* กำลังของสายที่ไม่มีเงาเลย — เป็นทั้งฐานเทียบและกระแสที่ตัวควบคุมพยายามคงไว้ */
      var un = eoaMPPu(lit), Ifix = eoaI(lit, un), Pfull = un * Ns * Ifix * Np;
      /* สถานการณ์ของ сл. 29: เมื่อตัวควบคุมคงกระแสสายไว้ที่ I_м ของสายที่ไม่มีเงา
         เซลล์ที่ถูกบังจะถูก обратное смещение และกลายเป็นโหลดที่ร้อนจนไหม้ */
      function hot(byp) {
        var Uh = eoaCellU(shd, Ifix, s.Rsh, Ubd, byp, Ud);
        var Ic = (byp && Uh <= -Ud + 1e-9) ? (shd.Iph + Ud / s.Rsh) : Ifix;
        return { U: Uh, P: Math.abs(Uh) * Ic, I: Ic };
      }
      var hOn = hot(true), hOff = hot(false), hAct = s.byp ? hOn : hOff;

      var xmax = eoaNice(Ns * lit.Uoc * 1.15), xmin = -eoaNice(Ubd * 1.1);
      if (s.byp) xmin = -eoaNice(Ns * lit.Uoc * 0.12);
      var ymax = eoaNice(lit.Iph * Np * 1.15);
      var top = 30;
      /* แถบผังสาย: СЭ เรียงอนุกรม เซลล์ที่ถูกบังเป็นสีเตือน + สามเหลี่ยมไดโอดเมื่อเปิด */
      var bw = Math.min(14, (w - 70) / Ns), bx = 48, by = 6;
      ctx.save();
      for (var q = 0; q < Ns; q++) {
        ctx.fillStyle = (q === Math.floor(Ns / 2)) ? crit : acc;
        ctx.globalAlpha = (q === Math.floor(Ns / 2)) ? 0.85 : 0.5;
        ctx.fillRect(bx + q * bw + 1, by, Math.max(2, bw - 2), 11);
        if (s.byp) {
          ctx.globalAlpha = 0.9; ctx.strokeStyle = ok; ctx.lineWidth = 1;
          ctx.beginPath();
          ctx.moveTo(bx + q * bw + 1, by + 17); ctx.lineTo(bx + q * bw + bw - 1, by + 17);
          ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(bx + q * bw + bw / 2 - 3, by + 14);
          ctx.lineTo(bx + q * bw + bw / 2 + 3, by + 14);
          ctx.lineTo(bx + q * bw + bw / 2, by + 20); ctx.closePath();
          ctx.fillStyle = ok; ctx.fill();
        }
      }
      ctx.restore();
      eoaTxt(ctx, s.byp ? "цепь с обходными диодами" : "цепь без обходных диодов",
             w - 6, by + 2, s.byp ? ok : crit, fs, "right", "top", true);

      var p = new Plot(ctx, 48, top, w - 64, h - top - 36, xmin, xmax, 0, ymax);
      p.frame(eoaTicksN(xmin, xmax, 6), eoaTicksN(0, ymax, 4), "U, В", "I, А");
      ctx.save(); ctx.strokeStyle = line2; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(p.X(0), p.y); ctx.lineTo(p.X(0), p.y + p.h); ctx.stroke();
      ctx.restore();
      var pw = [], i;
      for (i = 0; i < aCur.length; i++) pw.push([aCur[i][0], aCur[i][0] * aCur[i][1] / Math.max(act.P, 1e-6) * ymax * 0.9]);
      p.clip(function () {
        p.line(pw, ok, 1.6, [5, 4]);
        p.line(s.byp ? cOff : cOn, s.byp ? acc2 : acc, 1.4, [3, 3]);
        p.line(aCur, s.byp ? acc : acc2, 2.4);
        eoaMark(ctx, p, act.U, act.I * Np, ink2, 4);
      });
      {
        var mt = "M: " + act.P.toFixed(0) + " Вт";
        ctx.save(); ctx.font = "bold " + fs + 'px "IBM Plex Mono", monospace';
        var mtw = ctx.measureText(mt).width; ctx.restore();
        var mr = p.X(act.U) + 6 + mtw <= p.x + p.w - 2;
        eoaTxt(ctx, mt, p.X(act.U) + (mr ? 6 : -6), Math.max(p.y + fs + 2, p.Y(act.I * Np) - 6),
               ink2, fs, mr ? "left" : "right", "bottom", true);
      }

      var loss = Pfull > 0 ? (1 - act.P / Pfull) * 100 : 0;
      readout.innerHTML =
        'P<sub>м</sub> активного варианта = <b>' + act.P.toFixed(0) + ' Вт</b>' +
        '<span>с диодами <b>' + mOn.P.toFixed(0) + ' Вт</b> · без диодов <b>' + mOff.P.toFixed(0) + ' Вт</b></span>' +
        '<span>цепь без затенения даёт <b>' + Pfull.toFixed(0) + ' Вт</b> → потеря <b class="' + (loss > 20 ? "bad" : "good") + '">' + loss.toFixed(1) + ' %</b></span>' +
        '<span>สถานการณ์ของ сл. 29 — ตัวควบคุมคงกระแสสายไว้ที่ I<sub>м</sub> ของสายที่ไม่มีเงา (<b>' + Ifix.toFixed(1) + ' А</b>): U<sub>обр</sub> คร่อมเซลล์ที่ถูกบัง = <b>' + hAct.U.toFixed(2) + ' В</b></span>' +
        '<span>P<sub>обр</sub> = |U<sub>обр</sub>|·I<sub>через СЭ</sub> = ' + Math.abs(hAct.U).toFixed(2) + ' В · ' + hAct.I.toFixed(1) + ' А = <b class="' + (hAct.P > 20 ? "bad" : "good") + '">' + hAct.P.toFixed(0) + ' Вт</b> · без диодов <b class="bad">' + hOff.P.toFixed(0) + ' Вт</b> → с диодами <b class="good">' + hOn.P.toFixed(0) + ' Вт</b>' +
          (s.byp ? ' — เมื่อมีไดโอดบายพาส กระแสสายส่วนใหญ่ไหลผ่านไดโอด เหลือผ่านเซลล์เพียง ' + hAct.I.toFixed(1) + ' А จาก ' + Ifix.toFixed(1) + ' А' : '') + '</span>' +
        '<span>U<sub>хх</sub> цепи = <b>' + (Ns * lit.Uoc).toFixed(2) + ' В</b> = N<sub>с</sub>·U<sub>хх</sub>(СЭ) · I<sub>кз</sub> = <b>' + (lit.Iph * Np).toFixed(1) + ' А</b> = N<sub>п</sub>·I<sub>кз</sub>(СЭ) — правила сл. 25</span>' +
        '<span>ค่าที่สมมติ (ผู้เรียบเรียง — สไลด์ไม่ให้): U<sub>проб</sub> = 20 В · U<sub>д</sub> ของไดโอดบายพาส = 0,7 В · สไลด์ 29 แสดงแต่ปรากฏการณ์ обратное смещение ส่วนไดโอดบายพาสมาจาก Конспект ข้อ 3</span>';
    }
  });
}

/* ==== 4. eoSolarAngle — กำลังของ СБ กับการวางแนว · Л1 сл. 28 =================
   P_М = P_Mα = C·η·k_Д·k_ЗЭ·S·cos α   (сл. 28)
   P̄_max = P_max(φ)/P_max(0) = cos φ · P_max(0) = C·η·k_Д·k_ЗЭ·S
   ค่า C เลือกจากตารางค่าคงที่สุริยะของดาวเคราะห์ (сл. 20)                       */
function eoSolarAngle(host) {
  var PL = [["Меркурий", 9250], ["Венера", 2730], ["Земля", 1373], ["Марс", 610], ["Юпитер", 52], ["Сатурн", 15.4]];
  buildDemo(host, {
    label: "Лекция 1 · сл. 28 (+ таблица сл. 20)",
    title: "หมุนแผงออกจากทิศดวงอาทิตย์ แล้วดูกำลังตกตาม cos α — และเทียบดาวเคราะห์ต่าง ๆ",
    ratio: 0.58,
    legend: '<span><i style="background:var(--accent)"></i>P̄<sub>max</sub> = cos φ</span>' +
            '<span><i style="background:var(--ok)"></i>рабочая точка α</span>' +
            '<span><i style="background:var(--accent-2)"></i>нормаль n̄ и направление на Солнце s̄</span>',
    controls: [
      { id: "a", label: "α — угол отклонения нормали от направления на Солнце, град", min: -90, max: 90, step: 1, value: 5, fmt: function (v) { return v.toFixed(0); } },
      { id: "pl", label: "планета (C — солнечная постоянная)", min: 0, max: 5, step: 1, value: 2, fmt: function (v) { return PL[v][0] + " · " + PL[v][1] + " Вт/м²"; } },
      { id: "S", label: "S — геометрическая площадь панели, м²", min: 1, max: 50, step: 1, value: 16, fmt: function (v) { return v.toFixed(0); } },
      { id: "eta", label: "η — КПД СБ", min: 0.05, max: 0.3, step: 0.005, value: 0.14, fmt: function (v) { return v.toFixed(3); } },
      { id: "kd", label: "k<sub>Д</sub> — коэффициент деградации вспомогательных элементов", min: 0.8, max: 1, step: 0.005, value: 0.95, fmt: function (v) { return v.toFixed(3); } },
      { id: "kz", label: "k<sub>ЗЭ</sub> — коэффициент заполнения площади ФЭП", min: 0.7, max: 0.98, step: 0.005, value: 0.9, fmt: function (v) { return v.toFixed(3); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
          ink2 = CV("--ink-2"), ink3 = CV("--ink-3"), line2 = CV("--line-2"), fs = eoaFs(w);
      var pi = Math.max(0, Math.min(5, Math.round(s.pl)));
      var C = PL[pi][1], al = s.a * Math.PI / 180;
      var P0 = C * s.eta * s.kd * s.kz * s.S, P = P0 * Math.cos(al);
      if (P < 0) P = 0;
      var narrow = w < 520;
      var gw = narrow ? w : Math.round(w * 0.42);
      var gh = narrow ? Math.round(h * 0.46) : h;

      /* ---- ผังเรขาคณิต (рис. 2.10 а) ---- */
      var cx = gw / 2, cy = narrow ? gh / 2 : h / 2 + 4, R = Math.min(gw, gh) * 0.30;
      ctx.save();
      ctx.strokeStyle = acc2; ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.arc(cx + R * 1.35, cy - R * 1.05, 8, 0, 7); ctx.stroke();
      var i;
      for (i = 0; i < 8; i++) {
        var ag = i * Math.PI / 4;
        ctx.beginPath();
        ctx.moveTo(cx + R * 1.35 + 10 * Math.cos(ag), cy - R * 1.05 + 10 * Math.sin(ag));
        ctx.lineTo(cx + R * 1.35 + 14 * Math.cos(ag), cy - R * 1.05 + 14 * Math.sin(ag));
        ctx.stroke();
      }
      /* ทิศไปดวงอาทิตย์ s̄ — ตรึงไว้ · แผงหมุนไปตาม α */
      var sx = Math.cos(-Math.PI / 4), sy = Math.sin(-Math.PI / 4);
      ctx.strokeStyle = ink3; ctx.setLineDash([4, 3]); ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + sx * R * 1.5, cy + sy * R * 1.5); ctx.stroke();
      ctx.setLineDash([]);
      /* แผง: ตั้งฉากกับ n̄ ที่เอียงจาก s̄ ไป α */
      var na = -Math.PI / 4 + al;
      var nx = Math.cos(na), ny = Math.sin(na);
      ctx.strokeStyle = acc; ctx.lineWidth = 5; ctx.globalAlpha = 0.85;
      ctx.beginPath();
      ctx.moveTo(cx - ny * R, cy + nx * R); ctx.lineTo(cx + ny * R, cy - nx * R);
      ctx.stroke(); ctx.globalAlpha = 1;
      ctx.strokeStyle = acc2; ctx.lineWidth = 1.8;
      ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(cx + nx * R * 1.15, cy + ny * R * 1.15); ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(cx + nx * R * 1.15, cy + ny * R * 1.15);
      ctx.lineTo(cx + nx * R * 1.15 - 7 * Math.cos(na - 0.4), cy + ny * R * 1.15 - 7 * Math.sin(na - 0.4));
      ctx.lineTo(cx + nx * R * 1.15 - 7 * Math.cos(na + 0.4), cy + ny * R * 1.15 - 7 * Math.sin(na + 0.4));
      ctx.closePath(); ctx.fillStyle = acc2; ctx.fill();
      ctx.strokeStyle = ok; ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.arc(cx, cy, R * 0.55, Math.min(-Math.PI / 4, na), Math.max(-Math.PI / 4, na));
      ctx.stroke();
      ctx.restore();
      eoaTxt(ctx, "n̄", cx + nx * R * 1.3, cy + ny * R * 1.3, acc2, fs + 1, "center", "middle", true);
      eoaTxt(ctx, "s̄", cx + sx * R * 1.65, cy + sy * R * 1.65, ink3, fs + 1, "center", "middle", true);
      eoaTxt(ctx, "α = " + s.a.toFixed(0) + "°", cx, cy + R * 0.75, ok, fs + 1, "center", "top", true);
      eoaTxt(ctx, "ФЭП", cx - ny * R - 6, cy + nx * R + 6, acc, fs, "center", "top");

      /* ---- กราฟระฆัง P̄(φ) = cos φ (рис. 2.10 б) ---- */
      var px = narrow ? 48 : gw + 34, py = narrow ? gh + 18 : 18;
      var pw2 = w - px - 16, ph2 = (narrow ? h - gh - 52 : h - 54);
      var p = new Plot(ctx, px, py, pw2, ph2, -90, 90, 0, 1);
      p.frame(ticks(-90, 90, 6), eoaTicksN(0, 1, 4), "φ, град","P̄_max");
      var bell = [];
      for (i = -90; i <= 90; i++) bell.push([i, Math.max(0, Math.cos(i * Math.PI / 180))]);
      p.clip(function () {
        var bp = [];
        for (i = 0; i < bell.length; i++) bp.push([bell[i][0], bell[i][1], 0]);
        ctx.globalAlpha = 0.12; p.band(bp, acc); ctx.globalAlpha = 1;
        p.line(bell, acc, 2.2);
        eoaMark(ctx, p, s.a, Math.max(0, Math.cos(al)), ok, 4.5);
      });

      var udP = P / s.S;
      readout.innerHTML =
        'P<sub>max</sub>(0) = C·η·k<sub>Д</sub>·k<sub>ЗЭ</sub>·S = <b>' + P0.toFixed(1) + ' Вт</b>' +
        '<span>P<sub>М</sub>(α) = <b>' + P.toFixed(1) + ' Вт</b></span>' +
        '<span>P̄<sub>max</sub> = cos α = <b class="' + (Math.cos(al) < 0.5 ? "bad" : "good") + '">' + Math.max(0, Math.cos(al)).toFixed(3) + '</b></span>' +
        '<span>удельная мощность = <b>' + udP.toFixed(1) + ' Вт/м²</b> · планета: <b>' + PL[pi][0] + '</b>, C = <b>' + C + ' Вт/м²</b></span>' +
        '<span>ตรวจกับโปรแกรมภาควิชา (сл. 27): ที่ C = 1373, S = 16 м², α = 5° และ η·k<sub>Д</sub>·k<sub>ЗЭ</sub> = 0.120 ได้ P<sub>М</sub> ≈ 2613 Вт — ตรงกับ P<sub>м</sub> ที่โปรแกรมแสดง</span>' +
        '<span>บทเรียนของตาราง сл. 20: ที่ดาวพฤหัส C = 52 Вт/м² คือ <b>' + (1373 / 52).toFixed(0) + ' เท่า</b> ที่น้อยกว่าโลก จึงต้องใช้พื้นที่มากเท่านั้นเพื่อกำลังเท่ากัน — เหตุผลที่ยานสำรวจไกลใช้ РИТЭГ แทน СБ</span>' +
        '<span>หมายเหตุต้นฉบับ: สไลด์ 20 ใช้สัญลักษณ์ E<sub>C</sub> แต่สไลด์ 28–29 ใช้ C สำหรับปริมาณเดียวกัน</span>';
    }
  });
}

/* ==== 5. eoSolarDeg — การเสื่อมของ СБ · Л1 сл. 35 (табл. НПП «Квант») vs сл. 30
   ตาราง сл. 35 ให้ деградация рабочего тока за 10 лет ตามวงโคจรและวัสดุ
   สไลด์ 30 ให้ «скорость деградации 10…15 % в год» — สองแหล่งขัดกัน 5–10 เท่า
   เส้นตาราง: P/P₀ = (1 − D₁₀)^(t/10) · เส้นสไลด์ 30: (1 − r)^t, r = 0,10 และ 0,15 */
function eoSolarDeg(host) {
  var MAT = ["монокристаллический кремний", "GaInP2-GaInAs-Ge (3 каскада)", "аморфный кремний"];
  var ORB = ["ГСО", "низкая орбита", "эллиптическая и промежуточная"];
  var D10 = [[20, 20, 30], [15, 15, 25], [7, 7, 7]];
  buildDemo(host, {
    label: "Лекция 1 · сл. 35 ↔ сл. 30",
    title: "กำลังที่เหลือของ СБ ตามปี — เส้นจากตารางผู้ผลิต เทียบกับตัวเลข «10–15 % ต่อปี» ของสไลด์ 30",
    ratio: 0.58,
    legend: '<span><i style="background:var(--accent)"></i>табл. НПП «Квант», сл. 35</span>' +
            '<span><i style="background:var(--crit)"></i>«10…15 % в год», сл. 30</span>' +
            '<span><i style="background:var(--ok)"></i>текущий год</span>',
    controls: [
      { id: "t", label: "срок активного существования, лет", min: 0, max: 10, step: 0.25, value: 10, fmt: function (v) { return v.toFixed(2); } },
      { id: "m", label: "материал СБ", min: 0, max: 2, step: 1, value: 0, fmt: function (v) { return MAT[v]; } },
      { id: "o", label: "орбита", min: 0, max: 2, step: 1, value: 1, fmt: function (v) { return ORB[v]; } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), crit = CV("--crit"), ok = CV("--ok"),
          ink2 = CV("--ink-2"), ink3 = CV("--ink-3"), fs = eoaFs(w);
      var mi = Math.max(0, Math.min(2, Math.round(s.m))), oi = Math.max(0, Math.min(2, Math.round(s.o)));
      var d = D10[mi][oi] / 100;
      var kt = function (t) { return Math.pow(1 - d, t / 10); };
      var k10 = function (t) { return Math.pow(0.9, t); };
      var k15 = function (t) { return Math.pow(0.85, t); };
      var a = [], b = [], i, t;
      for (i = 0; i <= 200; i++) { t = 10 * i / 200; a.push([t, kt(t) * 100]); b.push([t, k15(t) * 100, k10(t) * 100]); }
      var p = new Plot(ctx, 48, 18, w - 64, h - 54, 0, 10, 0, 100);
      p.frame(ticks(0, 10, 5), eoaTicksN(0, 100, 5), "t, лет","P/P₀, %");
      p.clip(function () {
        ctx.globalAlpha = 0.16; p.band(b, crit); ctx.globalAlpha = 1;
        p.line(b.map(function (r) { return [r[0], r[1]]; }), crit, 1.6, [4, 4]);
        p.line(b.map(function (r) { return [r[0], r[2]]; }), crit, 1.6, [4, 4]);
        p.line(a, acc, 2.4);
        eoaMark(ctx, p, s.t, kt(s.t) * 100, ok, 4.5);
      });
      eoaTxt(ctx, "табл. сл. 35: −" + (d * 100).toFixed(0) + " % за 10 лет", p.x + 6, p.Y(kt(10) * 100) - 6, acc, fs, "left", "bottom");
      eoaTxt(ctx, "сл. 30: 10…15 % в год", p.x + p.w - 6, p.Y(k10(3) * 100) + 4, crit, fs, "right", "top");

      var vt = kt(s.t) * 100, v10 = k10(s.t) * 100, v15 = k15(s.t) * 100;
      var rat = v15 > 0 ? vt / v15 : 0;
      readout.innerHTML =
        'через <b>' + s.t.toFixed(2) + ' лет</b> остаётся:' +
        '<span>по табл. НПП «Квант» (сл. 35) — <b class="good">' + vt.toFixed(1) + ' %</b></span>' +
        '<span>по «10 % в год» (сл. 30) — <b>' + v10.toFixed(1) + ' %</b> · по «15 % в год» — <b class="bad">' + v15.toFixed(1) + ' %</b></span>' +
        '<span>расхождение источников: <b class="' + (rat > 1.5 ? "bad" : "good") + '">' + rat.toFixed(1) + ' раз</b></span>' +
        '<span>материал: <b>' + MAT[mi] + '</b> · орбита: <b>' + ORB[oi] + '</b> · деградация рабочего тока за САС по таблице: <b>' + (d * 100).toFixed(0) + ' %</b>' +
        (mi === 2 ? ' (для аморфного кремния таблица даёт одно значение «радиационная деградация ~7 %» на все орбиты)' : '') + '</span>' +
        '<span class="bad">จุดขัดแย้งของต้นฉบับ: สไลด์ 30 ระบุ «скорость деградации 10…15 % в год» แต่ตาราง НПП «Квант» สไลด์ 35 ให้ 15–30 % ต่อ 10 ปี (≈ 1,5–3 % ต่อปี) — ต่างกัน 5–10 เท่า · ตารางสไลด์ 35 เป็นข้อมูลผู้ผลิตจริงจึงน่าเชื่อถือกว่า ตัวเลขสไลด์ 30 น่าจะเป็นค่าเฉพาะกรณี (ปีแรก หรือวงโคจรที่ผ่านแถบ Ван Аллена สไลด์ 31) — ต้องถามอาจารย์</span>';
    }
  });
}

/* ==== 6. eoSolarSpectrum — สเปกตรัมกับวัสดุและเซลล์หลายรอยต่อ · Л1 сл. 20, 32, 33
   สเปกตรัมประมาณด้วยการแผ่รังสีวัตถุดำ 5778 К ปรับสเกลให้ ∫E_λ dλ = E_C = 1373 Вт/м² (сл. 20)
   ขอบเขตชั้นตาม сл. 33: GaInP 350–650, GaAs 650–920, Ge 920–1800 нм · E_g = 1239,84/λ_г, эВ
   กระแสของชั้น i: J_i = ∫ E_λ·λ/1239,84 dλ  (โฟตอนหนึ่งตัวให้อิเล็กตรอนหนึ่งตัว)
   ชั้นต่ออนุกรม → กระแสรวมถูกจำกัดโดยชั้นที่น้อยที่สุด (сл. 32)                */
function eoSolarSpectrum(host) {
  buildDemo(host, {
    label: "Лекция 1 · сл. 20, 32, 33",
    title: "แบ่งสเปกตรัมให้ชั้น GaInP / GaAs / Ge — ดูว่าทำไมสามรอยต่อจึงได้ КПД สูงกว่าหนึ่งรอยต่อเท่าตัว",
    ratio: 0.60,
    legend: '<span><i style="background:var(--ink-3)"></i>спектр AM0 (5778 К)</span>' +
            '<span><i style="background:var(--accent)"></i>верхний GaInP</span>' +
            '<span><i style="background:var(--accent-2)"></i>средний GaAs</span>' +
            '<span><i style="background:#8a63c8"></i>нижний Ge</span>',
    controls: [
      { id: "n", label: "число p–n переходов", min: 1, max: 3, step: 1, value: 3, fmt: function (v) { return v.toFixed(0); } },
      { id: "l1", label: "λ₁ — граница GaInP, нм", min: 550, max: 750, step: 5, value: 650, fmt: function (v) { return v.toFixed(0); } },
      { id: "l2", label: "λ₂ — граница GaAs (при 1 переходе — граница базового материала), нм", min: 800, max: 1150, step: 5, value: 920, fmt: function (v) { return v.toFixed(0); } },
      { id: "l3", label: "λ₃ — граница Ge, нм", min: 1400, max: 2200, step: 10, value: 1800, fmt: function (v) { return v.toFixed(0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
          ink2 = CV("--ink-2"), ink3 = CV("--ink-3"), fs = eoaFs(w);
      var L0 = 200, L1 = 4000, dl = 4, i, l, f, sum = 0, sp = [];
      for (l = L0; l <= L1; l += dl) {
        f = 1 / (Math.pow(l, 5) * (Math.exp(2490.1 / l) - 1));
        sp.push([l, f]); sum += f * dl;
      }
      var sc = EOA.Eref / sum;                       /* Вт/(м²·нм) */
      var bands;
      var nj = Math.max(1, Math.min(3, Math.round(s.n)));
      /* Ge ใช้สีม่วงเฉพาะ — เดิมใช้ --ok ซึ่งเป็นเขียวอมฟ้าชุดเดียวกับ --accent จนแยกแถบไม่ออก */
      var geCol = "#8a63c8";
      if (nj === 3) bands = [[300, s.l1, acc, "GaInP"], [s.l1, s.l2, acc2, "GaAs"], [s.l2, s.l3, geCol, "Ge"]];
      else if (nj === 2) bands = [[300, s.l1, acc, "GaInP"], [s.l1, s.l2, acc2, "GaAs"]];
      else bands = [[300, s.l2, acc2, "базовый материал"]];

      var Pb = [], Jb = [], k;
      for (k = 0; k < bands.length; k++) { Pb.push(0); Jb.push(0); }
      for (i = 0; i < sp.length; i++) {
        l = sp[i][0]; f = sp[i][1] * sc;
        for (k = 0; k < bands.length; k++) {
          if (l >= bands[k][0] && l < bands[k][1]) { Pb[k] += f * dl; Jb[k] += f * dl * l / 1239.84; }
        }
      }
      var Eg = [], Voc = [], Vsum = 0, Jlim = 1e9;
      for (k = 0; k < bands.length; k++) {
        Eg.push(1239.84 / bands[k][1]);
        Voc.push(Math.max(0.05, Eg[k] - 0.4));
        Vsum += Voc[k];
        if (Jb[k] < Jlim) Jlim = Jb[k];
      }
      var FF = 0.85, Pel = Jlim * Vsum * FF, eff = Pel / EOA.Eref * 100, effReal = eff * 0.65;

      var xmax = 2200, ymax = 2400;
      var p = new Plot(ctx, 52, 18, w - 68, h - 54, 300, xmax, 0, ymax);
      p.frame(ticks(300, xmax, 5), eoaTicksN(0, ymax, 4), "λ, нм","E_λ, Вт/(м²·мкм)");
      var full = [];
      for (i = 0; i < sp.length; i++) if (sp[i][0] >= 300 && sp[i][0] <= xmax) full.push([sp[i][0], sp[i][1] * sc * 1000, 0]);
      p.clip(function () {
        ctx.globalAlpha = 0.16; p.band(full, ink3); ctx.globalAlpha = 1;
        for (k = 0; k < bands.length; k++) {
          var seg = [];
          for (i = 0; i < sp.length; i++) {
            l = sp[i][0];
            if (l >= Math.max(300, bands[k][0]) && l <= Math.min(xmax, bands[k][1])) seg.push([l, sp[i][1] * sc * 1000, 0]);
          }
          if (seg.length > 1) { ctx.globalAlpha = 0.42; p.band(seg, bands[k][2]); ctx.globalAlpha = 1; }
        }
        p.line(full.map(function (r) { return [r[0], r[1]]; }), ink3, 1.8);
        ctx.save(); ctx.strokeStyle = ink2; ctx.globalAlpha = 0.6; ctx.setLineDash([3, 3]); ctx.lineWidth = 1;
        for (k = 0; k < bands.length; k++) {
          if (bands[k][1] <= xmax) {
            ctx.beginPath(); ctx.moveTo(p.X(bands[k][1]), p.y); ctx.lineTo(p.X(bands[k][1]), p.y + p.h); ctx.stroke();
          }
        }
        ctx.restore();
      });
      for (k = 0; k < bands.length; k++) {
        var mid = (Math.max(300, bands[k][0]) + Math.min(xmax, bands[k][1])) / 2;
        eoaTxt(ctx, bands[k][3], p.X(mid), p.y + 4 + k * (fs + 3), bands[k][2], fs, "center", "top", true);
      }

      var txt = '';
      for (k = 0; k < bands.length; k++) {
        txt += '<span>' + bands[k][3] + ' (' + bands[k][0].toFixed(0) + '–' + bands[k][1].toFixed(0) + ' нм): E<sub>g</sub> = <b>' +
          Eg[k].toFixed(2) + ' эВ</b> · доля потока <b>' + (Pb[k] / EOA.Eref * 100).toFixed(1) + ' %</b> · J = <b' +
          (Jb[k] <= Jlim + 1e-9 ? ' class="bad"' : '') + '>' + (Jb[k] / 10).toFixed(1) + ' мА/см²</b></span>';
      }
      readout.innerHTML =
        'число переходов: <b>' + nj + '</b>' + txt +
        '<span>ток последовательной сборки ограничен худшим слоем: J<sub>огр</sub> = <b>' + (Jlim / 10).toFixed(1) + ' мА/см²</b> · ΣU<sub>хх</sub> ≈ <b>' + Vsum.toFixed(2) + ' В</b></span>' +
        '<span>предельная оценка КПД = <b>' + eff.toFixed(1) + ' %</b> (P = J<sub>огр</sub>·ΣU·K<sub>зап</sub>, K<sub>зап</sub> = 0.85) · оценка реального КПД (0,65 от предела) = <b class="' + (effReal >= (nj > 1 ? 20 : 10) ? "good" : "bad") + '">' + effReal.toFixed(1) + ' %</b></span>' +
        '<span>สไลด์ 32 ระบุค่าจริง: однопереходные <b>10–15 %</b> · многопереходные <b>20–25 %</b> — เซลล์จริงทำได้ราว 55–75 % ของค่าขีดจำกัดนี้ (ผู้เรียบเรียง)</span>' +
        '<span>ผู้เรียบเรียง: สเปกตรัมใช้การแผ่รังสีวัตถุดำ 5778 К ปรับสเกลให้พลังงานรวม = 1373 Вт/м² ตาม сл. 20 · U<sub>хх</sub> ของแต่ละชั้นประมาณเป็น E<sub>g</sub> − 0,4 В · จุดสอนหลักคือ <b>การจับคู่กระแส</b>: เลื่อน λ₁ หรือ λ₂ แล้วชั้นที่กระแสน้อยที่สุดจะฉุดทั้งกองลง</span>' +
        '<span>หมายเหตุต้นฉบับ: λ₂ = 920 нм ให้ E<sub>g</sub> = 1,35 эВ ซึ่งเป็นค่าของ GaInAs ไม่ใช่ GaAs (1,42 эВ, λ = 873 нм) — ตรงกับที่ตาราง сл. 35 เขียน «GaInAs» ขณะที่ сл. 33 เขียน «GaAs»</span>';
    }
  });
}

/* ==== 7. eoTEG — термоэлектрический преобразователь · Л2 сл. 11–12 ===========
   E₁ = α₁(T_Г − T_Х) · E₂ = α₂(T_Г − T_Х) · E = (α₁ + α₂)(T_Г − T_Х)   (сл. 11)
   U = E − I·r_вн  — ВАХ เป็นเส้นตรง · P = U(E − U)/r · P_max = E²/(4r) ที่ U = E/2
   I при P_max = E/(R + r) = E/(2r) = 0,5·I_КЗ  เมื่อ R = r (согласованная нагрузка)
   โมดูล ТЭГ ต่อ N คู่ อนุกรมทางไฟฟ้า ขนานทางความร้อน (сл. 12): E→N·E, r→N·r     */
function eoTEG(host) {
  buildDemo(host, {
    label: "Лекция 2 · сл. 11–12",
    title: "ВАХ ของ ТЭП เป็นเส้นตรง — เลื่อนโหลดหาจุด R = r แล้วเทียบสัมประสิทธิ์การใช้ ВАХ กับ ФЭП",
    ratio: 0.58,
    legend: '<span><i style="background:var(--accent)"></i>U = E − I·r<sub>вн</sub></span>' +
            '<span><i style="background:var(--accent-2)"></i>P(I) (в масштабе)</span>' +
            '<span><i style="background:var(--ok)"></i>рабочая точка R<sub>н</sub></span>' +
            '<span><i style="background:var(--ink-3)"></i>P<sub>max</sub> при I = 0,5·I<sub>кз</sub></span>',
    controls: [
      { id: "a1", label: "α₁ — коэффициент термоэдс 1-й ветви, мкВ/К", min: 100, max: 300, step: 5, value: 200, fmt: function (v) { return v.toFixed(0); } },
      { id: "a2", label: "α₂ — коэффициент термоэдс 2-й ветви, мкВ/К", min: 100, max: 300, step: 5, value: 200, fmt: function (v) { return v.toFixed(0); } },
      { id: "Tg", label: "T<sub>Г</sub> — температура горячего спая, К", min: 300, max: 900, step: 5, value: 600, fmt: function (v) { return v.toFixed(0); } },
      { id: "Tx", label: "T<sub>Х</sub> — температура холодного спая, К", min: 250, max: 400, step: 5, value: 300, fmt: function (v) { return v.toFixed(0); } },
      { id: "r", label: "r<sub>вн</sub> — внутреннее сопротивление одной пары, Ом", min: 0.05, max: 2, step: 0.05, value: 0.5, fmt: function (v) { return v.toFixed(2); } },
      { id: "Rn", label: "R<sub>н</sub> — сопротивление нагрузки, Ом", min: 0.05, max: 10, step: 0.05, value: 0.5, fmt: function (v) { return v.toFixed(2); } },
      { id: "N", label: "N — число термоэлементов (пар) в модуле", min: 1, max: 100, step: 1, value: 1, fmt: function (v) { return v.toFixed(0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
          ink2 = CV("--ink-2"), ink3 = CV("--ink-3"), fs = eoaFs(w);
      var dT = s.Tg - s.Tx;
      if (dT < 0) dT = 0;
      var E1 = s.a1 * 1e-6 * dT, E2 = s.a2 * 1e-6 * dT;
      var E = (E1 + E2) * s.N, r = s.r * s.N;
      var Ikz = E / r, Pmax = E * E / (4 * r);
      var Iw = E / (s.Rn + r), Uw = E - Iw * r, Pw = Uw * Iw;
      var xmax = eoaNice(Ikz * 1.12), ymax = eoaNice(E * 1.12);
      var iv = [], pw = [], i, I;
      for (i = 0; i <= 200; i++) {
        I = xmax * i / 200;
        iv.push([I, E - I * r]);
        pw.push([I, (I * (E - I * r)) / Math.max(Pmax, 1e-12) * ymax * 0.92]);
      }
      var p = new Plot(ctx, 52, 18, w - 68, h - 54, 0, xmax, 0, ymax);
      p.frame(ticks(0, xmax, 5), eoaTicksN(0, ymax, 4), "I, А","U, В");
      eoaHLine(ctx, p, ymax * 0.92, ink3, [4, 4]);
      p.clip(function () {
        p.line(pw, acc2, 1.8, [5, 4]);
        p.line(iv, acc, 2.4);
        eoaMark(ctx, p, Ikz / 2, E / 2, ink3, 3.5);
        eoaMark(ctx, p, Iw, Uw, ok, 4.5);
      });
      eoaTxt(ctx, "E = " + E.toFixed(3) + " В", p.x + 4, p.Y(E) - 4, acc, fs, "left", "bottom");
      eoaTxt(ctx, "I_кз = " + Ikz.toFixed(3) + " А", p.X(Ikz) - 4, p.y + p.h - 4, acc, fs, "right", "bottom");
      eoaTxt(ctx, "P_max = " + (Pmax * 1000).toFixed(1) + " мВт", p.x + p.w - 4, p.y + 2, acc2, fs, "right", "top");
      eoaTxt(ctx, "U_м = E/2", p.X(Ikz / 2) + 5, p.Y(E / 2) - 5, ink3, fs, "left", "bottom");

      var soglas = Math.abs(s.Rn - r) / r;
      readout.innerHTML =
        'E = (α₁ + α₂)·(T<sub>Г</sub> − T<sub>Х</sub>)·N = <b>' + E.toFixed(4) + ' В</b> · ΔT = <b>' + dT.toFixed(0) + ' К</b>' +
        '<span>I<sub>кз</sub> = E/r = <b>' + Ikz.toFixed(3) + ' А</b></span>' +
        '<span>P<sub>max</sub> = E²/(4r) = <b>' + (Pmax * 1000).toFixed(2) + ' мВт</b> при U<sub>м</sub> = E/2 = <b>' + (E / 2).toFixed(4) + ' В</b> и I = 0,5·I<sub>кз</sub></span>' +
        '<span>рабочая точка: U = <b>' + Uw.toFixed(4) + ' В</b> · I = <b>' + Iw.toFixed(3) + ' А</b> · P = <b>' + (Pw * 1000).toFixed(2) + ' мВт</b> = <b class="' + (soglas < 0.1 ? "good" : "bad") + '">' + (Pmax > 0 ? (Pw / Pmax * 100).toFixed(1) : "0.0") + ' %</b> จาก P<sub>max</sub></span>' +
        '<span>согласование нагрузки: R<sub>н</sub> = <b>' + s.Rn.toFixed(2) + ' Ом</b> · r<sub>вн</sub> модуля = <b>' + r.toFixed(2) + ' Ом</b> → <b class="' + (soglas < 0.1 ? "good" : "bad") + '">' + (soglas < 0.1 ? "R ≈ r, согласовано" : "R ≠ r, не согласовано") + '</b></span>' +
        '<span>коэффициент использования ВАХ = P<sub>max</sub>/(E·I<sub>кз</sub>) = <b>0.250</b> เสมอ เพราะ ВАХ เป็นเส้นตรง ยอดพาราโบลาจึงอยู่กลางพอดี — เทียบ ФЭП ที่ได้ ≈ 0,81 ตามสไลด์ Л1 сл. 24 (ต่างกันราวสามเท่า)</span>' +
        '<span>P ~ (ΔT)² เพราะ E ~ ΔT — ยืนยันด้วยกราฟจริงของ Л2 сл. 15 (98 пар: ~430 мкВт ที่ ΔT = 9 К · 12 пар: ~580 мкВт ที่ 14 К · 5 пар: ~270 мкВт ที่ 14 К)</span>';
    }
  });
}

/* ==== 8. eoFuelCell — ВАХ ของ ТЭ และอัตราสิ้นเปลือง · Л2 сл. 26 ==============
   E_т = 1,229 В (ЭДС при нормальных условиях) · удельная энергия 4,4 кВт·ч/кг
   ВАХ: U(j) = E_т − a·ln(j/j₀) − b·j + c·ln(1 − j/j_к)  (แบบจำลองสามโซน A/Б/В ของสไลด์)
   C_уд = 0,227·η_е  ← ตามที่พิมพ์บนสไลด์ (ผิด) · C_уд = 0,227/η_е ← ที่ถูก (0,227 = 1/4,4) */
function eoFuelCell(host) {
  buildDemo(host, {
    label: "Лекция 2 · сл. 26",
    title: "ВАХ ของเซลล์เชื้อเพลิงสามโซน A/Б/В และเครื่องคิดมวลเชื้อเพลิง — สลับสูตรสไลด์กับสูตรที่ถูก",
    ratio: 0.62,
    legend: '<span><i style="background:var(--accent)"></i>U(j)</span>' +
            '<span><i style="background:var(--accent-2)"></i>P(j) = U·j</span>' +
            '<span><i style="background:var(--ok)"></i>рабочая точка j</span>' +
            '<span><i style="background:var(--ink-3)"></i>E<sub>т</sub> = 1,229 В</span>',
    buttons: [
      { id: "fix", label: "формула C_уд: правильная / как на слайде", toggle: true, value: true }
    ],
    controls: [
      { id: "j", label: "j — рабочая плотность тока, А/см²", min: 0.02, max: 1.6, step: 0.01, value: 0.6, fmt: function (v) { return v.toFixed(2); } },
      { id: "b", label: "b — наклон омических потерь, В·см²/А", min: 0.1, max: 0.6, step: 0.01, value: 0.35, fmt: function (v) { return v.toFixed(2); } },
      { id: "jk", label: "j<sub>к</sub> — предельная плотность тока, А/см²", min: 0.8, max: 2, step: 0.05, value: 1.4, fmt: function (v) { return v.toFixed(2); } },
      { id: "eta", label: "η<sub>е</sub> — эффективный КПД", min: 0.57, max: 0.66, step: 0.005, value: 0.6, fmt: function (v) { return v.toFixed(3); } },
      { id: "P", label: "потребная мощность ЭХГ, кВт", min: 0.1, max: 10, step: 0.1, value: 1, fmt: function (v) { return v.toFixed(1); } },
      { id: "t", label: "длительность полёта, сут", min: 1, max: 30, step: 1, value: 14, fmt: function (v) { return v.toFixed(0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
          crit = CV("--crit"), ink2 = CV("--ink-2"), ink3 = CV("--ink-3"), fs = eoaFs(w);
      var Et = 1.229, a = 0.05, j0 = 1e-3, cc = 0.05, jk = s.jk;
      function U(j) {
        if (j < 1e-5) j = 1e-5;
        var x = 1 - j / jk;
        if (x < 1e-4) x = 1e-4;
        return Et - a * Math.log(j / j0) - s.b * j + cc * Math.log(x);
      }
      var lo = 1e-3, hi = jk * 0.995, i, p1, p2;
      for (i = 0; i < 70; i++) {
        p1 = lo + (hi - lo) / 3; p2 = hi - (hi - lo) / 3;
        if (p1 * U(p1) < p2 * U(p2)) lo = p1; else hi = p2;
      }
      var jm = (lo + hi) / 2, Pm = jm * U(jm);
      var jw = Math.min(s.j, jk * 0.995), Uw = U(jw), Pw = jw * Uw;
      var ymax = 1.4, xmax = eoaNice(jk * 1.1);
      var uv = [], pv = [], j;
      for (i = 1; i <= 300; i++) {
        j = xmax * i / 300;
        if (j > jk * 0.998) break;
        uv.push([j, U(j)]);
        pv.push([j, j * U(j) / Math.max(Pm, 1e-9) * ymax * 0.9]);
      }
      var p = new Plot(ctx, 52, 18, w - 68, h - 54, 0, xmax, 0, ymax);
      p.frame(ticks(0, xmax, 5), eoaTicksN(0, ymax, 4), "j, А/см²","U, В");
      var jA = 0.15 * jk;
      ctx.save();
      ctx.globalAlpha = 0.10;
      ctx.fillStyle = acc; ctx.fillRect(p.X(0), p.y, p.X(jA) - p.X(0), p.h);
      ctx.fillStyle = ok; ctx.fillRect(p.X(jA), p.y, p.X(jm) - p.X(jA), p.h);
      ctx.fillStyle = crit; ctx.fillRect(p.X(jm), p.y, p.X(Math.min(jk, xmax)) - p.X(jm), p.h);
      ctx.restore();
      eoaTxt(ctx, "A", (p.X(0) + p.X(jA)) / 2, p.y + 3, ink2, fs + 2, "center", "top", true);
      eoaTxt(ctx, "Б", (p.X(jA) + p.X(jm)) / 2, p.y + 3, ink2, fs + 2, "center", "top", true);
      eoaTxt(ctx, "В", (p.X(jm) + p.X(Math.min(jk, xmax))) / 2, p.y + 3, ink2, fs + 2, "center", "top", true);
      eoaHLine(ctx, p, Et, ink3, [5, 4]);
      eoaTxt(ctx, "E_т = 1.229 В", p.x + p.w - 4, Math.max(p.Y(Et) - 3, p.y + fs * 2.8), ink3, fs, "right", "bottom");
      p.clip(function () {
        p.line(pv, acc2, 1.8, [5, 4]);
        p.line(uv, acc, 2.4);
        eoaMark(ctx, p, jw, Uw, ok, 4.5);
      });
      /* ตรึงป้ายให้อยู่ในกรอบและแยกคนละบรรทัดเมื่อจุดสองจุดชิดกัน */
      var cl = function (xv, half) { return Math.max(p.x + half + 2, Math.min(p.X(xv), p.x + p.w - half - 2)); };
      var near = Math.abs(p.X(jm) - p.X(jk)) < 70;
      /* วางในกรอบเหนือแกน x — เดิมทับป้าย tick ที่เอนจินวาดใต้กรอบ */
      eoaTxt(ctx, "j_м = " + jm.toFixed(2), cl(jm, 34), p.y + p.h - 4, acc2, fs, "center", "bottom");
      eoaTxt(ctx, "j_к = " + jk.toFixed(2), cl(jk, 34), p.y + p.h - 4 - (near ? fs + 3 : 0), crit, fs, "center", "bottom");

      var Cud = s.fix ? 0.227 / s.eta : 0.227 * s.eta;
      var m = Cud * s.P * s.t * 24, mIdeal = 0.227 * s.P * s.t * 24;
      var kpd = Uw / Et * 100;
      readout.innerHTML =
        'U(j) = <b>' + Uw.toFixed(3) + ' В</b> · P<sub>уд</sub> = <b>' + Pw.toFixed(3) + ' Вт/см²</b>' +
        '<span>КПД по напряжению = U/E<sub>т</sub> = <b class="' + (kpd >= 50 ? "good" : "bad") + '">' + kpd.toFixed(1) + ' %</b></span>' +
        '<span>максимум мощности при j<sub>м</sub> = <b>' + jm.toFixed(3) + ' А/см²</b> (P<sub>уд</sub> = ' + Pm.toFixed(3) + ' Вт/см²) · j<sub>к</sub> = <b>' + jk.toFixed(2) + ' А/см²</b></span>' +
        '<span>режим формулы: <b class="' + (s.fix ? "good" : "bad") + '">' + (s.fix ? "C_уд = 0,227/η_е — правильно" : "C_уд = 0,227·η_е — как на слайде") + '</b></span>' +
        '<span>C<sub>уд</sub> = <b>' + Cud.toFixed(3) + ' кг/(кВт·ч)</b> · масса компонентов H₂ + O₂ за полёт = <b>' + m.toFixed(1) + ' кг</b> · масса образующейся воды ≈ столько же</span>' +
        (s.fix
          ? '<span>ที่ η<sub>е</sub> = 0,57…0,66 ได้ C<sub>уд</sub> = 0,398…0,344 кг/(кВт·ч) คือใช้ H₂ + O₂ ราว 0,34–0,40 กก. ต่อ 1 кВт·ч</span>'
          : '<span class="bad">สูตรตามสไลด์ให้ C<sub>уд</sub> = ' + Cud.toFixed(3) + ' кг/(кВт·ч) ซึ่งน้อยกว่าค่าอุดมคติ 0,227 (= 1/4,4 จาก удельная энергия 4,4 кВт·ч/кг บนสไลด์แผ่นเดียวกัน) — แปลว่าระบบจริงกินเชื้อเพลิงน้อยกว่าอุดมคติ เป็นไปไม่ได้ทางเทอร์โมไดนามิกส์ · มวลที่ได้ ' + m.toFixed(1) + ' กก. เทียบกับค่าอุดมคติ ' + mIdeal.toFixed(1) + ' กก. คือน้อยเกินจริง</span>') +
        '<span>เทียบกับแบตเตอรี่ Li—ion (Л2 сл. 21, 120 Вт·ч/кг): พลังงานภารกิจ ' + (s.P * s.t * 24).toFixed(0) + ' кВт·ч ต้องใช้แบตเตอรี่ <b>' + (s.P * s.t * 24 * 1000 / 120).toFixed(0) + ' кг</b> — ภารกิจยิ่งยาว ЭХГ ยิ่งได้เปรียบ</span>' +
        '<span>ชื่อของสามโซน (активационные / омические / концентрационные потери) ไม่ได้พิมพ์บนสไลด์ — สไลด์ให้แค่ตัวอักษร A, Б, В ต้องถามอาจารย์ · ค่า a, b, c ของแบบจำลอง ВАХ เป็นค่าที่ผู้เรียบเรียงเลือกให้รูปเส้นตรงกับกราฟบนสไลด์</span>';
    }
  });
}

/* ==== 9. eoBattery — ประจุ/คายประจุ/คายเอง และ разрядные характеристики =====
   โหมด 1 — Л2 сл. 21: กราฟ I(t), N(t), T(t) พร้อมเขต перезаряд และ саморазряд
     ตาราง сл. 21 ให้ саморазряд 5/20/30/10/10 % ต่อเดือน, плотность энергии 40/60/90/120/120 Вт·ч/кг,
     циклы 250/1500/400/400/400, цена за цикл 0,10/0,04/0,10/0,14/0,29 USD
   โหมด 2 — Л13 сл. 23 (рис. 8.4): разрядные характеристики ที่ I_н, 2I_н, 10I_н
     แบตเงิน-สังกะสี двухступенчатая кривая: ที่ราบบน ≈1,85 В ที่ราบล่าง ≈1,5 В    */
function eoBattery(host) {
  var BT = ["Кислотный (Pb)", "Никель-кадмиевый Ni—Cd", "Никель-металлогидридный Ni—MH", "Литий-ионный Li—ion", "Литий-полимерный Li—Pol"];
  var WH = [40, 60, 90, 120, 120], CYC = [250, 1500, 400, 400, 400], SD = [5, 20, 30, 10, 10], PRC = [0.10, 0.04, 0.10, 0.14, 0.29];
  buildDemo(host, {
    label: "Лекция 2 · сл. 21 · Лекция 13 · сл. 23",
    title: "ประจุ → เกินประจุ → คายเอง → คายประจุ และเส้นคายประจุที่กระแสต่าง ๆ (กดปุ่มสลับสองภาพ)",
    ratio: 0.66,
    legend: '<span><i style="background:var(--accent)"></i>N — заряженные активные массы / U</span>' +
            '<span><i style="background:var(--accent-2)"></i>I</span>' +
            '<span><i style="background:var(--crit)"></i>T (перезаряд)</span>' +
            '<span><i style="background:var(--ok)"></i>рабочий ток</span>',
    buttons: [
      { id: "rz", label: "разрядные характеристики (Л13 сл. 23)", toggle: true, value: false }
    ],
    controls: [
      { id: "b", label: "тип аккумулятора (табл. сл. 21)", min: 0, max: 4, step: 1, value: 1, fmt: function (v) { return BT[v]; } },
      { id: "Iz", label: "I<sub>з</sub> — зарядный ток, доля C", min: 0.05, max: 0.5, step: 0.01, value: 0.2, fmt: function (v) { return v.toFixed(2); } },
      { id: "tp", label: "длительность перезаряда, ч", min: 0, max: 8, step: 0.25, value: 1.5, fmt: function (v) { return v.toFixed(2); } },
      { id: "mo", label: "хранение (саморазряд), мес", min: 0, max: 12, step: 0.5, value: 3, fmt: function (v) { return v.toFixed(1); } },
      { id: "Ir", label: "I<sub>р</sub> — разрядный ток, в долях I<sub>н</sub>", min: 0.5, max: 10, step: 0.1, value: 1, fmt: function (v) { return v.toFixed(1); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
          crit = CV("--crit"), ink2 = CV("--ink-2"), ink3 = CV("--ink-3"),
          line2 = CV("--line-2"), fs = eoaFs(w);
      var bi = Math.max(0, Math.min(4, Math.round(s.b)));
      var self = SD[bi] / 100;

      if (s.rz) {
        /* ---------- โหมด 2: разрядные характеристики (Л13 сл. 23, рис. 8.4) ---------- */
        var p = new Plot(ctx, 52, 18, w - 68, h - 54, 0, 1, 1.2, 2.0);
        p.frame(ticks(0, 1, 4), eoaTicksN(1.2, 2.0, 4), "Q/Q_н","U, В");
        function xend(k) { return Math.min(0.98, 0.85 * Math.pow(k, -0.55)); }
        function curveK(k) {
          var out = [], i, x, xe = xend(k), u;
          for (i = 0; i <= 200; i++) {
            x = xe * i / 200;
            u = 1.5 + 0.35 / (1 + Math.exp((x - 0.40) / 0.045)) - 0.02 * k - 0.55 * Math.pow(x / xe, 8);
            out.push([x, u]);
          }
          return out;
        }
        p.clip(function () {
          [[1, "I_т = I_н"], [2, "2I_н"], [10, "10I_н"]].forEach(function (q) {
            p.line(curveK(q[0]), ink3, 1.6, [4, 3]);
          });
          p.line(curveK(s.Ir), ok, 2.6);
        });
        [[1, "I_т = I_н"], [2, "2I_н"], [10, "10I_н"]].forEach(function (q) {
          var xe = xend(q[0]);
          eoaTxt(ctx, q[1], p.X(xe) - 3, p.Y(1.55) , ink3, fs, "right", "bottom");
        });
        var xe2 = xend(s.Ir);
        eoaTxt(ctx, "I_р = " + s.Ir.toFixed(1) + " I_н", p.X(xe2 / 2), p.Y(1.9) - 4, ok, fs + 1, "center", "bottom", true);
        eoaTxt(ctx, "двухступенчатая кривая СЦ: ≈1.85 В и ≈1.5 В", p.x + p.w - 4, p.y + 2, ink2, fs, "right", "top");
        readout.innerHTML =
          'разрядная характеристика по Л13 сл. 23 (аккумулятор серебряно-цинковый)' +
          '<span>I<sub>р</sub> = <b>' + s.Ir.toFixed(1) + ' I<sub>н</sub></b> → доступная ёмкость = <b class="' + (xe2 < 0.5 ? "bad" : "good") + '">' + (xe2 * 100).toFixed(0) + ' % Q<sub>н</sub></b></span>' +
          '<span>при I<sub>н</sub> — <b>' + (xend(1) * 100).toFixed(0) + ' %</b> · при 2I<sub>н</sub> — <b>' + (xend(2) * 100).toFixed(0) + ' %</b> · при 10I<sub>н</sub> — <b>' + (xend(10) * 100).toFixed(0) + ' %</b> (สไลด์แสดงเข่าของเส้น 10I<sub>н</sub> ที่ราว 0,25 Q/Q<sub>н</sub>)</span>' +
          '<span>สองที่ราบ (≈1,85 В และ ≈1,5 В) เป็นลักษณะเฉพาะของแบตเงิน-สังกะสี — สาเหตุที่ СЭП รุ่นแรก (รูป 8.5) ปล่อยให้ U<sub>НАГ</sub> ลอยไปตามเส้นนี้ จึงต้องมีตัวรักษาระดับแรงดันในรุ่นต่อมา</span>' +
          '<span>ผู้เรียบเรียง: รูปเส้นสร้างจากกฎ Пейкерта Q(I)/Q<sub>н</sub> = 0,85·(I/I<sub>н</sub>)<sup>−0,55</sup> ปรับให้เข่าของเส้น 10I<sub>н</sub> ตรงกับกราฟ рис. 8.4 · สไลด์ให้แต่รูปกราฟ ไม่ให้สมการ</span>';
        return;
      }

      /* ---------- โหมด 1: กระบวนการตามเวลา (Л2 сл. 21) ---------- */
      var N0 = 0.15, dt = 0.02;
      var t1 = (1 - N0) / (0.9 * s.Iz);           /* ч — заряд до N = 1     */
      var Tamb = 20, Cth = 0.12, Rth = 30, Rint = 2.0;
      var segs = [], T = Tamb, N = N0, i, q, n;
      /* сегмент 1 — заряд */
      var s1 = [];
      for (i = 0; i * dt <= t1; i++) {
        q = s.Iz * s.Iz * Rint;
        T += (q - (T - Tamb) / Rth) / Cth * dt;
        N = Math.min(1, N0 + 0.9 * s.Iz * i * dt);
        s1.push([i * dt / Math.max(t1, 1e-6), N, T, s.Iz]);
      }
      /* сегмент 2 — перезаряд: вся мощность идёт в тепло */
      var s2 = [];
      for (i = 0; i * dt <= s.tp; i++) {
        q = s.Iz * 1.45;
        T += (q - (T - Tamb) / Rth) / Cth * dt;
        s2.push([s.tp > 0 ? i * dt / s.tp : 0, 1, T, s.Iz]);
      }
      var Tmax = T;
      /* сегмент 3 — саморазряд (хранение) */
      var s3 = [], Nst = 1;
      for (i = 0; i <= 100; i++) {
        var mo = s.mo * i / 100;
        Nst = Math.pow(1 - self, mo);
        T += (0 - (T - Tamb) / Rth) / Cth * (s.mo > 0 ? 0.06 : 0);
        s3.push([i / 100, Nst, T, 0]);
      }
      /* сегмент 4 — разряд */
      var s4 = [], Nd = Nst, td = Nst / Math.max(s.Ir * 0.2, 1e-6);
      for (i = 0; i * dt <= td; i++) {
        q = (s.Ir * 0.2) * (s.Ir * 0.2) * Rint;
        T += (q - (T - Tamb) / Rth) / Cth * dt;
        Nd = Math.max(0, Nst - s.Ir * 0.2 * i * dt);
        s4.push([i * dt / Math.max(td, 1e-6), Nd, T, -s.Ir * 0.2]);
        if (T > Tmax) Tmax = T;
      }
      /* แกนเวลาแบบเฟส: 4 ช่วง ความกว้างคงที่ (สไลด์เองก็เป็นภาพเชิงคุณภาพ) */
      var frac = [0.32, 0.16, 0.20, 0.32], off = [0, 0.32, 0.48, 0.68];
      var all = [s1, s2, s3, s4], Ipts = [], Npts = [], Tpts = [];
      for (n = 0; n < 4; n++) {
        for (i = 0; i < all[n].length; i++) {
          var x = off[n] + all[n][i][0] * frac[n];
          Ipts.push([x, all[n][i][3]]); Npts.push([x, all[n][i][1]]); Tpts.push([x, all[n][i][2]]);
        }
      }
      var gap = 22, hh = (h - 18 - 32 - 2 * gap) / 3;
      var pI = new Plot(ctx, 52, 18, w - 68, hh, 0, 1, -0.6, 0.6);
      var pN = new Plot(ctx, 52, 18 + hh + gap, w - 68, hh, 0, 1, 0, 1.1);
      var Tlo = Math.floor(Tamb - 2), Thi = Math.ceil(Math.max(Tmax + 3, Tamb + 12));
      var pT = new Plot(ctx, 52, 18 + 2 * (hh + gap), w - 68, hh, 0, 1, Tlo, Thi);
      pI.frame(ticks(0, 1, 4), eoaTicksN(-0.6, 0.6, 2), "", "I",true);
      pN.frame(ticks(0, 1, 4), eoaTicksN(0, 1, 2), "", "N",true);
      pT.frame(ticks(0, 1, 4), eoaTicksN(Tlo, Thi, 2), "условное время (фазы не в масштабе)","T, °C");
      ctx.save(); ctx.strokeStyle = line2; ctx.globalAlpha = 0.8; ctx.setLineDash([3, 3]); ctx.lineWidth = 1;
      [0.32, 0.48, 0.68].forEach(function (x) {
        [pI, pN, pT].forEach(function (pp) {
          ctx.beginPath(); ctx.moveTo(pp.X(x), pp.y); ctx.lineTo(pp.X(x), pp.y + pp.h); ctx.stroke();
        });
      });
      ctx.restore();
      pI.clip(function () { pI.line(Ipts, acc2, 2.2); });
      pN.clip(function () { pN.line(Npts, acc, 2.4); });
      pT.clip(function () { pT.line(Tpts, crit, 2.2); });
      eoaTxt(ctx, "заряд", pI.X(0.16), pI.y + 1, ink3, fs, "center", "top");
      eoaTxt(ctx, "перезаряд", pI.X(0.40), pI.y + 1, crit, fs, "center", "top");
      eoaTxt(ctx, "саморазряд", pI.X(0.58), pI.y + 1, ink3, fs, "center", "top");
      eoaTxt(ctx, "разряд", pI.X(0.84), pI.y + 1, ink3, fs, "center", "top");
      eoaTxt(ctx, w < 520 ? "обл. откл. заряда" : "область отключения с заряда",
             pN.X(0.32) - 4, pN.y + 2, ink2, fs, "right", "top");
      eoaTxt(ctx, "аналогично растёт давление (кроме НВ)", pT.x + pT.w - 4, pT.y + 2, ink2, fs, "right", "top");

      var lost = (1 - Nst) * 100;
      readout.innerHTML =
        'тип: <b>' + BT[bi] + '</b> · плотность энергии <b>' + WH[bi] + ' Вт·ч/кг</b> · циклов <b>' + CYC[bi] + '</b> · цена за цикл <b>' + PRC[bi].toFixed(2) + ' USD</b>' +
        '<span>саморазряд <b>' + SD[bi] + ' %/мес</b> → за ' + s.mo.toFixed(1) + ' мес хранения потеряно <b class="' + (lost > 30 ? "bad" : "good") + '">' + lost.toFixed(1) + ' %</b> заряда</span>' +
        '<span>время заряда до N = 1: <b>' + t1.toFixed(1) + ' ч</b> при I<sub>з</sub> = ' + s.Iz.toFixed(2) + ' C</span>' +
        '<span>максимальная температура: <b class="' + (Tmax > 45 ? "bad" : "good") + '">' + Tmax.toFixed(1) + ' °C</b>' + (Tmax > 45 ? ' — перегрев, требуется отключение с заряда' : '') + '</span>' +
        '<span>ในช่วง перезаряд พลังงานที่ป้อนเข้าไม่ถูกเก็บอีกต่อไป แต่กลายเป็นความร้อนทั้งหมด อุณหภูมิและความดันจึงพุ่ง (สไลด์กำกับ «аналогично растёт давление, кроме НВ») — นี่คือเหตุผลที่ต้องมี ЗУ และ «область отключения с заряда» ซึ่งจะกลับมาใน Тема 6</span>' +
        '<span>ผู้เรียบเรียง: สไลด์ 21 ให้กราฟเชิงคุณภาพ ไม่ให้สมการ — เส้น N(t) และ T(t) ที่นี่คำนวณจากแบบจำลองความร้อนอย่างง่าย (dT/dt = (q − (T − T<sub>окр</sub>)/R<sub>т</sub>)/C<sub>т</sub>) โดย q = I²·r ระหว่างประจุ/คายประจุ และ q = I·U ทั้งหมดระหว่าง перезаряд · ค่า саморазряд มาจากตารางสไลด์ 21 จริง</span>';
    }
  });
}

window.EODEMOS = Object.assign(window.EODEMOS || {}, {
  eoSolarIV: eoSolarIV,
  eoSolarPoint: eoSolarPoint,
  eoSolarArray: eoSolarArray,
  eoSolarAngle: eoSolarAngle,
  eoSolarDeg: eoSolarDeg,
  eoSolarSpectrum: eoSolarSpectrum,
  eoTEG: eoTEG,
  eoFuelCell: eoFuelCell,
  eoBattery: eoBattery
});

/* ================= ЭОЛА — กลุ่ม B · Тема 2 วงจรเรียงกระแส =================
   แหล่งสูตรทั้งหมด: notes/L03.md (Л3 сл. 14–21) · notes/L04.md (Л4 сл. 13–23) ·
   notes/L05.md (Л5 сл. 10–22)
   ทุกเดโมคำนวณจากสมการของภาควิชาโดยตรง จุดที่ทีมเรียบเรียง derive เองมีหมายเหตุกำกับ */

/* ---------- ตัวช่วยภายในกลุ่ม B (ชื่อขึ้นต้น eob เพื่อไม่ชนกับกลุ่มอื่น) ---------- */


/* ---- ป้ายค่าบนแกนแบบเลขกลม (แทนการส่ง min/max ดิบเข้า ticks) ---- */
function eobNiceStep(span, n) {
  var raw = Math.abs(span) / Math.max(1, n);
  if (!(raw > 0) || !isFinite(raw)) return 1;
  var e = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), f = raw / e;
  return (f < 1.5 ? 1 : f < 3.5 ? 2 : f < 7.5 ? 5 : 10) * e;
}
function eobTicksN(a, b, n) {
  if (!isFinite(a) || !isFinite(b) || b <= a) return [a, b];
  /* เอนจินพิมพ์ป้ายด้วย toFixed(2) — ก้าวต่ำกว่า 0,01 จะได้ป้ายซ้ำ จึงยกพื้นไว้ */
  var st = Math.max(eobNiceStep(b - a, n), 0.01), out = [], seen = {}, lab,
    k = Math.ceil((a - st * 1e-6) / st), guard = 0, v;
  for (; k * st <= b + st * 1e-6 && guard < 400; k++, guard++) {
    v = +(k * st).toPrecision(12);
    lab = String(+v.toFixed(2));
    if (seen[lab]) continue;
    seen[lab] = 1; out.push(v);
  }
  return out.length >= 2 ? out : [a, b];
}

function eobF(v, d) {
  if (v === null || v === undefined || !isFinite(v)) return "—";
  var n = (d === undefined) ? 2 : d;
  return v.toFixed(n).replace(".", ",");
}

/* ค่าแรงดันสามเฟส (แอมพลิจูด 1) ที่มุม th [рад] */
function eobPh(th) {
  var k = 2 * Math.PI / 3;
  return [Math.sin(th), Math.sin(th - k), Math.sin(th + k)];
}

function eobMax3(v) { return Math.max(v[0], Math.max(v[1], v[2])); }
function eobMin3(v) { return Math.min(v[0], Math.min(v[1], v[2])); }

/* สถิติของรูปคลื่นหนึ่งคาบ: ค่าเฉลี่ย U₀ · ค่าสูงสุด/ต่ำสุด · размах ΔU */
function eobStat(a) {
  var s = 0, mn = Infinity, mx = -Infinity, i;
  for (i = 0; i < a.length; i++) {
    s += a[i];
    if (a[i] < mn) mn = a[i];
    if (a[i] > mx) mx = a[i];
  }
  return { m: s / a.length, min: mn, max: mx, dU: mx - mn };
}

/* K_п ตามนิยาม A ของภาควิชา (Л3 сл. 14): K_п = ΔU/(2·U₀) */
function eobKpA(st) { return st.m > 1e-9 ? st.dU / (2 * st.m) : Infinity; }

/* เรขาคณิตของแผงกราฟซ้อนกัน n แผง */
function eobPlots(w, h, n, o) {
  o = o || {};
  var L = o.left || (w < 430 ? 38 : 46);
  var R = o.right === undefined ? 10 : o.right;
  var top = Math.max(o.top === undefined ? 18 : o.top, 18);
  var gap = Math.max(o.gap === undefined ? 34 : o.gap, 34);
  var bot = Math.max(o.bottom === undefined ? 32 : o.bottom, 32);
  var ph = (h - top - bot - gap * (n - 1)) / n;
  var out = [], i;
  for (i = 0; i < n; i++) out.push({ x: L, y: top + i * (ph + gap), w: w - L - R, h: ph });
  return out;
}

function eobFS(w) { return w < 430 ? 9 : 10; }
function eobFont(fs) { return fs + 'px "IBM Plex Mono", monospace'; }

/* ป้ายชื่อแผงกราฟ (มุมในกรอบ) */
/* ตัดข้อความให้พอดีความกว้าง */
function eobClip(ctx, txt, maxw) {
  if (ctx.measureText(txt).width <= maxw) return txt;
  var s = txt;
  while (s.length > 1 && ctx.measureText(s + "…").width > maxw) s = s.slice(0, -1);
  return s + "…";
}

/* ย่อฟอนต์ให้พอดีความกว้าง แล้วค่อยตัดคำถ้ายังไม่พอ */
function eobFit(ctx, txt, maxw, fs, min) {
  var lo = min === undefined ? 7.2 : min, f = fs;
  ctx.font = eobFont(f);
  while (f > lo && ctx.measureText(txt).width > maxw) {
    f = Math.max(lo, f - 0.5);
    ctx.font = eobFont(f);
  }
  return { fs: f, txt: eobClip(ctx, txt, maxw) };
}

function eobTagH(fs) { return fs * 1.55 + 5; }

/* จองพื้นที่ป้ายบนแผง — ป้ายที่วางทีหลังจะเลี่ยงป้ายที่วางไปแล้ว */
function eobFree(p, x0, y0, x1, y1) {
  var L = p._lbl;
  if (!L) return true;
  for (var i = 0; i < L.length; i++) {
    var r = L[i];
    if (x1 > r[0] + 1.5 && x0 < r[2] - 1.5 && y1 > r[1] + 1.5 && y0 < r[3] - 1.5) return false;
  }
  return true;
}
function eobTake(p, x0, y0, x1, y1) {
  if (!p._lbl) p._lbl = [];
  p._lbl.push([x0, y0, x1, y1]);
}

function eobTag(ctx, p, txt, col, fs, right) {
  ctx.save();
  ctx.textAlign = right ? "right" : "left";
  ctx.textBaseline = "top";
  var t = eobFit(ctx, txt, p.w - 8, fs);
  var tw = ctx.measureText(t.txt).width;
  var x0 = right ? p.x + p.w - 4 - tw : p.x + 4;
  var y = p.y + 3, guard = 0;
  while (!eobFree(p, x0, y, x0 + tw, y + t.fs * 1.15) && guard++ < 5 &&
         y + t.fs * 2.4 < p.y + p.h) y += eobTagH(t.fs);
  ctx.fillStyle = col;
  ctx.fillText(t.txt, right ? p.x + p.w - 4 : p.x + 4, y);
  eobTake(p, x0, y, x0 + tw, y + t.fs * 1.15);
  ctx.restore();
}

/* เส้นอ้างอิงแนวนอนพร้อมป้าย */
function eobRef(ctx, p, val, col, txt, fs, dash) {
  if (!isFinite(val)) return;
  var y = Math.round(p.Y(val)) + 0.5;
  if (y < p.y - 1 || y > p.y + p.h + 1) return;
  ctx.save();
  ctx.strokeStyle = col;
  ctx.lineWidth = 1.2;
  ctx.setLineDash(dash || [5, 4]);
  ctx.beginPath();
  ctx.moveTo(p.x, y);
  ctx.lineTo(p.x + p.w, y);
  ctx.stroke();
  ctx.setLineDash([]);
  if (txt) {
    ctx.textAlign = "right";
    ctx.textBaseline = "top";
    var t = eobFit(ctx, txt, p.w - 8, fs);
    var tw = ctx.measureText(t.txt).width, hh = t.fs * 1.15;
    var x0 = p.x + p.w - 3 - tw;
    var yTop = y - 2 - hh;
    if (yTop < p.y + eobTagH(t.fs) || !eobFree(p, x0, yTop, x0 + tw, yTop + hh)) yTop = y + 2;
    var guard = 0;
    while (!eobFree(p, x0, yTop, x0 + tw, yTop + hh) && guard++ < 4 && yTop + hh * 2 < p.y + p.h) yTop += hh + 2;
    /* ห้ามล้นลงไปทับป้ายแกน x ที่วาดใต้กรอบ */
    if (yTop + hh > p.y + p.h - 2) {
      yTop = y - 2 - hh;
      var g3 = 0;
      while (!eobFree(p, x0, yTop, x0 + tw, yTop + hh) && g3++ < 4 && yTop - hh > p.y) yTop -= hh + 2;
      yTop = Math.max(p.y + 2, yTop);
    }
    ctx.fillStyle = col;
    ctx.fillText(t.txt, p.x + p.w - 3, yTop);
    eobTake(p, x0, yTop, x0 + tw, yTop + hh);
  }
  ctx.restore();
}

/* เส้นอ้างอิงแนวตั้ง */
function eobVLine(ctx, p, xv, col, dash, lw) {
  var x = Math.round(p.X(xv)) + 0.5;
  if (x < p.x - 1 || x > p.x + p.w + 1) return;
  ctx.save();
  ctx.strokeStyle = col;
  ctx.lineWidth = lw || 1;
  if (dash) ctx.setLineDash(dash);
  ctx.beginPath();
  ctx.moveTo(x, p.y);
  ctx.lineTo(x, p.y + p.h);
  ctx.stroke();
  ctx.restore();
}

/* ลูกศรวัดระยะแนวตั้ง (ใช้กับ U_обр, ΔU) */
function eobVArrow(ctx, p, xv, a, b, col, txt, fs) {
  var x = p.X(xv), ya = p.Y(a), yb = p.Y(b), d = yb > ya ? 1 : -1;
  ctx.save();
  ctx.strokeStyle = col;
  ctx.fillStyle = col;
  ctx.lineWidth = 1.2;
  ctx.beginPath();
  ctx.moveTo(x, ya);
  ctx.lineTo(x, yb);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(x, yb); ctx.lineTo(x - 3, yb - 5 * d); ctx.lineTo(x + 3, yb - 5 * d);
  ctx.closePath(); ctx.fill();
  ctx.beginPath();
  ctx.moveTo(x, ya); ctx.lineTo(x - 3, ya + 5 * d); ctx.lineTo(x + 3, ya + 5 * d);
  ctx.closePath(); ctx.fill();
  if (txt) {
    ctx.font = eobFont(fs);
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    var tw = ctx.measureText(txt).width, hh = fs * 1.15;
    var ty = (ya + yb) / 2, g2 = 0;
    while (!eobFree(p, x + 5, ty - hh / 2, x + 5 + tw, ty + hh / 2) && g2++ < 5 &&
           ty + hh * 1.6 < p.y + p.h) ty += hh + 2;
    ctx.fillText(txt, x + 5, ty);
    eobTake(p, x + 5, ty - hh / 2, x + 5 + tw, ty + hh / 2);
  }
  ctx.restore();
}

/* แกน ωt เป็นหน่วย π */
function eobAxisPi(ctx, p, n, show, fs) {
  ctx.save();
  ctx.strokeStyle = CV("--grid");
  ctx.lineWidth = 1;
  ctx.fillStyle = CV("--ink-3");
  ctx.font = eobFont(fs);
  ctx.textAlign = "center";
  ctx.textBaseline = "top";
  for (var k = 0; k <= n; k++) {
    var px = Math.round(p.X(k * Math.PI)) + 0.5;
    ctx.beginPath();
    ctx.moveTo(px, p.y);
    ctx.lineTo(px, p.y + p.h);
    ctx.stroke();
    if (show) ctx.fillText(k === 0 ? "0" : (k === 1 ? "π" : (k + "π")), px, p.y + p.h + 4);
  }
  ctx.restore();
}

/* แกนมุมเป็นองศา (สำหรับวงจรสามเฟส) */
function eobAxisDeg(ctx, p, step, show, fs) {
  ctx.save();
  ctx.strokeStyle = CV("--grid");
  ctx.lineWidth = 1;
  ctx.fillStyle = CV("--ink-3");
  ctx.font = eobFont(fs);
  ctx.textAlign = "center";
  ctx.textBaseline = "top";
  for (var v = p.xmin; v <= p.xmax + 1e-6; v += step) {
    var px = Math.round(p.X(v)) + 0.5;
    ctx.beginPath();
    ctx.moveTo(px, p.y);
    ctx.lineTo(px, p.y + p.h);
    ctx.stroke();
    if (show) ctx.fillText(String(Math.round(v)), px, p.y + p.h + 4);
  }
  ctx.restore();
}

/* ระบายพื้นที่ใต้กราฟถึงระดับศูนย์ */
function eobFill(ctx, p, pts, col) {
  ctx.save();
  ctx.beginPath();
  ctx.rect(p.x, p.y, p.w, p.h);
  ctx.clip();
  ctx.beginPath();
  var y0 = p.Y(0), i;
  ctx.moveTo(p.X(pts[0][0]), y0);
  for (i = 0; i < pts.length; i++) ctx.lineTo(p.X(pts[i][0]), p.Y(pts[i][1]));
  ctx.lineTo(p.X(pts[pts.length - 1][0]), y0);
  ctx.closePath();
  ctx.fillStyle = col;
  ctx.fill();
  ctx.restore();
}

/* ---------------------------------------------------------------------------
   1. eoRect1 — Однофазный однополупериодный выпрямитель
   สูตร: Л3 сл. 17  u₂ = U_2m·sin ωt · Л3 сл. 18  U₀ = U_2m/π
   Л3 сл. 15/18  K_U = U₀/U₂ = √2/π = 0,45 · U_обр.max = U_2m = √2·U₂ ⇒ K_ДU = π
   Л3 сл. 14  K_п = ΔU/(2U₀) = π/2 · f_п = m·f_c (m = 1)
   กราฟ i₁ = i₀ − I₀ คือรูปที่สไลด์ 18 วาด (ระดับคงที่ I₀·κ_т ใต้ศูนย์ ที่ κ_т = 1)
--------------------------------------------------------------------------- */
function eoRect1(host) {
  buildDemo(host, {
    label: "Лекция 3 · сл. 17–18",
    title: "วงจรครึ่งคลื่นเฟสเดียว — ปรับ U_2m · f_c · R_н แล้วดูว่า U₀/U₂ ออกมา 0,45 เสมอ",
    ratio: 0.8,
    legend: '<span><i style="background:var(--accent)"></i>u₂</span>' +
      '<span><i style="background:var(--accent-2)"></i>u_вых</span>' +
      '<span><i style="background:var(--ok)"></i>U₀ · I₀</span>' +
      '<span><i style="background:var(--ink-3)"></i>i₁ — องค์ประกอบไฟตรงในหม้อแปลง</span>',
    controls: [
      { id: "U2m", label: "U<sub>2m</sub>, В — แอมพลิจูดขดทุติยภูมิ", min: 10, max: 310, step: 5, value: 100, fmt: function (v) { return eobF(v, 0); } },
      { id: "fc", label: "f<sub>c</sub>, Гц — ความถี่แหล่งจ่าย", min: 50, max: 400, step: 10, value: 50, fmt: function (v) { return eobF(v, 0); } },
      { id: "Rn", label: "R<sub>н</sub>, Ом — ความต้านทานโหลด", min: 5, max: 1000, step: 5, value: 100, fmt: function (v) { return eobF(v, 0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink3 = CV("--ink-3"), crit = CV("--crit"), wash = CV("--wash-2");
      var fs = eobFS(w);
      var U2m = s.U2m, f = s.fc, R = s.Rn;
      var U2 = U2m / Math.SQRT2, U0 = U2m / Math.PI, KU = U0 / U2;
      var Uobr = U2m, I0 = U0 / R, Im = U2m / R, Kp = Math.PI / 2, fp = f;

      var N = 720, thmax = 4 * Math.PI, k, x, v, o;
      var u2 = [], uv = [], i0 = [], i1 = [];
      for (k = 0; k <= N; k++) {
        x = thmax * k / N;
        v = U2m * Math.sin(x);
        o = v > 0 ? v : 0;
        u2.push([x, v]);
        uv.push([x, o]);
        i0.push([x, o / R]);
        i1.push([x, o / R - I0]);
      }

      var g = eobPlots(w, h, 3, { gap: 18, bottom: 22 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, thmax, -1.15 * U2m, 1.15 * U2m);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, thmax, -0.12 * U2m, 1.15 * U2m);
      var p3 = new Plot(ctx, g[2].x, g[2].y, g[2].w, g[2].h, 0, thmax, -1.3 * I0, 1.15 * Im);

      p1.frame([], eobTicksN(-U2m, U2m, 4), null, null,true);
      eobAxisPi(ctx, p1, 4, false, fs);
      p1.clip(function () { p1.line(u2, acc, 2); });
      eobRef(ctx, p1, 0, CV("--line-2"), null, fs, [2, 3]);
      eobVArrow(ctx, p1, 3 * Math.PI / 2 + 0.35, 0, -U2m, crit, "U_обр = √2·U₂", fs);
      eobTag(ctx, p1, "u₂, В", acc, fs);

      p2.frame([], eobTicksN(0, U2m, 4), null, null,true);
      eobAxisPi(ctx, p2, 4, false, fs);
      eobFill(ctx, p2, uv, wash);
      p2.clip(function () { p2.line(uv, acc2, 2); });
      eobRef(ctx, p2, U0, ok, "U₀ = U_2m/π", fs);
      eobTag(ctx, p2, "u_вых, В  (m = 1 ระลอกต่อคาบ)", acc2, fs);

      p3.frame([], eobTicksN(-I0, Im, 4), null, null,true);
      eobAxisPi(ctx, p3, 4, true, fs);
      p3.clip(function () {
        p3.line(i1, ink3, 1.4, [4, 3]);
        p3.line(i0, acc2, 2);
      });
      eobRef(ctx, p3, I0, ok, "I₀ = U₀/R_н", fs);
      eobRef(ctx, p3, -I0, ink3, "−I₀·κ_т — подмагничивание", fs, [3, 3]);
      eobTag(ctx, p3, "i₀ = i_V = i₂, А · i₁ (เส้นประ)", acc2, fs);

      readout.innerHTML =
        'U₀ = <b>' + eobF(U0, 1) + ' В</b>' +
        '<span>U₂ = U<sub>2m</sub>/√2 = <b>' + eobF(U2, 1) + ' В</b></span>' +
        '<span>K<sub>U</sub> = U₀/U₂ = <b class="good">' + eobF(KU, 3) + '</b> (ตาราง сл. 15 ให้ 0,45)</span>' +
        '<span>U<sub>обр.max</sub> = √2·U₂ = <b>' + eobF(Uobr, 1) + ' В</b> ⇒ K<sub>ДU</sub> = π = 3,14</span>' +
        '<span>K<sub>п</sub> = ΔU/(2U₀) = π/2 = <b class="bad">' + eobF(Kp, 2) + '</b> — แย่ที่สุดในตาราง</span>' +
        '<span>f<sub>п</sub> = m·f<sub>c</sub> = <b>' + eobF(fp, 0) + ' Гц</b> (m = 1)</span>' +
        '<span>I₀ = I<sub>V.ср</sub> = I<sub>2ср</sub> = <b>' + eobF(I0 * 1000, 0) + ' мА</b> · P₀ = <b>' + eobF(U0 * I0, 2) + ' Вт</b></span>' +
        '<span>K<sub>S</sub> = 3,09 — เส้นประในแผงล่างคือสาเหตุ: ขดปฐมภูมิมีระดับไฟตรงค้าง แกนหม้อแปลงอิ่มตัวง่าย</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   2. eoRectCompare — ตารางเปรียบเทียบจริงของภาควิชา Л3 сл. 15 = Л4 сл. 16
   ตัวเลขทุกตัวคัดจากตาราง (ห้ามคำนวณใหม่) · รูปคลื่นด้านบนสร้างจาก m ของแต่ละแถว
   U₀/U_m = (m/π)·sin(π/m) สำหรับ m ≥ 2 และ = 1/π สำหรับ m = 1 (ผู้เรียบเรียง derive)
   f_п = m·f_c (Л3 сл. 14)
--------------------------------------------------------------------------- */
var EOB_SCHEMES = [
  { btn: "1φ · 1П", ru: "Однофазный однополупериодный", KU: 0.45, KI: 0.64, m: 1, Kp: 1.57, Kf: 1.57, KDU: 3.14, KDI: 1, KS: 3.09 },
  { btn: "1φ · 0", ru: "Однофазный двухполупериодный нулевой", KU: 0.9, KI: 1.24, m: 2, Kp: 0.67, Kf: 1.57, KDU: 3.14, KDI: 0.5, KS: 1.48 },
  { btn: "1φ · М", ru: "Однофазный двухполупериодный мостовой", KU: 0.9, KI: 0.9, m: 2, Kp: 0.67, Kf: 1.57, KDU: 1.57, KDI: 0.5, KS: 1.23 },
  { btn: "3φ · 0", ru: "Трехфазный однополупериодный нулевой", KU: 1.17, KI: 1.72, m: 3, Kp: 0.25, Kf: 1.76, KDU: 2.09, KDI: 0.33, KS: 1.35 },
  { btn: "3φ · М", ru: "Трехфазный двухполупериодный мостовой", KU: 2.34, KI: 1.23, m: 6, Kp: 0.06, Kf: 1.74, KDU: 1.05, KDI: 0.33, KS: 1.05 }
];

var EOB_ROWS = [
  { id: "KU", t: "K_U", best: "max", d: 2 },
  { id: "KI", t: "K_I", best: "", d: 2 },
  { id: "m", t: "K_f = m", best: "max", d: 0 },
  { id: "Kp", t: "K_п", best: "min", d: 2 },
  { id: "Kf", t: "K_ф", best: "", d: 2 },
  { id: "KDU", t: "K_ДU", best: "min", d: 2 },
  { id: "KDI", t: "K_ДI", best: "min", d: 2 },
  { id: "KS", t: "K_S", best: "min", d: 2 }
];

/* รูปคลื่น u₀/U_m ของสคีมที่เลือก (หน่วยของค่ายอดที่ป้อนบล็อกวาล์ว) */
function eobWave(sel, th) {
  var v, m;
  if (sel === 0) return Math.max(Math.sin(th), 0);
  if (sel === 1 || sel === 2) return Math.abs(Math.sin(th));
  v = eobPh(th);
  if (sel === 3) return eobMax3(v);
  return (eobMax3(v) - eobMin3(v)) / Math.sqrt(3);
}

function eoRectCompare(host) {
  buildDemo(host, {
    label: "Лекция 3 · сл. 15  (= Лекция 4 · сл. 16)",
    title: "ตารางจริงของภาควิชา 5 สคีม — กดปุ่มเลือกสคีม แล้วดูว่าดัชนีทั้ง 8 ตัวขยับไปตรงไหน",
    ratio: 0.92,
    legend: '<span><i style="background:var(--accent-2)"></i>สคีมที่เลือก</span>' +
      '<span><i style="background:var(--ok)"></i>ค่าที่ดีที่สุดของคอลัมน์</span>' +
      '<span><i style="background:var(--ink-3)"></i>อีก 4 สคีม</span>',
    controls: [
      { id: "fc", label: "f<sub>c</sub>, Гц — ความถี่แหล่งจ่าย (ใช้คำนวณ f_п = m·f_c)", min: 50, max: 400, step: 10, value: 50, fmt: function (v) { return eobF(v, 0); } }
    ],
    buttons: [
      { id: "b0", label: "1φ · 1П", act: function (st) { st.sel = 0; } },
      { id: "b1", label: "1φ · 0", act: function (st) { st.sel = 1; } },
      { id: "b2", label: "1φ · М", act: function (st) { st.sel = 2; } },
      { id: "b3", label: "3φ · 0", act: function (st) { st.sel = 3; } },
      { id: "b4", label: "3φ · М", act: function (st) { st.sel = 4; } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc2 = CV("--accent-2"), ok = CV("--ok"), ink = CV("--ink"),
        ink3 = CV("--ink-3"), line2 = CV("--line-2"), wash = CV("--wash-2"), crit = CV("--crit");
      var fs = eobFS(w);
      var sel = (s.sel === undefined) ? 0 : s.sel;
      var sc = EOB_SCHEMES[sel], m = sc.m;

      /* --- รูปคลื่นด้านบน --- */
      var N = 720, k, th, arr = [], vals = [];
      for (k = 0; k <= N; k++) {
        th = 2 * Math.PI * k / N;
        var y = eobWave(sel, th);
        arr.push([th, y]);
        vals.push(y);
      }
      var st = eobStat(vals);
      var U0rel = m === 1 ? 1 / Math.PI : (m / Math.PI) * Math.sin(Math.PI / m);

      var wavH = Math.round(h * 0.3);
      var pw = new Plot(ctx, w < 430 ? 38 : 46, 8, w - (w < 430 ? 38 : 46) - 10, wavH, 0, 2 * Math.PI, -0.08, 1.12);
      pw.frame([], [0, 0.5, 1], null, null,true);
      eobAxisPi(ctx, pw, 2, true, fs);
      eobFill(ctx, pw, arr, wash);
      pw.clip(function () { pw.line(arr, acc2, 2); });
      eobRef(ctx, pw, U0rel, ok, "U₀/U_m = " + eobF(U0rel, 3), fs);
      eobTag(ctx, pw, "u₀/U_m · " + m + " ระลอกต่อคาบ", acc2, fs);

      /* --- แถวดัชนี 8 แถว --- */
      var top = wavH + 30, bot = h - 6;
      var rowH = (bot - top) / EOB_ROWS.length;
      var lw = w < 430 ? 46 : 56;
      var tx0 = pw.x + lw, tx1 = w - 46;
      var i, j;
      ctx.save();
      ctx.font = eobFont(fs);
      for (i = 0; i < EOB_ROWS.length; i++) {
        var r = EOB_ROWS[i], yy = top + rowH * (i + 0.5);
        var mx = 0, bestV = null;
        for (j = 0; j < 5; j++) mx = Math.max(mx, EOB_SCHEMES[j][r.id]);
        for (j = 0; j < 5; j++) {
          var vv = EOB_SCHEMES[j][r.id];
          if (bestV === null) bestV = vv;
          else if (r.best === "max") bestV = Math.max(bestV, vv);
          else if (r.best === "min") bestV = Math.min(bestV, vv);
        }
        ctx.fillStyle = ink3;
        ctx.textAlign = "left";
        ctx.textBaseline = "middle";
        ctx.fillText(r.t, pw.x, yy);
        ctx.strokeStyle = line2;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(tx0, Math.round(yy) + 0.5);
        ctx.lineTo(tx1, Math.round(yy) + 0.5);
        ctx.stroke();
        for (j = 0; j < 5; j++) {
          var val = EOB_SCHEMES[j][r.id];
          var px = tx0 + (val / mx) * (tx1 - tx0);
          var isSel = j === sel, isBest = r.best !== "" && val === bestV;
          ctx.beginPath();
          ctx.arc(px, yy, isSel ? 4.5 : 2.6, 0, 7);
          ctx.fillStyle = isSel ? acc2 : (isBest ? ok : ink3);
          ctx.fill();
        }
        var pxs = tx0 + (EOB_SCHEMES[sel][r.id] / mx) * (tx1 - tx0);
        ctx.fillStyle = acc2;
        ctx.textAlign = pxs > (tx0 + tx1) / 2 ? "right" : "left";
        ctx.textBaseline = "bottom";
        ctx.fillText(eobF(EOB_SCHEMES[sel][r.id], r.d), pxs + (pxs > (tx0 + tx1) / 2 ? -7 : 7), yy - 2);
        ctx.fillStyle = ink3;
        ctx.textAlign = "left";
        ctx.textBaseline = "middle";
        ctx.fillText(eobF(mx, r.d), tx1 + 4, yy);
      }
      ctx.restore();

      readout.innerHTML =
        '<b>' + sc.ru + '</b>' +
        '<span>K<sub>U</sub> = U₀/U₂ = <b>' + eobF(sc.KU, 2) + '</b> · K<sub>I</sub> = <b>' + eobF(sc.KI, 2) + '</b> · K<sub>f</sub> = m = <b>' + m + '</b></span>' +
        '<span>K<sub>п</sub> = <b class="' + (sc.Kp < 0.3 ? "good" : "bad") + '">' + eobF(sc.Kp, 2) + '</b> · K<sub>ф</sub> = <b>' + eobF(sc.Kf, 2) + '</b></span>' +
        '<span>K<sub>ДU</sub> = U<sub>обр.max</sub>/U₀ = <b>' + eobF(sc.KDU, 2) + '</b> · K<sub>ДI</sub> = I<sub>д.ср</sub>/I₀ = <b>' + eobF(sc.KDI, 2) + '</b></span>' +
        '<span>K<sub>S</sub> = S<sub>тр</sub>/P₀ = <b class="' + (sc.KS < 1.4 ? "good" : "bad") + '">' + eobF(sc.KS, 2) + '</b></span>' +
        '<span>f<sub>п</sub> = m·f<sub>c</sub> = <b>' + eobF(m * s.fc, 0) + ' Гц</b> · U₀/U_m ที่คำนวณจากรูปคลื่น = <b>' + eobF(st.m, 3) + '</b></span>' +
        '<span>หมายเหตุต้นฉบับ: คำอธิบายคอลัมน์ 6 กับ 7 ใต้ตารางสไลด์สลับกัน — ตัวห้อยถูก (6 = по напряжению, 7 = по току)</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   3. eoRectRipple — สองนิยามของ K_п ที่ให้ค่าต่างกัน ~20 %
   นิยาม B (Л4 сл. 15): K_П(1) = U_М(1)/U₀ = 2/(m² − 1) — ใช้ได้เมื่อ m ≥ 2
   นิยาม A (Л3 сл. 14): K_п = ΔU/(2·U₀)
   ผู้เรียบเรียง derive จากรูปคลื่น: U_min = U_m·cos(π/m) · ΔU = U_m·[1 − cos(π/m)]
   U₀ = U_m·(m/π)·sin(π/m) · สำหรับ m = 1: ΔU = U_m, U₀ = U_m/π ⇒ ทั้งสองนิยามได้ π/2
--------------------------------------------------------------------------- */
function eobKp1(m) { return m <= 1 ? Math.PI / 2 : 2 / (m * m - 1); }

function eobKpDef(m) {
  if (m <= 1) return Math.PI / 2;
  var dU = 1 - Math.cos(Math.PI / m);
  var U0 = (m / Math.PI) * Math.sin(Math.PI / m);
  return dU / (2 * U0);
}

/* รูปแบบเลขของแต่ละคอลัมน์ ให้ตรงกับที่ภาควิชาพิมพ์ */
function eobFmtB(v) { return v >= 0.1 ? eobF(v, 2) : eobF(v, 3); }
function eobFmtA(v) { return v >= 1 ? eobF(v, 2) : eobF(v, 3); }

function eoRectRipple(host) {
  buildDemo(host, {
    label: "Лекция 4 · сл. 15  ·  Лекция 3 · сл. 14",
    title: "กับดักข้อสอบ — K_п มีสองนิยามที่ให้ค่าต่างกันราว 20 % เลื่อน m แล้วเทียบทั้งคู่",
    ratio: 0.92,
    legend: '<span><i style="background:var(--accent)"></i>K_П(1) = 2/(m²−1) — ฮาร์มอนิกที่ 1</span>' +
      '<span><i style="background:var(--accent-2)"></i>K_п = ΔU/(2U₀) — วัดจากออสซิลโลสโคป</span>' +
      '<span><i style="background:var(--ok)"></i>U₀</span>',
    controls: [
      { id: "m", label: "m — จำนวนระลอกต่อคาบของแรงดันป้อน", min: 1, max: 12, step: 1, value: 6, fmt: function (v) { return eobF(v, 0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink = CV("--ink"), ink3 = CV("--ink-3"), line2 = CV("--line-2"),
        wash = CV("--wash-2"), crit = CV("--crit"), panel2 = CV("--panel-2");
      var fs = eobFS(w);
      var m = Math.round(s.m);

      /* รูปคลื่นหนึ่งคาบของแรงดันป้อน */
      var N = 720, k, th, arr = [], vals = [], y;
      for (k = 0; k <= N; k++) {
        th = 2 * Math.PI * k / N;
        if (m === 1) y = Math.max(Math.sin(th), 0);
        else y = Math.cos((th % (2 * Math.PI / m)) - Math.PI / m);
        arr.push([th, y]);
        vals.push(y);
      }
      var st = eobStat(vals);
      var U0a = m === 1 ? 1 / Math.PI : (m / Math.PI) * Math.sin(Math.PI / m);
      var dUa = m === 1 ? 1 : 1 - Math.cos(Math.PI / m);
      var kB = eobKp1(m), kA = eobKpDef(m);
      var diff = kB > 0 ? (kA / kB - 1) * 100 : 0;

      var wide = w >= 560;
      var topH = Math.round(h * (wide ? 0.46 : 0.30));
      var L = w < 430 ? 38 : 46;

      /* --- แผงรูปคลื่น --- */
      var wavW = wide ? Math.round((w - L - 20) * 0.52) : (w - L - 10);
      var pw = new Plot(ctx, L, 8, wavW, topH - 24, 0, 2 * Math.PI, -0.05, 1.12);
      pw.frame([], [0, 0.5, 1], null, null,true);
      eobAxisPi(ctx, pw, 2, true, fs);
      eobFill(ctx, pw, arr, wash);
      pw.clip(function () { pw.line(arr, acc2, 2); });
      eobRef(ctx, pw, U0a, ok, "U₀ = " + eobF(U0a, 3) + "·U_m", fs);
      eobRef(ctx, pw, st.max, ink3, null, fs, [2, 3]);
      eobRef(ctx, pw, st.min, ink3, null, fs, [2, 3]);
      eobVArrow(ctx, pw, Math.PI / m + 0.12, st.max, st.min, crit, "ΔU", fs);
      eobTag(ctx, pw, "u₀/U_m · m = " + m, acc2, fs);

      /* --- กราฟ K(m) เฉพาะจอกว้าง --- */
      if (wide) {
        var gx = L + wavW + 26;
        var pg = new Plot(ctx, gx, 8, w - gx - 12, topH - 24, 1, 12, 0, 1.7);
        pg.frame(ticks(1, 12, 11), eobTicksN(0, 1.6, 4), null, null,false);
        var cB = [], cA = [], mm;
        for (mm = 1; mm <= 12; mm++) {
          cB.push([mm, eobKp1(mm)]);
          cA.push([mm, eobKpDef(mm)]);
        }
        pg.clip(function () {
          pg.line(cA, acc2, 2);
          pg.line(cB, acc, 2, [5, 4]);
          pg.dots(cA, acc2, 2.6);
          pg.dots(cB, acc, 2.6);
          pg.dots([[m, kA], [m, kB]], crit, 4);
        });
        eobTag(ctx, pg, "K_п(m) — สองนิยาม", ink3, fs);
      }

      /* --- ตารางค่าที่ต้องท่อง m = 1, 2, 3, 6 --- */
      var tabTop = topH + 6, tabBot = h - 4;
      var rowsM = [1, 2, 3, 6];
      var rh = (tabBot - tabTop) / (rowsM.length + 1);
      var c0 = L, c1 = L + Math.round((w - L - 10) * 0.14),
        c2 = L + Math.round((w - L - 10) * 0.46), c3 = L + Math.round((w - L - 10) * 0.78);
      ctx.save();
      ctx.font = eobFont(fs);
      ctx.textBaseline = "middle";
      ctx.textAlign = "left";
      ctx.fillStyle = ink3;
      var hy = tabTop + rh * 0.5;
      ctx.fillText("m", c0, hy);
      ctx.fillText("2/(m²−1)", c1, hy);
      ctx.fillText("ΔU/(2U₀)", c2, hy);
      ctx.fillText("ต่างกัน", c3, hy);
      ctx.strokeStyle = line2;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(c0, Math.round(tabTop + rh) + 0.5);
      ctx.lineTo(w - 10, Math.round(tabTop + rh) + 0.5);
      ctx.stroke();
      for (k = 0; k < rowsM.length; k++) {
        var mm2 = rowsM[k], yy = tabTop + rh * (k + 1.5);
        var b = eobKp1(mm2), a = eobKpDef(mm2), dd = b > 0 ? (a / b - 1) * 100 : 0;
        if (mm2 === m) {
          ctx.fillStyle = panel2;
          ctx.fillRect(c0 - 4, yy - rh / 2 + 1, w - 10 - c0 + 8, rh - 2);
        }
        ctx.fillStyle = mm2 === m ? ink : ink3;
        ctx.fillText(String(mm2), c0, yy);
        ctx.fillStyle = acc;
        ctx.fillText(eobClip(ctx, mm2 === 1 ? "1,57  (สูตรใช้ไม่ได้ · π/2)" : eobFmtB(b), c2 - c1 - 8), c1, yy);
        ctx.fillStyle = acc2;
        ctx.fillText(eobFmtA(a), c2, yy);
        ctx.fillStyle = mm2 === 1 ? ok : crit;
        ctx.fillText(eobF(dd, 1) + " %", c3, yy);
      }
      ctx.restore();

      readout.innerHTML =
        'ที่ m = <b>' + m + '</b> — นิยาม B (ฮาร์มอนิกที่ 1) K<sub>П(1)</sub> = 2/(m²−1) = <b>' + (m === 1 ? "ใช้ไม่ได้ · π/2 = 1,57" : eobFmtB(kB)) + '</b>' +
        '<span>นิยาม A (วัดจากรูปคลื่น) K<sub>п</sub> = ΔU/(2U₀) = <b>' + eobFmtA(kA) + '</b></span>' +
        '<span>' + (Math.abs(diff) < 0.05
          ? 'สองนิยามให้ค่า<b class="good">ตรงกันพอดี</b>ที่ m นี้'
          : 'ค่าที่วัดได้' + (diff > 0 ? 'สูงกว่า' : 'ต่ำกว่า') + 'ค่าทฤษฎีในตาราง <b class="bad">' + eobF(Math.abs(diff), 1) + ' %</b> — เกิดจากนิยาม ไม่ใช่วงจรเสีย') + '</span>' +
        '<span>U₀ = <b>' + eobF(U0a, 3) + '·U_m</b> · ΔU = <b>' + eobF(dUa, 3) + '·U_m</b> · U<sub>min</sub> = <b>' + eobF(st.min, 3) + '·U_m</b>' +
          (m === 1 ? ' (m = 1 ไดโอดปิดครึ่งคาบ แรงดันขาออกจึงเป็น 0 — สูตร U_m·cos(π/m) ใช้ได้ตั้งแต่ m ≥ 2 เท่านั้น)'
                   : ' = U_m·cos(π/m)') + '</span>' +
        '<span>ตรวจกับรูปคลื่น: ค่าเฉลี่ยที่คำนวณเชิงตัวเลข = <b>' + eobF(st.m, 3) + '·U_m</b> ⇒ ตรงกับสูตร</span>' +
        '<span>เวลาสอบต้องบอกให้ชัดว่าใช้นิยามใด — ตาราง сл. 15/16 (1,57 · 0,67 · 0,25 · 0,06) ใช้นิยาม B</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   4. eoRect3 — สามเฟส: нулевая (3 พัลส์) และ мостовая Ларионова (6 พัลส์)
   Л4 сл. 10–14 · โครงสร้างวงจรและไดอะแกรม
   นูลเลวายา: u₀ = max(u_a, u_b, u_c) · m = 3 · U₀ = 1,17·U_ф = 0,675·U_л
   Ларионов:  u₀ = max(u) − min(u) · m = 6 · U₀ = (3√2/π)·U_л = 1,3505·U_л
   หมายเหตุต้นฉบับ: Л4 сл. 14 พิมพ์ U₀ = 1,34·U_вх.л — ที่ถูกคือ 1,35 (Л5 сл. 20 ให้ 3√2/π)
--------------------------------------------------------------------------- */
function eoRect3(host) {
  buildDemo(host, {
    label: "Лекция 4 · сл. 10–14",
    title: "สามเฟส нулевая (3 พัลส์) เทียบสะพาน Ларионова (6 พัลส์) — ดู U₀ และระลอกเปลี่ยนไป",
    ratio: 0.7,
    legend: '<span><i style="background:var(--accent)"></i>u_a · u_b · u_c</span>' +
      '<span><i style="background:var(--accent-2)"></i>u₀ ที่โหลด</span>' +
      '<span><i style="background:var(--ok)"></i>U₀ ค่าเฉลี่ย</span>',
    controls: [
      { id: "Ul", label: "U<sub>вх.л</sub>, В — แรงดันคู่สาย (действующее)", min: 10, max: 400, step: 5, value: 220, fmt: function (v) { return eobF(v, 0); } },
      { id: "fc", label: "f<sub>c</sub>, Гц — ความถี่แหล่งจ่าย", min: 50, max: 400, step: 10, value: 400, fmt: function (v) { return eobF(v, 0); } }
    ],
    buttons: [
      { id: "brg", label: "мостовая (Ларионов)", toggle: true, value: true }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink3 = CV("--ink-3"), crit = CV("--crit"), wash = CV("--wash-2"), line2 = CV("--line-2");
      var fs = eobFS(w);
      var Ul = s.Ul, f = s.fc, brg = s.brg !== false;
      var Uf = Ul / Math.sqrt(3);
      var Umf = Math.SQRT2 * Uf;            /* ค่ายอดของแรงดันเฟส */
      var m = brg ? 6 : 3;

      var N = 720, k, th, deg, v, y;
      var pa = [], pb = [], pc = [], po = [], vals = [];
      for (k = 0; k <= N; k++) {
        deg = 720 * k / N;
        th = deg * Math.PI / 180;
        v = eobPh(th);
        pa.push([deg, Umf * v[0]]);
        pb.push([deg, Umf * v[1]]);
        pc.push([deg, Umf * v[2]]);
        y = brg ? Umf * (eobMax3(v) - eobMin3(v)) : Umf * eobMax3(v);
        po.push([deg, y]);
        if (deg < 360) vals.push(y);
      }
      var st = eobStat(vals);
      var KpA = eobKpA(st), KpB = eobKp1(m);
      var U0f = brg ? (3 * Math.SQRT2 / Math.PI) * Ul : 1.17 * Uf;
      var U0_134 = brg ? 1.34 * Ul : null;
      var Uobr = Math.SQRT2 * Ul;
      var top = brg ? Umf * Math.sqrt(3) : Umf;

      var g = eobPlots(w, h, 2, { gap: 20, bottom: 22 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, 720, -1.15 * Umf, 1.15 * Umf);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, 720, -0.06 * top, 1.12 * top);

      p1.frame([], eobTicksN(-Umf, Umf, 4), null, null,true);
      eobAxisDeg(ctx, p1, 120, false, fs);
      p1.clip(function () {
        p1.line(pa, acc, 1.8);
        p1.line(pb, acc, 1.4, [6, 4]);
        p1.line(pc, acc, 1.4, [2, 3]);
      });
      eobRef(ctx, p1, 0, line2, null, fs, [2, 3]);
      eobTag(ctx, p1, "u_a (ทึบ) · u_b · u_c, В", acc, fs);

      p2.frame([], eobTicksN(0, top, 4), null, null,true);
      eobAxisDeg(ctx, p2, 120, true, fs);
      eobFill(ctx, p2, po, wash);
      p2.clip(function () { p2.line(po, acc2, 2); });
      eobRef(ctx, p2, U0f, ok, "U₀ = " + eobF(U0f, 1) + " В", fs);
      eobRef(ctx, p2, st.min, ink3, "U_min", fs, [2, 3]);
      eobVArrow(ctx, p2, 30, st.max, st.min, crit, "ΔU", fs);
      eobTag(ctx, p2, "u₀, В · m = " + m + " ระลอกต่อคาบ", acc2, fs);

      var head = brg ? "Трехфазная мостовая (схема Ларионова)" : "Трехфазная нулевая (однополупериодная)";
      readout.innerHTML =
        '<b>' + head + '</b> · m = <b>' + m + '</b>' +
        '<span>U₀ = <b>' + eobF(U0f, 1) + ' В</b> ' + (brg
          ? '= (3√2/π)·U<sub>вх.л</sub> = <b>1,3505</b>·U_л'
          : '= 1,17·U_ф = 0,675·U_л') + '</span>' +
        (brg ? '<span>หมายเหตุต้นฉบับ: สไลด์ сл. 14 พิมพ์ 1,34·U_вх.л ⇒ ได้ ' + eobF(U0_134, 1) + ' В ต่างจากค่าที่ถูก <b class="bad">' + eobF(U0f - U0_134, 1) + ' В</b> (0,7 %) — ใช้ 1,35 เสมอ</span>' : '') +
        '<span>ตรวจกับรูปคลื่น: ค่าเฉลี่ยเชิงตัวเลข = <b>' + eobF(st.m, 1) + ' В</b> ⇒ ตรงกับสูตร</span>' +
        '<span>K<sub>П(1)</sub> = 2/(m²−1) = <b class="' + (KpB < 0.3 ? "good" : "bad") + '">' + eobFmtB(KpB) + '</b> · K<sub>п</sub> = ΔU/(2U₀) = <b>' + eobFmtA(KpA) + '</b></span>' +
        '<span>f<sub>п</sub> = m·f<sub>c</sub> = <b>' + eobF(m * f, 0) + ' Гц</b> ⇒ ยิ่ง m มากฟิลเตอร์ยิ่งเล็ก</span>' +
        '<span>U<sub>обр.max</sub> = √2·U_л = <b>' + eobF(Uobr, 1) + ' В</b> ⇒ K<sub>ДU</sub> = ' + (brg ? '1,05' : '2,09') + ' · K<sub>ДI</sub> = 0,33 (ไดโอดนำ 120°)</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   5. eoRectFault — อาการเสียของสะพานสามเฟส Л4 сл. 21–23
   норма:        u = max(u_a,u_b,u_c) − min(u_a,u_b,u_c)                (6 พัลส์)
   обрыв VD1:    u = max(u_b,u_c) − min(u_a,u_b,u_c)                    (หาย 2 พัลส์/คาบ)
   обрыв фазы a: u = max(u_b,u_c) − min(u_b,u_c) = |u_bc|               (หาย 4 พัลส์/คาบ)
   пробой VD1:   ไดโอดพังเป็น перемычка ⇒ หลังลูกโซ่ (сл. 23) VD3 และ VD5 ไหม้เป็น обрыв
                 บัสบวกค้างที่เฟส a: u = u_a − min(u_a,u_b,u_c)
--------------------------------------------------------------------------- */
var EOB_FAULTS = [
  { ru: "Норма", th: "ปกติ", lost: 0 },
  { ru: "Обрыв диода 1", th: "ไดโอด 1 ขาด", lost: 2 },
  { ru: "Пробой диода 1", th: "ไดโอด 1 ทะลุ", lost: -1 },
  { ru: "Обрыв фазы «а»", th: "เฟส a ขาด", lost: 4 }
];

function eobFaultU(fi, v) {
  var mx3 = eobMax3(v), mn3 = eobMin3(v);
  if (fi === 1) return Math.max(0, Math.max(v[1], v[2]) - mn3);
  if (fi === 2) return Math.max(0, v[0] - mn3);
  if (fi === 3) return Math.max(0, Math.max(v[1], v[2]) - Math.min(v[1], v[2]));
  return mx3 - mn3;
}

function eoRectFault(host) {
  buildDemo(host, {
    label: "Лекция 4 · сл. 21–23",
    title: "กดเลือกความบกพร่อง — นับพัลส์ที่หายไปต่อคาบ แล้วอ่าน U₀ กับ K_п ที่เปลี่ยนไป",
    ratio: 0.72,
    legend: '<span><i style="background:var(--accent-2)"></i>u₀ ตอนเสีย</span>' +
      '<span><i style="background:var(--ink-3)"></i>u₀ ตอนปกติ (เส้นประ)</span>' +
      '<span><i style="background:var(--ok)"></i>U₀</span>',
    controls: [
      { id: "Ul", label: "U<sub>вх.л</sub>, В — แรงดันคู่สาย (действующее)", min: 10, max: 400, step: 5, value: 220, fmt: function (v) { return eobF(v, 0); } }
    ],
    buttons: [
      { id: "f0", label: "Норма", act: function (st) { st.fi = 0; } },
      { id: "f1", label: "Обрыв VD1", act: function (st) { st.fi = 1; } },
      { id: "f2", label: "Пробой VD1", act: function (st) { st.fi = 2; } },
      { id: "f3", label: "Обрыв фазы «а»", act: function (st) { st.fi = 3; } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink3 = CV("--ink-3"), crit = CV("--crit"), wash = CV("--wash-2"), line2 = CV("--line-2");
      var fs = eobFS(w);
      var Ul = s.Ul, fi = (s.fi === undefined) ? 0 : s.fi;
      var Umf = Math.SQRT2 * Ul / Math.sqrt(3);
      var top = Umf * Math.sqrt(3);

      var N = 720, k, deg, th, v, pa = [], pb = [], pc = [], pn = [], pf = [], valsF = [], valsN = [];
      for (k = 0; k <= N; k++) {
        deg = 720 * k / N;
        th = deg * Math.PI / 180;
        v = eobPh(th);
        pa.push([deg, Umf * v[0]]);
        pb.push([deg, Umf * v[1]]);
        pc.push([deg, Umf * v[2]]);
        var un = Umf * eobFaultU(0, v), uf = Umf * eobFaultU(fi, v);
        pn.push([deg, un]);
        pf.push([deg, uf]);
        if (deg < 360) { valsN.push(un); valsF.push(uf); }
      }
      var stF = eobStat(valsF), stN = eobStat(valsN);
      var KpF = eobKpA(stF);

      /* นับพัลส์เต็มความสูงในหนึ่งคาบ (ยอด ≥ 0,9 ของยอดปกติ) และนับยอดทั้งหมด */
      var full = 0, any = 0, i, nv = valsF.length;
      for (i = 0; i < nv; i++) {
        var vp = valsF[(i - 1 + nv) % nv], vn = valsF[(i + 1) % nv];
        if (valsF[i] >= vp && valsF[i] > vn) {
          if (valsF[i] > 0.05 * stN.max) any++;
          if (valsF[i] >= 0.9 * stN.max) full++;
        }
      }

      var g = eobPlots(w, h, 2, { gap: 20, bottom: 22 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, 720, -1.15 * Umf, 1.15 * Umf);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, 720, -0.06 * top, 1.12 * top);

      p1.frame([], eobTicksN(-Umf, Umf, 4), null, null,true);
      eobAxisDeg(ctx, p1, 120, false, fs);
      p1.clip(function () {
        p1.line(pa, fi === 3 ? crit : acc, fi === 3 ? 1.2 : 1.8, fi === 3 ? [3, 4] : null);
        p1.line(pb, acc, 1.4, [6, 4]);
        p1.line(pc, acc, 1.4, [2, 3]);
      });
      eobRef(ctx, p1, 0, line2, null, fs, [2, 3]);
      eobTag(ctx, p1, fi === 3 ? "u_a ขาด (เส้นประแดง) · u_b · u_c" : "u_a (ทึบ) · u_b · u_c, В", acc, fs);

      p2.frame([], eobTicksN(0, top, 4), null, null,true);
      eobAxisDeg(ctx, p2, 120, true, fs);
      eobFill(ctx, p2, pf, wash);
      p2.clip(function () {
        p2.line(pn, ink3, 1.3, [4, 4]);
        p2.line(pf, fi === 0 ? acc2 : crit, 2.2);
      });
      eobRef(ctx, p2, stF.m, ok, "U₀ = " + eobF(stF.m, 1) + " В", fs);
      eobTag(ctx, p2, "u₀, В · " + EOB_FAULTS[fi].ru, fi === 0 ? acc2 : crit, fs);

      var diag;
      if (fi === 0) diag = "รูปคลื่น 6 พัลส์เต็มคาบ ระลอกเล็กที่สุด";
      else if (fi === 1) diag = "ยอด ab และ ac หายไป ⇒ หาย 2 พัลส์ต่อคาบ = ไดโอดหนึ่งตัวขาด (Рис. 1.10 а)";
      else if (fi === 3) diag = "เหลือเฉพาะยอดจากคู่ b–c ⇒ หาย 4 พัลส์ต่อคาบ = เฟสหนึ่งของแหล่งจ่ายขาด (Рис. 1.10 б)";
      else diag = "ไดโอดที่ทะลุกลายเป็น перемычка บัสบวกค้างที่เฟส a ⇒ ตาม сл. 23 ไดโอด 3 แล้ว 5 เกิดคอนทัวร์ КЗ จากแรงดัน ba และ ca แล้วไหม้กลายเป็น обрыв";

      readout.innerHTML =
        '<b>' + EOB_FAULTS[fi].ru + '</b> — ' + EOB_FAULTS[fi].th +
        '<span>U₀ = <b class="' + (stF.m > 0.9 * stN.m ? "good" : "bad") + '">' + eobF(stF.m, 1) + ' В</b> = <b>' + eobF(100 * stF.m / stN.m, 0) + ' %</b> ของค่าปกติ (' + eobF(stN.m, 1) + ' В)</span>' +
        '<span>K<sub>п</sub> = ΔU/(2U₀) = <b class="' + (KpF < 0.15 ? "good" : "bad") + '">' + eobFmtA(KpF) + '</b> (ปกติ ' + eobFmtA(eobKpA(stN)) + ')</span>' +
        '<span>พัลส์เต็มความสูงต่อคาบ: <b>' + full + '</b> จาก 6 ⇒ หายไป <b class="' + (full === 6 ? "good" : "bad") + '">' + (6 - full) + '</b> · ยอดที่ยังเห็นได้ทั้งหมด ' + any + '</span>' +
        '<span>U<sub>min</sub> ตกลงถึง <b>' + eobF(stF.min, 1) + ' В</b> — นี่คือรอยบากที่มองเห็นบนออสซิลโลสโคป</span>' +
        '<span>' + diag + '</span>' +
        '<span>กับดัก: ช่วง «зона закрытого состояния» ของไดโอดที่ปิดปกติกับที่ขาดมีรูปเหมือนกัน ต้องดูช่วงที่ไดโอดควรนำจึงแยกออก</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   6. eoFilterC — ฟิลเตอร์ตัวเก็บประจุ Л4 сл. 18
   «Емкостной фильтр применяется … при малом значении тока, потребляемого нагрузкой»
   แบบจำลอง: ไดโอดอุดมคติ ⇒ ถ้า u₂ ≥ u_C ⇒ u_C = u₂ (ชาร์จ)
             ถ้า u₂ < u_C ⇒ คายผ่านโหลดด้วย τ = R_н·C  (Конспект ข้อ 10 · ผู้เรียบเรียงเขียนเป็นสมการ)
   i_V = C·du₂/dt + u₂/R_н ในช่วงนำ · холостой ход ⇒ U_вых → √2·U₂
   K_п = ΔU/(2U₀) (Л3 сл. 14) · q = K_п.вх/K_п.вых (Конспект ข้อ 9 — ไม่มีบนสไลด์ Л4)
--------------------------------------------------------------------------- */
function eoFilterC(host) {
  buildDemo(host, {
    label: "Лекция 4 · сл. 17–18",
    title: "ฟิลเตอร์ตัวเก็บประจุ — เพิ่ม C หรือ R_н แล้วดู τ = R_н·C ยืดจนระลอกแทบหาย แต่พัลส์กระแสไดโอดพุ่ง",
    ratio: 0.7,
    legend: '<span><i style="background:var(--accent)"></i>u₂</span>' +
      '<span><i style="background:var(--accent-2)"></i>u_C = u_вых</span>' +
      '<span><i style="background:var(--crit)"></i>i_V พัลส์กระแสไดโอด</span>' +
      '<span><i style="background:var(--ok)"></i>U₀ · i_н</span>',
    controls: [
      { id: "U2", label: "U₂, В — แรงดันขดทุติยภูมิ (действующее)", min: 5, max: 220, step: 1, value: 24, fmt: function (v) { return eobF(v, 0); } },
      { id: "Rn", label: "R<sub>н</sub>, Ом — ความต้านทานโหลด", min: 10, max: 2000, step: 10, value: 200, fmt: function (v) { return eobF(v, 0); } },
      { id: "C", label: "C, мкФ — ความจุของฟิลเตอร์", min: 1, max: 2000, step: 1, value: 200, fmt: function (v) { return eobF(v, 0); } },
      { id: "fc", label: "f<sub>c</sub>, Гц — ความถี่แหล่งจ่าย", min: 50, max: 400, step: 10, value: 50, fmt: function (v) { return eobF(v, 0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink3 = CV("--ink-3"), crit = CV("--crit"), wash = CV("--wash-2"), line2 = CV("--line-2");
      var fs = eobFS(w);
      var U2 = s.U2, R = s.Rn, C = s.C * 1e-6, f = s.fc;
      var U2m = Math.SQRT2 * U2, T = 1 / f, wq = 2 * Math.PI * f;
      var tau = R * C;

      var per = 24, steps = 900, dt = T / steps;
      var uc = 0, t, us, cond;
      var keep = (per - 2) * T;
      var wu = [], ws = [], wi = [], wn = [], vals = [], ivals = [];
      var tot = per * steps, kk;
      for (kk = 0; kk <= tot; kk++) {
        t = kk * dt;
        us = U2m * Math.sin(wq * t);
        cond = us >= uc;
        if (cond) uc = us;
        else {
          uc = uc - uc * dt / tau;
          if (uc < 0) uc = 0;
        }
        if (t >= keep) {
          var ms = (t - keep) * 1000;
          var iv = cond ? (C * U2m * wq * Math.cos(wq * t) + us / R) : 0;
          if (iv < 0) iv = 0;
          ws.push([ms, us]);
          wu.push([ms, uc]);
          wi.push([ms, iv * 1000]);
          wn.push([ms, uc / R * 1000]);
          vals.push(uc);
          ivals.push(iv);
        }
      }
      var st = eobStat(vals), sti = eobStat(ivals);
      var U0 = st.m, Kp = eobKpA(st), q = 1.5708 / Kp;
      var In = U0 / R, tmax = 2 * T * 1000;

      var g = eobPlots(w, h, 2, { gap: 20, bottom: 24 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, tmax, -1.12 * U2m, 1.12 * U2m);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, tmax, -0.05 * Math.max(sti.max * 1000, 1), 1.12 * Math.max(sti.max * 1000, 1));

      p1.frame(ticks(0, tmax, 4), eobTicksN(-U2m, U2m, 4), null, null,true);
      p1.clip(function () {
        p1.line(ws, acc, 1.4, [4, 4]);
        p1.line(wu, acc2, 2.2);
      });
      eobRef(ctx, p1, U0, ok, "U₀ = " + eobF(U0, 1) + " В", fs);
      eobRef(ctx, p1, U2m, ink3, "√2·U₂ = " + eobF(U2m, 1) + " В", fs, [2, 3]);
      eobRef(ctx, p1, 0, line2, null, fs, [2, 3]);
      eobVArrow(ctx, p1, tmax * 0.62, st.max, st.min, crit, "ΔU = " + eobF(st.dU, 1) + " В", fs);
      eobTag(ctx, p1, "u₂ (เส้นประ) · u_C = u_вых, В", acc2, fs);

      p2.frame(ticks(0, tmax, 4), eobTicksN(0, Math.max(sti.max * 1000, 1), 4), "t, мс", null,false);
      p2.clip(function () {
        p2.line(wi, crit, 2);
        p2.line(wn, ok, 1.6, [5, 4]);
      });
      eobTag(ctx, p2, "i_V พัลส์แคบ (แดง) · i_н เกือบคงที่, мА", crit, fs);

      readout.innerHTML =
        'τ = R<sub>н</sub>·C = <b>' + eobF(tau * 1000, 1) + ' мс</b> = <b>' + eobF(tau / T, 2) + '</b>·T' +
        '<span>U₀ = <b>' + eobF(U0, 1) + ' В</b> · ถ้าไม่มีฟิลเตอร์จะได้ 0,45·U₂ = <b>' + eobF(0.45 * U2, 1) + ' В</b> · ตอนไม่มีโหลด U_вых → √2·U₂ = <b>' + eobF(U2m, 1) + ' В</b></span>' +
        '<span>K<sub>п</sub> = ΔU/(2U₀) = <b class="' + (Kp < 0.1 ? "good" : "bad") + '">' + eobFmtA(Kp) + '</b> (ก่อนกรอง 1,57) ⇒ q = K<sub>п.вх</sub>/K<sub>п.вых</sub> = <b>' + eobF(q, 1) + '</b></span>' +
        '<span>ΔU = <b>' + eobF(st.dU, 1) + ' В</b> · I<sub>н</sub> = <b>' + eobF(In * 1000, 0) + ' мА</b></span>' +
        '<span>i<sub>V.max</sub> = <b class="' + (sti.max / Math.max(In, 1e-9) > 8 ? "bad" : "good") + '">' + eobF(sti.max * 1000, 0) + ' мА</b> = <b>' + eobF(sti.max / Math.max(In, 1e-9), 1) + '</b> เท่าของ I_н — ยิ่ง C โต พัลส์ยิ่งแคบและสูง</span>' +
        '<span>ลองลด R_н (โหลดกินกระแสมาก) จะเห็นระลอกโตทันที ⇒ ตรงกับกรอบแดงบนสไลด์: C-фильтр ใช้กับกระแสโหลดน้อยเท่านั้น</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   7. eoFilterL — ฟิลเตอร์ตัวเหนี่ยวนำและโหมดกระแสไม่ต่อเนื่อง Л4 сл. 19
   «Индуктивный фильтр применяется … при больших значениях тока»
   สมการวงจร (ผู้เรียบเรียงเขียนจากรูปวงจรและคำอธิบาย ЭДС самоиндукции e_L บนสไลด์):
        L·di/dt = u_вент(ωt) − i·R_н ,  i ≥ 0 (วาล์วนำทางเดียว) ,  u_вых = i·R_н
   u_вент: m = 1 → U_m·sin ωt · m = 2 → |U_m·sin ωt| · m = 3 → max(u_a,u_b,u_c)
   เงื่อนไขการกรอง ωL ≫ R_н (Конспект ข้อ 11 — ไม่มีบนสไลด์)
   ที่ L เล็กหรือกระแสโหลดน้อย ⇒ режим прерывистого тока (กระแสขาดเป็นช่วง)
--------------------------------------------------------------------------- */
function eoFilterL(host) {
  buildDemo(host, {
    label: "Лекция 4 · сл. 19",
    title: "ฟิลเตอร์ตัวเหนี่ยวนำ — ลด L หรือเพิ่ม R_н จนกระแสขาดเป็นช่วง (режим прерывистого тока)",
    ratio: 0.7,
    legend: '<span><i style="background:var(--accent)"></i>u_вент ก่อนฟิลเตอร์</span>' +
      '<span><i style="background:var(--accent-2)"></i>u_вых = i·R_н</span>' +
      '<span><i style="background:var(--crit)"></i>i ตัวเหนี่ยวนำ</span>' +
      '<span><i style="background:var(--ok)"></i>I_ср</span>',
    controls: [
      { id: "U", label: "U₂, В — แรงดันเฟส (действующее)", min: 5, max: 220, step: 1, value: 24, fmt: function (v) { return eobF(v, 0); } },
      { id: "L", label: "L, мГн — ตัวเหนี่ยวนำของฟิลเตอร์", min: 0.5, max: 500, step: 0.5, value: 6, fmt: function (v) { return eobF(v, 1); } },
      { id: "Rn", label: "R<sub>н</sub>, Ом — ความต้านทานโหลด", min: 1, max: 500, step: 1, value: 20, fmt: function (v) { return eobF(v, 0); } },
      { id: "fc", label: "f<sub>c</sub>, Гц — ความถี่แหล่งจ่าย", min: 50, max: 400, step: 10, value: 50, fmt: function (v) { return eobF(v, 0); } }
    ],
    buttons: [
      { id: "s1", label: "1φ · 1П", act: function (st) { st.m = 1; } },
      { id: "s2", label: "1φ · мост", act: function (st) { st.m = 2; } },
      { id: "s3", label: "3φ · нулевая (сл. 19)", act: function (st) { st.m = 3; } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink3 = CV("--ink-3"), crit = CV("--crit"), wash = CV("--wash-2"), line2 = CV("--line-2");
      var fs = eobFS(w);
      var U = s.U, L = s.L / 1000, R = s.Rn, f = s.fc;
      var m = (s.m === undefined) ? 1 : s.m;
      var Um = Math.SQRT2 * U, T = 1 / f, wq = 2 * Math.PI * f;

      var steps = 1200, per = 30, dt = T / steps, keep = (per - 2) * T;
      var i = 0, kk, t, us, v;
      var wu = [], wi = [], wo = [], vi = [], vo = [], zero = 0, tot = per * steps;
      for (kk = 0; kk <= tot; kk++) {
        t = kk * dt;
        if (m === 1) us = Um * Math.sin(wq * t);
        else if (m === 2) us = Math.abs(Um * Math.sin(wq * t));
        else { v = eobPh(wq * t); us = Um * eobMax3(v); }
        if (i <= 0 && us <= 0) i = 0;
        else {
          i = i + (us - i * R) / L * dt;
          if (i < 0) i = 0;
        }
        if (t >= keep) {
          var ms = (t - keep) * 1000;
          wu.push([ms, us]);
          wi.push([ms, i]);
          wo.push([ms, i * R]);
          vi.push(i);
          vo.push(i * R);
          if (i <= 1e-9) zero++;
        }
      }
      var sti = eobStat(vi), sto = eobStat(vo);
      var Kp = eobKpA(sto);
      var lam = 360 * (1 - zero / vi.length) * (m === 1 ? 1 : 1);
      var brk = zero > 2;
      var wL = wq * L, ratio = wL / R;
      var tmax = 2 * T * 1000;
      var ymaxU = m === 3 ? Um * 1.12 : Um * 1.12;
      var yminU = m === 1 ? -1.12 * Um : -0.06 * Um;

      var g = eobPlots(w, h, 2, { gap: 20, bottom: 24 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, tmax, yminU, ymaxU);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, tmax, -0.06 * Math.max(sti.max, 1e-3), 1.15 * Math.max(sti.max, 1e-3));

      p1.frame(ticks(0, tmax, 4), eobTicksN(yminU, ymaxU, 4), null, null,true);
      p1.clip(function () {
        p1.line(wu, acc, 1.4, [4, 4]);
        p1.line(wo, acc2, 2.2);
      });
      eobRef(ctx, p1, sto.m, ok, "U_вых.ср = " + eobF(sto.m, 1) + " В", fs);
      eobRef(ctx, p1, 0, line2, null, fs, [2, 3]);
      eobTag(ctx, p1, "u_вент (เส้นประ) · u_вых = i·R_н, В", acc2, fs);

      p2.frame(ticks(0, tmax, 4), eobTicksN(0, Math.max(sti.max, 1e-3), 4), "t, мс", null,false);
      eobFill(ctx, p2, wi, wash);
      p2.clip(function () { p2.line(wi, crit, 2.2); });
      eobRef(ctx, p2, sti.m, ok, "I_ср = " + eobF(sti.m, 2) + " А", fs);
      eobTag(ctx, p2, brk ? "i(t), А — กระแสขาดเป็นช่วง" : "i(t), А — กระแสต่อเนื่อง", crit, fs);

      var nm = m === 1 ? "Однофазная однополупериодная" : (m === 2 ? "Однофазная мостовая" : "Трехфазная нулевая (сл. 19)");
      readout.innerHTML =
        '<b>' + nm + '</b> · m = <b>' + m + '</b>' +
        '<span>ωL = <b>' + eobF(wL, 1) + ' Ом</b> · ωL/R<sub>н</sub> = <b class="' + (ratio > 5 ? "good" : "bad") + '">' + eobF(ratio, 2) + '</b> — เงื่อนไขการกรองคือ ωL ≫ R_н</span>' +
        '<span>โหมด: <b class="' + (brk ? "bad" : "good") + '">' + (brk ? "прерывистый ток — กระแสไม่ต่อเนื่อง" : "непрерывный ток — กระแสต่อเนื่อง") + '</b>' + (brk ? ' · มุมนำ λ ≈ <b>' + eobF(lam, 0) + '°</b>' : '') + '</span>' +
        '<span>I_ср = <b>' + eobF(sti.m, 3) + ' А</b> · ΔI = <b>' + eobF(sti.dU, 3) + ' А</b> · U_вых.ср = <b>' + eobF(sto.m, 1) + ' В</b></span>' +
        '<span>K<sub>п</sub> = ΔU/(2U₀) = <b class="' + (Kp < 0.1 ? "good" : "bad") + '">' + eobFmtA(Kp) + '</b></span>' +
        '<span>เพิ่ม L หรือลด R_н (กระแสโหลดมาก) ⇒ กระแสเรียบและต่อเนื่อง ⇒ ตรงกับกรอบแดง: L-фильтр ใช้กับกระแสโหลดมาก</span>' +
        '<span>ในทางปฏิบัติสไลด์แนะนำให้รวมเป็น LC-фильтр เพราะได้ดีทั้งย่านกระแสน้อยและกระแสมาก</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   8. eoThyristor — ВАХ ของทิริสเตอร์พร้อมกระแสเกต Л5 сл. 10–11
   สไลด์ให้ ВАХ เชิงคุณภาพ (จุดพลิก · ส่วนความต้านทานลบ · I_уд) และแบบจำลองสองทรานซิสเตอร์
   ผู้เรียบเรียงใช้แบบจำลองสองทรานซิสเตอร์ของ сл. 11 เขียนเป็นสมการ:
        i_A = M·(I_к0 + α₂·I_у) + M·(α₁+α₂)·i_A ,  α(i) = a_max·i/(i + i_s)
        ⇒ M = 1/[ (I_к0+α₂I_у)/i + α(i) ] ,  M = 1/[1 − (U/U_проб)^n]
        ⇒ U(i) = U_проб·[ 1 − (I_к0+α₂I_у)/i − α(i) ]^(1/n)
   กิ่งเปิดใช้ U = U_ТО + r_д·i (แบบจำลองไดโอดเชิงเส้น) · I_уд ตามที่สไลด์กำกับ
--------------------------------------------------------------------------- */
var EOB_TH = { Ub: 1200, n: 4, ik0: 1e-4, a2: 0.02, amax: 1.05, is: 0.002, Uto: 1.0, rd: 0.004, Iud: 50 };

/* คืนกิ่งปิด (มาสก์เป็น мА) และจุดพลิก U_вкл ของกระแสเกต Iу [мА] */
function eobThyBranch(IuMa) {
  var P = EOB_TH, c = P.ik0 + P.a2 * IuMa / 1000;
  var pts = [], best = null, k, i, sum, U;
  for (k = 0; k <= 260; k++) {
    i = 1e-5 * Math.pow(10, 3.3 * k / 260);         /* 0,01 … 20 мА */
    sum = c / i + P.amax * i / (i + P.is);
    if (sum >= 1) continue;
    U = P.Ub * Math.pow(1 - sum, 1 / P.n);
    pts.push([U, i * 1000]);
    if (best === null || U > best[0]) best = [U, i * 1000];
  }
  return { pts: pts, top: best };
}

/* แกนกระแสแบบขยายย่านต่ำ: ต่ำกว่า 2 мА ขยาย ~200 เท่า (ผู้เรียบเรียง เพื่อให้เห็นกิ่งปิด) */
function eobThyY(ma) {
  var a = Math.abs(ma), v;
  if (a <= 2) v = 0.42 * a / 2;
  else v = 0.42 + 0.58 * (a - 2) / 398;
  return ma < 0 ? -v : v;
}

function eoThyristor(host) {
  buildDemo(host, {
    label: "Лекция 5 · сл. 10–11",
    title: "ВАХ ของทิริสเตอร์ — เพิ่มกระแสเกต I_у แล้วดูแรงดันพลิก U_вкл เลื่อนเข้าหาแกนจนคุมได้เต็มที่",
    ratio: 0.68,
    legend: '<span><i style="background:var(--accent-2)"></i>ВАХ ที่ I_у ปัจจุบัน</span>' +
      '<span><i style="background:var(--ink-3)"></i>ครอบครัวเส้นที่ I_у อื่น</span>' +
      '<span><i style="background:var(--ok)"></i>กิ่งเปิด · จุดทำงาน</span>' +
      '<span><i style="background:var(--crit)"></i>I_уд ток удержания</span>',
    controls: [
      { id: "Iu", label: "I<sub>у</sub>, мА — กระแสขั้วควบคุม (управляющий электрод)", min: 0, max: 60, step: 1, value: 0, fmt: function (v) { return eobF(v, 0); } },
      { id: "In", label: "I<sub>н</sub>, мА — กระแสแอโนดในวงจรจริง", min: 0, max: 400, step: 5, value: 200, fmt: function (v) { return eobF(v, 0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink = CV("--ink"), ink3 = CV("--ink-3"), crit = CV("--crit"), line2 = CV("--line-2");
      var fs = eobFS(w);
      var P = EOB_TH, Iu = s.Iu, In = s.In;

      var L = w < 430 ? 40 : 48;
      var p = new Plot(ctx, L, 10, w - L - 12, h - 40, -1300, 1300, -0.5, 1.02);
      p.frame(ticks(-1200, 1200, 4), [], "U_АК, В", null,false);

      /* แกน i_А ที่ทำเอง (ขยายย่านต่ำกว่า 2 мА) */
      var yl = [-2, -1, 0, 1, 2, 100, 200, 300, 400], q;
      ctx.save();
      ctx.font = eobFont(fs);
      ctx.textAlign = "right";
      ctx.textBaseline = "middle";
      for (q = 0; q < yl.length; q++) {
        var yy = Math.round(p.Y(eobThyY(yl[q]))) + 0.5;
        ctx.strokeStyle = yl[q] === 0 ? line2 : CV("--grid");
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(p.x, yy);
        ctx.lineTo(p.x + p.w, yy);
        ctx.stroke();
        ctx.fillStyle = ink3;
        ctx.fillText(String(yl[q]), p.x - 6, yy);
      }
      ctx.restore();
      eobVLine(ctx, p, 0, line2, [2, 3], 1);

      /* ครอบครัวเส้นของกระแสเกตต่าง ๆ */
      var fam = [0, 10, 20, 30, 40], j, br, cur = null;
      p.clip(function () {
        for (j = 0; j < fam.length; j++) {
          br = eobThyBranch(fam[j]);
          if (!br.pts.length) continue;
          var seg = [], z;
          for (z = 0; z < br.pts.length; z++) seg.push([br.pts[z][0], eobThyY(br.pts[z][1])]);
          p.line(seg, ink3, 1.2, [3, 3]);
        }
        br = eobThyBranch(Iu);
        cur = br;
        if (br.pts.length) {
          var seg2 = [], z2;
          for (z2 = 0; z2 < br.pts.length; z2++) seg2.push([br.pts[z2][0], eobThyY(br.pts[z2][1])]);
          p.line(seg2, acc2, 2.4);
        }
        /* กิ่งเปิด (открыт) */
        var on = [], im;
        for (im = P.Iud; im <= 400; im += 5) on.push([P.Uto + P.rd * im, eobThyY(im)]);
        p.line(on, ok, 2.6);
        /* ส่วนความต้านทานลบ (ไม่เสถียร) — เส้นประเชื่อมจุดพลิกกับกิ่งเปิด */
        if (br.top) {
          var uns = [], z3, ii, uu;
          for (z3 = 0; z3 <= 40; z3++) {
            ii = br.top[1] + (P.Iud - br.top[1]) * z3 / 40;
            uu = (P.Uto + P.rd * P.Iud) + (br.top[0] - (P.Uto + P.rd * P.Iud)) * Math.pow((P.Iud - ii) / (P.Iud - br.top[1]), 0.55);
            uns.push([uu, eobThyY(ii)]);
          }
          p.line(uns, acc2, 1.4, [5, 4]);
        }
        /* กิ่งย้อนกลับ */
        var rev = [[0, eobThyY(-0.05)], [-600, eobThyY(-0.1)], [-1100, eobThyY(-0.18)], [-1200, eobThyY(-0.6)], [-1250, eobThyY(-2)]];
        p.line(rev, acc, 2);
      });

      /* เส้น I_уд และจุดทำงาน */
      eobRef(ctx, p, eobThyY(P.Iud), crit, "I_уд = " + P.Iud + " мА", fs, [4, 4]);
      if (In > 0) {
        var Uw = P.Uto + P.rd * In;
        p.dots([[Uw, eobThyY(In)]], ok, 5);
      }
      if (cur && cur.top) {
        p.dots([[cur.top[0], eobThyY(cur.top[1])]], crit, 4.5);
        ctx.save();
        ctx.font = eobFont(fs);
        ctx.fillStyle = crit;
        ctx.textAlign = "right";
        ctx.textBaseline = "bottom";
        ctx.fillText("U_вкл", p.X(cur.top[0]) - 5, p.Y(eobThyY(cur.top[1])) - 3);
        ctx.restore();
      }
      ctx.save();
      ctx.font = eobFont(fs);
      ctx.fillStyle = ink3;
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      ctx.fillText("закрыт (обратное)", p.X(-650), p.y + 4);
      ctx.fillText("закрыт", p.X(650), p.y + 4);
      ctx.fillStyle = ok;
      ctx.textAlign = "left";
      ctx.fillText("открыт", p.X(40), p.y + p.h * 0.45);
      ctx.restore();

      var Uvkl = cur && cur.top ? cur.top[0] : 0;
      var fullCtl = !cur || !cur.top || Uvkl < 20;
      readout.innerHTML =
        'I<sub>у</sub> = <b>' + eobF(Iu, 0) + ' мА</b> ⇒ U<sub>вкл</sub> = <b class="' + (fullCtl ? "good" : "bad") + '">' + (fullCtl ? "≈ 0 В — เปิดที่แรงดันใด ๆ" : eobF(Uvkl, 0) + " В") + '</b>' +
        '<span>ยิ่ง I<sub>у</sub> โต จุดพลิกยิ่งต่ำ — นี่คือครอบครัวเส้น 1…8 บนกราฟล่างของ сл. 10</span>' +
        '<span>I<sub>уд</sub> (ток удержания) = <b>' + P.Iud + ' мА</b> · กระแสแอโนดปัจจุบัน I<sub>н</sub> = <b>' + eobF(In, 0) + ' мА</b> ⇒ <b class="' + (In >= P.Iud ? "good" : "bad") + '">' + (In >= P.Iud ? "ยังเปิดค้างอยู่" : "กระแสต่ำกว่า I_уд ⇒ ทิริสเตอร์ปิดเอง") + '</b></span>' +
        '<span>แรงดันตกตอนเปิด U<sub>пр</sub> = U<sub>ТО</sub> + r<sub>д</sub>·I = <b>' + eobF(P.Uto + P.rd * In, 2) + ' В</b> · U<sub>обр.повт</sub> ของคลาส 12 ≈ <b>1200 В</b> (Т142-80-12)</span>' +
        '<span>ทิริสเตอร์เปิดด้วยพัลส์ที่เกตแต่ปิดเองไม่ได้ — ปิดเมื่อกระแสแอโนดตกต่ำกว่า I_уд (естественная коммутация ตอนครึ่งคลื่นหมด)</span>' +
        '<span>ผู้เรียบเรียง: เส้นโค้งคำนวณจากแบบจำลองสองทรานซิสเตอร์ของ сл. 11 · แกน i_А ขยาย 200 เท่าในย่านต่ำกว่า 2 мА เพื่อให้เห็นกิ่งปิด</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   9. eoThyrRect — วงจรควบคุม: α → รูปคลื่นและ U_d(α) สำหรับโหลดตัวต้านทาน
   Л5 сл. 11 (นิยาม α วัดจาก точка естественного отпирания) · сл. 15–16 (ไดอะแกรม)
   Л5 сл. 20 (สูตรหลัก):
     6Т :  U_0α = (3√2/π)·U_вх.лин·cos α ,                 0 ≤ α ≤ π/3
           U_0α = (3√2/π)·U_вх.лин·[1 + cos(π/3 + α)] ,     π/3 < α < 2π/3
     3Д3Т: U_0α = (3√2/π)·U_вх.лин·(1 + cos α)/2 ,          0 … π
   รูปคลื่นสร้างจากลำดับการจุดชนวนจริง: ช่วงที่ k เริ่มตามธรรมชาติที่ 30° + 60°k
   (สำหรับ 6Т) และ 30° + 120°j (สำหรับ 3Д3Т) เลื่อนไปด้วย α · โหลดตัวต้านทาน ⇒ ตัดที่ศูนย์
--------------------------------------------------------------------------- */
var EOB_K135 = 3 * Math.SQRT2 / Math.PI;   /* = 1,35047 (Л5 сл. 20) */

function eoThyrU0(alphaDeg, Ul, six) {
  var a = alphaDeg * Math.PI / 180;
  if (six) {
    if (alphaDeg <= 60) return EOB_K135 * Ul * Math.cos(a);
    if (alphaDeg < 120) return EOB_K135 * Ul * (1 + Math.cos(Math.PI / 3 + a));
    return 0;
  }
  if (alphaDeg >= 180) return 0;
  return EOB_K135 * Ul * (1 + Math.cos(a)) / 2;
}

/* u_вых ขณะหนึ่ง (หน่วย В) ที่มุม deg สำหรับมุมควบคุม al */
function eobThyWave(deg, al, six, Ul) {
  var Uml = Math.SQRT2 * Ul, Umf = Uml / Math.sqrt(3), v, k, j, p, val;
  if (six) {
    k = Math.floor((deg - 30 - al) / 60);
    val = Uml * Math.sin((deg - 60 * k + 30) * Math.PI / 180);
    return val > 0 ? val : 0;
  }
  j = Math.floor((deg - 30 - al) / 120);
  p = ((j % 3) + 3) % 3;
  v = eobPh(deg * Math.PI / 180);
  val = Umf * (v[p] - eobMin3(v));
  return val > 0 ? val : 0;
}

function eoThyrRect(host) {
  buildDemo(host, {
    label: "Лекция 5 · сл. 15–17, 20–21",
    title: "เลื่อนมุมควบคุม α — ดูรูปคลื่นถูกตัดเป็นฟันเลื่อยและ U_d(α) ลดลงตามสูตรของสไลด์ 20",
    ratio: 0.72,
    legend: '<span><i style="background:var(--accent)"></i>แรงดันเฟส</span>' +
      '<span><i style="background:var(--accent-2)"></i>u_вых ที่มุม α</span>' +
      '<span><i style="background:var(--ink-3)"></i>u_вых ที่ α = 0 (เส้นประ)</span>' +
      '<span><i style="background:var(--crit)"></i>จุดจุดชนวน</span>',
    controls: [
      { id: "al", label: "α, град — มุมควบคุม (วัดจาก точка естественного отпирания)", min: 0, max: 180, step: 1, value: 30, fmt: function (v) { return eobF(v, 0); } },
      { id: "Ul", label: "U<sub>вх.лин</sub>, В — แรงดันคู่สาย (действующее)", min: 10, max: 400, step: 5, value: 220, fmt: function (v) { return eobF(v, 0); } }
    ],
    buttons: [
      { id: "six", label: "схема 6Т (ปิด = 3Д3Т)", toggle: true, value: true }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink3 = CV("--ink-3"), crit = CV("--crit"), wash = CV("--wash-2"), line2 = CV("--line-2");
      var fs = eobFS(w);
      var al = s.al, Ul = s.Ul, six = s.six !== false;
      var Uml = Math.SQRT2 * Ul, Umf = Uml / Math.sqrt(3);
      var alMax = six ? 120 : 180;
      var alEff = Math.min(al, 180);

      var N = 1080, k, deg, v, pa = [], pb = [], pc = [], wf = [], w0 = [], vals = [];
      for (k = 0; k <= N; k++) {
        deg = 720 * k / N;
        v = eobPh(deg * Math.PI / 180);
        pa.push([deg, Umf * v[0]]);
        pb.push([deg, Umf * v[1]]);
        pc.push([deg, Umf * v[2]]);
        var u = eobThyWave(deg, alEff, six, Ul);
        var un = eobThyWave(deg, 0, six, Ul);
        wf.push([deg, u]);
        w0.push([deg, un]);
        if (deg >= 360 && deg < 720) vals.push(u);
      }
      var st = eobStat(vals);
      var Uform = eoThyrU0(alEff, Ul, six);
      var Kp = st.m > 1e-6 ? eobKpA(st) : Infinity;
      var branch = six ? (al <= 60 ? "cos α" : (al < 120 ? "1 + cos(π/3 + α)" : "U_0α = 0")) : "(1 + cos α)/2";

      var g = eobPlots(w, h, 2, { gap: 20, bottom: 24 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, 720, -1.15 * Umf, 1.15 * Umf);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, 720, -0.06 * Uml, 1.12 * Uml);

      p1.frame([], eobTicksN(-Umf, Umf, 4), null, null,true);
      eobAxisDeg(ctx, p1, 120, false, fs);
      p1.clip(function () {
        p1.line(pa, acc, 1.7);
        p1.line(pb, acc, 1.3, [6, 4]);
        p1.line(pc, acc, 1.3, [2, 3]);
      });
      eobRef(ctx, p1, 0, line2, null, fs, [2, 3]);
      /* จุดสับเปลี่ยนตามธรรมชาติ และจุดจุดชนวนจริง */
      var stepDeg = six ? 60 : 120, d;
      for (d = 30; d <= 720; d += stepDeg) {
        eobVLine(ctx, p1, d, ink3, [2, 4], 1);
        if (d + alEff <= 720) eobVLine(ctx, p1, d + alEff, crit, null, 1.4);
      }
      eobTag(ctx, p1, "u_a · u_b · u_c, В — เส้นบาง = จุดธรรมชาติ · เส้นแดง = จุดจุดชนวน", acc, fs);

      p2.frame([], eobTicksN(0, Uml, 4), null, null,true);
      eobAxisDeg(ctx, p2, 120, true, fs);
      eobFill(ctx, p2, wf, wash);
      p2.clip(function () {
        p2.line(w0, ink3, 1.3, [4, 4]);
        p2.line(wf, acc2, 2.2);
      });
      eobRef(ctx, p2, Uform, ok, "U_0α = " + eobF(Uform, 1) + " В", fs);
      eobTag(ctx, p2, "u_вых, В · " + (six ? "6Т" : "3Д3Т") + " · α = " + eobF(al, 0) + "°", acc2, fs);

      readout.innerHTML =
        '<b>' + (six ? "Схема 6Т (шесть тиристоров)" : "Схема 3Д3Т (три диода + три тиристора)") + '</b> · α = <b>' + eobF(al, 0) + '°</b> = <b>' + eobF(al * Math.PI / 180, 3) + ' рад</b>' +
        '<span>สูตร сл. 20 สาขา <b>' + branch + '</b> ⇒ U<sub>0α</sub> = <b>' + eobF(Uform, 1) + ' В</b> = <b>' + eobF(Uform / Ul, 3) + '</b>·U_вх.лин</span>' +
        '<span>ค่าเฉลี่ยที่คำนวณจากรูปคลื่นเชิงตัวเลข = <b>' + eobF(st.m, 1) + ' В</b> ⇒ ' + (Math.abs(st.m - Uform) < 0.02 * Math.max(Uform, 1) + 0.5 ? '<b class="good">ตรงกับสูตร</b>' : '<b>ต่างกัน ' + eobF(st.m - Uform, 1) + ' В</b>') + '</span>' +
        '<span>ที่ α = 0 ได้ U₀ = <b>' + eobF(EOB_K135 * Ul, 1) + ' В</b> = 1,35·U_л ⇒ ทำงานเหมือนวงจรไม่ควบคุมทุกประการ (сл. 20 ข้อ 1)</span>' +
        '<span>K<sub>п</sub> = ΔU/(2U₀) = <b class="' + (Kp < 0.15 ? "good" : "bad") + '">' + (isFinite(Kp) ? eobFmtA(Kp) : "—") + '</b> — ยิ่ง α โต แรงดันยิ่งต่ำ <b>แต่ระลอกยิ่งแย่</b> จึงต้องมีฟิลเตอร์ตามหลังเสมอ</span>' +
        '<span>ช่วงปรับได้: 6Т ถึง <b>120°</b> · 3Д3Т ถึง <b>180°</b> · ขณะนี้ α_max ของสคีมนี้ = <b>' + alMax + '°</b>' + (al > alMax ? ' ⇒ <b class="bad">เลยช่วง U_0α = 0</b>' : '') + '</span>' +
        '<span>โหลดตัวต้านทาน: ที่ α &gt; 60° (6Т) กระแสขาดเป็นช่วง รูปคลื่นแยกเป็นพัลส์ — จึงต้องใช้สูตรสาขาที่สอง</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   10. eoThyrChar — คุณลักษณะปรับค่าและคุณลักษณะภายนอก Л5 сл. 19, 20, 21
   а) регулировочные (сл. 19 а): เส้น 1 = 6Т โหลดตัวต้านทาน · เส้น 2 = 6Т โหลดเหนี่ยวนำ
      (กระแสต่อเนื่อง U_0α = 1,35·U_л·cos α ถึง 90°) · เส้น 3 = 3Д3Т (ถึง 180°)
   б) внешние (сл. 19 б, в + сл. 22): กระแสโหลดโตขึ้น ⇒ มุมสับเปลี่ยน γ กว้างขึ้น ⇒ U ตก
      ผู้เรียบเรียงเขียนเป็นสมการมาตรฐานของสะพาน 6 พัลส์:
        ΔU_γ = (3/π)·X_к·I_d ,  cos α − cos(α + γ) = 2·X_к·I_d/(√2·U_л) ,  ΔU_VS = 1 В ต่อวาล์ว
--------------------------------------------------------------------------- */
function eoThyrChar(host) {
  buildDemo(host, {
    label: "Лекция 5 · сл. 19, 21, 22",
    title: "คุณลักษณะปรับค่า U_0α(α) สามเส้น และคุณลักษณะภายนอก U_d(I_н) ที่มุม α ต่าง ๆ",
    ratio: 0.66,
    legend: '<span><i style="background:var(--accent-2)"></i>6Т โหลดตัวต้านทาน (เส้น 1)</span>' +
      '<span><i style="background:var(--accent)"></i>6Т โหลดเหนี่ยวนำ (เส้น 2)</span>' +
      '<span><i style="background:var(--ink-3)"></i>3Д3Т (เส้น 3)</span>' +
      '<span><i style="background:var(--crit)"></i>จุดทำงาน</span>',
    controls: [
      { id: "al", label: "α, град — มุมควบคุม", min: 0, max: 180, step: 1, value: 30, fmt: function (v) { return eobF(v, 0); } },
      { id: "Ul", label: "U<sub>вх.лин</sub>, В — แรงดันคู่สาย (действующее)", min: 10, max: 400, step: 5, value: 220, fmt: function (v) { return eobF(v, 0); } },
      { id: "In", label: "I<sub>н</sub>, А — กระแสโหลด", min: 0, max: 40, step: 0.5, value: 10, fmt: function (v) { return eobF(v, 1); } },
      { id: "Xk", label: "X<sub>к</sub>, Ом — รีแอกแตนซ์การสับเปลี่ยน (индуктивность рассеяния)", min: 0, max: 1.5, step: 0.05, value: 0.15, fmt: function (v) { return eobF(v, 2); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink3 = CV("--ink-3"), crit = CV("--crit"), line2 = CV("--line-2");
      var fs = eobFS(w);
      var al = s.al, Ul = s.Ul, In = s.In, Xk = s.Xk;
      var U00 = EOB_K135 * Ul;

      var c1 = [], c2 = [], c3 = [], a;
      for (a = 0; a <= 180; a += 1) {
        c1.push([a, eoThyrU0(a, Ul, true)]);
        c2.push([a, a <= 90 ? U00 * Math.cos(a * Math.PI / 180) : 0]);
        c3.push([a, eoThyrU0(a, Ul, false)]);
      }

      /* คุณลักษณะภายนอก (6Т โหลดตัวต้านทาน) */
      function Ud(alpha, I) {
        var u = eoThyrU0(alpha, Ul, true) - (3 / Math.PI) * Xk * I - 2;
        return u > 0 ? u : 0;
      }
      function gamma(alpha, I) {
        var ar = alpha * Math.PI / 180;
        var x = Math.cos(ar) - 2 * Xk * I / (Math.SQRT2 * Ul);
        if (x < -1) x = -1;
        if (x > 1) x = 1;
        return (Math.acos(x) - ar) * 180 / Math.PI;
      }
      var Imax = 40, e1 = [], e2 = [], e3 = [], I;
      for (I = 0; I <= Imax; I += 0.5) {
        e1.push([I, Ud(al, I)]);
        e2.push([I, Ud(0, I)]);
        e3.push([I, Ud(60, I)]);
      }

      var wide = w >= 560, L = w < 430 ? 40 : 46, gA, gB;
      if (wide) {
        var cw = (w - L - 20 - L) / 2;
        gA = { x: L, y: 10, w: cw, h: h - 44 };
        gB = { x: L + cw + 20 + L - 10, y: 10, w: cw, h: h - 44 };
      } else {
        var hh = (h - 20 - 56) / 2;
        gA = { x: L, y: 8, w: w - L - 12, h: hh };
        gB = { x: L, y: 8 + hh + 34, w: w - L - 12, h: hh };
      }

      var pA = new Plot(ctx, gA.x, gA.y, gA.w, gA.h, 0, 180, 0, U00 * 1.08);
      pA.frame(ticks(0, 180, 6), eobTicksN(0, U00, 4), "α, град", null,false);
      pA.clip(function () {
        pA.line(c3, ink3, 1.8, [5, 4]);
        pA.line(c2, acc, 1.8);
        pA.line(c1, acc2, 2.4);
        pA.dots([[al, eoThyrU0(al, Ul, true)]], crit, 4.5);
      });
      eobVLine(ctx, pA, 60, line2, [3, 4], 1);
      eobVLine(ctx, pA, 120, line2, [3, 4], 1);
      eobTag(ctx, pA, "U_0α, В — регулировочные", acc2, fs);

      var pB = new Plot(ctx, gB.x, gB.y, gB.w, gB.h, 0, Imax, 0, U00 * 1.08);
      pB.frame(ticks(0, Imax, 4), eobTicksN(0, U00, 4), "I_н, А", null,false);
      pB.clip(function () {
        pB.line(e2, ink3, 1.5, [4, 4]);
        pB.line(e3, ink3, 1.5, [2, 3]);
        pB.line(e1, acc2, 2.4);
        pB.dots([[In, Ud(al, In)]], crit, 4.5);
      });
      eobTag(ctx, pB, "U_d, В — внешние (α = 0 · 60° · ปัจจุบัน)", acc2, fs);

      var g0 = gamma(al, In), dUg = (3 / Math.PI) * Xk * In;
      readout.innerHTML =
        'α = <b>' + eobF(al, 0) + '°</b> · U<sub>0α</sub>: 6Т โหลดตัวต้านทาน = <b>' + eobF(eoThyrU0(al, Ul, true), 1) + ' В</b>' +
        '<span>6Т โหลดเหนี่ยวนำ = <b>' + eobF(al <= 90 ? U00 * Math.cos(al * Math.PI / 180) : 0, 1) + ' В</b> · 3Д3Т = <b>' + eobF(eoThyrU0(al, Ul, false), 1) + ' В</b></span>' +
        '<span>โหลดเหนี่ยวนำแตะศูนย์ที่ <b>90°</b> · 6Т โหลดตัวต้านทานที่ <b>120°</b> · 3Д3Т ที่ <b>180°</b> ⇒ 3Д3Т ปรับได้ช่วงกว้างที่สุด</span>' +
        '<span>มุมสับเปลี่ยน γ = <b class="' + (g0 > 20 ? "bad" : "good") + '">' + eobF(g0, 1) + '°</b> ที่ I_н = ' + eobF(In, 1) + ' А ⇒ แรงดันตกจากการสับเปลี่ยน ΔU<sub>γ</sub> = (3/π)·X_к·I_d = <b>' + eobF(dUg, 1) + ' В</b></span>' +
        '<span>U<sub>d</sub> ที่จุดทำงาน = <b>' + eobF(Ud(al, In), 1) + ' В</b> (หักแรงดันตกบนวาล์ว 2 × 1 В แล้ว)</span>' +
        '<span>กระแสโหลดโตขึ้น ⇒ γ กว้างขึ้น ⇒ แรงดันตก — นี่คือ «дополнительные потери» ของ сл. 22 และคือที่มาของกราฟ в) บน сл. 19</span>' +
        '<span>ถ้าต้องการรักษา U_вых คงที่เมื่อ I_н โต ต้อง <b>ลด α ลง</b> (กราฟ б) сл. 19) — นี่คือหลักการของวงจรป้อนกลับบน сл. 13</span>' +
        '<span>ผู้เรียบเรียง: สูตร ΔU_γ และ γ ไม่ได้พิมพ์บนสไลด์ ทีมเรียบเรียงเขียนจากกลไกที่ сл. 22 อธิบายไว้</span>';
    }
  });
}

/* ---------------------------------------------------------------------------
   11. eoSIFU — СИФУ: แรงดันซิงโครไนซ์ + ฟันเลื่อย + ระดับควบคุม → พัลส์จุดชนวน 3 ช่อง
   Л5 сл. 13 (โครงสร้าง СУВ: ДН → СУ → U_х → ФСУ1…3) · сл. 14 (โซ่ НО → ГЛИН → К → ДЧ)
   สูตรหลัก сл. 14:  α = ω·t_з  · จุดตัดของฟันเลื่อยกับ U_х เป็นตัวกำหนด t_з
   ⇒ t_з/T_ю = U_х/U_Гm  และ  α = 180°·U_х/U_Гm  (ผู้เรียบเรียงเขียนจากไดอะแกรมของสไลด์)
   Л5 сл. 11: α วัดจาก точка естественного отпирания — ในวงจรสามเฟสอยู่หลังจุดข้ามศูนย์ 30°
   Л5 сл. 15: ลำดับช่อง u_у1 → u_у3 → u_у5 ห่างกัน 120° (สคีม 3Д3Т) · Л18 сл. 19 ใช้ผังเดียวกัน
--------------------------------------------------------------------------- */
function eoSIFU(host) {
  buildDemo(host, {
    label: "Лекция 5 · сл. 13–14  ·  Лекция 18 · сл. 19",
    title: "СИФУ ทำงานจริง — เลื่อนระดับควบคุม U_х แล้วดูจุดตัดฟันเลื่อยเลื่อน พัลส์ 3 ช่องขยับ แรงดันออกเปลี่ยน",
    ratio: 0.95,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>u_синх · ฟันเลื่อยช่อง 1</span>' +
      '<span><i style="background:var(--accent-2)"></i>u_вых</span>' +
      '<span><i style="background:var(--ok)"></i>ระดับควบคุม U_х</span>' +
      '<span><i style="background:var(--crit)"></i>พัลส์จุดชนวน · เวลาปัจจุบัน</span>',
    controls: [
      { id: "Ux", label: "U<sub>х</sub>, В — สัญญาณควบคุมจากตัวเปรียบเทียบ (U_Гm = 10 В)", min: 0, max: 10, step: 0.1, value: 3.3, fmt: function (v) { return eobF(v, 1); } },
      { id: "fc", label: "f<sub>c</sub>, Гц — ความถี่แหล่งจ่าย", min: 50, max: 400, step: 10, value: 400, fmt: function (v) { return eobF(v, 0); } },
      { id: "Ul", label: "U<sub>вх.лин</sub>, В — แรงดันคู่สาย (действующее)", min: 10, max: 400, step: 5, value: 220, fmt: function (v) { return eobF(v, 0); } }
    ],
    draw: function (ctx, w, h, s, readout, t) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"),
        ink3 = CV("--ink-3"), crit = CV("--crit"), wash = CV("--wash-2"), line2 = CV("--line-2");
      var fs = eobFS(w);
      var UGm = 10, Ux = s.Ux, f = s.fc, Ul = s.Ul;
      var al = 180 * Ux / UGm;
      var tz = al / (360 * f);
      var Uml = Math.SQRT2 * Ul, Umf = Uml / Math.sqrt(3);
      var cur = ((t || 0) * 90) % 720;

      var N = 720, k, deg, v, i;
      var pa = [], pb = [], pc = [], wf = [], vals = [];
      var saw = [[], [], []];
      for (k = 0; k <= N; k++) {
        deg = 720 * k / N;
        v = eobPh(deg * Math.PI / 180);
        pa.push([deg, v[0]]);
        pb.push([deg, v[1]]);
        pc.push([deg, v[2]]);
        for (i = 0; i < 3; i++) {
          var st0 = 30 + 120 * i;
          var dd = ((deg - st0) % 360 + 360) % 360;
          saw[i].push([deg, dd <= 180 ? UGm * dd / 180 : 0]);
        }
        var u = eobThyWave(deg, al, false, Ul);
        wf.push([deg, u]);
        if (deg >= 360 && deg < 720) vals.push(u);
      }
      var st = eobStat(vals);
      var Uform = eoThyrU0(al, Ul, false);

      var g = eobPlots(w, h, 4, { gap: 14, bottom: 22 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, 720, -1.15, 1.15);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, 720, -0.5, UGm * 1.1);
      var p3 = new Plot(ctx, g[2].x, g[2].y, g[2].w, g[2].h, 0, 720, -0.2, 3.4);
      var p4 = new Plot(ctx, g[3].x, g[3].y, g[3].w, g[3].h, 0, 720, -0.05 * Uml, 1.12 * Uml);

      /* 1 — แรงดันซิงโครไนซ์ + จุดสับเปลี่ยนตามธรรมชาติ */
      p1.frame([], [-1, 0, 1], null, null,true);
      eobAxisDeg(ctx, p1, 120, false, fs);
      p1.clip(function () {
        p1.line(pa, acc, 1.8);
        p1.line(pb, acc, 1.2, [6, 4]);
        p1.line(pc, acc, 1.2, [2, 3]);
      });
      var d, ci;
      for (i = 0; i < 3; i++) {
        for (d = 30 + 120 * i; d <= 720; d += 360) {
          p1.dots([[d, eobPh(d * Math.PI / 180)[i]]], ink3, 3);
          eobVLine(ctx, p1, d, ink3, [2, 4], 1);
        }
      }
      eobTag(ctx, p1, "u_синх1…3 (о.е.) · จุด = точки естественного отпирания", acc, fs);

      /* 2 — ฟันเลื่อยจาก ГЛИН + ระดับ U_х */
      p2.frame([], eobTicksN(0, UGm, 2), null, null,true);
      eobAxisDeg(ctx, p2, 120, false, fs);
      p2.clip(function () {
        p2.line(saw[1], ink3, 1.2, [3, 3]);
        p2.line(saw[2], ink3, 1.2, [3, 3]);
        p2.line(saw[0], acc, 2);
      });
      eobRef(ctx, p2, Ux, ok, "U_х = " + eobF(Ux, 1) + " В", fs);
      eobTag(ctx, p2, "u_Г ฟันเลื่อยจาก ГЛИН, В · จุดตัดกับ U_х ให้ t_з", acc, fs);
      for (i = 0; i < 3; i++) {
        for (d = 30 + 120 * i + al; d <= 720; d += 360) {
          p2.dots([[d, Ux]], crit, 3.4);
        }
      }

      /* 3 — พัลส์จุดชนวนสามช่อง */
      p3.frame([], [], null, null,true);
      eobAxisDeg(ctx, p3, 120, false, fs);
      ctx.save();
      ctx.font = eobFont(fs);
      ctx.textAlign = "left";
      ctx.textBaseline = "middle";
      var nm = ["u_у5", "u_у3", "u_у1"];   /* base โตขึ้น = สูงขึ้น จึงกลับลำดับให้ u_у1 อยู่บนสุด */
      for (i = 0; i < 3; i++) {
        var base = 0.25 + i * 1.0;
        ctx.strokeStyle = line2;
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(p3.x, Math.round(p3.Y(base)) + 0.5);
        ctx.lineTo(p3.x + p3.w, Math.round(p3.Y(base)) + 0.5);
        ctx.stroke();
        ctx.fillStyle = ink3;
        ctx.fillText(nm[i], p3.x + 3, p3.Y(base + 0.55));
        for (d = 30 + 120 * (2 - i) + al; d <= 720; d += 360) {
          var hot = (cur - d + 720) % 720 < 40;
          ctx.strokeStyle = hot ? crit : acc2;
          ctx.lineWidth = hot ? 3 : 2;
          ctx.beginPath();
          ctx.moveTo(p3.X(d), p3.Y(base));
          ctx.lineTo(p3.X(d), p3.Y(base + 0.75));
          ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(p3.X(d), p3.Y(base + 0.75));
          ctx.lineTo(p3.X(d + 14), p3.Y(base));
          ctx.stroke();
        }
      }
      ctx.restore();
      eobTag(ctx, p3, "พัลส์ที่ขั้วเกต — ห่างกัน 120° · เลื่อนไปพร้อมกันด้วย α", acc2, fs, true);

      /* 4 — แรงดันออกของสคีม 3Д3Т */
      p4.frame([], eobTicksN(0, Uml, 3), null, null,true);
      eobAxisDeg(ctx, p4, 120, true, fs);
      var shown = [];
      for (k = 0; k < wf.length; k++) if (wf[k][0] <= cur) shown.push(wf[k]);
      if (shown.length > 1) eobFill(ctx, p4, shown, wash);
      p4.clip(function () {
        p4.line(wf, ink3, 1.2, [3, 3]);
        if (shown.length > 1) p4.line(shown, acc2, 2.2);
      });
      eobRef(ctx, p4, Uform, ok, "U_0α = " + eobF(Uform, 1) + " В", fs);
      eobTag(ctx, p4, "u_вых ของสคีม 3Д3Т, В", acc2, fs);

      /* เส้นเวลาปัจจุบัน */
      eobVLine(ctx, p1, cur, crit, null, 1.6);
      eobVLine(ctx, p2, cur, crit, null, 1.6);
      eobVLine(ctx, p3, cur, crit, null, 1.6);
      eobVLine(ctx, p4, cur, crit, null, 1.6);

      readout.innerHTML =
        'U<sub>х</sub> = <b>' + eobF(Ux, 1) + ' В</b> จาก U<sub>Гm</sub> = 10 В ⇒ t<sub>з</sub>/T<sub>ю</sub> = <b>' + eobF(Ux / UGm, 2) + '</b>' +
        '<span>α = ω·t<sub>з</sub> = <b>' + eobF(al, 0) + '°</b> = <b>' + eobF(al * Math.PI / 180, 3) + ' рад</b> · t<sub>з</sub> = <b>' + eobF(tz * 1e6, 0) + ' мкс</b> ที่ f_c = ' + eobF(f, 0) + ' Гц</span>' +
        '<span>U<sub>0α</sub> ของ 3Д3Т = 1,35·U_л·(1 + cos α)/2 = <b>' + eobF(Uform, 1) + ' В</b> · ค่าเฉลี่ยจากรูปคลื่น = <b class="' +
          (Math.abs(st.m - Uform) <= Math.max(0.02 * Math.abs(Uform), 0.5) ? "good" : "bad") + '">' + eobF(st.m, 1) + ' В</b> (สูตรกับรูปคลื่นต้องตรงกัน)</span>' +
        '<span>สามช่องห่างกัน <b>120°</b> ⇒ m = 3 · f<sub>п</sub> = 3·f_c = <b>' + eobF(3 * f, 0) + ' Гц</b></span>' +
        '<span>สายโซ่ควบคุม: U<sub>ОП</sub> → СУ → U<sub>х</sub> → จุดตัดฟันเลื่อย → t<sub>з</sub> → α → U<sub>вых</sub> แล้ววนกลับผ่าน ДН</span>' +
        '<span>จุดที่สับสนบ่อยที่สุด: α ไม่ได้วัดจากจุดที่แรงดันข้ามศูนย์ แต่วัดจาก <b>точка естественного отпирания</b> ซึ่งอยู่หลังจุดข้ามศูนย์ 30° (จุดวงกลมในแผงบนสุด)</span>';
    }
  });
}

/* ================= ลงทะเบียนเดโมของกลุ่ม B (11 ตัว) ================= */
window.EODEMOS = Object.assign(window.EODEMOS || {}, {
  eoRect1: eoRect1,
  eoRectCompare: eoRectCompare,
  eoRectRipple: eoRectRipple,
  eoRect3: eoRect3,
  eoRectFault: eoRectFault,
  eoFilterC: eoFilterC,
  eoFilterL: eoFilterL,
  eoThyristor: eoThyristor,
  eoThyrRect: eoThyrRect,
  eoThyrChar: eoThyrChar,
  eoSIFU: eoSIFU
});

/* ================= ЭОЛА — กลุ่ม C · Тема 3 «Инверторы и конверторы» =================
   แหล่งสูตรทั้งหมด: notes/L06.md, notes/L07.md, notes/L08.md (หัวข้อ «Формулы», «Числовые данные»)

   กับดักหลักของหัวข้อนี้ที่เดโมชุดนี้ต้องแสดงให้ชัด:
     · อินเวอร์เตอร์  (Л6 сл. 17 · Л7 сл. 12–13):  q = 2·t_и/T   →  U₂ = U_m2·√q   (ค่าประสิทธิผล ∝ √q)
     · คอนเวอร์เตอร์  (Л8 сл. 12, 14):             q =   t_и/T   →  U_ВЫХ = q·U_ВХ (ค่าเฉลี่ย ∝ q)
   ตัวอักษรเดียวกัน นิยามคนละอย่าง — eoInvBridge และ eoConvBuck จึงพิมพ์นิยามของตัวเองใน readout ทุกครั้ง
   ================================================================================= */

/* ---------- เครื่องมือร่วมของกลุ่ม C (ไม่ได้ส่งออกเป็นเดโม) ---------- */


/* ---- ป้ายค่าบนแกนแบบเลขกลม (แทนการส่ง min/max ดิบเข้า ticks) ---- */
function eocNiceStep(span, n) {
  var raw = Math.abs(span) / Math.max(1, n);
  if (!(raw > 0) || !isFinite(raw)) return 1;
  var e = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), f = raw / e;
  return (f < 1.5 ? 1 : f < 3.5 ? 2 : f < 7.5 ? 5 : 10) * e;
}
function eocTicksN(a, b, n) {
  if (!isFinite(a) || !isFinite(b) || b <= a) return [a, b];
  /* เอนจินพิมพ์ป้ายด้วย toFixed(2) — ก้าวต่ำกว่า 0,01 จะได้ป้ายซ้ำ จึงยกพื้นไว้ */
  var st = Math.max(eocNiceStep(b - a, n), 0.01), out = [], seen = {}, lab,
    k = Math.ceil((a - st * 1e-6) / st), guard = 0, v;
  for (; k * st <= b + st * 1e-6 && guard < 400; k++, guard++) {
    v = +(k * st).toPrecision(12);
    lab = String(+v.toFixed(2));
    if (seen[lab]) continue;
    seen[lab] = 1; out.push(v);
  }
  return out.length >= 2 ? out : [a, b];
}

function eocFS(w) { return w < 430 ? 9 : 10; }
function eocFont(w, bold) { return (bold ? "bold " : "") + eocFS(w) + 'px "IBM Plex Mono", monospace'; }
function eocN(v, d) {
  return (isFinite(v) ? v : 0).toFixed(d === undefined ? 2 : d).replace(".", ",").replace(/^-/, "−");
}

function eocTxt(ctx, str, x, y, color, font, align, base) {
  ctx.save();
  ctx.fillStyle = color; ctx.font = font;
  ctx.textAlign = align || "left"; ctx.textBaseline = base || "middle";
  ctx.fillText(str, x, y);
  ctx.restore();
}

/* วาดรูปคลื่นหนึ่งแถว: fn(u) โดย u = เวลาในหน่วย «คาบ» ตั้งแต่ 0 ถึง nper */
function eocW(ctx, x, y, wd, ht, nper, fn, vmin, vmax, color, lw, dash) {
  const N = 1100;
  ctx.save(); ctx.beginPath();
  if (dash) ctx.setLineDash(dash);
  ctx.strokeStyle = color; ctx.lineWidth = lw || 1.6; ctx.lineJoin = "round";
  for (let i = 0; i <= N; i++) {
    const u = i / N * nper, v = fn(u);
    const px = x + i / N * wd;
    const py = y + ht - (Math.max(vmin, Math.min(vmax, v)) - vmin) / (vmax - vmin) * ht;
    i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
  }
  ctx.stroke(); ctx.restore();
}

/* เส้นระดับอ้างอิงในแถว (เช่นเส้นศูนย์) */
function eocLev(ctx, x, y, wd, ht, v, vmin, vmax, color, dash) {
  const py = Math.round(y + ht - (v - vmin) / (vmax - vmin) * ht) + 0.5;
  ctx.save(); ctx.beginPath();
  if (dash) ctx.setLineDash(dash);
  ctx.strokeStyle = color; ctx.lineWidth = 1;
  ctx.moveTo(x, py); ctx.lineTo(x + wd, py); ctx.stroke(); ctx.restore();
  return py;
}

/* แบ่งพื้นที่แนวตั้งเป็น n แถวเท่า ๆ กัน */
function eocRows(y0, hTot, n, gap) {
  const g = gap === undefined ? 6 : gap;
  const rh = (hTot - g * (n - 1)) / n, ys = [];
  for (let i = 0; i < n; i++) ys.push(y0 + i * (rh + g));
  return { rh: rh, ys: ys };
}

/* เส้นแบ่งคาบแนวตั้ง */
function eocPeriods(ctx, x, y, wd, ht, nper, color) {
  ctx.save(); ctx.strokeStyle = color; ctx.lineWidth = 1; ctx.setLineDash([2, 3]);
  for (let k = 1; k <= nper; k++) {
    const px = Math.round(x + k / nper * wd) + 0.5;
    ctx.beginPath(); ctx.moveTo(px, y); ctx.lineTo(px, y + ht); ctx.stroke();
  }
  ctx.restore();
}

/* แถบสีเน้นช่วงเวลา (u1…u2 ในหน่วยคาบ) */
function eocSpan(ctx, x, y, wd, ht, nper, u1, u2, color, alpha) {
  ctx.save(); ctx.globalAlpha = alpha === undefined ? 0.16 : alpha; ctx.fillStyle = color;
  ctx.fillRect(x + u1 / nper * wd, y, (u2 - u1) / nper * wd, ht);
  ctx.restore();
}


/* =====================================================================
   1. eoInvSingle — Однотактный инвертор (Л6 сл. 16) และค่าประสิทธิผล
      U = √( (2/T)·∫₀^τ u²dt ) = U_m·√(2τ/T)   (Ф6.2, Л6 сл. 17)
      รูปคลื่น ОИ คำนวณจากสมการวงจร: ช่วง VT นำ  i_L → U_m/R แบบเอกซ์โพเนนเชียล
      ช่วง VT ปิด  ตัวเหนี่ยวนำคายพลังงานเข้าโหลด  u_вых = −i_L·R  (ЭДС самоиндукции)
      ค่าเริ่มต้น R_н = 10 Ом — **ค่าสมมติของผู้เรียบเรียง** (สไลด์ 16 ไม่ให้ตัวเลขใด ๆ)
   ===================================================================== */
function eoInvSingle(host) {
  buildDemo(host, {
    label: "Лекция 6 · сл. 16–17",
    title: "เทียบวงจรหนึ่งแทกต์กับสองแทกต์ แล้วดูว่าสูตร U = U_m·√(2τ/T) ใช้ได้เมื่อใด",
    ratio: 0.74,
    legend: '<span><i style="background:var(--accent)"></i>u_вых</span><span><i style="background:var(--accent-2)"></i>i_L</span><span><i style="background:var(--ink-3)"></i>u_у</span>',
    controls: [
      { id: "qs", label: "τ/T (ความกว้างพัลส์ต่อคาบ)", min: 0.05, max: 0.5, step: 0.01, value: 0.5, fmt: v => eocN(v, 2) },
      { id: "Um", label: "U_m ВЫХ, В", min: 5, max: 100, step: 1, value: 27 },
      { id: "f", label: "f, Гц", min: 200, max: 3000, step: 10, value: 400 },
      { id: "kL", label: "T_L/T (ค่าคงเวลา L/R ต่อคาบ)", min: 0.05, max: 2, step: 0.05, value: 0.5, fmt: v => eocN(v, 2) }
    ],
    buttons: [{ id: "pp", label: "двухтактная схема", toggle: true, value: false }],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"),
            grid = CV("--grid"), line2 = CV("--line-2");
      const fs = eocFS(w), font = eocFont(w);
      const T = 1 / s.f, tau = s.qs * T, R = 10, TL = Math.max(1e-9, s.kL * T);
      const Um = s.Um, Imax = Um / R, pp = !!s.pp;

      const a = Math.exp(-tau / TL), b = Math.exp(-(T - tau) / TL);
      const i0 = Imax * b * (1 - a) / (1 - a * b);
      const iOn = dt => Imax + (i0 - Imax) * Math.exp(-dt / TL);
      const iPk = iOn(tau);
      const iOff = dt => iPk * Math.exp(-dt / TL);

      function uOut(u) {
        const t = (u - Math.floor(u)) * T;
        if (!pp) return t < tau ? Um : -iOff(t - tau) * R;
        if (t < tau) return Um;
        if (t < T / 2) return 0;
        if (t < T / 2 + tau) return -Um;
        return 0;
      }
      function iLf(u) {
        const t = (u - Math.floor(u)) * T;
        if (!pp) return t < tau ? iOn(t) : iOff(t - tau);
        return uOut(u) / R;
      }
      const uy1 = u => { const t = (u - Math.floor(u)) * T; return t < tau ? 1 : 0; };
      const uy2 = u => { const t = (u - Math.floor(u)) * T; return (t >= T / 2 && t < T / 2 + tau) ? 1 : 0; };

      let sum = 0; const N = 2400;
      for (let i = 0; i < N; i++) { const v = uOut((i + 0.5) / N); sum += v * v; }
      const urms = Math.sqrt(sum / N);
      const uform = Um * Math.sqrt(2 * s.qs);

      const x0 = 48, wp = w - 60, nper = 2;
      const R3 = eocRows(12, h - 34, 3, 8), rh = R3.rh;
      const uMax = Math.max(Um, iPk * R) * 1.18, iMx = Math.max(iPk, Imax, 0.01) * 1.2;

      /* แถว 1 — สัญญาณควบคุม */
      eocPeriods(ctx, x0, R3.ys[0], wp, rh, nper, grid);
      eocLev(ctx, x0, R3.ys[0], wp, rh, 0, -0.15, 1.25, line2);
      eocW(ctx, x0, R3.ys[0], wp, rh, nper, uy1, -0.15, 1.25, ink3, 1.6);
      if (pp) eocW(ctx, x0, R3.ys[0], wp, rh, nper, uy2, -0.15, 1.25, acc2, 1.6, [4, 3]);
      eocTxt(ctx, pp ? "u_у1,2" : "u_у", x0 - 6, R3.ys[0] + rh / 2, ink3, font, "right");

      /* แถว 2 — แรงดันขาออก */
      eocPeriods(ctx, x0, R3.ys[1], wp, rh, nper, grid);
      eocLev(ctx, x0, R3.ys[1], wp, rh, 0, -uMax, uMax, line2);
      eocW(ctx, x0, R3.ys[1], wp, rh, nper, uOut, -uMax, uMax, acc, 2);
      eocTxt(ctx, "u_вых", x0 - 6, R3.ys[1] + rh / 2, ink3, font, "right");
      eocTxt(ctx, eocN(Um, 0) + " В", x0 + 3, R3.ys[1] + 7, ink3, font, "left");

      /* แถว 3 — กระแสในตัวเหนี่ยวนำ/โหลด */
      eocPeriods(ctx, x0, R3.ys[2], wp, rh, nper, grid);
      eocLev(ctx, x0, R3.ys[2], wp, rh, 0, -iMx, iMx, line2);
      eocW(ctx, x0, R3.ys[2], wp, rh, nper, iLf, -iMx, iMx, acc2, 2);
      eocTxt(ctx, pp ? "i_н" : "i_L", x0 - 6, R3.ys[2] + rh / 2, ink3, font, "right");
      eocTxt(ctx, "t", x0 + wp, h - 12, ink3, font, "right");
      eocTxt(ctx, "T = " + eocN(T * 1000, 2) + " мс", x0, h - 12, ink3, font, "left");

      const good = Math.abs(urms - uform) / Math.max(uform, 1e-9) < 0.02;
      readout.innerHTML =
        'U (числ.) = <b>' + eocN(urms, 1) + ' В</b>' +
        '<span>U<sub>m</sub>·√(2τ/T) = <b class="' + (good ? "good" : "bad") + '">' + eocN(uform, 1) + ' В</b></span>' +
        '<span>2τ/T = <b>' + eocN(2 * s.qs, 2) + '</b></span>' +
        '<span>' + (pp
          ? 'รูปคลื่นสมมาตรสองขั้ว — สูตร (6.2) ให้ค่าตรงกับการอินทิเกรตเชิงตัวเลข'
          : 'ครึ่งลบเป็นหางเอกซ์โพเนนเชียล ไม่ใช่สี่เหลี่ยม — สูตร (6.2) ยังใช้ไม่ได้') + '</span>';
    }
  });
}


/* =====================================================================
   2. eoInvPP — Двухтактный инвертор с нулевой точкой (Л6 сл. 17, 19 · Л7 сл. 23 в)
      สาระ: ทรานซิสเตอร์ที่ **ปิด** ในวงจรมีจุดกลางต้องทน  U_КЭ.закр ≈ 2·U_ВХ  (Ф-Л7 ข้อ 9)
      ในวงจรสะพานทนเพียง  U_ВХ  → เป็นเกณฑ์เลือกทรานซิสเตอร์
      สัมประสิทธิ์ความปลอดภัย 1,5 เป็น **ค่าสมมติของผู้เรียบเรียง** (สไลด์ไม่ระบุ)
   ===================================================================== */
function eoInvPP(host) {
  buildDemo(host, {
    label: "Лекция 6 · сл. 17, 19 · Л7 сл. 23",
    title: "ดูว่าคีย์ที่ปิดในวงจรมีจุดกลางรับแรงดัน 2·U_ВХ — และเทียบกับวงจรสะพาน",
    ratio: 0.66,
    legend: '<span><i style="background:var(--accent)"></i>i_К1</span><span><i style="background:var(--accent-2)"></i>i_К2</span><span><i style="background:var(--ok)"></i>I_ВХ</span><span><i style="background:var(--crit)"></i>u_КЭ1</span>',
    controls: [
      { id: "Uv", label: "U_ВХ, В", min: 12, max: 120, step: 1, value: 27 },
      { id: "n", label: "W₂/W₁", min: 0.1, max: 20, step: 0.1, value: 1.5, fmt: v => eocN(v, 1) },
      { id: "I2", label: "I₂, А", min: 0.2, max: 3, step: 0.1, value: 1, fmt: v => eocN(v, 1) },
      { id: "f", label: "f, Гц", min: 200, max: 900, step: 10, value: 400 }
    ],
    buttons: [{ id: "br", label: "мостовая схема", toggle: true, value: false }],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"), crit = CV("--crit"),
            ink3 = CV("--ink-3"), grid = CV("--grid"), line2 = CV("--line-2");
      const font = eocFont(w);
      const T = 1 / s.f, br = !!s.br;
      const Ip = s.I2 * s.n;                  /* กระแสโหลดที่แปลงมาฝั่งปฐมภูมิ I′₂ */
      const Uk = br ? s.Uv : 2 * s.Uv;        /* แรงดันบนคีย์ที่ปิด */
      const Um2 = s.n * s.Uv;                 /* แอมพลิจูดขาออก */

      /* i_К1, i_К2 — พัลส์ครึ่งคาบ ยอดไต่ขึ้นเล็กน้อยเพราะกระแสแม่เหล็ก (Л6 сл. 17 а, б) */
      const kmag = 0.18;
      const ik1 = u => { const p = u - Math.floor(u); return p < 0.5 ? Ip * (1 + kmag * (p / 0.5)) : 0; };
      const ik2 = u => { const p = u - Math.floor(u); return p >= 0.5 ? Ip * (1 + kmag * ((p - 0.5) / 0.5)) : 0; };
      const iin = u => ik1(u) + ik2(u);
      const uke = u => { const p = u - Math.floor(u); return p < 0.5 ? 0 : Uk; };

      const x0 = 44, wp = w - 56, nper = 2;
      const R2 = eocRows(12, h - 34, 2, 10), rh = R2.rh;
      const iMx = Ip * (1 + kmag) * 1.35, uMx = Uk * 1.25;

      eocPeriods(ctx, x0, R2.ys[0], wp, rh, nper, grid);
      eocLev(ctx, x0, R2.ys[0], wp, rh, 0, 0, iMx, line2);
      eocW(ctx, x0, R2.ys[0], wp, rh, nper, ik1, 0, iMx, acc, 1.8);
      eocW(ctx, x0, R2.ys[0], wp, rh, nper, ik2, 0, iMx, acc2, 1.8);
      eocW(ctx, x0, R2.ys[0], wp, rh, nper, iin, 0, iMx, ok, 2, [5, 3]);
      eocTxt(ctx, "i_К, А", x0 - 6, R2.ys[0] + rh / 2, ink3, font, "right");
      eocTxt(ctx, "I_ВХ ≈ " + eocN(Ip * (1 + kmag / 2), 2) + " А", x0 + 4, R2.ys[0] + 8, ok, font, "left");

      eocPeriods(ctx, x0, R2.ys[1], wp, rh, nper, grid);
      eocLev(ctx, x0, R2.ys[1], wp, rh, 0, 0, uMx, line2);
      const yUv = eocLev(ctx, x0, R2.ys[1], wp, rh, s.Uv, 0, uMx, ink3, [3, 3]);
      eocW(ctx, x0, R2.ys[1], wp, rh, nper, uke, 0, uMx, crit, 2);
      eocTxt(ctx, "u_КЭ1", x0 - 6, R2.ys[1] + rh / 2, ink3, font, "right");
      eocTxt(ctx, "U_ВХ", x0 + wp - 2, yUv - 7, ink3, font, "right");
      eocTxt(ctx, (br ? "U_ВХ" : "2·U_ВХ") + " = " + eocN(Uk, 0) + " В",
        x0 + 4, R2.ys[1] + 8, crit, eocFont(w, true), "left");
      eocTxt(ctx, "t", x0 + wp, h - 12, ink3, font, "right");
      eocTxt(ctx, br ? "мостовая схема" : "схема с нулевой точкой", x0, h - 12, ink3, font, "left");

      const need = 1.5 * Uk;
      readout.innerHTML =
        'U<sub>КЭ.закр</sub> = <b class="' + (br ? "good" : "bad") + '">' + eocN(Uk, 0) + ' В</b>' +
        '<span>' + (br ? "≈ U_ВХ" : "≈ 2·U_ВХ") + '</span>' +
        '<span>U<sub>КЭ.доп</sub> ≥ 1,5·U<sub>КЭ.закр</sub> = <b>' + eocN(need, 0) + ' В</b></span>' +
        '<span>U<sub>m2</sub> = (W₂/W₁)·U<sub>ВХ</sub> = <b>' + eocN(Um2, 1) + ' В</b></span>' +
        '<span>I′₂ = <b>' + eocN(Ip, 2) + ' А</b> · I_ВХ เกือบคงที่ เพราะสองแทกต์ต่อกันพอดี</span>';
    }
  });
}


/* =====================================================================
   3. eoInvBridge — Мостовой инвертор (Л6 сл. 18 · Л7 сл. 12–13)
      q = 2·t_и/T                       (Л7 сл. 12)
      U₂ = √[(2/T)·∫₀^{t_и} u₂²dt] = U_m2·√q   (Л7 сл. 13)
      0 < t_и < T/2 → регулируемый (มี пауза) · t_и = T/2 → q = 1 → нерегулируемый
   ===================================================================== */
function eoInvBridge(host) {
  buildDemo(host, {
    label: "Лекция 6 · сл. 18 · Лекция 7 · сл. 12–13",
    title: "เลื่อน q ของอินเวอร์เตอร์สะพาน แล้วดูช่วงพักบน u₂ กับค่าประสิทธิผลที่ลดตาม √q",
    ratio: 0.86,
    legend: '<span><i style="background:var(--accent)"></i>u₂</span><span><i style="background:var(--ink-3)"></i>X1, X4</span><span><i style="background:var(--accent-2)"></i>X2, X3 · U₂(q) = U_m2·√q</span>',
    controls: [
      { id: "q", label: "q = 2·t_и/T", min: 0.05, max: 1, step: 0.01, value: 0.6, fmt: v => eocN(v, 2) },
      { id: "Um2", label: "U_m2, В", min: 5, max: 50, step: 1, value: 25 },
      { id: "f", label: "f, Гц", min: 200, max: 900, step: 10, value: 400 }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"),
            grid = CV("--grid"), line2 = CV("--line-2"), crit = CV("--crit");
      const font = eocFont(w);
      const T = 1 / s.f, q = s.q, ti = q * T / 2, Um2 = s.Um2;
      const U2 = Um2 * Math.sqrt(q);

      /* คู่ทแยงตาม Л6 сл. 19: (X1, X4) นำในครึ่งคาบแรก · (X2, X3) นำในครึ่งคาบหลัง */
      const Sa = u => { const p = (u - Math.floor(u)) * T; return p < ti ? 1 : 0; };
      const Sb = u => { const p = (u - Math.floor(u)) * T; return (p >= T / 2 && p < T / 2 + ti) ? 1 : 0; };
      const S1 = Sa, S4 = Sa, S2 = Sb, S3 = Sb;
      const u2 = u => { const p = (u - Math.floor(u)) * T; if (p < ti) return Um2; if (p >= T / 2 && p < T / 2 + ti) return -Um2; return 0; };

      const x0 = 40, wp = w - 52, nper = 2;
      const hTop = (h - 28) * 0.60;
      const R5 = eocRows(10, hTop, 5, 4), rh = R5.rh;
      const names = ["X1", "X2", "X3", "X4"], fns = [S1, S2, S3, S4];
      for (let i = 0; i < 4; i++) {
        eocPeriods(ctx, x0, R5.ys[i], wp, rh, nper, grid);
        eocLev(ctx, x0, R5.ys[i], wp, rh, 0, -0.12, 1.2, line2);
        eocW(ctx, x0, R5.ys[i], wp, rh, nper, fns[i], -0.12, 1.2, (i === 0 || i === 3) ? ink3 : acc2, 1.5);
        eocTxt(ctx, names[i], x0 - 6, R5.ys[i] + rh / 2, ink3, font, "right");
      }
      const yU = R5.ys[4], hU = rh;
      eocPeriods(ctx, x0, yU, wp, hU, nper, grid);
      /* แถบเน้นช่วง «พัก» (пауза) ที่ u₂ = 0 */
      eocSpan(ctx, x0, yU, wp, hU, nper, ti / T, 0.5, crit);
      eocSpan(ctx, x0, yU, wp, hU, nper, 0.5 + ti / T, 1, crit);
      eocSpan(ctx, x0, yU, wp, hU, nper, 1 + ti / T, 1.5, crit);
      eocSpan(ctx, x0, yU, wp, hU, nper, 1.5 + ti / T, 2, crit);
      eocLev(ctx, x0, yU, wp, hU, 0, -Um2 * 1.2, Um2 * 1.2, line2);
      eocW(ctx, x0, yU, wp, hU, nper, u2, -Um2 * 1.2, Um2 * 1.2, acc, 2);
      eocTxt(ctx, "u₂", x0 - 6, yU + hU / 2, ink3, font, "right");
      eocTxt(ctx, "пауза", x0 + (ti / T + 0.06) * wp / nper, yU + hU / 2, crit, font, "left");

      /* กราฟ U₂(q) = U_m2·√q */
      const py0 = 10 + hTop + 26;
      const p = new Plot(ctx, 40, py0, w - 54, h - py0 - 34, 0, 1, 0, Um2 * 1.05);
      p.frame(ticks(0, 1, 5), eocTicksN(0, Um2 * 1.05, 3), "q","U₂, В");
      const pts = [];
      for (let i = 0; i <= 100; i++) { const qq = i / 100; pts.push([qq, Um2 * Math.sqrt(qq)]); }
      p.clip(() => p.line(pts, acc2, 2));
      p.dots([[q, U2]], acc, 4);
      ctx.save(); ctx.strokeStyle = ink3; ctx.setLineDash([2, 3]); ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(p.X(q), p.Y(0)); ctx.lineTo(p.X(q), p.Y(U2)); ctx.lineTo(p.X(0), p.Y(U2)); ctx.stroke();
      ctx.restore();

      readout.innerHTML =
        'q = 2·t<sub>и</sub>/T = <b>' + eocN(q, 2) + '</b>' +
        '<span>t<sub>и</sub> = <b>' + eocN(ti * 1e3, 3) + ' мс</b> (T/2 = ' + eocN(T * 500, 3) + ' мс)</span>' +
        '<span>U₂ = U<sub>m2</sub>·√q = <b>' + eocN(U2, 1) + ' В</b></span>' +
        '<span>' + (q >= 0.995
          ? '<b class="good">нерегулируемый</b> · t_и = T/2 · U₂ = U_m2'
          : '<b>регулируемый</b> · 0 &lt; t_и &lt; T/2 · มีช่วงพัก') + '</span>' +
        '<span>อินเวอร์เตอร์นิยาม q = 2t<sub>и</sub>/T ⇒ ค่าประสิทธิผลแปรตาม <b>√q</b> ไม่ใช่ q</span>';
    }
  });
}


/* =====================================================================
   4. eoInvSym — Алгоритмы управления мостом (Л7 сл. 13 б, в)
      симметричный:  X1+X4 และ X2+X3 เปิดเต็มครึ่งคาบ → q = 1
      несимметричный: พัลส์แคบกว่าครึ่งคาบ → มี пауза → q < 1 → U₂ = U_m2·√q
      กระแส i₁ คำนวณจากสมการโหลดเหนี่ยวนำ  L·di/dt = u₂ − i·R  (T_н = L/R)
      ช่วงที่ u₂ กับ i₁ คนละเครื่องหมาย = ช่วงที่ไดโอด VD1–VD4 คืนพลังงานเข้าแหล่งจ่าย
   ===================================================================== */
function eoInvSym(host) {
  buildDemo(host, {
    label: "Лекция 7 · сл. 13",
    title: "สลับอัลกอริทึมสมมาตร/ไม่สมมาตร ดูสถานะคีย์ X1–X4 และช่วงที่ไดโอดคืนกระแส",
    ratio: 0.84,
    legend: '<span><i style="background:var(--accent)"></i>u₂</span><span><i style="background:var(--crit)"></i>i₁</span><span><i style="background:var(--ink-3)"></i>X1…X4</span>',
    controls: [
      { id: "q", label: "q = 2·t_и/T (เฉพาะโหมดไม่สมมาตร)", min: 0.1, max: 1, step: 0.01, value: 0.6, fmt: v => eocN(v, 2) },
      { id: "tn", label: "T_н/T = L/(R·T)", min: 0.05, max: 2, step: 0.05, value: 0.4, fmt: v => eocN(v, 2) },
      { id: "Um2", label: "U_m2, В", min: 5, max: 50, step: 1, value: 25 }
    ],
    buttons: [{ id: "ns", label: "несимметричный алгоритм", toggle: true, value: false }],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), crit = CV("--crit"), ink3 = CV("--ink-3"),
            grid = CV("--grid"), line2 = CV("--line-2"), ok = CV("--ok");
      const font = eocFont(w);
      const ns = !!s.ns, q = ns ? s.q : 1, T = 1, ti = q * T / 2, Um2 = s.Um2, R = 10, TN = s.tn * T;

      const u2 = u => { const p = u - Math.floor(u); if (p < ti) return Um2; if (p >= 0.5 && p < 0.5 + ti) return -Um2; return 0; };
      /* สถานะคีย์: โหมดสมมาตร X1,X4 คู่กัน ครึ่งคาบเต็ม · โหมดไม่สมมาตร X1 เปิดครึ่งคาบเต็ม แต่ X4 แคบลง */
      const X1 = u => { const p = u - Math.floor(u); return p < 0.5 ? 1 : 0; };
      const X2 = u => { const p = u - Math.floor(u); return p >= 0.5 ? 1 : 0; };
      const X4 = u => { const p = u - Math.floor(u); return p < ti ? 1 : 0; };
      const X3 = u => { const p = u - Math.floor(u); return (p >= 0.5 && p < 0.5 + ti) ? 1 : 0; };

      /* กระแสโหลด — อินทิเกรตจนเข้าสภาวะคงตัว */
      const N = 1600, dt = 1 / N;
      let i1 = 0;
      for (let k = 0; k < 6 * N; k++) { const u = (k + 0.5) / N; i1 += dt * ((u2(u) / R) - i1) / TN; }
      const arr = new Array(N + 1);
      for (let k = 0; k <= N; k++) { arr[k] = i1; const u = (k + 0.5) / N; i1 += dt * ((u2(u) / R) - i1) / TN; }
      const iOf = u => arr[Math.min(N, Math.max(0, Math.round((u - Math.floor(u)) * N)))];
      let iMax = 0, back = 0;
      for (let k = 0; k < N; k++) { iMax = Math.max(iMax, Math.abs(arr[k])); if (u2((k + 0.5) / N) * arr[k] < -1e-9) back++; }
      iMax = Math.max(iMax, 1e-6);

      const x0 = 40, wp = w - 52, nper = 2;
      const R6 = eocRows(10, h - 28, 6, 5), rh = R6.rh;
      const nm = ["X1", "X2", "X3", "X4"], fs4 = [X1, X2, X3, X4];
      for (let i = 0; i < 4; i++) {
        eocPeriods(ctx, x0, R6.ys[i], wp, rh, nper, grid);
        eocLev(ctx, x0, R6.ys[i], wp, rh, 0, -0.12, 1.2, line2);
        eocW(ctx, x0, R6.ys[i], wp, rh, nper, fs4[i], -0.12, 1.2, ink3, 1.5);
        eocTxt(ctx, nm[i], x0 - 6, R6.ys[i] + rh / 2, ink3, font, "right");
      }
      /* u₂ */
      const yU = R6.ys[4];
      eocPeriods(ctx, x0, yU, wp, rh, nper, grid);
      eocLev(ctx, x0, yU, wp, rh, 0, -Um2 * 1.2, Um2 * 1.2, line2);
      eocW(ctx, x0, yU, wp, rh, nper, u2, -Um2 * 1.2, Um2 * 1.2, acc, 1.8);
      eocTxt(ctx, "u₂", x0 - 6, yU + rh / 2, ink3, font, "right");
      /* i₁ + แถบช่วงคืนกระแสผ่านไดโอด */
      const yI = R6.ys[5];
      eocPeriods(ctx, x0, yI, wp, rh, nper, grid);
      for (let k = 0; k < N; k++) {
        if (u2((k + 0.5) / N) * arr[k] < -1e-9) {
          for (let r = 0; r < nper; r++) eocSpan(ctx, x0, yI, wp, rh, nper, r + k / N, r + (k + 1) / N, ok, 0.22);
        }
      }
      eocLev(ctx, x0, yI, wp, rh, 0, -iMax * 1.2, iMax * 1.2, line2);
      eocW(ctx, x0, yI, wp, rh, nper, iOf, -iMax * 1.2, iMax * 1.2, crit, 1.8);
      eocTxt(ctx, "i₁", x0 - 6, yI + rh / 2, ink3, font, "right");
      eocTxt(ctx, "ช่วงแรเงา = VD1–VD4 คืนกระแสเข้าแหล่งจ่าย", x0 + 4, yI + rh - 7, ok, font, "left");
      eocTxt(ctx, "t", x0 + wp, h - 8, ink3, font, "right");

      const U2 = Um2 * Math.sqrt(q), pb = back / N * 100;
      readout.innerHTML =
        'อัลกอริทึม: <b>' + (ns ? "несимметричный" : "симметричный") + '</b>' +
        '<span>q = <b>' + eocN(q, 2) + '</b> · U₂ = U<sub>m2</sub>·√q = <b>' + eocN(U2, 1) + ' В</b></span>' +
        '<span>ช่วงคืนกระแสผ่าน VD = <b class="' + (pb > 25 ? "bad" : "good") + '">' + eocN(pb, 1) + ' %</b> ของคาบ</span>' +
        '<span>I₁ (ยอด) = <b>' + eocN(iMax, 2) + ' А</b> · T_н/T = ' + eocN(s.tn, 2) + '</span>' +
        '<span>' + (ns
          ? 'ช่วง пауза โหลดถูกลัดผ่านคู่ทรานซิสเตอร์–ไดโอด กระแสจึงลดช้ากว่า'
          : 'สมมาตร: q = 1 เสมอ ปรับแรงดันไม่ได้ ต้องใช้อัลกอริทึมไม่สมมาตรจึงจะปรับได้') + '</span>';
    }
  });
}


/* =====================================================================
   5. eoInv3ph — Трёхфазный мостовой инвертор, λ = 180° (Л7 сл. 18–19)
      คีย์ 6 ตัว: Т1(a+) Т2(a−) Т3(b+) Т4(b−) Т5(c+) Т6(c−) · สวิตช์ทุก 60° → 6 тактов
      ลำดับเปิดตามสไลด์: u_у1 (0°), u_у6 (60°), u_у3 (120°), u_у2 (180°), u_у5 (240°), u_у4 (300°)
      แรงดันขั้ว u_a0 = ±U_ВХ/2 · แรงดันสาย u_ab = u_a0 − u_b0 → บวก 120° · ศูนย์ 60° · ลบ 120° · ศูนย์ 60°
      U_л(действ.) = U_ВХ·√(2/3) — **ผู้เรียบเรียงคำนวณ** (สไลด์ให้แต่รูปคลื่น ไม่ให้สูตร)
   ===================================================================== */
function eoInv3ph(host) {
  buildDemo(host, {
    label: "Лекция 7 · сл. 18–19",
    title: "อินเวอร์เตอร์สามเฟส λ = 180°: ดูคีย์ที่นำในแต่ละทัต และแรงดันขั้ว/แรงดันสาย",
    ratio: 0.92,
    animate: true,
    legend: '<span><i style="background:var(--ink-3)"></i>u_у1…u_у4</span><span><i style="background:var(--accent)"></i>u_ab</span><span><i style="background:var(--accent-2)"></i>u_bc</span><span><i style="background:var(--ok)"></i>u_ca</span>',
    controls: [
      { id: "Uv", label: "U_ВХ, В", min: 12, max: 120, step: 1, value: 27 },
      { id: "f", label: "f, Гц", min: 50, max: 1000, step: 10, value: 400 }
    ],
    buttons: [{ id: "pol", label: "полюсные напряжения u_a0", toggle: true, value: false }],
    draw(ctx, w, h, s, readout, t) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"), ink3 = CV("--ink-3"),
            grid = CV("--grid"), line2 = CV("--line-2"), crit = CV("--crit");
      const font = eocFont(w), U = s.Uv, pol = !!s.pol;

      /* สถานะคีย์เป็นฟังก์ชันของเฟส p ∈ [0;1) */
      const on = (p, deg0, deg1) => { const d = (p * 360 % 360 + 360) % 360; return (deg0 < deg1) ? (d >= deg0 && d < deg1) : (d >= deg0 || d < deg1); };
      const T1 = p => on(p, 0, 180) ? 1 : 0, T2 = p => on(p, 180, 360) ? 1 : 0;
      const T3 = p => on(p, 120, 300) ? 1 : 0, T4 = p => on(p, 300, 120) ? 1 : 0;
      const T5 = p => on(p, 240, 60) ? 1 : 0, T6 = p => on(p, 60, 240) ? 1 : 0;
      const ua0 = p => (T1(p) ? 0.5 : -0.5) * U, ub0 = p => (T3(p) ? 0.5 : -0.5) * U, uc0 = p => (T5(p) ? 0.5 : -0.5) * U;
      const uab = p => ua0(p) - ub0(p), ubc = p => ub0(p) - uc0(p), uca = p => uc0(p) - ua0(p);

      const x0 = 46, wp = w - 58, nper = 1;
      const R9 = eocRows(20, h - 40, 9, 3), rh = R9.rh;
      const rows = [
        ["u_у1", T1], ["u_у6", T6], ["u_у3", T3], ["u_у2", T2], ["u_у5", T5], ["u_у4", T4]
      ];
      /* ป้ายทัต 1…6 */
      for (let k = 0; k < 6; k++) {
        const cx = x0 + (k + 0.5) / 6 * wp;
        eocTxt(ctx, String(k + 1), cx, 10, ink3, font, "center");
      }
      eocTxt(ctx, "Такт", x0 - 6, 10, ink3, font, "right");
      for (let i = 0; i < 6; i++) {
        const y = R9.ys[i];
        ctx.save(); ctx.strokeStyle = grid; ctx.lineWidth = 1; ctx.setLineDash([2, 3]);
        for (let k = 1; k < 6; k++) { const px = Math.round(x0 + k / 6 * wp) + 0.5; ctx.beginPath(); ctx.moveTo(px, y); ctx.lineTo(px, y + rh); ctx.stroke(); }
        ctx.restore();
        eocLev(ctx, x0, y, wp, rh, 0, -0.15, 1.25, line2);
        eocW(ctx, x0, y, wp, rh, nper, rows[i][1], -0.15, 1.25, ink3, 1.5);
        eocTxt(ctx, rows[i][0], x0 - 6, y + rh / 2, ink3, font, "right");
      }
      const trio = pol ? [["u_a0", ua0, acc], ["u_b0", ub0, acc2], ["u_c0", uc0, ok]]
                       : [["u_ab", uab, acc], ["u_bc", ubc, acc2], ["u_ca", uca, ok]];
      const vm = (pol ? U * 0.5 : U) * 1.25;
      for (let i = 0; i < 3; i++) {
        const y = R9.ys[6 + i];
        ctx.save(); ctx.strokeStyle = grid; ctx.lineWidth = 1; ctx.setLineDash([2, 3]);
        for (let k = 1; k < 6; k++) { const px = Math.round(x0 + k / 6 * wp) + 0.5; ctx.beginPath(); ctx.moveTo(px, y); ctx.lineTo(px, y + rh); ctx.stroke(); }
        ctx.restore();
        eocLev(ctx, x0, y, wp, rh, 0, -vm, vm, line2);
        eocW(ctx, x0, y, wp, rh, nper, trio[i][1], -vm, vm, trio[i][2], 1.8);
        eocTxt(ctx, trio[i][0], x0 - 6, y + rh / 2, ink3, font, "right");
      }

      /* เคอร์เซอร์เวลา — เดินช้ากว่าจริงมาก เพื่อให้ตามทัตได้ทัน */
      const ph = ((t || 0) * 0.3) % 1;
      const cx = x0 + ph * wp;
      ctx.save(); ctx.strokeStyle = crit; ctx.lineWidth = 1.4;
      ctx.beginPath(); ctx.moveTo(cx, 16); ctx.lineTo(cx, h - 22); ctx.stroke(); ctx.restore();
      eocTxt(ctx, "ωt", x0 + wp, h - 10, ink3, font, "right");
      eocTxt(ctx, "0°", x0, h - 10, ink3, font, "left");
      eocTxt(ctx, "360°", x0 + wp - 26, h - 10, ink3, font, "right");

      const takt = Math.floor(ph * 6) + 1;
      const open = [];
      if (T1(ph)) open.push("Т1"); if (T2(ph)) open.push("Т2");
      if (T3(ph)) open.push("Т3"); if (T4(ph)) open.push("Т4");
      if (T5(ph)) open.push("Т5"); if (T6(ph)) open.push("Т6");
      const Ul = U * Math.sqrt(2 / 3), Ul1 = 0.78 * U;
      readout.innerHTML =
        'Такт <b>' + takt + '</b> из 6 · λ = <b>180°</b>' +
        '<span>открыты: <b class="' + (open.length === 3 ? "good" : "bad") + '">' + open.join(", ") + '</b> — โหมด λ = 180° ต้องมี <b>3 คีย์</b> นำพร้อมกันเสมอ</span>' +
        '<span>u_ab = <b>' + eocN(uab(ph), 0) + ' В</b> · u_bc = <b>' + eocN(ubc(ph), 0) + ' В</b> · u_ca = <b>' + eocN(uca(ph), 0) + ' В</b></span>' +
        '<span>U_л(действ.) = U_ВХ·√(2/3) = <b>' + eocN(Ul, 1) + ' В</b> · U_л(1) ≈ 0,78·U_ВХ = <b>' + eocN(Ul1, 1) + ' В</b></span>' +
        '<span>สวิตช์ทุก 60° · แรงดันสามเส้นเลื่อมกัน 120° · T = ' + eocN(1000 / s.f, 2) + ' мс</span>';
    }
  });
}


/* =====================================================================
   6. eoInvSelf — Инвертор с самовозбуждением (Л7 сл. 23 · Л6 сл. 21)
      ความถี่กำหนดโดยเวลาที่ฟลักซ์วิ่งจาก −B_S ถึง +B_S:
        f = [U_П − r₁·(I_1ХХ + I₂·W₂/W₁)] / (4·B_S·S_C·W₁)      (Ф6.6)
      ค่าเริ่มต้น S_C = 3,05·10⁻⁴ м², B_S = 1,68 Тл จากตารางค่าคงที่ РГР-2 (Л7 сл. 26)
      **ค่าสมมติของผู้เรียบเรียง:** r₁ = 0,15 Ом · I_1ХХ = 0,2 А · W₂/W₁ = 1,5 (สไลด์ไม่ให้)
      **หมายเหตุต้นฉบับ:** สไลด์ 21 พิมพ์ตัวส่วนเป็น ΔW₁/ΔW — ที่ถูกคือ W₁
   ===================================================================== */
function eoInvSelf(host) {
  buildDemo(host, {
    label: "Лекция 7 · сл. 23 · Лекция 6 · сл. 21",
    title: "ดูจุดทำงานวิ่งบนลูปฮิสเทอรีซิสของแกน แล้วอ่านความถี่ที่ได้จากสูตรของภาควิชา",
    ratio: 0.62,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>петля B(i_н)</span><span><i style="background:var(--accent-2)"></i>B(t)</span><span><i style="background:var(--ok)"></i>u₂(t)</span>',
    controls: [
      { id: "Up", label: "U_П, В", min: 10, max: 30, step: 0.5, value: 27, fmt: v => eocN(v, 1) },
      { id: "W1", label: "W₁, витков", min: 10, max: 200, step: 1, value: 33 },
      { id: "Sc", label: "S_C, см²", min: 1, max: 6, step: 0.05, value: 3.05, fmt: v => eocN(v, 2) },
      { id: "Bs", label: "B_S, Тл", min: 1, max: 1.8, step: 0.01, value: 1.68, fmt: v => eocN(v, 2) },
      { id: "I2", label: "I₂, А", min: 0, max: 3, step: 0.1, value: 1, fmt: v => eocN(v, 1) }
    ],
    draw(ctx, w, h, s, readout, t) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"), ink3 = CV("--ink-3"),
            grid = CV("--grid"), line2 = CV("--line-2"), crit = CV("--crit");
      const font = eocFont(w);
      const r1 = 0.15, Ixx = 0.2, n = 1.5;
      const dU1 = r1 * (Ixx + s.I2 * n);
      const Sc = s.Sc * 1e-4;
      const f = Math.max(1, (s.Up - dU1) / (4 * s.Bs * Sc * s.W1));
      const fxx = Math.max(1, (s.Up - r1 * Ixx) / (4 * s.Bs * Sc * s.W1));
      const Fmax = s.Bs * Sc;

      /* ---- ซ้าย: ลูปฮิสเทอรีซิส แบบสี่เหลี่ยม (ППГ: B_m ≈ B_r ≈ B_S) ---- */
      const side = Math.min(h - 34, w * 0.44);
      const lx = 34, ly = 14 + (h - 34 - side) / 2, ls = side;
      const Hc = 0.35, Hm = 1;
      const HX = v => lx + (v + Hm) / (2 * Hm) * ls;
      const BY = v => ly + ls - (v + 1) / 2 * ls;
      ctx.save();
      ctx.strokeStyle = grid; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(HX(-Hm), BY(0)); ctx.lineTo(HX(Hm), BY(0)); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(HX(0), BY(-1)); ctx.lineTo(HX(0), BY(1)); ctx.stroke();
      ctx.strokeStyle = acc; ctx.lineWidth = 1.8;
      ctx.beginPath();
      ctx.moveTo(HX(Hm), BY(1)); ctx.lineTo(HX(-Hc), BY(1)); ctx.lineTo(HX(-Hc), BY(-1)); ctx.lineTo(HX(-Hm), BY(-1));
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(HX(-Hm), BY(-1)); ctx.lineTo(HX(Hc), BY(-1)); ctx.lineTo(HX(Hc), BY(1)); ctx.lineTo(HX(Hm), BY(1));
      ctx.stroke();
      ctx.restore();
      eocTxt(ctx, "Φ", HX(0) + 5, ly + 2, ink3, font, "left");
      eocTxt(ctx, "i_н", HX(Hm), BY(0) + 10, ink3, font, "right");
      eocTxt(ctx, "+Φ_МАХ", lx + 2, BY(1) - 7, ink3, font, "left");
      eocTxt(ctx, "−Φ_МАХ", lx + 2, BY(-1) + 8, ink3, font, "left");

      /* จุดทำงานวิ่ง: ครึ่งคาบไต่ฟลักซ์ที่ i_н เกือบคงที่ แล้วพุ่งเข้าอิ่มตัว */
      const ph = ((t || 0) * 0.35) % 1;
      let pb, ph2;
      if (ph < 0.45) { pb = -1 + 2 * (ph / 0.45); ph2 = Hc; }
      else if (ph < 0.5) { pb = 1; ph2 = Hc + (Hm - Hc) * ((ph - 0.45) / 0.05); }
      else if (ph < 0.95) { pb = 1 - 2 * ((ph - 0.5) / 0.45); ph2 = -Hc; }
      else { pb = -1; ph2 = -Hc - (Hm - Hc) * ((ph - 0.95) / 0.05); }
      ctx.save(); ctx.fillStyle = crit;
      ctx.beginPath(); ctx.arc(HX(ph2), BY(pb), 4, 0, 7); ctx.fill(); ctx.restore();

      /* ---- ขวา: B(t) รูปสามเหลี่ยม และ u₂(t) สี่เหลี่ยม ---- */
      const rx = lx + ls + 34, rw = w - rx - 12;
      const R2 = eocRows(16, h - 40, 2, 12), rh = R2.rh;
      const Bt = u => { const p = u - Math.floor(u); return p < 0.5 ? -1 + 4 * p : 1 - 4 * (p - 0.5); };
      const u2 = u => { const p = u - Math.floor(u); return p < 0.5 ? 1 : -1; };
      eocPeriods(ctx, rx, R2.ys[0], rw, rh, 2, grid);
      eocLev(ctx, rx, R2.ys[0], rw, rh, 0, -1.3, 1.3, line2);
      eocW(ctx, rx, R2.ys[0], rw, rh, 2, Bt, -1.3, 1.3, acc2, 2);
      eocTxt(ctx, "B(t)", rx - 4, R2.ys[0] + rh / 2, ink3, font, "right");
      eocPeriods(ctx, rx, R2.ys[1], rw, rh, 2, grid);
      eocLev(ctx, rx, R2.ys[1], rw, rh, 0, -1.3, 1.3, line2);
      eocW(ctx, rx, R2.ys[1], rw, rh, 2, u2, -1.3, 1.3, ok, 2);
      eocTxt(ctx, "u₂(t)", rx - 4, R2.ys[1] + rh / 2, ink3, font, "right");
      const cx = rx + (ph / 2) * rw;
      ctx.save(); ctx.strokeStyle = crit; ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.moveTo(cx, R2.ys[0]); ctx.lineTo(cx, R2.ys[1] + rh); ctx.stroke(); ctx.restore();
      eocTxt(ctx, "T = " + eocN(1000 / f, 2) + " мс", rx, h - 12, ink3, font, "left");

      const drop = (1 - f / fxx) * 100;
      readout.innerHTML =
        'f = <b>' + eocN(f, 0) + ' Гц</b>' +
        '<span>T = <b>' + eocN(1000 / f, 2) + ' мс</b> · Φ_МАХ = B_S·S_C = <b>' + eocN(Fmax * 1e6, 1) + '·10⁻⁶ Вб</b></span>' +
        '<span>ΔU₁ = r₁·(I_1ХХ + I₂·W₂/W₁) = <b>' + eocN(dU1, 2) + ' В</b></span>' +
        '<span>f_ХХ = <b>' + eocN(fxx, 0) + ' Гц</b> · ตกลง <b class="' + (drop > 10 ? "bad" : "good") + '">' + eocN(drop, 1) + ' %</b> เมื่อโหลดเต็ม</span>' +
        '<span>f ∝ U_П และ f ∝ 1/(B_S·S_C·W₁) — ความถี่ลอยตามโหลด คือข้อเสียหลักของ самовозбуждение</span>';
    }
  });
}


/* =====================================================================
   7. eoInvExt — Внешняя и частотная характеристики инвертора (Л6 сл. 21)
      U₂ = (W₂/W₁)·(U_П − ΔU₁) − r₂·I₂                       (Ф6.3)
      ΔU₁ = r₁·(I_1ХХ + I₂·W₂/W₁)                            (Ф6.7 — ได้จากการเทียบ Ф6.5 กับ Ф6.6)
      f  = [U_П − ΔU₁] / (4·B_S·S_C·W₁)                      (Ф6.6)
      เกณฑ์ตัดสิน ΔŪ₂ = 0,1 และ Δf̄ = 0,1 จากตาราง РГР-2 (Л7 сл. 26)
      **ค่าสมมติ:** I_1ХХ = 0,2 А · W₁ = 33 витка · S_C = 3,05 см² · B_S = 1,68 Тл
   ===================================================================== */
function eoInvExt(host) {
  buildDemo(host, {
    label: "Лекция 6 · сл. 21",
    title: "เลื่อนกระแสโหลดแล้วดูแรงดันและความถี่ตกพร้อมกัน — เทียบกับเกณฑ์ 10 % ของ РГР-2",
    ratio: 0.86,
    legend: '<span><i style="background:var(--accent)"></i>U₂(I₂)</span><span><i style="background:var(--accent-2)"></i>f(I₂)</span><span><i style="background:var(--ok)"></i>เกณฑ์ 10 %</span>',
    controls: [
      { id: "Up", label: "U_П, В", min: 12, max: 120, step: 1, value: 27 },
      { id: "n", label: "W₂/W₁", min: 0.1, max: 20, step: 0.1, value: 1.5, fmt: v => eocN(v, 1) },
      { id: "r1", label: "r₁, Ом", min: 0.01, max: 5, step: 0.01, value: 0.15, fmt: v => eocN(v, 2) },
      { id: "r2", label: "r₂, Ом", min: 0.01, max: 5, step: 0.01, value: 0.5, fmt: v => eocN(v, 2) },
      { id: "I2", label: "I₂, А (จุดทำงาน)", min: 0, max: 3, step: 0.05, value: 2, fmt: v => eocN(v, 2) }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"), ink3 = CV("--ink-3");
      const Ixx = 0.2, W1 = 33, Sc = 3.05e-4, Bs = 1.68, Imax = 3;
      const dU1 = i => s.r1 * (Ixx + i * s.n);
      const U2 = i => s.n * (s.Up - dU1(i)) - s.r2 * i;
      const fr = i => Math.max(1, (s.Up - dU1(i)) / (4 * Bs * Sc * W1));
      const U0 = U2(0), f0 = fr(0), Uw = U2(s.I2), fw = fr(s.I2);

      const half = (h - 26) / 2;
      const p1 = new Plot(ctx, 46, 18, w - 60, half - 42, 0, Imax, 0, Math.max(U0 * 1.1, 1));
      p1.frame(ticks(0, Imax, 6), eocTicksN(0, Math.max(U0 * 1.1, 1), 4), "I₂, А","U₂, В");
      const c1 = [], c2 = [];
      for (let k = 0; k <= 120; k++) { const i = k / 120 * Imax; c1.push([i, U2(i)]); c2.push([i, fr(i)]); }
      p1.clip(() => {
        p1.line([[0, U0 * 0.9], [Imax, U0 * 0.9]], ok, 1.2, [4, 4]);
        p1.line(c1, acc, 2);
      });
      p1.dots([[s.I2, Uw]], acc2, 4);

      const fmin = Math.min(fr(Imax), f0) * 0.9, fmax = f0 * 1.05;
      const p2 = new Plot(ctx, 46, 18 + half, w - 60, half - 40, 0, Imax, fmin, fmax);
      p2.frame(ticks(0, Imax, 6), eocTicksN(fmin, fmax, 4), "I₂, А","f, Гц");
      p2.clip(() => {
        p2.line([[0, f0 * 0.9], [Imax, f0 * 0.9]], ok, 1.2, [4, 4]);
        p2.line(c2, acc2, 2);
      });
      p2.dots([[s.I2, fw]], acc, 4);

      const du = (1 - Uw / U0) * 100, df = (1 - fw / f0) * 100;
      readout.innerHTML =
        'U₂ХХ = <b>' + eocN(U0, 1) + ' В</b> → U₂ = <b>' + eocN(Uw, 1) + ' В</b>' +
        '<span>ΔU₂ = <b class="' + (du > 10 ? "bad" : "good") + '">' + eocN(du, 1) + ' %</b> (เกณฑ์ ΔŪ₂ = 0,1)</span>' +
        '<span>f_ХХ = <b>' + eocN(f0, 0) + ' Гц</b> → f = <b>' + eocN(fw, 0) + ' Гц</b> · Δf = <b class="' + (df > 10 ? "bad" : "good") + '">' + eocN(df, 1) + ' %</b></span>' +
        '<span>ΔU₁ = <b>' + eocN(dU1(s.I2), 2) + ' В</b> · แรงดันตกจาก r₂·I₂ = <b>' + eocN(s.r2 * s.I2, 2) + ' В</b></span>' +
        '<span>คุณลักษณะภายนอกเป็นเส้นตรงลาดลง ความชันคือ (W₂/W₁)²·r₁ + r₂</span>';
    }
  });
}


/* =====================================================================
   8. eoPCH — Преобразователь частоты และ ТАД (Л7 сл. 20–21)
      Ω₂ = (2π·f₁/P)·(1 − S)     · Ω₁ = 2π·f₁/P    · n₂ = (60·f₁/P)·(1 − S)
      скалярное управление: U/f = const เพื่อรักษาฟลักซ์ Φ ≈ const
      **ผู้เรียบเรียงเสริม:** Φ/Φ_ном ≈ (U₁/U_ном)·(f_ном/f₁) — สไลด์ไม่ให้สูตรนี้ แต่เป็นเหตุผลของ U/f = const
   ===================================================================== */
function eoPCH(host) {
  buildDemo(host, {
    label: "Лекция 7 · сл. 20–21",
    title: "ปรับความถี่ f₁ ของตัวแปลงความถี่ แล้วดูความเร็วโรเตอร์และฟลักซ์เมื่อเปิด/ปิด U/f = const",
    ratio: 0.86,
    legend: '<span><i style="background:var(--accent)"></i>U₁(f₁)</span><span><i style="background:var(--accent-2)"></i>n₂(f₁)</span><span><i style="background:var(--crit)"></i>Φ/Φ_ном</span>',
    controls: [
      { id: "f1", label: "f₁, Гц", min: 5, max: 100, step: 1, value: 50 },
      { id: "P", label: "P — число пар полюсов", min: 1, max: 4, step: 1, value: 2 },
      { id: "S", label: "S — скольжение", min: 0, max: 0.1, step: 0.005, value: 0.03, fmt: v => eocN(v, 3) },
      { id: "Un", label: "U₁ном, В", min: 110, max: 380, step: 10, value: 220 }
    ],
    buttons: [{ id: "uf", label: "U/f = const", toggle: true, value: true }],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"), ink3 = CV("--ink-3"), ok = CV("--ok");
      const fn = 50, uf = !!s.uf;
      const U1 = f => uf ? s.Un * Math.min(1, f / fn) : s.Un;
      const n2 = f => 60 * f / s.P * (1 - s.S);
      const flux = f => (U1(f) / s.Un) * (fn / Math.max(f, 1e-6));
      const W2 = 2 * Math.PI * s.f1 / s.P * (1 - s.S), W1 = 2 * Math.PI * s.f1 / s.P;

      const half = (h - 26) / 2;
      const p1 = new Plot(ctx, 46, 18, w - 60, half - 42, 0, 100, 0, s.Un * 1.15);
      p1.frame(ticks(0, 100, 5), eocTicksN(0, s.Un * 1.15, 4), "f₁, Гц","U₁, В");
      const cu = [], cf = [];
      for (let k = 0; k <= 100; k++) { const f = 5 + k / 100 * 95; cu.push([f, U1(f)]); cf.push([f, Math.min(2.5, flux(f))]); }
      p1.clip(() => p1.line(cu, acc, 2));
      p1.dots([[s.f1, U1(s.f1)]], acc2, 4);

      const nmax = 60 * 100 / s.P * 1.1;
      const p2 = new Plot(ctx, 46, 18 + half, w - 60, half - 40, 0, 100, 0, nmax);
      p2.frame(ticks(0, 100, 5), eocTicksN(0, nmax, 4), "f₁, Гц","n₂, об/мин");
      const cn = [];
      for (let k = 0; k <= 100; k++) { const f = 5 + k / 100 * 95; cn.push([f, n2(f)]); }
      p2.clip(() => p2.line(cn, acc2, 2));
      p2.dots([[s.f1, n2(s.f1)]], acc, 4);
      eocTxt(ctx, uf ? "U/f = const" : "U₁ = const → Φ พุ่งเมื่อ f₁ ต่ำ", 50, 12 + 8,
        uf ? ok : crit, eocFont(w), "left");

      const fl = flux(s.f1);
      readout.innerHTML =
        'Ω₂ = (2π·f₁/P)·(1−S) = <b>' + eocN(W2, 1) + ' рад/с</b>' +
        '<span>n₂ = <b>' + eocN(n2(s.f1), 0) + ' об/мин</b> · Ω₁ = <b>' + eocN(W1, 1) + ' рад/с</b></span>' +
        '<span>U₁ = <b>' + eocN(U1(s.f1), 0) + ' В</b> · Φ/Φ_ном = <b class="' + (fl > 1.05 ? "bad" : "good") + '">' + eocN(fl, 2) + '</b></span>' +
        '<span>' + (uf
          ? 'รักษา U/f คงที่ ⇒ ฟลักซ์คงที่ โมเมนต์สูงสุดไม่ตก'
          : 'ไม่ลด U₁ ตาม f₁ ⇒ ฟลักซ์เกินพิกัด แกนอิ่มตัว กระแสแม่เหล็กพุ่ง') + '</span>' +
        '<span>โครงสร้าง ПЧ สองระดับ: сеть (f₁) → В → U_d → АИН → (U_2m, f₂)</span>';
    }
  });
}


/* =====================================================================
   9. eoConvBuck — Понижающий конвертор ПН (Л8 сл. 12, 14 а)
      q = t_и/T                                     (Л8 сл. 12 — **นิยามคนละอย่างกับอินเวอร์เตอร์**)
      U_ВЫХ = (1/T)·∫₀^{t_и} U_ВХ dt = q·U_ВХ        (Л8 сл. 12) · K_ПН = q (сл. 14)
      ΔI_L = U_ВХ·q·(1−q)·T/L — **ผู้เรียบเรียงเสริม** (Л8 ระบุว่าไม่มีสูตรริปเปิลบนสไลด์)
   ===================================================================== */
function eoConvBuck(host) {
  buildDemo(host, {
    label: "Лекция 8 · сл. 12, 14",
    title: "เลื่อน q ของคอนเวอร์เตอร์ลดแรงดัน แล้วดูค่าเฉลี่ยขาออกกับกระแสในตัวเหนี่ยวนำ (дроссель)",
    ratio: 0.72,
    legend: '<span><i style="background:var(--accent)"></i>u บนขา дроссель</span><span><i style="background:var(--accent-2)"></i>i_L</span><span><i style="background:var(--ok)"></i>ค่าเฉลี่ย</span>',
    controls: [
      { id: "q", label: "q = t_и/T", min: 0.05, max: 0.95, step: 0.01, value: 0.5, fmt: v => eocN(v, 2) },
      { id: "Uv", label: "U_ВХ, В", min: 10, max: 40, step: 1, value: 27 },
      { id: "L", label: "L, мГн", min: 0.01, max: 10, step: 0.01, value: 1, fmt: v => eocN(v, 2) },
      { id: "f", label: "f_ШИМ, кГц", min: 1, max: 200, step: 1, value: 20 },
      { id: "Rn", label: "R_н, Ом", min: 1, max: 500, step: 1, value: 20 }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"), ink3 = CV("--ink-3"),
            grid = CV("--grid"), line2 = CV("--line-2");
      const font = eocFont(w);
      const q = s.q, T = 1 / (s.f * 1e3), L = s.L * 1e-3;
      /* เกณฑ์โหมด: I_Н > ΔI_L/2 ⟺ 2L/(R_н·T) > 1 − q (ตรงกับ eoConvMode)
         ในโหมด ПТ ค่าจริงสูงกว่า q·U_ВХ — ใช้ M = 2/(1+√(1+4K/q²)) (ผู้เรียบเรียงเสริม) */
      const Kf = 2 * L / (s.Rn * T), cont = Kf > (1 - q);
      const Uid = q * s.Uv;
      const Uo = cont ? Uid : 2 * s.Uv / (1 + Math.sqrt(1 + 4 * Kf / (q * q)));
      const In = Uo / s.Rn;
      const dI = (s.Uv - Uo) * q * T / L;
      const Imin = cont ? In - dI / 2 : 0, Imax0 = cont ? In + dI / 2 : dI;
      const tf = cont ? (1 - q) : q * (s.Uv - Uo) / Math.max(Uo, 1e-9);

      const uimp = u => { const p = u - Math.floor(u); return p < q ? s.Uv : 0; };
      const iL = u => {
        const p = u - Math.floor(u);
        if (cont) return p < q ? Imin + (p / q) * dI : Imax0 - ((p - q) / (1 - q)) * dI;
        if (p < q) return (p / q) * Imax0;
        if (p < q + tf) return Imax0 * (1 - (p - q) / tf);
        return 0;
      };

      const x0 = 46, wp = w - 58, nper = 2;
      const R2 = eocRows(12, h - 34, 2, 12), rh = R2.rh;
      const uM = s.Uv * 1.2;
      eocPeriods(ctx, x0, R2.ys[0], wp, rh, nper, grid);
      eocLev(ctx, x0, R2.ys[0], wp, rh, 0, 0, uM, line2);
      eocW(ctx, x0, R2.ys[0], wp, rh, nper, uimp, 0, uM, acc, 1.8);
      const yo = eocLev(ctx, x0, R2.ys[0], wp, rh, Uo, 0, uM, ok, [5, 3]);
      eocTxt(ctx, "u, В", x0 - 6, R2.ys[0] + rh / 2, ink3, font, "right");
      eocTxt(ctx, "U_ВЫХ = " + eocN(Uo, 1) + " В", x0 + wp - 2, yo - 7, ok, font, "right");
      eocTxt(ctx, "t_и", x0 + q / nper * wp * 0.5, R2.ys[0] + 8, ink3, font, "center");

      const iM = Math.max(Imax0 * 1.25, 1e-4);
      eocPeriods(ctx, x0, R2.ys[1], wp, rh, nper, grid);
      eocLev(ctx, x0, R2.ys[1], wp, rh, 0, 0, iM, line2);
      eocLev(ctx, x0, R2.ys[1], wp, rh, In, 0, iM, ok, [5, 3]);
      eocW(ctx, x0, R2.ys[1], wp, rh, nper, iL, 0, iM, acc2, 1.8);
      eocTxt(ctx, "i_L, А", x0 - 6, R2.ys[1] + rh / 2, ink3, font, "right");
      eocTxt(ctx, "I_Н = " + eocN(In, 2) + " А", x0 + wp - 2, R2.ys[1] + rh - (In / iM) * rh - 7, ok, font, "right");
      eocTxt(ctx, "t", x0 + wp, h - 12, ink3, font, "right");
      eocTxt(ctx, "T = " + eocN(T * 1e6, 1) + " мкс", x0, h - 12, ink3, font, "left");

      readout.innerHTML =
        'q = t<sub>и</sub>/T = <b>' + eocN(q, 2) + '</b>' +
        '<span>t<sub>и</sub> = <b>' + eocN(q * T * 1e6, 1) + ' мкс</b> · t<sub>П</sub> = <b>' + eocN((1 - q) * T * 1e6, 1) + ' мкс</b></span>' +
        '<span>U<sub>ВЫХ</sub> = q·U<sub>ВХ</sub> = <b>' + eocN(Uid, 1) + ' В</b> · I<sub>Н</sub> = <b>' + eocN(In, 2) + ' А</b></span>' +
        '<span>ΔI_L = <b>' + eocN(dI, 3) + ' А</b> · режим <b class="' + (cont ? "good" : "bad") + '">' + (cont ? "НТ" : "ПТ") + '</b>' +
          (cont ? '' : ' ⇒ ค่าจริง <b>' + eocN(Uo, 1) + ' В</b> สูงกว่าสูตร') + '</span>' +
        '<span>คอนเวอร์เตอร์นิยาม q = t<sub>и</sub>/T ⇒ ค่า <b>เฉลี่ย</b> แปรตาม q เป็นเชิงเส้น (ต่างจากอินเวอร์เตอร์ที่ ∝ √q)</span>';
    }
  });
}


/* =====================================================================
   10. eoConvAll — Коэффициенты передачи ПН / ПВ / ПИ (Л8 сл. 14, таблица 3.1)
       K_ПН = q · K_ПВ = 1/(1−q) · K_ПИ = −q/(1−q)  โดย q = t_и/T, 0 ≤ q < 1
   ===================================================================== */
function eoConvAll(host) {
  buildDemo(host, {
    label: "Лекция 8 · сл. 14",
    title: "เทียบค่าถ่ายโอนของสามสคีมบนแกนเดียว — ทำไม ПВ พุ่งเป็นอนันต์และ ПИ ข้าม |K| = 1 ที่ q = 0,5",
    ratio: 0.64,
    legend: '<span><i style="background:var(--accent)"></i>ПН = q</span><span><i style="background:var(--accent-2)"></i>ПВ = 1/(1−q)</span><span><i style="background:var(--crit)"></i>ПИ = −q/(1−q)</span>',
    controls: [
      { id: "q", label: "q = t_и/T", min: 0.05, max: 0.9, step: 0.01, value: 0.5, fmt: v => eocN(v, 2) },
      { id: "Uv", label: "U_ВХ, В", min: 10, max: 40, step: 1, value: 27 }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
            ink3 = CV("--ink-3"), line2 = CV("--line-2");
      const q = s.q;
      const kn = q, kv = 1 / (1 - q), ki = -q / (1 - q);
      const p = new Plot(ctx, 46, 18, w - 60, h - 52, 0, 0.9, -6, 6);
      p.frame(ticks(0, 0.9, 6), eocTicksN(-6, 6, 6), "q","K = U_ВЫХ/U_ВХ");
      const a = [], b = [], c = [];
      for (let k = 0; k <= 180; k++) {
        const x = k / 180 * 0.9;
        a.push([x, x]); b.push([x, 1 / (1 - x)]); c.push([x, -x / (1 - x)]);
      }
      p.clip(() => {
        p.line([[0, 1], [0.9, 1]], line2, 1, [4, 4]);
        p.line([[0, -1], [0.9, -1]], line2, 1, [4, 4]);
        p.line([[0.5, -6], [0.5, 6]], line2, 1, [3, 3]);
        p.line(a, acc, 2);
        p.line(b, acc2, 2);
        p.line(c, crit, 2);
        p.dots([[q, Math.max(-6, Math.min(6, kn))]], acc, 4);
        p.dots([[q, Math.max(-6, Math.min(6, kv))]], acc2, 4);
        p.dots([[q, Math.max(-6, Math.min(6, ki))]], crit, 4);
      });
      eocTxt(ctx, "q = 0,5", p.X(0.5) + 4, p.Y(5.4), ink3, eocFont(w), "left");

      readout.innerHTML =
        'q = <b>' + eocN(q, 2) + '</b> · U<sub>ВХ</sub> = <b>' + eocN(s.Uv, 0) + ' В</b>' +
        '<span>ПН: K = q = <b>' + eocN(kn, 2) + '</b> → U = <b>' + eocN(kn * s.Uv, 1) + ' В</b></span>' +
        '<span>ПВ: K = 1/(1−q) = <b>' + eocN(kv, 2) + '</b> → U = <b>' + eocN(kv * s.Uv, 1) + ' В</b></span>' +
        '<span>ПИ: K = −q/(1−q) = <b>' + eocN(ki, 2) + '</b> → U = <b>' + eocN(ki * s.Uv, 1) + ' В</b> (ขั้วกลับ)</span>' +
        '<span>ย่านใช้งานจริงของ q: <b class="' + (q >= 0.1 && q <= 0.85 ? "good" : "bad") + '">' + eocN(q, 2) + '</b> — นอกช่วง 0,10…0,85 ตัวประกอบ K ของ ПВ/ПИ พุ่งเร็วจนควบคุมไม่ได้จริง</span>' +
        '<span>' + (Math.abs(q - 0.5) < 0.005
          ? 'q = 0,5 ⇒ |K_ПИ| = 1 พอดี · K_ПВ = 2 — จุดพลิกของ ПИ'
          : (q < 0.5
            ? 'q &lt; 0,5 ⇒ |K_ПИ| &lt; 1 (ลดแรงดัน)'
            : 'q &gt; 0,5 ⇒ |K_ПИ| &gt; 1 (เพิ่มแรงดัน) — ПИ ทำได้ทั้งสองทาง')) + '</span>';
    }
  });
}


/* =====================================================================
   11. eoConvMode — Режимы НТ / ПТ ของ ПНК (Л8 сл. 15)
       เงื่อนไขเลือกฟิลเตอร์บนสไลด์:  ω·L ≫ R_Н  และ  1/(ω·C_ВЫХ) ≪ R_Н  โดย ω = 2π·f
       ในโหมด ПТ ความสัมพันธ์ U_ВЫХ = q·U_ВХ **ไม่เป็นจริง** — แรงดันขาออกขึ้นกับโหลดด้วย
       ค่าที่ใช้คำนวณเส้นโค้ง ПТ:  M = 2/(1 + √(1 + 4K/q²)), K = 2L/(R_Н·T)
       — **ผู้เรียบเรียงเสริม** สไลด์ระบุแต่ข้อเท็จจริง ไม่ให้สมการนี้
       **หมายเหตุต้นฉบับ:** เนื้อหาแผ่นนี้ถูกตัดออกจากวัสดุแจก «к л.8» — มีเฉพาะบนสไลด์
   ===================================================================== */
function eoConvMode(host) {
  buildDemo(host, {
    label: "Лекция 8 · сл. 15",
    title: "ลดโหลดลงจนกระแส дроссель แตะศูนย์ — ดูช่วง t_Х และเงื่อนไข ωL ≫ R_н, 1/(ωC) ≪ R_н",
    ratio: 0.76,
    legend: '<span><i style="background:var(--accent-2)"></i>i_L</span><span><i style="background:var(--ok)"></i>I_Н</span><span><i style="background:var(--crit)"></i>t_Х</span>',
    controls: [
      { id: "Rn", label: "R_н, Ом", min: 1, max: 500, step: 1, value: 50 },
      { id: "L", label: "L, мГн", min: 0.01, max: 10, step: 0.01, value: 0.5, fmt: v => eocN(v, 2) },
      { id: "C", label: "C_ВЫХ, мкФ", min: 1, max: 1000, step: 1, value: 100 },
      { id: "f", label: "f_ШИМ, кГц", min: 1, max: 200, step: 1, value: 20 },
      { id: "q", label: "q = t_и/T", min: 0.1, max: 0.9, step: 0.01, value: 0.5, fmt: v => eocN(v, 2) }
    ],
    draw(ctx, w, h, s, readout) {
      const acc2 = CV("--accent-2"), ok = CV("--ok"), crit = CV("--crit"), ink3 = CV("--ink-3"),
            grid = CV("--grid"), line2 = CV("--line-2");
      const font = eocFont(w);
      const Uv = 27, q = s.q, T = 1 / (s.f * 1e3), L = s.L * 1e-3, C = s.C * 1e-6, R = s.Rn;
      const wc = 2 * Math.PI * s.f * 1e3;
      const K = 2 * L / (R * T), Kcr = 1 - q;
      const cont = K > Kcr;
      const M = cont ? q : 2 / (1 + Math.sqrt(1 + 4 * K / (q * q)));
      const Uo = M * Uv, In = Uo / R;
      const dI = (Uv - Uo) * q * T / L;
      const t2 = cont ? (1 - q) : q * (Uv - Uo) / Math.max(Uo, 1e-9);
      const tX = cont ? 0 : Math.max(0, 1 - q - t2);
      const Ipk = cont ? In + dI / 2 : dI;
      const iL = u => {
        const p = u - Math.floor(u);
        if (cont) return p < q ? (In - dI / 2) + (p / q) * dI : (In + dI / 2) - ((p - q) / (1 - q)) * dI;
        if (p < q) return (p / q) * Ipk;
        if (p < q + t2) return Ipk * (1 - (p - q) / t2);
        return 0;
      };

      const x0 = 46, wp = w - 58, nper = 2;
      /* ความสูงของออสซิลโลแกรม = ที่เหลือหลังหักแถบเงื่อนไขสองแถบ — ไม่ให้เหลือที่ว่างท้ายภาพ */
      const hw = Math.max(60, h - 68);
      eocPeriods(ctx, x0, 12, wp, hw, nper, grid);
      if (!cont) for (let r = 0; r < nper; r++) eocSpan(ctx, x0, 12, wp, hw, nper, r + q + t2, r + 1, crit, 0.18);
      const iM = Math.max(Ipk * 1.3, 1e-4);
      eocLev(ctx, x0, 12, wp, hw, 0, 0, iM, line2);
      eocLev(ctx, x0, 12, wp, hw, In, 0, iM, ok, [5, 3]);
      eocW(ctx, x0, 12, wp, hw, nper, iL, 0, iM, acc2, 2);
      eocTxt(ctx, "i_L, А", x0 - 6, 12 + hw / 2, ink3, font, "right");
      eocTxt(ctx, "I_Н = " + eocN(In, 3) + " А", x0 + wp - 2, 12 + hw - (In / iM) * hw - 8, ok, font, "right");
      if (!cont) eocTxt(ctx, "t_Х", x0 + (q + t2 + tX / 2) / nper * wp, 12 + hw - 8, crit, font, "center");
      eocTxt(ctx, "I_М = " + eocN(Ipk, 3) + " А", x0 + 4, 12 + hw - (Ipk / iM) * hw - 8, acc2, font, "left");

      /* แถบเงื่อนไขเลือกฟิลเตอร์ของ сл. 15 */
      const r1 = wc * L / R, r2 = 1 / (wc * C * R);
      ctx.save(); ctx.font = font;
      const labW = Math.max(ctx.measureText("ω·L/R_н").width, ctx.measureText("1/(ωC·R_н)").width);
      ctx.restore();
      /* แถบเริ่มหลังป้าย เพื่อให้ป้ายชิดขวาไม่ล้นขอบซ้ายของผ้าใบ */
      const bx = Math.max(x0, labW + 12);
      const by = 12 + hw + 16, bh = 9, bw = Math.max(50, Math.min(wp * 0.55, w - bx - 92));
      const bar = (y, lab, val, good, txt) => {
        ctx.save(); ctx.fillStyle = CV("--wash"); ctx.fillRect(bx, y, bw, bh);
        ctx.fillStyle = good ? ok : crit;
        ctx.fillRect(bx, y, bw * Math.max(0.04, Math.min(1, val)), bh);
        ctx.restore();
        eocTxt(ctx, lab, bx - 6, y + bh / 2, ink3, font, "right");
        eocTxt(ctx, txt, bx + bw + 6, y + bh / 2, good ? ok : crit, font, "left");
      };
      bar(by, "ω·L/R_н", Math.min(1, r1 / 20), r1 > 10, eocN(r1, 1) + (r1 > 10 ? " ≫ 1" : " — น้อยเกินไป"));
      bar(by + bh + 8, "1/(ωC·R_н)", Math.min(1, r2 / 0.2), r2 < 0.1, eocN(r2, 3) + (r2 < 0.1 ? " ≪ 1" : " — มากเกินไป"));

      readout.innerHTML =
        'режим <b class="' + (cont ? "good" : "bad") + '">' + (cont ? "НТ (непрерывных токов)" : "ПТ (прерывистых токов)") + '</b>' +
        '<span>U<sub>ВЫХ</sub> = <b>' + eocN(Uo, 2) + ' В</b> · q·U<sub>ВХ</sub> = <b>' + eocN(q * Uv, 2) + ' В</b>' +
          (cont ? '' : ' ⇒ สูตรเชิงเส้นใช้ไม่ได้แล้ว') + '</span>' +
        '<span>t_Х = <b>' + eocN(tX * T * 1e6, 1) + ' мкс</b> · I_М = <b>' + eocN(Ipk, 3) + ' А</b></span>' +
        '<span>ω·L = <b>' + eocN(wc * L, 1) + ' Ом</b> เทียบ R_н = ' + eocN(R, 0) + ' Ом · 1/(ω·C) = <b>' + eocN(1 / (wc * C), 3) + ' Ом</b></span>' +
        '<span>' + (cont
          ? 'อยู่ในโหมด НТ — ค่าถ่ายโอนขึ้นกับ q อย่างเดียว ไม่ขึ้นกับโหลด'
          : 'โหลดเบาเกินไป กระแสขาดช่วง — แรงดันขาออกลอยขึ้นตามโหลด ต้องเพิ่ม L หรือ f') + '</span>';
    }
  });
}


/* =====================================================================
   12. eoPWM — Широтно-импульсный модулятор (Л8 сл. 11 · Л10 сл. 16)
       ЗГ → ГЛИН (คลื่นฟันเลื่อย U_г) → компаратор К เทียบกับ U_УПРВХ → พัลส์ U_у ที่กว้าง t_и
       характеристика «вход-выход»: q = k·U_УПРВХ เชิงเส้นจนถึง q = 1 แล้วอิ่มตัว (Л8 сл. 11 в)
       ค่าเฉลี่ยขาออกของ ПН-конвертора: U_ВЫХ = q·U_ВХ (Л8 сл. 12)
   ===================================================================== */
function eoPWM(host) {
  buildDemo(host, {
    label: "Лекция 8 · сл. 11 · Лекция 10 · сл. 16",
    title: "เลื่อนแรงดันควบคุมตัดกับฟันเลื่อย แล้วดูดิวตี้ไซเคิลกับแรงดันเฉลี่ยขาออกเปลี่ยนตาม",
    ratio: 0.82,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>U_г (ฟันเลื่อย)</span><span><i style="background:var(--crit)"></i>U_УПРВХ</span><span><i style="background:var(--ok)"></i>U_у</span><span><i style="background:var(--accent-2)"></i>q(U_УПРВХ)</span>',
    controls: [
      { id: "Uu", label: "U_УПРВХ, В", min: 0, max: 12, step: 0.1, value: 6, fmt: v => eocN(v, 1) },
      { id: "Uv", label: "U_ВХ, В", min: 10, max: 40, step: 1, value: 27 },
      { id: "f", label: "f_ЗГ, кГц", min: 1, max: 50, step: 1, value: 10 }
    ],
    draw(ctx, w, h, s, readout, t) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"), crit = CV("--crit"),
            ink3 = CV("--ink-3"), grid = CV("--grid"), line2 = CV("--line-2");
      const font = eocFont(w);
      const Ugm = 10;                       /* แอมพลิจูดฟันเลื่อยของ ГЛИН — ค่าสมมติ 10 В */
      const q = Math.max(0, Math.min(1, s.Uu / Ugm));
      const T = 1 / (s.f * 1e3), ti = q * T, Uo = q * s.Uv;
      const sh = ((t || 0) * 0.5) % 1;      /* เลื่อนหน้าต่างเวลาให้เห็นการทำงานเป็นรอบ */
      const saw = u => { const p = (u + sh) - Math.floor(u + sh); return Ugm * p; };
      const pulse = u => saw(u) < s.Uu ? 1 : 0;
      const zg = u => { const p = (u + sh) - Math.floor(u + sh); return p > 0.97 ? 1 : 0; };

      const x0 = 46, wp = w - 58, nper = 3;
      const hTop = (h - 30) * 0.56;
      const R3 = eocRows(12, hTop, 3, 6), rh = R3.rh;
      eocPeriods(ctx, x0, R3.ys[0], wp, rh, nper, grid);
      eocLev(ctx, x0, R3.ys[0], wp, rh, 0, -0.15, 1.25, line2);
      eocW(ctx, x0, R3.ys[0], wp, rh, nper, zg, -0.15, 1.25, ink3, 1.4);
      eocTxt(ctx, "U_зг", x0 - 6, R3.ys[0] + rh / 2, ink3, font, "right");

      eocPeriods(ctx, x0, R3.ys[1], wp, rh, nper, grid);
      eocLev(ctx, x0, R3.ys[1], wp, rh, 0, 0, Ugm * 1.2, line2);
      eocW(ctx, x0, R3.ys[1], wp, rh, nper, saw, 0, Ugm * 1.2, acc, 1.8);
      const yc = eocLev(ctx, x0, R3.ys[1], wp, rh, Math.min(s.Uu, Ugm * 1.15), 0, Ugm * 1.2, crit, [5, 3]);
      eocTxt(ctx, "U_г", x0 - 6, R3.ys[1] + rh / 2, ink3, font, "right");
      eocTxt(ctx, "U_УПРВХ = " + eocN(s.Uu, 1) + " В", x0 + wp - 2, yc - 7, crit, font, "right");

      eocPeriods(ctx, x0, R3.ys[2], wp, rh, nper, grid);
      eocLev(ctx, x0, R3.ys[2], wp, rh, 0, -0.15, 1.25, line2);
      eocW(ctx, x0, R3.ys[2], wp, rh, nper, pulse, -0.15, 1.25, ok, 1.8);
      eocTxt(ctx, "U_у", x0 - 6, R3.ys[2] + rh / 2, ink3, font, "right");
      eocTxt(ctx, "откр РЭ", x0 + 4, R3.ys[2] + 8, ok, font, "left");

      /* характеристика «вход-выход» */
      const py0 = 12 + hTop + 24;
      const p = new Plot(ctx, 46, py0, w - 60, h - py0 - 34, 0, 12, 0, 1.15);
      p.frame(ticks(0, 12, 6), eocTicksN(0, 1.15, 4), "U_УПРВХ, В","q");
      const cc = [];
      for (let k = 0; k <= 120; k++) { const u = k / 120 * 12; cc.push([u, Math.min(1, u / Ugm)]); }
      p.clip(() => {
        p.line(cc, acc2, 2);
        p.line([[Ugm, 0], [Ugm, 1.15]], line2, 1, [3, 3]);
      });
      p.dots([[Math.min(s.Uu, 12), q]], crit, 4);
      eocTxt(ctx, "อิ่มตัว", p.X(Ugm) + 4, p.Y(1.08), ink3, font, "left");

      readout.innerHTML =
        'q = t<sub>и</sub>/T = <b>' + eocN(q, 2) + '</b>' +
        '<span>t<sub>и</sub> = <b>' + eocN(ti * 1e6, 1) + ' мкс</b> · T = <b>' + eocN(T * 1e6, 1) + ' мкс</b></span>' +
        '<span>U<sub>ВЫХ</sub> = q·U<sub>ВХ</sub> = <b>' + eocN(Uo, 1) + ' В</b></span>' +
        '<span>' + (q >= 1
          ? '<b class="bad">อิ่มตัว</b> — U_УПРВХ เกินแอมพลิจูดฟันเลื่อย ปรับต่อไม่ได้'
          : '<b class="good">อยู่ในช่วงเชิงเส้น</b> — q แปรตาม U_УПРВХ เป็นเส้นตรง') + '</span>' +
        '<span>ที่นี่ q = t<sub>и</sub>/T ตามนิยามของคอนเวอร์เตอร์ (Л8 сл. 12)</span>';
    }
  });
}


window.EODEMOS = Object.assign(window.EODEMOS || {}, {
  eoInvSingle, eoInvPP, eoInvBridge, eoInvSym, eoInv3ph, eoInvSelf, eoInvExt,
  eoPCH, eoConvBuck, eoConvAll, eoConvMode, eoPWM
});

/* ================= ЭОЛА — กลุ่ม D · Тема 4 «Стабилизаторы напряжения» + Тема 5 «КЗА» =================
   แหล่งสูตรทั้งหมด: notes/L09.md (Л9), notes/L10.md (Л10), notes/L11.md (Л11)
   ทุกฟังก์ชันคำนวณจากสมการของภาควิชาที่อ้างเลขสไลด์ไว้ในคอมเมนต์เหนือฟังก์ชัน
   ค่าที่สไลด์ไม่ได้ให้ (พารามิเตอร์ตัวอย่างของแบบจำลอง) ระบุไว้ใน legend ว่าเป็นของผู้เรียบเรียง */

/* ---- เครื่องมือช่วยวาดเฉพาะกลุ่ม D (ขึ้นต้น eoD เพื่อไม่ชนกับกลุ่มอื่น) ---- */

/* ---- ป้ายค่าบนแกนแบบเลขกลม (แทนการส่ง min/max ดิบเข้า ticks) ---- */
function eoDniceStep(span, n) {
  var raw = Math.abs(span) / Math.max(1, n);
  if (!(raw > 0) || !isFinite(raw)) return 1;
  var e = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), f = raw / e;
  return (f < 1.5 ? 1 : f < 3.5 ? 2 : f < 7.5 ? 5 : 10) * e;
}
function eoDticksN(a, b, n) {
  if (!isFinite(a) || !isFinite(b) || b <= a) return [a, b];
  /* เอนจินพิมพ์ป้ายด้วย toFixed(2) — ก้าวต่ำกว่า 0,01 จะได้ป้ายซ้ำ จึงยกพื้นไว้ */
  var st = Math.max(eoDniceStep(b - a, n), 0.01), out = [], seen = {}, lab,
    k = Math.ceil((a - st * 1e-6) / st), guard = 0, v;
  for (; k * st <= b + st * 1e-6 && guard < 400; k++, guard++) {
    v = +(k * st).toPrecision(12);
    lab = String(+v.toFixed(2));
    if (seen[lab]) continue;
    seen[lab] = 1; out.push(v);
  }
  return out.length >= 2 ? out : [a, b];
}

function eoDn(v, d) {
  var k = (d === undefined) ? 2 : d;
  if (!isFinite(v)) return "∞";
  return v.toFixed(k).replace(".", ",").replace("-", "−");
}
function eoDfs(w) { return w < 430 ? 9 : (w < 560 ? 10 : 11); }
function eoDtx(ctx, x, y, t, color, size, align, baseline, bold) {
  ctx.save();
  ctx.fillStyle = color;
  ctx.font = (bold ? "600 " : "") + size + 'px "IBM Plex Mono", ui-monospace, monospace';
  ctx.textAlign = align || "left";
  ctx.textBaseline = baseline || "top";
  ctx.fillText(t, x, y);
  ctx.restore();
}
function eoDbox(ctx, x, y, w, h, fill, stroke, lw) {
  ctx.save();
  if (fill) { ctx.fillStyle = fill; ctx.fillRect(x, y, w, h); }
  if (stroke) { ctx.strokeStyle = stroke; ctx.lineWidth = lw || 1.2; ctx.strokeRect(Math.round(x) + 0.5, Math.round(y) + 0.5, Math.round(w), Math.round(h)); }
  ctx.restore();
}
function eoDseg(ctx, x1, y1, x2, y2, color, lw, dash) {
  ctx.save();
  ctx.strokeStyle = color; ctx.lineWidth = lw || 1.2;
  if (dash) ctx.setLineDash(dash);
  ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  ctx.restore();
}
function eoDarrow(ctx, x1, y1, x2, y2, color, lw) {
  eoDseg(ctx, x1, y1, x2, y2, color, lw);
  var a = Math.atan2(y2 - y1, x2 - x1), s = 5;
  ctx.save();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x2, y2);
  ctx.lineTo(x2 - s * Math.cos(a - 0.4), y2 - s * Math.sin(a - 0.4));
  ctx.lineTo(x2 - s * Math.cos(a + 0.4), y2 - s * Math.sin(a + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.restore();
}
/* ป้ายแกนนอนแบบกำหนดเอง (ใช้กับแกนลอการิทึม — ต้องเรียก frame ด้วย noX = true) */
function eoDxlab(ctx, p, vals, labs, color, size) {
  for (var i = 0; i < vals.length; i++) eoDtx(ctx, p.X(vals[i]), p.y + p.h + 5, labs[i], color, size, "center", "top");
}
function eoDvline(ctx, p, x, color, dash, lw) {
  eoDseg(ctx, p.X(x), p.y, p.X(x), p.y + p.h, color, lw || 1, dash);
}
function eoDhline(ctx, p, y, color, dash, lw) {
  eoDseg(ctx, p.X(p.xmin), p.Y(y), p.X(p.xmax), p.Y(y), color, lw || 1, dash);
}

/* ============================================================================
   1. eoStabQuality — 6 ตัวชี้วัดใช้งานของ СН
   สูตรทั้งหมดจาก Л9 сл. 12 (สูตร 1–6) อ่านออกจากกราฟสองรูปของ Л9 сл. 13
     (9.1) δu_вых(X) = (δU_вых)_X / U_вых.н
     (9.2) K_ст(U) = (δU_вх / U_вх.н) : ((δU_вых)_U / U_вых.н)
     (9.3) K_ст(I) = (δI_н / I_нн) : ((δU_вых)_I / U_вых.н)   ← สูตรของภาควิชา
     (9.4) r_вых  = (δU_вых)_I / δI_н
     (9.5) K_п    = ΔU_вых / (2 · U_вых.н)
     (9.6) η      = P_вых / (P_вых + P_п)
   แบบจำลองเชิงเส้น: U_вых = U_вых.н + a·(U_вх − U_вх.н) − r_вых·(I_н − I_нн), a = U_вых.н/(K_ст(U)·U_вх.н)
   ค่าคงที่ตัวอย่าง (ผู้เรียบเรียง): U_вх.н = 27 В, U_вых.н = 12 В, I_нн = 2 А, P_упр = 0,3 Вт
============================================================================ */
function eoStabQuality(host) {
  buildDemo(host, {
    label: "Лекция 9 · сл. 12–13",
    title: "เลื่อนคุณภาพของวงจรรักษาระดับ แล้วอ่านตัวชี้วัดทั้ง 6 ตัวออกมาจากกราฟสองรูปของสไลด์ 13",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>U<sub>вых</sub>(U<sub>вх</sub>) при I<sub>н</sub> = I<sub>нн</sub> = const</span>' +
      '<span><i style="background:var(--accent-2)"></i>U<sub>вых</sub>(I<sub>н</sub>) при U<sub>вх</sub> = U<sub>вх.н</sub> = const</span>' +
      '<span>ค่าคงที่ของแบบจำลอง (ผู้เรียบเรียง): U<sub>вх.н</sub> = 27 В · U<sub>вых.н</sub> = 12 В · I<sub>нн</sub> = 2 А · P<sub>упр</sub> = 0,3 Вт</span>' +
      '<span><b>สูตรที่ใช้เป็นของภาควิชา (сл. 12):</b> K<sub>ст</sub>(I) = (δI<sub>н</sub>/I<sub>нн</sub>) : ((δU<sub>вых</sub>)<sub>I</sub>/U<sub>вых.н</sub>) — เป็นอัตราส่วนของสองปริมาณสัมพัทธ์เหมือน K<sub>ст</sub>(U) · ส่วน Конспект ข้อ 20 อธิบายไว้เพียง «การเปลี่ยนแปลงสัมพัทธ์ของแรงดันขาออก» ซึ่งจะได้ <b>ส่วนกลับ</b> ของสูตรจริง</span>',
    controls: [
      { id: "Kst", label: "K<sub>ст</sub>(U) ของวงจร", min: 10, max: 2000, step: 10, value: 200, fmt: function (v) { return v.toFixed(0); } },
      { id: "rout", label: "r<sub>вых</sub>, Ом", min: 0.005, max: 2, step: 0.005, value: 0.05, fmt: function (v) { return eoDn(v, 3); } },
      { id: "dU", label: "δU<sub>вх</sub>, % ของ U<sub>вх.н</sub>", min: 2, max: 40, step: 1, value: 20 },
      { id: "dI", label: "δI<sub>н</sub>, % ของ I<sub>нн</sub>", min: 10, max: 100, step: 5, value: 80 },
      { id: "dUp", label: "ΔU<sub>вых</sub> (размах ริปเปิล), мВ", min: 0, max: 500, step: 5, value: 60 }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), wash = CV("--wash");
      var fs = eoDfs(w);
      var UIN = 27, UOUT = 12, INN = 2, PU = 0.3;
      var a = UOUT / (s.Kst * UIN);                      /* ความชัน dU_вых/dU_вх จาก (9.2) */
      var dUin = UIN * s.dU / 100;
      var dUoutU = a * dUin;                             /* (δU_вых)_U */
      var dIn = INN * s.dI / 100;
      var dUoutI = s.rout * dIn;                         /* (δU_вых)_I จาก (9.4) */
      var duU = dUoutU / UOUT, duI = dUoutI / UOUT;      /* (9.1) */
      var KstU = (dUin / UIN) / (dUoutU / UOUT);         /* (9.2) — ต้องได้เท่าค่าสไลเดอร์ */
      var KstI = (dIn / INN) / (dUoutI / UOUT);          /* (9.3) */
      var Kp = (s.dUp / 1000) / (2 * UOUT);              /* (9.5) */
      var Pout = UOUT * INN, Pp = (UIN - UOUT) * INN + PU;
      var eta = Pout / (Pout + Pp);                      /* (9.6) */
      var span = Math.max(dUoutU, dUoutI, 0.02) * 1.5;
      var ymin = UOUT - span, ymax = UOUT + span;

      var gap = 16, ml = 40, mr = 8, top = 18, bot = 34;
      var pw = (w - ml * 2 - mr - gap) / 2, ph = h - top - bot;
      var p1 = new Plot(ctx, ml, top, pw, ph, UIN - dUin / 2 - dUin * 0.18, UIN + dUin / 2 + dUin * 0.18, ymin, ymax);
      p1.frame(eoDticksN(p1.xmin, p1.xmax, 3), eoDticksN(ymin, ymax, 4), "Uвх, В","Uвых, В");
      var pts1 = [];
      for (var i = 0; i <= 60; i++) {
        var x = p1.xmin + (p1.xmax - p1.xmin) * i / 60;
        pts1.push([x, UOUT + a * (x - UIN)]);
      }
      p1.clip(function () {
        p1.line([[UIN - dUin / 2, ymin], [UIN - dUin / 2, ymax]], line, 1, [3, 3]);
        p1.line([[UIN + dUin / 2, ymin], [UIN + dUin / 2, ymax]], line, 1, [3, 3]);
        p1.line([[p1.xmin, UOUT], [p1.xmax, UOUT]], line, 1, [2, 4]);
        p1.line(pts1, acc, 2.2);
        p1.dots([[UIN, UOUT]], acc, 3.2);
      });
      /* วางไว้ในกรอบเหนือแกน x — เดิมชนกับป้ายแกน «Uвх, В» ที่เอนจินวาดใต้กรอบ */
      eoDtx(ctx, p1.X(UIN - dUin / 2), p1.y + ph - 4, "Uвх min", ink3, fs - 1, "center", "bottom");
      eoDtx(ctx, p1.X(UIN + dUin / 2), p1.y + ph - 4 - (fs + 2), "Uвх max", ink3, fs - 1, "center", "bottom");
      var yA = p1.Y(UOUT + dUoutU / 2), yB = p1.Y(UOUT - dUoutU / 2), xA = p1.x + pw - 8;
      eoDseg(ctx, xA, yA, xA, yB, acc, 1.4);
      eoDseg(ctx, xA - 3, yA, xA + 3, yA, acc, 1.4);
      eoDseg(ctx, xA - 3, yB, xA + 3, yB, acc, 1.4);
      eoDtx(ctx, xA - 5, (yA + yB) / 2, "(δUвых)U", acc, fs - 1, "right", "middle");

      var p2 = new Plot(ctx, ml * 2 + pw + gap - 6, top, pw, ph, 0, INN * 1.06, ymin, ymax);
      p2.frame(eoDticksN(0, INN * 1.06, 3), eoDticksN(ymin, ymax, 4), "Iн, А","Uвых, В");
      var pts2 = [];
      for (var j = 0; j <= 60; j++) {
        var xi = p2.xmin + (p2.xmax - p2.xmin) * j / 60;
        pts2.push([xi, UOUT + s.rout * (INN - xi)]);
      }
      p2.clip(function () {
        p2.line([[INN - dIn, ymin], [INN - dIn, ymax]], line, 1, [3, 3]);
        p2.line([[INN, ymin], [INN, ymax]], line, 1, [3, 3]);
        p2.line([[p2.xmin, UOUT], [p2.xmax, UOUT]], line, 1, [2, 4]);
        p2.line(pts2, acc2, 2.2);
        p2.dots([[INN, UOUT]], acc2, 3.2);
      });
      eoDtx(ctx, p2.X(INN - dIn), p2.y + ph - 4, "Iн min", ink3, fs - 1, "center", "bottom");
      eoDtx(ctx, p2.X(INN), p2.y + ph - 4 - (fs + 2), "Iнн", ink3, fs - 1, "center", "bottom");
      var yC = p2.Y(UOUT + dUoutI), yD = p2.Y(UOUT), xC = p2.x + pw - 8;
      eoDseg(ctx, xC, yC, xC, yD, acc2, 1.4);
      eoDseg(ctx, xC - 3, yC, xC + 3, yC, acc2, 1.4);
      eoDseg(ctx, xC - 3, yD, xC + 3, yD, acc2, 1.4);
      eoDtx(ctx, xC - 5, (yC + yD) / 2, "(δUвых)I", acc2, fs - 1, "right", "middle");
      eoDtx(ctx, p2.x + 4, p2.y + 2, "наклон = rвых", ink, fs - 1, "left", "top");

      var duMax = Math.max(duU, duI) * 100;
      var cls = duMax > 5 ? "низкой точности" :
        (duMax >= 1 ? "средней точности" :
          (duMax >= 0.1 ? "высокой точности" : "прецизионный"));
      readout.innerHTML =
        '<span>δu<sub>вых</sub>(U) = <b>' + eoDn(duU * 100, 3) + ' %</b></span>' +
        '<span>δu<sub>вых</sub>(I) = <b>' + eoDn(duI * 100, 3) + ' %</b></span>' +
        '<span>K<sub>ст</sub>(U) = <b class="' + (KstU >= 100 ? "good" : "bad") + '">' + eoDn(KstU, 0) + '</b></span>' +
        '<span>K<sub>ст</sub>(I) = <b>' + eoDn(KstI, 0) + '</b></span>' +
        '<span>r<sub>вых</sub> = <b class="' + (s.rout <= 0.2 ? "good" : "bad") + '">' + eoDn(s.rout, 3) + ' Ом</b></span>' +
        '<span>K<sub>п</sub> = <b class="' + (Kp <= 0.002 ? "good" : "bad") + '">' + eoDn(Kp * 100, 3) + ' %</b></span>' +
        '<span>η = <b class="' + (eta >= 0.6 ? "good" : "bad") + '">' + eoDn(eta * 100, 1) + ' %</b> (P<sub>п</sub> = ' + eoDn(Pp, 2) + ' Вт)</span>' +
        '<span>шкала точности (сл. 11): <b>' + cls + '</b></span>' +
        '<span>สังเกต: η ต่ำเพราะ РЭ กิน (U<sub>вх</sub> − U<sub>вых</sub>)·I<sub>н</sub> = ' + eoDn((UIN - UOUT) * INN, 1) + ' Вт เป็นความร้อนทั้งหมด</span>';
    }
  });
}

/* ============================================================================
   2. eoStabTrans — ผลตอบสนองชั่วครู่ (Л9 сл. 14)
   สไลด์ให้แนวคิด: выброс / провал · колебательный затухающий процесс · δu_вых ≷ 0 · t_рег
   แบบจำลองอันดับสองของวงป้อนกลับ (ผู้เรียบเรียง — สไลด์ไม่ให้สมการ):
     δu(t) = δu_уст·[1 − e^(−ζω₀t)(cos ω_д t + ζ/√(1−ζ²)·sin ω_д t)]
             + (D − δu_уст)·(1/√(1−ζ²))·e^(−ζω₀t)·sin(ω_д t),  ω₀ = 1/T, ω_д = ω₀√(1−ζ²)
   D = การเบี่ยงเบนถ้าไม่มี ООС · δu_уст = D/(1+K) — ความคลาดเคลื่อนคงค้าง
   เชื่อมกับ сл. 12: K_ст(U) = (1+K)·U_вых.н/U_вх.н · r_вых = r_вых.разомк/(1+K)
   ค่าคงที่ (ผู้เรียบเรียง): U_вх.н = 27 В, U_вых.н = 12 В, I_нн = 2 А, r_вых.разомк = 5 Ом
   เกณฑ์ t_рег: ±5 % ของขนาดการเบี่ยงเบนสูงสุด
============================================================================ */
function eoStabTrans(host) {
  buildDemo(host, {
    label: "Лекция 9 · сл. 14",
    title: "กระโดด U<sub>вх</sub> หรือ I<sub>н</sub> แล้วดู выброс / провал, δu<sub>вых</sub> ที่ค้างอยู่ และ t<sub>рег</sub>",
    ratio: 0.56,
    legend: '<span><i style="background:var(--accent)"></i>u<sub>вых</sub>(t)</span>' +
      '<span><i style="background:var(--accent-2)"></i>ระดับคงตัวใหม่ (U<sub>вых.н</sub> + δu<sub>вых</sub>)</span>' +
      '<span><i style="background:var(--line-2)"></i>แถบ ±5 % ของการเบี่ยงเบนสูงสุด — ใช้วัด t<sub>рег</sub></span>' +
      '<span>แบบจำลองอันดับสองและเกณฑ์ ±5 % เป็นของ <b>ผู้เรียบเรียง</b> (สไลด์ 14 ให้เพียงรูปเชิงคุณภาพ) · ค่าคงที่: U<sub>вх.н</sub> = 27 В, U<sub>вых.н</sub> = 12 В, I<sub>нн</sub> = 2 А, r<sub>вых</sub> วงเปิด = 5 Ом</span>',
    controls: [
      { id: "K", label: "K — อัตราขยายของลูป", min: 1, max: 300, step: 1, value: 50 },
      { id: "z", label: "ζ — อัตราส่วนการหน่วง", min: 0.05, max: 0.95, step: 0.01, value: 0.3, fmt: function (v) { return eoDn(v, 2); } },
      { id: "T", label: "T — ค่าคงตัวเวลา, мс", min: 0.1, max: 20, step: 0.1, value: 2, fmt: function (v) { return eoDn(v, 1); } },
      { id: "d", label: "ขนาดการรบกวน, %", min: 5, max: 50, step: 1, value: 20 }
    ],
    buttons: [
      { id: "byI", label: "возмущение по IН", toggle: true, value: false },
      { id: "neg", label: "знак «−»", toggle: true, value: false }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok");
      var fs = eoDfs(w);
      var UIN = 27, UOUT = 12, INN = 2, R0 = 5;
      var K = s.K, z = s.z, T = s.T / 1000;
      var sign = s.neg ? -1 : 1;
      var D, dust, lab, KstU, rout;
      rout = R0 / (1 + K);
      KstU = (1 + K) * UOUT / UIN;
      if (s.byI) {
        var dI = INN * s.d / 100;
        D = sign * dI * R0;                       /* ถ้าไม่มี ООС แรงดันจะเบี่ยงเท่านี้ */
        dust = D / (1 + K);                       /* = ±δI_н · r_вых */
        lab = "скачок IН " + (s.neg ? "+" : "−") + eoDn(dI, 2) + " А";
      } else {
        var dU = UIN * s.d / 100;
        D = sign * dU;
        dust = D / (1 + K);
        lab = "скачок UВХ " + (s.neg ? "−" : "+") + eoDn(dU, 1) + " В";
      }
      var wd = Math.sqrt(1 - z * z) / T, w0 = 1 / T;
      var tmax = Math.min(0.5, Math.max(8 * T, 5 * T / z));
      var N = 700, pts = [], peak = 0, tset = 0;
      var band, k;
      var vals = [];
      for (k = 0; k <= N; k++) {
        var t = tmax * k / N;
        var e = Math.exp(-z * w0 * t);
        var v1 = dust * (1 - e * (Math.cos(wd * t) + z / Math.sqrt(1 - z * z) * Math.sin(wd * t)));
        var v2 = (D - dust) * (1 / Math.sqrt(1 - z * z)) * e * Math.sin(wd * t);
        var v = v1 + v2;
        vals.push([t, v]);
        if (Math.abs(v) > Math.abs(peak)) peak = v;
      }
      band = Math.abs(peak) * 0.05;
      for (k = vals.length - 1; k >= 0; k--) {
        if (Math.abs(vals[k][1] - dust) > band) { tset = vals[k][0]; break; }
      }
      var amp = Math.max(Math.abs(peak), Math.abs(dust)) * 1.35 + 1e-4;
      var ymin = UOUT - amp, ymax = UOUT + amp;
      var tpre = tmax * 0.14;
      var p = new Plot(ctx, 46, 18, w - 62, h - 52, -tpre * 1000, tmax * 1000, ymin, ymax);
      p.frame(eoDticksN(-tpre * 1000, tmax * 1000, 5), eoDticksN(ymin, ymax, 4), "t, мс","uвых, В");
      var curve = [[-tpre * 1000, UOUT], [0, UOUT]];
      for (k = 0; k < vals.length; k++) curve.push([vals[k][0] * 1000, UOUT + vals[k][1]]);
      p.clip(function () {
        p.band([[0, UOUT + dust + band, UOUT + dust - band], [tmax * 1000, UOUT + dust + band, UOUT + dust - band]], CV("--wash-2"));
        p.line([[-tpre * 1000, UOUT], [tmax * 1000, UOUT]], line, 1, [2, 4]);
        p.line([[0, UOUT + dust], [tmax * 1000, UOUT + dust]], acc2, 1.4, [5, 4]);
        p.line(curve, acc, 2.2);
        p.line([[0, ymin], [0, ymax]], crit, 1.2, [3, 3]);
        if (tset > 0) p.line([[tset * 1000, ymin], [tset * 1000, ymax]], ok, 1.4, [4, 3]);
      });
      eoDtx(ctx, p.X(0) + 3, p.y + 2, "возмущение", crit, fs - 1, "left", "top");
      if (tset > 0) eoDtx(ctx, p.X(tset * 1000) + 3, p.y + 2 + fs + 2, "tрег", ok, fs - 1, "left", "top");
      eoDtx(ctx, p.x + 4, p.y + p.h - 4, lab, ink, fs - 1, "left", "bottom");
      var yPk = p.Y(UOUT + peak);
      eoDseg(ctx, p.X(0), yPk, p.X(tmax * 1000), yPk, acc, 1, [2, 3]);
      eoDtx(ctx, p.x + p.w - 4, yPk + (peak > 0 ? -3 : 3), (peak > 0 ? "выброс" : "провал"), acc, fs - 1, "right", peak > 0 ? "bottom" : "top");

      readout.innerHTML =
        '<span>выброс / провал = <b>' + eoDn(peak, 3) + ' В</b> (' + eoDn(Math.abs(peak) / UOUT * 100, 2) + ' %)</span>' +
        '<span>δu<sub>вых</sub> уст. = <b class="' + (Math.abs(dust) / UOUT < 0.01 ? "good" : "bad") + '">' + (dust >= 0 ? "+" : "") + eoDn(dust, 4) + ' В</b> (' + eoDn(dust / UOUT * 100, 3) + ' %)</span>' +
        '<span>t<sub>рег</sub> = <b>' + eoDn(tset * 1000, 2) + ' мс</b></span>' +
        '<span>K<sub>ст</sub>(U) = <b>' + eoDn(KstU, 0) + '</b> · r<sub>вых</sub> = <b>' + eoDn(rout, 3) + ' Ом</b></span>' +
        '<span>ข้อแลกเปลี่ยน: เพิ่ม K → δu<sub>вых</sub> เล็กลง (แม่นยำสถิตดีขึ้น) แต่ выброс ยังโตเท่าเดิมและ t<sub>рег</sub> ยาวขึ้น — นี่คือเหตุผลที่ сл. 14 แยก <b>динамические свойства</b> ออกจาก <b>статическая точность</b> ของ сл. 12–13 คนละมิติกัน</span>' +
        '<span>ในวงจรจริง K มีค่าหลายร้อย ทำให้ δu<sub>вых</sub> เล็กมากจนแทบมองไม่เห็นบนกราฟ แต่ выброс ยังคงเห็นชัด — ตรงกับรูปของ сл. 14</span>';
    }
  });
}

/* ============================================================================
   3. eoStabZener — параметрический СН на стабилитроне (Л9 сл. 17 วงจรบน)
   สมการบนสไลด์:
     (9.8)  U_вх = U_б + U_вых
     (9.9)  U_б = I_б·R_б
     (9.10) I_б = I_ст + I_н
     (9.11) U_вх = R_б·(I_ст + I_н) + U_вых
   แบบจำลอง ВАХ ของซีเนอร์ในย่านพังทลาย (ผู้เรียบเรียง): U_ст = U_ст0 + r_д·I_ст
     ⇒ I_ст = (U_вх − U_ст0 − R_б·I_н)/(R_б + r_д) ,  U_вых = U_ст0 + r_д·I_ст
   ผลที่ derive ได้ (ผู้เรียบเรียง จาก (9.11) + นิยาม сл. 12):
     K_ст(U) = (R_б + r_д)/r_д · U_вых/U_вх ;  r_вых = r_д·R_б/(r_д + R_б)
   ค่าจำกัด (ผู้เรียบเรียง): I_ст.min = 3 мА, P_доп ของซีเนอร์ = 0,5 Вт
============================================================================ */
function eoStabZener(host) {
  buildDemo(host, {
    label: "Лекция 9 · сл. 17 (верхняя схема)",
    title: "เลื่อน R<sub>б</sub> และ I<sub>н</sub> ดูจุดทำงานวิ่งบน ВАХ ของซีเนอร์ไดโอด พร้อม K<sub>ст</sub>, r<sub>вых</sub> และกำลังสูญเสีย",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>ВАХ ของซีเนอร์ไดโอด (стабилитрон)</span>' +
      '<span><i style="background:var(--accent-2)"></i>прямая нагрузки ของ R<sub>б</sub> — จากสมการ (сл. 17-4)</span>' +
      '<span><i style="background:var(--ok)"></i>U<sub>вых</sub>(U<sub>вх</sub>) ที่ได้จริง</span>' +
      '<span>ค่าจำกัดที่ใช้ตรวจ (ผู้เรียบเรียง): I<sub>ст.min</sub> = 3 мА · P<sub>доп</sub> ของซีเนอร์ = 0,5 Вт · แบบจำลอง ВАХ ใช้ U<sub>ст</sub> = U<sub>ст0</sub> + r<sub>д</sub>·I<sub>ст</sub></span>',
    controls: [
      { id: "Uin", label: "U<sub>вх</sub>, В", min: 8, max: 40, step: 0.5, value: 27, fmt: function (v) { return eoDn(v, 1); } },
      { id: "Rb", label: "R<sub>б</sub>, Ом", min: 50, max: 2000, step: 10, value: 470, fmt: function (v) { return v.toFixed(0); } },
      { id: "In", label: "I<sub>н</sub>, мА", min: 0, max: 60, step: 1, value: 20 },
      { id: "Ust", label: "U<sub>ст0</sub>, В", min: 4.7, max: 15, step: 0.1, value: 9.1, fmt: function (v) { return eoDn(v, 1); } },
      { id: "rd", label: "r<sub>д</sub>, Ом", min: 2, max: 50, step: 1, value: 10 }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok");
      var fs = eoDfs(w);
      var Rb = s.Rb, rd = s.rd, In = s.In / 1000, U0 = s.Ust;
      function solve(uin) {
        var ist = (uin - U0 - Rb * In) / (Rb + rd);
        if (ist <= 0) return { ist: 0, u: Math.max(0, uin - Rb * In), reg: false };
        return { ist: ist, u: U0 + rd * ist, reg: true };
      }
      var st = solve(s.Uin);
      var Imax = 0.5 / U0;                                  /* จาก P_доп = 0,5 Вт */
      var Imin = 0.003;
      var KstU = (Rb + rd) / rd * (st.u / s.Uin);           /* (สูตร сл. 12 ข้อ 2) */
      var rvyh = rd * Rb / (rd + Rb);                       /* (สูตร сл. 12 ข้อ 4) */
      var Pb = (st.ist + In) * (st.ist + In) * Rb;
      var Pst = st.u * st.ist;
      var Pn = st.u * In;
      var eta = Pn / Math.max(1e-9, Pn + Pb + Pst);

      var gap = 16, ml = 42, mr = 10, top = 18, bot = 32;
      var pw = (w - ml * 2 - mr - gap) / 2, ph = h - top - bot;
      var imA = Math.max(Imax * 1000 * 1.15, st.ist * 1000 * 1.15, 12);
      var p1 = new Plot(ctx, ml, top, pw, ph, 0, U0 * 1.35, 0, imA);
      p1.frame(eoDticksN(0, U0 * 1.35, 3), eoDticksN(0, imA, 4), "Uст, В","Iст, мА");
      var vax = [], ll = [], i;
      for (i = 0; i <= 80; i++) {
        var u = p1.xmin + (p1.xmax - p1.xmin) * i / 80;
        vax.push([u, u < U0 ? 0 : (u - U0) / rd * 1000]);
        ll.push([u, ((s.Uin - u) / Rb - In) * 1000]);
      }
      p1.clip(function () {
        p1.line([[p1.xmin, Imax * 1000], [p1.xmax, Imax * 1000]], crit, 1, [4, 3]);
        p1.line([[p1.xmin, Imin * 1000], [p1.xmax, Imin * 1000]], line, 1, [4, 3]);
        p1.line(vax, acc, 2.2);
        p1.line(ll, acc2, 1.8);
        p1.dots([[st.u, st.ist * 1000]], st.reg ? ok : crit, 3.6);
      });
      eoDtx(ctx, p1.x + p1.w - 3, p1.Y(Imax * 1000) - 2, "Iст max", crit, fs - 1, "right", "bottom");
      eoDtx(ctx, p1.x + p1.w - 3, p1.Y(Imin * 1000) - 2, "Iст min", ink3, fs - 1, "right", "bottom");

      var p2 = new Plot(ctx, ml * 2 + pw + gap - 8, top, pw, ph, 0, 40, 0, Math.max(U0 * 1.6, 16));
      p2.frame(eoDticksN(0, 40, 4), eoDticksN(0, Math.max(U0 * 1.6, 16), 4), "Uвх, В","Uвых, В");
      var cu = [];
      for (i = 0; i <= 100; i++) {
        var x = 40 * i / 100;
        cu.push([x, solve(x).u]);
      }
      p2.clip(function () {
        p2.line(cu, ok, 2.2);
        p2.line([[s.Uin, 0], [s.Uin, 99]], line, 1, [3, 3]);
        p2.dots([[s.Uin, st.u]], ok, 3.4);
      });
      eoDtx(ctx, p2.x + 4, p2.y + 2, "участок стабилизации", ink, fs - 1, "left", "top");

      var warn = "";
      if (!st.reg) warn = '<span class="bad">ซีเนอร์หลุดจากย่านพังทลาย — Iст = 0 ไม่มีการรักษาระดับแรงดัน</span>';
      else if (st.ist < Imin) warn = '<span class="bad">I<sub>ст</sub> &lt; I<sub>ст.min</sub> — จุดทำงานหลุดออกจากช่วงชัน</span>';
      else if (st.ist > Imax) warn = '<span class="bad">I<sub>ст</sub> &gt; I<sub>ст.max</sub> — ซีเนอร์เกินกำลัง P<sub>доп</sub></span>';
      else warn = '<span class="good">จุดทำงานอยู่ในช่วงที่ถูกต้อง</span>';
      readout.innerHTML =
        '<span>U<sub>вых</sub> = <b>' + eoDn(st.u, 2) + ' В</b></span>' +
        '<span>I<sub>ст</sub> = <b>' + eoDn(st.ist * 1000, 1) + ' мА</b> · I<sub>б</sub> = ' + eoDn((st.ist + In) * 1000, 1) + ' мА</span>' +
        '<span>U<sub>б</sub> = <b>' + eoDn((st.ist + In) * Rb, 2) + ' В</b></span>' +
        '<span>K<sub>ст</sub>(U) = <b>' + eoDn(st.reg ? KstU : 1, 1) + '</b></span>' +
        '<span>r<sub>вых</sub> = <b>' + eoDn(rvyh, 2) + ' Ом</b></span>' +
        '<span>P<sub>Rб</sub> = <b>' + eoDn(Pb, 2) + ' Вт</b> · P<sub>VD</sub> = <b>' + eoDn(Pst, 2) + ' Вт</b> · P<sub>н</sub> = ' + eoDn(Pn, 2) + ' Вт</span>' +
        '<span>η = <b class="' + (eta > 0.4 ? "good" : "bad") + '">' + eoDn(eta * 100, 1) + ' %</b></span>' + warn;
    }
  });
}

/* ============================================================================
   4. eoStabTr — параметрический транзисторный СН (эмиттерный повторитель со стабилитроном)
   วงจรอยู่ที่ Л9 сл. 17 (วงจรล่างของสไลด์เดียวกัน) · เทียบโครงสร้างกับ сл. 19–20
   สมการที่ใช้ (จาก сл. 17 + กฎกระแสของ Кирхгоф · การแยกส่วนเป็นของผู้เรียบเรียง):
     I_б = I_н/(β+1)                       — โหลดถูกจ่ายผ่านทรานซิสเตอร์ ไม่ผ่านซีเนอร์
     I_ст = (U_вх − U_ст0 − R·I_б)/(R + r_д)
     U_б  = U_ст0 + r_д·I_ст ;   U_вых = U_б − U_эб    (U_эб ≈ 0,7 В)
     r_вых ≈ (r_д ‖ R)/(β+1) + φ_т/I_н     (φ_т = 0,026 В — ผู้เรียบเรียง)
   เทียบกับวงจรบนของ сл. 17 ที่โหลดดึงกระแสผ่านตัวต้านทานบัลลาสต์โดยตรง
============================================================================ */
function eoStabTr(host) {
  buildDemo(host, {
    label: "Лекция 9 · сл. 17 (нижняя схема)",
    title: "เทียบวงจรพารามิเตอร์สองแบบ: ซีเนอร์ล้วน กับ ซีเนอร์ + ทรานซิสเตอร์ — ใครรับกระแสโหลดได้มากกว่า",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>วงจรซีเนอร์ล้วน (сл. 17 บน)</span>' +
      '<span><i style="background:var(--accent-2)"></i>วงจรทรานซิสเตอร์ (сл. 17 ล่าง)</span>' +
      '<span>ซ้าย: U<sub>вых</sub>(I<sub>н</sub>) · ขวา: I<sub>ст</sub>(I<sub>н</sub>) — เห็นได้ว่าวงจรทรานซิสเตอร์ดึงจากซีเนอร์เพียง I<sub>б</sub> = I<sub>н</sub>/(β+1)</span>' +
      '<span>ผู้เรียบเรียงเสริม: U<sub>эб</sub> = 0,7 В · r<sub>вых</sub> คำนวณจาก (r<sub>д</sub> ‖ R)/(β+1) + 0,026/I<sub>н</sub> · I<sub>ст.min</sub> = 3 мА — สไลด์ 17 ไม่ให้สูตรเชิงปริมาณ</span>',
    controls: [
      { id: "Uin", label: "U<sub>вх</sub>, В", min: 10, max: 40, step: 0.5, value: 27, fmt: function (v) { return eoDn(v, 1); } },
      { id: "R", label: "R (บัลลาสต์), Ом", min: 100, max: 5000, step: 20, value: 1000, fmt: function (v) { return v.toFixed(0); } },
      { id: "In", label: "I<sub>н</sub>, А", min: 0.01, max: 2, step: 0.01, value: 0.5, fmt: function (v) { return eoDn(v, 2); } },
      { id: "b", label: "β ของ VT", min: 10, max: 200, step: 5, value: 50 },
      { id: "Ust", label: "U<sub>ст0</sub>, В", min: 4.7, max: 15, step: 0.1, value: 9.1, fmt: function (v) { return eoDn(v, 1); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok");
      var fs = eoDfs(w);
      var R = s.R, rd = 10, U0 = s.Ust, UEB = 0.7, IMIN = 0.003;
      function plain(In) {                       /* วงจรบน — โหลดขนานกับซีเนอร์ */
        var ist = (s.Uin - U0 - R * In) / (R + rd);
        if (ist <= 0) return { u: Math.max(0, s.Uin - R * In), ist: 0, reg: false };
        return { u: U0 + rd * ist, ist: ist, reg: ist >= IMIN };
      }
      function tr(In) {                          /* วงจรล่าง — โหลดผ่านคอลเลกเตอร์ของ VT */
        var ib = In / (s.b + 1);
        var ist = (s.Uin - U0 - R * ib) / (R + rd);
        if (ist <= 0) return { u: Math.max(0, s.Uin - R * ib - UEB), ist: 0, ib: ib, reg: false };
        return { u: U0 + rd * ist - UEB, ist: ist, ib: ib, reg: ist >= IMIN };
      }
      var a = plain(s.In), b = tr(s.In);
      var rP = rd * R / (rd + R);
      var rT = rP / (s.b + 1) + 0.026 / Math.max(s.In, 0.01);
      var Pvt = (s.Uin - b.u) * s.In;
      var InMaxP = (s.Uin - U0 - (R + rd) * IMIN) / R;
      var InMaxT = InMaxP * (s.b + 1);

      var gap = 16, ml = 42, mr = 10, top = 18, bot = 32;
      var pw = (w - ml * 2 - mr - gap) / 2, ph = h - top - bot;
      var imax = 2, i, ca = [], cb = [], sa = [], sb = [];
      for (i = 0; i <= 100; i++) {
        var x = imax * i / 100;
        ca.push([x, plain(x).u]); cb.push([x, tr(x).u]);
        sa.push([x, plain(x).ist * 1000]); sb.push([x, tr(x).ist * 1000]);
      }
      var p1 = new Plot(ctx, ml, top, pw, ph, 0, imax, 0, Math.max(U0 * 1.5, 14));
      p1.frame(ticks(0, imax, 4), eoDticksN(0, Math.max(U0 * 1.5, 14), 4), "Iн, А","Uвых, В");
      p1.clip(function () {
        p1.line(ca, acc, 2.2);
        p1.line(cb, acc2, 2.2);
        p1.line([[s.In, 0], [s.In, 99]], line, 1, [3, 3]);
        p1.dots([[s.In, a.u]], acc, 3.2);
        p1.dots([[s.In, b.u]], acc2, 3.2);
      });
      var p2 = new Plot(ctx, ml * 2 + pw + gap - 8, top, pw, ph, 0, imax, 0, 40);
      p2.frame(ticks(0, imax, 4), eoDticksN(0, 40, 4), "Iн, А","Iст, мА");
      p2.clip(function () {
        p2.line([[0, IMIN * 1000], [imax, IMIN * 1000]], line, 1, [4, 3]);
        p2.line(sa, acc, 2.2);
        p2.line(sb, acc2, 2.2);
        p2.line([[s.In, 0], [s.In, 99]], line, 1, [3, 3]);
      });
      eoDtx(ctx, p2.x + p2.w - 3, p2.Y(IMIN * 1000) - 2, "Iст min", ink3, fs - 1, "right", "bottom");

      readout.innerHTML =
        '<span>ซีเนอร์ล้วน: U<sub>вых</sub> = <b class="' + (a.reg ? "good" : "bad") + '">' + eoDn(a.u, 2) + ' В</b> · I<sub>ст</sub> = ' + eoDn(a.ist * 1000, 1) + ' мА · r<sub>вых</sub> = ' + eoDn(rP, 2) + ' Ом' + (a.reg ? '' : ' — <b class="bad">หลุดการรักษาระดับ</b> เพราะกระแสโหลดทั้งก้อนไหลผ่าน R จนไม่เหลือให้ซีเนอร์') + '</span>' +
        '<span>ทรานซิสเตอร์: U<sub>вых</sub> = <b class="' + (b.reg ? "good" : "bad") + '">' + eoDn(b.u, 2) + ' В</b> · I<sub>ст</sub> = ' + eoDn(b.ist * 1000, 1) + ' мА · I<sub>б</sub> = ' + eoDn(b.ib * 1000, 2) + ' мА</span>' +
        '<span>r<sub>вых</sub> ของวงจรทรานซิสเตอร์ = <b class="good">' + eoDn(rT, 3) + ' Ом</b> (เล็กลงราว β+1 เท่า)</span>' +
        '<span>I<sub>н</sub> สูงสุดที่ยังรักษาระดับได้: ซีเนอร์ล้วน <b>' + eoDn(Math.max(0, InMaxP), 3) + ' А</b> · ทรานซิสเตอร์ <b>' + eoDn(Math.max(0, InMaxT), 2) + ' А</b></span>' +
        '<span>P<sub>VT</sub> = U<sub>кэ</sub>·I<sub>н</sub> = <b class="' + (Pvt < 5 ? "good" : "bad") + '">' + eoDn(Pvt, 2) + ' Вт</b> — ความร้อนทั้งหมดตกที่ทรานซิสเตอร์ (ข้อเสียของ РЭ ที่ทำงานต่อเนื่อง)</span>';
    }
  });
}

/* ============================================================================
   5. eoStabComp — компенсационный СН (Э1/Э2/Э3): ИОН + СУ + УП + РЭ + Д พร้อม ООС
   โครงสร้างบล็อกจาก Л9 сл. 19 · ผังฟังก์ชันจาก сл. 20 · วงจรจริงและโซ่เหตุผลจาก сл. 21
     สัญญาณผิดพลาด (сл. 21-3 ในรูปทั่วไป):  x = U_оп − K_д·U_вых
     สมดุลแรงดันของ РЭ (сл. 21-1):          U_вх = U_кэ1 + U_вых
   แบบจำลองวงปิด (ผู้เรียบเรียง — สไลด์ให้เพียงโซ่ ↑↓):
     U_вых = (K·U_оп + U_вх − r₀·I_н)/(1 + K·K_д) ;  K_д = R₂/(R₁+R₂)
     K_ст(U) = (1 + K·K_д)·U_вых/U_вх ;  r_вых = r₀/(1 + K·K_д)
   เสถียรภาพ (ผู้เรียบเรียงเสริม — เกณฑ์ Гурвиц ของ ТАУ สำหรับลูปสามค่าคงตัวเวลา):
     K_кр = (T₁T₂ + T₁T₃ + T₂T₃)(T₁+T₂+T₃)/(T₁T₂T₃) − 1 ,  T₂ = 20 мкс, T₃ = 5 мкс
============================================================================ */
function eoStabComp(host) {
  buildDemo(host, {
    label: "Лекция 9 · сл. 19–22",
    title: "เลื่อนอัตราขยายของลูป ООС แล้วดู K<sub>ст</sub> โตขึ้นพร้อมกับขอบเขตเสถียรภาพที่แคบลง",
    ratio: 0.62,
    legend: '<span><i style="background:var(--accent)"></i>เส้นทางไปข้างหน้า ИОН → СУ → УП → РЭ → объект</span>' +
      '<span><i style="background:var(--accent-2)"></i>ป้อนกลับลบ ООС ผ่าน Д (делитель R₁/R₂)</span>' +
      '<span>ค่าคงที่ (ผู้เรียบเรียง): r₀ วงเปิด = 5 Ом · I<sub>н</sub> = 1 А · T₂ = 20 мкс · T₃ = 5 мкс · เกณฑ์เสถียรภาพเป็นของ ТАУ (Гурвиц) ไม่ใช่ของสไลด์ Л9</span>',
    controls: [
      { id: "K", label: "K — อัตราขยายของ УП+РЭ", min: 10, max: 2000, step: 10, value: 500 },
      { id: "Kd", label: "K<sub>д</sub> = R₂/(R₁+R₂)", min: 0.1, max: 1, step: 0.01, value: 0.5, fmt: function (v) { return eoDn(v, 2); } },
      { id: "Uop", label: "U<sub>оп</sub> (ИОН), В", min: 4, max: 10, step: 0.1, value: 6, fmt: function (v) { return eoDn(v, 1); } },
      { id: "Uin", label: "U<sub>вх</sub>, В", min: 15, max: 40, step: 0.5, value: 27, fmt: function (v) { return eoDn(v, 1); } },
      { id: "T1", label: "T₁ — ค่าคงตัวเวลาของวงจรแก้ไข, мс", min: 0.05, max: 5, step: 0.05, value: 1, fmt: function (v) { return eoDn(v, 2); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok"), panel = CV("--panel-2"), wash = CV("--wash");
      var fs = eoDfs(w);
      var R0 = 5, IN = 1;
      var depth = 1 + s.K * s.Kd;
      var Uout = (s.K * s.Uop + s.Uin - R0 * IN) / depth;
      var x = s.Uop - s.Kd * Uout;
      var Uke = s.Uin - Uout;
      var KstU = depth * Uout / s.Uin;
      var rout = R0 / depth;
      var T1 = s.T1 / 1000, T2 = 20e-6, T3 = 5e-6;
      var Kkr = (T1 * T2 + T1 * T3 + T2 * T3) * (T1 + T2 + T3) / (T1 * T2 * T3) - 1;
      var Kloop = s.K * s.Kd;
      var stable = Kloop < Kkr;

      /* ---- ผังบล็อก Э1 (сл. 19) ---- */
      var by = 22, bh = Math.min(34, h * 0.17);
      var n = 5, pad = 6;
      var bw = (w - pad * (n + 1)) / n;
      var names = ["1 ИОН", "2 СУ", "4 УП", "5 РЭ", "6 Объект"];
      var subs = ["Uоп = " + eoDn(s.Uop, 2) + " В", "x = " + eoDn(x * 1000, 1) + " мВ", "K = " + s.K.toFixed(0), "Uкэ = " + eoDn(Uke, 2) + " В", "Uвых = " + eoDn(Uout, 2) + " В"];
      var i, bx;
      for (i = 0; i < n; i++) {
        bx = pad + i * (bw + pad);
        var hl = (i === 3 && Uke < 0.5) || (i === 2 && !stable);
        eoDbox(ctx, bx, by, bw, bh, hl ? CV("--wash-2") : panel, hl ? crit : line, hl ? 1.8 : 1.2);
        eoDtx(ctx, bx + bw / 2, by + 5, names[i], ink, fs, "center", "top", true);
        eoDtx(ctx, bx + bw / 2, by + bh - 5, subs[i], ink3, fs - 1, "center", "bottom");
        if (i < n - 1) eoDarrow(ctx, bx + bw, by + bh / 2, bx + bw + pad, by + bh / 2, acc, 1.6);
      }
      /* เส้นป้อนกลับผ่าน Д */
      var fy = by + bh + 22;
      var dx0 = pad + 1.6 * (bw + pad), dw = bw * 0.9;
      eoDseg(ctx, pad + 4 * (bw + pad) + bw / 2, by + bh, pad + 4 * (bw + pad) + bw / 2, fy + bh * 0.5, acc2, 1.6);
      eoDseg(ctx, pad + 4 * (bw + pad) + bw / 2, fy + bh * 0.5, dx0 + dw, fy + bh * 0.5, acc2, 1.6);
      eoDbox(ctx, dx0, fy, dw, bh * 0.72, panel, acc2, 1.4);
      eoDtx(ctx, dx0 + dw / 2, fy + bh * 0.36, "3 Д · Kд = " + eoDn(s.Kd, 2), acc2, fs - 1, "center", "middle");
      eoDseg(ctx, dx0, fy + bh * 0.36, pad + (bw + pad) + bw / 2, fy + bh * 0.36, acc2, 1.6);
      eoDarrow(ctx, pad + (bw + pad) + bw / 2, fy + bh * 0.36, pad + (bw + pad) + bw / 2, by + bh + 2, acc2, 1.6);
      eoDtx(ctx, pad + (bw + pad) + bw / 2 + 5, fy + bh * 0.36 - 12, "ООС", acc2, fs - 1, "left", "middle");
      eoDtx(ctx, w - pad, by - 2, "ΔUвх, ΔIн — возмущающие воздействия", ink3, fs - 1, "right", "bottom");

      /* ---- แถบเสถียรภาพ ---- */
      var sy = fy + bh + 16, sh = Math.max(16, h - sy - 24);
      var sx = 46, sw = w - sx - 14;
      var lo = Math.log10(10), hi = Math.log10(Math.max(Kkr, Kloop) * 3);
      function XX(v) { return sx + (Math.log10(Math.max(v, 10)) - lo) / (hi - lo) * sw; }
      eoDbox(ctx, sx, sy, sw, sh, wash, line, 1);
      eoDbox(ctx, sx, sy, Math.max(0, XX(Kkr) - sx), sh, CV("--wash-2"), null, 0);
      eoDseg(ctx, XX(Kkr), sy - 4, XX(Kkr), sy + sh + 4, crit, 1.8);
      eoDtx(ctx, XX(Kkr) - 4, sy + sh / 2, "Kкр = " + eoDn(Kkr, 0), crit, fs - 1, "right", "middle");
      eoDseg(ctx, XX(Kloop), sy - 6, XX(Kloop), sy + sh + 6, stable ? ok : crit, 2.2);
      eoDtx(ctx, XX(Kloop) + 5, sy + sh / 2, "K·Kд = " + eoDn(Kloop, 0), stable ? ok : crit, fs - 1, "left", "middle");
      eoDtx(ctx, sx, sy - 8, "устойчивость", ink3, fs - 1, "left", "bottom");

      readout.innerHTML =
        '<span>U<sub>вых</sub> = <b>' + eoDn(Uout, 3) + ' В</b> (U<sub>оп</sub>/K<sub>д</sub> = ' + eoDn(s.Uop / s.Kd, 2) + ' В)</span>' +
        '<span>x = U<sub>оп</sub> − K<sub>д</sub>U<sub>вых</sub> = <b>' + eoDn(x * 1000, 2) + ' мВ</b></span>' +
        '<span>глубина ООС = 1 + K·K<sub>д</sub> = <b>' + eoDn(depth, 0) + '</b></span>' +
        '<span>K<sub>ст</sub>(U) = <b>' + eoDn(KstU, 0) + '</b> · r<sub>вых</sub> = <b>' + eoDn(rout, 4) + ' Ом</b></span>' +
        '<span>U<sub>кэ1</sub> = <b class="' + (Uke > 1.5 ? "good" : "bad") + '">' + eoDn(Uke, 2) + ' В</b> · P<sub>РЭ</sub> = ' + eoDn(Uke * IN, 2) + ' Вт</span>' +
        '<span>เสถียรภาพ: <b class="' + (stable ? "good" : "bad") + '">' + (stable ? "устойчив" : "неустойчив — ตัวเลขคำนวณได้แต่วงจรจริงจะแกว่งเอง") + '</b></span>' +
        (Uke <= 1.5 ? '<span class="bad">U<sub>кэ1</sub> ต่ำเกิน — РЭ เข้าสู่ насыщение เหมือนแถวที่ 3 ของตารางความบกพร่อง (сл. 23)</span>' : '');
    }
  });
}

/* ============================================================================
   6. eoStabFault — ตารางความบกพร่องของ НКСН (Л9 сл. 23, ครบทั้ง 5 แถว)
   สัญลักษณ์บนวงจรอ้างผังฟังก์ชัน Э2 ของ сл. 20: РО, У, ИОН, ДН (R₁/R₂), +ОС, −ОС, R_н
   หลักการวินิจฉัยสองตัวชี้วัด: แรงดันตกคร่อม РЭ และอุณหภูมิของ РЭ
   ค่ามิเตอร์เป็นตัวอย่างที่สอดคล้องกับอาการในตาราง (ผู้เรียบเรียง — สไลด์ให้เฉพาะคำบรรยาย)
============================================================================ */
function eoStabFault(host) {
  var CASES = [
    {
      sym: "Uвых велико (близко к Uвх), не регулируется · на РЭ малое падение",
      cause: "Обрыв в цепи ООС (จาก +ОС ถึงอินพุต «−» ของ У)",
      fix: "Найти и устранить обрыв",
      th: "ตัวขยายไม่เห็นแรงดันขาออกเลย จึงเปิด РЭ จนสุด — แรงดันตกคร่อม РЭ เหลือน้อยแต่ยังไม่เป็นศูนย์",
      hl: "oos", Uin: 27, Uout: 25.5, In: 1.0, temp: "тёплый"
    },
    {
      sym: "Uвых = Uвх, не регулируется · падение на РЭ равно нулю",
      cause: "Пробой (короткое замыкание) транзистора РЭ",
      fix: "Заменить транзистор на исправный",
      th: "ทรานซิสเตอร์ลัดวงจร คอลเลกเตอร์กับอิมิตเตอร์ต่อถึงกัน แรงดันขาเข้าผ่านไปทั้งก้อน",
      hl: "ro", Uin: 27, Uout: 27, In: 1.0, temp: "холодный"
    },
    {
      sym: "Uвых ниже нормы, нет стабилизации · Uвх менее нижнего допустимого предела",
      cause: "Насыщение транзисторного РЭ จากแรงดันขาเข้าที่ต่ำเกินกำหนด",
      fix: "Восстановить нормальное напряжение НИ (แหล่งจ่ายต้นทาง)",
      th: "วงจรยังดีทั้งหมด แต่ไม่มีแรงดันเหลือให้ РЭ ควบคุม — ต้องแก้ที่แหล่งจ่าย ไม่ใช่ที่ตัวรักษาระดับ",
      hl: "in", Uin: 9, Uout: 8.4, In: 0.7, temp: "тёплый"
    },
    {
      sym: "Uвых близко к нулю, есть малый ток нагрузки · РЭ горячий на ощупь · Uвх в норме",
      cause: "РЭ удерживается в призакрытом состоянии — เช่น КЗ в ИОН หรือ обрыв цепи «−ОС, R₂»",
      fix: "ตรวจ ИОН และวงจร R₂ ของตัวแบ่ง",
      th: "РЭ ปิดค้าง แรงดันเกือบทั้งหมดตกคร่อมมันและกลายเป็นความร้อน — ร้อนคือหลักฐานว่ากระแสยังไหลอยู่",
      hl: "ion", Uin: 27, Uout: 0.2, In: 0.15, temp: "горячий"
    },
    {
      sym: "Uвых и ток нагрузки равны нулю · Uвх в норме · РЭ холодный на ощупь",
      cause: "Обрыв силовой цепи СН (จากจุด «+» ถึงจุด «−» ของขาเข้า รวมทั้งตัว РЭ)",
      fix: "Устранить обрыв (заменить РЭ)",
      th: "ไม่มีกระแสไหลเลย จึงไม่มีความร้อน — เย็นคือหลักฐานว่าวงจรกำลังขาด ไม่ใช่วงควบคุมผิด",
      hl: "pwr", Uin: 27, Uout: 0, In: 0, temp: "холодный"
    }
  ];
  buildDemo(host, {
    label: "Лекция 9 · сл. 23",
    title: "เลือกอาการด้วยปุ่ม 1–5 แล้วดูบล็อกที่ต้องสงสัยพร้อมสาเหตุและวิธีตรวจตามตารางของสไลด์ 23",
    ratio: 0.66,
    legend: '<span><i style="background:var(--crit)"></i>บล็อกที่ต้องสงสัยของอาการที่เลือก</span>' +
      '<span>วงจรที่วาดคือผังฟังก์ชัน Э2 ของ <b>сл. 20</b> เพราะตาราง сл. 23 อ้างสัญลักษณ์ +ОС, −ОС, У, ИОН, R₂, РЭ จากผังนั้น</span>' +
      '<span>ค่ามิเตอร์เป็นตัวอย่างของ <b>ผู้เรียบเรียง</b> ที่สอดคล้องกับคำบรรยายอาการ — สไลด์ 23 ไม่ได้ให้ตัวเลข</span>',
    buttons: [
      { id: "b1", label: "1", act: function (s) { s.k = 0; } },
      { id: "b2", label: "2", act: function (s) { s.k = 1; } },
      { id: "b3", label: "3", act: function (s) { s.k = 2; } },
      { id: "b4", label: "4", act: function (s) { s.k = 3; } },
      { id: "b5", label: "5", act: function (s) { s.k = 4; } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok"), panel = CV("--panel-2"), wash = CV("--wash");
      var fs = eoDfs(w);
      var k = s.k || 0, c = CASES[k];
      var hot = function (id) { return c.hl === id ? crit : line; };
      var lw = function (id) { return c.hl === id ? 2.2 : 1.2; };

      /* ---- ผังวงจร Э2 ---- */
      var top = 8, ch = Math.min(h * 0.52, 150);
      var yTop = top + 14, yBot = top + ch - 14;
      var xL = 26, xR = w - 20;
      /* สายกำลังบน (+) และล่าง (−) */
      eoDseg(ctx, xL, yTop, xR, yTop, hot("pwr"), lw("pwr"));
      eoDseg(ctx, xL, yBot, xR, yBot, hot("pwr"), lw("pwr"));
      /* แหล่งจ่ายซ้าย */
      eoDseg(ctx, xL, yTop, xL, yBot, hot("in"), lw("in"));
      eoDtx(ctx, xL - 3, (yTop + yBot) / 2, "Uвх", c.hl === "in" ? crit : ink, fs, "right", "middle");
      /* РО (регулирующий орган) บนสายบวก */
      var roW = Math.max(46, w * 0.15), roX = xL + (w * 0.16);
      eoDbox(ctx, roX, yTop - 11, roW, 22, c.hl === "ro" ? CV("--wash-2") : panel, hot("ro"), lw("ro"));
      eoDtx(ctx, roX + roW / 2, yTop, "РО (РЭ)", c.hl === "ro" ? crit : ink, fs, "center", "middle", true);
      /* โหลด R_н ทางขวา */
      eoDbox(ctx, xR - 34, (yTop + yBot) / 2 - 16, 22, 32, panel, line, 1.2);
      eoDtx(ctx, xR - 23, (yTop + yBot) / 2, "Rн", ink, fs, "center", "middle");
      eoDseg(ctx, xR - 23, yTop, xR - 23, (yTop + yBot) / 2 - 16, line, 1.2);
      eoDseg(ctx, xR - 23, (yTop + yBot) / 2 + 16, xR - 23, yBot, line, 1.2);
      /* ДН — R1/R2 */
      var dnX = xR - 82;
      eoDseg(ctx, dnX, yTop, dnX, yBot, line, 1.2);
      eoDbox(ctx, dnX - 8, yTop + 12, 16, 20, panel, line, 1.2);
      eoDtx(ctx, dnX, yTop + 22, "R₁", ink3, fs - 1, "center", "middle");
      eoDbox(ctx, dnX - 8, yBot - 32, 16, 20, panel, c.hl === "ion" ? crit : line, c.hl === "ion" ? 2 : 1.2);
      eoDtx(ctx, dnX, yBot - 22, "R₂", c.hl === "ion" ? crit : ink3, fs - 1, "center", "middle");
      /* У (усилитель) + ИОН */
      var uyX = roX + roW + 26, uyY = (yTop + yBot) / 2 + 8;
      ctx.save();
      ctx.strokeStyle = c.hl === "oos" ? crit : line; ctx.lineWidth = c.hl === "oos" ? 2 : 1.2;
      ctx.beginPath(); ctx.moveTo(uyX, uyY - 16); ctx.lineTo(uyX, uyY + 16); ctx.lineTo(uyX + 26, uyY); ctx.closePath(); ctx.stroke();
      ctx.restore();
      eoDtx(ctx, uyX + 9, uyY, "У", ink, fs, "center", "middle", true);
      eoDtx(ctx, uyX - 3, uyY - 11, "−", ink3, fs, "right", "middle");
      eoDtx(ctx, uyX - 3, uyY + 11, "+", ink3, fs, "right", "middle");
      eoDarrow(ctx, uyX + 26, uyY, roX + roW / 2, yTop + 12, acc, 1.4);
      eoDbox(ctx, uyX - 46, uyY + 16, 42, 18, c.hl === "ion" ? CV("--wash-2") : panel, c.hl === "ion" ? crit : line, c.hl === "ion" ? 2 : 1.2);
      eoDtx(ctx, uyX - 25, uyY + 25, "ИОН", c.hl === "ion" ? crit : ink, fs - 1, "center", "middle");
      eoDseg(ctx, uyX - 4, uyY + 25, uyX - 4, uyY + 11, c.hl === "ion" ? crit : line, 1.2);
      eoDseg(ctx, uyX - 4, uyY + 11, uyX, uyY + 11, c.hl === "ion" ? crit : line, 1.2);
      /* สาย ООС จาก +ОС ไปยังอินพุต «−» */
      eoDseg(ctx, dnX, yTop + 32, dnX, uyY - 11, hot("oos"), lw("oos"), c.hl === "oos" ? [4, 3] : null);
      eoDseg(ctx, dnX, uyY - 11, uyX, uyY - 11, hot("oos"), lw("oos"), c.hl === "oos" ? [4, 3] : null);
      eoDtx(ctx, dnX + 4, uyY - 22, "ООС (+ОС)", c.hl === "oos" ? crit : ink3, fs - 1, "left", "middle");
      if (c.hl === "oos") {
        eoDtx(ctx, (dnX + uyX) / 2, uyY - 24, "обрыв", crit, fs, "center", "bottom", true);
        eoDseg(ctx, (dnX + uyX) / 2 - 5, uyY - 16, (dnX + uyX) / 2 + 5, uyY - 6, crit, 2.2);
        eoDseg(ctx, (dnX + uyX) / 2 - 5, uyY - 6, (dnX + uyX) / 2 + 5, uyY - 16, crit, 2.2);
      }

      /* ---- รายการอาการ 5 แถว ---- */
      var ly = top + ch + 4, rowh = Math.max(13, (h - ly - 6) / 5);
      for (var i = 0; i < 5; i++) {
        var yy = ly + i * rowh;
        if (i === k) eoDbox(ctx, 6, yy, w - 12, rowh - 2, CV("--wash-2"), crit, 1.2);
        var t = (i + 1) + ". " + CASES[i].sym;
        /* วัดความกว้างจริงแทนการเดาจากจำนวนตัวอักษร (คีริลลิกกว้างกว่าที่เดาไว้) */
        ctx.save();
        ctx.font = (fs - (i === k ? 0 : 1)) + 'px "IBM Plex Mono", monospace';
        while (t.length > 2 && ctx.measureText(t + "…").width > w - 26) t = t.slice(0, -1);
        if (t !== (i + 1) + ". " + CASES[i].sym) t += "…";
        ctx.restore();
        eoDtx(ctx, 12, yy + rowh / 2 - 1, t, i === k ? ink : ink3, fs - (i === k ? 0 : 1), "left", "middle", i === k);
      }

      readout.innerHTML =
        '<span>มิเตอร์: U<sub>вх</sub> = <b>' + eoDn(c.Uin, 1) + ' В</b> · U<sub>вых</sub> = <b>' + eoDn(c.Uout, 1) + ' В</b> · ΔU<sub>РЭ</sub> = <b>' + eoDn(c.Uin - c.Uout, 1) + ' В</b> · I<sub>н</sub> = <b>' + eoDn(c.In, 2) + ' А</b> · РЭ <b class="' + (c.temp === "горячий" ? "bad" : "good") + '">' + c.temp + '</b></span>' +
        '<span><b>Вероятная причина:</b> ' + c.cause + '</span>' +
        '<span><b>Метод восстановления:</b> ' + c.fix + '</span>' +
        '<span>' + c.th + '</span>' +
        '<span>กฎวินิจฉัยของตาราง: ΔU<sub>РЭ</sub> = 0 → пробой РЭ · ΔU<sub>РЭ</sub> เล็กแต่ไม่ศูนย์ + U<sub>вых</sub> สูง → обрыв ООС · РЭ ร้อน + U<sub>вых</sub> ต่ำ → РЭ ปิดค้าง · РЭ เย็น + I<sub>н</sub> = 0 → обрыв силовой цепи</span>';
    }
  });
}

/* ============================================================================
   7. eoISN — ИСН แบบรีเลย์ (двухпозиционный метод регулирования)
   Л10 сл. 12–13: РЭ ถูกขับด้วย пороговое устройство (компаратор с гистерезисом / триггер Шмитта)
     (10.1) T = t_и + t_п      (сл. 12)
     (10.2) q = t_и / T        (сл. 12–14, 16 — สไลด์ใช้สัญลักษณ์ q, นิยามเป็นของผู้เรียบเรียง)
     (10.3) U_x = K_уу·X       (сл. 13 — แกนนอนของลูปฮิสเทอรีซิส)
   วงจร buck ของ сл. 16 (ผู้เรียบเรียงเสริม — สมการของ понижающий конвертор):
     di_L/dt = (U_вх − U_вых)/L ตอน РЭ เปิด · = −U_вых/L ตอน РЭ ปิด
     ΔI = ΔU_гист / r_c  (ริปเปิลแรงดันถูกกำหนดโดย ESR ของตัวเก็บประจุ r_c = 0,06 Ом)
     t_и = L·ΔI/(U_вх − U_вых) · t_п = L·ΔI/U_вых · f = 1/(t_и + t_п) · q = U_вых/U_вх
   K_п คำนวณด้วยสูตรของ Л9 сл. 12: K_п = ΔU_вых/(2·U_вых)
============================================================================ */
function eoISN(host) {
  buildDemo(host, {
    label: "Лекция 10 · сл. 13, 16",
    title: "ขยายลูปฮิสเทอรีซิสของ РЭ แล้วดูริปเปิลโตขึ้นและความถี่สลับลดลงพร้อมกัน",
    ratio: 0.66,
    legend: '<span><i style="background:var(--accent)"></i>u<sub>вых</sub>(t)</span>' +
      '<span><i style="background:var(--accent-2)"></i>i<sub>L</sub>(t) ในตัว дроссель</span>' +
      '<span><i style="background:var(--line-2)"></i>ระดับ U<sub>вкл</sub> / U<sub>выкл</sub> ของ пороговое устройство</span>' +
      '<span>ผู้เรียบเรียงเสริม: r<sub>c</sub> (ESR ของตัวเก็บประจุ) = 0,06 Ом และความสัมพันธ์ U<sub>вых</sub> = q·U<sub>вх</sub> ของ понижающий конвертор — สไลด์ Л10 ไม่ได้เขียนสูตรเหล่านี้</span>',
    controls: [
      { id: "Uin", label: "U<sub>вх</sub>, В", min: 15, max: 60, step: 0.5, value: 27, fmt: function (v) { return eoDn(v, 1); } },
      { id: "Uout", label: "U<sub>вых</sub> ที่ตั้ง, В", min: 5, max: 24, step: 0.5, value: 12, fmt: function (v) { return eoDn(v, 1); } },
      { id: "hys", label: "ΔU<sub>гист</sub>, мВ", min: 10, max: 300, step: 5, value: 60 },
      { id: "L", label: "L, мкГн", min: 50, max: 2000, step: 10, value: 500 },
      { id: "In", label: "I<sub>н</sub>, А", min: 0.2, max: 6, step: 0.1, value: 2, fmt: function (v) { return eoDn(v, 1); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok"), panel = CV("--panel-2");
      var fs = eoDfs(w);
      var rc = 0.06, L = s.L * 1e-6, hys = s.hys / 1000;
      var Uo = Math.min(s.Uout, s.Uin - 0.5);
      var dI = hys / rc;
      var ti = L * dI / (s.Uin - Uo), tp = L * dI / Uo, T = ti + tp;
      var f = 1 / T, q = ti / T;
      var Kp = hys / (2 * Uo);                         /* Л9 сл. 12 สูตรที่ 5 */
      var pt = s.In < dI / 2;                          /* กระแสไม่ต่อเนื่อง — โซน ПТ */

      /* ---- ซ้าย: ลูปฮิสเทอรีซิสของ РЭ (сл. 13 รูปที่ 1) ---- */
      var lw2 = Math.min(w * 0.36, 170), lh = h * 0.42;
      var lx = 30, ly = 12;
      eoDseg(ctx, lx, ly + lh - 12, lx + lw2 - 8, ly + lh - 12, line, 1.2);
      eoDseg(ctx, lx + lw2 / 2, ly + 2, lx + lw2 / 2, ly + lh - 4, line, 1.2);
      eoDtx(ctx, lx + lw2 - 6, ly + lh - 12 - 3, w < 470 ? "Ux" : "Ux = Kуу·X", ink3, fs - 1, "right", "bottom");
      eoDtx(ctx, lx + lw2 / 2 + 4, ly + 2, "UУРО", ink3, fs - 1, "left", "top");
      var xo = lx + lw2 / 2 - lw2 * 0.22, xi2 = lx + lw2 / 2 + lw2 * 0.22;
      var yop = ly + 12, ycl = ly + lh - 24;
      eoDseg(ctx, lx + 4, ycl, xi2, ycl, acc, 2.2);
      eoDseg(ctx, xi2, ycl, xi2, yop, acc, 2.2);
      eoDseg(ctx, xi2, yop, lx + lw2 - 10, yop, acc, 2.2);
      eoDseg(ctx, lx + 10, yop, xo, yop, acc, 2.2);
      eoDseg(ctx, xo, yop, xo, ycl, acc, 2.2);
      eoDtx(ctx, lx + lw2 - 10, yop + 3, "UОТКР · ВКЛ. РО", acc, fs - 1, "right", "top");
      eoDtx(ctx, lx + 6, ycl - 3, "UЗАКР · ОТКЛ. РО", acc, fs - 1, "left", "bottom");
      eoDtx(ctx, xo, ly + lh - 8, "Uвыкл", ink3, fs - 1, "center", "top");
      eoDtx(ctx, xi2, ly + lh - 8, "Uвкл", ink3, fs - 1, "center", "top");
      eoDseg(ctx, xo, ly + lh - 14, xi2, ly + lh - 14, crit, 1.4);
      eoDtx(ctx, (xo + xi2) / 2, ly + lh - 16, "гистерезис", crit, fs - 1, "center", "bottom");

      /* ---- ขวา: u_вых(t) ---- */
      var px = lx + lw2 + 34, pwv = w - px - 12;
      var nT = 3, tt = [], ii = [], uu = [], i;
      var N = 240;
      for (i = 0; i <= N; i++) {
        var t = nT * T * i / N;
        var ph = t % T;
        var cur;
        if (ph < ti) cur = s.In - dI / 2 + (s.Uin - Uo) / L * ph;
        else cur = s.In + dI / 2 - Uo / L * (ph - ti);
        tt.push(t * 1e6);
        ii.push([t * 1e6, cur]);
        uu.push([t * 1e6, Uo + rc * (cur - s.In)]);
      }
      var p1y = 18, p1h = h * 0.42 - 22;
      var p1 = new Plot(ctx, px, p1y, pwv, p1h, 0, nT * T * 1e6, Uo - hys, Uo + hys);
      p1.frame(eoDticksN(0, nT * T * 1e6, 3), eoDticksN(Uo - hys, Uo + hys, 2), "t, мкс","uвых, В");
      p1.clip(function () {
        p1.line([[0, Uo + hys / 2], [nT * T * 1e6, Uo + hys / 2]], line, 1, [4, 3]);
        p1.line([[0, Uo - hys / 2], [nT * T * 1e6, Uo - hys / 2]], line, 1, [4, 3]);
        p1.line(uu, acc, 2);
      });
      /* ---- ล่าง: i_L(t) ---- */
      var p2y = Math.max(h * 0.48, p1y + p1h + 42);
      var p2 = new Plot(ctx, 46, p2y, w - 62, h - p2y - 34, 0, nT * T * 1e6, Math.min(0, s.In - dI), s.In + dI);
      p2.frame(eoDticksN(0, nT * T * 1e6, 6), eoDticksN(Math.min(0, s.In - dI), s.In + dI, 4), "t, мкс","iL, А");
      p2.clip(function () {
        p2.line([[0, s.In], [nT * T * 1e6, s.In]], line, 1, [3, 3]);
        p2.line(ii, acc2, 2);
        for (var m = 0; m < nT; m++) {
          p2.line([[(m * T + ti) * 1e6, p2.ymin], [(m * T + ti) * 1e6, p2.ymax]], line, 1, [2, 3]);
        }
      });
      /* ป้ายช่วงเวลา — บังคับให้อยู่ในกรอบ และแยกคนละบรรทัดเพื่อไม่ทับกันเมื่อ t_и สั้นมาก */
      var clampX = function (xv, half) { return Math.max(p2.x + half + 2, Math.min(p2.X(xv), p2.x + p2.w - half - 2)); };
      eoDtx(ctx, clampX(ti * 1e6 / 2, 34), p2.y + 2, "tи (РО открыт)", ink3, fs - 1, "center", "top");
      eoDtx(ctx, clampX(ti * 1e6 + tp * 1e6 / 2, 8), p2.y + 2 + fs + 3, "tп", ink3, fs - 1, "center", "top");

      readout.innerHTML =
        '<span>f<sub>комм</sub> = <b>' + eoDn(f / 1000, 2) + ' кГц</b> (T = ' + eoDn(T * 1e6, 1) + ' мкс)</span>' +
        '<span>t<sub>и</sub> = <b>' + eoDn(ti * 1e6, 1) + ' мкс</b> · t<sub>п</sub> = <b>' + eoDn(tp * 1e6, 1) + ' мкс</b></span>' +
        '<span>q = t<sub>и</sub>/T = <b>' + eoDn(q, 3) + '</b> (ตรงกับ U<sub>вых</sub>/U<sub>вх</sub> = ' + eoDn(Uo / s.Uin, 3) + ')</span>' +
        '<span>ΔU<sub>вых</sub> = <b>' + eoDn(s.hys, 0) + ' мВ</b> · ΔI<sub>L</sub> = <b>' + eoDn(dI, 2) + ' А</b></span>' +
        '<span>K<sub>п</sub> = ΔU<sub>вых</sub>/(2U<sub>вых</sub>) = <b class="' + (Kp < 0.005 ? "good" : "bad") + '">' + eoDn(Kp * 100, 3) + ' %</b></span>' +
        (pt ? '<span class="bad">I<sub>н</sub> &lt; ΔI/2 — เข้าโหมด прерывистых токов (โซน ПТ ของ сл. 14)</span>'
          : '<span class="good">โหมดกระแสต่อเนื่อง (НТ)</span>') +
        '<span>ขยายฮิสเทอรีซิส → ริปเปิลโต แต่ f<sub>комм</sub> ลด (สวิตช์น้อยลง กำลังสูญเสียจากการสวิตช์ลดลง) — นี่คือข้อแลกเปลี่ยนหลักของวิธี двухпозиционный</span>';
    }
  });
}

/* ============================================================================
   8. eoISNzone — ВАХ ИСН และโซน ПТ / стабилизации / защиты (Л10 сл. 14)
   สไลด์ให้ตระกูลเส้นตามค่า коэффициента заполнения (q₁ = 1 > q₂ > q₃ > q₄) และเส้น «Граница зоны ПТ»
   สมการที่ใช้ (ผู้เรียบเรียงเสริม — ทฤษฎีมาตรฐานของ понижающий конвертор ที่สไลด์ไม่ได้เขียน):
     โหมดกระแสต่อเนื่อง (НТ):  U_вых = q·U_вх − I_н·r
     ขอบเขตโซน ПТ:            I_гр = U_вх·q·(1 − q)/(2·L·f)
     โหมดกระแสไม่ต่อเนื่อง (ПТ): M = 2/(1 + √(1 + 8·L·f·I_н/(q²·U_вх·M))) แก้ด้วยการวนซ้ำ
============================================================================ */
function eoISNzone(host) {
  buildDemo(host, {
    label: "Лекция 10 · сл. 14",
    title: "เลื่อน γ (q) และ I<sub>н</sub> เพื่อดูว่าจุดทำงานอยู่ในโซน ПТ, โซนรักษาระดับ หรือโซนที่ระบบป้องกันทำงาน",
    ratio: 0.62,
    legend: '<span><i style="background:var(--accent)"></i>ตระกูล ВАХ ที่ γ = 1 · 0,75 · 0,5 · 0,25 (คือ q₁ … q₄ ของสไลด์)</span>' +
      '<span><i style="background:var(--crit)"></i>Граница зоны ПТ</span>' +
      '<span><i style="background:var(--ok)"></i>ВАХ เมื่อคลุมด้วย ООС — «жёсткая» ในโซนรักษาระดับ</span>' +
      '<span><b>สัญลักษณ์:</b> γ ที่ใช้บนแกนของ сл. 14 กับ q ที่ใช้ใน сл. 16 คือ <b>ปริมาณเดียวกัน</b> — коэффициент заполнения q = t<sub>и</sub>/T · ควรใช้สัญลักษณ์เดียวตลอดเมื่อตอบข้อสอบ</span>' +
      '<span>ผู้เรียบเรียงเสริม: f = 25 кГц · r ภายใน = 0,15 Ом · สูตรโหมด ПТ เป็นทฤษฎีมาตรฐานของคอนเวอร์เตอร์ ไม่ได้อยู่บนสไลด์</span>',
    controls: [
      { id: "Uin", label: "U<sub>вх</sub>, В", min: 15, max: 60, step: 0.5, value: 27, fmt: function (v) { return eoDn(v, 1); } },
      { id: "g", label: "γ (q) — коэффициент заполнения", min: 0.05, max: 1, step: 0.01, value: 0.45, fmt: function (v) { return eoDn(v, 2); } },
      { id: "In", label: "I<sub>н</sub>, А", min: 0.02, max: 8, step: 0.02, value: 2, fmt: function (v) { return eoDn(v, 2); } },
      { id: "L", label: "L, мкГн", min: 50, max: 2000, step: 10, value: 300 },
      { id: "Imax", label: "I<sub>MAX</sub> (เกณฑ์ป้องกัน), А", min: 1, max: 8, step: 0.1, value: 5, fmt: function (v) { return eoDn(v, 1); } }
    ],
    buttons: [{ id: "oos", label: "ООС включена", toggle: true, value: false }],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok"), wash = CV("--wash-2");
      var fs = eoDfs(w);
      var f = 25000, L = s.L * 1e-6, r = 0.15;
      function Igr(q) { return s.Uin * q * (1 - q) / (2 * L * f); }
      function uOut(q, I) {
        var ig = Igr(q);
        if (I >= ig) return Math.max(0, q * s.Uin - I * r);
        var M = 1, kk, j;
        for (j = 0; j < 40; j++) {
          kk = 8 * L * f * I / (q * q * s.Uin * Math.max(M, 1e-4));
          M = 2 / (1 + Math.sqrt(1 + kk));
        }
        return M * s.Uin;
      }
      var Imax = s.Imax, ig = Igr(s.g);
      var uNow = s.In > Imax ? uOut(s.g, s.In) * 0.15 : uOut(s.g, s.In);
      var zone = s.In > Imax ? "Зона работы защиты" : (s.In < ig ? "Зона ПТ (прерывистые токи)" : "Зона стабилизации (НТ)");

      var p = new Plot(ctx, 44, 18, w - 60, h - 50, 0, Imax * 1.25, 0, s.Uin * 1.05);
      p.frame(eoDticksN(0, Imax * 1.25, 5), eoDticksN(0, s.Uin * 1.05, 4), "Iн, А","Uвых, В");
      var qs = [1, 0.75, 0.5, 0.25], i, j2;
      p.clip(function () {
        /* แถบโซน ПТ ของค่า γ ปัจจุบัน และโซนป้องกัน */
        p.band([[0, s.Uin * 1.05, 0], [ig, s.Uin * 1.05, 0]], wash);
        p.band([[Imax, s.Uin * 1.05, 0], [Imax * 1.25, s.Uin * 1.05, 0]], wash);
        for (i = 0; i < qs.length; i++) {
          var pts = [];
          for (j2 = 1; j2 <= 140; j2++) {
            var I = Imax * 1.25 * j2 / 140;
            pts.push([I, uOut(qs[i], I)]);
          }
          p.line(pts, acc, i === 0 ? 2 : 1.5, i === 0 ? null : [5, 3]);
        }
        /* เส้นขอบโซน ПТ — locus ของจุด (I_гр(q), q·U_вх) */
        var bd = [];
        for (i = 1; i <= 100; i++) {
          var q = i / 100;
          bd.push([Igr(q), q * s.Uin]);
        }
        p.line(bd, crit, 1.8, [4, 3]);
        /* เส้นของ γ ที่เลือก */
        var cur = [];
        for (j2 = 1; j2 <= 160; j2++) {
          var I2 = Imax * 1.25 * j2 / 160;
          cur.push([I2, uOut(s.g, I2)]);
        }
        p.line(cur, acc2, 2.4);
        if (s.oos) {
          var oosPts = [];
          for (j2 = 1; j2 <= 160; j2++) {
            var I3 = Imax * 1.25 * j2 / 160;
            var v;
            if (I3 < ig) v = uOut(s.g, I3);
            else if (I3 <= Imax) v = s.g * s.Uin;
            else v = s.g * s.Uin * Math.max(0.05, 1 - (I3 - Imax) / (Imax * 0.12));
            oosPts.push([I3, v]);
          }
          p.line(oosPts, ok, 2.4);
        }
        p.line([[s.In, 0], [s.In, s.Uin * 1.05]], line, 1, [3, 3]);
        p.dots([[s.In, s.oos && s.In >= ig && s.In <= Imax ? s.g * s.Uin : uNow]], s.In > Imax ? crit : ok, 3.6);
      });
      eoDtx(ctx, p.X(ig / 2), p.y + 3, "ПТ", crit, fs, "center", "top", true);
      eoDtx(ctx, p.X(Imax) + 3, p.y + 3, "защита", crit, fs - 1, "left", "top");
      eoDtx(ctx, p.X(Imax * 0.62), p.Y(s.Uin * 0.97), "q₁ = 1", ink3, fs - 1, "center", "middle");
      eoDtx(ctx, p.x + p.w - 4, p.Y(0.25 * s.Uin) - 3, "q₄", ink3, fs - 1, "right", "bottom");

      readout.innerHTML =
        '<span>I<sub>гр</sub> = U<sub>вх</sub>γ(1−γ)/(2Lf) = <b>' + eoDn(ig, 3) + ' А</b> (= I<sub>MIN</sub> ของสไลด์)</span>' +
        '<span>U<sub>вых</sub> ที่จุดทำงาน = <b>' + eoDn(s.oos && s.In >= ig && s.In <= Imax ? s.g * s.Uin : uNow, 2) + ' В</b></span>' +
        '<span>γ·U<sub>вх</sub> = <b>' + eoDn(s.g * s.Uin, 2) + ' В</b> (ค่าที่ควรได้ในโหมด НТ)</span>' +
        '<span>โซนปัจจุบัน: <b class="' + (zone.indexOf("стабилизации") >= 0 ? "good" : "bad") + '">' + zone + '</b></span>' +
        '<span>ООС: <b>' + (s.oos ? "включена — ВАХ ยุบเป็นเส้นแบนเส้นเดียวในโซนรักษาระดับ" : "отключена — เห็นตระกูลเส้นตาม γ") + '</b></span>' +
        '<span>ข้อสรุปของสไลด์ 14: ต้องรักษา I<sub>н</sub> ≥ I<sub>НГР</sub> ไม่งั้นแม้มี ООС แรงดันก็พุ่งขึ้นในโซน ПТ</span>';
    }
  });
}

/* ============================================================================
   9. eoISNeff — เทียบ КПД ของ НСН กับ ИСН (ผู้เรียบเรียงเสริม)
   ฐานที่มาจากต้นฉบับ: Л9 сл. 12 สูตรที่ 6 (η = P_вых/(P_вых + P_п)) และ Л9 сл. 22 (недостатки НКСН:
   низкий КПД, большие габариты и масса) · Л10 ทั้งบรรยายอธิบายว่าเหตุใด ИСН จึงมี КПД สูง
   ตัวเลข η ≈ 0,85–0,95 ของ ИСН เป็นค่าทั่วไปจากวรรณกรรม — สไลด์ Л9/Л10 ไม่ได้ระบุ
     НСН: P_п = (U_вх − U_вых)·I_н + P_упр ;  η = P_вых/(P_вых + P_п) ≈ U_вых/U_вх
     ИСН: η ตั้งค่าได้ 0,85–0,95 ; P_п = P_вых·(1/η − 1)
============================================================================ */
function eoISNeff(host) {
  buildDemo(host, {
    label: "Лекция 9 сл. 12, 22 · Лекция 10 — ผู้เรียบเรียงเสริม",
    title: "ผู้เรียบเรียงเสริม: เทียบ КПД ของ НСН กับ ИСН ตาม U<sub>вх</sub> และดูกำลังสูญเสียที่ต้องระบายเป็นความร้อน",
    ratio: 0.56,
    legend: '<span><i style="background:var(--accent)"></i>η ของ НСН = U<sub>вых</sub>I<sub>н</sub>/(U<sub>вх</sub>I<sub>н</sub> + P<sub>упр</sub>)</span>' +
      '<span><i style="background:var(--accent-2)"></i>η ของ ИСН (ค่าที่ตั้ง 0,85–0,95)</span>' +
      '<span><b>ป้ายกำกับ:</b> ตัวเลข η ของ ИСН และการคำนวณเปรียบเทียบทั้งหมดในเดโมนี้เป็นของ <b>ผู้เรียบเรียง</b> · สิ่งที่มาจากต้นฉบับคือสูตร η = P<sub>вых</sub>/(P<sub>вых</sub>+P<sub>п</sub>) (Л9 сл. 12) และข้อเสีย «низкий КПД, большие габариты и масса» (Л9 сл. 22)</span>',
    controls: [
      { id: "Uin", label: "U<sub>вх</sub> (จุดทำงาน), В", min: 10, max: 60, step: 0.5, value: 27, fmt: function (v) { return eoDn(v, 1); } },
      { id: "Uout", label: "U<sub>вых</sub>, В", min: 5, max: 28, step: 0.5, value: 12, fmt: function (v) { return eoDn(v, 1); } },
      { id: "In", label: "I<sub>н</sub>, А", min: 0.1, max: 5, step: 0.1, value: 2, fmt: function (v) { return eoDn(v, 1); } },
      { id: "ei", label: "η ของ ИСН", min: 0.85, max: 0.95, step: 0.01, value: 0.9, fmt: function (v) { return eoDn(v, 2); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok"), wash = CV("--wash-2");
      var fs = eoDfs(w);
      var PU = 0.3;
      var Pout = s.Uout * s.In;
      /* วงจรรักษาระดับแบบลดทอนต้องมี U_вх > U_вых เสมอ — จำกัดจุดทำงานให้อยู่ในย่านที่มีความหมาย */
      var Uw = Math.max(s.Uin, s.Uout + 0.5), xmax = Math.max(60, Uw + 2);
      function etaN(uin) { return uin <= s.Uout ? NaN : Pout / (uin * s.In + PU); }
      var eN = etaN(Uw), eI = s.ei;
      var PpN = (Uw - s.Uout) * s.In + PU;
      var PpI = Pout * (1 / eI - 1);

      var p = new Plot(ctx, 44, 18, w - 60, h - 52, s.Uout, xmax, 0, 1);
      p.frame(ticks(s.Uout, xmax, 5), eoDticksN(0, 1, 5), "Uвх, В","η");
      var a = [], b = [], i;
      for (i = 0; i <= 120; i++) {
        var u = s.Uout + (xmax - s.Uout) * i / 120;
        a.push([u, etaN(u)]);
        b.push([u, eI]);
      }
      p.clip(function () {
        p.band(a.map(function (pt) { return [pt[0], eI, isFinite(pt[1]) ? pt[1] : eI]; }), wash);
        p.line(b, acc2, 2.2);
        p.line(a, acc, 2.2);
        p.line([[Uw, 0], [Uw, 1]], line, 1, [3, 3]);
        p.dots([[Uw, eN]], acc, 3.4);
        p.dots([[Uw, eI]], acc2, 3.4);
      });
      eoDtx(ctx, p.X(Uw) + 4, Math.min(p.y + p.h - 4, p.Y(eI) + 5), "ИСН", acc2, fs, "left", "top");
      eoDtx(ctx, p.X(Uw) + 4, p.Y(isFinite(eN) ? eN : 0) + 4, "НСН", acc, fs, "left", "top");
      eoDtx(ctx, p.x + 5, p.y + 3, "พื้นที่ระหว่างสองเส้น = กำลังที่ НСН ทิ้งเป็นความร้อน", ink3, fs - 1, "left", "top");

      readout.innerHTML =
        '<span>P<sub>вых</sub> = <b>' + eoDn(Pout, 1) + ' Вт</b></span>' +
        '<span>НСН: η = <b class="' + (eN > 0.6 ? "good" : "bad") + '">' + eoDn(eN * 100, 1) + ' %</b> · P<sub>п</sub> = <b class="bad">' + eoDn(PpN, 2) + ' Вт</b></span>' +
        '<span>ИСН: η = <b class="good">' + eoDn(eI * 100, 1) + ' %</b> · P<sub>п</sub> = <b>' + eoDn(PpI, 2) + ' Вт</b></span>' +
        '<span>สูญเสียมากกว่ากัน <b>' + eoDn(PpN / PpI, 1) + ' เท่า</b> — นี่คือสาเหตุของข้อเสีย «большие габариты и масса» (сл. 22) เพราะหม้อระบายความร้อนโตตาม P<sub>п</sub></span>' +
        '<span>ยิ่ง U<sub>вх</sub> ห่างจาก U<sub>вых</sub> มาก η ของ НСН ยิ่งตก แต่ η ของ ИСН แทบไม่ขึ้นกับ U<sub>вх</sub></span>' +
        (s.Uin <= s.Uout ? '<span class="bad">U<sub>вх</sub> ≤ U<sub>вых</sub> — วงจรรักษาระดับแบบลดทอนทำงานไม่ได้ กราฟจึงคำนวณที่ U<sub>вх</sub> = ' + eoDn(Uw, 1) + ' В</span>' : '');
    }
  });
}

/* ============================================================================
   10. eoOverload — ампер-секундная характеристика และ «จุดขัดแย้งของต้นฉบับ» (Л11 сл. 13 กับ сл. 21)
   ค่าจากต้นฉบับ:
     (11.5) I_пд = (1,5 … 2)·I_н   — ข้อความของ сл. 13 และ сл. 21
     (11.6) I_п  = 6·I_н           — сл. 13, 18, 19, 22
     (11.7) I_кз = 11·I_н          — сл. 13, 18, 19, 22
     (11.9) τ < 0,01 с (КЗ) · τ < 0,1 с (перегрузка) · τ до 60–180 с (длительная перегрузка) — ตาราง сл. 13
     (11.13) I > 135 % I_н นาน «от 60 с до 20 мин и более» — ข้อความ сл. 21
   จุดขัดแย้งสองจุดที่ต้องแสดง: (1) เกณฑ์กระแส 1,5–2 I_н (150–200 %) กับ 135 %
                                (2) เวลา 60–180 с (сл. 13) กับ 60 с – 20 мин (сл. 21)
============================================================================ */
function eoOverload(host) {
  buildDemo(host, {
    label: "Лекция 11 · сл. 13 และ сл. 21",
    title: "คุณลักษณะแอมแปร์-วินาที: สองเส้นบนกราฟเดียวคือค่าที่ต้นฉบับให้ไว้ขัดกันเอง",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>ตาราง сл. 13: 11 I<sub>н</sub> → τ &lt; 0,01 с · 6 I<sub>н</sub> → τ &lt; 0,1 с · 1,5 I<sub>н</sub> → τ ถึง 60–180 с</span>' +
      '<span><i style="background:var(--accent-2)"></i>ข้อความ сл. 21: เกิน 135 % I<sub>н</sub> นาน 60 с ถึง 20 мин และมากกว่า</span>' +
      '<span><i style="background:var(--crit)"></i>แถบ (1,5 – 2)·I<sub>н</sub> ตามข้อความของ сл. 13 — ส่วนตารางในสไลด์เดียวกันเขียนเพียง I<sub>ДП</sub> = 1,5 I<sub>Н</sub> (ตัดขอบบนทิ้ง)</span>' +
      '<span><b>หมายเหตุต้นฉบับ:</b> เมื่อทำโจทย์ให้ใช้ช่วง (1,5 – 2)·I<sub>н</sub> ตามข้อความ และระบุว่าตารางให้ค่าล่างสุด · เรื่องเวลาและ 135 % ต้องถามอาจารย์ว่าใช้ค่าไหนในการสอบ</span>',
    controls: [
      { id: "In", label: "I<sub>н</sub> ของโหลด, А", min: 1, max: 30, step: 0.5, value: 10, fmt: function (v) { return eoDn(v, 1); } },
      { id: "k", label: "I / I<sub>н</sub> (кратность)", min: 1, max: 12, step: 0.05, value: 1.6, fmt: function (v) { return eoDn(v, 2); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok"), wash = CV("--wash-2");
      var fs = eoDfs(w);
      var LG = function (t) { return Math.log10(t); };
      var p = new Plot(ctx, 40, 18, w - 56, h - 54, LG(0.005), LG(2400), 0, 12.5);
      p.frame([LG(0.01), LG(0.1), LG(1), LG(10), LG(60), LG(180), LG(1200)], eoDticksN(0, 12, 6), "t, с", "I / Iн",true);
      eoDxlab(ctx, p, [LG(0.01), LG(0.1), LG(1), LG(10), LG(60), LG(180), LG(1200)],
        ["0,01", "0,1", "1", "10", "60", "180", "1200"], ink3, fs - 1);
      p.clip(function () {
        /* แถบ (1,5 – 2) I_н */
        p.band([[p.xmin, 2, 1.5], [p.xmax, 2, 1.5]], wash);
        /* เส้นของ сл. 13 */
        p.line([[LG(0.01), 11], [LG(0.1), 6], [LG(60), 1.5]], acc, 2.4);
        p.line([[LG(60), 1.5], [LG(180), 1.5]], acc, 2.4);
        p.dots([[LG(0.01), 11], [LG(0.1), 6], [LG(60), 1.5], [LG(180), 1.5]], acc, 3.4);
        /* เส้นของ сл. 21 */
        p.line([[LG(60), 1.35], [LG(1200), 1.35]], acc2, 2.4, [6, 3]);
        p.dots([[LG(60), 1.35], [LG(1200), 1.35]], acc2, 3.4);
        /* เส้นระดับอ้างอิง */
        p.line([[p.xmin, 6], [p.xmax, 6]], line, 1, [2, 4]);
        p.line([[p.xmin, 11], [p.xmax, 11]], line, 1, [2, 4]);
        p.line([[p.xmin, s.k], [p.xmax, s.k]], crit, 1.6, [4, 3]);
      });
      eoDtx(ctx, p.x + 4, p.Y(11) - 3, "Iкз = 11 Iн", ink3, fs - 1, "left", "bottom");
      eoDtx(ctx, p.x + 4, p.Y(6) - 3, "Iп = 6 Iн", ink3, fs - 1, "left", "bottom");
      eoDtx(ctx, p.X(LG(120)), p.Y(1.5) - 4 - (fs + 3), "сл. 13: 60–180 с", acc, fs - 1, "center", "bottom");
      eoDtx(ctx, p.X(LG(400)), p.Y(1.35) + 4, "сл. 21: 60 с – 20 мин", acc2, fs - 1, "center", "top");
      eoDtx(ctx, p.x + p.w - 4, p.Y(1.75), "(1,5 – 2) Iн", crit, fs - 1, "right", "middle");

      var I = s.k * s.In;
      var mode, t13, t21, dev;
      if (s.k >= 11) { mode = "Короткое замыкание"; t13 = "τ < 0,01 с"; dev = "Плавкая вставка หรือ автоматический выключатель (ЭМ-контур)"; }
      else if (s.k >= 6) { mode = "Перегрузка по току"; t13 = "τ < 0,1 с"; dev = "Плавкая вставка หรือ автоматический выключатель"; }
      else if (s.k >= 1.5) { mode = "Длительная перегрузка по току"; t13 = "τ до 60–180 с"; dev = "Тепловое реле магнитного пускателя"; }
      else if (s.k >= 1.35) { mode = "โซนขัดแย้งของต้นฉบับ"; t13 = "ตาราง сл. 13 ยังไม่ถือว่าเป็น I_ДП"; dev = "Тепловое реле — ตาม сл. 21 ต้องตัดแล้ว"; }
      else { mode = "Нормальный режим"; t13 = "ไม่ตัด"; dev = "ไม่มีอุปกรณ์ใดต้องทำงาน"; }
      t21 = s.k >= 1.35 ? "60 с – 20 мин และมากกว่า" : "ไม่ตัด";
      readout.innerHTML =
        '<span>I = <b>' + eoDn(I, 1) + ' А</b> (I<sub>н</sub> = ' + eoDn(s.In, 1) + ' А · кратность ' + eoDn(s.k, 2) + ')</span>' +
        '<span>โหมด: <b class="' + (s.k < 1.35 ? "good" : "bad") + '">' + mode + '</b></span>' +
        '<span>เวลาที่ยอมให้ทนตาม <b>сл. 13</b>: <b>' + t13 + '</b></span>' +
        '<span>เวลาที่ยอมให้ทนตาม <b>сл. 21</b>: <b>' + t21 + '</b></span>' +
        '<span>อุปกรณ์ที่ต้องทำงาน (сл. 22): ' + dev + '</span>' +
        '<span class="bad">จุดขัดแย้ง 1: เกณฑ์กระแส — сл. 21 เขียน «более 135 % I<sub>н</sub>» แล้วต่อทันทีว่า I<sub>пд</sub> = (1,5 – 2) I<sub>н</sub> คือ 150–200 % · คำอธิบายที่น่าจะถูก: 135 % คือ ток трогания ของ теплового реле ส่วน (1,5 – 2) I<sub>н</sub> คือค่านิยามของระบบตาม сл. 13</span>' +
        '<span class="bad">จุดขัดแย้ง 2: เวลา — ตาราง сл. 13 ให้ «τ до 60–180 с» แต่ข้อความ сл. 21 ให้ «จาก 60 с ถึง 20 мин และมากกว่า» · ที่น่าจะถูกคือ сл. 21 เพราะรีเลย์ความร้อนทนโอเวอร์โหลดยาวได้จริงหลายนาที — <b>ต้องถามอาจารย์</b></span>';
    }
  });
}

/* ============================================================================
   11. eoProtect — เทียบอุปกรณ์ป้องกัน: предохранитель / АЗС / автомат (АВ) / электронная защита
   ต้นฉบับ: Л11 сл. 16 (การจำแนก КЗА) · сл. 18 (плавкие предохранители + АСХ) ·
            сл. 19 (АВ: тепловой контур กับ ЭМ-контур, ток отсечки I_ОТС, t_кз) ·
            сл. 20–21 (контактор / магнитный пускатель) · сл. 22 (ตารางว่าอุปกรณ์ไหนกันอะไรได้)
   แบบจำลอง АСХ (ผู้เรียบเรียง — สไลด์ให้เพียงรูปเชิงคุณภาพ ปรับให้ผ่านจุดอ้างอิงของ сл. 13):
     ตัวที่ตัดด้วยความร้อน: t(k) = A/(k² − k_кр²) · ฟิวส์ (หลอมละลาย ชันกว่ามาก): t(k) = A/(k⁴ − k_кр⁴)
     k = I/I_ном ; АВ มี отсечка: k ≥ k_отс ⇒ t = t_кз = 0,01 с (сл. 19)
     плавкая вставка A = 120 · k_кр = 1,3 | АЗС A = 90 · k_кр = 1,35 | АВ (тепловой) A = 60 · k_кр = 1,35
     электронная защита: ตัดที่ k ≥ 1,2 ในเวลา 0,2 мс คงที่ (ไม่มีความเฉื่อยทางความร้อน)
============================================================================ */
function eoProtect(host) {
  buildDemo(host, {
    label: "Лекция 11 · сл. 16–22",
    title: "เทียบเวลาตัดของอุปกรณ์ป้องกันสี่ชนิดที่กระแสต่าง ๆ แล้วดูว่าชนิดไหนผ่านข้อกำหนดของสไลด์ 13",
    ratio: 0.62,
    legend: '<span><i style="background:var(--accent)"></i>Плавкая вставка (предохранитель)</span>' +
      '<span><i style="background:var(--accent-2)"></i>АЗС — автомат защиты сети (ตัดด้วยความร้อนอย่างเดียว)</span>' +
      '<span><i style="background:var(--ok)"></i>Автоматический выключатель: тепловой контур + ЭМ-контур (отсечка)</span>' +
      '<span><i style="background:var(--crit)"></i>Электронная защита (ключ транзисторный/тиристорный, сл. 26–28)</span>' +
      '<span><b>ผู้เรียบเรียงเสริม:</b> สมการ t(k) = A/(k² − k<sub>кр</sub>²) และค่า A ทั้งสี่ชุดเป็นแบบจำลองเชิงคุณภาพที่ปรับให้ผ่านจุดอ้างอิงของ сл. 13 · สไลด์ 18–19 ให้เพียงรูปกราฟไม่มีสมการ · ชื่อ «АЗС» ไม่ปรากฏบนสไลด์ Л11 (สไลด์ใช้ «автоматы защиты») — เป็นคำที่ใช้ในระบบไฟฟ้าอากาศยาน</span>' +
      '<span>ในแบบจำลองนี้ электронная защита ตัดทันทีเมื่อเกิน 1,2 I<sub>ном</sub> จึงตัดตอนสตาร์ตมอเตอร์เสมอ — วงจรจริงต้องเพิ่มการหน่วงเวลาหรือปิดการป้องกันชั่วขณะช่วงสตาร์ต (ผู้เรียบเรียง)</span>',
    controls: [
      { id: "kn", label: "I<sub>ном</sub> ของอุปกรณ์ / I<sub>н</sub> ของโหลด", min: 1, max: 3, step: 0.05, value: 1, fmt: function (v) { return eoDn(v, 2); } },
      { id: "kots", label: "I<sub>ОТС</sub> / I<sub>ном</sub> ของ АВ", min: 4, max: 12, step: 0.5, value: 6, fmt: function (v) { return eoDn(v, 1); } },
      { id: "kp", label: "кратность пускового тока АД", min: 3, max: 8, step: 0.5, value: 6, fmt: function (v) { return eoDn(v, 1); } },
      { id: "tp", label: "длительность пуска, с", min: 0.5, max: 5, step: 0.1, value: 2, fmt: function (v) { return eoDn(v, 1); } },
      { id: "k", label: "I / I<sub>н</sub> ที่จุดตรวจ", min: 1, max: 12, step: 0.05, value: 6, fmt: function (v) { return eoDn(v, 2); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok");
      var fs = eoDfs(w);
      var LG = function (t) { return Math.log10(t); };
      function tTherm(kk, A, kkr) {
        var x = kk * kk - kkr * kkr;
        return x <= 0 ? Infinity : A / x;
      }
      function tFuse(kL) {
        var kk = kL / s.kn, x = kk * kk * kk * kk - 1.3 * 1.3 * 1.3 * 1.3;
        return x <= 0 ? Infinity : 120 / x;
      }
      function tAzs(kL) { return tTherm(kL / s.kn, 90, 1.35); }
      function tAv(kL) {
        var kk = kL / s.kn;
        if (kk >= s.kots) return 0.01;                      /* отсечка ЭМ-контура, t_кз (сл. 19) */
        return tTherm(kk, 60, 1.35);
      }
      function tEl(kL) { return (kL / s.kn) >= 1.2 ? 0.0002 : Infinity; }

      var p = new Plot(ctx, 40, 18, w - 56, h - 54, LG(0.00008), LG(1500), 0, 12.5);
      p.frame([LG(0.0001), LG(0.01), LG(0.1), LG(1), LG(10), LG(100), LG(1000)], eoDticksN(0, 12, 6), "t, с", "I / Iн",true);
      eoDxlab(ctx, p, [LG(0.0001), LG(0.01), LG(0.1), LG(1), LG(10), LG(100), LG(1000)],
        ["0,1 мс", "0,01", "0,1", "1", "10", "100", "1000"], ink3, fs - 1);
      function curve(fn) {
        var out = [], i;
        for (i = 0; i <= 200; i++) {
          var kk = 1 + 11.5 * i / 200;
          var t = fn(kk);
          if (isFinite(t) && t > 0.00005 && t < 3000) out.push([LG(t), kk]);
        }
        return out;
      }
      p.clip(function () {
        p.line(curve(tFuse), acc, 2.2);
        p.line(curve(tAzs), acc2, 2.2);
        p.line(curve(tAv), ok, 2.2);
        p.line(curve(tEl), crit, 2.2);
        /* ข้อกำหนดของ сл. 13 */
        p.dots([[LG(0.01), 11], [LG(0.1), 6], [LG(60), 1.5]], ink, 4);
        /* กระแสสตาร์ตของ АД (сл. 18) */
        p.line([[LG(0.02), s.kp], [LG(s.tp), s.kp]], ink3, 2, [5, 3]);
        p.dots([[LG(s.tp), s.kp]], ink3, 3.6);
        p.line([[p.xmin, s.k], [p.xmax, s.k]], line, 1.4, [4, 3]);
      });
      {
        var rq = "требование сл. 13";
        ctx.save(); ctx.font = (fs - 1) + 'px "IBM Plex Mono", monospace';
        var rqw = ctx.measureText(rq).width; ctx.restore();
        var toR = p.X(LG(60)) + 4 + rqw <= p.x + p.w - 2;
        eoDtx(ctx, p.X(LG(60)) + (toR ? 4 : -4), p.Y(1.5) - 3, rq, ink, fs - 1, toR ? "left" : "right", "bottom");
      }
      eoDtx(ctx, p.X(LG(s.tp)) + 4, p.Y(s.kp) + 3, "ток при запуске АД", ink3, fs - 1, "left", "top");

      var tf = tFuse(s.k), ta = tAzs(s.k), tv = tAv(s.k), te = tEl(s.k);
      function fmtT(t) { return !isFinite(t) ? "ไม่ตัด" : (t < 0.001 ? eoDn(t * 1e6, 0) + " мкс" : (t < 1 ? eoDn(t * 1000, 1) + " мс" : eoDn(t, 1) + " с")); }
      var need = s.k >= 11 ? 0.01 : (s.k >= 6 ? 0.1 : (s.k >= 1.5 ? 180 : Infinity));
      function verdict(t) { return (isFinite(need) ? (t <= need ? "good" : "bad") : "good"); }
      var startTrip = [];
      if (tFuse(s.kp) < s.tp) startTrip.push("плавкая вставка");
      if (tAzs(s.kp) < s.tp) startTrip.push("АЗС");
      if (tAv(s.kp) < s.tp) startTrip.push("АВ");
      if (tEl(s.kp) < s.tp) startTrip.push("электронная защита");

      readout.innerHTML =
        '<span>ที่ I = <b>' + eoDn(s.k, 2) + ' I<sub>н</sub></b> · ข้อกำหนดของ сл. 13: <b>' + (isFinite(need) ? "τ ≤ " + eoDn(need, 2) + " с" : "ไม่ต้องตัด") + '</b></span>' +
        '<span>Плавкая вставка: <b class="' + verdict(tf) + '">' + fmtT(tf) + '</b></span>' +
        '<span>АЗС: <b class="' + verdict(ta) + '">' + fmtT(ta) + '</b></span>' +
        '<span>Автоматический выключатель: <b class="' + verdict(tv) + '">' + fmtT(tv) + '</b>' + (s.k / s.kn >= s.kots ? ' (ทำงานด้วย ЭМ-контур — отсечка)' : ' (ทำงานด้วย тепловой контур)') + '</span>' +
        '<span>Электронная защита: <b class="' + verdict(te) + '">' + fmtT(te) + '</b></span>' +
        (startTrip.length ? '<span class="bad">ตัดผิดพลาดตอนสตาร์ตมอเตอร์: ' + startTrip.join(", ") + ' — ต้องเลือกพิกัดใหม่ให้ АСХ อยู่เหนือเส้นกระแสสตาร์ต (сл. 18)</span>'
          : '<span class="good">ไม่มีอุปกรณ์ใดตัดผิดพลาดตอนสตาร์ตมอเตอร์</span>') +
        '<span>กฎของ сл. 22: магнитный пускатель กันได้เฉพาะ I<sub>ДП</sub> จึงต้องติดตั้งคู่กับฟิวส์หรือ АВ เสมอ ส่วน магнитный контактор ไม่ให้การป้องกันใดเลย</span>';
    }
  });
}

/* ============================================================================
   12. eoShortCircuit — КЗ บนบัส: ΔU เทียบ ΔU_доп (Л11 сл. 12, ข้อ 3)
   ข้อความของสไลด์: «амплитуда пульсаций напряжений питания потребителя ПРЕВЫШАЕТ допустимое значение»
   แต่สูตรที่พิมพ์บนสไลด์เขียนว่า «ΔU < ΔU_доп» ซึ่ง <b>กลับด้าน</b> — เดโมนี้แสดงเงื่อนไขที่ถูก: ΔU > ΔU_доп
   แบบจำลองบัส (ผู้เรียบเรียง): E = 27 В, r_и ภายในแหล่งจ่าย, r_каб ถึงจุดลัดวงจร
     I_кз = E/(r_и + r_каб) ;  u_ш = E − I_кз·r_и = E·r_каб/(r_и + r_каб) ;  ΔU = E − u_ш
   เทียบกับ сл. 13: I_кз ควรอยู่ราว 11·I_н และต้องตัดภายใน τ < 0,01 с
============================================================================ */
function eoShortCircuit(host) {
  buildDemo(host, {
    label: "Лекция 11 · сл. 12–13",
    title: "КЗ บนบัส: ดูแรงดันบัสตกลึกแค่ไหน เทียบกับ ΔU<sub>доп</sub> และเวลาตัดที่สไลด์ 13 กำหนด",
    ratio: 0.56,
    legend: '<span><i style="background:var(--accent)"></i>u<sub>ш</sub>(t) — แรงดันบนบัสที่ผู้ใช้ไฟตัวอื่นได้รับ</span>' +
      '<span><i style="background:var(--line-2)"></i>ขอบเขต U<sub>н</sub> − ΔU<sub>доп</sub></span>' +
      '<span><b>หมายเหตุต้นฉบับ (сл. 12 ข้อ 3):</b> สไลด์พิมพ์เงื่อนไขฉุกเฉินว่า «ΔU &lt; ΔU<sub>доп</sub>» ซึ่งขัดกับข้อความบนสไลด์เดียวกันที่เขียนว่าริปเปิล «превышает допустимое значение» — <b>ที่ถูกคือ ΔU &gt; ΔU<sub>доп</sub></b> · Конспект ข้อ 25 เขียนถูก</span>' +
      '<span>ผู้เรียบเรียง: E = 27 В และรูปคลื่นเวลาเป็นตัวอย่างประกอบ สไลด์ 12 ไม่มีกราฟ · สไลด์นิยาม ΔU เป็น <b>амплитуда пульсаций</b> ที่ขั้วผู้ใช้ไฟ เดโมนี้ใช้เกณฑ์เดียวกันกับ <b>การตกของแรงดันบัสตอนเกิด КЗ</b> ซึ่งเป็นการเบี่ยงเบนจาก U<sub>н</sub> เหมือนกัน</span>',
    controls: [
      { id: "ri", label: "r<sub>и</sub> ของแหล่งจ่าย, Ом", min: 0.005, max: 0.5, step: 0.005, value: 0.15, fmt: function (v) { return eoDn(v, 3); } },
      { id: "rk", label: "r<sub>каб</sub> ถึงจุด КЗ, Ом", min: 0.005, max: 0.5, step: 0.005, value: 0.1, fmt: function (v) { return eoDn(v, 3); } },
      { id: "In", label: "I<sub>н</sub> ของวงจรที่ลัด, А", min: 1, max: 30, step: 0.5, value: 10, fmt: function (v) { return eoDn(v, 1); } },
      { id: "dop", label: "ΔU<sub>доп</sub>, % ของ U<sub>н</sub>", min: 1, max: 20, step: 0.5, value: 5, fmt: function (v) { return eoDn(v, 1); } },
      { id: "toff", label: "t<sub>откл</sub> ของอุปกรณ์ป้องกัน, мс", min: 1, max: 200, step: 1, value: 8 }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok"), wash = CV("--wash-2");
      var fs = eoDfs(w);
      var E = 27;
      var Ikz = E / (s.ri + s.rk);
      var ush = E * s.rk / (s.ri + s.rk);
      var dU = E - ush;
      var dop = E * s.dop / 100;
      var krat = Ikz / s.In;
      var bad = dU > dop;
      var t1 = 20, t2 = t1 + s.toff, tend = Math.max(120, t2 + 40);

      var p = new Plot(ctx, 44, 18, w - 60, h - 52, 0, tend, 0, E * 1.12);
      p.frame(ticks(0, tend, 6), eoDticksN(0, E * 1.12, 4), "t, мс","uш, В");
      var pts = [], i;
      for (i = 0; i <= 300; i++) {
        var t = tend * i / 300, v;
        if (t < t1) v = E;
        else if (t < t2) v = ush + (E - ush) * Math.exp(-(t - t1) / 0.8) * 0;
        else v = E - (E - ush) * Math.exp(-(t - t2) / 6);
        pts.push([t, v]);
      }
      p.clip(function () {
        p.band([[0, E * 1.12, E - dop], [tend, E * 1.12, E - dop]], wash);
        p.line([[0, E - dop], [tend, E - dop]], line, 1.4, [5, 3]);
        p.line([[0, E], [tend, E]], line, 1, [2, 4]);
        p.line(pts, acc, 2.4);
        p.line([[t1, 0], [t1, E * 1.12]], crit, 1.4, [3, 3]);
        p.line([[t2, 0], [t2, E * 1.12]], ok, 1.4, [3, 3]);
      });
      eoDtx(ctx, p.X(t1) + 3, p.y + 2, "КЗ", crit, fs, "left", "top", true);
      eoDtx(ctx, p.X(t2) + 3, p.y + 2 + fs + 3, "отключение", ok, fs - 1, "left", "top");
      eoDtx(ctx, p.x + 4, p.Y(E - dop) - 3, "Uн − ΔUдоп", ink3, fs - 1, "left", "bottom");
      var ya = p.Y(E), yb = p.Y(ush), xa = p.X((t1 + t2) / 2);
      eoDseg(ctx, xa, ya, xa, yb, crit, 1.6);
      eoDtx(ctx, xa + 5, (ya + yb) / 2, "ΔU = " + eoDn(dU, 1) + " В", crit, fs - 1, "left", "middle");

      readout.innerHTML =
        '<span>I<sub>кз</sub> = E/(r<sub>и</sub>+r<sub>каб</sub>) = <b>' + eoDn(Ikz, 0) + ' А</b> = <b>' + eoDn(krat, 1) + '·I<sub>н</sub></b> (сл. 13 ให้ค่ามาตรฐาน 11·I<sub>н</sub>)</span>' +
        '<span>u<sub>ш</sub> ขณะลัดวงจร = <b>' + eoDn(ush, 2) + ' В</b> · ΔU = <b>' + eoDn(dU, 2) + ' В</b> (' + eoDn(dU / E * 100, 1) + ' %)</span>' +
        '<span>ΔU<sub>доп</sub> = <b>' + eoDn(dop, 2) + ' В</b> (' + eoDn(s.dop, 1) + ' %)</span>' +
        '<span>เงื่อนไขที่ถูกต้อง: <b class="' + (bad ? "bad" : "good") + '">ΔU ' + (bad ? "&gt;" : "≤") + ' ΔU<sub>доп</sub> → ' + (bad ? "อยู่ในโหมดฉุกเฉิน ผู้ใช้ไฟตัวอื่นบนบัสเดียวกันเสียหาย" : "ยังอยู่ในเกณฑ์") + '</b></span>' +
        '<span>t<sub>откл</sub> = <b class="' + (s.toff <= 10 ? "good" : "bad") + '">' + s.toff + ' мс</b> · ข้อกำหนดของ сл. 13 สำหรับ КЗ คือ <b>τ &lt; 0,01 с = 10 мс</b> — ทำได้ด้วย ЭМ-контур ของ АВ หรือฟิวส์</span>' +
        '<span class="bad">หมายเหตุต้นฉบับ: สไลด์ 12 พิมพ์ «ΔU &lt; ΔU<sub>доп</sub>» เป็นเงื่อนไขฉุกเฉิน ซึ่งกลับด้านกับข้อความของตัวเอง — ตอบข้อสอบต้องเขียน <b>ΔU &gt; ΔU<sub>доп</sub></b></span>';
    }
  });
}

/* ============================================================================
   13. eoStorageCmp — เทียบอุปกรณ์สะสมพลังงานตามตาราง 7.1 ของ Четти (Л11 сл. 6)
   ตัวเลขคัดจากตารางบนสไลด์ทั้งหมด: удельная энергия (Вт·ч/кг) · габаритная энергия ·
   допустимое число перезарядов (относительное) · допуск к применению в космосе
   หมายเหตุต้นฉบับ: หัวคอลัมน์ที่สองบนสไลด์เขียนหน่วยเป็น «Вт·ч/кг» ซึ่งผิด — габаритная (объёмная)
   энергия ต้องเป็น <b>Вт·ч/дм³</b> เพราะถ้าเป็นหน่วยเดียวกับคอลัมน์แรก ค่า Ag–Zn 260 กับ 90–120
   จะขัดกันเอง · เดโมนี้ใช้หน่วยที่ถูกต้องบนแกน
     m = W / w_уд  [кг]   ·   V = W / w_габ  [дм³]
============================================================================ */
function eoStorageCmp(host) {
  var TAB = [
    { n: "Ag–Zn", ud: [90, 120], gab: 260, cyc: 1, cycTxt: "1", sp: "Да", ok: true },
    { n: "Ag–Cd", ud: [40, 60], gab: 120, cyc: 26, cycTxt: "26", sp: "Да", ok: true },
    { n: "Ni–Cd", ud: [30, 35], gab: 100, cyc: 60, cycTxt: "60", sp: "Да", ok: true },
    { n: "Ni–H₂", ud: [45, 55], gab: 40, cyc: 65, cycTxt: "> 60", sp: "Испытывается", ok: false },
    { n: "Ag–H₂", ud: [70, 80], gab: 50, cyc: -1, cycTxt: "—", sp: "Проводятся исследования", ok: false }
  ];
  buildDemo(host, {
    label: "Лекция 11 · сл. 6 (таблица 7.1, Четти П.)",
    title: "เลือกพลังงานที่ต้องการและจำนวนรอบประจุ แล้วดูมวลกับปริมาตรของอุปกรณ์สะสมพลังงานแต่ละชนิด",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>มวล m = W / w<sub>уд</sub>, кг</span>' +
      '<span><i style="background:var(--accent-2)"></i>ปริมาตร V = W / w<sub>габ</sub>, дм³</span>' +
      '<span><b>หมายเหตุต้นฉบับ (сл. 6):</b> ตารางบนสไลด์เขียนหน่วยของ «габаритная энергия» ว่า <b>Вт·ч/кг</b> ซึ่งผิด — ต้องเป็น <b>Вт·ч/дм³</b> (พลังงานต่อปริมาตร) เพราะถ้าเป็นหน่วยเดียวกับคอลัมน์แรก ค่าของ Ag–Zn จะเป็นทั้ง 90–120 และ 260 พร้อมกัน ซึ่งเป็นไปไม่ได้ · <b>ต้องถามอาจารย์เพื่อยืนยัน</b></span>' +
      '<span>ผู้เรียบเรียง: การคำนวณใช้ค่ากลางของช่วง w<sub>уд</sub> · «&gt; 60» ของ Ni–H₂ แทนด้วย 65 เพื่อให้เปรียบเทียบได้ · Ag–H₂ ไม่มีข้อมูลจำนวนรอบ («—»)</span>',
    controls: [
      { id: "W", label: "W — พลังงานที่ต้องการ, Вт·ч", min: 20, max: 3000, step: 20, value: 500 },
      { id: "cyc", label: "จำนวนรอบประจุที่ต้องการ (относительное)", min: 1, max: 65, step: 1, value: 26 }
    ],
    buttons: [{ id: "sp", label: "только допущенные в космос", toggle: true, value: false }],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"), ink = CV("--ink"),
        line = CV("--line-2"), crit = CV("--crit"), ok = CV("--ok"), panel = CV("--panel-2");
      var fs = eoDfs(w);
      var i, rows = [];
      for (i = 0; i < TAB.length; i++) {
        var e = TAB[i];
        var ud = (e.ud[0] + e.ud[1]) / 2;
        var m = s.W / ud, V = s.W / e.gab;
        var fitCyc = e.cyc >= s.cyc;
        var fitSp = s.sp ? e.ok : true;
        rows.push({ e: e, m: m, V: V, ud: ud, fit: fitCyc && fitSp, fitCyc: fitCyc, fitSp: fitSp });
      }
      var mMax = 0, vMax = 0;
      for (i = 0; i < rows.length; i++) { if (rows[i].m > mMax) mMax = rows[i].m; if (rows[i].V > vMax) vMax = rows[i].V; }
      var top = 18, rowh = (h - top - 6) / rows.length;
      var nameW = Math.max(46, w * 0.14), x0 = nameW + 8;
      var barW = (w - x0 - 66) / 2 - 8;
      eoDtx(ctx, x0, 4, "m, кг", acc, fs - 1, "left", "top");
      eoDtx(ctx, x0 + barW + 12, 4, w < 560 ? "V, дм³" : "V, дм³ (габаритная энергия, Вт·ч/дм³)", acc2, fs - 1, "left", "top");
      /* ป้ายค่าอยู่ท้ายแท่ง — ถ้าแท่งยาวจนป้ายจะล้นกล่อง ให้ย้ายเข้าไปในแท่ง (สี --bg เพื่อคอนทราสต์) */
      var valLab = function (bx0, frac, y, bhh, txt, fit) {
        var fx = bx0 + barW * frac;
        ctx.save(); ctx.font = eoDfs(w) - 1 + 'px "IBM Plex Mono", monospace';
        var tw2 = ctx.measureText(txt).width; ctx.restore();
        if (fx + 4 + tw2 <= bx0 + barW + 8) {
          eoDtx(ctx, fx + 4, y + bhh / 2, txt, fit ? ink : ink3, fs - 1, "left", "middle");
        } else {
          eoDtx(ctx, bx0 + barW - 4, y + bhh / 2, txt, CV("--bg"), fs - 1, "right", "middle", true);
        }
      };
      for (i = 0; i < rows.length; i++) {
        var r = rows[i];
        var bh = Math.max(12, Math.min(rowh - 8, 28));      /* แท่งสูงตามพื้นที่จริง — ไม่เหลือช่องว่างท้ายภาพ */
        var y = top + i * rowh + (rowh - bh) / 2;
        eoDtx(ctx, 6, y + bh / 2, r.e.n, r.fit ? ink : ink3, fs, "left", "middle", r.fit);
        eoDbox(ctx, x0, y, barW, bh, panel, line, 1);
        eoDbox(ctx, x0, y, barW * r.m / mMax, bh, r.fit ? acc : CV("--line"), null, 0);
        valLab(x0, r.m / mMax, y, bh, eoDn(r.m, 1), r.fit);
        var x2 = x0 + barW + 12;
        eoDbox(ctx, x2, y, barW, bh, panel, line, 1);
        eoDbox(ctx, x2, y, barW * r.V / vMax, bh, r.fit ? acc2 : CV("--line"), null, 0);
        valLab(x2, r.V / vMax, y, bh, eoDn(r.V, 1), r.fit);
        if (!r.fit) eoDtx(ctx, w - 4, y + bh / 2, r.fitCyc ? "не допущен" : "мало циклов", crit, fs - 1, "right", "middle");
      }
      var best = null, bestV = null;
      for (i = 0; i < rows.length; i++) {
        if (!rows[i].fit) continue;
        if (!best || rows[i].m < best.m) best = rows[i];
        if (!bestV || rows[i].V < bestV.V) bestV = rows[i];
      }
      readout.innerHTML =
        '<span>W = <b>' + s.W + ' Вт·ч</b> · ต้องการรอบประจุ ≥ <b>' + s.cyc + '</b>' + (s.sp ? ' · เฉพาะที่ <b>допущен к применению в космосе</b>' : '') + '</span>' +
        (best ? '<span>เบาที่สุด: <b class="good">' + best.e.n + '</b> — ' + eoDn(best.m, 1) + ' кг (w<sub>уд</sub> = ' + eoDn(best.ud, 0) + ' Вт·ч/кг)</span>' : '<span class="bad">ไม่มีชนิดใดผ่านเงื่อนไข</span>') +
        (bestV ? '<span>เล็กที่สุด: <b class="good">' + bestV.e.n + '</b> — ' + eoDn(bestV.V, 1) + ' дм³ (w<sub>габ</sub> = ' + bestV.e.gab + ' Вт·ч/дм³)</span>' : '') +
        '<span>Ag–Zn เบาและกินที่น้อยที่สุดแต่ทนได้เพียง <b>1</b> รอบสัมพัทธ์ · Ni–Cd ทน <b>60</b> รอบจึงเป็นชนิดหลักของ АБ บนดาวเทียม (จะใช้ซ้ำในหัวข้อ 6 เรื่อง СЭС КА)</span>' +
        '<span>Ni–H₂: เชิงอรรถของตารางระบุว่าติดตั้งบนดาวเทียมวงโคจร геосинхронная คาบ <b>12 ч</b> และการทดสอบภาคพื้นแบบเร่งให้จำนวนรอบมากกว่าของ Ni–Cd</span>';
    }
  });
}

window.EODEMOS = Object.assign(window.EODEMOS || {}, {
  eoStabQuality: eoStabQuality,
  eoStabTrans: eoStabTrans,
  eoStabZener: eoStabZener,
  eoStabTr: eoStabTr,
  eoStabComp: eoStabComp,
  eoStabFault: eoStabFault,
  eoISN: eoISN,
  eoISNzone: eoISNzone,
  eoISNeff: eoISNeff,
  eoOverload: eoOverload,
  eoProtect: eoProtect,
  eoShortCircuit: eoShortCircuit,
  eoStorageCmp: eoStorageCmp
});

/* ================= ЭОЛА — กลุ่ม E · Тема 6 (СЭС КА) และ Тема 7 (СЭС РН) =================
   12 แบบจำลอง: eoShadow, eoCyclogram, eoSESsize, eoDOD, eoOSH, eoRSH, eoSNzones,
   eoSBtemp, eoLogicOSH, eoRNbalance, eoRNstruct, eoISN4101
   แหล่งสูตร: notes/L12.md, notes/L13.md, notes/L14.md, notes/L15.md,
             notes/PZ-LOGIKA-OSH.md, notes/PZ-SES-RN-ISN.md
   ทุกสีอ่านผ่าน CV(...) ภายใน draw() เท่านั้น (ฟังก์ชันช่วยทั้งหมดถูกเรียกจากใน draw)
*/

/* ---------- เครื่องมือวาดร่วมของกลุ่ม E ---------- */

/* ---- ป้ายค่าบนแกนแบบเลขกลม (แทนการส่ง min/max ดิบเข้า ticks) ---- */
function eoNiceStepE(span, n) {
  var raw = Math.abs(span) / Math.max(1, n);
  if (!(raw > 0) || !isFinite(raw)) return 1;
  var e = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), f = raw / e;
  return (f < 1.5 ? 1 : f < 3.5 ? 2 : f < 7.5 ? 5 : 10) * e;
}
function eoTicksNice(a, b, n) {
  if (!isFinite(a) || !isFinite(b) || b <= a) return [a, b];
  /* เอนจินพิมพ์ป้ายด้วย toFixed(2) — ก้าวต่ำกว่า 0,01 จะได้ป้ายซ้ำ จึงยกพื้นไว้ */
  var st = Math.max(eoNiceStepE(b - a, n), 0.01), out = [], seen = {}, lab,
    k = Math.ceil((a - st * 1e-6) / st), guard = 0, v;
  for (; k * st <= b + st * 1e-6 && guard < 400; k++, guard++) {
    v = +(k * st).toPrecision(12);
    lab = String(+v.toFixed(2));
    if (seen[lab]) continue;
    seen[lab] = 1; out.push(v);
  }
  return out.length >= 2 ? out : [a, b];
}

function eoFont(px, bold) { return (bold ? "600 " : "") + px + 'px "IBM Plex Mono", monospace'; }

function eoTxt(ctx, s, x, y, col, px, align, base, bold) {
  ctx.save();
  ctx.fillStyle = col;
  ctx.font = eoFont(px, bold);
  ctx.textAlign = align || "left";
  ctx.textBaseline = base || "middle";
  ctx.fillText(s, x, y);
  ctx.restore();
}

function eoRRPath(ctx, x, y, w, h, r) {
  const rr = Math.max(0, Math.min(r, w / 2, h / 2));
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y); ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr); ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr); ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
}

function eoBox(ctx, x, y, w, h, txt, on, px) {
  ctx.save();
  eoRRPath(ctx, x, y, w, h, 4);
  ctx.fillStyle = on ? CV("--wash-2") : CV("--panel-2");
  ctx.fill();
  ctx.lineWidth = on ? 2 : 1;
  ctx.strokeStyle = on ? CV("--accent") : CV("--line-2");
  ctx.stroke();
  ctx.restore();
  eoTxt(ctx, txt, x + w / 2, y + h / 2, on ? CV("--ink") : CV("--ink-3"), px, "center", "middle", on);
}

function eoPath(ctx, pts, col, wd, dash) {
  ctx.save();
  ctx.beginPath();
  if (dash) ctx.setLineDash(dash);
  ctx.strokeStyle = col; ctx.lineWidth = wd || 1.4;
  ctx.lineJoin = "round"; ctx.lineCap = "round";
  pts.forEach((p, i) => { i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]); });
  ctx.stroke();
  ctx.restore();
}

function eoHead(ctx, x, y, ang, s, col) {
  ctx.save();
  ctx.fillStyle = col;
  ctx.translate(x, y); ctx.rotate(ang);
  ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(-s, s * 0.5); ctx.lineTo(-s, -s * 0.5);
  ctx.closePath(); ctx.fill();
  ctx.restore();
}

function eoArrowEnd(ctx, pts, col, s) {
  const n = pts.length;
  if (n < 2) return;
  const a = pts[n - 2], b = pts[n - 1];
  eoHead(ctx, b[0], b[1], Math.atan2(b[1] - a[1], b[0] - a[0]), s || 6, col);
}

/* จุดพลังงานวิ่งบนเส้นทางที่ทำงาน (ใช้กับ animate: true) */
function eoFlow(ctx, pts, col, phase, n, r) {
  const seg = [], L = [];
  let tot = 0;
  for (let i = 1; i < pts.length; i++) {
    const d = Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]);
    seg.push(d); tot += d; L.push(tot);
  }
  if (tot <= 0) return;
  ctx.save(); ctx.fillStyle = col;
  const k = n || 4;
  for (let j = 0; j < k; j++) {
    const u = ((phase + j / k) % 1) * tot;
    let i = 0;
    while (i < L.length - 1 && L[i] < u) i++;
    const s0 = i ? L[i - 1] : 0;
    const f = seg[i] ? (u - s0) / seg[i] : 0;
    const x = pts[i][0] + (pts[i + 1][0] - pts[i][0]) * f;
    const y = pts[i][1] + (pts[i + 1][1] - pts[i][1]) * f;
    ctx.beginPath(); ctx.arc(x, y, r || 2.6, 0, 7); ctx.fill();
  }
  ctx.restore();
}

/* แถบเทอร์โมมิเตอร์แนวตั้ง (แท่ง P_СБ ของ Л14 сл. 27) */
function eoBar(ctx, x, y, w, h, frac, col, back) {
  ctx.save();
  eoRRPath(ctx, x, y, w, h, 3); ctx.fillStyle = back; ctx.fill();
  ctx.strokeStyle = CV("--line-2"); ctx.lineWidth = 1; ctx.stroke();
  const fh = Math.max(0, Math.min(1, frac)) * (h - 4);
  if (fh > 0.5) {
    eoRRPath(ctx, x + 2, y + h - 2 - fh, w - 4, fh, 2);
    ctx.fillStyle = col; ctx.fill();
  }
  ctx.restore();
}

function eoFS(w) { return Math.max(8, Math.min(11, Math.round(w / 42))); }

/* ================================================================
   1. eoShadow — เรขาคณิตเงาโลกและระยะเวลา ТУО
   Л13 сл. 11 (Пространственная (а) และ плоская (б) геометрия ТУО + ตาราง ТУО)
   สูตร (Идея демонстраций ข้อ 1 ของ notes/L13.md — เรขาคณิตจากรูป сл. 11 б):
     r = R₃ + H
     T_вит = 2π·√(r³/μ)                            (กฎเคปเลอร์ที่สาม)
     Δ = arccos[ √(r² − R₃²) / (r·cos β) ]          (ครึ่งมุมส่วนโค้งเงาในระนาบวงโคจร)
     τ̄_т = Δ/π   (Л13 сл. 12: τ̄_т = τ_т/T_вит) ,  τ_т = τ̄_т·T_вит
   เงาเป็นทรงกระบอกรัศมี R₃ (модель цилиндрической тени) — ตรงกับรูป «Цилиндр тени» сл. 11
   ตรวจผลกับตารางจริง сл. 11: НОО ≈37 мин · ГЛОНАСС ≈56 мин · ГСО ≈71 мин
================================================================ */
function eoShadow(host) {
  buildDemo(host, {
    label: "Лекция 13 · сл. 11–12 (геометрия ТУО)",
    title: "เลื่อนความสูงวงโคจรและมุมเบตา แล้วดูส่วนโค้งเงาและระยะเวลา ТУО เทียบกับตารางจริงของสไลด์ 11",
    ratio: 0.62,
    legend: '<span><i style="background:var(--accent)"></i>ส่วนโค้งที่อยู่ในเงา (ТУО)</span>' +
            '<span><i style="background:var(--accent-2)"></i>ค่าที่คำนวณได้</span>' +
            '<span><i style="background:var(--ink-3)"></i>ค่าจากตาราง сл. 11</span>',
    controls: [
      { id: "H", label: "H — ความสูงวงโคจร, км", min: 200, max: 36000, step: 100, value: 500, fmt: v => v.toFixed(0) },
      { id: "b", label: "β — มุมระหว่างทิศดวงอาทิตย์กับระนาบวงโคจร, град", min: 0, max: 90, step: 1, value: 0 }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink = CV("--ink"),
            ink2 = CV("--ink-2"), ink3 = CV("--ink-3"), line2 = CV("--line-2"),
            ok = CV("--ok"), crit = CV("--crit");
      const RE = 6371, MU = 398600.44;
      const rad = Math.PI / 180;

      function calc(H, b) {
        const r = RE + H;
        const T = 2 * Math.PI * Math.sqrt(r * r * r / MU) / 60;
        const arg = Math.sqrt(r * r - RE * RE) / (r * Math.cos(b * rad));
        if (arg >= 1) return { r: r, T: T, D: 0, f: 0, tau: 0, none: true };
        const D = Math.acos(arg);
        const f = D / Math.PI;
        return { r: r, T: T, D: D, f: f, tau: f * T, none: false };
      }

      const c = calc(s.H, s.b);
      const fs = eoFS(w);
      const wide = w >= 470;
      const gx = 6, gy = 6;
      const gw = wide ? Math.round(w * 0.56) - 10 : w - 12;
      const gh = wide ? h - 12 : Math.round(h * 0.58);

      /* --- แผงซ้าย: เรขาคณิตในระนาบวงโคจร (มุมมอง б ของ сл. 11) --- */
      ctx.save();
      eoRRPath(ctx, gx, gy, gw, gh, 6);
      ctx.fillStyle = CV("--panel-2"); ctx.fill();
      ctx.strokeStyle = line2; ctx.lineWidth = 1; ctx.stroke();
      ctx.clip();

      const cx = gx + gw * 0.56, cy = gy + gh * 0.52;
      const sc = Math.min(gw * 0.40, gh * 0.40) / c.r;
      const rp = c.r * sc, rep = Math.max(2.5, RE * sc);

      /* แถบเงา: x²·sin²β + y² < R₃² บนซีกตรงข้ามดวงอาทิตย์ (x < 0) */
      const sb = Math.sin(s.b * rad);
      ctx.beginPath();
      const xlim = -(gx + gw + 40 - cx) / sc;
      const N = 90;
      for (let i = 0; i <= N; i++) {
        const xx = xlim * (1 - i / N);
        const yy = Math.sqrt(Math.max(0, RE * RE - xx * xx * sb * sb));
        i ? ctx.lineTo(cx + xx * sc, cy - yy * sc) : ctx.moveTo(cx + xx * sc, cy - yy * sc);
      }
      for (let i = N; i >= 0; i--) {
        const xx = xlim * (1 - i / N);
        const yy = Math.sqrt(Math.max(0, RE * RE - xx * xx * sb * sb));
        ctx.lineTo(cx + xx * sc, cy + yy * sc);
      }
      ctx.closePath();
      ctx.fillStyle = CV("--wash");
      ctx.fill();
      ctx.strokeStyle = ink3; ctx.setLineDash([3, 3]); ctx.lineWidth = 1; ctx.stroke();
      ctx.setLineDash([]);

      /* รังสีดวงอาทิตย์เข้าจากขวา */
      for (let i = 0; i < 4; i++) {
        const yy = gy + gh * (0.18 + i * 0.21);
        eoPath(ctx, [[gx + gw - 6, yy], [gx + gw - 30, yy]], ink3, 1);
        eoHead(ctx, gx + gw - 30, yy, Math.PI, 4, ink3);
      }
      eoTxt(ctx, "Лучи Солнца", gx + gw - 6, gy + 8, ink3, fs - 1, "right", "middle");

      /* วงโคจร */
      ctx.save();
      ctx.strokeStyle = line2; ctx.lineWidth = 1; ctx.setLineDash([4, 3]);
      ctx.beginPath(); ctx.arc(cx, cy, rp, 0, 7); ctx.stroke();
      ctx.restore();

      /* ส่วนโค้งที่อยู่ในเงา */
      if (!c.none) {
        ctx.save();
        ctx.strokeStyle = acc; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.arc(cx, cy, rp, Math.PI - c.D, Math.PI + c.D); ctx.stroke();
        ctx.restore();
        const t1 = [cx + rp * Math.cos(Math.PI - c.D), cy + rp * Math.sin(Math.PI - c.D)];
        const t2 = [cx + rp * Math.cos(Math.PI + c.D), cy + rp * Math.sin(Math.PI + c.D)];
        ctx.save(); ctx.fillStyle = acc;
        ctx.beginPath(); ctx.arc(t1[0], t1[1], 3, 0, 7); ctx.fill();
        ctx.beginPath(); ctx.arc(t2[0], t2[1], 3, 0, 7); ctx.fill();
        ctx.restore();
        eoTxt(ctx, "Т1", t1[0] - 4, t1[1] + 10, acc, fs - 1, "right", "middle", true);
        eoTxt(ctx, "Т2", t2[0] - 4, t2[1] - 10, acc, fs - 1, "right", "middle", true);
        /* มุมศูนย์กลาง Δθ = 2σ */
        eoPath(ctx, [[cx, cy], t1], ink3, 1, [2, 3]);
        eoPath(ctx, [[cx, cy], t2], ink3, 1, [2, 3]);
        eoTxt(ctx, "Δθ = 2σ = " + (2 * c.D / rad).toFixed(1) + "°",
          gx + 8, gy + gh - 10, ink2, fs - 1, "left", "middle");
      } else {
        eoTxt(ctx, "бестеневой период", cx, cy - rp - 14, ok, fs, "center", "middle", true);
      }

      /* โลก */
      ctx.save();
      ctx.beginPath(); ctx.arc(cx, cy, rep, 0, 7);
      ctx.fillStyle = CV("--wash-2"); ctx.fill();
      ctx.strokeStyle = ink2; ctx.lineWidth = 1.2; ctx.stroke();
      ctx.restore();
      if (rep > 9) eoTxt(ctx, "R₃", cx, cy, ink2, fs - 1, "center", "middle");

      eoTxt(ctx, "H = " + s.H.toFixed(0) + " км · β = " + s.b.toFixed(0) + "°",
        gx + 8, gy + 10, ink, fs, "left", "middle", true);
      ctx.restore();

      /* --- แผงขวา: เทียบกับตาราง сл. 11 --- */
      const bx = wide ? gx + gw + 8 : gx;
      const by = wide ? gy : gy + gh + 8;
      const bw = wide ? w - bx - 6 : w - 12;
      const bh = wide ? h - 12 : h - by - 6;

      ctx.save();
      eoRRPath(ctx, bx, by, bw, bh, 6);
      ctx.fillStyle = CV("--panel-2"); ctx.fill();
      ctx.strokeStyle = line2; ctx.lineWidth = 1; ctx.stroke();
      ctx.restore();

      const REF = [
        { n: "НОО 180", H: 180, t: 37 },
        { n: "НОО 5000", H: 5000, t: 37 },
        { n: "ГЛОНАСС", H: 20000, t: 56 },
        { n: "ГСО", H: 36000, t: 71 }
      ];
      eoTxt(ctx, "ТУО, мин — расчёт против таблицы сл. 11", bx + 8, by + 12, ink, fs, "left", "middle", true);
      const rowH = (bh - 34) / REF.length;
      const lblW = Math.max(52, bw * 0.26);
      const maxT = 80;
      REF.forEach((rf, i) => {
        const m = calc(rf.H, 0);
        const y0 = by + 26 + i * rowH;
        eoTxt(ctx, rf.n, bx + 6, y0 + rowH * 0.42, ink2, fs - 1, "left", "middle");
        const x0 = bx + lblW, aw = bw - lblW - 40;
        ctx.save();
        ctx.fillStyle = ink3;
        ctx.fillRect(x0, y0 + rowH * 0.10, aw * rf.t / maxT, Math.max(4, rowH * 0.26));
        ctx.fillStyle = acc2;
        ctx.fillRect(x0, y0 + rowH * 0.44, aw * m.tau / maxT, Math.max(4, rowH * 0.26));
        ctx.restore();
        eoTxt(ctx, rf.t.toFixed(0), x0 + aw * rf.t / maxT + 4, y0 + rowH * 0.23, ink3, fs - 2, "left", "middle");
        eoTxt(ctx, m.tau.toFixed(1), x0 + aw * m.tau / maxT + 4, y0 + rowH * 0.57, acc2, fs - 2, "left", "middle");
      });

      const dev = Math.abs(c.tau - 37) / 37 * 100;
      const cls = c.none ? "good" : "";
      readout.innerHTML =
        'ТУО = <b class="' + cls + '">' + (c.none ? "0 (нет тени)" : c.tau.toFixed(1) + " мин") + '</b>' +
        '<span>T<sub>вит</sub> = <b>' + c.T.toFixed(1) + ' мин</b></span>' +
        '<span>τ̄<sub>т</sub> = <b>' + (c.f * 100).toFixed(1) + ' %</b></span>' +
        '<span>2σ = <b>' + (2 * c.D / rad).toFixed(1) + '°</b></span>' +
        '<span>' + (c.none
          ? 'β ใหญ่พอจน เงาโลกพลาดวงโคจร — นี่คือ бестеневая зона ของตาราง сл. 11 (ГСО 4,5 мес)'
          : 'แบบจำลองทรงกระบอกเงาต่างจากตาราง сл. 11 ไม่เกิน ±3 % — <b>สูงกว่า</b>เล็กน้อยที่ НОО และ <b>ต่ำกว่า</b>เล็กน้อยที่ ГЛОНАСС/ГСО เพราะไม่นับ полутень (сл. 12 โซน 1 และ 4)') +
        '</span>' +
        '<span>ตาราง сл. 11: НОО ≈37 · ГЛОНАСС ≈56 · ГСО ≈71 мин · ' +
        (dev < 8 ? 'ค่าปัจจุบันใกล้เคียงกลุ่ม НОО' : 'ค่าปัจจุบันอยู่นอกกลุ่ม НОО') + '</span>';
    }
  });
}

/* ================================================================
   2. eoCyclogram — กราฟการใช้พลังงาน (ГЭП) แบบขั้นบันได + สมดุลกำลัง
   Л13 сл. 16 (สูตร 4 และ 5), ตัวเลขจริงของช่วงจาก Л13 сл. 18
     P_Q i = P_СБ i − P_Нi/η_СН = const , t ∈ Δt_i
     W_P = Σ P_Нi·Δt_i = P_НСР·T
   виток = 95 мин · เข้าเงาที่ 60 мин (0,63 витка) · ระดับสูงสุด 1,0 = 1200 Вт (сл. 18)
================================================================ */
function eoCyclogram(host) {
  buildDemo(host, {
    label: "Лекция 13 · сл. 16, 18 (ГЭП และ ГЭГ)",
    title: "เลื่อนกำลังของ СБ และ КПД ของ СН แล้วดูว่าแต่ละช่วง Δt แบตชาร์จหรือคาย และสมดุลต่อรอบเป็นบวกหรือลบ",
    ratio: 0.58,
    legend: '<span><i style="background:var(--accent)"></i>P<sub>Н</sub>(t) — โหลด</span>' +
            '<span><i style="background:var(--accent-2)"></i>P<sub>СБ</sub>(t)</span>' +
            '<span><i style="background:var(--ok)"></i>P<sub>Q</sub> &gt; 0 ชาร์จ</span>' +
            '<span><i style="background:var(--crit)"></i>P<sub>Q</sub> &lt; 0 คาย</span>',
    controls: [
      { id: "psb", label: "P<sub>СБ</sub> — กำลังที่ СБ ผลิตบนช่วงสว่าง, Вт", min: 0, max: 2000, step: 20, value: 1200, fmt: v => v.toFixed(0) },
      { id: "kn", label: "ตัวคูณระดับโหลดของไซโคลแกรม", min: 0.4, max: 1.6, step: 0.05, value: 1, fmt: v => v.toFixed(2) },
      { id: "eta", label: "η<sub>СН</sub> — КПД ของวงจรรักษาระดับแรงดัน", min: 0.8, max: 0.98, step: 0.01, value: 0.9, fmt: v => v.toFixed(2) }
    ],
    buttons: [
      { id: "dej", label: "дежурный виток", toggle: true, value: false }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink3 = CV("--ink-3"),
            ok = CV("--ok"), crit = CV("--crit"), ink2 = CV("--ink-2");
      const TV = 95, TSH = 60, PBASE = 1200;
      /* ระดับของ рабочий / дежурный виток ตาม сл. 18 */
      const lev = s.dej ? [[0, 19, 0.5], [19, 38, 0.5], [38, TSH, 0.5], [TSH, TV, 0.4]]
                        : [[0, 19, 0.4], [19, 38, 0.8], [38, TSH, 1.0], [TSH, TV, 0.4]];
      const segs = lev.map(v => {
        const pn = v[2] * PBASE * s.kn;
        const psb = v[0] >= TSH ? 0 : s.psb;
        return { a: v[0], b: v[1], pn: pn, psb: psb, pq: psb - pn / s.eta };
      });
      let WP = 0, WQ = 0;
      segs.forEach(g => { WP += g.pn * (g.b - g.a); WQ += g.pq * (g.b - g.a); });
      const PSR = WP / TV;
      const ymax = Math.max(1.15 * s.psb, 1.25 * PBASE * s.kn, 400);
      const ymin = Math.min(0, 1.15 * Math.min.apply(null, segs.map(g => g.pq)));

      const fs = eoFS(w);
      const p = new Plot(ctx, 46, 18, w - 60, h - 52, 0, TV, ymin, ymax);
      p.frame(ticks(0, TV, 5), eoTicksNice(ymin, ymax, 4), "t, мин","P, Вт");

      /* แถบช่วงเงา */
      ctx.save();
      ctx.fillStyle = CV("--wash");
      ctx.fillRect(p.X(TSH), p.y, p.X(TV) - p.X(TSH), p.h);
      ctx.restore();
      eoTxt(ctx, "ТУО 35 мин", (p.X(TSH) + p.X(TV)) / 2, p.y + 10, ink3, fs - 1, "center", "middle");

      /* แถบ P_Q ระหว่าง P_СБ กับ P_Н/η_СН */
      segs.forEach(g => {
        const x0 = p.X(g.a), x1 = p.X(g.b);
        const yA = p.Y(g.psb), yB = p.Y(g.pn / s.eta);
        ctx.save();
        ctx.fillStyle = g.pq >= 0 ? ok : crit;
        ctx.globalAlpha = 0.18;
        ctx.fillRect(x0, Math.min(yA, yB), x1 - x0, Math.abs(yB - yA));
        ctx.restore();
        if (x1 - x0 > 34) {
          eoTxt(ctx, (g.pq >= 0 ? "+" : "") + g.pq.toFixed(0),
            (x0 + x1) / 2, (yA + yB) / 2, g.pq >= 0 ? ok : crit, fs - 1, "center", "middle", true);
        }
      });

      /* เส้นขั้นบันได P_Н และ P_Н/η_СН */
      const stepPts = a => {
        const o = [];
        segs.forEach(g => { o.push([g.a, a(g)]); o.push([g.b, a(g)]); });
        return o;
      };
      p.clip(() => {
        p.line(stepPts(g => g.pn / s.eta), acc, 1.2, [3, 3]);
        p.line(stepPts(g => g.pn), acc, 2.2);
        p.line(stepPts(g => g.psb), acc2, 1.8, [6, 4]);
        p.line([[0, PSR], [TV, PSR]], ink2, 1, [2, 4]);
      });
      eoTxt(ctx, "P НСР = " + PSR.toFixed(0) + " Вт", p.X(TV) - 4, p.Y(PSR) - 8, ink2, fs - 1, "right", "middle");

      /* ป้ายช่วง Δt */
      segs.forEach((g, i) => {
        const x0 = p.X(g.a), x1 = p.X(g.b);
        if (x1 - x0 > 26) {
          eoTxt(ctx, "Δt" + (i ? "+" + i : ""), (x0 + x1) / 2, p.y + p.h - 8, ink3, fs - 2, "center", "middle");
        }
      });

      const dW = WQ / 60;
      readout.innerHTML =
        'ΔW<sub>АБ</sub> за виток = <b class="' + (dW >= 0 ? "good" : "bad") + '">' +
        (dW >= 0 ? "+" : "") + dW.toFixed(1) + ' Вт·ч</b>' +
        '<span>P<sub>НСР</sub> = <b>' + PSR.toFixed(0) + ' Вт</b></span>' +
        '<span>W<sub>P</sub> = <b>' + (WP / 60).toFixed(0) + ' Вт·ч</b> ต่อรอบ</span>' +
        '<span>P<sub>Q</sub> ในเงา = <b>' + segs[3].pq.toFixed(0) + ' Вт</b></span>' +
        '<span>' + (dW >= 0
          ? 'สมดุลเป็นบวก — ถ้าเกินต่อเนื่อง АБ จะเข้า режим сохранения заряженности และ ЗУ ถูกตัดเป็นช่วง (сл. 20 ข้อ 2)'
          : 'สมดุลเป็นลบ — дефицит สะสมทุกวันจะทำให้แรงดันขั้นต่ำของ СЭС ลดลงจนต้องตัดโหลดหนักโดยอัตโนมัติ (сл. 20 ข้อ 1)') +
        '</span>' +
        '<span>สูตร: P<sub>Q i</sub> = P<sub>СБ i</sub> − P<sub>Нi</sub>/η<sub>СН</sub> (сл. 16) · виток 95 мин, เข้าเงาที่ 60 мин, ระดับ 1,0 = 1200 Вт (сл. 18)</span>';
    }
  });
}

/* ================================================================
   3. eoSESsize — คำนวณพื้นที่ СБ และความจุ АБ จากวัฏจักรพลังงาน
   «ผู้เรียบเรียงคำนวณ» — ประกอบสูตรจริงสองสูตรเข้าด้วยกัน:
     P_M = C·η·k_Д·k_ЗЭ·S·cos α          (Л13 сл. 14 · Л12 сл. 26)
     P_Q i = P_СБ i − P_Нi/η_СН          (Л13 сл. 16)
   เงื่อนไขสมดุลต่อหนึ่ง виток (ผู้เรียบเรียงเขียนเอง จาก W_C(T) = W_П(T) + ΔW(T), сл. 19):
     P_СБ·(T − τ_т) = P_Н·(T − τ_т)/η_СН + [P_Н·τ_т/η_СН]/(η_ЗУ·η_РУ)
     ⇒ P_СБ = (P_Н/η_СН)·[ 1 + τ_т /((T − τ_т)·η_ЗУ·η_РУ) ]
     ⇒ S = P_СБ /(C·η·k_Д·k_ЗЭ·cos α)
     ⇒ C_АБ = P_Н·τ_т /(60·η_СН·η_РУ·U_н·ГР)   [А·ч],  U_н = 27 В (Л14 сл. 27)
   ตรวจกับตัวเลขจริง: удельная мощность Si 200 Вт/м² และ масса 1,7–1,85 кг/м² (Л12 сл. 24)
================================================================ */
function eoSESsize(host) {
  buildDemo(host, {
    label: "Лекция 13 сл. 14, 16 + Лекция 12 сл. 24, 26 · ผู้เรียบเรียงคำนวณ",
    title: "ผู้เรียบเรียงคำนวณ — ใส่กำลังโหลดและมุมตกกระทบ แล้วดูพื้นที่ СБ และความจุ АБ ที่ต้องมี",
    ratio: 0.58,
    legend: '<span><i style="background:var(--accent)"></i>S(α) — พื้นที่ที่ต้องมี</span>' +
            '<span><i style="background:var(--accent-2)"></i>จุดทำงานปัจจุบัน</span>' +
            '<span><i style="background:var(--ink-3)"></i>ตรวจทางลัด 200 Вт/м² (сл. 24)</span>',
    controls: [
      { id: "pn", label: "P<sub>НСР</sub> — กำลังโหลดเฉลี่ย, Вт", min: 100, max: 3000, step: 20, value: 700, fmt: v => v.toFixed(0) },
      { id: "al", label: "α — มุมเบี่ยงเบนของเส้นตั้งฉากแผงจากทิศดวงอาทิตย์, град", min: 0, max: 80, step: 1, value: 20 },
      { id: "eta", label: "η — КПД ของ СБ", min: 0.08, max: 0.32, step: 0.005, value: 0.14, fmt: v => v.toFixed(3) },
      { id: "gr", label: "ГР — ความลึกการคายประจุที่ยอมให้, %", min: 10, max: 80, step: 1, value: 25 }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink2 = CV("--ink-2"), ink3 = CV("--ink-3");
      const C = 1360, kD = 0.9, kZ = 0.85, etaSN = 0.9, etaZU = 0.9, etaRU = 0.9;
      const TV = 95, TT = 35, UN = 27, MSP = 1.75;
      const rad = Math.PI / 180;

      const Psb = (s.pn / etaSN) * (1 + TT / ((TV - TT) * etaZU * etaRU));
      const Sof = a => Psb / (C * s.eta * kD * kZ * Math.cos(a * rad));
      const S = Sof(s.al);
      const Sfast = Psb / 200;
      const Cab = s.pn * TT / (60 * etaSN * etaRU * UN * (s.gr / 100));
      const mass = S * MSP;

      const smax = Math.min(Math.max(Sof(70) * 1.05, S * 1.3), Sof(0) * 12);
      const p = new Plot(ctx, 46, 18, w - 60, h - 52, 0, 80, 0, smax);
      p.frame(ticks(0, 80, 4), eoTicksNice(0, smax, 4), "α, град","S, м²");

      const pts = [];
      for (let a = 0; a <= 80; a += 1) pts.push([a, Sof(a)]);
      p.clip(() => {
        p.line([[0, Sfast], [80, Sfast]], ink3, 1.2, [4, 4]);
        p.line(pts, acc, 2.2);
        p.line([[s.al, 0], [s.al, S]], acc2, 1, [2, 3]);
        p.dots([[s.al, S]], acc2, 4);
      });
      const fs = eoFS(w);
      {
        const st2 = "S = " + S.toFixed(1) + " м²";
        ctx.save(); ctx.font = eoFont(fs, true); const stw = ctx.measureText(st2).width; ctx.restore();
        const rr = p.X(s.al) + 6 + stw <= p.x + p.w - 2;
        eoTxt(ctx, st2, p.X(s.al) + (rr ? 6 : -6), Math.max(p.y + fs, p.Y(S) - 10), acc2, fs,
          rr ? "left" : "right", "middle", true);
      }
      eoTxt(ctx, "ทางลัด 200 Вт/м² → " + Sfast.toFixed(1) + " м²", p.x + 6, p.Y(Sfast) - 8, ink3, fs - 1, "left", "middle");

      readout.innerHTML =
        'S<sub>СБ</sub> = <b class="' + (S > 60 ? "bad" : "good") + '">' + S.toFixed(1) + ' м²</b>' +
        '<span>P<sub>СБ треб</sub> = <b>' + Psb.toFixed(0) + ' Вт</b></span>' +
        '<span>C<sub>АБ</sub> = <b>' + Cab.toFixed(1) + ' А·ч</b> ที่ ГР = ' + s.gr.toFixed(0) + ' %</span>' +
        '<span>มวลส่วนแผง ≈ <b>' + mass.toFixed(1) + ' кг</b> (1,75 кг/м², сл. 24)</span>' +
        '<span>cos α = <b>' + Math.cos(s.al * rad).toFixed(3) + '</b> — ตัวคูณเดียวนี้กินพื้นที่มากที่สุด เมื่อ α = 60° ต้องใช้แผงเป็นสองเท่า</span>' +
        '<span><b>ผู้เรียบเรียงคำนวณ</b> · สมมติค่าคงที่: C = 1360 Вт/м², k<sub>Д</sub> = 0,9, k<sub>ЗЭ</sub> = 0,85, η<sub>СН</sub> = η<sub>ЗУ</sub> = η<sub>РУ</sub> = 0,9, U<sub>н</sub> = 27 В, виток 95 мин / ТУО 35 мин — <b>สไลด์ไม่ให้ค่าเหล่านี้</b></span>';
    }
  });
}

/* ================================================================
   4. eoDOD — ความลึกการคายประจุ ГР กับความจุที่ใช้ได้และอายุ АБ
   Л13 сл. 23 — «Рисунок 8.4. Разрядные характеристики при различных токах разряда»
     แกน U 1,4…2,0 В ต่อเซลล์ · แกน Q/Q_н 0,25…1,0 · เส้น I_н, 2I_н, 10I_н
     เส้น 10I_н ตกถึงเข่าที่ ≈0,25 Q/Q_н · เส้น I_н ยืดถึง ≈0,85
   Л13 сл. 11 — «Требуемое число режимов разряда в год»: НОО 5000–6000 · ВЭО 360 · ГЛОНАСС 120 · ГСО 80–120
   เส้น N(ГР) เป็น «ผู้เรียบเรียง» — สไลด์ไม่มีข้อมูลอายุรอบต่อความลึกการคาย
================================================================ */
function eoDOD(host) {
  buildDemo(host, {
    label: "Лекция 13 · сл. 23 (рис. 8.4) และ сл. 11 (ตาราง ТУО)",
    title: "เลื่อนกระแสคายและความลึกการคายประจุ แล้วดูความจุที่ใช้ได้จริงและจำนวนรอบที่แบตทนได้เทียบกับวงโคจร",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>U(Q/Q<sub>н</sub>) ของสไลด์ 23</span>' +
            '<span><i style="background:var(--accent-2)"></i>ขอบเขต ГР ที่เลือก</span>' +
            '<span><i style="background:var(--ink-3)"></i>รอบที่วงโคจรต้องการต่อปี (сл. 11)</span>',
    controls: [
      { id: "k", label: "I / I<sub>н</sub> — กระแสคายเทียบค่าพิกัด", min: 1, max: 10, step: 0.5, value: 1, fmt: v => v.toFixed(1) },
      { id: "gr", label: "ГР — ความลึกการคายประจุ, %", min: 5, max: 100, step: 1, value: 25 },
      { id: "orb", label: "วงโคจร (1 НОО · 2 ВЭО · 3 ГЛОНАСС · 4 ГСО)", min: 1, max: 4, step: 1, value: 1,
        fmt: v => ["", "НОО", "ВЭО", "ГЛОНАСС", "ГСО"][Math.round(v)] },
      { id: "sas", label: "САС — อายุภารกิจที่ต้องการ, лет", min: 1, max: 15, step: 1, value: 5 }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink2 = CV("--ink-2"),
            ink3 = CV("--ink-3"), ok = CV("--ok"), crit = CV("--crit");
      const fs = eoFS(w);
      const wide = w >= 470;
      const pad = 6;
      const halfW = wide ? (w - 3 * pad) / 2 : w - 2 * pad;
      const halfH = wide ? h : (h - pad) / 2;

      /* --- ซ้าย: разрядная характеристика ของแบตเงิน-สังกะสี (сл. 23) --- */
      const qmax = Math.max(0.10, 0.85 * (1 - 0.30 * Math.log(s.k)));
      const Uof = q => {
        const x = q / qmax;
        const U1 = 1.87 - 0.012 * (s.k - 1), U2 = 1.52 - 0.010 * (s.k - 1);
        const sg = 1 / (1 + Math.exp(-(x - 0.32) / 0.05));
        const u = Math.max(0, (x - 0.90) / 0.10);
        return U1 + (U2 - U1) * sg - 0.12 * u * u - 2.0 * Math.pow(Math.max(0, x - 1), 2);
      };
      const p1 = new Plot(ctx, 40, 18, halfW - 46, halfH - 52, 0, 1, 1.3, 2.05);
      p1.frame(eoTicksNice(0, 1, 4), eoTicksNice(1.3, 2.05, 3), "Q/Q н","U, В");
      const cur = [];
      for (let q = 0; q <= Math.min(1, qmax * 1.05); q += 0.005) cur.push([q, Uof(q)]);
      p1.clip(() => {
        [1, 2, 10].forEach(kk => {
          const qm = Math.max(0.10, 0.85 * (1 - 0.30 * Math.log(kk)));
          const ref = [];
          for (let q = 0; q <= Math.min(1, qm * 1.05); q += 0.01) {
            const x = q / qm, U1 = 1.87 - 0.012 * (kk - 1), U2 = 1.52 - 0.010 * (kk - 1);
            const sg = 1 / (1 + Math.exp(-(x - 0.32) / 0.05));
            const u = Math.max(0, (x - 0.90) / 0.10);
            ref.push([q, U1 + (U2 - U1) * sg - 0.12 * u * u - 2.0 * Math.pow(Math.max(0, x - 1), 2)]);
          }
          p1.line(ref, ink3, 1, [3, 3]);
        });
        p1.line(cur, acc, 2.2);
        p1.line([[s.gr / 100, 1.3], [s.gr / 100, 2.05]], acc2, 1.4, [2, 3]);
      });
      eoTxt(ctx, "I н", p1.X(0.86), p1.Y(1.58), ink3, fs - 2, "left", "middle");
      eoTxt(ctx, "10I н", p1.X(0.26), p1.Y(1.44), ink3, fs - 2, "left", "middle");
      eoTxt(ctx, "ГР", p1.X(s.gr / 100) + 3, p1.y + 10, acc2, fs - 1, "left", "middle", true);

      /* --- ขวา: จำนวนรอบที่ทนได้ N(ГР) (ผู้เรียบเรียง) --- */
      const ORB = [
        { n: "НОО", cy: 5500 }, { n: "ВЭО", cy: 360 },
        { n: "ГЛОНАСС", cy: 120 }, { n: "ГСО", cy: 100 }
      ][Math.max(0, Math.min(3, Math.round(s.orb) - 1))];
      const Nof = g => 300 * Math.pow(1 / g, 1.6);
      const Ncur = Nof(s.gr / 100);
      const need = ORB.cy * s.sas;

      const bx = wide ? pad * 2 + halfW : pad;
      const by = wide ? 0 : halfH + pad;
      const p2 = new Plot(ctx, bx + 40, by + 18, halfW - 46, halfH - 52, 5, 100, 0, 14000);
      p2.frame(eoTicksNice(5, 100, 4), eoTicksNice(0, 14000, 4), "ГР, %","N циклов");
      const np = [];
      for (let g = 5; g <= 100; g += 1) np.push([g, Nof(g / 100)]);
      p2.clip(() => {
        p2.line(np, acc, 2.2);
        p2.line([[5, need], [100, need]], ink3, 1.4, [5, 4]);
        p2.line([[s.gr, 0], [s.gr, Ncur]], acc2, 1, [2, 3]);
        p2.dots([[s.gr, Ncur]], acc2, 4);
      });
      /* ตรึงป้ายไว้ในกรอบ — เดิมลอยออกนอกผ้าใบเมื่อ need เกิน ymax */
      eoTxt(ctx, ORB.n + ": " + need.toFixed(0) + " циклов за " + s.sas.toFixed(0) + " лет",
        p2.x + 4, Math.max(p2.y + fs, Math.min(p2.y + p2.h - 4, p2.Y(need) - 8)), ink3, fs - 2, "left", "middle");

      const years = Ncur / ORB.cy;
      readout.innerHTML =
        'อายุที่ได้ = <b class="' + (years >= s.sas ? "good" : "bad") + '">' + years.toFixed(1) + ' лет</b> ' +
        (years >= s.sas ? "≥ САС ที่ต้องการ" : "< САС ที่ต้องการ") +
        '<span>ความจุที่ใช้ได้ที่ ' + s.k.toFixed(1) + ' I<sub>н</sub> = <b>' + (qmax * 100).toFixed(0) + ' %</b> ของ Q<sub>н</sub></span>' +
        '<span>N(ГР) = <b>' + Ncur.toFixed(0) + '</b> รอบ · ต้องการ <b>' + need.toFixed(0) + '</b> รอบ</span>' +
        '<span>' + ORB.n + ' ต้องการ <b>' + ORB.cy + '</b> รอบคายประจุต่อปี (ตาราง сл. 11)</span>' +
        '<span>ที่ 10 I<sub>н</sub> แบตให้ความจุใช้งานเพียง ≈25 % ของค่าที่ระบุ — นี่คือเหตุผลเชิงปริมาณที่ СЭС โครงสร้างง่ายที่สุดถูกจำกัดไว้ที่ 15 суток (сл. 21, 23)</span>' +
        '<span><b>ผู้เรียบเรียง</b> — เส้น N(ГР) = 300·(1/ГР)<sup>1,6</sup> เป็นแบบจำลองเชิงประจักษ์ที่ผู้เรียบเรียงเลือกเอง <b>สไลด์ไม่มีข้อมูลอายุรอบต่อความลึกการคายเลย</b> ส่วนเส้น U(Q/Q<sub>н</sub>) ปรับให้ผ่านจุดจริงของ рис. 8.4 (เข่าที่ 0,25 สำหรับ 10I<sub>н</sub> และ 0,85 สำหรับ I<sub>н</sub>)</span>';
    }
  });
}

/* ================================================================
   5. eoOSH — СЭС แบบบัสรวม (общие шины): เลือกโหมดเองตามสมดุลกำลัง
   Л14 сл. 12 (кирхгофовы соотношения ของ ОШ):
     I_СБ + I_АБ = I_Н  ·  U_СБ = U_АБ = U_Н = U_ОШ
   Л14 сл. 16 (графический метод): I_Н = I_СБ − I_АБ, โหลดมาก → U_ОШ ต่ำ
   Л14 сл. 21: U_ВЫХ = γ·U_ВХ (РП เป็นคอนเวอร์เตอร์ ШИМ)
   Л14 сл. 27 (зонный принцип, ตัวเลขจริง 25,5 / 27,0 / 28,5 В) และ сл. 28 (สามโหมด, หกภาพ)
   Л13 сл. 16: P_Q = P_СБ − P_Н/η_СН — ใช้ตัดสินว่ากำลังเกินหรือขาด
   หมายเหตุ: แต่ละแถบของ Рис. 2.3 กำกับ «ขอบล่าง» ด้วย U₀ ของตัวเอง จึงอ่านเป็น
     РУ 25,5…27,0 · ЗУ 27,0…28,5 · СН เหนือ 28,5 В
================================================================ */
function eoOSH(host) {
  buildDemo(host, {
    label: "Лекция 14 · сл. 12, 21, 27, 28 (зонный принцип и режимы)",
    title: "เลื่อนกำลังของ СБ กับกำลังโหลด แล้วดูระบบเลือกโหมดเอง — เส้นทางพลังงานที่ทำงานจะสว่างขึ้นและตัวชี้เลื่อนไปตามแถบแรงดัน",
    ratio: 0.62,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>เส้นทางพลังงานที่ทำงาน</span>' +
            '<span><i style="background:var(--ok)"></i>แถบ ЗУ 27,0–28,5 В</span>' +
            '<span><i style="background:var(--crit)"></i>แถบ РУ 25,5–27,0 В</span>' +
            '<span><i style="background:var(--accent-2)"></i>แถบ СН เหนือ 28,5 В</span>',
    controls: [
      { id: "psb", label: "P<sub>СБ</sub> — กำลังที่ СБ ผลิตได้, Вт", min: 0, max: 1500, step: 10, value: 900, fmt: v => v.toFixed(0) },
      { id: "pn", label: "P<sub>Н</sub> — กำลังโหลด, Вт", min: 0, max: 1200, step: 10, value: 500, fmt: v => v.toFixed(0) },
      { id: "soz", label: "ระดับประจุของ АБ, %", min: 0, max: 100, step: 1, value: 60 }
    ],
    draw(ctx, w, h, s, readout, t) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink = CV("--ink"),
            ink2 = CV("--ink-2"), ink3 = CV("--ink-3"), line2 = CV("--line-2"),
            ok = CV("--ok"), crit = CV("--crit"), panel2 = CV("--panel-2");
      const ETA = 0.9, PZU = 600, PRU = 900, PSN = 600;
      const fs = eoFS(w);

      /* --- แบบจำลองโหมด --- */
      const pex = s.psb - s.pn / ETA;
      let U, mode, gam, gname;
      const full = s.soz >= 99.5, empty = s.soz <= 0.5;
      if (pex >= 0 && (full || pex > PZU)) {
        mode = "СН"; gname = "γ сн";
        U = 28.5 + 1.5 * Math.min(1, (full ? Math.max(pex, 1) : pex - PZU) / PSN);
        gam = Math.max(0, 1 - (U - 28.5) / 1.5);
      } else if (pex >= 0) {
        mode = "ЗУ"; gname = "γ зу";
        U = 27.0 + 1.5 * Math.min(1, pex / PZU);
        gam = (U - 27.0) / 1.5;
      } else {
        mode = "РУ"; gname = "γ ру";
        U = 27.0 - 1.5 * Math.min(1, (-pex) / PRU);
        if (empty) U = 24.6;
        gam = Math.min(1, (27.0 - U) / 1.5);
      }
      const avar = U < 25.5;
      const on = { sn: !avar, zu: mode === "ЗУ" && !full, ru: mode === "РУ" && !empty, ab: mode !== "СН" && !avar };

      /* --- ผังบล็อก --- */
      const lw = 26, rw = 52;
      const px = lw + 4, py = 6, pw = w - lw - rw - 12, ph = h - 12;
      const bw = Math.max(34, pw * 0.15), bh = Math.max(20, ph * 0.15);
      const yTop = py + ph * 0.16, yMid = py + ph * 0.52, yBot = py + ph * 0.84;
      const xSB = px + pw * 0.01, xA = px + pw * 0.30, xSN = px + pw * 0.40,
            xB = px + pw * 0.74, xP = px + pw * 0.85, xAB = px + pw * 0.44;

      const nA = [xA, yTop], nB = [xB, yTop];
      const pMain = [[xSB + bw, yTop], nA, [xSN, yTop]];
      const pMain2 = [[xSN + bw, yTop], nB, [xP, yTop]];
      const pChg = [nA, [xA, yMid]];
      const pChg2 = [[xA, yMid + bh], [xA, yBot + bh / 2], [xAB, yBot + bh / 2]];
      const pDis = [[xAB + bw, yBot + bh / 2], [xB, yBot + bh / 2], [xB, yMid + bh]];
      const pDis2 = [[xB, yMid], nB];

      const dim = line2, hot = acc;
      const wOn = 2.4, wOff = 1.2;
      /* เส้นทางหลัก СБ → СН → П */
      eoPath(ctx, pMain, on.sn ? hot : dim, on.sn ? wOn : wOff);
      eoPath(ctx, pMain2, on.sn ? hot : dim, on.sn ? wOn : wOff);
      eoArrowEnd(ctx, pMain2, on.sn ? hot : dim, 6);
      /* เส้นทางประจุ СБ → ЗУ → АБ */
      eoPath(ctx, pChg, on.zu ? hot : dim, on.zu ? wOn : wOff);
      eoPath(ctx, pChg2, on.zu ? hot : dim, on.zu ? wOn : wOff);
      eoArrowEnd(ctx, pChg2, on.zu ? hot : dim, 5);
      /* เส้นทางคาย АБ → РУ → П */
      eoPath(ctx, pDis, on.ru ? hot : dim, on.ru ? wOn : wOff);
      eoPath(ctx, pDis2, on.ru ? hot : dim, on.ru ? wOn : wOff);
      eoArrowEnd(ctx, pDis2, on.ru ? hot : dim, 5);

      const ph1 = (t * 0.32) % 1;
      if (on.sn) { eoFlow(ctx, pMain, acc, ph1, 3); eoFlow(ctx, pMain2, acc, ph1, 3); }
      if (on.zu) { eoFlow(ctx, pChg, acc, ph1, 2); eoFlow(ctx, pChg2, acc, ph1, 3); }
      if (on.ru) { eoFlow(ctx, pDis, acc, ph1, 3); eoFlow(ctx, pDis2, acc, ph1, 2); }

      eoBox(ctx, xSB, yTop - bh / 2, bw, bh, "СБ", s.psb > 1, fs);
      eoBox(ctx, xSN, yTop - bh / 2, bw, bh, "СН", on.sn, fs);
      eoBox(ctx, xP, yTop - bh / 2, Math.min(bw, px + pw - xP), bh, "П", !avar, fs);
      eoBox(ctx, xA - bw / 2, yMid, bw, bh, "ЗУ", on.zu, fs);
      eoBox(ctx, xB - bw / 2, yMid, bw, bh, "РУ", on.ru, fs);
      eoBox(ctx, xAB, yBot, bw, bh, "АБ", on.ab, fs);

      eoTxt(ctx, "+ ШИ", xA - 2, yTop - bh / 2 - 8, ink3, fs - 2, "right", "middle");
      eoTxt(ctx, "+ ШН", xB + 2, yTop - bh / 2 - 8, ink3, fs - 2, "left", "middle");
      eoTxt(ctx, "+ ШАБ", xAB + bw + 6, yBot + bh / 2, ink3, fs - 2, "left", "middle");

      /* --- แท่ง P_СБ ด้านซ้าย (ตาม сл. 27) --- */
      eoBar(ctx, 6, py + 14, 14, ph - 28, s.psb / 1500, acc2, panel2);
      eoTxt(ctx, "P СБ", 13, py + 6, ink3, fs - 2, "center", "middle");

      /* --- สเกลแรงดันด้านขวา 25,5 / 27,0 / 28,5 --- */
      const sx = w - rw + 4, sy = py + 14, sh = ph - 28, sw = 16;
      const Umin = 24, Umax = 30;
      const Yu = v => sy + sh - (v - Umin) / (Umax - Umin) * sh;
      ctx.save();
      ctx.fillStyle = panel2; ctx.fillRect(sx, sy, sw, sh);
      ctx.fillStyle = crit; ctx.globalAlpha = 0.35;
      ctx.fillRect(sx, Yu(27.0), sw, Yu(25.5) - Yu(27.0));
      ctx.fillStyle = ok;
      ctx.fillRect(sx, Yu(28.5), sw, Yu(27.0) - Yu(28.5));
      ctx.fillStyle = acc2;
      ctx.fillRect(sx, Yu(Umax), sw, Yu(28.5) - Yu(Umax));
      ctx.globalAlpha = 1;
      ctx.strokeStyle = line2; ctx.lineWidth = 1; ctx.strokeRect(sx + .5, sy + .5, sw, sh);
      ctx.restore();
      [25.5, 27.0, 28.5].forEach(v => {
        eoPath(ctx, [[sx, Yu(v)], [sx + sw, Yu(v)]], ink3, 1);
        eoTxt(ctx, v.toFixed(1), sx - 3, Yu(v), ink3, fs - 2, "right", "middle");
      });
      eoTxt(ctx, "РУ", sx + sw + 2, (Yu(25.5) + Yu(27)) / 2, crit, fs - 2, "left", "middle");
      eoTxt(ctx, "ЗУ", sx + sw + 2, (Yu(27) + Yu(28.5)) / 2, ok, fs - 2, "left", "middle");
      eoTxt(ctx, "СН", sx + sw + 2, (Yu(28.5) + Yu(Umax)) / 2, acc2, fs - 2, "left", "middle");
      const yu = Yu(Math.max(Umin, Math.min(Umax, U)));
      eoPath(ctx, [[sx - 5, yu], [sx + sw + 1, yu]], acc, 2.4);
      eoHead(ctx, sx + sw + 1, yu, 0, 5, acc);
      eoTxt(ctx, "U, В", sx + sw / 2, sy - 7, ink3, fs - 2, "center", "middle");

      /* ป้ายโหมด */
      eoTxt(ctx, "режим " + mode + (avar ? " · авария" : ""), px + 2, py + 6, avar ? crit : ink,
        fs + 1, "left", "middle", true);

      readout.innerHTML =
        'U<sub>ОШ</sub> = <b class="' + (avar ? "bad" : "good") + '">' + U.toFixed(2) + ' В</b> — โหมด <b>' + mode + '</b>' +
        '<span>P<sub>Q</sub> = P<sub>СБ</sub> − P<sub>Н</sub>/η<sub>СН</sub> = <b>' + pex.toFixed(0) + ' Вт</b></span>' +
        '<span>' + gname + ' = <b>' + gam.toFixed(2) + '</b> · РП ตัวอื่นถูกตรึงที่ γ = 0 หรือ γ = 1</span>' +
        '<span>' + (avar
          ? 'แรงดันต่ำกว่า 25,5 В — АБ คายจนหมด ระบบต้องตัดโหลดหนักบางส่วนเพื่อรักษายาน (Л13 сл. 20 ข้อ 1)'
          : mode === "СН" ? 'กำลังเกินมาก АБ ชาร์จเต็มจึงถูกตัดออกขณะสว่าง — ตรงกับข้อได้เปรียบข้อ 3 ของ сл. 22'
          : mode === "ЗУ" ? 'กำลังเกินพอดี ЗУ นำส่วนเกินไปประจุ АБ ส่วน РУ ปิดสนิท (γ = 0)'
          : 'กำลังขาด РУ ดึงพลังงานจาก АБ มาเสริมบัสโหลด ส่วน ЗУ ปิดสนิท') + '</span>' +
        '<span>สไลด์ 28 มีหกภาพ = <b>สามโหมด × สองมุมมอง</b> (ซ้ายไฮไลต์เส้นทาง ขวาแสดงบล็อกที่ทำงาน) — ในทุกโหมดมี РП ทำงานเพียง 1–2 ตัว</span>' +
        '<span><b>ผู้เรียบเรียงสมมติ</b> ค่ากำลังสูงสุดของ РП (ЗУ 600 Вт, РУ 900 Вт, СН 600 Вт) และ η<sub>СН</sub> = 0,9 เพื่อผูกสมดุลกำลังเข้ากับสเกลแรงดัน — <b>สไลด์ให้เฉพาะตัวเลข 25,5 / 27,0 / 28,5 В</b></span>';
    }
  });
}

/* ================================================================
   6. eoRSH — บัสแยก (разделённые шины) เทียบกับบัสรวม
   Л14 сл. 22 — โครงสร้าง (а) параллельная, (б) последовательно-параллельная,
     (в) потоки энергии: W_ВЫХ СН = η_СН·W_ВХ СН · W_ВЫХ ЗУ = η_ЗУ·W_ВХ ЗУ · W_ВЫХ РУ = η_РУ·W_ВХ РУ
     W_ПИ = W_ВХ СН + W_ВХ ЗУ · W_П = W_ВЫХ СН + W_ВЫХ РУ    (สมการอ่านจากรูป — ผู้เรียบเรียง)
   Л14 сл. 17 — ข้อเสีย 4 ข้อของ ОШ · сл. 22 — ข้อได้เปรียบ 3 และ 5 ข้อ
   Л12 сл. 14 — ต้นไม้การจำแนก: ОШ แบบ нерегулируемые · РШ с централизованным регулятором
   Л13 сл. 12 — τ̄_т = τ_т/T_вит เป็นสัดส่วนพลังงานที่ต้องผ่าน АБ
================================================================ */
function eoRSH(host) {
  buildDemo(host, {
    label: "Лекция 14 · сл. 17, 22 · Лекция 12 сл. 14",
    title: "กดปุ่มสลับโครงสร้าง แล้วเทียบบัสรวมกับบัสแยกสองแบบ ทั้ง КПД รวม ช่วงแรงดันบนโหลด และจำนวนรอบของ АБ",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>เส้นทางหลัก</span>' +
            '<span><i style="background:var(--accent-2)"></i>เส้นทางผ่าน АБ</span>' +
            '<span><i style="background:var(--ok)"></i>ดีกว่า</span>' +
            '<span><i style="background:var(--crit)"></i>แย่กว่า</span>',
    controls: [
      { id: "tt", label: "τ̄<sub>т</sub> — สัดส่วนพลังงานที่ต้องผ่าน АБ", min: 0, max: 0.5, step: 0.01, value: 0.37, fmt: v => v.toFixed(2) },
      { id: "esn", label: "η<sub>СН</sub>", min: 0.8, max: 0.98, step: 0.01, value: 0.92, fmt: v => v.toFixed(2) },
      { id: "ezu", label: "η<sub>ЗУ</sub>", min: 0.8, max: 0.98, step: 0.01, value: 0.9, fmt: v => v.toFixed(2) },
      { id: "eru", label: "η<sub>РУ</sub>", min: 0.8, max: 0.98, step: 0.01, value: 0.9, fmt: v => v.toFixed(2) }
    ],
    buttons: [
      { id: "va", label: "(а) параллельная", act: st => { st.v = 0; } },
      { id: "vb", label: "(б) последовательно-параллельная", act: st => { st.v = 1; } }
    ],
    draw(ctx, w, h, s, readout) {
      if (s.v === undefined) s.v = 1;
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink = CV("--ink"),
            ink3 = CV("--ink-3"), line2 = CV("--line-2"), ok = CV("--ok"), crit = CV("--crit");
      const fs = eoFS(w);
      const x = s.tt;
      /* КПД รวมของเส้นทางพลังงาน (สมการ (в) ของ сл. 22) */
      const etaOSH = 1;
      const etaA = (1 - x) * 1 + x * s.ezu * s.eru;
      const etaB = (1 - x) * s.esn + x * s.ezu * s.eru;
      const etaR = s.v ? etaB : etaA;

      const topH = h * 0.56, botH = h - topH;
      /* --- ผังบน: โครงสร้างที่เลือก --- */
      const px = 8, py = 8, pw = w - 16, ph = topH - 16;
      const bw = Math.max(30, pw * 0.13), bh = Math.max(18, ph * 0.20);
      const yBus = py + ph * 0.24, yZR = py + ph * 0.56, yAB = py + ph * 0.84;
      const xPI = px, xSN = px + pw * 0.33, xZR = px + pw * 0.44, xP = px + pw * 0.84;

      eoTxt(ctx, s.v ? "СЭС РШ (б) последовательно-параллельная" : "СЭС РШ (а) параллельная",
        px, py, ink, fs, "left", "top", true);

      if (s.v) {
        eoPath(ctx, [[xPI + bw, yBus], [xSN, yBus]], acc, 2);
        eoBox(ctx, xSN, yBus - bh / 2, bw, bh, "СН", true, fs);
        eoPath(ctx, [[xSN + bw, yBus], [xP, yBus]], acc, 2);
      } else {
        eoPath(ctx, [[xPI + bw, yBus], [xP, yBus]], acc, 2);
        eoPath(ctx, [[xPI + bw + pw * 0.06, yBus], [xPI + bw + pw * 0.06, yZR]], acc, 1.4);
        eoBox(ctx, xPI + bw + pw * 0.06 - bw / 2, yZR, bw, bh, "СН", true, fs);
      }
      eoArrowEnd(ctx, [[xP - 20, yBus], [xP, yBus]], acc, 6);
      eoBox(ctx, xPI, yBus - bh / 2, bw, bh, "ПИ", true, fs);
      eoBox(ctx, xP, yBus - bh / 2, Math.min(bw, px + pw - xP), bh, "П", true, fs);

      /* กรอบ ЗРУ (ЗУ + РУ) */
      ctx.save();
      ctx.setLineDash([3, 3]); ctx.strokeStyle = line2; ctx.lineWidth = 1;
      ctx.strokeRect(xZR - 6, yZR - 8, bw * 2 + 22, bh + 16);
      ctx.restore();
      eoTxt(ctx, "ЗРУ", xZR - 6, yZR - 12, ink3, fs - 2, "left", "middle");
      eoBox(ctx, xZR, yZR, bw, bh, "ЗУ", true, fs);
      eoBox(ctx, xZR + bw + 10, yZR, bw, bh, "РУ", true, fs);
      eoBox(ctx, xZR + bw * 0.5 + 5, yAB, bw, bh, "АБ", true, fs);
      eoPath(ctx, [[xZR + bw / 2, yBus], [xZR + bw / 2, yZR]], acc2, 1.6);
      eoPath(ctx, [[xZR + bw / 2, yZR + bh], [xZR + bw / 2, yAB + bh / 2], [xZR + bw * 0.5 + 5, yAB + bh / 2]], acc2, 1.6);
      eoPath(ctx, [[xZR + bw * 1.5 + 5, yAB + bh / 2], [xZR + bw * 1.5 + 10, yAB + bh / 2], [xZR + bw * 1.5 + 10, yZR + bh]], acc2, 1.6);
      eoPath(ctx, [[xZR + bw * 1.5 + 10, yZR], [xZR + bw * 1.5 + 10, yBus]], acc2, 1.6);
      eoTxt(ctx, "заряд", xZR + bw / 2 + 3, (yZR + yAB) / 2, ink3, fs - 2, "left", "middle");
      eoTxt(ctx, "разряд", xZR + bw * 1.5 + 13, (yZR + yAB) / 2, ink3, fs - 2, "left", "middle");

      /* --- แผงล่าง: แถบเทียบสามโครงสร้าง --- */
      const by = topH, bx = 8, bwid = w - 16;
      const rows = [
        { n: "ОШ", e: etaOSH, du: 6.0, cyc: 12 },
        { n: "РШ (а)", e: etaA, du: 1.2, cyc: 1 },
        { n: "РШ (б)", e: etaB, du: 0.6, cyc: 1 }
      ];
      eoTxt(ctx, "КПД пути энергии · ΔU на нагрузке, В · циклов АБ за виток",
        bx, by + 2, ink3, fs - 1, "left", "top");
      const rh = (botH - 22) / 3;
      rows.forEach((r, i) => {
        const y0 = by + 18 + i * rh;
        const sel = (i === 0) ? false : (i - 1 === s.v);
        eoTxt(ctx, r.n, bx, y0 + rh * 0.45, sel ? ink : ink3, fs - 1, "left", "middle", sel);
        const x0 = bx + 48, aw = bwid * 0.36;
        ctx.save();
        ctx.fillStyle = i === 0 ? ink3 : acc;
        ctx.fillRect(x0, y0 + rh * 0.18, aw * r.e, Math.max(5, rh * 0.42));
        ctx.restore();
        eoTxt(ctx, (r.e * 100).toFixed(1) + " %", x0 + aw * r.e + 4, y0 + rh * 0.40,
          i === 0 ? ink3 : acc, fs - 2, "left", "middle");
        const x1 = x0 + aw + 56;
        eoTxt(ctx, "ΔU ≈ " + r.du.toFixed(1), x1, y0 + rh * 0.40, r.du > 2 ? crit : ok, fs - 2, "left", "middle");
        eoTxt(ctx, r.cyc + " цикл.", x1 + 62, y0 + rh * 0.40, r.cyc > 2 ? crit : ok, fs - 2, "left", "middle");
      });

      readout.innerHTML =
        'КПД ของโครงสร้างที่เลือก = <b class="' + (etaR > 0.93 ? "good" : "") + '">' + (etaR * 100).toFixed(1) + ' %</b>' +
        '<span>ОШ = <b>100 %</b> (ไม่มีตัวแปลงบนเส้นทาง) · РШ (а) = <b>' + (etaA * 100).toFixed(1) +
        ' %</b> · РШ (б) = <b>' + (etaB * 100).toFixed(1) + ' %</b></span>' +
        '<span>ราคาที่จ่ายของบัสแยกคือ КПД ที่คูณสะสม แต่ได้คืนเป็นแรงดันโหลดที่นิ่งและจำนวนรอบของ АБ ที่ลดเหลือเท่าจำนวนช่วงเงา (сл. 22 ข้อได้เปรียบข้อ 1)</span>' +
        '<span>(а) เสีย КПД เฉพาะกระแสที่ผ่าน АБ เพราะ СН ต่อขนาน · (б) พลังงานทั้งหมดผ่าน СН จึงเสียมากกว่า แต่แรงดันโหลดนิ่งที่สุด และเปิดทาง экстремальное регулирование (ข้อ 5)</span>' +
        '<span>ข้อได้เปรียบเฉพาะของ (а): เมื่อ СН เสียหายแบบใด ๆ ระบบไม่ล่ม แต่กลายเป็นระบบ ОШ (сл. 22 ข้อ 2) — โครงสร้าง (б) ไม่มีข้อนี้เพราะ СН อยู่บนเส้นทางหลัก</span>' +
        '<span><b>ผู้เรียบเรียง</b> — ค่า ΔU และจำนวนรอบต่อ виток เป็นค่าประกอบภาพจากข้อเสียข้อ 1 และ 4 ของ сл. 17 <b>สไลด์ไม่ให้ตัวเลข</b> ส่วนสมการ КПД อ่านจากผัง потоки энергии сл. 22 (в)</span>';
    }
  });
}

/* ================================================================
   7. eoSNzones — แถบเกณฑ์แรงดันสั่งงาน СН / ЗУ / РУ
   Л14 сл. 27 «Рисунок 2.3. Зоны широтно-импульсного управления потоками
   электроэнергии с помощью ЗУ, РУ, СН» — สามแถบ แต่ละแถบกำกับ «ขอบล่าง» ด้วย U₀ ของตัวเอง
   ตัวเลขจริงบนแท่งมาตร: 28,5 (СН) · 27,0 (ЗУ) · 25,5 (РУ) [В]
   เครื่องหมาย γ ที่ขอบแถบตามสไลด์: СН γ=0 บน / γ=1 ล่าง · ЗУ γ=1 บน / γ=0 ล่าง · РУ γ=0 บน / γ=1 ล่าง
   ค่าของ Конспект RU-TH ข้อ 33 (БАС 17МО26): 27 ± 0,81 В · ДПН 29,5 · ДМН1 24 · ДМН2 22 В
   — ไม่มีบนสไลด์ Л14 เลย และ ไม่เข้ากับสเกลนี้
================================================================ */
function eoSNzones(host) {
  buildDemo(host, {
    label: "Лекция 14 · сл. 27 (рис. 2.3) · เทียบกับ Конспект ข้อ 33",
    title: "เลื่อนแรงดันบัสแล้วดูว่า РП ตัวใดเข้าโหมด ШИМ และกดปุ่มเทียบกับค่าเกณฑ์ของ Конспект ที่ไม่เข้ากับสเกลนี้",
    ratio: 0.56,
    legend: '<span><i style="background:var(--accent-2)"></i>γ<sub>сн</sub></span>' +
            '<span><i style="background:var(--ok)"></i>γ<sub>зу</sub></span>' +
            '<span><i style="background:var(--crit)"></i>γ<sub>ру</sub></span>' +
            '<span><i style="background:var(--ink-3)"></i>เกณฑ์ของ Конспект ข้อ 33</span>',
    controls: [
      { id: "u", label: "U — แรงดันบนบัส, В", min: 21, max: 31, step: 0.05, value: 27.4, fmt: v => v.toFixed(2) }
    ],
    buttons: [
      { id: "kon", label: "пороги Конспекта п. 33", toggle: true, value: false }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink = CV("--ink"),
            ink3 = CV("--ink-3"), ok = CV("--ok"), crit = CV("--crit");
      const fs = eoFS(w);
      const U0RU = 25.5, U0ZU = 27.0, U0SN = 28.5;
      const xa = s.kon ? 21 : 24.5, xb = s.kon ? 31 : 30.5;

      const gru = u => u <= U0RU ? 1 : u >= U0ZU ? 0 : (U0ZU - u) / (U0ZU - U0RU);
      const gzu = u => u <= U0ZU ? 0 : u >= U0SN ? 1 : (u - U0ZU) / (U0SN - U0ZU);
      const gsn = u => u <= U0SN ? 0 : Math.max(0, 1 - (u - U0SN) / 1.5);

      const p = new Plot(ctx, 42, 18, w - 56, h - 52, xa, xb, 0, 1.05);
      /* แถบโซนเป็นพื้นหลัง */
      ctx.save();
      ctx.globalAlpha = 0.22;
      ctx.fillStyle = crit; ctx.fillRect(p.X(U0RU), p.y, p.X(U0ZU) - p.X(U0RU), p.h);
      ctx.fillStyle = ok; ctx.fillRect(p.X(U0ZU), p.y, p.X(U0SN) - p.X(U0ZU), p.h);
      ctx.fillStyle = acc2; ctx.fillRect(p.X(U0SN), p.y, p.X(xb) - p.X(U0SN), p.h);
      ctx.restore();
      p.frame(ticks(xa, xb, 5), eoTicksNice(0, 1, 4), "U, В","γ");

      const mk = f => { const o = []; for (let u = xa; u <= xb; u += 0.02) o.push([u, f(u)]); return o; };
      p.clip(() => {
        p.line(mk(gru), crit, 2.2);
        p.line(mk(gzu), ok, 2.2);
        p.line(mk(gsn), acc2, 2.2);
        [U0RU, U0ZU, U0SN].forEach(v => p.line([[v, 0], [v, 1.05]], ink3, 1, [3, 3]));
        p.line([[s.u, 0], [s.u, 1.05]], acc, 1.8);
        if (s.kon) {
          [[29.5, "ДПН"], [24, "ДМН1"], [22, "ДМН2"]].forEach(m => {
            if (m[0] >= xa && m[0] <= xb) p.line([[m[0], 0], [m[0], 1.05]], ink3, 1.6, [1, 3]);
          });
          ctx.save();
          ctx.globalAlpha = 0.30; ctx.fillStyle = ink3;
          ctx.fillRect(p.X(27 - 0.81), p.y + p.h * 0.86, p.X(27 + 0.81) - p.X(27 - 0.81), p.h * 0.10);
          ctx.restore();
        }
      });
      /* วางในกรอบเหนือแกน x — เดิมทับป้าย tick «27» ที่เอนจินวาดใต้กรอบ */
      [[U0RU, "25,5"], [U0ZU, "27,0"], [U0SN, "28,5"]].forEach((v, i) => {
        eoTxt(ctx, v[1], p.X(v[0]), p.y + p.h - 5 - (i % 2) * (fs + 1), ink3, fs - 2, "center", "bottom");
      });
      eoTxt(ctx, "зона РУ", (p.X(U0RU) + p.X(U0ZU)) / 2, p.y + 10, crit, fs - 1, "center", "middle", true);
      eoTxt(ctx, "зона ЗУ", (p.X(U0ZU) + p.X(U0SN)) / 2, p.y + 10, ok, fs - 1, "center", "middle", true);
      eoTxt(ctx, "зона СН", Math.min(p.X(U0SN) + 32, p.x + p.w - 24), p.y + 10, acc2, fs - 1, "center", "middle", true);
      if (s.kon) {
        [[29.5, "ДПН 29,5"], [24, "ДМН1 24"], [22, "ДМН2 22"]].forEach((m, i) => {
          if (m[0] >= xa && m[0] <= xb)
            eoTxt(ctx, m[1], p.X(m[0]) + 3, p.y + 26 + i * 12, ink3, fs - 2, "left", "middle");
        });
        eoTxt(ctx, "27 ± 0,81", p.X(27), p.y + p.h * 0.80, ink3, fs - 2, "center", "middle");
      }

      const act = s.u > U0SN ? "СН" : s.u > U0ZU ? "ЗУ" : s.u > U0RU ? "РУ" : "—";
      const g = s.u > U0SN ? gsn(s.u) : s.u > U0ZU ? gzu(s.u) : s.u > U0RU ? gru(s.u) : 1;
      readout.innerHTML =
        'РП ที่อยู่ในโหมด ШИМ: <b class="' + (act === "—" ? "bad" : "good") + '">' + act + '</b> · γ = <b>' + g.toFixed(2) + '</b>' +
        '<span>γ<sub>ру</sub> = ' + gru(s.u).toFixed(2) + ' · γ<sub>зу</sub> = ' + gzu(s.u).toFixed(2) +
        ' · γ<sub>сн</sub> = ' + gsn(s.u).toFixed(2) + '</span>' +
        '<span>' + (act === "—"
          ? 'ต่ำกว่า 25,5 В — อยู่นอกช่วงที่ยอมรับได้ ระบบเข้าสถานะฉุกเฉิน'
          : 'ในแต่ละโซนมี РП เพียงตัวเดียวที่ 0 &lt; γ &lt; 1 ตัวอื่นถูกตรึงที่ γ = 0 หรือ γ = 1 จึงไม่เกิด «борьба регуляторов»') + '</span>' +
        '<span><b>หมายเหตุต้นฉบับ</b> — ค่าของ Конспект ข้อ 33 (БАС 17МО26): <b>27 ± 0,81 В · ДПН 29,5 · ДМН1 24 · ДМН2 22 В</b> ' +
        '<b>ไม่เข้ากับสเกลนี้</b>: ДПН 29,5 В อยู่สูงกว่าขอบบน 28,5 В และ ДМН1/ДМН2 (24 / 22 В) อยู่ต่ำกว่าขอบล่าง 25,5 В — เป็นคนละระบบ คนละรุ่น ' +
        'ตัวเลขทั้งชุดนี้<b>ไม่มีอยู่ในสไลด์ Л12–Л14 ชุดใดเลย</b> ต้องมาจากตำราหรือ ЛР — <b>ต้องถามอาจารย์</b></span>' +
        '<span><b>หมายเหตุต้นฉบับ</b> — เครื่องหมาย γ ที่ขอบโซนของ рис. 2.3 กลับทิศกันระหว่างโซน (СН และ РУ กำกับ γ=0 บน / γ=1 ล่าง ส่วน ЗУ กำกับตรงข้าม) และสไลด์ไม่อธิบายวิธีอ่านเลย · กราฟนี้วาดตามที่สไลด์กำกับทุกประการ</span>';
    }
  });
}

/* ================================================================
   8. eoSBtemp — ВАХ ของ СБ ตามอุณหภูมิและมุมตกกระทบ
   Л12 сл. 26 «Изменение формы ВАХ СБ» — สามกราฟ: Освещённость («0°» และ «60°»),
     Температура («−50 °C» และ «0 °C»), Затенение
   Л13 сл. 13 — ตัวเลขจริงของกราฟ U,I (%) กับ T_ОУО:
     U ≈125 % ที่ −60 °C → ≈75 % ที่ +60 °C · I ≈85 % ที่ −60 °C → สูงสุด ≈100 % ที่ 0…+20 °C
     Реальные равновесные температуры: ОУО +30…+60 °C · ТУО −60…−100 °C
     ช่วงออกจากเงา ≤15 мин กำลังสูงกว่าค่าคงตัวหลายเท่า
   Л12 сл. 24 — удельная мощность Si: 200 Вт/м² ที่ 25 °C · 165–170 Вт/м² ที่ 60 °C
   Л12 сл. 26 / Л13 сл. 14 — P_M ∝ cos α ⇒ I_кз ∝ cos α
================================================================ */
function eoSBtemp(host) {
  buildDemo(host, {
    label: "Лекция 12 · сл. 26 · ตัวเลขจาก Лекция 13 сл. 13 และ Лекция 12 сл. 24",
    title: "เลื่อนอุณหภูมิแผงและมุมตกกระทบ แล้วดู ВАХ ขยับ — เส้นอ้างอิง −50 °C และ 0 °C คือคู่เส้นที่สไลด์ 26 วาดไว้",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>ВАХ ที่ T และ α ปัจจุบัน</span>' +
            '<span><i style="background:var(--accent-2)"></i>P(U)</span>' +
            '<span><i style="background:var(--ink-3)"></i>เส้นอ้างอิง −50 °C และ 0 °C</span>',
    controls: [
      { id: "T", label: "T — อุณหภูมิผิวแผง, °C", min: -100, max: 60, step: 1, value: -50 },
      { id: "al", label: "α — มุมตกกระทบของแสง, град", min: 0, max: 60, step: 1, value: 0 }
    ],
    buttons: [
      { id: "ref", label: "เส้นอ้างอิง −50 °C / 0 °C", toggle: true, value: true }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink2 = CV("--ink-2"), ink3 = CV("--ink-3");
      const fs = eoFS(w);
      const rad = Math.PI / 180, VT = 4.5;
      const kU = T => 1.25 - 0.0041667 * (T + 60);
      const kI = T => 1 - 3.061e-5 * Math.pow(T - 10, 2);

      function vah(T, al) {
        const ca = Math.cos(al * rad);
        const Uoc = 100 * kU(T) * (1 + 0.06 * Math.log(Math.max(0.2, ca)));
        const Isc = 100 * kI(T) * ca;
        const den = 1 - Math.exp(-Uoc / VT);
        const I = U => Isc * (1 - Math.exp((U - Uoc) / VT)) / den;
        let Pm = 0, Um = 0, Im = 0;
        for (let U = 0; U <= Uoc; U += Uoc / 400) {
          const i = I(U), pp = U * i;
          if (pp > Pm) { Pm = pp; Um = U; Im = i; }
        }
        return { Uoc: Uoc, Isc: Isc, I: I, Pm: Pm, Um: Um, Im: Im };
      }

      const cur = vah(s.T, s.al);
      const ref25 = vah(25, 0);
      const K = 200 / ref25.Pm;
      const ref60 = vah(60, 0);

      const p = new Plot(ctx, 44, 18, w - 58, h - 52, 0, 135, 0, 115);
      p.frame(ticks(0, 135, 5), eoTicksNice(0, 115, 4), "U, % ของค่าที่ 0 °C","I, %");

      const mk = v => { const o = []; for (let U = 0; U <= v.Uoc; U += v.Uoc / 160) o.push([U, v.I(U)]); return o; };
      p.clip(() => {
        if (s.ref) {
          p.line(mk(vah(-50, s.al)), ink3, 1.2, [4, 3]);
          p.line(mk(vah(0, s.al)), ink3, 1.2, [4, 3]);
        }
        p.line(mk(cur), acc, 2.4);
        const pw = [];
        for (let U = 0; U <= cur.Uoc; U += cur.Uoc / 160) pw.push([U, U * cur.I(U) / 115]);
        p.line(pw, acc2, 1.6, [3, 3]);
        p.dots([[cur.Um, cur.Im]], acc2, 4);
      });
      if (s.ref) {
        const a = vah(-50, s.al), b = vah(0, s.al);
        eoTxt(ctx, "−50 °C", p.X(a.Uoc) - 4, p.Y(8), ink3, fs - 2, "right", "middle");
        eoTxt(ctx, "0 °C", p.X(b.Uoc) - 4, p.Y(20), ink3, fs - 2, "right", "middle");
      }
      {
        ctx.save(); ctx.font = eoFont(fs - 2);
        const lw2 = ctx.measureText("точка max P").width; ctx.restore();
        const toRight = p.X(cur.Um) + 5 + lw2 < w - 4;
        eoTxt(ctx, "точка max P", p.X(cur.Um) + (toRight ? 5 : -5), p.Y(cur.Im) + 2, acc2, fs - 2,
          toRight ? "left" : "right", "middle");
      }

      const pWt = cur.Pm * K;
      const p60 = ref60.Pm * K;
      const hot = s.T >= 30;
      readout.innerHTML =
        'P<sub>max</sub> = <b class="' + (pWt > 200 ? "good" : hot ? "bad" : "") + '">' + pWt.toFixed(0) + ' Вт/м²</b> ' +
        '(' + (cur.Pm / ref25.Pm * 100).toFixed(0) + ' % ของค่าที่ 25 °C, α = 0)' +
        '<span>U<sub>хх</sub> = <b>' + cur.Uoc.toFixed(0) + ' %</b> · I<sub>кз</sub> = <b>' + cur.Isc.toFixed(0) + ' %</b> · ' +
        'FF = <b>' + (cur.Pm / (cur.Uoc * cur.Isc)).toFixed(3) + '</b></span>' +
        '<span>cos α = <b>' + Math.cos(s.al * rad).toFixed(3) + '</b> — มุมตกกระทบลด I<sub>кз</sub> ตามตรง และลด U<sub>хх</sub> เล็กน้อยตามลอการิทึม (สไลด์ 26 กราฟ 1)</span>' +
        '<span>' + (s.T <= -50
          ? 'อุณหภูมิ ТУО จริงคือ −60…−100 °C — เมื่อแผงเย็นจัดโผล่พ้นเงา U สูงถึง 125 % กำลังจึงสูงกว่าค่าคงตัวหลายเท่าเป็นเวลาไม่เกิน 15 мин (сл. 13)'
          : hot ? 'อุณหภูมิ ОУО จริงคือ +30…+60 °C — นี่คือย่านที่แผงทำงานเกือบตลอดช่วงสว่าง'
          : 'ระหว่าง −50 °C ถึง 0 °C คือคู่เส้นที่สไลด์ 26 วาดเทียบกันพอดี') + '</span>' +
        '<span><b>หมายเหตุต้นฉบับ</b> — สองแหล่งของภาควิชาไม่ตรงกัน: กราฟ Л13 сл. 13 (U 125 %→75 % ระหว่าง −60…+60 °C) ให้ที่ 60 °C ≈ <b>' +
        p60.toFixed(0) + ' Вт/м²</b> ขณะที่ตาราง Л12 сл. 24 ระบุ <b>165–170 Вт/м²</b> — <b>ต้องถามอาจารย์</b></span>' +
        '<span><b>ผู้เรียบเรียง</b> — รูปทรงของ ВАХ ใช้แบบจำลองไดโอดมาตรฐาน โดยตรึงปลายทั้งสองข้าง (U<sub>хх</sub>, I<sub>кз</sub>) ไว้กับตัวเลขจริงของ сл. 13 · สไลด์ 26 ให้เฉพาะรูปที่ความละเอียดต่ำ ไม่มีสเกลตัวเลข</span>';
    }
  });
}

/* ================================================================
   9. eoLogicOSH — ตรรกะการทำงานของ СЭП: датчики → команды → транспаранты
   notes/PZ-LOGIKA-OSH.md — Рис. 3 (окно «Консультация»: датчики 12 · информация 12 · команды 9)
   และ Рис. 4 (Логическая схема СЭП: БКИП รับ ВНБ, АНБ, ННБ1, ННБ2 → РК-141 / РК-43;
   ЗБС รับ ДЗН, ДМН → РК-61 / РК-149 → ПРЗТ; นอกนั้น САЧ-15, САЧ-80, РВ)
   ลำดับการตัดสินใจตาม Ситуации A–F ของโน้ต
   ⚠ เอกสารไม่ให้ค่าธรณีแรงดันของเซนเซอร์ใดเลย — ค่าที่ใช้ในแบบจำลองนี้ผู้เรียบเรียงสมมติ
================================================================ */
function eoLogicOSH(host) {
  buildDemo(host, {
    label: "ПЗ «Логика работы СЭП с ОШ» · рис. 3 และ рис. 4",
    title: "เลื่อนแรงดันของ ББ และตัวนับแอมแปร์-ชั่วโมง แล้วกดปุ่มคำสั่ง ดูว่าไฟสถานะดวงไหนติดและคำสั่งที่ถูกคืออะไร",
    ratio: 0.56,
    legend: '<span><i style="background:var(--crit)"></i>датчик ทำงาน</span>' +
            '<span><i style="background:var(--accent)"></i>транспарант สว่าง</span>' +
            '<span><i style="background:var(--ok)"></i>คำสั่งถูกต้องแล้ว</span>',
    controls: [
      { id: "u", label: "แรงดันของ ББ, В (ค่าธรณี — ผู้เรียบเรียงสมมติ)", min: 22, max: 34, step: 0.1, value: 28.5, fmt: v => v.toFixed(1) },
      { id: "q", label: "САЧ — ประจุที่คายออกไปแล้ว, А·ч", min: 0, max: 100, step: 1, value: 5 }
    ],
    buttons: [
      { id: "sb", label: "СБ на ББ", toggle: true, value: true },
      { id: "ld", label: "нагрузка полная", toggle: true, value: true },
      { id: "pr", label: "ПРЗТ", toggle: true, value: false },
      { id: "rb", label: "переход на РБ", toggle: true, value: false },
      { id: "rz", label: "резерв БКИП", toggle: true, value: false },
      { id: "fl", label: "отказ БКИП", toggle: true, value: false }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), ink = CV("--ink"), ink2 = CV("--ink-2"), ink3 = CV("--ink-3"),
            line2 = CV("--line-2"), ok = CV("--ok"), crit = CV("--crit"), panel2 = CV("--panel-2");
      const fs = Math.max(7, Math.min(10, Math.round(w / 46)));
      const U = s.u, Q = s.q;
      const D = {
        "ВНБ": U >= 32.0, "ННБ1": U <= 27.0, "ННБ2": U <= 25.5, "АНБ": U <= 24.0,
        "ДЗН": U >= 30.0, "ДМН": U <= 25.0, "САЧ-15": Q >= 15, "САЧ-80": Q >= 80
      };
      const T = [
        ["СБ от ББ откл", !s.sb], ["СБ к ББ подкл", s.sb],
        ["БСС к ОС подкл.", s.pr], ["ПРЗТ подкл.", s.pr],
        ["Работа СЭУ-СБ не норма", D["АНБ"] && !s.rb],
        ["Работа БСС не норма", D["ДМН"] && s.pr],
        ["Откл. части нагрузки", !s.ld],
        ["t < 350 мс", false],
        ["БКИП не норма", s.fl && !s.rz],
        ["Работа на СЭУ-СБ", !s.rb], ["Работа на РБ", s.rb],
        ["t > 20 мин.", false]
      ];
      let need, sit;
      if (s.fl && !s.rz) { need = "«Резерв БКИП» → ВКЛ"; sit = "E"; }
      else if (D["АНБ"] && !s.rb) { need = "«Переход на РБ» → ВКЛ"; sit = "B"; }
      else if (D["ВНБ"] && s.sb) { need = "«СБ на ББ» → ОТКЛ"; sit = "C"; }
      else if (D["ННБ1"] && s.ld) { need = "«Часть нагр.» → ОТКЛ"; sit = "A"; }
      else if (D["ДЗН"] && !s.pr) { need = "«ПРЗТ» → ВКЛ"; sit = "D"; }
      else if (D["ДМН"] && s.pr) { need = "«ПРЗТ» → ОТКЛ"; sit = "D"; }
      else if (D["САЧ-80"]) { need = "«Кор. мин. САЧ»"; sit = "F"; }
      else if (s.rb && D["ВНБ"]) { need = "«Возврат на СЭУ-СБ» → ВКЛ"; sit = "B"; }
      else if (!D["ВНБ"] && !s.sb && !s.rb) { need = "«СБ на ББ» → ВКЛ"; sit = "C"; }
      else { need = "«Норма» — ไม่ต้องสั่งการใด ๆ"; sit = "—"; }

      function lamp(x, y, bw, bh, txt, lit, col) {
        ctx.save();
        eoRRPath(ctx, x, y, bw, bh, 3);
        ctx.fillStyle = lit ? CV("--wash-2") : panel2; ctx.fill();
        ctx.strokeStyle = lit ? col : line2; ctx.lineWidth = lit ? 1.6 : 1; ctx.stroke();
        ctx.fillStyle = lit ? col : line2;
        ctx.beginPath(); ctx.arc(x + 7, y + bh / 2, 3, 0, 7); ctx.fill();
        ctx.restore();
        /* ย่อ/ตัดข้อความให้อยู่ในกล่องเสมอ (สำคัญที่ 390 px) */
        ctx.save();
        var tf = fs, avail = bw - 18;
        ctx.font = eoFont(tf, lit);
        while (tf > 6.6 && ctx.measureText(txt).width > avail) { tf -= 0.4; ctx.font = eoFont(tf, lit); }
        var ts = txt;
        while (ts.length > 1 && ctx.measureText(ts + "…").width > avail) ts = ts.slice(0, -1);
        if (ts !== txt) ts += "…";
        ctx.restore();
        eoTxt(ctx, ts, x + 14, y + bh / 2, lit ? ink : ink3, tf, "left", "middle", lit);
      }

      const cw = (w - 20) / 3, ch = h - 12;
      const cx1 = 6, cx2 = 6 + cw + 4, cx3 = 6 + 2 * (cw + 4);
      eoTxt(ctx, "ДАТЧИКИ", cx1, 8, ink2, fs, "left", "top", true);
      eoTxt(ctx, "ЛОГИКА (рис. 4)", cx2, 8, ink2, fs, "left", "top", true);
      eoTxt(ctx, "ИНФОРМАЦИЯ", cx3, 8, ink2, fs, "left", "top", true);

      const keys = Object.keys(D);
      /* ความสูงแถวคิดจาก h จริง เพื่อให้เนื้อหาเต็มผ้าใบ ไม่เหลือพื้นที่ว่างครึ่งภาพ */
      const lh = Math.max(11, Math.min(28, (ch - 26) / 12 - 3));
      keys.forEach((k, i) => lamp(cx1, 22 + i * (lh + 3), cw - 4, lh, k, D[k], crit));
      {
        const clipW = (t2, mw) => {
          ctx.save(); ctx.font = eoFont(fs - 1);
          let r = t2;
          while (r.length > 1 && ctx.measureText(r + "…").width > mw) r = r.slice(0, -1);
          ctx.restore();
          return r === t2 ? t2 : r + "…";
        };
        eoTxt(ctx, clipW("Мх Сл.А · К.О. · t > 350 мс · 15 мин", cw - 6), cx1, 22 + 8 * (lh + 3) + 4, ink3, fs - 1, "left", "top");
        eoTxt(ctx, clipW("(4 датчика ไม่ได้จำลอง)", cw - 6), cx1, 22 + 8 * (lh + 3) + 4 + fs + 2, ink3, fs - 1, "left", "top");
      }

      /* คอลัมน์กลาง — БКИП / ЗБС และรีเลย์ РК */
      const by0 = 22;
      ctx.save();
      ctx.setLineDash([3, 3]); ctx.strokeStyle = line2; ctx.lineWidth = 1;
      ctx.strokeRect(cx2, by0, cw - 4, lh * 4 + 14);
      ctx.strokeRect(cx2, by0 + lh * 4 + 22, cw - 4, lh * 3 + 10);
      ctx.restore();
      eoTxt(ctx, "БКИП " + (s.rz ? "рез." : "осн."), cx2 + 4, by0 + 8, s.fl && !s.rz ? crit : ink2, fs, "left", "middle", true);
      lamp(cx2 + 4, by0 + 16, cw - 12, lh, "РК-141 · СЭУ-СБ", !s.rb, acc);
      lamp(cx2 + 4, by0 + 16 + lh + 3, cw - 12, lh, "РК-43 · РБ", s.rb, acc);
      lamp(cx2 + 4, by0 + 16 + 2 * (lh + 3), cw - 12, lh, "нагрузка", s.ld, acc);
      eoTxt(ctx, "ЗБС", cx2 + 4, by0 + lh * 4 + 30, ink2, fs, "left", "middle", true);
      lamp(cx2 + 4, by0 + lh * 4 + 38, cw - 12, lh, "РК-149 · ПРЗТ вкл", D["ДЗН"] && s.pr, acc);
      lamp(cx2 + 4, by0 + lh * 4 + 38 + lh + 3, cw - 12, lh, "РК-61 · ПРЗТ откл", D["ДМН"] && !s.pr, acc);
      const rvY = by0 + lh * 4 + 22 + lh * 3 + 10 + 14;   /* ใต้กรอบ ЗБС พอดี */
      eoTxt(ctx, "РВ: t > 20 мс · t < 350 мс", cx2 + 4, rvY, ink3, fs - 1, "left", "middle");
      eoTxt(ctx, "САЧ-15 / САЧ-80 → контроль", cx2 + 4, rvY + fs + 4, ink3, fs - 1, "left", "middle");

      T.forEach((row, i) => lamp(cx3, 22 + i * (lh + 3), cw - 4, lh, row[0], row[1], acc));

      const okNow = need.indexOf("Норма") >= 0;
      readout.innerHTML =
        'คำสั่งที่ถูกต้องตอนนี้: <b class="' + (okNow ? "good" : "bad") + '">' + need + '</b>' +
        (sit === "—" ? "" : ' <span>(ситуация ' + sit + ')</span>') +
        '<span>U<sub>ББ</sub> = <b>' + U.toFixed(1) + ' В</b> · САЧ = <b>' + Q.toFixed(0) + ' А·ч</b> · датчиков сработало: <b>' +
        Object.keys(D).filter(k => D[k]).length + '</b> · транспарантов горит: <b>' + T.filter(r => r[1]).length + '</b></span>' +
        '<span>เกณฑ์ประเมินของโหมด «Зачёт»: ผิดได้ <b>3 ครั้ง</b> · ครั้งที่ <b>4</b> ระบบล็อกและขึ้น «НЕ ЗАЧЁТ» · เอกสารไม่ระบุค่าตัวจับเวลา</span>' +
        '<span>ลำดับตรรกะหลัก: ННБ1 → ЭЗС 15″ → БКИП → сброс нагрузки · АНБ → ЭЗС 15″ → БКИП → РК-43 (РБ вкл) + РК-141 (СЭУ-СБ откл) · ВНБ → БКИП → РК-141 → СБ от ББ откл · ДЗН → РК-149 → ПРЗТ вкл · ДМН → ЭЗС 5..10″ → РК-61 → ПРЗТ откл</span>' +
        '<span><b>ผู้เรียบเรียงสมมติ</b> — ค่าธรณี ВНБ 32,0 · ННБ1 27,0 · ННБ2 25,5 · АНБ 24,0 · ДЗН 30,0 · ДМН 25,0 В และธรณี САЧ 15 / 80 А·ч (สองค่าหลังมาจากชื่อเซนเซอร์จริง) · ' +
        '<b>เอกสารไม่มีตารางถอดรหัสตัวย่อและไม่ให้ค่าธรณีใดเลย ต้องยืนยันกับอาจารย์</b></span>';
    }
  });
}

/* ================================================================
   10. eoRNbalance — วัฏจักรพลังงานของ РН และการเลือก АБ
   Л15 сл. 21 — табл. 2.1 «Режимы разряда АБ СЭС РН "Протон"» (ตัวเลขจริงทั้งตาราง)
     11Л045   режим I : 30 А/115 с + 60 А/10 с      U 32,5–28,0 В
     11Л045   режим II: 30 А/600 с одноступенчатый  U 32,5–27,0 В
     11Л032К  режим I : 120 А/125 с + 320 А/30 с + 150 А/180 с  U 32,5–27,0 В
     11Л032К  режим II: 120 А/600 с                U 32,0–26,0 В
     11Л044   режим I : 120 А/600 с одноступенчатый U 32,0–27,0 В
   Q = Σ I_k·t_k / 3600  [А·ч] — ประจุที่ต้องคายออกในภารกิจหนึ่งครั้ง (ผู้เรียบเรียงคำนวณ)
   Л15 сл. 23 — เวลาทำงานจริง: боковой блок «Союз» 3 мин · центральный 8 мин · РБ «Протон» ≈6 ч
================================================================ */
function eoRNbalance(host) {
  buildDemo(host, {
    label: "Лекция 15 · сл. 21 (табл. 2.1 «Протон») · ผู้เรียบเรียงคำนวณ Q",
    title: "เลือกโหมดคายประจุจากตารางจริง แล้วดูขั้นกระแส แรงดันที่ตก และความจุที่แบตต้องมีจึงจะพอ",
    ratio: 0.56,
    legend: '<span><i style="background:var(--accent)"></i>I(t) ตามตาราง 2.1</span>' +
            '<span><i style="background:var(--accent-2)"></i>U(t) จากช่วงแรงดันในตาราง</span>' +
            '<span><i style="background:var(--ink-3)"></i>Q สะสม</span>',
    controls: [
      { id: "m", label: "режим разряда", min: 1, max: 5, step: 1, value: 3,
        fmt: v => ["", "11Л045 · I", "11Л045 · II", "11Л032К ×2 · I", "11Л032К ×2 · II", "11Л044 ×2 · I"][Math.round(v)] },
      { id: "cap", label: "ёмкость АБ ที่ติดตั้ง, А·ч (ค่าสมมติ — ตารางไม่ให้)", min: 5, max: 60, step: 1, value: 25 },
      { id: "gr", label: "ГР — ความลึกการคายที่ยอมให้, %", min: 20, max: 100, step: 5, value: 60 }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink2 = CV("--ink-2"), ink3 = CV("--ink-3");
      const fs = eoFS(w);
      const MODES = [
        { n: "11Л045 · режим I", st: [[30, 115], [60, 10]], u: [32.5, 28.0], b: "1 блок × 24 Ni-Cd · 1-я ступень" },
        { n: "11Л045 · режим II", st: [[30, 600]], u: [32.5, 27.0], b: "одноступенчатый разряд" },
        { n: "11Л032К ×2 · режим I", st: [[120, 125], [320, 30], [150, 180]], u: [32.5, 27.0], b: "2 блока по 25 Ni-Cd · 2-я ступень" },
        { n: "11Л032К ×2 · режим II", st: [[120, 600]], u: [32.0, 26.0], b: "одноступенчатый разряд" },
        { n: "11Л044 ×2 · режим I", st: [[120, 600]], u: [32.0, 27.0], b: "2 блока по 25 Ni-Cd · 3-я ступень" }
      ];
      const M = MODES[Math.max(0, Math.min(4, Math.round(s.m) - 1))];
      let tot = 0, Qas = 0, Imax = 0;
      M.st.forEach(x => { tot += x[1]; Qas += x[0] * x[1]; Imax = Math.max(Imax, x[0]); });
      const Q = Qas / 3600;
      const need = Q / (s.gr / 100);
      const Isr = Qas / tot;

      const ymax = Imax * 1.25;
      const p = new Plot(ctx, 44, 18, w - 88, h - 52, 0, tot, 0, ymax);
      p.frame(ticks(0, tot, 5), eoTicksNice(0, ymax, 4), "t, с","I, А");

      const ipts = [], upts = [], qpts = [];
      let t0 = 0, qq = 0;
      M.st.forEach(x => {
        ipts.push([t0, x[0]]); ipts.push([t0 + x[1], x[0]]);
        t0 += x[1];
      });
      for (let t = 0; t <= tot; t += tot / 200) {
        const u = M.u[0] + (M.u[1] - M.u[0]) * t / tot;
        upts.push([t, (u - 24) / (34 - 24) * ymax]);
      }
      t0 = 0; qq = 0;
      qpts.push([0, 0]);
      M.st.forEach(x => { qq += x[0] * x[1]; t0 += x[1]; qpts.push([t0, qq / Qas * ymax * 0.95]); });

      p.clip(() => {
        p.line(qpts, ink3, 1.4, [4, 3]);
        p.line(upts, acc2, 1.6, [6, 4]);
        p.line(ipts, acc, 2.4);
      });
      [28, 30, 32].forEach(v => {
        const yy = p.Y((v - 24) / (34 - 24) * ymax);
        eoTxt(ctx, v.toFixed(0) + " В", p.x + p.w + 3, yy, acc2, fs - 2, "left", "middle");
      });
      eoTxt(ctx, M.n, p.x + 4, p.y + 9, ink2, fs, "left", "middle", true);
      M.st.forEach((x, i) => {
        let a = 0;
        for (let j = 0; j < i; j++) a += M.st[j][1];
        if (p.X(a + x[1]) - p.X(a) > 30)
          eoTxt(ctx, x[0] + " А", (p.X(a) + p.X(a + x[1])) / 2, p.Y(x[0]) - 9, acc, fs - 1, "center", "middle", true);
      });

      readout.innerHTML =
        'Q<sub>разр</sub> = <b>' + Q.toFixed(2) + ' А·ч</b> · ต้องมีความจุ ≥ <b class="' +
        (s.cap >= need ? "good" : "bad") + '">' + need.toFixed(1) + ' А·ч</b>' +
        '<span>Σ I<sub>k</sub>·t<sub>k</sub> = ' + M.st.map(x => x[0] + "·" + x[1]).join(" + ") +
        ' = <b>' + Qas.toFixed(0) + ' А·с</b> → /3600 = <b>' + Q.toFixed(2) + ' А·ч</b></span>' +
        '<span>t<sub>общ</sub> = <b>' + tot + ' с</b> · I<sub>ср</sub> = <b>' + Isr.toFixed(0) +
        ' А</b> · I<sub>max</sub> = <b>' + Imax + ' А</b> · U: <b>' + M.u[0].toFixed(1) + ' → ' + M.u[1].toFixed(1) + ' В</b></span>' +
        '<span>' + M.b + ' · ' + (s.cap >= need
          ? 'ความจุที่ติดตั้งพอสำหรับโหมดนี้'
          : 'ความจุที่ติดตั้งไม่พอ — ต้องเพิ่มความจุหรือยอมให้คายลึกกว่านี้') + '</span>' +
        '<span>กระแสสูงสุดของทั้งบรรยายคือ <b>320 А</b> (11Л032К ขั้นที่สองของ режим I) — เป็นพีคสั้น 30 с ตอนแยกขั้น จึงกำหนดกระแสสูงสุดของสายและหน้าสัมผัส ไม่ใช่กำหนดความจุ</span>' +
        '<span><b>ผู้เรียบเรียงคำนวณ</b> — สูตร Q = Σ I<sub>k</sub>·t<sub>k</sub>/3600 ไม่มีบนสไลด์ ตารางให้เฉพาะกระแส เวลา และช่วงแรงดัน · <b>ตารางไม่ให้ความจุพิกัดของแบตแต่ละรุ่นเลย</b> ค่าในสไลเดอร์จึงเป็นค่าสมมติ</span>';
    }
  });
}

/* ================================================================
   11. eoRNstruct — โครงสร้าง СЭС РН «Союз»: สามแหล่งที่ขัดกันเอง
   Л15 сл. 20 (ข้อความ): «На РН "Союз-2" устанавливается 12 бортовых батарей типа 22СЦК-25 …
      На каждый блок РН устанавливается по две бортовые батареи» (6 บล็อก × 2 = 12)
   Л15 сл. 14 (ผังโครงสร้าง): боковые Б, В, Г, Д — 1 × 22СЦК-25 ต่อบล็อก, บัส 32,5–28 В ·
      центральный А — АБ-1/АБ-2 21СЦК-50Б, บัส 32–27,3 В · блок И — АБ-1/АБ-2 21СЦК-25Б, บัส 32,5–28 В
   Л15 сл. 22 (ตาราง «Типы бортовых источников …»): «Союз»/«Союз-2» → 21 СЦК-50 และ 22 СЦК-25 (สองรุ่น ไม่ให้จำนวน)
   ⇒ สามแหล่งขัดกันทั้งจำนวนก้อนและจำนวนรุ่น
================================================================ */
function eoRNstruct(host) {
  buildDemo(host, {
    label: "Лекция 15 · сл. 14 / 20 / 22 — источники противоречат друг другу",
    title: "กดปุ่มสลับสามแหล่งของสไลด์ชุดเดียวกัน แล้วดูว่าจำนวนและรุ่นของแบตบนบล็อกของ «Союз» ไม่ตรงกัน",
    ratio: 0.58,
    legend: '<span><i style="background:var(--accent)"></i>22СЦК-25</span>' +
            '<span><i style="background:var(--accent-2)"></i>21СЦК-50Б</span>' +
            '<span><i style="background:var(--ok)"></i>21СЦК-25Б</span>' +
            '<span><i style="background:var(--ink-3)"></i>ไม่ระบุจำนวน</span>',
    buttons: [
      { id: "s0", label: "сл. 20 (текст)", act: st => { st.src = 0; } },
      { id: "s1", label: "сл. 14 (схема)", act: st => { st.src = 1; } },
      { id: "s2", label: "сл. 22 (таблица)", act: st => { st.src = 2; } }
    ],
    draw(ctx, w, h, s, readout) {
      if (s.src === undefined) s.src = 1;
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink = CV("--ink"),
            ink2 = CV("--ink-2"), ink3 = CV("--ink-3"), line2 = CV("--line-2"), ok = CV("--ok");
      const fs = eoFS(w);
      const SRC = ["сл. 20 · текст", "сл. 14 · структурная схема", "сл. 22 · таблица типов"][s.src];
      const BL = [
        { n: "Б", u: "32,5–28 В" }, { n: "В", u: "32,5–28 В" },
        { n: "Г", u: "32,5–28 В" }, { n: "Д", u: "32,5–28 В" },
        { n: "А", u: "32–27,3 В" }, { n: "И", u: "32,5–28 В" }
      ];
      function bat(i) {
        if (s.src === 0) return { c: 2, t: "22СЦК-25", col: acc };
        if (s.src === 1) {
          if (i < 4) return { c: 1, t: "22СЦК-25", col: acc };
          if (i === 4) return { c: 2, t: "21СЦК-50Б", col: acc2 };
          return { c: 2, t: "21СЦК-25Б", col: ok };
        }
        return { c: 0, t: i === 4 ? "21 СЦК-50" : "22 СЦК-25", col: ink3 };
      }
      eoTxt(ctx, "РН «Союз» / «Союз-2» — источник: " + SRC, 8, 8, ink, fs + 1, "left", "top", true);

      const cols = w >= 470 ? 6 : 3;
      const rows = Math.ceil(6 / cols);
      const gw = (w - 12 - (cols - 1) * 6) / cols;
      const gh = (h - 34 - (rows - 1) * 8) / rows;
      let total = 0;
      const types = {};
      BL.forEach((b, i) => {
        const r = Math.floor(i / cols), c = i % cols;
        const x = 6 + c * (gw + 6), y = 26 + r * (gh + 8);
        const bb = bat(i);
        total += bb.c;
        types[bb.t] = 1;
        ctx.save();
        eoRRPath(ctx, x, y, gw, gh, 5);
        ctx.fillStyle = CV("--panel-2"); ctx.fill();
        ctx.strokeStyle = line2; ctx.lineWidth = 1; ctx.stroke();
        ctx.restore();
        eoTxt(ctx, "блок " + b.n, x + gw / 2, y + 11, ink2, fs, "center", "middle", true);
        eoTxt(ctx, b.u, x + gw / 2, y + 11 + fs + 4, ink3, fs - 2, "center", "middle");
        const nb = bb.c || 1;
        const bwid = Math.min(18, (gw - 12) / nb - 3);
        const bx0 = x + gw / 2 - (nb * (bwid + 3) - 3) / 2;
        for (let k = 0; k < nb; k++) {
          const bx = bx0 + k * (bwid + 3), byy = y + 22 + fs * 2;
          ctx.save();
          eoRRPath(ctx, bx, byy, bwid, Math.max(20, gh - 30 - fs * 3), 2);
          ctx.fillStyle = bb.c ? CV("--wash-2") : CV("--panel");
          ctx.fill();
          ctx.strokeStyle = bb.col; ctx.lineWidth = bb.c ? 1.6 : 1;
          if (!bb.c) ctx.setLineDash([2, 2]);
          ctx.stroke();
          ctx.restore();
          if (!bb.c) eoTxt(ctx, "?", bx + bwid / 2, byy + gh * 0.13, ink3, fs, "center", "middle", true);
        }
        eoTxt(ctx, bb.t, x + gw / 2, y + gh - 9, bb.col, fs - 2, "center", "middle", bb.c > 0);
      });

      const nt = Object.keys(types).length;
      readout.innerHTML =
        'จำนวน АБ ทั้งหมดตามแหล่งนี้: <b class="' + (s.src === 2 ? "bad" : "") + '">' +
        (s.src === 2 ? "ไม่ระบุ" : total + " ก้อน") + '</b> · จำนวนรุ่น: <b>' + nt + '</b>' +
        '<span><b>สล. 20 (ข้อความ):</b> 12 ก้อน · รุ่นเดียว 22СЦК-25 · «по две батареи на каждый блок» (Б, В, Г, Д, А, И)</span>' +
        '<span><b>สล. 14 (ผัง):</b> 8 ก้อน · สามรุ่น — боковые 1 × 22СЦК-25 ต่อบล็อก · А 2 × 21СЦК-50Б · И 2 × 21СЦК-25Б</span>' +
        '<span><b>สล. 22 (ตาราง):</b> สองรุ่น 21 СЦК-50 และ 22 СЦК-25 · ไม่ให้จำนวนก้อนเลย</span>' +
        '<span><b>หมายเหตุต้นฉบับ</b> — สามแหล่งนี้อยู่ในสไลด์ชุดเดียวกันแต่<b>ขัดกันทั้งจำนวนก้อน (12 กับ 8) และจำนวนรุ่น (1, 3, 2)</b> · ' +
        'ตาราง сл. 22 สอดคล้องกับผัง сл. 14 เรื่องรุ่น แต่ขัดกับข้อความ сл. 20 ที่บอกว่าใช้ 22СЦК-25 อย่างเดียว — <b>ต้องถามอาจารย์ว่าข้อสอบใช้ชุดใด</b></span>' +
        '<span>การอ่านรหัส: <b>22</b>СЦК-<b>25</b> = 22 เซลล์เงิน-สังกะสีต่อเรียง ความจุ 25 А·ч · 22 × 1,5 В ≈ 33 В จึงพอดีกับบัส 32,5–28 В</span>';
    }
  });
}

/* ================================================================
   12. eoISN4101 — ИСН ЦЕ4101 และแท่นห้องแล็บแบบ понижающий (buck)
   Л15 сл. 25 — โครงสร้าง ЦЕ4101 (ДР, Ф1, Ф2, РЭ, КД, БК, ЗГ, СС, ИОН, ШИМ, УС, СЗ)
   Л15 сл. 26 — U_ст = 32 ± 0,64 В · пульсация ≤ 0,32 В · P_н ≤ 0,5 кВт
   notes/PZ-SES-RN-ISN.md:
     (Ф-S1) f = 1/T · (Ф-S2) T = t_з + t_р · (Ф-S3) U_вых = U_вх·(1 + t_з/t_р)  [boost ของ ЦЕ4101]
     (Ф-K1) q = t_и/T · (Ф-K2) U_вых = q·U_вх · (Ф-K3) I_вх.ср = q·I_вых
     (Ф-K4) ΔI_L = U_вых(1−q)T/L · (Ф-K5) I_вых.гр = ΔI_L/2
     (Ф-K6) ΔU_вых ≈ ΔI_L·[T/(8C) + r_ESR]
     (Ф-K7…K9) P_вх = U_вх·I_вх · P_вых = U_вых·I_вых · η = P_вых/P_вх
     (Ф-K10) R_вых = |ΔU_вых/ΔI_вых| · (Ф-K11) U_вых(ПТ) = U_вх·q²/[q² + 2LI_вых/(U_вх T)]
     (Ф-K12) τ_з = L/R_экв · (Ф-S11) K_п = ΔU_вых/(2U_вых)
   พารามิเตอร์แท่น §19.1 (ผู้เรียบเรียงกำหนด): U_вых.н 13,5 В · R_вых 0,06 Ом · R_экв 0,35 Ом ·
     P₀ 1,2 Вт · C 47 мкФ · r_ESR 0,20 Ом — ตรวจกับตาราง 5.2 แถวที่ 4: I 2,0 А → I_вх 0,924 А, η 91,2 %
================================================================ */
function eoISN4101(host) {
  buildDemo(host, {
    label: "Лекция 15 сл. 25–26 · ПЗ «СЭС РН · ИСН» (Ф-K1…K12)",
    title: "เลื่อนแรงดันเข้า กระแสโหลด ค่า L และความถี่ แล้วดูกระแสใน дроссель โหมด НТ หรือ ПТ และ КПД ของแท่น",
    ratio: 0.56,
    legend: '<span><i style="background:var(--accent)"></i>i<sub>L</sub>(t)</span>' +
            '<span><i style="background:var(--accent-2)"></i>I<sub>вых</sub> ค่าเฉลี่ย</span>' +
            '<span><i style="background:var(--ink-3)"></i>ขอบเขต НТ/ПТ</span>',
    controls: [
      { id: "uin", label: "U<sub>вх</sub>, В", min: 20, max: 36, step: 0.5, value: 32, fmt: v => v.toFixed(1) },
      { id: "io", label: "I<sub>вых</sub>, А", min: 0.1, max: 2.5, step: 0.05, value: 2, fmt: v => v.toFixed(2) },
      { id: "L", label: "L — индуктивность дросселя, мГн", min: 0.1, max: 2, step: 0.05, value: 0.5, fmt: v => v.toFixed(2) },
      { id: "f", label: "f — частота коммутации, кГц", min: 10, max: 40, step: 1, value: 20 }
    ],
    draw(ctx, w, h, s, readout) {
      const acc = CV("--accent"), acc2 = CV("--accent-2"), ink2 = CV("--ink-2"),
            ink3 = CV("--ink-3"), ok = CV("--ok"), crit = CV("--crit");
      const fs = eoFS(w);
      const RV = 0.06, REQ = 0.35, P0 = 1.2, C = 47e-6, ESR = 0.20, UN = 13.60;

      const T = 1 / (s.f * 1000), L = s.L * 1e-3;
      let Uo = UN - RV * s.io;
      let q = (Uo + REQ * s.io) / s.uin;
      const sat = q >= 1;
      if (sat) { q = 1; Uo = s.uin - REQ * s.io; }
      const dIL = Uo * (1 - q) * T / L;
      const Igr = dIL / 2;
      const PT = s.io < Igr;
      const dU = dIL * (T / (8 * C) + ESR);
      const Pout = Uo * s.io;
      const Ploss = P0 + REQ * s.io * s.io;
      const Pin = Pout + Ploss;
      const Iin = Pin / s.uin;
      const eff = Pout / Pin * 100;
      const Kp = dU / (2 * Uo);
      const tau = L / REQ;
      const Upt = s.uin * q * q / (q * q + 2 * L * s.io / (s.uin * T));

      const tmax = 2.2 * T * 1e6;
      const imax = Math.max(s.io + dIL, 0.4) * 1.35;
      const p = new Plot(ctx, 44, 18, w - 58, h - 52, 0, tmax, 0, imax);
      p.frame(ticks(0, tmax, 5), eoTicksNice(0, imax, 4), "t, мкс","i L, А");

      const pts = [];
      const Ton = q * T;
      if (!PT) {
        let i0 = s.io - dIL / 2;
        for (let k = 0; k < 3; k++) {
          const t0 = k * T;
          pts.push([t0 * 1e6, i0]);
          pts.push([(t0 + Ton) * 1e6, i0 + dIL]);
          pts.push([(t0 + T) * 1e6, i0]);
        }
      } else {
        /* โหมดกระแสไม่ต่อเนื่อง: ขึ้นด้วยความชัน (U_вх−U_вых)/L, ลงด้วย U_вых/L, แล้วเป็นศูนย์ */
        const ipk = Math.sqrt(Math.max(1e-9, 2 * s.io * L * ((s.uin - Upt) + Upt) / T / Math.max(0.01, (s.uin - Upt) * Upt / ((s.uin - Upt) + Upt))));
        const Ipk = Math.min(ipk, 3 * s.io + dIL);
        const t1 = Ipk * L / Math.max(0.5, s.uin - Upt);
        const t2 = Ipk * L / Math.max(0.5, Upt);
        for (let k = 0; k < 3; k++) {
          const t0 = k * T;
          pts.push([t0 * 1e6, 0]);
          pts.push([(t0 + t1) * 1e6, Ipk]);
          pts.push([(t0 + t1 + t2) * 1e6, 0]);
          pts.push([(t0 + T) * 1e6, 0]);
        }
      }
      p.clip(() => {
        p.line([[0, s.io], [tmax, s.io]], acc2, 1.4, [5, 4]);
        p.line([[0, Igr], [tmax, Igr]], ink3, 1.2, [2, 3]);
        p.line(pts, acc, 2.2);
      });
      eoTxt(ctx, "I вых = " + s.io.toFixed(2) + " А", p.x + p.w - 4, p.Y(s.io) - 8, acc2, fs - 1, "right", "middle");
      eoTxt(ctx, "I вых.гр = " + Igr.toFixed(3) + " А", p.x + 8, Math.min(p.y + p.h - 6, p.Y(Igr) + 9), ink3, fs - 2, "left", "middle");
      eoTxt(ctx, PT ? "режим ПТ" : "режим НТ", p.x + 4, p.y + 9, PT ? crit : ok, fs, "left", "middle", true);

      readout.innerHTML =
        'η = <b class="' + (eff >= 90 ? "good" : eff < 80 ? "bad" : "") + '">' + eff.toFixed(1) + ' %</b>' +
        ' · q = <b>' + q.toFixed(3) + '</b> · U<sub>вых</sub> = <b>' + Uo.toFixed(2) + ' В</b>' +
        '<span>T = <b>' + (T * 1e6).toFixed(1) + ' мкс</b> · t<sub>и</sub> = <b>' + (Ton * 1e6).toFixed(1) +
        ' мкс</b> · ΔI<sub>L</sub> = <b>' + dIL.toFixed(3) + ' А</b> (Ф-K4)</span>' +
        '<span>ΔU<sub>вых</sub> = <b>' + dU.toFixed(3) + ' В</b> (Ф-K6) · K<sub>п</sub> = <b>' +
        (Kp * 100).toFixed(2) + ' %</b> (Ф-S11) · τ<sub>з</sub> = L/R<sub>экв</sub> = <b>' +
        (tau * 1e6).toFixed(0) + ' мкс</b> ≫ t<sub>и</sub> (Ф-K12)</span>' +
        '<span>P<sub>вых</sub> = <b>' + Pout.toFixed(2) + ' Вт</b> · P<sub>вх</sub> = <b>' + Pin.toFixed(2) +
        ' Вт</b> · I<sub>вх</sub> = <b>' + Iin.toFixed(3) + ' А</b> (Ф-K7…K9)</span>' +
        '<span>' + (sat ? 'q ถึง 1 แล้ว — วงจรออกจากย่านรักษาระดับ แรงดันขาออกลอยตาม U<sub>вх</sub>'
          : PT ? 'I<sub>вых</sub> &lt; I<sub>вых.гр</sub> → โหมดกระแสไม่ต่อเนื่อง: U<sub>вых</sub> ขึ้นกับกระแสโหลดตาม Ф-K11 (ที่ q นี้ให้ ' + Upt.toFixed(2) + ' В) ไม่ใช่ q·U<sub>вх</sub> อีกต่อไป'
          : 'ในโหมด НТ ค่า ΔU<sub>вых</sub> แทบไม่ขึ้นกับ I<sub>вых</sub> เพราะ ΔI<sub>L</sub> ไม่ขึ้นกับกระแสโหลด') + '</span>' +
        '<span>ตรวจกับตาราง 5.2 แถวที่ 4 (U<sub>вх</sub> 32 В, I<sub>вых</sub> 2,0 А): U<sub>вых</sub> 13,48 В · I<sub>вх</sub> 0,924 А · q 0,443 · η 91,2 % · R<sub>вых</sub> = 0,060 Ом (Ф-K10)</span>' +
        '<span><b>หมายเหตุต้นฉบับ</b> — อุปกรณ์จริง <b>ЦЕ4101 เป็นวงจรแบบเพิ่มแรงดัน</b> (дроссель อนุกรม + ключ ขนาน, U<sub>вых</sub> = U<sub>вх</sub>(1 + t<sub>з</sub>/t<sub>р</sub>) = 32 ± 0,64 В จาก 24–32 В) ' +
        'ส่วน<b>แท่งห้องแล็บเป็นวงจรลดแรงดัน</b> จึงต้องใช้ชุด Ф-K ที่ผู้เรียบเรียงกู้คืนไว้ · เอกสารให้เฉพาะ Ф-S3 ของวงจรเพิ่มแรงดัน และ<b>ไม่ให้ค่า L, C, f ของแท่นเลย</b> ค่าที่ใช้ที่นี่เป็นค่าสมมติของ §19.1</span>';
    }
  });
}

window.EODEMOS = Object.assign(window.EODEMOS || {}, {
  eoShadow, eoCyclogram, eoSESsize, eoDOD, eoOSH, eoRSH, eoSNzones, eoSBtemp,
  eoLogicOSH, eoRNbalance, eoRNstruct, eoISN4101
});

/* ================= ЭОЛА — กลุ่ม F · Тема 8 ระบบจ่ายไฟภาคพื้น =================
   ไฟล์นี้บรรจุแบบจำลองโต้ตอบ 8 ตัวของหัวข้อ elob-16 … elob-18
   แหล่งสูตรและตัวเลขทั้งหมด: notes/L16.md · notes/L17.md · notes/L18.md
   (หัวข้อ «Формулы», «Числовые данные», «Идеи демонстраций»)

   สรุปสูตรที่ใช้ต่อเดโม (รายละเอียดอยู่ในคอมเมนต์เหนือแต่ละฟังก์ชัน):
     eoGroundNet — k_тр = U_вх / U_вых  · ลำดับชั้น 110(35) → 6(10) → 0,4 кВ   (Л16 сл. 10–12)
     eoCategory  — t_факт ≤ t_доп และ n_ист ≥ n_треб · หมวด 1 = 1,5 с          (Л16 сл. 14)
     eoAVR       — t_перерыва = t_обн + t_КМ เทียบกับ 1,5 с                     (Л17 сл. 27 · Л16 сл. 10, 14)
     eoEMPchar   — U = E₀ − I(R_а·cos φ + X_d·sin φ) · I_В = f(I_н) · f = p·n/60 (Л17 сл. 18 · 21–22)
     eoPSCH      — f = p·n₁(1 − s)/60 เทียบกับตารางจริง 388…392 / 390 / 427 Гц  (Л17 сл. 21–22)
     eoTPS       — U_d = 1,35·U_л·cos α · K_п = ΔU/(2U₀)                        (Л18 сл. 17, 19)
     eoDrossel   — L(I_у) = L_min + (L_max − L_min)e^(−I_у/I₀) · X_L = ωL       (Л18 сл. 18, Рис. 3.16)
     eoCombined  — P = U·I · t_раб = C_АБ·U_АБ·k_р·η / P_н                      (Л18 сл. 34–37)
=========================================================================== */

/* ---------- เครื่องมือวาดร่วมของกลุ่ม F (ไม่แตะเอนจินในเปลือก)
   ใช้คำนำหน้า eoFx… เพื่อไม่ให้ชนกับฟังก์ชันช่วยของไฟล์เดโมกลุ่มอื่น ---------- */

/* ---- ป้ายค่าบนแกนแบบเลขกลม (แทนการส่ง min/max ดิบเข้า ticks) ---- */
function eoFxNiceStep(span, n) {
  var raw = Math.abs(span) / Math.max(1, n);
  if (!(raw > 0) || !isFinite(raw)) return 1;
  var e = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), f = raw / e;
  return (f < 1.5 ? 1 : f < 3.5 ? 2 : f < 7.5 ? 5 : 10) * e;
}
function eoFxTicksN(a, b, n) {
  if (!isFinite(a) || !isFinite(b) || b <= a) return [a, b];
  /* เอนจินพิมพ์ป้ายด้วย toFixed(2) — ก้าวต่ำกว่า 0,01 จะได้ป้ายซ้ำ จึงยกพื้นไว้ */
  var st = Math.max(eoFxNiceStep(b - a, n), 0.01), out = [], seen = {}, lab,
    k = Math.ceil((a - st * 1e-6) / st), guard = 0, v;
  for (; k * st <= b + st * 1e-6 && guard < 400; k++, guard++) {
    v = +(k * st).toPrecision(12);
    lab = String(+v.toFixed(2));
    if (seen[lab]) continue;
    seen[lab] = 1; out.push(v);
  }
  return out.length >= 2 ? out : [a, b];
}

function eoFxSz(w, base) { return Math.max(7.4, base * Math.min(1, w / 540)); }

function eoFxTxt(ctx, str, x, y, px, color, align, baseline, bold) {
  ctx.save();
  ctx.font = (bold ? "600 " : "") + px.toFixed(1) + 'px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';
  ctx.fillStyle = color;
  ctx.textAlign = align || "left";
  ctx.textBaseline = baseline || "middle";
  ctx.fillText(str, x, y);
  ctx.restore();
}

function eoFxMono(ctx, str, x, y, px, color, align, baseline) {
  ctx.save();
  ctx.font = px.toFixed(1) + 'px "IBM Plex Mono", ui-monospace, monospace';
  ctx.fillStyle = color;
  ctx.textAlign = align || "left";
  ctx.textBaseline = baseline || "middle";
  ctx.fillText(str, x, y);
  ctx.restore();
}

function eoFxPath(ctx, x, y, w, h, r) {
  var rr = Math.min(r === undefined ? 4 : r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + rr, y);
  ctx.lineTo(x + w - rr, y); ctx.quadraticCurveTo(x + w, y, x + w, y + rr);
  ctx.lineTo(x + w, y + h - rr); ctx.quadraticCurveTo(x + w, y + h, x + w - rr, y + h);
  ctx.lineTo(x + rr, y + h); ctx.quadraticCurveTo(x, y + h, x, y + h - rr);
  ctx.lineTo(x, y + rr); ctx.quadraticCurveTo(x, y, x + rr, y);
  ctx.closePath();
}

function eoFxBox(ctx, x, y, w, h, fill, stroke, lw, dash) {
  ctx.save();
  eoFxPath(ctx, x, y, w, h, 4);
  if (fill) { ctx.fillStyle = fill; ctx.fill(); }
  if (stroke) {
    if (dash) ctx.setLineDash(dash);
    ctx.strokeStyle = stroke; ctx.lineWidth = lw || 1.3; ctx.stroke();
  }
  ctx.restore();
}

function eoFxSeg(ctx, pts, color, lw, dash) {
  ctx.save();
  ctx.beginPath();
  if (dash) ctx.setLineDash(dash);
  ctx.strokeStyle = color; ctx.lineWidth = lw || 1.4;
  ctx.lineJoin = "round"; ctx.lineCap = "round";
  pts.forEach(function (p, i) { i ? ctx.lineTo(p[0], p[1]) : ctx.moveTo(p[0], p[1]); });
  ctx.stroke();
  ctx.restore();
}

function eoFxArrowDown(ctx, x, y1, y2, color, lw, dash) {
  eoFxSeg(ctx, [[x, y1], [x, y2 - 4]], color, lw, dash);
  ctx.save();
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.moveTo(x, y2); ctx.lineTo(x - 3.4, y2 - 5); ctx.lineTo(x + 3.4, y2 - 5);
  ctx.closePath(); ctx.fill();
  ctx.restore();
}

/* ย่อฟอนต์/ตัดข้อความให้อยู่ในความกว้าง maxw เสมอ (จำเป็นที่ 390 px) */
function eoFxFit(ctx, str, x, y, px, color, align, baseline, bold, maxw) {
  ctx.save();
  var f = px, ff = function (v) {
    return (bold ? "600 " : "") + v.toFixed(1) + 'px system-ui, -apple-system, "Segoe UI", Roboto, sans-serif';
  };
  ctx.font = ff(f);
  while (f > 6.6 && ctx.measureText(str).width > maxw) { f -= 0.4; ctx.font = ff(f); }
  var t = str;
  while (t.length > 1 && ctx.measureText(t + "…").width > maxw) t = t.slice(0, -1);
  if (t !== str) t += "…";
  ctx.restore();
  eoFxTxt(ctx, t, x, y, f, color, align, baseline, bold);
}

function eoFxNum(v, d) { return (Math.round(v * Math.pow(10, d)) / Math.pow(10, d)).toFixed(d).replace(".", ","); }

/* =========================================================================
   1. eoGroundNet — โครงสร้างจ่ายไฟภาคพื้น ГТП → ЦРП → ТП1…ТПк → потребители
   สูตร/แหล่ง: Л16 сл. 10–12
     · ลำดับชั้นแรงดัน 110 (35) кВ → [ГТП] → 6 (10) кВ → [ТПП/ТП] → 0,4 кВ   (сл. 12)
     · k_тр = U_вх / U_вых — อัตราส่วนหม้อแปลงของแต่ละชั้น (คำนวณจากตัวเลขบนสไลด์)
     · การแพร่ของการดับไฟลงตามต้นไม้: ผู้ใช้จะดับเมื่อกิ่งเหนือมันขาดทั้งหมด
       (สายเข้าสองทางอิสระ Ввод 1 / Ввод 2 → ขาดทางเดียวไฟไม่ดับ — сл. 10, 14)
     · ผู้ใช้หมวด 1А ที่ต่อผ่าน УГП/ДЭС ยังมีไฟเมื่อ ТП ของตัวเองเสีย (сл. 12, 15–17)
   ========================================================================= */
function eoGroundNet(host) {
  var FAULT = ["без аварии", "обрыв Ввода 1", "обрыв Ввода 2", "авария ГТП", "авария ЦРП",
    "авария ТП1", "авария ТП2", "авария ТП3", "авария ТПк"];
  var TP = [
    { n: "ТП1", u: "6 кВ", a: "насосная,", b: "компрессорная", k: "кат. 2" },
    { n: "ТП2", u: "0,4 кВ", a: "КП, ПУ, УС", b: "через УГП", k: "кат. 1А" },
    { n: "ТП3", u: "0,4 кВ", a: "техздания", b: "РЭС", k: "кат. 2" },
    { n: "ТПк", u: "6 кВ", a: "освещение,", b: "жилой городок", k: "кат. 3" }
  ];

  buildDemo(host, {
    label: "Лекция 16 · сл. 10–12",
    title: "เลือกจุดที่เกิดความบกพร่อง แล้วดูว่าผู้ใช้ไฟกลุ่มไหนดับ และดับเพราะอะไร",
    ratio: 0.72,
    legend: '<span><i style="background:var(--ok)"></i>มีไฟตามปกติ</span>' +
      '<span><i style="background:var(--accent-2)"></i>มีไฟจาก УГП / ДЭС</span>' +
      '<span><i style="background:var(--crit)"></i>ไฟดับ</span>',
    controls: [
      { id: "f", label: "จุดบกพร่อง", min: 0, max: 8, step: 1, value: 0, fmt: function (v) { return FAULT[Math.round(v)]; } },
      { id: "Uv", label: "U ทางเข้า, кВ", min: 35, max: 110, step: 75, value: 110, fmt: function (v) { return v.toFixed(0); } },
      { id: "Us", label: "U ชั้นกลาง, кВ", min: 6, max: 10, step: 4, value: 6, fmt: function (v) { return v.toFixed(0); } }
    ],
    buttons: [
      { id: "vv2", label: "Ввод 2 в работе", toggle: true, value: true },
      { id: "ugp", label: "УГП + ДЭС в работе", toggle: true, value: true }
    ],
    draw: function (ctx, w, h, s, readout) {
      var ok = CV("--ok"), bad = CV("--crit"), ink = CV("--ink"), ink3 = CV("--ink-3"),
        pan = CV("--panel-2"), lin = CV("--line-2"), acc2 = CV("--accent-2");
      var f = Math.round(s.f), uv = s.Uv, us = s.Us;

      var in1 = f !== 1;
      var in2 = !!s.vv2 && f !== 2;
      var gtp = (in1 || in2) && f !== 3;
      var crp = gtp && f !== 4;
      var alive = [0, 1, 2, 3].map(function (i) { return crp && f !== (5 + i); });
      /* 2 = แหล่งปกติ · 1 = จ่ายจาก УГП/ДЭС · 0 = ดับ */
      var st = alive.map(function (a, i) { return a ? 2 : (i === 1 && s.ugp ? 1 : 0); });
      var dead = st.filter(function (v) { return v === 0; }).length;

      var F1 = eoFxSz(w, 11), F2 = eoFxSz(w, 9.2), F3 = eoFxSz(w, 8.2);
      var pad = 6, top = 10, bot = h - 22;
      var row = (bot - top) / 5;
      var bh = Math.min(21, row * 0.52);
      var yIn = top + row * 0.15, yG = top + row * 1.05, yC = top + row * 2.05,
        yT = top + row * 3.05, yP = top + row * 4.05;
      var cx = w / 2;

      /* --- แถวสายเข้าจาก госэнергосистема --- */
      var bw = Math.min(104, (w - 3 * pad) / 2.4);
      var x1 = cx - bw - 8, x2 = cx + 8;
      eoFxTxt(ctx, "от Госэнергосистемы", cx, top - 2, F3, ink3, "center", "top");
      eoFxBox(ctx, x1, yIn + 8, bw, bh, pan, in1 ? ok : bad, in1 ? 1.3 : 1.8, in1 ? null : [4, 3]);
      eoFxTxt(ctx, "Ввод 1", x1 + bw / 2, yIn + 8 + bh / 2, F2, in1 ? ink : bad, "center", "middle", true);
      eoFxBox(ctx, x2, yIn + 8, bw, bh, pan, in2 ? ok : bad, in2 ? 1.3 : 1.8, in2 ? null : [4, 3]);
      eoFxTxt(ctx, "Ввод 2", x2 + bw / 2, yIn + 8 + bh / 2, F2, in2 ? ink : bad, "center", "middle", true);
      eoFxTxt(ctx, "~" + uv.toFixed(0) + " кВ · 50 Гц", cx, yIn + 8 + bh + 7, F3, ink3, "center", "middle");

      /* --- ГТП --- */
      var gw = Math.min(132, w * 0.38);
      eoFxArrowDown(ctx, x1 + bw / 2, yIn + 8 + bh, yG, in1 ? ok : bad, in1 ? 1.6 : 1.2, in1 ? null : [3, 3]);
      eoFxArrowDown(ctx, x2 + bw / 2, yIn + 8 + bh, yG, in2 ? ok : bad, in2 ? 1.6 : 1.2, in2 ? null : [3, 3]);
      eoFxSeg(ctx, [[x1 + bw / 2, yG], [x2 + bw / 2, yG]], gtp ? ok : bad, 1.4);
      eoFxBox(ctx, cx - gw / 2, yG + 2, gw, bh, pan, gtp ? ok : bad, gtp ? 1.5 : 1.8, gtp ? null : [4, 3]);
      eoFxTxt(ctx, "ГТП", cx, yG + 2 + bh / 2, F1, gtp ? ink : bad, "center", "middle", true);
      eoFxTxt(ctx, uv.toFixed(0) + " → " + us.toFixed(0) + " кВ · k = " + eoFxNum(uv / us, 1),
        cx + gw / 2 + 5, yG + 2 + bh / 2, F3, ink3, "left", "middle");

      /* --- ЦРП + СГЭП + ДЭС --- */
      var cw = Math.min(112, w * 0.32);
      eoFxArrowDown(ctx, cx, yG + 2 + bh, yC, gtp ? ok : bad, gtp ? 1.6 : 1.2, gtp ? null : [3, 3]);
      eoFxBox(ctx, cx - cw / 2, yC, cw, bh, pan, crp ? ok : bad, crp ? 1.5 : 1.8, crp ? null : [4, 3]);
      eoFxTxt(ctx, "ЦРП", cx, yC + bh / 2, F1, crp ? ink : bad, "center", "middle", true);
      var sw = Math.min(74, w * 0.22);
      eoFxBox(ctx, w - pad - sw, yC, sw, bh, pan, s.ugp ? acc2 : lin, 1.2, s.ugp ? null : [3, 3]);
      eoFxTxt(ctx, "СГЭП", w - pad - sw / 2, yC + bh / 2, F2, s.ugp ? ink : ink3, "center", "middle");
      eoFxSeg(ctx, [[cx + cw / 2, yC + bh / 2], [w - pad - sw, yC + bh / 2]], s.ugp ? acc2 : lin, 1.2, [3, 3]);
      eoFxBox(ctx, pad, yC, sw, bh, pan, s.ugp ? acc2 : lin, 1.2, s.ugp ? null : [3, 3]);
      eoFxTxt(ctx, "ДЭС", pad + sw / 2, yC + bh / 2, F2, s.ugp ? ink : ink3, "center", "middle");
      eoFxSeg(ctx, [[pad + sw, yC + bh / 2], [cx - cw / 2, yC + bh / 2]], s.ugp ? acc2 : lin, 1.2, [3, 3]);

      /* --- แถว ТП --- */
      var gap = 5, tw = (w - 2 * pad - 3 * gap) / 4;
      var busY = yT - 8;
      eoFxArrowDown(ctx, cx, yC + bh, busY, crp ? ok : bad, crp ? 1.6 : 1.2, crp ? null : [3, 3]);
      eoFxSeg(ctx, [[pad + tw / 2, busY], [w - pad - tw / 2, busY]], crp ? ok : bad, 1.4, crp ? null : [3, 3]);
      TP.forEach(function (t, i) {
        var x = pad + i * (tw + gap);
        var a = alive[i], col = a ? ok : bad;
        eoFxArrowDown(ctx, x + tw / 2, busY, yT, col, a ? 1.5 : 1.1, a ? null : [3, 3]);
        eoFxBox(ctx, x, yT, tw, bh, pan, col, a ? 1.4 : 1.8, a ? null : [4, 3]);
        eoFxTxt(ctx, t.n, x + tw / 2, yT + bh / 2, F2, a ? ink : bad, "center", "middle", true);

        /* --- ผู้ใช้ไฟใต้ ТП --- */
        var c = st[i] === 2 ? ok : (st[i] === 1 ? acc2 : bad);
        eoFxArrowDown(ctx, x + tw / 2, yT + bh, yP, c, st[i] ? 1.5 : 1.1, st[i] === 2 ? null : [3, 3]);
        eoFxTxt(ctx, t.u, x + tw / 2, yP + 5, F3, c, "center", "middle", true);
        eoFxTxt(ctx, t.a, x + tw / 2, yP + 5 + F3 * 1.35, F3, ink3, "center", "middle");
        eoFxTxt(ctx, t.b, x + tw / 2, yP + 5 + F3 * 2.6, F3, ink3, "center", "middle");
        eoFxTxt(ctx, t.k, x + tw / 2, yP + 5 + F3 * 3.9, F3, st[i] === 0 ? bad : ink3, "center", "middle");
      });

      /* --- หมายเหตุตัวย่อสถานีหลัก (Замечания к источнику Л16 ข้อ 2) --- */
      eoFxTxt(ctx, "ГТП — по сл. 12; на сл. 10 напечатано ГПП, на сл. 11 — ГПТ",
        cx, h - 8, eoFxSz(w, 8.4), ink3, "center", "middle");

      var why;
      if (f === 0) why = "ระบบปกติ ผู้ใช้ได้ไฟครบทุกกลุ่ม";
      else if (f === 1 || f === 2) why = in1 || in2 ? "สายเข้าอีกทางรับภาระแทน — นี่คือความหมายของ «два независимых источника»" : "สายเข้าขาดทั้งสองทาง — ทั้งฐานดับ";
      else if (f === 3) why = "ГТП เป็นจุดเดียวที่ไม่มีการสำรอง สายเข้าสองทางจึงช่วยไม่ได้";
      else if (f === 4) why = "ЦРП อยู่เหนือ ТП ทุกตัว ความเสียหายจึงลามลงทั้งแถว";
      else why = "ความเสียหายที่ ТП ตัวเดียวจำกัดอยู่เฉพาะผู้ใช้ใต้ ТП ตัวนั้น";

      readout.innerHTML =
        'обесточено: <b class="' + (dead ? "bad" : "good") + '">' + dead + ' จาก 4 กลุ่ม</b>' +
        '<span>k<sub>ГТП</sub> = <b>' + eoFxNum(uv / us, 1) + '</b></span>' +
        '<span>k<sub>ТПП</sub> = <b>' + eoFxNum(us / 0.4, 1) + '</b></span>' +
        '<span>รวมทั้งสายโซ่ = <b>' + eoFxNum(uv / 0.4, 0) + '</b></span>' +
        '<span>' + why + '</span>';
    }
  });
}

/* =========================================================================
   2. eoCategory — สามประเภทผู้ใช้ไฟตามความต่อเนื่องของการจ่ายไฟ
   สูตร/แหล่ง: Л16 сл. 14 (คำถามสอบข้อ 38)
     · หมวด 1 (1А, 1Б, 1В): перерыв ≤ 1,5 с — 1А ต้องมี 3 แหล่งอิสระ, 1Б/1В 2 แหล่ง
     · หมวด 2: перерыв = เวลาสับสวิตช์สำรอง «ด้วยมือ»
     · หมวด 3: перерыв = เวลาซ่อมบำรุง · 1 แหล่ง
     เงื่อนไขผ่าน: t_факт ≤ t_доп และ n_ист ≥ n_треб (สไลด์ให้ตัวเลขเฉพาะ 1,5 с กับจำนวนแหล่ง
     ส่วนค่า t ของหมวด 2 และ 3 สไลด์ไม่ให้ตัวเลข → เป็นสไลเดอร์ที่ผู้เรียบเรียงเสริม)
   ========================================================================= */
function eoCategory(host) {
  buildDemo(host, {
    label: "Лекция 16 · сл. 14 · คำถามสอบข้อ 38",
    title: "เลื่อนเวลาไฟขาดจริงกับจำนวนแหล่งจ่ายอิสระ แล้วดูว่าผู้ใช้หมวดใดยังยอมรับได้",
    ratio: 0.62,
    legend: '<span><i style="background:var(--ok)"></i>ผ่านเกณฑ์</span>' +
      '<span><i style="background:var(--crit)"></i>ไม่ผ่าน</span>' +
      '<span><i style="background:var(--accent)"></i>t ที่เกิดขึ้นจริง</span>',
    controls: [
      {
        id: "lt", label: "t ไฟขาดจริง", min: -2, max: 4.2, step: 0.02, value: -0.3,
        fmt: function (v) {
          var t = Math.pow(10, v);
          return t < 1 ? (t * 1000).toFixed(0) + " мс" : (t < 3600 ? eoFxNum(t, 1) + " с" : eoFxNum(t / 3600, 1) + " ч");
        }
      },
      { id: "n", label: "จำนวนแหล่งจ่ายอิสระ", min: 1, max: 3, step: 1, value: 2, fmt: function (v) { return v.toFixed(0) + " ист."; } },
      { id: "tr", label: "เวลาสับสวิตช์ด้วยมือ (หมวด 2)", min: 5, max: 180, step: 5, value: 30, fmt: function (v) { return v.toFixed(0) + " с"; } },
      { id: "tv", label: "เวลาซ่อมบำรุง (หมวด 3)", min: 0.5, max: 24, step: 0.5, value: 4, fmt: function (v) { return eoFxNum(v, 1) + " ч"; } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var ok = CV("--ok"), bad = CV("--crit"), ink = CV("--ink"), ink3 = CV("--ink-3"),
        acc = CV("--accent"), grid = CV("--grid");
      var t = Math.pow(10, s.lt), n = Math.round(s.n);

      var CAT = [
        { n: "1А", tp: 1.5, ns: 3, ex: "КП · ПУ · УС", src: "3 независимых источника" },
        { n: "1Б", tp: 1.5, ns: 2, ex: "КП · ПУ · УС", src: "2 независимых источника" },
        { n: "1В", tp: 1.5, ns: 2, ex: "КП · ПУ · УС", src: "2 независимых источника" },
        { n: "2", tp: s.tr, ns: 1, ex: "ручное включение резерва", src: "—" },
        { n: "3", tp: s.tv * 3600, ns: 1, ex: "освещение дорог · жилой городок", src: "1 источник" }
      ];

      var F1 = eoFxSz(w, 10), F2 = eoFxSz(w, 8.6);
      var lw = Math.min(120, w * 0.30);
      var x0 = lw + 4, x1 = w - 8, wid = x1 - x0;
      var lo = -2, hi = 4.6;
      var X = function (v) { return x0 + (Math.log(v) / Math.LN10 - lo) / (hi - lo) * wid; };
      var top = 26, bh = 15, gap = Math.max(4, (h - top - 40 - 5 * bh) / 4);

      /* กริดแกนเวลาแบบลอการิทึม */
      var lab = [[0.01, "10 мс"], [0.1, "0,1 с"], [1, "1 с"], [10, "10 с"], [60, "1 мин"],
      [3600, "1 ч"], [36000, "10 ч"]];
      lab.forEach(function (L) {
        var px = Math.round(X(L[0])) + 0.5;
        eoFxSeg(ctx, [[px, top - 4], [px, top + 4 * (bh + gap) + bh + 4]], grid, 1);
        eoFxTxt(ctx, L[1], px, h - 20, F2, ink3, "center", "middle");
      });

      CAT.forEach(function (c, i) {
        var y = top + i * (bh + gap);
        var pass = (t <= c.tp) && (n >= c.ns);
        var col = pass ? ok : bad;
        eoFxTxt(ctx, "категория " + c.n, lw, y + bh / 2, F1, ink, "right", "middle", true);
        var bx = X(0.01), bw2 = Math.max(2, Math.min(X(c.tp), x1) - bx);   /* ไม่ให้แท่งล้นขอบขวา */
        eoFxBox(ctx, bx, y, bw2, bh, pass ? "rgba(70,150,110,0.20)" : "rgba(190,70,60,0.18)", col, 1.2);
        var lbl = c.tp < 60 ? eoFxNum(c.tp, c.tp < 10 ? 1 : 0) + " с" : eoFxNum(c.tp / 3600, 1) + " ч";
        var ctxt = "≤ " + lbl + (c.ns > 1 ? " · " + c.ns + " ист." : "");
        ctx.save(); ctx.font = F2.toFixed(1) + 'px system-ui, sans-serif';
        var ctw = ctx.measureText(ctxt).width; ctx.restore();
        var toRight = bx + bw2 + 5 + ctw <= x1 - 2;
        eoFxTxt(ctx, ctxt, toRight ? bx + bw2 + 5 : Math.min(bx + bw2 - 4, x1 - 2),
          y + bh / 2, F2, col, toRight ? "left" : "right", "middle");
      });

      /* เส้นเวลาไฟขาดจริง */
      var px = Math.round(X(Math.max(0.01, Math.min(t, 36000)))) + 0.5;
      eoFxSeg(ctx, [[px, top - 8], [px, top + 5 * (bh + gap) - gap + 4]], acc, 2);
      eoFxTxt(ctx, "t = " + (t < 1 ? (t * 1000).toFixed(0) + " мс" : (t < 3600 ? eoFxNum(t, 1) + " с" : eoFxNum(t / 3600, 1) + " ч")),
        Math.min(px + 4, x1), top - 9, F2, acc, px + 70 > x1 ? "right" : "left", "bottom", true);
      /* (ป้ายเวลาอยู่เหนือแถบแรก — top = 26 จึงไม่ถูกตัดที่ขอบบน) */

      var narrowF = w < 560;
      eoFxFit(ctx, narrowF ? "перерыв (лог. шкала)" : "перерыв в электроснабжении (шкала логарифмическая)",
        x1, h - 6, F2, ink3, "right", "middle", false, (x1 - x0) * 0.58);
      eoFxFit(ctx, narrowF ? "n = " + n + " ист." : "n = " + n + " независимых источника",
        x0 + 2, h - 6, F2, ink3, "left", "middle", false, (x1 - x0) * 0.38);

      var pass = CAT.filter(function (c) { return t <= c.tp && n >= c.ns; }).map(function (c) { return c.n; });
      var fail = CAT.filter(function (c) { return !(t <= c.tp && n >= c.ns); }).map(function (c) { return c.n; });

      readout.innerHTML =
        'ผ่านเกณฑ์: <b class="' + (pass.length ? "good" : "bad") + '">' + (pass.length ? pass.join(" · ") : "ไม่มีหมวดใดผ่าน") + '</b>' +
        '<span>ไม่ผ่าน: <b class="' + (fail.length ? "bad" : "good") + '">' + (fail.length ? fail.join(" · ") : "ไม่มี") + '</b></span>' +
        '<span>เกณฑ์หมวด 1 บนสไลด์: <b>не более 1,5 с</b></span>' +
        '<span>1А ต้อง 3 แหล่ง · 1Б และ 1В ต้อง 2 แหล่ง · หมวด 3 ใช้ 1 แหล่ง</span>' +
        '<span>ค่าเวลาของหมวด 2 และ 3 สไลด์ไม่ได้ให้ตัวเลข — สไลเดอร์สองตัวล่างเป็นค่าสมมติของ <b>ผู้เรียบเรียง</b></span>';
    }
  });
}

/* =========================================================================
   3. eoAVR — สองทางเข้าและการสลับสำรองอัตโนมัติ (АВР)
   สูตร/แหล่ง: Л17 сл. 27 (прибор питания С-13242: КАНАЛ 1 / КАНАЛ 2 + контактор КМ)
               Л16 сл. 10 (Ввод 1 / Ввод 2) · Л16 сл. 14 (เกณฑ์ 1,5 с ของหมวด 1)
     · t_перерыва = t_обн + t_КМ  (ผู้เรียบเรียงเสริม — สไลด์ไม่ให้ตัวเลขเวลา
       ช่วง t_КМ = 20…100 мс มาจากลำดับขนาดของคอนแทกเตอร์ที่บันทึกไว้ใน notes/L17.md)
     · เกณฑ์ตัดสิน: t_перерыва ≤ 1,5 с = 1500 мс (Л16 сл. 14)
     · แรงดันขณะทำงาน u(τ) = √2·U·sin(2π f τ), U = 380 В, f = 50 Гц
   ========================================================================= */
function eoAVR(host) {
  buildDemo(host, {
    label: "Лекция 17 · сл. 27 · Лекция 16 · сл. 10, 14",
    title: "ดูการสลับไปสายสำรองเมื่อ Ввод 1 หาย — ช่วงไฟขาดยาวเท่าไร และผ่านเกณฑ์ 1,5 с หรือไม่",
    ratio: 0.66,
    animate: true,
    legend: '<span><i style="background:var(--ok)"></i>สายที่จ่ายไฟอยู่</span>' +
      '<span><i style="background:var(--crit)"></i>สายที่หาย</span>' +
      '<span><i style="background:var(--accent)"></i>u(t) ที่โหลด</span>',
    controls: [
      { id: "tobn", label: "t обнаружения, мс", min: 10, max: 300, step: 5, value: 60, fmt: function (v) { return v.toFixed(0); } },
      { id: "tkm", label: "t срабатывания КМ, мс", min: 20, max: 150, step: 5, value: 40, fmt: function (v) { return v.toFixed(0); } }
    ],
    buttons: [
      { id: "avr", label: "АВР включено", toggle: true, value: true }
    ],
    draw: function (ctx, w, h, s, readout, t) {
      var ok = CV("--ok"), bad = CV("--crit"), ink = CV("--ink"), ink3 = CV("--ink-3"),
        acc = CV("--accent"), pan = CV("--panel-2"), lin = CV("--line-2");
      var tp = (s.tobn + s.tkm) / 1000;          /* ช่วงไฟขาด [с] */
      var t0 = -0.05, t1 = 0.45;                 /* หน้าต่างเวลา [с] */
      var tau = t0 + ((t / 3.2) % 1) * (t1 - t0);

      var F1 = eoFxSz(w, 10), F2 = eoFxSz(w, 8.6);
      var dh = Math.min(h * 0.42, 118);          /* ส่วนผังวงจร */
      var bh = Math.min(20, dh * 0.20);
      var bw = Math.min(96, (w - 30) / 2.4);
      var cx = w / 2;
      var x1 = cx - bw - 10, x2 = cx + 10;

      /* สถานะปัจจุบันของผังวงจร */
      var st;                                     /* 0 = จาก Ввод 1 · 1 = ขาด · 2 = จาก Ввод 2 */
      if (tau < 0) st = 0;
      else if (tau < tp || !s.avr) st = 1;
      else st = 2;

      var c1 = tau < 0 ? ok : bad;

      eoFxBox(ctx, x1, 6, bw, bh, pan, c1, 1.6, tau < 0 ? null : [4, 3]);
      eoFxTxt(ctx, "Ввод 1", x1 + bw / 2, 6 + bh / 2, F1, tau < 0 ? ink : bad, "center", "middle", true);
      eoFxBox(ctx, x2, 6, bw, bh, pan, st === 2 ? ok : lin, 1.4);
      eoFxTxt(ctx, "Ввод 2", x2 + bw / 2, 6 + bh / 2, F1, st === 2 ? ink : ink3, "center", "middle", true);
      eoFxTxt(ctx, "~380 В · 50 Гц", cx, 6 + bh + 7, F2, ink3, "center", "middle");

      /* คอนแทกเตอร์ КМ */
      var yk = 6 + bh + 18, kh = Math.min(18, bh);
      eoFxArrowDown(ctx, x1 + bw / 2, 6 + bh, yk, c1, tau < 0 ? 1.7 : 1.1, tau < 0 ? null : [3, 3]);
      eoFxArrowDown(ctx, x2 + bw / 2, 6 + bh, yk, st === 2 ? ok : lin, st === 2 ? 1.7 : 1.1, st === 2 ? null : [3, 3]);
      eoFxBox(ctx, x1 + bw / 2 - 22, yk, 44, kh, pan, tau < 0 ? ok : lin, 1.2);
      eoFxTxt(ctx, "КМ1", x1 + bw / 2, yk + kh / 2, F2, tau < 0 ? ink : ink3, "center", "middle");
      eoFxBox(ctx, x2 + bw / 2 - 22, yk, 44, kh, pan, st === 2 ? ok : lin, 1.2);
      eoFxTxt(ctx, "КМ2", x2 + bw / 2, yk + kh / 2, F2, st === 2 ? ink : ink3, "center", "middle");

      /* บัสโหลด */
      var yb = yk + kh + 16;
      var busCol = st === 1 ? bad : ok;
      eoFxArrowDown(ctx, x1 + bw / 2, yk + kh, yb, tau < 0 ? ok : lin, tau < 0 ? 1.7 : 1, tau < 0 ? null : [3, 3]);
      eoFxArrowDown(ctx, x2 + bw / 2, yk + kh, yb, st === 2 ? ok : lin, st === 2 ? 1.7 : 1, st === 2 ? null : [3, 3]);
      eoFxSeg(ctx, [[x1 + bw / 2, yb], [x2 + bw / 2, yb]], busCol, 2.2);
      eoFxTxt(ctx, st === 1 ? "шина обесточена" : "шина под напряжением", cx, yb + 9, F2, busCol, "center", "middle", true);
      eoFxTxt(ctx, "к потребителям категории 1", cx, yb + 9 + F2 * 1.5, F2, ink3, "center", "middle");

      /* --- ออสซิลโลแกรมแรงดันที่โหลด --- */
      var py = dh + 12, ph = h - py - 34;
      var Um = 1.0;
      var p = new Plot(ctx, 34, py, w - 46, ph, t0 * 1000, t1 * 1000, -1.25, 1.25);
      p.frame(ticks(-50, 450, 5), eoFxTicksN(-1, 1, 4), "t, мс","u / U_m");

      var pts = [], N = 700;
      for (var i = 0; i <= N; i++) {
        var x = t0 + (t1 - t0) * i / N;
        var live = x < 0 || (s.avr && x >= tp);
        pts.push([x * 1000, live ? Um * Math.sin(2 * Math.PI * 50 * x) : 0]);
      }
      /* แถบช่วงไฟขาด */
      ctx.save();
      ctx.fillStyle = "rgba(190,70,60,0.16)";
      var gx0 = p.X(0), gx1 = p.X(s.avr ? tp * 1000 : t1 * 1000);
      ctx.fillRect(gx0, p.y, gx1 - gx0, p.h);
      ctx.restore();
      p.clip(function () { p.line(pts, acc, 1.5); });

      /* เคอร์เซอร์เวลา */
      var cxp = p.X(tau * 1000);
      eoFxSeg(ctx, [[cxp, p.y], [cxp, p.y + p.h]], ink3, 1, [3, 3]);

      eoFxTxt(ctx, s.avr ? "перерыв " + (tp * 1000).toFixed(0) + " мс" : "АВР отключено — перерыв не ограничен",
        (gx0 + Math.min(gx1, p.x + p.w)) / 2, p.y + 8, F2, bad, "center", "middle", true);

      var okc = tp <= 1.5;
      readout.innerHTML =
        't<sub>перерыва</sub> = t<sub>обн</sub> + t<sub>КМ</sub> = <b class="' + (s.avr && okc ? "good" : "bad") + '">' +
        (s.avr ? (tp * 1000).toFixed(0) + " мс" : "∞") + '</b>' +
        '<span>เกณฑ์หมวด 1: <b>1,5 с = 1500 мс</b></span>' +
        '<span>' + (s.avr ? (okc ? "น้อยกว่าเกณฑ์ " + eoFxNum(1.5 / tp, 0) + " เท่า" : "เกินเกณฑ์") : "ไม่มีการสลับ ผู้ใช้ดับจนกว่าจะแก้ด้วยมือ") + '</span>' +
        '<span>С-13242 สลับด้วย <b>КМ</b> จึงมีช่วงขาด · ПСС ของ «Зенит» ขนานผ่าน <b>БРД</b> จึงไม่มีช่วงขาดเลย</span>' +
        '<span>ค่าเวลาสองตัวเป็นสไลเดอร์ของ <b>ผู้เรียบเรียง</b> — สไลด์ 27 ไม่ได้ให้ตัวเลข</span>';
    }
  });
}

/* =========================================================================
   4. eoEMPchar — คุณลักษณะภายนอกและคุณลักษณะปรับค่าของ СГ ใน ЭМП + f = p·n/60
   สูตร/แหล่ง: Л17 сл. 18 (นิยามสองกราฟ) · сл. 21–22 (ตัวเลขจริง) · Формулы ข้อ 1–3, 8
     · внешняя:      U = f(I_н) при I_В = const, n₂ = const, cos φ₁ = const
     · регулировочная: I_В = f(I_н) при U = const, n₂ = const, cos φ₁ = const
     · ΔU при активной нагрузке = U_н − U(I_н)
     · f = p·n / 60
     แบบจำลองเชิงตัวเลข (ผู้เรียบเรียงเสริม — สไลด์ให้เฉพาะรูปกราฟ):
       U = E₀ − I_н·(R_а·cos φ + X_d·sin φ)   [ค่าสัมพัทธ์ ต่อ U_н]
       E₀ = U_н · e(I_В/I_В0) · (n/n_ном) ,  e(x) = 1,35x/(0,35 + x)  (เส้นอิ่มตัวของแกนเหล็ก)
     ค่าฐาน U_н = 230 В และ n_ном = 2925 об/мин เลือกให้ตรงกับ ПСЧ-30 (сл. 21)
   ========================================================================= */
function eoEMPchar(host) {
  var UN = 230, NN = 2925, IB0 = 2.5;
  var esat = function (x) { return 1.35 * x / (0.35 + x); };
  var einv = function (e) { return e >= 1.349 ? Infinity : 0.35 * e / (1.35 - e); };

  buildDemo(host, {
    label: "Лекция 17 · сл. 18 · สูตร f = p·n/60 (сл. 21–22)",
    title: "เลื่อน cos φ ของโหลด กระแสกระตุ้น และรอบหมุน — ดูคุณลักษณะภายนอกและความถี่ที่ได้",
    ratio: 0.62,
    legend: '<span><i style="background:var(--accent)"></i>โหลดตามสไลเดอร์</span>' +
      '<span><i style="background:var(--ok)"></i>ёмкостная</span>' +
      '<span><i style="background:var(--ink-3)"></i>активная</span>' +
      '<span><i style="background:var(--crit)"></i>индуктивная</span>',
    controls: [
      { id: "phi", label: "φ ของโหลด, град (− = ёмкостная)", min: -60, max: 60, step: 1, value: 37, fmt: function (v) { return v.toFixed(0) + "° · cos φ = " + eoFxNum(Math.cos(v * Math.PI / 180), 2); } },
      { id: "ib", label: "I_В / I_В0", min: 0.3, max: 2, step: 0.02, value: 1, fmt: function (v) { return eoFxNum(v, 2); } },
      { id: "n", label: "n₂, об/мин", min: 2500, max: 3200, step: 5, value: 2925, fmt: function (v) { return v.toFixed(0); } },
      { id: "p", label: "p — число пар полюсов", min: 1, max: 14, step: 1, value: 8, fmt: function (v) { return v.toFixed(0); } },
      { id: "xd", label: "X_d (о.е.)", min: 0.1, max: 0.8, step: 0.01, value: 0.4, fmt: function (v) { return eoFxNum(v, 2); } }
    ],
    buttons: [
      { id: "reg", label: "регулировочная I_В(I)", toggle: true, value: false }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), ok = CV("--ok"), bad = CV("--crit"), ink3 = CV("--ink-3"), ink = CV("--ink");
      var Ra = 0.05, Xd = s.xd, kn = s.n / NN, ib = s.ib;
      var F2 = eoFxSz(w, 8.8);
      var E0 = UN * esat(ib) * kn;
      var f = s.p * s.n / 60;

      var drop = function (i, phi) { return i * (Ra * Math.cos(phi) + Xd * Math.sin(phi)) * UN; };
      var Uof = function (i, phi) { return E0 - drop(i, phi); };
      var curve = function (phi) {
        var a = [];
        for (var i = 0; i <= 70; i++) { var x = i / 50; a.push([x, Uof(x, phi)]); }
        return a;
      };
      /* คุณลักษณะปรับค่า: หา I_В ที่ทำให้ U = U_н ทุกค่ากระแสโหลด */
      var creg = function (phi) {
        var a = [];
        for (var i = 0; i <= 70; i++) {
          var x = i / 50;
          var e = (UN + drop(x, phi)) / (UN * kn);
          var xb = einv(e);
          a.push([x, isFinite(xb) ? xb * IB0 : NaN]);
        }
        return a;
      };

      var ph = s.phi * Math.PI / 180;
      var p;
      if (!s.reg) {
        /* ย่านแกนอิงข้อมูลจริงของทั้งสามเส้น + เผื่อ 8 % (เดิมเริ่มที่ 0 ทำให้ครึ่งล่างว่าง) */
        var yLo = Infinity, yHi = -Infinity, ci, cj, cset = [curve(-36.87 * Math.PI / 180), curve(0), curve(36.87 * Math.PI / 180), curve(ph)];
        for (ci = 0; ci < cset.length; ci++) for (cj = 0; cj < cset[ci].length; cj++) {
          var yv = cset[ci][cj][1];
          if (isFinite(yv)) { if (yv < yLo) yLo = yv; if (yv > yHi) yHi = yv; }
        }
        if (!isFinite(yLo)) { yLo = 0; yHi = 1.5 * UN; }
        yHi = Math.max(yHi, UN * 1.02); yLo = Math.min(yLo, UN * 0.98);
        var pad = Math.max(1, (yHi - yLo) * 0.08);
        var yA = Math.max(0, yLo - pad), yB = yHi + pad;
        p = new Plot(ctx, 42, 18, w - 56, h - 50, 0, 1.4, yA, yB);
        p.frame(ticks(0, 1.4, 7), eoFxTicksN(yA, yB, 5), "I / I_н","U, В");
        p.clip(function () {
          p.line(curve(-36.87 * Math.PI / 180), ok, 1.3, [5, 3]);
          p.line(curve(0), ink3, 1.3, [5, 3]);
          p.line(curve(36.87 * Math.PI / 180), bad, 1.3, [5, 3]);
          p.line(curve(ph), acc, 2.2);
          p.line([[1, yA], [1, yB]], ink3, 1, [2, 3]);
          p.line([[0, UN], [1.4, UN]], ink3, 1, [2, 3]);
        });
        /* วงเล็บ ΔU при активной нагрузке */
        var ua0 = Uof(0, 0), ua1 = Uof(1, 0);
        ctx.save();
        eoFxSeg(ctx, [[p.X(1.06), p.Y(ua0)], [p.X(1.12), p.Y(ua0)], [p.X(1.12), p.Y(ua1)], [p.X(1.06), p.Y(ua1)]], ink3, 1);
        ctx.restore();
        eoFxTxt(ctx, "ΔU", p.X(1.14), (p.Y(ua0) + p.Y(ua1)) / 2, F2, ink3, "left", "middle");
        eoFxTxt(ctx, "внешние характеристики (а)", p.x + 6, p.y + 8, F2, ink3, "left", "middle");
        eoFxTxt(ctx, "U_н = 230 В", p.X(0.02),
          p.Y(UN) - 6 < p.y + F2 * 2.6 ? p.Y(UN) + 8 : p.Y(UN) - 6, F2, ink3, "left", "middle");
      } else {
        var ymx = 2.2 * IB0;
        p = new Plot(ctx, 42, 18, w - 56, h - 50, 0, 1.4, 0, ymx);
        p.frame(ticks(0, 1.4, 7), eoFxTicksN(0, ymx, 5), "I / I_н","I_В, А");
        p.clip(function () {
          p.line(creg(-36.87 * Math.PI / 180), ok, 1.3, [5, 3]);
          p.line(creg(0), ink3, 1.3, [5, 3]);
          p.line(creg(36.87 * Math.PI / 180), bad, 1.3, [5, 3]);
          p.line(creg(ph), acc, 2.2);
          p.line([[1, 0], [1, ymx]], ink3, 1, [2, 3]);
          p.line([[0, IB0], [1.4, IB0]], ink3, 1, [2, 3]);
        });
        eoFxTxt(ctx, "регулировочные характеристики (б) · U = 230 В = const", p.x + 6, p.y + 8, F2, ink3, "left", "middle");
        eoFxTxt(ctx, "I_В0", p.X(0.02), p.Y(IB0) - 6, F2, ink3, "left", "middle");
      }

      var uH = Uof(1, ph), du = Uof(0, 0) - Uof(1, 0);
      var ebreg = einv((UN + drop(1, ph)) / (UN * kn));
      var kind = s.phi > 3 ? "индуктивная" : (s.phi < -3 ? "ёмкостная" : "активная");

      readout.innerHTML =
        'f = p·n/60 = <b>' + eoFxNum(f, 1) + ' Гц</b>' +
        '<span>โหลด: <b>' + kind + '</b> · cos φ = <b>' + eoFxNum(Math.cos(ph), 2) + '</b></span>' +
        '<span>U ที่ I_н = <b class="' + (Math.abs(uH - UN) < 0.1 * UN ? "good" : "bad") + '">' + eoFxNum(uH, 0) + ' В</b></span>' +
        '<span>ΔU при активной нагрузке = <b>' + eoFxNum(du, 1) + ' В</b> (' + eoFxNum(du / UN * 100, 1) + ' %)</span>' +
        '<span>I_В ที่ต้องใช้เพื่อคง U = U_н: <b class="' + (isFinite(ebreg) ? "good" : "bad") + '">' +
        (isFinite(ebreg) ? eoFxNum(ebreg * IB0, 2) + " А" : "เกินขีดกระตุ้น") + '</b></span>' +
        '<span>p = 8 กับ n₂ = 2925 об/мин ให้ 390 Гц พอดี — ตรงกับ ВПЛ-30 (сл. 22)</span>';
    }
  });
}

/* =========================================================================
   5. eoPSCH — เทียบพารามิเตอร์ ЭМП รุ่นจริงจากตาราง Л17 сл. 21–22
   สูตร/แหล่ง: Л17 сл. 21 (АЛА-3,5 · ПСЧ-30(15;50)) · сл. 22 (ВПЛ-30 · МГ-6(16))
               Формулы ข้อ 8: f = p·n/60 · n = n₁·(1 − s) เมื่อคิดสลิปของ АД
     ค่าจริงในตาราง: АЛА-3,5 → 427 Гц · ПСЧ-30 → 388…392 Гц · ВПЛ-30 → 390 Гц
                     МГ-6 (16) → ไม่มีความถี่ (ให้ไฟตรง 26…36 В)
     ไม่มีรุ่นใดให้ 400 Гц พอดี — เดโมนี้ให้ผู้เรียนหาค่า p กับ s ที่อธิบายตัวเลขจริงได้
   ========================================================================= */
function eoPSCH(host) {
  var M = [
    {
      n: "АЛА-3,5", uin: "220/380 В", uout: "115 (230) В", f: 427, fl: 427, fh: 427, n1: 3000,
      gen: "Индукторный генератор однофазный", pusk: "прямой", reg: "Регулятор U", dc: false
    },
    {
      n: "ПСЧ-30 (15; 50)", uin: "220/380 В", uout: "230 В", f: 390, fl: 388, fh: 392, n1: 3000,
      gen: "Индукторный генератор трехфазный", pusk: "двухступенчатый", reg: "Регулятор U · фазовое компаундирование + корректор", dc: false
    },
    {
      n: "ВПЛ-30 (8Н6204)", uin: "380 В", uout: "220/380 В", f: 390, fl: 390, fh: 390, n1: 3000,
      gen: "СГ с когтеобразным ротором + возбудитель ГПТ", pusk: "двухступенчатый", reg: "Регулятор U", dc: false
    },
    {
      n: "МГ-6 (16)", uin: "220/380 В", uout: "26…36 В =", f: 0, fl: 0, fh: 0, n1: 1500,
      gen: "ГПТ с параллельным возбуждением", pusk: "прямой", reg: "Регулятор U", dc: true
    }
  ];

  buildDemo(host, {
    label: "Лекция 17 · сл. 21–22",
    title: "เทียบความถี่ขาออกของ ЭМП สี่รุ่นจริง กับค่ามาตรฐาน 400 Гц และหาว่า p กับสลิปอธิบายตัวเลขได้อย่างไร",
    ratio: 0.68,
    legend: '<span><i style="background:var(--accent)"></i>ค่าจริงในตาราง</span>' +
      '<span><i style="background:var(--accent-2)"></i>f ที่คำนวณจาก p·n/60</span>' +
      '<span><i style="background:var(--crit)"></i>ค่ามาตรฐาน 400 Гц</span>',
    controls: [
      { id: "m", label: "รุ่น", min: 0, max: 3, step: 1, value: 1, fmt: function (v) { return M[Math.round(v)].n; } },
      { id: "p", label: "p — число пар полюсов генератора", min: 4, max: 14, step: 1, value: 8, fmt: function (v) { return v.toFixed(0); } },
      { id: "s", label: "скольжение АД, %", min: 0, max: 6, step: 0.1, value: 2.5, fmt: function (v) { return eoFxNum(v, 1); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), bad = CV("--crit"),
        ink = CV("--ink"), ink3 = CV("--ink-3"), pan = CV("--panel-2"), grid = CV("--grid");
      var mi = Math.round(s.m), m = M[mi];
      var nreal = m.n1 * (1 - s.s / 100);
      var fcalc = s.p * nreal / 60;

      var F1 = eoFxSz(w, 9.6), F2 = eoFxSz(w, 8.4), F3 = eoFxSz(w, 8);
      var top = 12;
      var lhTxt = Math.max(11, F1 * 1.45);
      /* พื้นที่กราฟ = ส่วนที่เหลือหลังหักบล็อกพารามิเตอร์ 4 บรรทัด — เพื่อไม่ให้เหลือที่ว่างท้ายภาพ */
      var chartH = Math.max(90, h - top - 24 - 4 * lhTxt - 12);
      var x0 = 34, x1 = w - 8;
      var fmax = 460;
      var Y = function (v) { return top + chartH - v / fmax * chartH; };

      /* กริดแนวนอน */
      [0, 100, 200, 300, 400].forEach(function (v) {
        var py = Math.round(Y(v)) + 0.5;
        eoFxSeg(ctx, [[x0, py], [x1, py]], grid, 1);
        eoFxMono(ctx, String(v), x0 - 5, py, F3, ink3, "right", "middle");
      });
      eoFxTxt(ctx, "f, Гц", x0 - 5, top - 4, F3, ink3, "right", "middle");

      /* เส้นมาตรฐาน 400 Гц */
      var y400 = Math.round(Y(400)) + 0.5;
      eoFxSeg(ctx, [[x0, y400], [x1, y400]], bad, 1.4, [5, 3]);
      eoFxFit(ctx, "400 Гц — номинал", x1 - 2, y400 - 7, F3, bad, "right", "middle", true, (x1 - x0) * 0.55);

      /* แท่งของแต่ละรุ่น */
      var gap = 8, bw = (x1 - x0 - 3 * gap) / 4;
      M.forEach(function (mm, i) {
        var bx = x0 + i * (bw + gap);
        var sel = i === mi;
        if (mm.dc) {
          eoFxBox(ctx, bx, Y(120), bw, top + chartH - Y(120), pan, sel ? acc : ink3, sel ? 2 : 1, [4, 3]);
          eoFxTxt(ctx, "=", bx + bw / 2, Y(60), eoFxSz(w, 15), ink3, "center", "middle", true);
          eoFxFit(ctx, "26…36 В", bx + bw / 2, Y(120) + F3 * 1.1, F3, ink3, "center", "middle", false, bw - 4);
        } else {
          eoFxBox(ctx, bx, Y(mm.f), bw, top + chartH - Y(mm.f),
            sel ? "rgba(90,140,200,0.22)" : pan, sel ? acc : ink3, sel ? 2 : 1);
          if (mm.fh > mm.fl) {
            ctx.save();
            ctx.fillStyle = "rgba(190,70,60,0.25)";
            ctx.fillRect(bx, Y(mm.fh), bw, Y(mm.fl) - Y(mm.fh));
            ctx.restore();
          }
          var ftxt = mm.fh > mm.fl ? mm.fl + "…" + mm.fh : String(mm.f);
          /* ป้ายอยู่ "ในแท่ง" — ไม่ทับเส้นประ 400 Гц และไม่หลุดขอบบนของผ้าใบ */
          var lyA = Y(mm.f) + F2 * 1.1, lyB = lyA + F2 * 1.55;
          eoFxFit(ctx, ftxt + " Гц", bx + bw / 2, lyA, F2, sel ? ink : ink3, "center", "middle", true, bw - 4);
          eoFxFit(ctx, eoFxNum((mm.f - 400) / 400 * 100, 1) + " %", bx + bw / 2, lyB, F3,
            Math.abs(mm.f - 400) < 1 ? ink3 : bad, "center", "middle", false, bw - 4);
        }
        eoFxFit(ctx, mm.n.split(" ")[0], bx + bw / 2, top + chartH + 8, F2, sel ? ink : ink3, "center", "middle", sel, bw - 2);
      });

      /* เส้นค่าที่คำนวณได้จาก p และสลิป */
      if (fcalc <= fmax) {
        var yc = Math.round(Y(fcalc)) + 0.5;
        eoFxSeg(ctx, [[x0, yc], [x1, yc]], acc2, 1.8);
        eoFxFit(ctx, "p·n/60 = " + eoFxNum(fcalc, 1) + " Гц", x1 - 2,
          Math.min(top + chartH - F3, Math.max(top + F3 * 2.4, yc + F3 * 1.2)), F3, acc2, "right", "middle", true, (x1 - x0) * 0.5);
      }

      /* แถบพารามิเตอร์ของรุ่นที่เลือก */
      var ty = top + chartH + 22;
      var lh = lhTxt, tmax = w - x0 - 8;
      eoFxFit(ctx, m.n, x0, ty, F1, ink, "left", "middle", true, tmax);
      eoFxFit(ctx, "вход: 3-ф АД с к.з. ротором · " + m.uin + " · 50 Гц · n₁ = " + m.n1 + " об/мин · пуск " + m.pusk,
        x0, ty + lh, F3, ink3, "left", "middle", false, tmax);
      eoFxFit(ctx, "выход: " + m.gen, x0, ty + 2 * lh, F3, ink3, "left", "middle", false, tmax);
      eoFxFit(ctx, "U = " + m.uout + (m.dc ? "" : " · f = " + (m.fh > m.fl ? m.fl + "…" + m.fh : m.f) + " Гц") + " · " + m.reg,
        x0, ty + 3 * lh, F3, ink3, "left", "middle", false, tmax);

      var dev = m.dc ? null : (m.f - 400) / 400 * 100;
      var pfit = m.dc ? null : m.f * 60 / nreal;

      readout.innerHTML =
        'f = p·n/60 = ' + s.p + '·' + eoFxNum(nreal, 0) + '/60 = <b>' + eoFxNum(fcalc, 1) + ' Гц</b>' +
        '<span>n = n₁(1 − s) = ' + m.n1 + '·(1 − ' + eoFxNum(s.s / 100, 3) + ') = <b>' + eoFxNum(nreal, 0) + ' об/мин</b></span>' +
        (m.dc
          ? '<span><b>МГ-6 (16)</b> ให้ไฟตรง 26…36 В จึงไม่มีความถี่ขาออก — เป็นที่มาของ «−30 В» ในนิยาม СНЭСТ</span>'
          : '<span>ค่าในตาราง <b>' + (m.fh > m.fl ? m.fl + "…" + m.fh : m.f) + ' Гц</b> ต่างจาก 400 Гц <b class="bad">' + eoFxNum(dev, 1) + ' %</b></span>' +
          '<span>p ที่ทำให้ได้ค่าตามตาราง = <b>' + eoFxNum(pfit, 2) + '</b> — ต้องเป็นจำนวนเต็ม จึงเป็นเหตุผลที่ได้ไม่ถึง 400 Гц พอดี</span>') +
        '<span><b>ไม่มีรุ่นใดในตารางให้ 400 Гц พอดี</b> — «400 Гц» เป็นค่ามาตรฐาน ส่วนตัวเลขในตารางคือค่าจริง</span>' +
        '<span><b>หมายเหตุต้นฉบับ:</b> ตาราง сл. 21 ระบุเครื่องกำเนิดของ ПСЧ-30 ว่า «индукторный генератор» ' +
        'แต่ Конспект RU-TH เขียนว่า «синхронный генератор» — ตอบข้อสอบตามสไลด์ คือ <b>индукторный</b> ' +
        '(ทั้งขดกระตุ้นและขดอาร์เมเจอร์อยู่บนสเตเตอร์ โรเตอร์เป็นเหล็กมีฟัน จึงทนรอบสูงและเหมาะกับความถี่สูง)</span>';
    }
  });
}

/* =========================================================================
   6. eoTPS — ตัวแปลงทิริสเตอร์ภาคพื้น: มุมจุดชนวน α → U_вых พร้อมลูปรักษาระดับ
   สูตร/แหล่ง: Л18 сл. 17 (ประเภทที่ 2 — воздействие на параметры блока вентилей)
               сл. 19 (силовая цепь на тиристорах VS1…VS6 · ФСУ1–ФСУ3 · ตัวอย่าง α = 30°)
               сл. 20 (ทางออกที่ต้องรักษาระดับ 28,5 В) · Формулы ข้อ 5
     · u_d(θ) = √2·U_л2·cos(θ − 60°k − 30°) สำหรับ θ ∈ [60°k + α, 60°(k+1) + α]
     · U_d = U_d0·cos α ,  U_d0 = 1,35·U_л2   (มอสต์สามเฟส Ларионова)
     · K_п = ΔU/(2U₀)   (นิยามริปเปิลของ Тема 2)
     · แรงดันตกภายใน: ΔU_в = 1,4 В (วาล์วสองตัว) และ I_н·R_вн — ผู้เรียบเรียงเสริม
     · อัตราส่วนหม้อแปลง Тр เลือกเป็น k = 12,8 เพื่อให้ที่สาย 380 В ได้ U_d0 ≈ 40 В
       ซึ่งพอดีสำหรับรักษาระดับ 28,5 В — ผู้เรียบเรียงเสริม (สไลด์ไม่ได้ให้ k)
   ========================================================================= */
function eoTPS(host) {
  var KTR = 12.8, UT = 28.5, DUV = 1.4, RVN = 0.01;

  buildDemo(host, {
    label: "Лекция 18 · сл. 17, 19–20",
    title: "เลื่อนมุมจุดชนวน α แล้วดูแรงดันขาออก — หรือเปิดลูปรักษาระดับให้ระบบหา α เองที่ 28,5 В",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>u_d(ωt)</span>' +
      '<span><i style="background:var(--line-2)"></i>линейные напряжения</span>' +
      '<span><i style="background:var(--crit)"></i>ส่วนที่ถูกตัดออกเพราะ α</span>',
    controls: [
      { id: "a", label: "α, эл. град", min: 0, max: 120, step: 1, value: 30, fmt: function (v) { return v.toFixed(0) + "°"; } },
      { id: "ul", label: "U_л сети, В", min: 340, max: 420, step: 2, value: 380, fmt: function (v) { return v.toFixed(0); } },
      { id: "in", label: "I_н, А", min: 0, max: 120, step: 2, value: 60, fmt: function (v) { return v.toFixed(0); } }
    ],
    buttons: [
      { id: "stab", label: "стабилизация 28,5 В", toggle: true, value: true }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), ink3 = CV("--ink-3"), lin = CV("--line-2"), ok = CV("--ok"), bad = CV("--crit");
      var Ul2 = s.ul / KTR;
      var Ud0 = 1.35 * Ul2;
      var need = UT + DUV + s.in * RVN;
      var lim = false, alpha;
      if (s.stab) {
        var ca = need / Ud0;
        if (ca > 1) { ca = 1; lim = true; }
        if (ca < -1) { ca = -1; lim = true; }
        alpha = Math.acos(ca) * 180 / Math.PI;
      } else alpha = s.a;

      var Um = Math.SQRT2 * Ul2;
      var ud = function (th) {
        var k = Math.floor((th - alpha) / 60);
        var ph = th - 60 * k - 30;
        return Um * Math.cos(ph * Math.PI / 180);
      };
      var pts = [], env = [], N = 720, mn = 1e9, mx = -1e9, sum = 0, cnt = 0;
      for (var i = 0; i <= N; i++) {
        var th = 360 * i / N;
        var v = ud(th), e = Um * Math.cos((((th + 30) % 60) - 30) * Math.PI / 180);
        pts.push([th, v]); env.push([th, e, v]);
        if (th >= 60) { if (v < mn) mn = v; if (v > mx) mx = v; sum += v; cnt++; }
      }
      var Ud = Ud0 * Math.cos(alpha * Math.PI / 180);
      var Uout = Math.max(0, Ud - DUV - s.in * RVN);
      var Kp = Ud > 0.5 ? (mx - mn) / (2 * Ud) : 0;

      /* ย่านแกนอิงข้อมูลจริง + ระยะเผื่อ 8 % (เดิม −0,15·U_m … U_m ทำให้ครึ่งล่างของกรอบว่างเปล่า) */
      var ySpan = Math.max(Um - mn, 1e-3);
      var ymin = mn - 0.08 * ySpan, ymax = Um + 0.08 * ySpan;
      var p = new Plot(ctx, 40, 18, w - 54, h - 50, 0, 360, ymin, ymax);
      p.frame(ticks(0, 360, 6), eoFxTicksN(Math.round(ymin), Math.round(ymax), 4), "ωt, град","u, В");
      p.clip(function () {
        for (var k = -1; k < 7; k++) {
          var seg = [];
          for (var j = 0; j <= 60; j++) {
            var th2 = 60 * k + j;
            seg.push([th2, Um * Math.cos((th2 - 60 * k - 30) * Math.PI / 180)]);
          }
          p.line(seg, lin, 1);
        }
        p.band(env, "rgba(206,86,76,0.20)");
        p.line(pts, acc, 2);
        p.line([[0, Ud], [360, Ud]], ok, 1.3, [5, 3]);
        p.line([[0, 0], [360, 0]], ink3, 1);
      });
      var F2 = eoFxSz(w, 8.6);
      eoFxTxt(ctx, "U_d = " + eoFxNum(Ud, 1) + " В", p.x + p.w - 4, p.Y(Ud) - 7, F2, ok, "right", "middle", true);
      eoFxTxt(ctx, "α = " + eoFxNum(alpha, 1) + "°" + (s.stab ? " (авто)" : ""), p.x + 5, p.y + 8, F2, acc, "left", "middle", true);

      readout.innerHTML =
        'U<sub>d</sub> = 1,35·U<sub>л2</sub>·cos α = <b>' + eoFxNum(Ud, 1) + ' В</b>' +
        '<span>U на выходе (после вентилей) = <b class="' + (Math.abs(Uout - UT) < 0.4 ? "good" : "bad") + '">' + eoFxNum(Uout, 1) + ' В</b></span>' +
        '<span>α = <b>' + eoFxNum(alpha, 1) + '°</b>' + (s.stab ? (lim ? ' — <b class="bad">предел регулирования</b>' : " — ระบบหาเอง") : " — ตั้งด้วยมือ") + '</span>' +
        '<span>U<sub>л2</sub> = U<sub>л</sub>/k = <b>' + eoFxNum(Ul2, 1) + ' В</b> · U<sub>d0</sub> = <b>' + eoFxNum(Ud0, 1) + ' В</b></span>' +
        '<span>K<sub>п</sub> = ΔU/(2U₀) = <b class="' + (Kp < 0.1 ? "good" : "bad") + '">' + eoFxNum(Kp * 100, 1) + ' %</b> — ยิ่ง α มาก ริปเปิลยิ่งลึก</span>' +
        '<span>สไลด์ 19 ยกตัวอย่าง <b>α = 30°</b> · ลำดับจุดชนวน VS1–VS6 ห่างกัน 60°</span>' +
        '<span>ค่า k = 12,8 · ΔU_в = 1,4 В · R_вн = 0,01 Ом เป็นค่าที่ <b>ผู้เรียบเรียง</b> เลือกให้สอดคล้องกับ 28,5 В — สไลด์ไม่ได้ให้</span>';
    }
  });
}

/* =========================================================================
   7. eoDrossel — активный дроссель (МУ) ของ ПСС 5801: เส้นโค้ง L(I_у)
   สูตร/แหล่ง: Л18 сл. 18 «Рис. 3.16. Зависимость индуктивности обмотки от тока управления ПУ»
               Формулы ข้อ 2 และ 7
     · L = f(I_у): ลดลงแบบเอกซ์โพเนนเชียลจาก L_max ที่ I_у = 0 เข้าหา L_min แบบอะซิมโทติก
       แบบจำลอง L(I_у) = L_min + (L_max − L_min)·e^(−I_у/I₀)   (ผู้เรียบเรียงเสริมรูปฟังก์ชัน)
     · X_L = ω·L(I_у), ω = 2πf = 314 рад/с ที่ 50 Гц
     · ตัวแบ่งแรงดันเชิงอิมพีแดนซ์: I_вх = U_вх/√(R_н² + X_L²) · U_вх тр = I_вх·R_н
   ========================================================================= */
function eoDrossel(host) {
  buildDemo(host, {
    label: "Лекция 18 · сл. 18 (Рис. 3.16)",
    title: "เลื่อนกระแสควบคุม I_у แล้วดูความเหนี่ยวนำของขดทำงานตก แรงดันถึงหม้อแปลงจึงเพิ่ม",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>L(I_у) / L_max</span>' +
      '<span><i style="background:var(--accent-2)"></i>U_вх тр / U_вх</span>' +
      '<span><i style="background:var(--ok)"></i>จุดทำงานปัจจุบัน</span>',
    controls: [
      { id: "iu", label: "I_у, А", min: 0, max: 4, step: 0.02, value: 0.8, fmt: function (v) { return eoFxNum(v, 2); } },
      { id: "lmax", label: "L_max, Гн", min: 0.05, max: 0.6, step: 0.01, value: 0.25, fmt: function (v) { return eoFxNum(v, 2); } },
      { id: "i0", label: "I₀ — ток насыщения, А", min: 0.2, max: 2, step: 0.05, value: 0.7, fmt: function (v) { return eoFxNum(v, 2); } },
      { id: "rn", label: "R_н приведённое, Ом", min: 5, max: 80, step: 1, value: 30, fmt: function (v) { return v.toFixed(0); } },
      { id: "uv", label: "U_вх, В", min: 300, max: 420, step: 2, value: 380, fmt: function (v) { return v.toFixed(0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), ok = CV("--ok"), ink3 = CV("--ink-3");
      var W = 2 * Math.PI * 50;
      var Lmin = 0.05 * s.lmax;
      var Lf = function (iu) { return Lmin + (s.lmax - Lmin) * Math.exp(-iu / s.i0); };
      var Uf = function (iu) {
        var xl = W * Lf(iu);
        return s.rn / Math.sqrt(s.rn * s.rn + xl * xl);
      };

      var a = [], b = [];
      for (var i = 0; i <= 120; i++) {
        var iu = 4 * i / 120;
        a.push([iu, Lf(iu) / s.lmax]);
        b.push([iu, Uf(iu)]);
      }
      var p = new Plot(ctx, 40, 18, w - 54, h - 50, 0, 4, 0, 1.05);
      p.frame(ticks(0, 4, 8), eoFxTicksN(0, 1, 5), "I_у, А","о.е.");
      p.clip(function () {
        p.line(a, acc, 2.2);
        p.line(b, acc2, 2.2);
        p.line([[0, Lmin / s.lmax], [4, Lmin / s.lmax]], ink3, 1, [4, 3]);
      });
      var F2 = eoFxSz(w, 8.6);
      eoFxTxt(ctx, "L_min", p.X(3.95), p.Y(Lmin / s.lmax) - 7, F2, ink3, "right", "middle");
      eoFxTxt(ctx, "L_max", p.X(0.06), p.Y(1) - 7, F2, ink3, "left", "middle");

      var L = Lf(s.iu), XL = W * L, u = Uf(s.iu);
      var Iin = s.uv / Math.sqrt(s.rn * s.rn + XL * XL);
      ctx.save();
      ctx.fillStyle = ok;
      ctx.beginPath(); ctx.arc(p.X(s.iu), p.Y(L / s.lmax), 4, 0, 7); ctx.fill();
      ctx.beginPath(); ctx.arc(p.X(s.iu), p.Y(u), 4, 0, 7); ctx.fill();
      ctx.restore();
      eoFxSeg(ctx, [[p.X(s.iu), p.y], [p.X(s.iu), p.y + p.h]], ok, 1, [3, 3]);

      readout.innerHTML =
        'L(I<sub>у</sub>) = <b>' + eoFxNum(L * 1000, 1) + ' мГн</b>' +
        '<span>X<sub>L</sub> = ωL = <b>' + eoFxNum(XL, 1) + ' Ом</b> (ω = 314 рад/с)</span>' +
        '<span>U<sub>вх тр</sub> = <b>' + eoFxNum(u * s.uv, 1) + ' В</b> (' + eoFxNum(u * 100, 1) + ' % ของ U<sub>вх</sub>)</span>' +
        '<span>แรงดันตกคร่อม МУ = <b class="' + ((1 - u) * 100 < 10 ? "good" : "bad") + '">' + eoFxNum((1 - u) * 100, 1) + ' %</b> — ในโหมดอิ่มตัว МУ ต้องกินแรงดันไม่เกิน 10 % จึงจะถือว่า «เปิดเต็ม»</span>' +
        '<span>I<sub>вх</sub> = <b>' + eoFxNum(Iin, 2) + ' А</b></span>' +
        '<span>วงป้อนกลับ: U<sub>вых</sub> สูงเกิน → ИУ ตรวจจับ → ПУ เพิ่ม I<sub>у</sub> → แกนอิ่มตัว → ' +
        'L และ X<sub>L</sub> ลด → แรงดันตกคร่อม МУ ลด → U<sub>вх тр</sub> เพิ่ม</span>' +
        '<span>สไลด์ให้เฉพาะรูปเส้นโค้ง Рис. 3.16 — รูปฟังก์ชันเอกซ์โพเนนเชียลกับ L_min = 0,05·L_max ' +
        'เป็นแบบจำลองของ <b>ผู้เรียบเรียง</b></span>';
    }
  });
}

/* =========================================================================
   8. eoCombined — СЭС ผสม СБ + АБ + сеть ของแบบจำลอง СЭС เคลื่อนที่
   สูตร/แหล่ง: Л18 сл. 34–37 · Формулы ข้อ 8 และ 9
     · P = U·I  (ใช้ตรวจตาราง сл. 37)
     · P_СБ = P_СБ.ном · E/1000     (สัดส่วนตรงกับความเข้มแสง — ผู้เรียบเรียงเสริม)
     · P_потр = P_н/η               (η = КПД ของ ЗРУ + инвертор)
     · t_раб = C_АБ·U_АБ·k_р·η / P_н  โดย C_АБ = 15 А·ч และ U_АБ ≈ 12 В (สไลด์ให้เฉพาะ 15 А·ч)
     ตาราง сл. 37: (5,0 В · 3,0 А · 15,0 Вт · до 5,0 ч) · (12,0 В · 3,0 А · 36,0 Вт · до 3,5 ч)
                   (220,0 В · 3,0 А · 1000,0 Вт · до 2,0 ч)  ← แถวที่ 3 ไม่ลงตัว 220×3 = 660 ≠ 1000
   ========================================================================= */
function eoCombined(host) {
  var ROW = [
    { u: 5, i: 3, p: 15, t: 5.0 },
    { u: 12, i: 3, p: 36, t: 3.5 },
    { u: 220, i: 3, p: 1000, t: 2.0 }
  ];

  buildDemo(host, {
    label: "Лекция 18 · сл. 34–37",
    title: "เลื่อนความเข้มแสง โหลด และสถานะไฟหลัก แล้วดูสมดุลพลังงานกับเวลาทำงานจากแบตเตอรี่",
    ratio: 0.7,
    legend: '<span><i style="background:var(--ok)"></i>СБ</span>' +
      '<span><i style="background:var(--accent)"></i>сеть 220 В</span>' +
      '<span><i style="background:var(--accent-2)"></i>АБ</span>' +
      '<span><i style="background:var(--crit)"></i>ค่าในตาราง сл. 37</span>',
    controls: [
      { id: "E", label: "E — ความเข้มแสง, Вт/м²", min: 0, max: 1000, step: 10, value: 700, fmt: function (v) { return v.toFixed(0); } },
      { id: "Pn", label: "P_н — กำลังโหลด, Вт", min: 0, max: 1000, step: 5, value: 200, fmt: function (v) { return v.toFixed(0); } },
      { id: "Psb", label: "P_СБ.ном, Вт", min: 50, max: 400, step: 10, value: 200, fmt: function (v) { return v.toFixed(0); } },
      { id: "C", label: "C_АБ, А·ч", min: 5, max: 50, step: 1, value: 15, fmt: function (v) { return v.toFixed(0); } },
      { id: "kr", label: "k_р — глубина разряда", min: 0.3, max: 1, step: 0.05, value: 0.5, fmt: function (v) { return eoFxNum(v, 2); } },
      { id: "eta", label: "η преобразования", min: 0.7, max: 0.95, step: 0.01, value: 0.9, fmt: function (v) { return eoFxNum(v, 2); } }
    ],
    buttons: [
      { id: "net", label: "сеть 220 В есть", toggle: true, value: false }
    ],
    draw: function (ctx, w, h, s, readout) {
      var ok = CV("--ok"), acc = CV("--accent"), acc2 = CV("--accent-2"), bad = CV("--crit"),
        ink = CV("--ink"), ink3 = CV("--ink-3"), pan = CV("--panel-2");
      var UAB = 12;
      var Psb = s.Psb * s.E / 1000;
      var Ptr = s.Pn / s.eta;
      var deficit = Math.max(0, Ptr - Psb);
      var Pnet = s.net ? deficit : 0;
      var Pab = s.net ? 0 : deficit;
      var surplus = Math.max(0, Psb - Ptr);
      var Wab = s.C * UAB * s.kr;
      var trab = Pab > 0.5 ? Wab / Pab : Infinity;

      var F1 = eoFxSz(w, 9.4), F2 = eoFxSz(w, 8.3);
      var top = 10, barH = 15, x0 = 8, x1 = w - 8;
      var scale = Math.max(Ptr, Psb + Pnet + Pab, 1);
      var Wpx = function (v) { return (x1 - x0) * v / (scale * 1.05); };

      /* แถบ «приход» */
      eoFxTxt(ctx, "приход", x0, top - 1, F2, ink3, "left", "bottom");
      var xx = x0;
      [[Psb, ok, "СБ"], [Pnet, acc, "сеть"], [Pab, acc2, "АБ"]].forEach(function (g) {
        if (g[0] <= 0.5) return;
        var bw = Wpx(g[0]);
        ctx.save(); ctx.fillStyle = g[1]; ctx.globalAlpha = 0.75;
        ctx.fillRect(xx, top + 2, bw, barH); ctx.restore();
        if (bw > 30) eoFxTxt(ctx, g[2] + " " + eoFxNum(g[0], 0) + " Вт", xx + bw / 2, top + 2 + barH / 2, F2, CV("--bg"), "center", "middle", true);
        xx += bw;
      });
      /* แถบ «расход» */
      var y2 = top + barH + 10;
      eoFxTxt(ctx, "расход", x0, y2 - 1, F2, ink3, "left", "bottom");
      var bw1 = Wpx(s.Pn), bw2 = Wpx(Ptr - s.Pn);
      ctx.save(); ctx.fillStyle = ink3; ctx.globalAlpha = 0.55;
      ctx.fillRect(x0, y2 + 2, bw1, barH); ctx.restore();
      ctx.save(); ctx.fillStyle = bad; ctx.globalAlpha = 0.35;
      ctx.fillRect(x0 + bw1, y2 + 2, bw2, barH); ctx.restore();
      if (bw1 > 40) eoFxTxt(ctx, "нагрузка " + eoFxNum(s.Pn, 0) + " Вт", x0 + bw1 / 2, y2 + 2 + barH / 2, F2, CV("--bg"), "center", "middle", true);
      eoFxTxt(ctx, "потери " + eoFxNum(Ptr - s.Pn, 0) + " Вт", Math.min(x0 + bw1 + bw2 + 4, x1), y2 + 2 + barH / 2, F2, ink3,
        x0 + bw1 + bw2 + 90 > x1 ? "right" : "left", "middle");

      /* กราฟ t_раб(P_н) */
      var py = y2 + barH + 22;
      var p = new Plot(ctx, 40, py, w - 54, h - py - 32, 0, 1000, 0, 6);
      p.frame(ticks(0, 1000, 5), eoFxTicksN(0, 6, 6), "P_н, Вт","t_раб, ч");
      var cur = [];
      for (var i = 1; i <= 200; i++) {
        var P = 1000 * i / 200;
        cur.push([P, Wab / P]);
      }
      p.clip(function () {
        p.line(cur, acc2, 2.2);
        ROW.forEach(function (r) { p.dots([[r.p, r.t]], bad, 4); });
        if (isFinite(trab)) {
          p.line([[Pab, 0], [Pab, Math.min(6, trab)]], ok, 1.2, [3, 3]);
          p.dots([[Pab, Math.min(6, trab)]], ok, 4.5);
        }
      });
      eoFxTxt(ctx, "t = C·U·k_р·η / P — точки: таблица сл. 37", p.x + 5, p.y + 8, F2, ink3, "left", "middle");
      ROW.forEach(function (r) {
        if (p.X(r.p) < p.x + p.w - 30 && r.t <= 6)
          eoFxTxt(ctx, eoFxNum(r.p, 0) + " Вт", p.X(r.p), p.Y(r.t) - 8, F2, bad, "center", "middle");
      });
      eoFxTxt(ctx, "проверка сл. 37: 220 В × 3,0 А = 660 Вт, в таблице 1000 Вт",
        w / 2, h - 8, eoFxSz(w, 8.4), bad, "center", "middle");

      /* ตรวจตาราง сл. 37 ด้วยตัวเลขของสไลด์เอง: 15 А·ч × 12 В = 180 Вт·ч, โหลด 1000 Вт */
      var tSlide = 15 * UAB / 1000;

      readout.innerHTML =
        'P<sub>СБ</sub> = P<sub>ном</sub>·E/1000 = <b>' + eoFxNum(Psb, 0) + ' Вт</b>' +
        '<span>P<sub>потр</sub> = P<sub>н</sub>/η = <b>' + eoFxNum(Ptr, 0) + ' Вт</b></span>' +
        '<span>' + (s.net
          ? 'จ่ายจากสาย <b>' + eoFxNum(Pnet, 0) + ' Вт</b>' + (surplus > 0.5 ? ' · เหลือชาร์จ АБ <b class="good">' + eoFxNum(surplus, 0) + ' Вт</b>' : '')
          : 'ดึงจาก АБ <b class="' + (Pab > 0.5 ? "bad" : "good") + '">' + eoFxNum(Pab, 0) + ' Вт</b>') + '</span>' +
        '<span>W<sub>АБ</sub> = C·U·k<sub>р</sub> = <b>' + eoFxNum(Wab, 0) + ' Вт·ч</b></span>' +
        '<span>t<sub>раб</sub> = <b class="' + (isFinite(trab) && trab < 1 ? "bad" : "good") + '">' +
        (isFinite(trab) ? eoFxNum(trab, 2) + " ч" : "ไม่จำกัด (แสงและสายจ่ายพอ)") + '</b></span>' +
        '<span><b>หมายเหตุต้นฉบับ (сл. 37):</b> แถวที่ 3 ระบุ 220 В · 3,0 А · 1000 Вт แต่ P = U·I ให้ <b>660 Вт</b> ' +
        'ไม่ใช่ 1000 Вт — ถ้ากำลัง 1000 Вт ถูก กระแสต้องเป็น <b>≈ 4,5 А</b></span>' +
        '<span>คอลัมน์เวลาก็ไม่ลงตัว: ที่ 15 А·ч × 12 В = 180 Вт·ч โหลด 1000 Вт ได้เพียง <b>' + eoFxNum(tSlide, 2) +
        ' ч</b> ไม่ใช่ «до 2,0 ч» — <b>ต้องถามอาจารย์</b></span>';
    }
  });
}

window.EODEMOS = Object.assign(window.EODEMOS || {}, {
  eoGroundNet: eoGroundNet,
  eoCategory: eoCategory,
  eoAVR: eoAVR,
  eoEMPchar: eoEMPchar,
  eoPSCH: eoPSCH,
  eoTPS: eoTPS,
  eoDrossel: eoDrossel,
  eoCombined: eoCombined
});

/* ================= ЭОЛА — กลุ่ม G · ПЗ / ЛР / РГР =================
   งานปฏิบัติ (ПЗ), งานทดลอง (ЛР) และงานคำนวณ (РГР-2)

   แหล่งสูตรของแต่ละเดโม (ระบุไว้เหนือฟังก์ชันทุกตัวอีกครั้ง):
     eoPZsg   — notes/PZ-SG.md         Ф-1…Ф-24 · ตัวอย่างคำนวณข้อ 9.1–9.8
     eoPZgpt  — notes/PZ-GPT.md        Ф-1…Ф-27 · ตัวอย่างคำนวณข้อ 9.1–9.7
     eoPZisn  — notes/PZ-SES-RN-ISN.md Ф-S1…Ф-S11 · Ф-K1…Ф-K12 · ตาราง 5.2 / 5.3
     eoPZnksn — notes/PZ-KO2657.md     สูตร рис. 4.8 (K_п.вх · K_п.вых · K_сгп) · ตาราง 4.2
     eoPZpss  — notes/PZ-PSS5805.md    уставки ТПС 28,5/120 · алгоритм резонансного инвертора
     eoLRdpt  — notes/LR-A.md          ЛР № 1 · Ф1…Ф10
     eoLRtr   — notes/LR-A.md          ЛР № 2 · Ф11…Ф21
     eoLRtad  — notes/LR-A.md          ЛР № 3 · Ф22…Ф34
     eoLRfep  — notes/LR-A.md          ЛР 1.1 · Ф43…Ф49
     eoLRosh  — notes/LR-B.md          § 4 · สูตร (4.3)–(4.6) + ค่าที่คาดหวังของแท่น
     eoLRkza  — notes/LR-B.md          § 5 · สูตร (5.1) t = 0,02·α
     eoRGR    — notes/RGR.md           методика 10 ขั้น + ตาราง 1,а และ 1,б

   กฎที่ยึดตลอดไฟล์:
   1) ค่าที่ต้นฉบับให้จริง ใช้ตรง ๆ · ค่าที่ต้นฉบับไม่ให้ (พารามิเตอร์แท่นทดลอง) ใช้ค่าที่โน้ต
      ระบุว่าเป็น «ผู้เรียบเรียงคำนวณ / ค่าสมมติ» และเดโมจะพิมพ์คำเตือนไว้ในบรรทัดผลลัพธ์เสมอ
   2) สีทุกสีอ่านผ่าน CV(...) ภายใน draw() เท่านั้น
   3) ไม่มีการเรียก setInterval / requestAnimationFrame เอง — ใช้ animate ของเอนจิน */

/* ---------- ตัวช่วยภายในกลุ่ม G (ขึ้นต้น eog เพื่อไม่ชนกับกลุ่มอื่น) ---------- */

/* ---- ป้ายค่าบนแกนแบบเลขกลม (แทนการส่ง min/max ดิบเข้า ticks) ---- */
function eogNiceStep(span, n) {
  var raw = Math.abs(span) / Math.max(1, n);
  if (!(raw > 0) || !isFinite(raw)) return 1;
  var e = Math.pow(10, Math.floor(Math.log(raw) / Math.LN10)), f = raw / e;
  return (f < 1.5 ? 1 : f < 3.5 ? 2 : f < 7.5 ? 5 : 10) * e;
}
function eogTicksN(a, b, n) {
  if (!isFinite(a) || !isFinite(b) || b <= a) return [a, b];
  /* เอนจินพิมพ์ป้ายด้วย toFixed(2) — ก้าวต่ำกว่า 0,01 จะได้ป้ายซ้ำ จึงยกพื้นไว้ */
  var st = Math.max(eogNiceStep(b - a, n), 0.01), out = [], seen = {}, lab,
    k = Math.ceil((a - st * 1e-6) / st), guard = 0, v;
  for (; k * st <= b + st * 1e-6 && guard < 400; k++, guard++) {
    v = +(k * st).toPrecision(12);
    lab = String(+v.toFixed(2));
    if (seen[lab]) continue;
    seen[lab] = 1; out.push(v);
  }
  return out.length >= 2 ? out : [a, b];
}

/* จัดรูปตัวเลขแบบรัสเซีย (จุลภาคเป็นตัวคั่นทศนิยม) */

function eogF(v, d) {
  if (v === null || v === undefined || !isFinite(v)) return "—";
  var n = (d === undefined) ? 2 : d;
  return v.toFixed(n).replace(".", ",");
}

/* ขนาดฟอนต์ตามความกว้างผ้าใบ — ต้องอ่านได้ที่ 390 px */
function eogFS(w) { return w < 430 ? 9 : (w < 700 ? 10 : 11); }
function eogFont(fs, bold) { return (bold ? "bold " : "") + fs + 'px "IBM Plex Mono", monospace'; }

/* เรขาคณิตของแผงกราฟ n แผงเรียงลงมา */
function eogPlots(w, h, n, o) {
  o = o || {};
  var L = o.left === undefined ? (w < 430 ? 40 : 50) : o.left;
  var R = Math.max(o.right === undefined ? 18 : o.right, 18);
  var top = Math.max(o.top === undefined ? 18 : o.top, 18);
  var gap = Math.max(o.gap === undefined ? 42 : o.gap, n > 1 ? 42 : 34);
  var bot = Math.max(o.bottom === undefined ? 32 : o.bottom, 32);
  var ph = (h - top - bot - gap * (n - 1)) / n;
  var out = [], i;
  for (i = 0; i < n; i++) out.push({ x: L, y: top + i * (ph + gap), w: w - L - R, h: ph });
  return out;
}

/* ป้ายชื่อแผงกราฟ (มุมในกรอบ) */
/* ย่อฟอนต์ให้ข้อความพอดีความกว้าง maxw (ถ้ายังไม่พอจึงตัดท้ายด้วย …)
   คืนขนาดฟอนต์ที่ใช้จริง — ใช้ร่วมกันทุกป้ายบนผ้าใบของกลุ่ม G */
function eogFitFont(ctx, txt, maxw, fs, bold, min) {
  var lo = min === undefined ? 7.2 : min, f = fs;
  ctx.font = eogFont(f, bold);
  while (f > lo && ctx.measureText(txt).width > maxw) {
    f = Math.max(lo, f - 0.5);
    ctx.font = eogFont(f, bold);
  }
  return f;
}

/* ข้อความที่รับประกันว่าไม่ล้นความกว้าง maxw (ย่อฟอนต์ก่อน แล้วค่อยตัดคำ) */
function eogFitTxt(ctx, txt, maxw, fs, bold, min) {
  var f = eogFitFont(ctx, txt, maxw, fs, bold, min);
  return { fs: f, txt: eogClipTxt(ctx, txt, maxw) };
}

/* ความสูงของแถวหัวเรื่องแผง — ป้ายอื่นในกรอบต้องหลบลงมาใต้แถวนี้ */
function eogTagH(fs) { return fs * 1.55 + 6; }

/* ---- ระบบจองพื้นที่ป้ายบนแผง: ป้ายที่วางทีหลังจะเลี่ยงป้ายที่วางไปแล้ว ----
   เก็บกรอบที่ใช้แล้วไว้บนตัว Plot เอง (Plot ถูกสร้างใหม่ทุกครั้งที่ draw จึงไม่ค้าง) */
function eogFree(p, x0, y0, x1, y1) {
  var L = p._lbl;
  if (!L) return true;
  for (var i = 0; i < L.length; i++) {
    var r = L[i];
    if (x1 > r[0] + 1.5 && x0 < r[2] - 1.5 && y1 > r[1] + 1.5 && y0 < r[3] - 1.5) return false;
  }
  return true;
}
function eogTake(p, x0, y0, x1, y1) {
  if (!p._lbl) p._lbl = [];
  p._lbl.push([x0, y0, x1, y1]);
}
/* แถบหัวเรื่องแผง — ป้ายอื่นในกรอบต้องหลบลงมาใต้แถบนี้ (เผื่อหัวเรื่องซ้าย+ขวา 2 แถว) */
function eogBandH(fs) { return fs * 3.2 + 10; }

/* หัวเรื่องแผง — ถ้ามีหลายอันบนแผงเดียวกันจะไล่ลงบรรทัดถัดไปแทนที่จะทับกัน */
function eogTag(ctx, p, txt, col, fs, right) {
  ctx.save();
  ctx.textAlign = right ? "right" : "left";
  ctx.textBaseline = "top";
  var t = eogFitTxt(ctx, txt, p.w - 10, fs);
  var row = p._tagRows || 0;
  var y = p.y + 4 + row * eogTagH(t.fs);
  var tw = ctx.measureText(t.txt).width;
  var x0 = right ? p.x + p.w - 5 - tw : p.x + 5;
  var guard = 0;
  while (!eogFree(p, x0, y, x0 + tw, y + t.fs * 1.15) && guard++ < 6 &&
         y + t.fs * 2.4 < p.y + p.h) { y += eogTagH(t.fs); row++; }
  ctx.fillStyle = col;
  ctx.fillText(t.txt, right ? p.x + p.w - 5 : p.x + 5, y);
  eogTake(p, x0, y, x0 + tw, y + t.fs * 1.15);
  p._tagRows = row + 1;
  ctx.restore();
}

/* เส้นอ้างอิงแนวนอนพร้อมป้ายทางขวา */
function eogRef(ctx, p, val, col, txt, fs, dash) {
  if (!isFinite(val)) return;
  var y = Math.round(p.Y(val)) + 0.5;
  if (y < p.y - 1 || y > p.y + p.h + 1) return;
  ctx.save();
  ctx.strokeStyle = col;
  ctx.lineWidth = 1.1;
  ctx.setLineDash(dash || [5, 4]);
  ctx.beginPath();
  ctx.moveTo(p.x, y);
  ctx.lineTo(p.x + p.w, y);
  ctx.stroke();
  ctx.setLineDash([]);
  if (txt) {
    ctx.textAlign = "right";
    var t = eogFitTxt(ctx, txt, p.w - 10, fs);
    var tw = ctx.measureText(t.txt).width, hh = t.fs * 1.15;
    var x0 = p.x + p.w - 3 - tw;
    /* ลองวางเหนือเส้นก่อน ถ้าไปชนแถบหัวเรื่องหรือป้ายอื่น ค่อยย้ายลงใต้เส้น */
    var yTop = y - 2 - hh;
    var below = (yTop < p.y + eogBandH(t.fs)) || !eogFree(p, x0, yTop, x0 + tw, yTop + hh);
    if (below) yTop = y + 2;
    if (yTop + hh > p.y + p.h) yTop = Math.max(p.y + eogBandH(t.fs), y - 2 - hh);
    var gR = 0;
    while (!eogFree(p, x0, yTop, x0 + tw, yTop + hh) && gR++ < 6) {
      yTop += hh + 2;
      if (yTop + hh > p.y + p.h) { yTop = Math.max(p.y + eogBandH(t.fs), y - 2 - hh - gR * (hh + 2)); break; }
    }
    ctx.textBaseline = "top";
    ctx.fillStyle = col;
    ctx.fillText(t.txt, p.x + p.w - 3, yTop);
    eogTake(p, x0, yTop, x0 + tw, yTop + hh);
  }
  ctx.restore();
}

/* เส้นอ้างอิงแนวตั้งพร้อมป้ายบน */
function eogVRef(ctx, p, xv, col, txt, fs, dash) {
  if (!isFinite(xv)) return;
  var x = Math.round(p.X(xv)) + 0.5;
  if (x < p.x - 1 || x > p.x + p.w + 1) return;
  ctx.save();
  ctx.strokeStyle = col;
  ctx.lineWidth = 1.1;
  ctx.setLineDash(dash || [5, 4]);
  ctx.beginPath();
  ctx.moveTo(x, p.y);
  ctx.lineTo(x, p.y + p.h);
  ctx.stroke();
  ctx.setLineDash([]);
  if (txt) {
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    var t = eogFitTxt(ctx, txt, p.w - 8, fs);
    var tw = ctx.measureText(t.txt).width, hh = t.fs * 1.15;
    var x0 = Math.max(p.x + 4, Math.min(x + 3, p.x + p.w - 4 - tw));
    var y0 = p.y + 3 + eogBandH(t.fs);
    var guard = 0;
    while (!eogFree(p, x0, y0, x0 + tw, y0 + hh) && y0 + hh * 2 < p.y + p.h && guard++ < 12) y0 += hh + 2;
    ctx.fillStyle = col;
    ctx.fillText(t.txt, x0, y0);
    eogTake(p, x0, y0, x0 + tw, y0 + hh);
  }
  ctx.restore();
}

/* จุดทำงานเน้น (วงกลมมีขอบ) พร้อมป้าย */
function eogMark(ctx, p, xv, yv, col, txt, fs, below) {
  var x = p.X(xv), y = p.Y(yv);
  if (x < p.x - 3 || x > p.x + p.w + 3) return;
  /* จุดข้อมูลที่ตกนอกกรอบ: ตรึงตำแหน่งอ้างอิงของป้ายไว้ในกรอบ ไม่ให้ป้ายไปกองกันที่ขอบ */
  var yA = Math.max(p.y + 2, Math.min(p.y + p.h - 2, y));
  ctx.save();
  ctx.fillStyle = col;
  ctx.beginPath(); ctx.arc(x, y, 4.2, 0, 7); ctx.fill();
  ctx.strokeStyle = CV("--bg"); ctx.lineWidth = 1.4;
  ctx.beginPath(); ctx.arc(x, y, 4.2, 0, 7); ctx.stroke();
  if (txt) {
    var t = eogFitTxt(ctx, txt, p.w - 14, fs, true);
    var tw = ctx.measureText(t.txt).width, hh = t.fs * 1.15;
    var right = (x + tw + 10 > p.x + p.w);
    var x0 = right ? Math.max(p.x + 2, x - 7 - tw) : Math.min(x + 7, p.x + p.w - 2 - tw);
    /* ลำดับความชอบ: ด้านที่ผู้เรียกขอ → อีกด้าน → ขยับทีละบรรทัด */
    var cand = [], k;
    for (k = 0; k < 6; k++) {
      cand.push(below ? yA + 6 + k * (hh + 2) : yA - 6 - hh - k * (hh + 2));
      cand.push(below ? yA - 6 - hh - k * (hh + 2) : yA + 6 + k * (hh + 2));
    }
    var lo = p.y + eogBandH(t.fs), hi = p.y + p.h - hh - 2, y0 = null;
    for (k = 0; k < cand.length; k++) {
      var c = cand[k];
      if (c < lo || c > hi) continue;
      if (eogFree(p, x0, c, x0 + tw, c + hh)) { y0 = c; break; }
    }
    if (y0 === null) {          /* กวาดทั้งกรอบหาแถวที่ยังว่าง */
      for (var yy = lo; yy <= hi; yy += hh + 2) {
        if (eogFree(p, x0, yy, x0 + tw, yy + hh)) { y0 = yy; break; }
      }
    }
    if (y0 === null) y0 = Math.min(hi, Math.max(lo, below ? yA + 6 : yA - 6 - hh));
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillStyle = col;
    ctx.fillText(t.txt, x0, y0);
    eogTake(p, x0, y0, x0 + tw, y0 + hh);
  }
  ctx.restore();
}

/* แถบสัญญาณไฟ (ใช้ในเดโมที่มีเงื่อนไขผ่าน/ไม่ผ่าน) */
function eogBar(ctx, x, y, w, h, frac, ok, label, val, fs) {
  ctx.save();
  ctx.fillStyle = CV("--wash");
  ctx.fillRect(x, y, w, h);
  ctx.fillStyle = ok ? CV("--ok") : CV("--crit");
  ctx.fillRect(x, y, Math.max(0, Math.min(1, frac)) * w, h);
  ctx.strokeStyle = CV("--line-2");
  ctx.lineWidth = 1;
  ctx.strokeRect(Math.round(x) + 0.5, Math.round(y) + 0.5, Math.round(w), Math.round(h));
  /* ข้อความบนแท่ง: วาดสองรอบ — ส่วนที่อยู่บนพื้นสีใช้สี --bg ส่วนที่อยู่บนพื้นว่างใช้ --ink-2
     (แก้ปัญหาคอนทราสต์ต่ำเมื่อป้ายทับแท่งแดง/เขียวเข้ม) */
  var fw = Math.max(0, Math.min(1, frac)) * w;
  ctx.textBaseline = "middle";
  var lab = eogFitTxt(ctx, label, w * 0.62, fs);
  var vv = eogFitTxt(ctx, val, w * 0.34, fs, true);
  var edge = x + fw;
  var draw2 = function (txt, tx, align, f, bold, onFill, offFill) {
    ctx.font = eogFont(f, bold);
    ctx.textAlign = align;
    var tw = ctx.measureText(txt).width;
    var a = align === "right" ? tx - tw : tx, b = a + tw;
    if (edge <= a + 0.5) { ctx.fillStyle = offFill; ctx.fillText(txt, tx, y + h / 2); return; }
    if (edge >= b - 0.5) { ctx.fillStyle = onFill; ctx.fillText(txt, tx, y + h / 2); return; }
    ctx.save(); ctx.beginPath(); ctx.rect(x, y, fw, h); ctx.clip();
    ctx.fillStyle = onFill; ctx.fillText(txt, tx, y + h / 2); ctx.restore();
    ctx.save(); ctx.beginPath(); ctx.rect(edge, y, x + w - edge, h); ctx.clip();
    ctx.fillStyle = offFill; ctx.fillText(txt, tx, y + h / 2); ctx.restore();
  };
  draw2(lab.txt, x + 4, "left", lab.fs, false, CV("--bg"), CV("--ink-2"));
  draw2(vv.txt, x + w - 4, "right", vv.fs, true, CV("--bg"), ok ? CV("--ok") : CV("--crit"));
  ctx.restore();
}

/* ข้อความหลายบรรทัดในกรอบ (ใช้กับตารางผลของ eoRGR และคำอธิบายบนผ้าใบ) */
function eogText(ctx, x, y, txt, col, fs, align, bold, maxw) {
  ctx.save();
  ctx.textAlign = align || "left";
  ctx.textBaseline = "middle";
  var t = maxw ? eogFitTxt(ctx, txt, maxw, fs, bold) : { txt: txt, fs: fs };
  ctx.font = eogFont(t.fs, bold);
  ctx.fillStyle = col;
  ctx.fillText(t.txt, x, y);
  ctx.restore();
}

/* กรอบพื้นหลังอ่อน (หัวตาราง/บล็อกข้อความ) */
function eogPanel(ctx, x, y, w, h, fill, stroke) {
  ctx.save();
  ctx.fillStyle = fill;
  ctx.fillRect(x, y, w, h);
  if (stroke) {
    ctx.strokeStyle = stroke;
    ctx.lineWidth = 1;
    ctx.strokeRect(Math.round(x) + 0.5, Math.round(y) + 0.5, Math.round(w), Math.round(h));
  }
  ctx.restore();
}

/* ปัดเศษตามกฎของ РГР-2: ความต้านทานและกระแส → ทศนิยม 2 ตำแหน่ง */
function eogR2(v) { return Math.round(v * 100) / 100; }


/* =====================================================================
   1) eoPZsg — ПЗ № 1 «Испытание трёхфазного синхронного генератора»
   สูตร: notes/PZ-SG.md
     Ф-1  f = p·n/60                Ф-2  n = 60·f/p
     Ф-3  E₀ = 4,44·f·w·k_об·Φ      Ф-5  U̅ = E̅₀ − I̅·(R_a + j·X_c)
     Ф-7  U ≈ E₀ − I·X_c·sinφ − I·R_a·cosφ   (ใช้รูปเวกเตอร์เต็มตามข้อ 9.4)
     Ф-8…Ф-10  внешняя характеристика และ ΔU %
     Ф-11 регулировочная характеристика  Ф-12…Ф-19 พลังงานและ КПД
   รูปเวกเตอร์เต็มที่ใช้คำนวณทุกจุดของกราฟ (ข้อ 9.4 ของโน้ต):
     U_ф = √(E₀² − (I·X_c·cosφ − I·R_a·sinφ)²) − I·R_a·cosφ − I·X_c·sinφ
     ที่ cos φ = 1 ลดรูปเป็น √(E₀² − (I·X_c)²) − I·R_a   ✔ ตรงกับตารางข้อ 9.4
     ที่ cos φ = 0 ลดรูปเป็น ≈ E₀ − I·X_c                ✔ ตรงกับตารางข้อ 9.6
   พารามิเตอร์แท่น (R_a, X_c, E₀, η_СГ, P₀) เป็น «ค่าสมมติของผู้เรียบเรียง» ตามข้อ 9.1
   ===================================================================== */
function eogSgU(E0, I, Xc, Ra, cosf) {
  var sinf = Math.sqrt(Math.max(0, 1 - cosf * cosf));
  var q = I * Xc * cosf - I * Ra * sinf;          // องค์ประกอบตั้งฉากกับ U
  var d = E0 * E0 - q * q;
  if (d <= 0) return 0;
  return Math.max(0, Math.sqrt(d) - I * Ra * cosf - I * Xc * sinf);
}
/* ЭДС ที่ต้องการเพื่อรักษา U_ф ให้คงที่ (ผกผันของสูตรข้างบน) — ฐานของ Ф-11 */
function eogSgE(U, I, Xc, Ra, cosf) {
  var sinf = Math.sqrt(Math.max(0, 1 - cosf * cosf));
  var a = U + I * Ra * cosf + I * Xc * sinf;
  var b = I * Xc * cosf - I * Ra * sinf;
  return Math.sqrt(a * a + b * b);
}

function eoPZsg(host) {
  buildDemo(host, {
    label: "ПЗ № 1 · СГ · п. 8–10, пример 9.4–9.8",
    title: "เลื่อนโหลดและ cos φ แล้วดูว่าคุณลักษณะภายนอกของ СГ ตกชันขึ้นเท่าไร และต้องเพิ่มกระแสกระตุ้นเท่าไรจึงจะดึงแรงดันกลับ",
    ratio: 0.92,
    legend: '<span><i style="background:var(--accent)"></i>cos φ = 1 (активная)</span>' +
      '<span><i style="background:var(--crit)"></i>cos φ = 0 (индуктивная)</span>' +
      '<span><i style="background:var(--accent-2)"></i>cos φ ที่เลือก</span>' +
      '<span><i style="background:var(--ok)"></i>U_н = 120 В · จุดพิกัด</span>',
    controls: [
      { id: "cosf", label: "cos φ — ตัวประกอบกำลังของโหลด", min: 0, max: 1, step: 0.05, value: 0.8, fmt: function (v) { return eogF(v, 2); } },
      { id: "I", label: "I, А — กระแสโหลดของเครื่องกำเนิด (พิกัด 3,0 А)", min: 0, max: 3.6, step: 0.05, value: 3, fmt: function (v) { return eogF(v, 2); } },
      { id: "Xc", label: "X_c, Ом — синхронное индуктивное сопротивление", min: 4, max: 20, step: 0.5, value: 12, fmt: function (v) { return eogF(v, 1); } },
      { id: "Ra", label: "R_a, Ом — активное сопротивление обмотки якоря", min: 0.4, max: 4, step: 0.1, value: 1.8, fmt: function (v) { return eogF(v, 1); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), line2 = CV("--line-2"), wash = CV("--wash");
      var fs = eogFS(w);

      /* ---- ค่าตั้งต้นของแท่น (ข้อ 9.1 ของโน้ต — «ค่าสมมติ») ---- */
      var Uln = 120, In = 3.0, p = 2, f = 50, Uv = 30, Udv = 110, Ivdv = 0.45;
      var etaSG = 0.80, P0 = 90;                 // ข้อ 9.5
      var Ufn = Uln / Math.sqrt(3);              // 69,3 В — แรงดันเฟสพิกัด
      var Xc = s.Xc, Ra = s.Ra, cosf = s.cosf, I = s.I;

      /* E₀ ตรึงจากจุดโหลดเต็มที่ cos φ = 1 (ข้อ 9.4) — I_в = const ตลอดคุณลักษณะภายนอก */
      var E0 = eogSgE(Ufn, In, Xc, Ra, 1);       // ค่าโน้ต 82,9 В เมื่อ X_c = 12 · R_a = 1,8
      var kXX = E0 / 1.20;                       // ลักษณะ ХХ เชิงเส้น E₀ = k·I_в (ข้อ 9.7)

      /* ---- สร้างเส้นโค้ง ---- */
      var N = 90, i, x, c1 = [], c0 = [], cx = [], r1 = [], r0 = [], rx = [], Imax = 3.6;
      for (i = 0; i <= N; i++) {
        x = Imax * i / N;
        c1.push([x, Math.sqrt(3) * eogSgU(E0, x, Xc, Ra, 1)]);
        c0.push([x, Math.sqrt(3) * eogSgU(E0, x, Xc, Ra, 0)]);
        cx.push([x, Math.sqrt(3) * eogSgU(E0, x, Xc, Ra, cosf)]);
        r1.push([x, eogSgE(Ufn, x, Xc, Ra, 1) / kXX]);
        r0.push([x, eogSgE(Ufn, x, Xc, Ra, 0) / kXX]);
        rx.push([x, eogSgE(Ufn, x, Xc, Ra, cosf) / kXX]);
      }

      var U0 = Math.sqrt(3) * E0;                       // แรงดันสายที่ ХХ
      var Ul = Math.sqrt(3) * eogSgU(E0, I, Xc, Ra, cosf);
      var UlN = Math.sqrt(3) * eogSgU(E0, In, Xc, Ra, cosf);
      var dU1 = (U0 - Math.sqrt(3) * eogSgU(E0, In, Xc, Ra, 1)) / (Math.sqrt(3) * eogSgU(E0, In, Xc, Ra, 1)) * 100;
      var dU0 = (U0 - Math.sqrt(3) * eogSgU(E0, In, Xc, Ra, 0)) / (Math.sqrt(3) * eogSgU(E0, In, Xc, Ra, 0)) * 100;
      var dUx = UlN > 1 ? (U0 - UlN) / UlN * 100 : Infinity;

      /* ---- พลังงาน (Ф-12…Ф-19) ---- */
      var S = Math.sqrt(3) * Ul * I;                    // Ф-13
      var P2 = S * cosf;                                // Ф-12
      var Q2 = S * Math.sqrt(Math.max(0, 1 - cosf * cosf)); // Ф-14
      var Pmeh = P2 / etaSG + P0;                       // ข้อ 9.5
      var Iadv = Pmeh / Udv;
      var Iv = eogSgE(Ufn, I, Xc, Ra, cosf) / kXX;
      var Pv = Uv * Iv;                                 // Ф-15
      var P1 = Udv * (Iadv + Ivdv);                     // Ф-16
      var etaAgr = P1 > 1 ? P2 / P1 * 100 : 0;          // Ф-19
      var etaGen = (Pmeh + Pv) > 1 ? P2 / (Pmeh + Pv) * 100 : 0; // Ф-18
      var nn = 60 * f / p;                              // Ф-2

      /* ---- วาด ---- */
      var g = eogPlots(w, h, 2, { gap: 34, bottom: 30 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, Imax, 0, Math.max(150, U0 * 1.06));
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, Imax, 0.8, 1.9);

      p1.frame(ticks(0, Imax, 6), eogTicksN(0, Math.max(150, U0 * 1.06), 5), "I, А","U_л, В");
      eogPanel(ctx, p1.x, p1.Y(Uln * 1.02), p1.w, p1.Y(Uln * 0.98) - p1.Y(Uln * 1.02), wash);
      eogRef(ctx, p1, Uln, ok, "U_н = 120 В", fs);
      eogRef(ctx, p1, U0, ink3, "U₀ = √3·E₀ = " + eogF(U0, 1) + " В", fs, [3, 3]);
      p1.clip(function () {
        p1.line(c1, acc, 2);
        p1.line(c0, crit, 2);
        p1.line(cx, acc2, 2.4, [6, 3]);
      });
      eogVRef(ctx, p1, In, ok, "I_н", fs, [4, 4]);
      eogMark(ctx, p1, I, Ul, acc2, eogF(Ul, 1) + " В", fs);
      eogTag(ctx, p1, "Внешняя характеристика  U_л = f(I)  при  I_в = const,  n = 1500 об/мин", acc, fs);

      p2.frame(ticks(0, Imax, 6), eogTicksN(0.8, 1.9, 4), "I, А","I_в, А");
      p2.clip(function () {
        p2.line(r1, acc, 2);
        p2.line(r0, crit, 2);
        p2.line(rx, acc2, 2.4, [6, 3]);
      });
      eogRef(ctx, p2, r1[0][1], ink3, "I_в0 (ХХ) = " + eogF(r1[0][1], 2) + " А", fs, [3, 3]);
      eogVRef(ctx, p2, In, ok, "I_н", fs, [4, 4]);
      eogMark(ctx, p2, I, Iv, acc2, eogF(Iv, 2) + " А", fs, true);
      eogTag(ctx, p2, "Регулировочная  I_в = f(I)  при  U_л = 120 В = const", acc, fs);

      /* ---- ผลลัพธ์ ---- */
      var stiff = dUx > 40 ? "bad" : (dUx > 20 ? "" : "good");
      readout.innerHTML =
        'U<sub>л</sub> = <b>' + eogF(Ul, 1) + ' В</b> · U<sub>ф</sub> = <b>' + eogF(Ul / Math.sqrt(3), 1) + ' В</b>' +
        '<span>ΔU % ที่โหลดพิกัด (Ф-10) = <b class="' + stiff + '">' + eogF(dUx, 1) + ' %</b> — เทียบ <b class="good">' + eogF(dU1, 1) + ' %</b> ที่ cos φ = 1 และ <b class="bad">' + eogF(dU0, 1) + ' %</b> ที่ cos φ = 0</span>' +
        '<span>I<sub>в</sub> ที่ต้องตั้ง = <b>' + eogF(Iv, 2) + ' А</b> (จาก ХХ เชิงเส้น E₀ = ' + eogF(kXX, 1) + '·I<sub>в</sub>) ⇒ ต้องเพิ่มจากภาวะ ХХ <b>' + eogF((Iv / r1[0][1] - 1) * 100, 0) + ' %</b></span>' +
        '<span>S = √3·U·I = <b>' + eogF(S, 0) + ' В·А</b> · P₂ = <b>' + eogF(P2, 0) + ' Вт</b> · Q = <b>' + eogF(Q2, 0) + ' вар</b>  (Ф-12…Ф-14)</span>' +
        '<span>P<sub>мех</sub> = P₂/η<sub>СГ</sub> + P₀ = <b>' + eogF(Pmeh, 0) + ' Вт</b> ⇒ I<sub>я.дв</sub> ≈ <b>' + eogF(Iadv, 2) + ' А</b> · P<sub>в</sub> = 30·I<sub>в</sub> = <b>' + eogF(Pv, 0) + ' Вт</b></span>' +
        '<span>η<sub>агр</sub> = P₂/P₁ = <b>' + eogF(etaAgr, 1) + ' %</b> · η<sub>СГ</sub> = P₂/(P<sub>мех</sub>+P<sub>в</sub>) = <b>' + eogF(etaGen, 1) + ' %</b>  (Ф-18, Ф-19)</span>' +
        '<span>n<sub>н</sub> = 60·f/p = 60·50/2 = <b>1500 об/мин</b> — ต้องตรึงด้วยรีโอสตัต RP2 ตลอดการทดลอง (Ф-2)</span>' +
        '<span>เหตุผลที่เส้นสีแดงตกชันกว่ามาก: ที่ cos φ = 0 กระแสอาร์เมเจอร์เป็นรีแอกทีฟล้วน ⇒ <b>реакция якоря เป็นแบบ продольная размагничивающая</b> ลดฟลักซ์ตรง ๆ และแรงดันตกทั้งหมดไปตกบน X_c ซึ่งใหญ่กว่า R_a หลายเท่า</span>' +
        '<span>สังเกตว่า I<sub>я.дв</sub> โตตาม P₂ เท่านั้น — ที่ cos φ = 0 กำลังจริงเกือบเป็นศูนย์ กระแสอาร์เมเจอร์ของมอเตอร์ขับจึงแทบไม่ขยับ (คำตอบของคำถามควบคุมข้อ 12)</span>' +
        '<span>⚠ R_a, X_c, η<sub>СГ</sub>, P₀ เป็นค่าสมมติของผู้เรียบเรียง (ข้อ 9.1 ของโน้ต) — ต้นฉบับไม่ให้ค่าพิกัดของ СГ เลย ต้องอ่านจากป้ายบนแท่น</span>';
    }
  });
}


/* =====================================================================
   2) eoPZgpt — ПЗ № 2 «Испытание ГПТ параллельного возбуждения»
   สูตร: notes/PZ-GPT.md
     Ф-1  E = c_E·n·Φ            Ф-3  U = E − I_я·R_я
     Ф-5  I_я = I + I_в          Ф-6  I_в = U/R_ц.в   ← แก่นของงานนี้
     Ф-7  R_ц.в = R_ов + R_RP1
     Ф-8/Ф-9  เงื่อนไขการกระตุ้นตัวเอง = จุดตัดของลักษณะ ХХ กับเส้นตรงสนาม U = R_ц.в·I_в
     Ф-10 ลักษณะ ХХ    Ф-11…Ф-13 внешняя характеристика และ ΔU %
     Ф-14 I_кз(парал.) = E_ост/R_я   Ф-15 I_кз(незав.) = E_н/R_я
     Ф-16 регулировочная характеристика
   แบบจำลอง ХХ ของโน้ต (ข้อ 9.3):  E₀(I_в) = E_ост + E_max·I_в/(I_в + a)
     E_ост = 4,5 В · E_max = 178 В · a = 0,60 А ⇒ ที่ I_в = 1,00 А ได้ 115,8 В ✔
   реакция якоря เข้าเป็นการลดกระแสกระตุ้นสมมูล: x = I_в − c_ра·I  (c_ра = 0,024 А/А
   ผู้เรียบเรียงปรับให้ตรงกับตารางข้อ 9.4 ซึ่งหัก 1,2 В ต่อกระแสโหลด 1 А)
   คุณลักษณะภายนอกวาดโดย «กวาดค่า I_в» ไม่ใช่กวาด I จึงได้กิ่งย้อนกลับ (участок КЗ) ครบ
   ===================================================================== */
function eogGptE0(iv, Eost, Emax, a) {
  var x = Math.max(0, iv);
  return Eost + Emax * x / (x + a);
}

function eoPZgpt(host) {
  buildDemo(host, {
    label: "ПЗ № 2 · ГПТ парал. возб. · п. 8.1–8.3, пример 9.2–9.7",
    title: "หมุนรีโอสตัต RP1 และความเร็วรอบ แล้วดูว่าเมื่อไรเครื่องกระตุ้นตัวเองได้ และทำไมคุณลักษณะภายนอกจึงม้วนกลับก่อนถึงจุดลัดวงจร",
    ratio: 1.05,
    legend: '<span><i style="background:var(--accent)"></i>ХХ: E₀(I_в) กิ่งขึ้น</span>' +
      '<span><i style="background:var(--ink-3)"></i>กิ่งลง (гистерезис)</span>' +
      '<span><i style="background:var(--accent-2)"></i>เส้นตรงสนาม U = R_ц.в·I_в</span>' +
      '<span><i style="background:var(--crit)"></i>внешняя U(I)</span>' +
      '<span><i style="background:var(--ok)"></i>регулировочная I_в(I)</span>',
    controls: [
      { id: "rp1", label: "R_RP1, Ом — รีโอสตัตในวงจรกระตุ้น (R_ов = 95 Ом คงที่)", min: 0, max: 260, step: 2, value: 20, fmt: function (v) { return eogF(v, 0); } },
      { id: "n", label: "n, об/мин — ความเร็วรอบของเครื่องขับ (พิกัด 1500)", min: 300, max: 1800, step: 20, value: 1500, fmt: function (v) { return eogF(v, 0); } },
      { id: "Rya", label: "R_я, Ом — ความต้านทานวงจรอาร์เมเจอร์", min: 0.8, max: 3.2, step: 0.1, value: 1.6, fmt: function (v) { return eogF(v, 1); } },
      { id: "I", label: "I, А — กระแสโหลด (พิกัด 3,0 А)", min: 0, max: 8, step: 0.1, value: 3, fmt: function (v) { return eogF(v, 1); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      /* ---- ค่าตั้งต้น (ข้อ 9.1 ของโน้ต — «ค่าสมมติ») ---- */
      var Eost = 4.5, Emax = 178, a = 0.60, Rov = 95, Un = 115, In = 3.0, nn = 1500;
      var cra = 0.024, etaG = 0.78, P0 = 80, Udv = 120;
      var Rcv = Rov + s.rp1, kn = s.n / nn, Rya = s.Rya;

      /* ---- แผงที่ 1: ลักษณะ ХХ + เส้นตรงสนาม ---- */
      var N = 120, i, iv, xx = [], xxDown = [], fieldLine = [], IvMax = 2.0;
      for (i = 0; i <= N; i++) {
        iv = IvMax * i / N;
        xx.push([iv, kn * eogGptE0(iv, Eost, Emax, a)]);
        /* กิ่งลงสูงกว่ากิ่งขึ้น 3…8 % (ข้อ 9.3) — แบบจำลองฮิสเทอรีซิสของผู้เรียบเรียง */
        xxDown.push([iv, kn * (eogGptE0(iv, Eost, Emax, a) * (1 + 0.06 * Math.exp(-iv / 0.9)) + 1.2 * Math.exp(-iv / 0.35))]);
        fieldLine.push([iv, Rcv * iv]);
      }
      /* จุดกระตุ้นตัวเอง: แก้ k·E₀(I_в) = R_ц.в·I_в โดยวิธีแบ่งครึ่ง */
      var Rkr = kn * Emax / a;                       // Ф-8: ความชันเริ่มต้นของลักษณะ ХХ
      var selfExc = Rcv < Rkr;
      var lo = 0.001, hi = IvMax, mid, ivSelf = 0, Uself = kn * Eost;
      if (selfExc) {
        for (i = 0; i < 60; i++) {
          mid = (lo + hi) / 2;
          if (kn * eogGptE0(mid, Eost, Emax, a) > Rcv * mid) lo = mid; else hi = mid;
        }
        ivSelf = lo; Uself = Rcv * ivSelf;
      }
      var nkr = nn * Rcv / (Emax / a);               // ความเร็ววิกฤต (ข้อ 9.7)

      /* ---- แผงที่ 2: внешняя характеристика (กวาดค่า I_в) ---- */
      var ext = [], Imax = 8, Ucur = 0, Icur = 0, x, E, Iload, it;
      for (i = N; i >= 0; i--) {
        iv = ivSelf > 0 ? ivSelf * i / N : 0;
        Iload = 0;
        for (it = 0; it < 12; it++) {                // แก้ซ้ำเพราะ реакция якоря ขึ้นกับ I
          x = Math.max(0, iv - cra * Iload);
          E = kn * eogGptE0(x, Eost, Emax, a);
          Iload = (E - iv * Rcv - iv * Rya) / Rya;
        }
        if (Iload >= -0.05) ext.push([Math.max(0, Iload), iv * Rcv]);
      }
      /* หาจุดทำงานที่กระแสโหลดที่ผู้ใช้เลือก (กิ่งบนของเส้นโค้ง) */
      var best = -1, bd = 1e9;
      for (i = 0; i < ext.length; i++) {
        if (Math.abs(ext[i][0] - s.I) < bd) { bd = Math.abs(ext[i][0] - s.I); best = i; }
      }
      if (best >= 0) { Icur = ext[best][0]; Ucur = ext[best][1]; }
      var Ikz = kn * Eost / Rya;                     // Ф-14
      var IkzNez = kn * eogGptE0(ivSelf, Eost, Emax, a) / Rya;  // Ф-15
      /* หาจุดวิกฤต (กระแสสูงสุดที่เครื่องจ่ายได้) */
      var Ikr = 0, Ukr = 0;
      for (i = 0; i < ext.length; i++) if (ext[i][0] > Ikr) { Ikr = ext[i][0]; Ukr = ext[i][1]; }

      /* ---- แผงที่ 3: регулировочная характеристика ---- */
      var reg = [], Ureq = selfExc ? Math.min(Un, Uself) : 0, ivr, Er;
      for (i = 0; i <= 60; i++) {
        Iload = In * 1.6 * i / 60;
        ivr = ivSelf;
        for (it = 0; it < 25; it++) {                // ผกผันของแบบจำลอง ХХ ด้วยการวนซ้ำ
          Er = Ureq + (Iload + ivr) * Rya + 0;
          x = (Er / kn - Eost);
          ivr = x >= Emax ? IvMax : (a * x / (Emax - x)) + cra * Iload;
          if (!isFinite(ivr) || ivr > IvMax) { ivr = IvMax; break; }
        }
        reg.push([Iload, ivr]);
      }

      /* ---- วาด ---- */
      var g = eogPlots(w, h, 3, { gap: 32, bottom: 28 });
      var Emx = Math.max(60, kn * (Eost + Emax * IvMax / (IvMax + a)) * 1.05);
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, IvMax, 0, Emx);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, Imax, 0, Math.max(60, Emx));
      var p3 = new Plot(ctx, g[2].x, g[2].y, g[2].w, g[2].h, 0, In * 1.6, 0, IvMax);

      p1.frame(ticks(0, IvMax, 4), eogTicksN(0, Emx, 4), "I_в, А","E₀, В");
      p1.clip(function () {
        p1.line(xxDown, ink3, 1.6, [5, 3]);
        p1.line(xx, acc, 2.2);
        p1.line(fieldLine, acc2, 2);
      });
      if (selfExc) eogMark(ctx, p1, ivSelf, Uself, ok, "точка самовозбуждения " + eogF(Uself, 1) + " В", fs);
      eogTag(ctx, p1, "1) ХХ  E₀ = f(I_в)  +  прямая поля  U = R_ц.в·I_в = " + eogF(Rcv, 0) + "·I_в", acc, fs);
      eogTag(ctx, p1, selfExc ? "R_ц.в < R_кр ⇒ возбуждается" : "R_ц.в > R_кр ⇒ НЕ возбуждается", selfExc ? ok : crit, fs, true);

      p2.frame(ticks(0, Imax, 8), eogTicksN(0, Math.max(60, Emx), 4), "I, А","U, В");
      eogPanel(ctx, p2.x, p2.Y(Un * 1.02), p2.w, p2.Y(Un * 0.98) - p2.Y(Un * 1.02), wash);
      eogRef(ctx, p2, Un, ok, "U_н = 115 В", fs);
      p2.clip(function () { p2.line(ext, crit, 2.2); });
      eogMark(ctx, p2, Ikz, 0, ink3, "I_кз = E_ост/R_я = " + eogF(Ikz, 2) + " А", fs, true);
      if (Ikr > 0) eogMark(ctx, p2, Ikr, Ukr, acc2, "I_кр ≈ " + eogF(Ikr, 1) + " А", fs);
      eogMark(ctx, p2, Icur, Ucur, crit, eogF(Ucur, 1) + " В", fs);
      eogTag(ctx, p2, "2) Внешняя  U = f(I)  при  R_ц.в = const — เส้นม้วนกลับเพราะ Ф-6", crit, fs);

      p3.frame(ticks(0, In * 1.6, 6), eogTicksN(0, IvMax, 4), "I, А","I_в, А");
      p3.clip(function () { p3.line(reg, ok, 2.2); });
      eogVRef(ctx, p3, In, acc2, "I_н", fs, [4, 4]);
      eogRef(ctx, p3, IvMax, crit, "ขีดจำกัดของ RP1 (R_RP1 = 0)", fs, [3, 3]);
      eogTag(ctx, p3, "3) Регулировочная  I_в = f(I)  при  U = 115 В = const", ok, fs);

      /* ---- ผลลัพธ์ ---- */
      var dU = Uself > 0 ? (Uself - Ucur) / Math.max(1, Ucur) * 100 : 0;
      readout.innerHTML =
        'สภาวะการกระตุ้นตัวเอง: <b class="' + (selfExc ? "good" : "bad") + '">' + (selfExc ? "กระตุ้นได้" : "ไม่กระตุ้น — แรงดันค้างที่ E_ост") + '</b>' +
        '<span>R<sub>ц.в</sub> = R<sub>ов</sub> + R<sub>RP1</sub> = 95 + ' + eogF(s.rp1, 0) + ' = <b>' + eogF(Rcv, 0) + ' Ом</b> เทียบกับ R<sub>кр</sub> = k·E<sub>max</sub>/a = <b>' + eogF(Rkr, 0) + ' Ом</b> (Ф-8)</span>' +
        '<span>n<sub>кр</sub> = n<sub>н</sub>·R<sub>ц.в</sub>/R<sub>кр</sub>(при n<sub>н</sub>) = <b>' + eogF(nkr, 0) + ' об/мин</b> — ต่ำกว่านี้ก็ไม่กระตุ้นแม้ความต้านทานจะพอ</span>' +
        '<span>U₀ (ХХ) = <b>' + eogF(Uself, 1) + ' В</b> · I<sub>в0</sub> = <b>' + eogF(ivSelf, 2) + ' А</b> · ที่ I = ' + eogF(Icur, 1) + ' А ⇒ U = <b>' + eogF(Ucur, 1) + ' В</b> · ΔU % = <b>' + eogF(dU, 1) + ' %</b> (Ф-13)</span>' +
        '<span>I<sub>кз</sub> ของเครื่องกระตุ้น<b>ขนาน</b> = E<sub>ост</sub>/R<sub>я</sub> = <b class="good">' + eogF(Ikz, 2) + ' А</b> เทียบกับกระตุ้น<b>อิสระ</b> = E/R<sub>я</sub> = <b class="bad">' + eogF(IkzNez, 1) + ' А</b> ⇒ ต่างกัน <b>' + eogF(IkzNez / Math.max(0.01, Ikz), 0) + ' เท่า</b> (Ф-14 / Ф-15 — คำตอบข้อ 9)</span>' +
        '<span>สาเหตุที่แรงดันตกมี <b>สามข้อ</b>: ① ตกคร่อม I<sub>я</sub>·R<sub>я</sub> (Ф-3) ② реакция якоря ลดฟลักซ์ ③ <b>I<sub>в</sub> ลดตาม U เอง</b> (Ф-6) — ข้อสามมีเฉพาะเครื่องกระตุ้นขนาน จึงทำให้เส้นม้วนกลับที่ I<sub>кр</sub></span>' +
        '<span>ลากรีโอสตัตขึ้นเกิน <b>' + eogF(Math.max(0, Rkr - Rov), 0) + ' Ом</b> ที่ความเร็วนี้ ⇒ เส้นตรงสนามชันกว่าลักษณะ ХХ ที่จุดกำเนิด ⇒ ไม่มีจุดตัด ⇒ ไม่กระตุ้นตัวเอง</span>' +
        '<span>⚠ E_ост = 4,5 В · E_max = 178 В · a = 0,60 А · c_ра = 0,024 А/А เป็นแบบจำลองของผู้เรียบเรียง (ข้อ 9.1–9.4) — ต้นฉบับไม่ให้ค่าพิกัดใด ๆ ของ ГПТ เลย</span>';
    }
  });
}


/* =====================================================================
   3) eoPZisn — ПЗ · แท่น ИСН บนคอนเวอร์เตอร์ลดแรงดัน (ПН / buck)
   สูตร: notes/PZ-SES-RN-ISN.md
     Ф-S1 f = 1/T           Ф-S2 T = t_з + t_р
     Ф-S4/S5  δU_вых(I) = [U_вых(I_min) − U_вых(I_max)]/U_вых.н · 100 %
     Ф-S6/S7  δU_вых(U) จากตาราง 5.3
     Ф-S8…S10 K_ст(U) = (δU_вх/U_вх.н) : (δU_вых/U_вых.н)
     Ф-S11 K_п = ΔU_вых/(2·U_вых)
     Ф-K1  q = t_и/T        Ф-K2 U_вых = q·U_вх
     Ф-K4  ΔI_L = U_вых·(1 − q)·T/L      Ф-K5 I_вых.гр = ΔI_L/2
     Ф-K6  ΔU_вых ≈ ΔI_L·[T/(8C) + r_ESR]
     Ф-K7…K9 P_вх · P_вых · η            Ф-K10 R_вых = |ΔU_вых/ΔI_вых|
     Ф-K11 U_вых(ПТ) = U_вх·q²/[q² + 2·L·I_вых/(U_вх·T)]
   พารามิเตอร์แท่นตามข้อ 19.1 (ค่าสมมติ): f = 20 кГц · L = 0,5 мГн · C = 47 мкФ ·
     r_ESR = 0,20 Ом · R_экв = 0,35 Ом · P₀ = 1,2 Вт · R_вых = 0,06 Ом · q_max = 0,90
   แบบจำลองการรักษาระดับ (ข้อ 19.5–19.7):
     U_вых = 13,60 − R_вых·I_вых − k_вх·(32 − U_вх)   โดย k_вх = 0,00267 В/В
     ตรวจแล้วให้ตาราง 5.2 และ 5.3 ตรงทุกช่อง (ดูบรรทัด «ตรวจ» ในผลลัพธ์)
   ===================================================================== */
function eogIsnPoint(Uvh, Iout, P) {
  /* คืนสถานะการทำงานหนึ่งจุดของแท่น ИСН */
  var Uout = 13.60 - P.Rout * Iout - P.kin * (32 - Uvh);
  var q = (Uout + P.Req * Iout) / Uvh;
  var brk = false;
  if (q > P.qmax) {                       // ถึงขีด ШИМ ⇒ срыв стабилизации
    brk = true;
    q = P.qmax;
    Uout = P.qmax * Uvh - P.Req * Iout;
  }
  var dIL = Uout * (1 - q) * P.T / P.L;   // Ф-K4
  var Igr = dIL / 2;                      // Ф-K5
  var dU = dIL * (P.T / (8 * P.C) + P.esr); // Ф-K6
  var Pout = Uout * Iout;                 // Ф-K8
  var Ploss = P.P0 + P.Req * Iout * Iout;
  var Pin = Pout + Ploss;
  var Iin = Pin / Uvh;                    // Ф-K7
  var eta = Pin > 0.001 ? Pout / Pin * 100 : 0; // Ф-K9
  var pt = Iout < Igr;                    // โหมดกระแสไม่ต่อเนื่อง
  if (pt) {                               // Ф-K11
    var den = q * q + 2 * P.L * Iout / (Uvh * P.T);
    Uout = den > 1e-9 ? Uvh * q * q / den : Uout;
  }
  return { U: Uout, q: q, dIL: dIL, Igr: Igr, dU: dU, Pout: Pout, Pin: Pin,
    Iin: Iin, eta: eta, pt: pt, srv: brk, Kp: dU / (2 * Uout) };
}

function eoPZisn(host) {
  buildDemo(host, {
    label: "ПЗ · ИСН (ПН-конвертор) · табл. 5.2 / 5.3 · Ф-K1…Ф-K12",
    title: "ป้อน U_вх และ I_н ของแท่น แล้วอ่าน q, U_вых, K_п, K_ст, η ทันที พร้อมเทียบกับตาราง 5.2 และ 5.3 ของระเบียบวิธี",
    ratio: 1.0,
    legend: '<span><i style="background:var(--accent)"></i>внешняя U_вых(I_вых) — табл. 5.2</span>' +
      '<span><i style="background:var(--crit)"></i>по входу U_вых(U_вх) — табл. 5.3</span>' +
      '<span><i style="background:var(--accent-2)"></i>η(I_вых)</span>' +
      '<span><i style="background:var(--ok)"></i>จุดทำงานปัจจุบัน</span>',
    controls: [
      { id: "Uvh", label: "U_вх, В — แรงดันขาเข้า (พิกัด 32 В)", min: 14, max: 36, step: 0.2, value: 32, fmt: function (v) { return eogF(v, 1); } },
      { id: "Iout", label: "I_вых, А — กระแสโหลด (ช่วงของงาน 0,5…2,5 А)", min: 0.1, max: 2.8, step: 0.05, value: 2, fmt: function (v) { return eogF(v, 2); } },
      { id: "L", label: "L, мГн — ตัวเหนี่ยวนำ L2 ของแท่น", min: 0.1, max: 2, step: 0.05, value: 0.5, fmt: function (v) { return eogF(v, 2); } },
      { id: "f", label: "f, кГц — ความถี่สวิตชิงของ РЭ", min: 5, max: 60, step: 1, value: 20, fmt: function (v) { return eogF(v, 0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      var P = { T: 1 / (s.f * 1000), L: s.L * 1e-3, C: 47e-6, esr: 0.20, Req: 0.35,
        P0: 1.2, Rout: 0.06, kin: 0.00267, qmax: 0.90 };
      var Uн = 13.5;                              // U_вых.н จากต้นฉบับ п. 2.3
      var cur = eogIsnPoint(s.Uvh, s.Iout, P);

      /* ---- เส้นโค้ง ---- */
      var i, x, ext = [], effc = [], inp = [], N = 100;
      for (i = 0; i <= N; i++) {
        x = 0.1 + (2.8 - 0.1) * i / N;
        ext.push([x, eogIsnPoint(s.Uvh, x, P).U]);
        effc.push([x, eogIsnPoint(s.Uvh, x, P).eta]);
      }
      for (i = 0; i <= N; i++) {
        x = 14 + (36 - 14) * i / N;
        inp.push([x, eogIsnPoint(x, s.Iout, P).U]);
      }
      /* จุดอ้างอิงจากตาราง 5.2 (ผู้เรียบเรียงคำนวณไว้ในโน้ต ข้อ 19.5) */
      var ref52 = [[0.5, 13.57], [1.0, 13.54], [1.5, 13.51], [2.0, 13.48], [2.5, 13.45]];
      var ref53 = [[32, 13.54], [28, 13.54], [24, 13.53], [20, 13.52], [17, 13.50]];

      /* ---- K_ст(U) ตาม Ф-S8: กวาด U_вх จาก 32 ถึง 17 В ---- */
      var Ua = eogIsnPoint(32, s.Iout, P).U, Ub = eogIsnPoint(17, s.Iout, P).U;
      var dUout = Math.abs(Ua - Ub), dUin = 32 - 17;
      var Kst = dUout > 1e-6 ? (dUin / 32) / (dUout / Uн) : Infinity;
      var dUrel = dUout / Uн * 100;
      /* U_вх min ที่การรักษาระดับหลุด (ข้อ 19.6/19.7) */
      var Uvmin = (eogIsnPoint(32, s.Iout, P).U + P.Req * s.Iout) / P.qmax;
      /* จุด η สูงสุดตามทฤษฎี: I = √(P₀/R_экв) */
      var Iopt = Math.sqrt(P.P0 / P.Req);

      /* ---- วาด ---- */
      var g = eogPlots(w, h, 3, { gap: 32, bottom: 28 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, 2.8, 12.8, 14.2);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 14, 36, 11, 14.2);   /* ย่านเดิม 8…15 กว้างเกินข้อมูลกว่าสองเท่า */
      var p3 = new Plot(ctx, g[2].x, g[2].y, g[2].w, g[2].h, 0, 2.8, 60, 100);

      p1.frame(eogTicksN(0, 2.8, 7), eogTicksN(12.8, 14.2, 4), "I_вых, А","U_вых, В");
      eogPanel(ctx, p1.x, p1.Y(Uн * 1.01), p1.w, p1.Y(Uн * 0.99) - p1.Y(Uн * 1.01), wash);
      eogRef(ctx, p1, Uн, ink3, "U_вых.н = 13,5 В", fs, [3, 3]);
      p1.clip(function () { p1.line(ext, acc, 2.2); p1.dots(ref52, ink3, 3); });
      eogVRef(ctx, p1, cur.Igr, crit, "I_гр = " + eogF(cur.Igr, 2) + " А", fs, [4, 4]);
      eogMark(ctx, p1, s.Iout, cur.U, ok, eogF(cur.U, 2) + " В", fs);
      eogTag(ctx, p1, "1) Внешняя  U_вых = f(I_вых)  при  U_вх = " + eogF(s.Uvh, 1) + " В — จุดเทา = ตาราง 5.2", acc, fs);

      p2.frame(eogTicksN(14, 36, 6), eogTicksN(11, 14.2, 4), "U_вх, В", "U_вых, В");
      p2.clip(function () { p2.line(inp, crit, 2.2); p2.dots(ref53, ink3, 3); });
      eogVRef(ctx, p2, Uvmin, acc2, "срыв стабилизации " + eogF(Uvmin, 1) + " В", fs, [4, 4]);
      eogMark(ctx, p2, s.Uvh, cur.U, ok, eogF(cur.U, 2) + " В", fs);
      eogTag(ctx, p2, "2) По входу  U_вых = f(U_вх)  при  I_вых = " + eogF(s.Iout, 2) + " А — จุดเทา = ตาราง 5.3", crit, fs);

      p3.frame(eogTicksN(0, 2.8, 7), eogTicksN(60, 100, 4), "I_вых, А","η, %");
      p3.clip(function () { p3.line(effc, acc2, 2.2); });
      eogVRef(ctx, p3, Iopt, ok, "I = √(P₀/R_экв) = " + eogF(Iopt, 2) + " А", fs, [4, 4]);
      eogMark(ctx, p3, s.Iout, cur.eta, ok, eogF(cur.eta, 1) + " %", fs, true);
      eogTag(ctx, p3, "3) КПД  η = P_вых/P_вх  (Ф-K9) — จุดสูงสุดอยู่ที่ P₀ = R_экв·I²", acc2, fs);

      /* ---- ตรวจกับตาราง 5.2 แถวที่ 4 (I = 2,0 А, U_вх = 32 В) ---- */
      var chk = eogIsnPoint(32, 2.0, P);
      var okChk = Math.abs(chk.U - 13.48) < 0.011 && Math.abs(chk.q - 0.443) < 0.002 &&
        Math.abs(chk.Iin - 0.924) < 0.005 && Math.abs(chk.eta - 91.2) < 0.15;

      readout.innerHTML =
        'q = (U<sub>вых</sub> + R<sub>экв</sub>·I)/U<sub>вх</sub> = <b class="' + (cur.srv ? "bad" : "good") + '">' + eogF(cur.q, 3) + '</b>' + (cur.srv ? ' — ถึง q_max = 0,90 แล้ว <b class="bad">срыв стабилизации</b>' : '') +
        '<span>U<sub>вых</sub> = <b>' + eogF(cur.U, 2) + ' В</b> · I<sub>вх</sub> = <b>' + eogF(cur.Iin, 3) + ' А</b> · P<sub>вых</sub> = <b>' + eogF(cur.Pout, 2) + ' Вт</b> · P<sub>вх</sub> = <b>' + eogF(cur.Pin, 2) + ' Вт</b> · η = <b>' + eogF(cur.eta, 1) + ' %</b></span>' +
        '<span>ΔI<sub>L</sub> = U<sub>вых</sub>(1−q)T/L = <b>' + eogF(cur.dIL, 3) + ' А</b> ⇒ I<sub>вых.гр</sub> = ΔI<sub>L</sub>/2 = <b>' + eogF(cur.Igr, 3) + ' А</b> ⇒ โหมด <b class="' + (cur.pt ? "bad" : "good") + '">' + (cur.pt ? "ПТ (กระแสไม่ต่อเนื่อง)" : "НТ (กระแสต่อเนื่อง)") + '</b>  (Ф-K4, Ф-K5)</span>' +
        '<span>ΔU<sub>вых</sub> = ΔI<sub>L</sub>·[T/(8C) + r<sub>ESR</sub>] = <b>' + eogF(cur.dU, 3) + ' В</b> ⇒ K<sub>п</sub> = ΔU/(2U) = <b>' + eogF(cur.Kp * 100, 2) + ' %</b>  (Ф-K6, Ф-S11)</span>' +
        '<span>K<sub>ст</sub>(U) = (δU<sub>вх</sub>/32) : (δU<sub>вых</sub>/13,5) = (15/32):(' + eogF(dUout, 3) + '/13,5) = <b class="good">' + (isFinite(Kst) ? eogF(Kst, 0) : "∞") + '</b> · δU<sub>вых</sub>(U) = <b>' + eogF(dUrel, 2) + ' %</b>  (Ф-S6…Ф-S8)</span>' +
        '<span>U<sub>вх min</sub> ที่การรักษาระดับหลุด = (U<sub>вых</sub> + R<sub>экв</sub>·I)/q<sub>max</sub> = <b>' + eogF(Uvmin, 1) + ' В</b> — โหลดยิ่งมาก ยิ่งหลุดเร็ว (โน้ตให้ 15,4 В ที่ 1 А และ 15,8 В ที่ 2 А)</span>' +
        '<span>R<sub>вых</sub> = |ΔU<sub>вых</sub>/ΔI<sub>вых</sub>| = <b>0,06 Ом</b> ⇒ δU<sub>вых</sub>(I) ทั้งช่วง 0,5…2,5 А = <b>' + eogF(Math.abs(eogIsnPoint(s.Uvh, 0.5, P).U - eogIsnPoint(s.Uvh, 2.5, P).U) / Uн * 100, 2) + ' %</b>  (Ф-K10, Ф-S4)</span>' +
        '<span>ตรวจกับตาราง 5.2 แถวที่ 4 (U<sub>вх</sub> = 32 В, I<sub>вых</sub> = 2,0 А): U<sub>вых</sub> = ' + eogF(chk.U, 2) + ' В · q = ' + eogF(chk.q, 3) + ' · I<sub>вх</sub> = ' + eogF(chk.Iin, 3) + ' А · η = ' + eogF(chk.eta, 1) + ' % ⇒ <b class="' + (okChk ? "good" : "bad") + '">' + (okChk ? "ตรงกับโน้ตทุกช่อง (13,48 · 0,443 · 0,924 · 91,2)" : "ไม่ตรง — ตรวจพารามิเตอร์แท่น") + '</b></span>' +
        '<span>กับดักที่เสียคะแนนบ่อย: <b>q ของ buck</b> = สัดส่วนเวลาเปิด ต่างจาก <b>скважность</b> ของอินเวอร์เตอร์ ซึ่งเป็นส่วนกลับ · และ K<sub>п</sub> ในงานนี้ใช้นิยาม ΔU/(2U) ไม่ใช่ 2/(m²−1)</span>' +
        '<span>⚠ L, C, r<sub>ESR</sub>, R<sub>экв</sub>, P₀, f เป็นค่าสมมติของผู้เรียบเรียง (ข้อ 19.1) — ต้นฉบับไม่ให้พารามิเตอร์แท่นเลย ต้องวัดเองหรือถามอาจารย์</span>';
    }
  });
}


/* =====================================================================
   4) eoPZnksn — ПЗ · แท่น НКСН (непрерывный компенсационный стабилизатор)
   สูตร: notes/PZ-KO2657.md — Рис. 4.8 (สูตรเดียวที่ต้นฉบับให้ครบ)
     K_п.вх  = ΔU_вх /(2·U_вх ср)
     K_п.вых = ΔU_вых/(2·U_вых ср)
     K_сгп   = K_п.вх / K_п.вых
     P_вх = U_вх·I_вх · P_вых = U_вых·I_вых · η = P_вых/P_вх   (табл. 4.5 / бланк Т4)
   ผู้เรียบเรียงเสริม (จากข้อ «สูตรที่ต้องใช้แต่เอกสารไม่ให้»):
     K_ст.u = (ΔU_вх/U_вх.н)/(ΔU_вых/U_вых.н) · R_вых = ΔU_вых/ΔI_вых
     P_РЭ = (U_вх − U_вых)·I_н  — กำลังที่เผาทิ้งบนตัวควบคุม
   แบบจำลองการกดริปเปิล: ลูป ООС ลดริปเปิลลง K_подавл เท่า ⇒
     ΔU_вых = ΔU_вх/K_подавл  ⇒  K_сгп = K_подавл·U_вых/U_вх
     ตรวจกับตัวอย่างของโน้ต: 1,80/0,020 = 90 · 10/18 ⇒ K_сгп = 50 ✔
     ตรวจกับตัวอย่าง вар. 5 ในบทเรียน: 4,00/0,040 = 100 · 18/26 ⇒ K_сгп = 69,2 ✔
   ตาราง 4.2 (8 вариантов) คัดจากต้นฉบับตรง ๆ — ป้ายชื่อแถวเป็นการกู้คืนตาม «ข้อสันนิษฐาน B»
   ===================================================================== */
var EOG_NKSN = [
  /* U_вых.н · U_вх.н · U_кэ.min · ΔU_вх⁺ · ΔU_вх⁻ · I_вых.н */
  [10, 18, 4, 6, 4, 4], [12, 20, 4, 6, 4, 3], [14, 22, 4, 6, 4, 2], [16, 24, 4, 6, 4, 2],
  [18, 26, 4, 6, 4, 3], [20, 28, 4, 6, 4, 3], [22, 30, 4, 6, 4, 3], [24, 32, 4, 6, 4, 2]
];

function eoPZnksn(host) {
  buildDemo(host, {
    label: "ПЗ · НКСН (КО 2657) · рис. 4.8 · табл. 4.2",
    title: "เลือก вариант ของตัวเอง แล้วดูริปเปิลขาเข้า–ขาออกในเวลาจริง พร้อมค่า K_сгп กำลังที่ไหม้บน РЭ และประสิทธิภาพ",
    ratio: 0.86,
    legend: '<span><i style="background:var(--accent)"></i>u_вх(t) พร้อมริปเปิล</span>' +
      '<span><i style="background:var(--ok)"></i>u_вых(t) หลังการกด</span>' +
      '<span><i style="background:var(--crit)"></i>P_РЭ — กำลังที่ไหม้บนตัวควบคุม</span>' +
      '<span><i style="background:var(--accent-2)"></i>η</span>',
    controls: [
      { id: "vr", label: "вариант ของ табл. 4.2 (1–8)", min: 1, max: 8, step: 1, value: 1, fmt: function (v) { return eogF(v, 0); } },
      { id: "Uvh", label: "U_вх, В — แรงดันขาเข้าที่ตั้งจริง", min: 10, max: 40, step: 0.5, value: 18, fmt: function (v) { return eogF(v, 1); } },
      { id: "Iout", label: "I_вых, А — กระแสโหลด", min: 0.5, max: 4.5, step: 0.1, value: 4, fmt: function (v) { return eogF(v, 1); } },
      { id: "dUin", label: "ΔU_вх, В — размах ริปเปิลขาเข้า (บล็อก БП / Q2)", min: 0.05, max: 5, step: 0.05, value: 1.8, fmt: function (v) { return eogF(v, 2); } },
      { id: "Kp", label: "K_подавл — อัตราการกดริปเปิลของลูป ООС", min: 10, max: 300, step: 5, value: 90, fmt: function (v) { return eogF(v, 0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      var V = EOG_NKSN[Math.round(s.vr) - 1];
      var Uoutn = V[0], Uinn = V[1], Ukemin = V[2], dUp = V[3], dUm = V[4], Inn = V[5];
      var UinMax = Uinn + dUp, UinMin = Uinn - dUm;
      var Uin = s.Uvh, I = s.Iout, dUin = s.dUin, K = s.Kp;

      /* การรักษาระดับทำงานได้ตราบที่ตัวควบคุมยังมีแรงดันคร่อมเหลือ ≥ U_кэ.min */
      var Uke = Uin - Uoutn;
      var alive = Uke >= Ukemin;
      var Uout = alive ? Uoutn : Math.max(0, Uin - Ukemin);   // หลุดการรักษาระดับ ⇒ ตามขาเข้า
      var dUout = alive ? dUin / K : dUin * 0.9;              // ริปเปิลทะลุออกเกือบหมดเมื่อหลุด

      var KpIn = dUin / (2 * Uin);
      var KpOut = dUout / (2 * Uout);
      var Ksgp = KpOut > 1e-12 ? KpIn / KpOut : Infinity;

      var Iu = 0.10;                       // กระแสของวงจรควบคุม (ตัวอย่างข้อ ЭТАП 8: 4,10 − 4,00)
      var Pout = Uout * I, Pin = Uin * (I + Iu);
      var eta = Pin > 0.001 ? Pout / Pin * 100 : 0;
      var Pre = (Uin - Uout) * I;
      var Ppot = Pin - Pout;

      /* ---- แผงที่ 1: รูปคลื่นริปเปิล (ริปเปิล 100 Гц จากวงจรเรียงกระแสสองครึ่งคลื่น) ---- */
      var N = 400, i, x, uin = [], uout = [], tmax = 0.03, tms = tmax * 1000;   /* แกนเวลาเป็น มิลลิวินาที เพื่อไม่ให้ป้ายแกนถูกปัดเป็นเลขซ้ำ */
      for (i = 0; i <= N; i++) {
        x = tmax * i / N;
        uin.push([x * 1000, Uin + dUin / 2 * Math.sin(2 * Math.PI * 100 * x)]);
        uout.push([x * 1000, Uout + dUout / 2 * Math.sin(2 * Math.PI * 100 * x - 0.5)]);
      }
      /* ---- แผงที่ 2: กำลังและ КПД ตลอดพิสัย U_вх ที่อนุญาต ---- */
      var pre = [], effc = [];
      for (i = 0; i <= 100; i++) {
        x = 10 + 30 * i / 100;
        var uo = (x - Uoutn) >= Ukemin ? Uoutn : Math.max(0, x - Ukemin);
        pre.push([x, (x - uo) * I]);
        effc.push([x, x > 0.1 ? uo * I / (x * (I + Iu)) * 100 : 0]);
      }

      var g = eogPlots(w, h, 2, { gap: 34, bottom: 28 });
      var ytop = Math.max(Uin + dUin, Uinn + dUp) * 1.08;
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, tms, 0, ytop);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 10, 40, 0, Math.max(60, Math.max(Pre * 1.4, 100)));

      p1.frame(eogTicksN(0, tms, 6), eogTicksN(0, ytop, 4), "t, мс", "u, В");
      eogPanel(ctx, p1.x, p1.Y(Uin + dUin / 2), p1.w, p1.Y(Uin - dUin / 2) - p1.Y(Uin + dUin / 2), wash);
      p1.clip(function () { p1.line(uin, acc, 2); p1.line(uout, ok, 2.2); });
      eogRef(ctx, p1, Uin, ink3, "U_вх ср = " + eogF(Uin, 1) + " В (PV1)", fs, [3, 3]);
      eogRef(ctx, p1, Uout, ink3, "U_вых ср = " + eogF(Uout, 2) + " В (PV2)", fs, [3, 3]);
      eogTag(ctx, p1, "1) Осциллограммы  ΔU_вх = " + eogF(dUin, 2) + " В  ⇒  ΔU_вых = " + eogF(dUout, 4) + " В", acc, fs);
      eogTag(ctx, p1, alive ? "стабилизация в норме" : "СРЫВ: U_кэ < U_кэ.min", alive ? ok : crit, fs, true);

      p2.frame(ticks(10, 40, 6), eogTicksN(0, Math.max(60, Math.max(Pre * 1.4, 100)), 4), "U_вх, В","P, Вт  /  η, %");
      p2.clip(function () { p2.line(pre, crit, 2.2); p2.line(effc, acc2, 2, [6, 3]); });
      eogVRef(ctx, p2, UinMin, ok, "U_вх min = " + eogF(UinMin, 0) + " В", fs, [4, 4]);
      eogVRef(ctx, p2, UinMax, ok, "U_вх max = " + eogF(UinMax, 0) + " В", fs, [4, 4]);
      eogMark(ctx, p2, Uin, Pre, crit, "P_РЭ = " + eogF(Pre, 1) + " Вт", fs);
      eogMark(ctx, p2, Uin, eta, acc2, "η = " + eogF(eta, 1) + " %", fs, true);
      eogTag(ctx, p2, "2) P_РЭ = (U_вх − U_вых)·I_н  และ  η  ตลอดพิสัยแรงดันขาเข้าที่โจทย์อนุญาต", crit, fs);

      readout.innerHTML =
        'Вариант ' + Math.round(s.vr) + ': U<sub>вых.н</sub> = <b>' + Uoutn + ' В</b> · U<sub>вх.н</sub> = <b>' + Uinn + ' В</b> · I<sub>вых.н</sub> = <b>' + Inn + ' А</b> · U<sub>вх</sub> ที่อนุญาต = <b>' + UinMin + '…' + UinMax + ' В</b>' +
        '<span>K<sub>п.вх</sub> = ΔU<sub>вх</sub>/(2·U<sub>вх ср</sub>) = ' + eogF(dUin, 2) + '/(2·' + eogF(Uin, 1) + ') = <b>' + eogF(KpIn * 100, 3) + ' %</b></span>' +
        '<span>K<sub>п.вых</sub> = ΔU<sub>вых</sub>/(2·U<sub>вых ср</sub>) = ' + eogF(dUout, 4) + '/(2·' + eogF(Uout, 2) + ') = <b>' + eogF(KpOut * 100, 4) + ' %</b></span>' +
        '<span>K<sub>сгп</sub> = K<sub>п.вх</sub>/K<sub>п.вых</sub> = <b class="good">' + (isFinite(Ksgp) ? eogF(Ksgp, 1) : "∞") + '</b> ⇒ กดริปเปิลได้ <b>' + (isFinite(Ksgp) ? eogF(Ksgp, 0) : "∞") + ' เท่า</b> — นี่คือค่าที่ต้องกรอกทั้งแถว «Норм. работа, БП откл» และ «Работа с БП»</span>' +
        '<span>P<sub>вых</sub> = <b>' + eogF(Pout, 1) + ' Вт</b> · P<sub>вх</sub> = <b>' + eogF(Pin, 1) + ' Вт</b> · η = <b class="' + (eta < 60 ? "bad" : "") + '">' + eogF(eta, 1) + ' %</b> · P<sub>пот</sub> = <b>' + eogF(Ppot, 1) + ' Вт</b></span>' +
        '<span>P<sub>РЭ</sub> = (U<sub>вх</sub> − U<sub>вых</sub>)·I = <b class="bad">' + eogF(Pre, 1) + ' Вт</b> = <b>' + eogF(Ppot > 0.01 ? Pre / Ppot * 100 : 0, 1) + ' %</b> ของการสูญเสียทั้งหมด ⇒ ต้องมีแผงระบายความร้อน — <b>ข้อเสียหลักของ НКСН</b></span>' +
        '<span>U<sub>кэ</sub> = U<sub>вх</sub> − U<sub>вых</sub> = <b class="' + (alive ? "good" : "bad") + '">' + eogF(Uke, 1) + ' В</b> เทียบเกณฑ์ U<sub>кэ.min</sub> = ' + Ukemin + ' В ⇒ ' + (alive ? "ตัวควบคุมยังอยู่ในย่านเชิงเส้น" : "หลุดการรักษาระดับ — แรงดันขาออกไหลตามขาเข้า") + '</span>' +
        '<span>ความร้อนสูงสุดเกิดที่ <b>U<sub>вх max</sub> = ' + UinMax + ' В</b> ไม่ใช่ที่ U<sub>вх min</sub> — P<sub>РЭ</sub> ที่นั่นเท่ากับ <b>' + eogF((UinMax - Uoutn) * I, 1) + ' Вт</b> (ข้อผิดพลาดยอดนิยมคือคิดกลับด้าน)</span>' +
        '<span>ตรวจกับตัวอย่างของโน้ต (U<sub>вх</sub> = 18 В · ΔU<sub>вх</sub> = 1,80 В · U<sub>вых</sub> = 10 В · ΔU<sub>вых</sub> = 0,020 В): K<sub>п.вх</sub> = 5,0 % · K<sub>п.вых</sub> = 0,1 % · <b>K<sub>сгп</sub> = 50</b> — ตั้ง вариант 1 · K<sub>подавл</sub> = 90 แล้วจะได้ค่านี้พอดี</span>' +
        '<span>กับดัก: <b>K<sub>сгп</sub> ไม่ใช่ K<sub>п</sub></b> — K<sub>п</sub> คือระดับริปเปิลของสัญญาณหนึ่ง ๆ ส่วน K<sub>сгп</sub> คืออัตราส่วนของ K<sub>п</sub> สองค่า (เอกสาร Конспект ข้อ 20 ตีความผิด)</span>' +
        '<span>⚠ ป้ายชื่อแถวของ табл. 4.2 <b>หายไปในต้นฉบับทั้งฉบับ</b> — การตีความ U<sub>вых.н</sub>/U<sub>вх.н</sub>/U<sub>кэ.min</sub>/ΔU<sub>вх</sub>⁺/ΔU<sub>вх</sub>⁻/I<sub>вых.н</sub> เป็น «ข้อสันนิษฐาน B» ของผู้เรียบเรียง ต้องถามอาจารย์ยืนยัน · K<sub>подавл</sub> และ I<sub>у</sub> = 0,1 А เป็นค่าสมมติเช่นกัน</span>';
    }
  });
}


/* =====================================================================
   5) eoPZpss — ПЗ · ПСС 5805.1 (ТПС 28,5/120) — อินเวอร์เตอร์เรโซแนนซ์
                 + วงจรรักษาระดับด้วยการเปลี่ยนความถี่
   ข้อมูลเชิงตัวเลขทั้งหมดจาก notes/PZ-PSS5805.md (уставки และ ТТХ ของต้นฉบับ):
     380 ± 19 В (ชั่วคราว ± 57 В 3 นาที) · 50 Гц · U_вых = 28,5 В · ความแม่น ± 1 В
     пульсации 400 мВ · I_н = 120 А (180 А ได้ 1 วินาที โดย U ลงถึง 22 В)
     БКН min 20 ± 1 В (t = 2 с) · БКН max 34 ± 1 В (t = 0,25 с)
     cos φ ≥ 0,72 · КПД ≥ 0,7 · f инверторов = 3 кГц (เปลี่ยนได้ระหว่างรักษาระดับ)
     U ที่ขาเข้าอินเวอร์เตอร์ ≈ 600 В
   ขั้นตอนที่จำลอง (АЛГОРИТМ резонансного инвертора + контур стабилизации):
     ① VS1 เปิด → C5 ประจุผ่านวงจรสั่น C5-L6-L8 ⇒ ครึ่งคลื่นบวกเกือบไซน์
     ② i = 0 ⇒ VS1 ปิดเอง (естественная коммутация)
     ③ ПАУЗА — ความยาวกำหนดโดยความถี่ของ УЗГ  ← องค์ประกอบควบคุมเพียงตัวเดียว
     ④ VS2 เปิด → C5 คายลง TV1 ⇒ ครึ่งคลื่นลบ
   สูตรที่ใช้ (บทเรียนกลุ่ม H ให้ไว้เป็น «ผู้เรียบเรียงเสริม» — ห้ามใช้ในการสอบโดยไม่ถามอาจารย์):
     U_вых.д ∝ √( (t_и⁺ + t_и⁻)/T ) = √(2·t_и·f)
     U_d = 1,35·U_л (ฟิลเตอร์เหนี่ยวนำ) หรือ → √2·U_л (โหมดตัวเก็บประจุ)
     ΔU_л = I_н·R_л  ·  U_ШТПС = U_потр + ΔU_л   (ตัวอย่าง В2: 100 А × 0,05 Ом ⇒ 33 В)
   ===================================================================== */
function eoPZpss(host) {
  buildDemo(host, {
    label: "ПЗ · ПСС 5805.1 · рис. 5.2 / 5.3 · пример В2",
    title: "ปรับกระแสโหลดและแรงดันเครือข่าย แล้วดูวงจรรักษาระดับเปลี่ยนความถี่อินเวอร์เตอร์เพื่อดึงแรงดันที่ผู้ใช้ไฟกลับมาที่ 28,5 В",
    ratio: 0.9,
    legend: '<span><i style="background:var(--accent)"></i>i ผ่าน VS1 (ครึ่งคลื่นบวก)</span>' +
      '<span><i style="background:var(--accent-2)"></i>i ผ่าน VS2 (ครึ่งคลื่นลบ)</span>' +
      '<span><i style="background:var(--ink-3)"></i>ПАУЗА — องค์ประกอบควบคุม</span>' +
      '<span><i style="background:var(--ok)"></i>ช่วงที่ БКН ยอมรับ 20…34 В</span>',
    controls: [
      { id: "In", label: "I_н, А — กระแสโหลด (พิกัด 120 А · 180 А ได้ 1 วินาที)", min: 0, max: 200, step: 5, value: 100, fmt: function (v) { return eogF(v, 0); } },
      { id: "Rl", label: "R_л, Ом — ความต้านทานสายเคเบิล ПСС → потребитель", min: 0, max: 0.12, step: 0.005, value: 0.05, fmt: function (v) { return eogF(v, 3); } },
      { id: "Uset", label: "U_сети, В — แรงดันสามเฟสที่ทางเข้า (พิกัด 380 ± 19 В)", min: 300, max: 440, step: 2, value: 380, fmt: function (v) { return eogF(v, 0); } },
      { id: "Uz", label: "U_потр ที่ต้องการรักษา, В", min: 26, max: 31, step: 0.1, value: 28.5, fmt: function (v) { return eogF(v, 1); } }
    ],
    buttons: [
      { id: "cap", label: "ёмкостный режим фильтра (U_d = √2·U_л)", toggle: true, value: true },
      { id: "auto", label: "контур стабилизации включён", toggle: true, value: true }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      /* ---- ข้อมูลของเครื่องตามต้นฉบับ ---- */
      var Un = 28.5, tol = 1, bknMin = 20, bknMax = 34, Inom = 120, fNom = 3000;
      var tI = 100e-6;                            /* ครึ่งคลื่นเรโซแนนซ์: t_и = π√(L·C) — ตรึงโดย C5, L6, L8
                                                     ค่านี้เลือกให้ q = 2·t_и·f = 0,60 ที่ f = 3 кГц (ผู้เรียบเรียง) */
      var Kt = 0.0793;                            /* อัตราส่วนรวม TV1 + วงจรเรียงกระแสขาออก (ปรับให้ตัวอย่าง В2 ตรง) */
      var Ud = (s.cap ? Math.SQRT2 : 1.35) * s.Uset;
      var dUl = s.In * s.Rl;                      /* แรงดันตกในสายเคเบิล */
      var Uzad = s.Uz + dUl;                      /* แรงดันที่ ШТПС ต้องมี (การชดเชยของ БК1/БК2) */

      /* วงจรรักษาระดับ: หา f ที่ทำให้ U_ШТПС = U_зад ; ไม่มีลูป ⇒ f = 3 кГц ตายตัว */
      var fReq = Uzad * Uzad / (Kt * Kt * Ud * Ud * 2 * tI);
      var fLim = 1 / (2 * tI);                    /* เพดาน: ครึ่งคลื่นสองลูกเต็มคาบ ⇒ ไม่มีพัก */
      var f = s.auto ? Math.min(fLim, Math.max(600, fReq)) : fNom;
      var q = Math.min(1, 2 * tI * f);
      var Uw = Kt * Ud * Math.sqrt(q);            /* แรงดันบนบัส ШТПС */
      /* ข้อจำกัดกระแส: УОТ สั่ง запрет เมื่อ I_н เกินพิกัด (180 А ⇒ U ลงถึง 22 В) */
      var limited = s.In > Inom;
      if (limited) Uw = Math.min(Uw, 28.5 - (s.In - Inom) / 60 * 6.5);
      var Upotr = Uw - dUl;

      var bknTrip = Uw > bknMax || Uw < bknMin;
      var inTol = Math.abs(Upotr - Un) <= tol;
      var P2 = Uw * s.In;
      var eta = 0.72;                             /* ค่าที่ต้นฉบับรับประกัน ≥ 0,7 */

      /* ---- แผงที่ 1: диаграмма токов и напряжения (рис. 5.3) ---- */
      var T = 1 / f, N = 600, i, x, iv1 = [], iv2 = [], uinv = [];
      for (i = 0; i <= N; i++) {
        x = 2.2 * T * i / N;
        var ph = x % T, a1 = 0, a2 = 0;
        if (ph < tI) a1 = Math.sin(Math.PI * ph / tI);
        else if (ph >= T / 2 && ph < T / 2 + tI) a2 = -Math.sin(Math.PI * (ph - T / 2) / tI);
        iv1.push([x * 1e6, a1]);
        iv2.push([x * 1e6, a2]);
        uinv.push([x * 1e6, a1 + a2]);
      }

      var g = eogPlots(w, h, 2, { gap: 36, bottom: 28 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, 2.2 * T * 1e6, -1.25, 1.25);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, 200, 16, 38);

      p1.frame(eogTicksN(0, 2.2 * T * 1e6, 6), eogTicksN(-1, 1, 4), "t, мкс","i / i_m");
      /* แรเงาช่วงพัก */
      ctx.save();
      ctx.fillStyle = wash;
      for (i = 0; i < 3; i++) {
        var pa = (i * T + tI) * 1e6, pb = (i * T + T / 2) * 1e6;
        var pc = (i * T + T / 2 + tI) * 1e6, pd = ((i + 1) * T) * 1e6;
        if (pa < p1.xmax) ctx.fillRect(p1.X(Math.min(pa, p1.xmax)), p1.y, Math.max(0, p1.X(Math.min(pb, p1.xmax)) - p1.X(Math.min(pa, p1.xmax))), p1.h);
        if (pc < p1.xmax) ctx.fillRect(p1.X(Math.min(pc, p1.xmax)), p1.y, Math.max(0, p1.X(Math.min(pd, p1.xmax)) - p1.X(Math.min(pc, p1.xmax))), p1.h);
      }
      ctx.restore();
      p1.clip(function () {
        p1.line(uinv, ink3, 1.2, [3, 3]);
        p1.line(iv1, acc, 2.2);
        p1.line(iv2, acc2, 2.2);
      });
      eogTag(ctx, p1, "1) Резонансный инвертор: f = " + eogF(f / 1000, 2) + " кГц · t_и = 100 мкс · пауза = " + eogF((T / 2 - tI) * 1e6, 0) + " мкс · q = 2·t_и·f = " + eogF(q, 3), acc, fs);
      eogTag(ctx, p1, "ток спадает до нуля ⇒ VS закрывается сам", ink3, fs, true);

      /* ---- แผงที่ 2: แรงดันบัสและเกณฑ์ป้องกันตามกระแสโหลด ---- */
      var curve = [], curveP = [];
      for (i = 0; i <= 100; i++) {
        x = 200 * i / 100;
        var d = x * s.Rl, uz = s.Uz + d;
        var fr = s.auto ? Math.min(fLim, Math.max(600, uz * uz / (Kt * Kt * Ud * Ud * 2 * tI))) : fNom;
        var uu = Kt * Ud * Math.sqrt(Math.min(1, 2 * tI * fr));
        if (x > Inom) uu = Math.min(uu, 28.5 - (x - Inom) / 60 * 6.5);
        curve.push([x, uu]);
        curveP.push([x, uu - d]);
      }
      p2.frame(eogTicksN(0, 200, 8), eogTicksN(16, 38, 4), "I_н, А","U, В");
      eogPanel(ctx, p2.x, p2.Y(bknMax), p2.w, p2.Y(bknMin) - p2.Y(bknMax), wash);
      eogRef(ctx, p2, bknMax, crit, "БКН max = 34 ± 1 В (t = 0,25 с)", fs);
      eogRef(ctx, p2, bknMin, crit, "БКН min = 20 ± 1 В (t = 2 с)", fs);
      eogRef(ctx, p2, Un, ok, "28,5 ± 1 В — точка стабилизации", fs, [3, 3]);
      p2.clip(function () { p2.line(curve, acc, 2.2); p2.line(curveP, ok, 2.2, [6, 3]); });
      eogVRef(ctx, p2, Inom, ink3, "I_н.ном = 120 А", fs, [4, 4]);
      eogMark(ctx, p2, s.In, Uw, acc, "U_ШТПС = " + eogF(Uw, 1) + " В", fs);
      eogMark(ctx, p2, s.In, Upotr, ok, "U_потр = " + eogF(Upotr, 1) + " В", fs, true);
      eogTag(ctx, p2, "2) U_ШТПС (ทึบ) และ U ที่ входе потребителя (ประ) — ระยะห่างคือ ΔU_л = I_н·R_л", acc, fs);

      readout.innerHTML =
        'U<sub>ШТПС</sub> = <b>' + eogF(Uw, 2) + ' В</b> · ΔU<sub>л</sub> = I<sub>н</sub>·R<sub>л</sub> = <b>' + eogF(dUl, 2) + ' В</b> · U<sub>потр</sub> = <b class="' + (inTol ? "good" : "bad") + '">' + eogF(Upotr, 2) + ' В</b> (เกณฑ์ 28,5 ± 1 В)' +
        '<span>f อินเวอร์เตอร์ = <b>' + eogF(f / 1000, 2) + ' кГц</b> (พิกัด 3 кГц) · ความยาวพัก = <b>' + eogF((T / 2 - tI) * 1e6, 0) + ' мкс</b> ⇒ q = <b>' + eogF(q, 3) + '</b> ⇒ U<sub>вых.д</sub> ∝ √q = <b>' + eogF(Math.sqrt(q), 3) + '</b></span>' +
        '<span>U<sub>d</sub> ที่ขาเข้าอินเวอร์เตอร์ = ' + (s.cap ? "√2" : "1,35") + '·U<sub>л</sub> = <b>' + eogF(Ud, 0) + ' В</b> — ต้นฉบับระบุ «≈ 600 В» ซึ่งได้เฉพาะเมื่อฟิลเตอร์ทำงานแบบ<b>ตัวเก็บประจุ</b> หรือแรงดันเครือข่ายอยู่ขอบบน 437 В (ที่ 380 В กับฟิลเตอร์เหนี่ยวนำ คำนวณได้ 513 В)</span>' +
        '<span>สถานะการป้องกัน: ' + (bknTrip ? '<b class="bad">БКН สั่งตัดโหลด</b> — แรงดันบัสออกนอกช่วง 20…34 В' : '<b class="good">БКН ปกติ</b>') + ' · ' + (limited ? '<b class="bad">УОТ จำกัดกระแส</b> — I_н เกิน 120 А (โหมด 180 А อนุญาตเพียง 1 วินาที โดยแรงดันลงถึง 22 В)' : 'УОТ ไม่ทำงาน') + '</span>' +
        '<span>P₂ = U·I = <b>' + eogF(P2 / 1000, 2) + ' кВт</b> · КПД ≥ <b>' + eogF(eta * 100, 0) + ' %</b> · cos φ ≥ <b>0,72</b> (ค่ารับประกันตามต้นฉบับ)</span>' +
        '<span>ลำดับการรักษาระดับ 5 ขั้น: <b>① ИЗМЕРЕНИЕ</b> (U<sub>вых.ТПС</sub> + поправка จาก БК1/БК2 ที่ СО จำกัดไว้) → <b>② СРАВНЕНИЕ ใน УФСР</b> กับแรงดันอ้างอิง → <b>③ УЗГ</b> ออกพัลส์ความถี่ตามสัญญาณ → <b>④ ФДИ → РУ → УФ1/УФ2</b> ไปยัง VS1…VS4 → <b>⑤ ЭФФЕКТ</b>: ความถี่ขึ้น ⇒ ช่วงพักสั้นลง ⇒ ค่ายังผลของแรงดันขาออกสูงขึ้น</span>' +
        '<span>ตรวจกับตัวอย่าง В2 ของต้นฉบับ (I<sub>н</sub> = 100 А · R<sub>л</sub> = 0,05 Ом · U<sub>потр</sub> = 28 В): ΔU<sub>л</sub> = 5 В ⇒ <b>U<sub>ШТПС</sub> = 33 В</b> — ตั้งสไลเดอร์ตามนี้แล้วจะเห็นว่าค่า 33 В เหลือระยะถึง БКН max เพียง 1 В จึงต้องมี <b>схема ограничения (СО)</b> จำกัดการชดเชยของ БК1/БК2</span>' +
        '<span>ความต่างที่ถูกถามบ่อย: ПСС 5805.<b>1</b> รักษาแรงดันด้วยการ <b>เปลี่ยนความถี่อินเวอร์เตอร์</b> (воздействие на параметры инвертора) ส่วน ПСС 5805.<b>3</b> รักษาด้วยการ <b>เปลี่ยนมุม α ของบล็อกวาล์ว</b> (воздействие на параметры блока вентилей)</span>' +
        '<span>⚠ t_и = 100 мкс · K_т = 0,0793 และความสัมพันธ์ U ∝ √q เป็นแบบจำลองของผู้เรียบเรียง — ต้นฉบับให้เพียงประโยค «частота ↑ ⇒ U ↑» ไม่มีสูตร <b>ห้ามใช้เป็นสูตรคำนวณในการสอบโดยไม่ถามอาจารย์</b></span>';
    }
  });
}


/* =====================================================================
   6) eoLRdpt — ЛР № 1 «Испытание ДПТ независимого возбуждения»
   สูตร: notes/LR-A.md ข้อ 1.4
     Ф1   Ω = π·n/30
     Ф2   η = P₂/P₁ · P₁ = U·I · P₂ = M·Ω
     Ф3   M[Н·м] = M[Гсм]·9,81·10⁻⁵
     Ф4.1 Ω = U/(kΦ) − (R_я + R_д)·M/(kΦ)²
     Ф4.2 Ω₀ = U/(kΦ)      Ф4.3 ΔΩ = (R_я+R_д)·M/(kΦ)²
     Ф5   E = kΦ·Ω · M = kΦ·I_я · U = E + I_я(R_я+R_д)
     Ф6.1 I_пуск = U/(R_я+R_д)   Ф6.3 I_реверс/I_пуск ≈ 2
     Ф7.1 T_М = J·(R_я+R_д)/(kΦ)²   Ф7.4 t_пп ≈ 3·T_М
     Ф8   τ = t_и/T · U_ср = τ·U_пит
     Ф9   D = Ω_max/Ω_min          Ф10 регулировочная Ω = f(U)
   สามวิธีปรับความเร็วที่แสดงพร้อมกัน:
     ① ลด U อาร์เมเจอร์  ⇒ Ω₀ ลด แต่ความชันเท่าเดิม (เส้นขนานเลื่อนลง)
     ② เพิ่ม R_д          ⇒ Ω₀ เท่าเดิม แต่ชันขึ้น (เส้นพัดออกจากจุดเดียวกัน)
     ③ ลดฟลักซ์กระตุ้น    ⇒ Ω₀ สูงขึ้น และชันขึ้นเป็นกำลังสอง — วิธีนี้ทำบนแท่นนี้ไม่ได้
        เพราะอินดักเตอร์เป็น «постоянный магнит» (ต้นฉบับระบุชัด) จึงใส่ไว้เชิงทฤษฎีเท่านั้น
   ค่าพิกัดของมอเตอร์ต้นฉบับ «ไม่ให้เลย» ⇒ ค่าด้านล่างเป็นค่าสมมติของผู้เรียบเรียง
   ===================================================================== */
function eoLRdpt(host) {
  buildDemo(host, {
    label: "ЛР № 1 · ДПТ · п. 5.1–5.7 · Ф1…Ф10",
    title: "ปรับแรงดัน ความต้านทานเพิ่ม และฟลักซ์กระตุ้น แล้วดูว่าคุณลักษณะเชิงกลของ ДПТ ขยับต่างกันอย่างไรในแต่ละวิธี",
    ratio: 0.95,
    legend: '<span><i style="background:var(--ink-3)"></i>естественная (U = 30 В · R_д = 0)</span>' +
      '<span><i style="background:var(--accent)"></i>① U ที่ปรับ</span>' +
      '<span><i style="background:var(--crit)"></i>② R_д ที่ใส่</span>' +
      '<span><i style="background:var(--accent-2)"></i>③ ฟลักซ์ที่อ่อนลง</span>' +
      '<span><i style="background:var(--ok)"></i>ทั้งสามอย่างพร้อมกัน (จุดทำงาน)</span>',
    controls: [
      { id: "U", label: "U, В — แรงดันอาร์เมเจอร์ (แหล่งจ่าย 30 В)", min: 5, max: 30, step: 0.5, value: 30, fmt: function (v) { return eogF(v, 1); } },
      { id: "Rd", label: "R_д, Ом — ความต้านทานเพิ่ม R3 (เปิด S7 จึงเข้าวงจร)", min: 0, max: 24, step: 0.5, value: 0, fmt: function (v) { return eogF(v, 1); } },
      { id: "kf", label: "Φ/Φ_н — ฟลักซ์สัมพัทธ์ (เชิงทฤษฎี — แท่นใช้แม่เหล็กถาวร)", min: 0.4, max: 1.2, step: 0.05, value: 1, fmt: function (v) { return eogF(v, 2); } },
      { id: "M", label: "M, Гсм — โมเมนต์โหลดจากเบรก ЭТ (พิกัด ≈ 877 Гсм)", min: 0, max: 1600, step: 20, value: 877, fmt: function (v) { return eogF(v, 0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      /* ---- พารามิเตอร์แท่น (ค่าสมมติของผู้เรียบเรียง) ---- */
      var Un = 30, Rya = 6.0, kF0 = 0.08, J = 2.0e-5, M0 = 0.010, Mmax = 1600;
      var kF = kF0 * s.kf, Rt = Rya + s.Rd;
      var GSM = 9.80665e-5;                        // Ф3: 1 Гсм = 9,80665·10⁻⁵ Н·м
      var Mnm = s.M * GSM;                          // โมเมนต์โหลดเป็น Н·м

      /* Ф4.1 — คุณลักษณะเชิงกล (โมเมนต์ที่คิดคือโมเมนต์แม่เหล็กไฟฟ้า = M_вал + M₀) */
      var omega = function (U, R, kf, Mv) {
        var Mem = Mv + M0;
        return U / kf - R * Mem / (kf * kf);
      };
      var mkLine = function (U, R, kf) {
        var out = [], i, mv;
        for (i = 0; i <= 80; i++) {
          mv = Mmax * GSM * i / 80;
          out.push([mv / GSM, omega(U, R, kf, mv) * 30 / Math.PI]);   // Ф1: n = 30·Ω/π
        }
        return out;
      };
      var nat = mkLine(Un, Rya, kF0);
      var lU = mkLine(s.U, Rya, kF0);
      var lR = mkLine(Un, Rt, kF0);
      var lF = mkLine(Un, Rya, kF);
      var all = mkLine(s.U, Rt, kF);

      var Om = omega(s.U, Rt, kF, Mnm), n = Om * 30 / Math.PI;
      var Ia = (Mnm + M0) / kF;                     // Ф5.2
      var E = kF * Om;                              // Ф5.1
      var P1 = s.U * Ia;                            // Ф2.2
      var P2 = Mnm * Om;                            // Ф2.3
      var eta = P1 > 0.01 ? P2 / P1 * 100 : 0;      // Ф2.1
      var Ipusk = s.U / Rt;                         // Ф6.1
      var Irev = (s.U + E) / Rt;                    // Ф6.2
      var Tm = J * Rt / (kF * kF);                  // Ф7.1
      var tau = s.U / Un;                           // Ф8.2 — แรงดันเฉลี่ยเท่ากันถ้าใช้พัลส์
      var Om0 = s.U / kF, n0 = Om0 * 30 / Math.PI;
      /* Ф9 — พิสัยการปรับความเร็วที่โมเมนต์คงที่ โดยจำกัดที่ U_min ให้ยังมี M_п.min = M_ном */
      var Umin = (Mnm + M0) * Rt / kF + kF * 0.0;   // แรงดันต่ำสุดที่ยังหมุนได้ที่โมเมนต์นี้
      var nmax = omega(Un, Rya, kF0, Mnm) * 30 / Math.PI;
      var nmin = Math.max(1, omega(Math.max(Umin, 5), Rt, kF, Mnm) * 30 / Math.PI);
      var D = nmax / nmin;

      /* ---- แผงที่ 2: η(M) และ I_я(M) ---- */
      var effc = [], iac = [], i, mv, o2;
      for (i = 0; i <= 80; i++) {
        mv = Mmax * GSM * i / 80;
        o2 = omega(s.U, Rt, kF, mv);
        iac.push([mv / GSM, (mv + M0) / kF]);
        effc.push([mv / GSM, o2 > 0 ? mv * o2 / (s.U * (mv + M0) / kF) * 100 : 0]);
      }

      var g = eogPlots(w, h, 2, { gap: 34, bottom: 28 });
      var nTop = Math.max(600, Un / (kF0 * 0.4) * 30 / Math.PI * 0.55);
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, Mmax, 0, nTop);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, Mmax, 0, 100);

      p1.frame(ticks(0, Mmax, 8), eogTicksN(0, nTop, 5), "M, Гсм","n, об/мин");
      p1.clip(function () {
        p1.line(nat, ink3, 1.6, [5, 3]);
        p1.line(lU, acc, 1.8);
        p1.line(lR, crit, 1.8);
        p1.line(lF, acc2, 1.8);
        p1.line(all, ok, 2.6);
      });
      eogVRef(ctx, p1, 877, ink3, "M_ном", fs, [4, 4]);
      eogMark(ctx, p1, s.M, n, ok, eogF(n, 0) + " об/мин", fs);
      eogTag(ctx, p1, "1) Механические характеристики  n = f(M)  ตาม Ф4.1", ok, fs);
      eogTag(ctx, p1, "n₀ = " + eogF(n0, 0) + " об/мин", ink3, fs, true);

      p2.frame(ticks(0, Mmax, 8), eogTicksN(0, 100, 5), "M, Гсм","η, %  /  I_я·20, А");
      p2.clip(function () {
        p2.line(effc, acc2, 2.2);
        p2.line(iac.map(function (v) { return [v[0], v[1] * 20]; }), crit, 2, [6, 3]);
      });
      eogMark(ctx, p2, s.M, eta, acc2, "η = " + eogF(eta, 1) + " %", fs);
      eogMark(ctx, p2, s.M, Ia * 20, crit, "I_я = " + eogF(Ia, 2) + " А", fs, true);
      eogTag(ctx, p2, "2) η = M·Ω/(U·I_я)  (Ф2)  และ  I_я = (M + M₀)/kΦ  (Ф5.2, สเกล ×20)", acc2, fs);

      readout.innerHTML =
        'n = <b>' + eogF(n, 0) + ' об/мин</b> (Ω = ' + eogF(Om, 1) + ' рад/с) · I<sub>я</sub> = <b>' + eogF(Ia, 2) + ' А</b> · E = kΦ·Ω = <b>' + eogF(E, 1) + ' В</b>' +
        '<span>M = ' + eogF(s.M, 0) + ' Гсм × 9,81·10⁻⁵ = <b>' + eogF(Mnm, 4) + ' Н·м</b> (Ф3 — <b>ถ้าลืมแปลงหน่วยนี้ η จะผิดไปราว 10⁴ เท่า</b>)</span>' +
        '<span>P₁ = U·I = <b>' + eogF(P1, 1) + ' Вт</b> · P₂ = M·Ω = <b>' + eogF(P2, 1) + ' Вт</b> · η = <b>' + eogF(eta, 1) + ' %</b> (ค่าที่คาดหวังของมอเตอร์เล็ก 0,4…0,7)</span>' +
        '<span>Ω₀ = U/(kΦ) = <b>' + eogF(Om0, 1) + ' рад/с</b> = ' + eogF(n0, 0) + ' об/мин · ΔΩ = (R_я+R_д)M/(kΦ)² = <b>' + eogF(Om0 - Om, 1) + ' рад/с</b> (Ф4.2, Ф4.3)</span>' +
        '<span>I<sub>пуск</sub> = U/(R_я+R_д) = <b class="bad">' + eogF(Ipusk, 2) + ' А</b> = <b>' + eogF(Ipusk / Math.max(0.01, Ia), 1) + '</b> เท่าของกระแสทำงาน · I<sub>реверс</sub> = (U+E)/(R_я+R_д) = <b>' + eogF(Irev, 2) + ' А</b> ⇒ อัตราส่วน <b>' + eogF(Irev / Math.max(0.01, Ipusk), 2) + '</b> ≈ 2 (Ф6.3 — คำตอบข้อ 8)</span>' +
        '<span>T<sub>М</sub> = J(R_я+R_д)/(kΦ)² = <b>' + eogF(Tm * 1000, 1) + ' мс</b> ⇒ t<sub>пп</sub> ≈ 3·T<sub>М</sub> = <b>' + eogF(3 * Tm * 1000, 0) + ' мс</b> (Ф7.1, Ф7.4) — ใส่ R_д แล้ว T<sub>М</sub> โตตามทันที</span>' +
        '<span>ถ้าใช้แรงดันแบบพัลส์แทน: τ = U<sub>ср</sub>/U<sub>пит</sub> = ' + eogF(s.U, 1) + '/30 = <b>' + eogF(tau, 3) + '</b> ⇒ เส้นควรทับกับเส้น «①» พอดี (Ф8.2) — ถ้าเบี่ยงมาก แปลว่ามีการสูญเสียเพิ่มจากริปเปิลกระแส</span>' +
        '<span>พิสัยการปรับความเร็ว D = Ω<sub>max</sub>/Ω<sub>min</sub> ≈ <b>' + eogF(D, 2) + '</b> ที่โมเมนต์นี้ (Ф9) — จะแคบลงทันทีถ้าต้องรักษาโมเมนต์สตาร์ตขั้นต่ำไว้ด้วย</span>' +
        '<span><b>ความต่างที่ต้องชี้ให้ชัดในบทสรุป:</b> ① ลด U ⇒ เส้น<b>ขนาน</b>เลื่อนลง (Ω₀ ลด ความชันคงที่) · ② เพิ่ม R_д ⇒ เส้น<b>พัดออกจาก Ω₀ จุดเดิม</b> (ชันขึ้น) · ③ อ่อนฟลักซ์ ⇒ Ω₀ <b>สูงขึ้น</b> และชันขึ้นเป็นกำลังสอง เพราะ (kΦ)² อยู่ที่ตัวส่วน</span>' +
        '<span>⚠ แท่น ЛР № 1 ใช้ <b>возбуждение от постоянного магнита</b> ⇒ Φ = const จริง วิธี ③ <b>ทำบนแท่นนี้ไม่ได้</b> ใส่ไว้เพื่อเทียบทฤษฎีเท่านั้น · R_я = 6 Ом · kΦ = 0,08 В·с/рад · J = 2·10⁻⁵ кг·м² · M₀ = 0,010 Н·м เป็นค่าสมมติของผู้เรียบเรียง (ต้นฉบับไม่ให้ค่าพิกัดใด ๆ)</span>';
    }
  });
}


/* =====================================================================
   7) eoLRtr — ЛР № 2 «Испытание однофазного трансформатора»
   สูตร: notes/LR-A.md ข้อ 2.5
     Ф11   E = 4,44·f·w·Φ_m ⇒ Φ_m = U₁/(4,44·f·w₁) ∝ U₁/f
     Ф12   k = w₁/w₂ = U₁/U₂₀
     Ф13   I₁ном = S_ном/U₁ном · I₂ном = S_ном/U₂ном
     Ф14   ХХ: S₀ = U₁·I₀ · cos φ₀ = P₀/S₀ · I₀а = P₀/U₁ · I₀р = √(I₀² − I₀а²)
           Z₀ = U₁/I₀ · R₀ = P₀/I₀² · X₀ = √(Z₀² − R₀²)
     Ф15   КЗ: cos φ_к = P_к/(U₁к·I₁к) · I₁ка = P_к/U₁к · u_к % = U₁к/U₁ном·100
           Z_к = U₁к/I₁ном · R_к = P_к/I₁ном² · X_к = √(Z_к² − R_к²)
     Ф16   η_прям = U₂I₂cos φ₂/P₁
     Ф17   β = I₂/I₂ном · η = βS cos φ₂/(βS cos φ₂ + P₀ + β²P_к) · β_опт = √(P₀/P_к)
     Ф18   ΔU % = β(u_а%·cos φ₂ + u_р%·sin φ₂) โดย u_а% = R_кI₁ном/U₁ном·100 ฯลฯ
     Ф19   ΔP_общ = P₀ + β²P_к
   ผู้ใช้ป้อน «ผลการทดลอง» สี่ค่า (I₀, P₀, U₁к, P_к) เหมือนกรอกตาราง 9.1 และ 9.2 จริง
   หม้อแปลง ЛАВА-220/10 ⇒ 220 В → 10 В ⇒ คาด k ≈ 22 · S_ном = 100 В·А (ค่าสมมติ)
   ===================================================================== */
function eoLRtr(host) {
  buildDemo(host, {
    label: "ЛР № 2 · трансформатор · табл. 9.1–9.3 · Ф11…Ф19",
    title: "ป้อนผลการทดลอง ХХ และ КЗ เหมือนกรอกตารางจริง แล้วอ่านพารามิเตอร์วงจรสมมูล คุณลักษณะภายนอก และ η(β) ที่ cos φ ต่าง ๆ ทันที",
    ratio: 0.95,
    legend: '<span><i style="background:var(--accent)"></i>cos φ₂ = 1</span>' +
      '<span><i style="background:var(--accent-2)"></i>cos φ₂ = 0,8 (индукт.)</span>' +
      '<span><i style="background:var(--crit)"></i>cos φ₂ = 0</span>' +
      '<span><i style="background:var(--ok)"></i>cos φ₂ ที่เลือก · จุดทำงาน</span>',
    controls: [
      { id: "I0", label: "I₀, А — กระแส ХХ จาก PA1 (ตาราง 9.1)", min: 0.05, max: 0.7, step: 0.01, value: 0.25, fmt: function (v) { return eogF(v, 2); } },
      { id: "P0", label: "P₀, Вт — กำลัง ХХ จากวัตต์มิเตอร์ PW", min: 1, max: 30, step: 0.5, value: 8, fmt: function (v) { return eogF(v, 1); } },
      { id: "Uk", label: "U₁к, В — แรงดัน КЗ ที่ทำให้ I₂ = I₂ном (ตาราง 9.2)", min: 4, max: 44, step: 0.5, value: 20, fmt: function (v) { return eogF(v, 1); } },
      { id: "Pk", label: "P_к, Вт — กำลัง КЗ (ต้องน้อยกว่า U₁к·I₁ном เสมอ)", min: 0.5, max: 20, step: 0.25, value: 6, fmt: function (v) { return eogF(v, 2); } },
      { id: "cosf", label: "cos φ₂ — ตัวประกอบกำลังของโหลด (ตาราง 9.3)", min: 0, max: 1, step: 0.05, value: 0.8, fmt: function (v) { return eogF(v, 2); } },
      { id: "beta", label: "β = I₂/I₂ном — สัมประสิทธิ์โหลด", min: 0, max: 1.4, step: 0.02, value: 1, fmt: function (v) { return eogF(v, 2); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      /* ---- ค่าป้ายของหม้อแปลง (ค่าสมมติที่สอดคล้องกับชื่อรุ่น ЛАВА-220/10) ---- */
      var U1n = 220, U20 = 10, Sn = 100;
      var k = U1n / U20;                          // Ф12 ⇒ 22
      var I1n = Sn / U1n, I2n = Sn / U20;         // Ф13

      /* ---- ประมวลผล ХХ (Ф14) ---- */
      var S0 = U1n * s.I0;
      var cos0 = Math.min(1, s.P0 / S0);
      var I0a = s.P0 / U1n, I0p = Math.sqrt(Math.max(0, s.I0 * s.I0 - I0a * I0a));
      var Z0 = U1n / s.I0, R0 = s.P0 / (s.I0 * s.I0), X0 = Math.sqrt(Math.max(0, Z0 * Z0 - R0 * R0));

      /* ---- ประมวลผล КЗ (Ф15) ---- */
      var Sk = s.Uk * I1n;
      var cosk = Sk > 1e-6 ? s.Pk / Sk : 2;
      var badInput = cosk > 1;                    // ข้อมูลป้อนไม่สอดคล้องกันเชิงกายภาพ
      var Zk = s.Uk / I1n, Rk = s.Pk / (I1n * I1n);
      var Xk = Math.sqrt(Math.max(0, Zk * Zk - Rk * Rk));
      var uk = s.Uk / U1n * 100;
      var ua = Rk * I1n / U1n * 100, up = Xk * I1n / U1n * 100;

      /* ---- คุณลักษณะภายนอกและ КПД (Ф17, Ф18) ---- */
      var dUp = function (b, cf) { return b * (ua * cf + up * Math.sqrt(Math.max(0, 1 - cf * cf))); };
      var U2f = function (b, cf) { return U20 * (1 - dUp(b, cf) / 100); };
      var effF = function (b, cf) {
        var Pw = b * Sn * cf;
        return Pw > 1e-6 ? Pw / (Pw + s.P0 + b * b * s.Pk) * 100 : 0;
      };
      var i, b, e1 = [], e8 = [], e0 = [], ex = [], y1 = [], y8 = [], yx = [];
      for (i = 0; i <= 80; i++) {
        b = 1.4 * i / 80;
        e1.push([b, U2f(b, 1)]); e8.push([b, U2f(b, 0.8)]); e0.push([b, U2f(b, 0)]);
        ex.push([b, U2f(b, s.cosf)]);
        y1.push([b, effF(b, 1)]); y8.push([b, effF(b, 0.8)]); yx.push([b, effF(b, s.cosf)]);
      }
      var bOpt = s.Pk > 1e-6 ? Math.sqrt(s.P0 / s.Pk) : 0;   // Ф17
      var etaMax = effF(bOpt, s.cosf);
      var etaNom = effF(1, s.cosf);
      var U2now = U2f(s.beta, s.cosf), dUnow = dUp(s.beta, s.cosf);
      var P2now = s.beta * Sn * s.cosf;
      var dPnow = s.P0 + s.beta * s.beta * s.Pk;             // Ф19.1
      var etaNow = effF(s.beta, s.cosf);
      var etaPrym = P2now > 1e-6 ? P2now / (P2now + dPnow) * 100 : 0;

      var g = eogPlots(w, h, 2, { gap: 34, bottom: 28 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, 1.4, U20 * 0.75, U20 * 1.02);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, 1.4, 0, 100);

      p1.frame(ticks(0, 1.4, 7), eogTicksN(U20 * 0.75, U20 * 1.02, 4), "β = I₂/I₂ном","U₂, В");
      eogRef(ctx, p1, U20, ink3, "U₂₀ = " + eogF(U20, 1) + " В (ХХ)", fs, [3, 3]);
      p1.clip(function () {
        p1.line(e1, acc, 1.8); p1.line(e8, acc2, 1.8); p1.line(e0, crit, 1.8);
        p1.line(ex, ok, 2.6, [6, 3]);
      });
      eogVRef(ctx, p1, 1, ink3, "β = 1", fs, [4, 4]);
      eogMark(ctx, p1, s.beta, U2now, ok, eogF(U2now, 2) + " В", fs, true);
      eogTag(ctx, p1, "1) Внешние характеристики  U₂ = f(β)  ตาม ΔU % = β(u_а·cos φ₂ + u_р·sin φ₂)  (Ф18)", acc, fs);

      p2.frame(ticks(0, 1.4, 7), eogTicksN(0, 100, 5), "β","η, %");
      p2.clip(function () {
        p2.line(y1, acc, 1.8); p2.line(y8, acc2, 1.8); p2.line(yx, ok, 2.6, [6, 3]);
      });
      eogVRef(ctx, p2, bOpt, crit, "β_опт = √(P₀/P_к) = " + eogF(bOpt, 2), fs, [4, 4]);
      eogMark(ctx, p2, s.beta, etaNow, ok, eogF(etaNow, 1) + " %", fs, true);
      eogTag(ctx, p2, "2) КПД по данным ХХ и КЗ  (Ф17.2) — สูงสุดเมื่อ P₀ = β²·P_к", ok, fs);

      readout.innerHTML =
        'k = U₁/U₂₀ = <b>' + eogF(k, 1) + '</b> (ป้ายรุ่น ЛАВА-220/10 บอก 220 → 10 В ⇒ คาด ≈ 22) · I₁ном = <b>' + eogF(I1n, 3) + ' А</b> · I₂ном = <b>' + eogF(I2n, 1) + ' А</b>  (Ф12, Ф13)' +
        '<span><b>ХХ (Ф14):</b> S₀ = <b>' + eogF(S0, 1) + ' В·А</b> · cos φ₀ = P₀/S₀ = <b class="' + (cos0 < 0.35 ? "good" : "bad") + '">' + eogF(cos0, 3) + '</b> (ปกติ 0,1…0,3) · I₀а = <b>' + eogF(I0a, 3) + ' А</b> · I₀р = <b>' + eogF(I0p, 3) + ' А</b></span>' +
        '<span>สาขาแม่เหล็ก: Z₀ = <b>' + eogF(Z0, 0) + ' Ом</b> · R₀ = <b>' + eogF(R0, 0) + ' Ом</b> · X₀ = <b>' + eogF(X0, 0) + ' Ом</b> · P₀ ≈ <b>потери в стали</b> เพราะ I₀²R₁ เล็กมาก</span>' +
        '<span><b>КЗ (Ф15):</b> cos φ_к = <b' + (badInput ? ' class="bad"' : '') + '>' + eogF(Math.min(cosk, 9.99), 3) + '</b> · u_к % = U₁к/U₁ном = <b class="' + (uk >= 3 && uk <= 15 ? "good" : "bad") + '">' + eogF(uk, 1) + ' %</b> (ปกติ 3…10 %, หม้อแปลงเล็กถึง 15 %) · P_к ≈ <b>потери в меди</b></span>' +
        '<span>Z_к = <b>' + eogF(Zk, 1) + ' Ом</b> · R_к = <b>' + eogF(Rk, 1) + ' Ом</b> · X_к = <b>' + eogF(Xk, 1) + ' Ом</b> ⇒ u_а % = <b>' + eogF(ua, 2) + ' %</b> · u_р % = <b>' + eogF(up, 2) + ' %</b></span>' +
        '<span>ที่ β = ' + eogF(s.beta, 2) + ' และ cos φ₂ = ' + eogF(s.cosf, 2) + ': ΔU % = <b>' + eogF(dUnow, 2) + ' %</b> ⇒ U₂ = <b>' + eogF(U2now, 2) + ' В</b> · P₂ = <b>' + eogF(P2now, 1) + ' Вт</b> · ΔP = P₀ + β²P_к = <b>' + eogF(dPnow, 1) + ' Вт</b></span>' +
        '<span>η<sub>косв</sub> (วิธีอ้อม Ф17) = <b>' + eogF(etaNow, 2) + ' %</b> · η<sub>прям</sub> (วิธีตรง Ф16) = <b>' + eogF(etaPrym, 2) + ' %</b> · η<sub>ном</sub> = <b>' + eogF(etaNom, 2) + ' %</b> · η<sub>max</sub> = <b>' + eogF(etaMax, 2) + ' %</b> ที่ β = ' + eogF(bOpt, 2) + '</span>' +
        '<span>เหตุที่ต้องเทียบสองวิธี (ต้นฉบับ п.6з สั่งไว้): วิธีตรงวัดกำลังสองค่าที่<b>ใกล้เคียงกันมาก</b> ผลต่างจึงจมอยู่ในความคลาดเคลื่อนของเครื่องวัดสามตัว ส่วนวิธีอ้อม<b>วัดการสูญเสียโดยตรง</b> จึงแม่นกว่าและเป็นวิธีมาตรฐาน</span>' +
        '<span>เส้นของ cos φ₂ = 0 ตกชันที่สุดเพราะ ΔU มาจาก u_р % ซึ่งผูกกับ X_к ที่ใหญ่กว่า R_к — และ η ที่ cos φ₂ = 0 เป็นศูนย์ตลอด เพราะ P₂ = 0 มีแต่กำลังรีแอกทีฟ (คำตอบ КВ 12)</span>' +
        '<span>เชื่อมกับ Ф11: Φ_m = U₁/(4,44·f·w₁) ∝ U₁/f ⇒ ถ้าจ่ายหม้อแปลง 50 Гц ด้วย 400 Гц ฟลักซ์จะลดแปดเท่า (ปลอดภัย) แต่ถ้าจ่าย 400 Гц ด้วย 50 Гц แกน<b>อิ่มตัวทันที</b> และ I₀ พุ่ง</span>' +
        (badInput ? '<span><b class="bad">ข้อมูลป้อนไม่สอดคล้อง:</b> P_к = ' + eogF(s.Pk, 2) + ' Вт มากกว่า S_к = U₁к·I₁ном = ' + eogF(Sk, 2) + ' В·А ⇒ cos φ_к > 1 เป็นไปไม่ได้ ต้องลด P_к หรือเพิ่ม U₁к</span>' : '') +
        '<span>⚠ S_ном = 100 В·А และ U₂₀ = 10 В เป็นค่าสมมติของผู้เรียบเรียง — ต้นฉบับไม่ให้ค่าป้ายของหม้อแปลง ต้องอ่านจากป้ายจริงบนแท่นก่อนคำนวณ I₁ном (ซึ่งเป็นเกณฑ์หยุดเพิ่มแรงดันในการทดลอง КЗ)</span>';
    }
  });
}


/* =====================================================================
   8) eoLRtad — ЛР № 3 «Испытание ТАД (АД с фазным ротором)»
   สูตร: notes/LR-A.md ข้อ 3.4
     Ф22   M_ном = 0,975·P_ном/n_ном [кгс·м]  ⇒ M[Н·м] = 9,55·P_ном/n_ном
     Ф23   n₁ = 60·f₁/p  (50 Гц ⇒ 3000/1500/1000/750)
     Ф24   P₁ = 3·P_ф = √3·U_л·I_л·cos φ₁
     Ф25   P₂ = M·Ω₂ = M·n₂/9,55
     Ф26   s = (n₁ − n₂)/n₁ · n₂ = n₁(1 − s) · f₂ = s·f₁
     Ф27   η = P₂/P₁
     Ф28   M₀ — โมเมนต์ ไร้โหลด หาโดยวิธีกราฟิก
     Ф29   cos φ = P₁/(√3·U_л·I₁)
     Ф30.1 M = 2·M_к/(s/s_к + s_к/s)                       — สูตร Клосса
     Ф30.2 M_к = 3U₁ф²/(2Ω₁[R₁ + √(R₁² + X_к²)])
     Ф30.3 s_к = R₂′/√(R₁² + X_к²)                          Ф30.4 M ∝ U₁²
     Ф31.1 I_пуск = U₁ф/√((R₁+R₂′)² + X_к²)  Ф31.3 M_пуск = 2M_к/(1/s_к + s_к)
     Ф31.4 M_пуск = M_к เมื่อ s_к = 1 ⇒ R₂′ + R_доб = X_к   ← เหตุผลของ пусковой реостат
     Ф32.5 ΔP_эл2 = s·P_эм ⇒ η_max ≤ 1 − s
   พารามิเตอร์แท่น (ค่าสมมติของผู้เรียบเรียง ปรับให้ได้ s_ном = 5,3 % และ M_к/M_ном = 2,2
   ซึ่งเป็นช่วงที่โน้ตข้อ 3.8 ระบุว่าคาดหวัง): U_л = 380 В · p = 2 · R₁ = 2,0 Ом ·
   X_к = 12,0 Ом · R₂′ = 2,70 Ом · P_ном = 2,2 кВт · n_ном ≈ 1420 об/мин
   ===================================================================== */
function eoLRtad(host) {
  buildDemo(host, {
    label: "ЛР № 3 · ТАД с фазным ротором · п. 6, п. 13 · Ф22…Ф34",
    title: "ใส่ความต้านทานเพิ่มในโรเตอร์และลดแรงดัน แล้วดูสูตร Клосса ขยับ: ยอดโมเมนต์คงที่แต่สลิปวิกฤตเลื่อน ส่วนการลดแรงดันหั่นโมเมนต์เป็นกำลังสอง",
    ratio: 1.0,
    legend: '<span><i style="background:var(--ink-3)"></i>естественная (U = 380 В · R_доб = 0)</span>' +
      '<span><i style="background:var(--accent)"></i>с R_доб (пусковой реостат)</span>' +
      '<span><i style="background:var(--crit)"></i>при пониженном U₁</span>' +
      '<span><i style="background:var(--ok)"></i>เส้นที่ตั้งไว้จริง · จุดทำงาน</span>' +
      '<span><i style="background:var(--accent-2)"></i>I₂′(s) — กระแสโรเตอร์</span>',
    controls: [
      { id: "u", label: "U₁/U₁ном, % — แรงดันที่ตั้งด้วยหม้อแปลงปรับค่า", min: 50, max: 110, step: 1, value: 100, fmt: function (v) { return eogF(v, 0); } },
      { id: "rd", label: "R_доб, Ом — ความต้านทานเพิ่มในวงจรโรเตอร์ (ปรับที่ пусковой реостат)", min: 0, max: 14, step: 0.1, value: 0, fmt: function (v) { return eogF(v, 1); } },
      { id: "M", label: "M, Н·м — โมเมนต์โหลดจากเบรก ЭТ (พิกัด 14,8 Н·м)", min: 0, max: 40, step: 0.2, value: 14.8, fmt: function (v) { return eogF(v, 1); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      /* ---- พารามิเตอร์วงจรสมมูล (ค่าสมมติ) ---- */
      var Ul = 380, p = 2, f1 = 50, R1 = 2.0, Xk = 12.0, R2 = 2.70;
      var Pn = 2200, M0 = 0.5, cosn = 0.85;
      var n1 = 60 * f1 / p;                                  // Ф23 ⇒ 1500
      var W1 = 2 * Math.PI * n1 / 60;                        // Ф30.5 ⇒ 157,1 рад/с
      var U1f = Ul / Math.sqrt(3) * s.u / 100;
      var Zk = Math.sqrt(R1 * R1 + Xk * Xk);

      var Mk = function (U) { return 3 * U * U / (2 * W1 * (R1 + Zk)); };      // Ф30.2
      var sk = function (rd) { return (R2 + rd) / Zk; };                        // Ф30.3
      var Kloss = function (sv, U, rd) {                                        // Ф30.1
        var k = sk(rd);
        return sv <= 1e-6 ? 0 : 2 * Mk(U) / (sv / k + k / sv);
      };
      var I2 = function (sv, U, rd) {                                           // จาก Ф26.7
        return sv <= 1e-6 ? 0 : U / Math.sqrt(Math.pow(R1 + (R2 + rd) / sv, 2) + Xk * Xk);
      };

      var U1n = Ul / Math.sqrt(3);
      var i, sv, natC = [], rdC = [], uC = [], allC = [], i2C = [];
      for (i = 1; i <= 200; i++) {
        sv = i / 200;
        natC.push([sv, Kloss(sv, U1n, 0)]);
        rdC.push([sv, Kloss(sv, U1n, s.rd)]);
        uC.push([sv, Kloss(sv, U1f, 0)]);
        allC.push([sv, Kloss(sv, U1f, s.rd)]);
        i2C.push([sv, I2(sv, U1f, s.rd)]);
      }

      /* หาสลิปทำงาน: แก้ M(s) = M_нагр + M₀ บนกิ่งเสถียร (s < s_к) */
      var Mreq = s.M + M0, skc = sk(s.rd), Mkc = Mk(U1f);
      var lo = 1e-5, hi = skc, mid, sw = skc;
      var stall = Mreq > Mkc;
      if (!stall) {
        for (i = 0; i < 60; i++) {
          mid = (lo + hi) / 2;
          if (Kloss(mid, U1f, s.rd) < Mreq) lo = mid; else hi = mid;
        }
        sw = lo;
      }
      var n2 = n1 * (1 - sw);                                 // Ф26.3
      var f2 = sw * f1;                                       // Ф26.4
      var W2 = 2 * Math.PI * n2 / 60;
      var P2 = s.M * W2;                                      // Ф25
      var Pem = Mreq * W1;
      var dPel2 = sw * Pem;                                   // Ф32.5
      var I1 = I2(sw, U1f, s.rd) + 3.0;                       // + กระแสแม่เหล็ก (ค่าสมมติ 3 А)
      var P1 = Math.sqrt(3) * Ul * s.u / 100 * I1 * cosn;     // Ф24.2
      var eta = P1 > 1 ? P2 / P1 * 100 : 0;                   // Ф27
      var Ipusk = I2(1, U1f, s.rd);                           // Ф31.1
      var Mpusk = Kloss(1, U1f, s.rd);                        // Ф31.3
      var Mn = 9.55 * Pn / 1420;                              // Ф22 ⇒ 14,8 Н·м
      var In = 4.80;                                          // กระแสพิกัด (ค่าสมมติ)
      var rdOpt = Math.max(0, Zk - R2);                       // Ф31.4: s_к = 1

      var g = eogPlots(w, h, 2, { gap: 34, bottom: 28 });
      var Mtop = Math.max(40, Mk(U1n) * 1.15);
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, 1, 0, Mtop);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, 0, 1, 0, Math.max(25, I2(1, U1n, 0) * 1.15));

      p1.frame(ticks(0, 1, 5), eogTicksN(0, Mtop, 5), "s (0 = синхр. · 1 = пуск)","M, Н·м");
      eogRef(ctx, p1, Mn, ink3, "M_ном = 9,55·P/n = " + eogF(Mn, 1) + " Н·м", fs, [3, 3]);
      p1.clip(function () {
        p1.line(natC, ink3, 1.6, [5, 3]);
        p1.line(rdC, acc, 1.8);
        p1.line(uC, crit, 1.8);
        p1.line(allC, ok, 2.6);
      });
      eogVRef(ctx, p1, skc, acc2, "s_к = " + eogF(skc, 3), fs, [4, 4]);
      eogMark(ctx, p1, skc, Mkc, acc2, "M_к = " + eogF(Mkc, 1) + " Н·м", fs);
      eogMark(ctx, p1, sw, stall ? 0 : Mreq, ok, stall ? "ОПРОКИДЫВАНИЕ" : "s = " + eogF(sw, 4), fs, true);
      eogMark(ctx, p1, 1, Mpusk, acc, "M_пуск = " + eogF(Mpusk, 1) + " Н·м", fs);
      eogTag(ctx, p1, "1) Формула Клосса  M = 2M_к/(s/s_к + s_к/s)   (Ф30.1)", ok, fs);

      p2.frame(ticks(0, 1, 5), eogTicksN(0, Math.max(25, I2(1, U1n, 0) * 1.15), 5), "s","I₂′, А");
      p2.clip(function () { p2.line(i2C, acc2, 2.2); });
      eogRef(ctx, p2, In, ink3, "I_ном ≈ " + eogF(In, 2) + " А", fs, [3, 3]);
      eogMark(ctx, p2, 1, Ipusk, crit, "I_пуск = " + eogF(Ipusk, 1) + " А = " + eogF(Ipusk / In, 1) + "·I_ном", fs);
      eogMark(ctx, p2, sw, I2(sw, U1f, s.rd), ok, eogF(I2(sw, U1f, s.rd), 2) + " А", fs, true);
      eogTag(ctx, p2, "2) Ток ротора  I₂′ = U₁ф/√((R₁ + R₂′/s)² + X_к²)  — ยอดที่ s = 1 คือกระแสสตาร์ต", acc2, fs);

      readout.innerHTML =
        (stall ? '<b class="bad">โมเมนต์โหลดเกิน M_к ⇒ мотор опрокидывается (หยุดหมุน กระแสพุ่งถึงค่าสตาร์ต)</b>'
          : 's = <b>' + eogF(sw * 100, 2) + ' %</b> · n₂ = n₁(1 − s) = <b>' + eogF(n2, 0) + ' об/мин</b> · f₂ = s·f₁ = <b>' + eogF(f2, 2) + ' Гц</b>  (Ф26)') +
        '<span>n₁ = 60·f₁/p = 60·50/2 = <b>1500 об/мин</b> — ตารางของต้นฉบับให้ 3000/1500/1000/750 สำหรับ p = 1/2/3/4 (Ф23) · หา p จาก «n₁ คือค่าถัดขึ้นไปจาก n_ном»</span>' +
        '<span>M_к = 3U₁ф²/(2Ω₁[R₁+√(R₁²+X_к²)]) = <b>' + eogF(Mkc, 2) + ' Н·м</b> · s_к = R₂′/√(R₁²+X_к²) = <b>' + eogF(skc, 4) + '</b> · кратность M_к/M_ном = <b class="' + (Mkc / Mn >= 1.7 && Mkc / Mn <= 2.6 ? "good" : "bad") + '">' + eogF(Mkc / Mn, 2) + '</b> (ค่าปกติ 1,7…2,5)</span>' +
        '<span><b>ผลของ R_доб (Ф30.2/Ф30.3):</b> M_к <b>ไม่เปลี่ยนเลย</b> เพราะสูตรไม่มี R₂′ อยู่ — แต่ s_к ∝ R₂′ ⇒ ยอดโค้งเลื่อนไปทาง s ใหญ่ ที่ R_доб = <b>' + eogF(rdOpt, 2) + ' Ом</b> จะได้ s_к = 1 พอดี ⇒ <b>M_пуск = M_к สูงสุด พร้อมกระแสสตาร์ตต่ำลง</b> (Ф31.4 — ข้อได้เปรียบหลักของโรเตอร์แบบพันขด)</span>' +
        '<span><b>ผลของ U₁ (Ф30.4):</b> M ∝ U₁² ⇒ ที่ ' + eogF(s.u, 0) + ' % ของแรงดันพิกัด โมเมนต์ทุกจุดเหลือ <b>' + eogF(s.u * s.u / 100, 1) + ' %</b> ของเดิม ส่วน s_к <b>ไม่ขยับ</b> — เส้นยุบลงในแนวโมเมนต์อย่างเดียว</span>' +
        '<span>I_пуск = U₁ф/√((R₁+R₂′+R_доб)² + X_к²) = <b>' + eogF(Ipusk, 2) + ' А</b> = <b>' + eogF(Ipusk / In, 1) + '·I_ном</b> (ค่าปกติของ АД 4…7 เท่า — โรเตอร์แบบพันขดกดลงได้) · M_пуск = <b>' + eogF(Mpusk, 2) + ' Н·м</b> = <b>' + eogF(Mpusk / Mn, 2) + '·M_ном</b></span>' +
        '<span>P₂ = M·Ω₂ = <b>' + eogF(P2, 0) + ' Вт</b> · P₁ = √3·U_л·I₁·cos φ = <b>' + eogF(P1, 0) + ' Вт</b> · η = <b>' + eogF(eta, 1) + ' %</b> (ค่าที่คาดหวัง 70…90 %)</span>' +
        '<span>ΔP<sub>эл2</sub> = s·P<sub>эм</sub> = <b>' + eogF(dPel2, 0) + ' Вт</b> — การสูญเสียในโรเตอร์<b>แปรตามสลิปโดยตรง</b> (Ф32.5) ⇒ <b>η<sub>max</sub> ≤ 1 − s = ' + eogF((1 - sw) * 100, 1) + ' %</b> เป็นเพดานที่ АД ไม่มีวันข้าม นี่คือราคาที่ต้องจ่ายเมื่อใส่ R_доб ค้างไว้ตอนทำงาน</span>' +
        '<span>ที่ ХХ (M = 0) η = 0 เสมอ · cos φ₀ ต่ำมาก (0,1…0,3) เพราะกระแสเกือบเป็นรีแอกทีฟล้วนสำหรับสร้างสนามหมุน ⇒ <b>ห้ามเลือกมอเตอร์ใหญ่เกินงาน</b> (Ф29)</span>' +
        '<span>Реверс (Ф34): สลับสายสองเฟส ⇒ s = (n₁+n₂)/n₁ > 1 คือโหมด противовключения — กระแสสูงกว่าตอนสตาร์ตอีก จึงต้องทำต่อหน้าอาจารย์เท่านั้น · ДТ (Ф33): จ่ายไฟตรงเข้าสเตเตอร์ ⇒ โมเมนต์เบรก → 0 เมื่อหยุดสนิท «หยุดเร็วแต่ไม่ยึด»</span>' +
        '<span>⚠ R₁ = 2,0 Ом · X_к = 12,0 Ом · R₂′ = 2,70 Ом · P_ном = 2,2 кВт · n_ном = 1420 об/мин · I_ном = 4,80 А เป็นค่าสมมติของผู้เรียบเรียง ปรับให้ s_ном และ кратность อยู่ในช่วงที่โน้ตข้อ 3.8 คาดหวัง — <b>ต้นฉบับไม่ให้ค่าพิกัดเลย ต้องอ่านจากป้ายบนแท่น</b></span>';
    }
  });
}


/* =====================================================================
   9) eoLRfep — ЛР 1.1 «Испытание ФЭП / СБ» (แท่นจริงพร้อมโคมส่องและบล็อกทำความร้อน)
   สูตร: notes/LR-A.md ข้อ 5.4
     Ф43   P = U·I  [мВт] เมื่อ U ใน [В] และ I ใน [мА]
     Ф44   P_сб опт = max(U_i·I_i) ⇒ คู่ (U_опт, I_опт) = точка максимальной мощности
     Ф45   FF = (U_опт·I_опт)/(U_хх·I_кз)
     Ф46   P_уд.вес = P_макс/m [Вт/кг] · P_уд.площ = P_макс/S [Вт/м²]
     Ф47   P_расч(α) = P_сб опт(0°)·|cos α|            — กฎโคไซน์ (Ламберт)
     Ф48.1 I = I_ф − I₀·[exp(qU/(A·k·T)) − 1]
     Ф48.2 I_кз ≈ I_ф ∝ P_св (เชิงเส้น)   Ф48.3 U_хх ∝ ln(P_св) (ลอการิทึม)
     Ф48.4 dU_хх/dT ≈ −2,0…−2,3 мВ/°C ต่อเซลล์   Ф48.5 dI_кз/dT ≈ +0,05…+0,1 %/°C
           ⇒ dP/dT ≈ −0,4…−0,5 %/°C
     Ф49   η = P_опт/(E_осв·S)
   ค่าที่ต้นฉบับให้จริง (ЛР เดียวในชุดที่ให้ตัวเลข): โคม 4 หลอด × 250 Вт = 1000 Вт ·
     m = 58 г · S = 174 см² · เกณฑ์เทียบแสงอาทิตย์ 20 Вт/кг และ 100 Вт/м² ·
     ระดับความสว่าง 20/40/60/80/100 % · อุ่นถึง +45 °C · เย็น +20 °C · มุม 0/±45/±60/±90°
   จำนวนเซลล์อนุกรมของแผงและ I_кз ที่ 100 % เป็นค่าสมมติ (เลือกให้ P_уд ออกมาต่ำกว่าเกณฑ์
   แสงอาทิตย์ตามที่ต้นฉบับข้อ 5.8 เตือนไว้)
   ===================================================================== */
function eoLRfep(host) {
  buildDemo(host, {
    label: "ЛР 1.1 · ФЭП · табл. 2.1–2.5 · Ф43…Ф49",
    title: "หมุนตัวต้านทาน R_ВАХ เปลี่ยนความสว่างและอุณหภูมิ แล้วดูจุดกำลังสูงสุดขยับ พร้อมกำลังจำเพาะเทียบกับเกณฑ์แสงอาทิตย์ของต้นฉบับ",
    ratio: 0.95,
    legend: '<span><i style="background:var(--accent)"></i>ВАХ  U = f(I)</span>' +
      '<span><i style="background:var(--accent-2)"></i>P = U·I (ย่อสเกลให้พอดีกรอบ)</span>' +
      '<span><i style="background:var(--ok)"></i>ТММ — точка максимальной мощности</span>' +
      '<span><i style="background:var(--crit)"></i>เส้นโหลด R_ВАХ · P(α)</span>',
    controls: [
      { id: "E", label: "P_св, % — ความสว่างของโคม (ตำแหน่ง 20/40/60/80/100 %)", min: 20, max: 100, step: 5, value: 100, fmt: function (v) { return eogF(v, 0); } },
      { id: "T", label: "T, °C — อุณหภูมิแผง (เย็น +20 · อุ่น +45 ตามข้อ 5.1)", min: 15, max: 70, step: 1, value: 20, fmt: function (v) { return eogF(v, 0); } },
      { id: "pos", label: "ตำแหน่ง R_ВАХ (1 = 2,2 кОм … 7 = ≈ 0 Ом)", min: 1, max: 7, step: 1, value: 4, fmt: function (v) { return eogF(v, 0); } },
      { id: "ang", label: "α, град — มุมระหว่างทิศของโคมกับเส้นตั้งฉากผิวแผง", min: -90, max: 90, step: 5, value: 0, fmt: function (v) { return eogF(v, 0); } }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      /* ---- พารามิเตอร์แผง (ค่าสมมติ) ---- */
      var Ns = 14, A = 1.5, Ikz100 = 110, Uoc20 = 8.0, Tref = 293.15;
      var m = 0.058, Sm = 0.0174;                       // 58 г · 174 см² (ต้นฉบับ)
      var kB = 1.380649e-23, qe = 1.602176634e-19, Eg = 1.12 * qe;
      var Tk = s.T + 273.15;
      var cosA = Math.abs(Math.cos(s.ang * Math.PI / 180));    // Ф47.1
      var Erel = s.E / 100 * cosA;

      /* กระแสแสง: เชิงเส้นกับความสว่าง + สัมประสิทธิ์อุณหภูมิเล็กน้อย (Ф48.2, Ф48.5) */
      var Iph = Ikz100 * Erel * (1 + 0.0007 * (s.T - 20));
      /* กระแสอิ่มตัวย้อนกลับ: I₀ ∝ T³·exp(−E_g/kT) (Ф48.1) — ตรึงจาก U_хх ที่ 20 °C */
      var Ut = A * Ns * kB * Tk / qe;
      var Ut0 = A * Ns * kB * Tref / qe;
      var I00 = Ikz100 / (Math.exp(Uoc20 / Ut0) - 1);
      var I0 = I00 * Math.pow(Tk / Tref, 3) * Math.exp(Eg / (A * kB) * (1 / Tref - 1 / Tk));
      var Ifun = function (U) { return Iph - I0 * (Math.exp(U / Ut) - 1); };

      /* ---- สร้าง ВАХ และหา ТММ (Ф44) ---- */
      var Uoc = Iph > 1e-9 ? Ut * Math.log(Iph / I0 + 1) : 0;   // Ф48.3
      var N = 260, i, U, I, P, iv = [], pw = [], Pm = 0, Um = 0, Im = 0;
      for (i = 0; i <= N; i++) {
        U = Uoc * 1.02 * i / N;
        I = Math.max(0, Ifun(U));
        P = U * I;
        iv.push([I, U]);                                        // แกน x = I ตามที่แบบฟอร์มรายงานของงานใช้
        pw.push([I, P]);
        if (P > Pm) { Pm = P; Um = U; Im = I; }
      }
      var Ikz = Math.max(0, Ifun(0));
      var FF = (Uoc * Ikz) > 1e-9 ? Pm / (Uoc * Ikz) : 0;        // Ф45

      /* ---- เส้นโหลด: R_ВАХ ตามตำแหน่ง 1…7 (2,2 кОм … ≈ 0) แบบลอการิทึม ---- */
      var Rpos = [2200, 700, 220, 70, 22, 5, 0.1];
      var R = Rpos[Math.round(s.pos) - 1];
      /* แก้จุดตัด: I = (U/R) เมื่อ U จาก ВАХ — ใช้แบ่งครึ่งบน U */
      var lo = 0, hi = Uoc, mid, Uw = 0, Iw = 0;
      for (i = 0; i < 60; i++) {
        mid = (lo + hi) / 2;
        if (Ifun(mid) > mid / R * 1000) lo = mid; else hi = mid;  // I เป็น мА ⇒ U/R·1000
      }
      Uw = lo; Iw = Math.max(0, Ifun(Uw)); var Pw = Uw * Iw;

      /* ---- กำลังจำเพาะ (Ф46) ---- */
      var Pves = Pm * 1e-3 / m, Ppl = Pm * 1e-3 / Sm;
      var kVes = Pves / 20 * 100, kPl = Ppl / 100 * 100;

      /* ---- แผงที่ 2: P(α) เทียบกฎโคไซน์ ---- */
      var pa = [], pm0 = 0, a, Iph0, Uoc0, j, Um2, Pm2;
      for (i = 0; i <= 72; i++) {
        a = -90 + 180 * i / 72;
        Iph0 = Ikz100 * (s.E / 100) * Math.abs(Math.cos(a * Math.PI / 180)) * (1 + 0.0007 * (s.T - 20));
        if (Iph0 < 1e-6) { pa.push([a, 0]); continue; }
        Uoc0 = Ut * Math.log(Iph0 / I0 + 1);
        Pm2 = 0;
        for (j = 0; j <= 60; j++) {
          Um2 = Uoc0 * j / 60;
          Pm2 = Math.max(Pm2, Um2 * Math.max(0, Iph0 - I0 * (Math.exp(Um2 / Ut) - 1)));
        }
        pa.push([a, Pm2]);
        if (Math.abs(a) < 1e-6) pm0 = Pm2;
      }
      var paCos = [];
      for (i = 0; i <= 72; i++) {
        a = -90 + 180 * i / 72;
        paCos.push([a, pm0 * Math.abs(Math.cos(a * Math.PI / 180))]);
      }

      var g = eogPlots(w, h, 2, { gap: 34, bottom: 28 });
      var Itop = Ikz100 * 1.1, Utop = Math.max(9, Uoc20 * 1.15);
      /* ตัวหารของเส้น P — เลือกให้ยอดของเส้นพอดีกรอบ (เดิมตรึงไว้ที่ 50 จึงพุ่งทะลุกรอบบน) */
      var pMaxC = 0, ii2;
      for (ii2 = 0; ii2 < pw.length; ii2++) if (pw[ii2][1] > pMaxC) pMaxC = pw[ii2][1];
      var kRaw = pMaxC / Math.max(Utop * 0.92, 1e-6);
      var kP = [1, 2, 5, 10, 20, 25, 50, 100, 200, 250, 500, 1000].filter(function (v) { return v >= kRaw; })[0] || 1000;
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 0, Itop, 0, Utop);
      var p2 = new Plot(ctx, g[1].x, g[1].y, g[1].w, g[1].h, -90, 90, 0, Math.max(100, Ikz100 * Uoc20 * 0.85));

      p1.frame(eogTicksN(0, Itop, 6), eogTicksN(0, Utop, 5), "I, мА", "U, В  /  P/" + kP + ", мВт");
      p1.clip(function () {
        p1.line(iv, acc, 2.2);
        p1.line(pw.map(function (v) { return [v[0], v[1] / kP]; }), acc2, 2);
        p1.line([[0, 0], [Itop, Itop * R / 1000]], crit, 1.6, [5, 3]);
      });
      eogMark(ctx, p1, Im, Um, ok, "ТММ: " + eogF(Um, 2) + " В · " + eogF(Im, 0) + " мА", fs);
      eogMark(ctx, p1, Iw, Uw, crit, "R = " + (R >= 1000 ? eogF(R / 1000, 1) + " кОм" : eogF(R, 1) + " Ом"), fs, true);
      eogRef(ctx, p1, Uoc, ink3, "U_хх = E = " + eogF(Uoc, 2) + " В", fs, [3, 3]);
      eogVRef(ctx, p1, Ikz, ink3, "I_кз = " + eogF(Ikz, 0) + " мА", fs, [3, 3]);
      eogTag(ctx, p1, "1) ВАХ  U = f(I)  และ  P = U·I  (Ф43, Ф48) — เส้นประแดงคือเส้นโหลดของ R_ВАХ", acc, fs);

      p2.frame(eogTicksN(-90, 90, 6), eogTicksN(0, Math.max(100, Ikz100 * Uoc20 * 0.85), 4), "α, град","P_сб опт, мВт");
      p2.clip(function () {
        p2.line(paCos, ink3, 1.8, [5, 3]);
        p2.line(pa, crit, 2.2);
      });
      p2.dots([[0, pm0], [45, pm0 * 0.707], [60, pm0 * 0.5], [-45, pm0 * 0.707], [-60, pm0 * 0.5]], ink3, 3);
      eogMark(ctx, p2, s.ang, Pm, ok, eogF(Pm, 0) + " мВт", fs, true);
      eogTag(ctx, p2, "2) P(α) วัดได้ (ทึบ) เทียบกฎโคไซน์ P_опт(0°)·|cos α| (ประ)  (Ф47)", crit, fs);

      readout.innerHTML =
        'จุดทำงานที่ตำแหน่ง R_ВАХ = ' + Math.round(s.pos) + ': U = <b>' + eogF(Uw, 2) + ' В</b> · I = <b>' + eogF(Iw, 1) + ' мА</b> · P = U·I = <b>' + eogF(Pw, 0) + ' мВт</b>  (Ф43)' +
        '<span>ТММ: U<sub>опт</sub> = <b>' + eogF(Um, 2) + ' В</b> · I<sub>опт</sub> = <b>' + eogF(Im, 1) + ' мА</b> · <b>P<sub>сб опт</sub> = ' + eogF(Pm, 0) + ' мВт</b> ⇒ ตอนนี้ใช้กำลังไปเพียง <b class="' + (Pw / Math.max(1, Pm) > 0.9 ? "good" : "bad") + '">' + eogF(Pw / Math.max(1e-9, Pm) * 100, 0) + ' %</b> ของที่แผงให้ได้  (Ф44)</span>' +
        '<span>U<sub>хх</sub> = E = <b>' + eogF(Uoc, 2) + ' В</b> · I<sub>кз</sub> = <b>' + eogF(Ikz, 1) + ' мА</b> ⇒ FF = P<sub>опт</sub>/(E·I<sub>кз</sub>) = <b class="' + (FF > 0.68 ? "good" : "bad") + '">' + eogF(FF, 3) + '</b> (ซิลิคอนคุณภาพดี 0,7…0,8 · แผงร้อนหรือเก่า 0,5…0,65)  (Ф45)</span>' +
        '<span>กำลังจำเพาะ (Ф46): <b>' + eogF(Pves, 2) + ' Вт/кг</b> = <b>' + eogF(kVes, 0) + ' %</b> ของเกณฑ์แสงอาทิตย์ 20 Вт/кг · <b>' + eogF(Ppl, 1) + ' Вт/м²</b> = <b>' + eogF(kPl, 0) + ' %</b> ของเกณฑ์ 100 Вт/м² (m = 58 г · S = 174 см² จากต้นฉบับ)</span>' +
        '<span>เหตุผลที่ต่ำกว่าเกณฑ์มาก: หลอดไส้ 4 × 250 Вт ให้สเปกตรัม<b>อินฟราเรดเป็นหลัก</b> ซึ่งพลังงานโฟตอนต่ำกว่า E_g ของซิลิคอน (1,12 эВ) จึงกลายเป็นความร้อนแทนที่จะสร้างคู่พาหะ — ไม่ใช่เพราะแผงเสีย</span>' +
        '<span>ผลของอุณหภูมิ (Ф48.4/Ф48.5): ที่ T = ' + eogF(s.T, 0) + ' °C เทียบ 20 °C ⇒ U<sub>хх</sub> เปลี่ยน <b>' + eogF((Uoc - Ut0 * Math.log(Ikz100 * (s.E / 100) * cosA / I00 + 1)) * 1000, 0) + ' мВ</b> คิดเป็น <b>' + eogF(Ns > 0 ? (Uoc - Ut0 * Math.log(Ikz100 * (s.E / 100) * cosA / I00 + 1)) * 1000 / Ns / Math.max(0.001, s.T - 20) : 0, 2) + ' мВ/°C ต่อเซลล์</b> (ค่าที่คาดหวัง −2,0…−2,3) ⇒ <b>ร้อนขึ้น กำลังลดลง</b> ประมาณ −0,4…−0,5 %/°C</span>' +
        '<span>ที่ α = ' + eogF(s.ang, 0) + '° ⇒ |cos α| = <b>' + eogF(cosA, 3) + '</b> ⇒ กฎโคไซน์ทำนาย <b>' + eogF(pm0 * cosA, 0) + ' мВт</b> ส่วนแบบจำลองให้ <b>' + eogF(Pm, 0) + ' мВт</b> — ต่างกันเพราะ U<sub>хх</sub> ลดตาม <b>ลอการิทึม</b> ของฟลักซ์ ไม่ใช่เชิงเส้น (Ф48.3) นี่คือแก่นของคำถามข้อ 7</span>' +
        '<span>ที่ α = ±90° กำลังเป็นศูนย์ตามทฤษฎี แต่บนแท่นจริงจะยังอ่านค่าได้บ้างเพราะ<b>แสงสะท้อนจากผนังห้อง</b> — ต้องอธิบายจุดนี้ในบทสรุป</span>' +
        '<span>η = P<sub>опт</sub>/(E<sub>осв</sub>·S) (Ф49) — <b>คำนวณไม่ได้ในงานนี้</b> เพราะแท่นไม่มีลักซ์มิเตอร์หรือไพรานอมิเตอร์วัด E<sub>осв</sub> ที่ผิวแผง · ถ้าใช้ AM1.5 = 1000 Вт/м² ค่าอ้างอิง 100 Вт/м² ของต้นฉบับจะเท่ากับ η = 10 % พอดี</span>' +
        '<span>⚠ จำนวนเซลล์อนุกรม 14 · I<sub>кз</sub>(100 %) = 110 мА · U<sub>хх</sub>(20 °C) = 8,0 В · A = 1,5 เป็นค่าสมมติของผู้เรียบเรียง — ต้นฉบับให้เฉพาะ m, S, กำลังโคม และเกณฑ์เทียบ ส่วนค่าที่วัดได้จริงต้องกรอกจากแท่นเอง</span>';
    }
  });
}


/* =====================================================================
   10) eoLRosh — ЛР «Испытание СЭС с общими шинами (ОШ)» + тренажёр СЭП КА «Янтарь»
   สูตร: notes/LR-B.md § 4
     (4.3) P = U·I_СБ                    (4.4) P = U·|I| (ใช้ค่าสัมบูรณ์เพราะ I_АБ มีสองทิศ)
     (4.5) P_M, I_M — จุดกำลังสูงสุดของแต่ละ ВАХ
     (4.6) เงื่อนไขเทียบโหมด: I_СБ2 = I_АБ2 > 0 · I_СБ3 = I_АБ3 > I_АБ2 · q_MAX > q_MIN
   หลักการ ОШ: СБ · АБ · нагрузка ต่อบัสร่วมโดยไม่มีตัวแปลงรวมศูนย์ ⇒
     แรงดันบัสคือ «จุดตัด» ของ ВАХ ทั้งสามเส้น แก้จาก  I_СБ(U) = I_Н(U) + I_АБ(U)
     I_АБ = (U − ЭДС)/R_вн   (บวก = ประจุ · ลบ = คายประจุ)
   ค่าที่ต้นฉบับ/บทเรียนให้: 3 บล็อก × 7 герметичных NiCd = 21 เซลล์ · ป้าย 3хТД-0,115-У1.1 ·
     U = 25,2 В · Q = 115 мА·ч · ห้ามคายต่ำกว่า 18 В (= 0,86 В ต่อเซลล์) · โคม 4 × 250 Вт
     ปรับ 20…100 % · ตัวอย่างของบทเรียน: R_вн 3,75 → 4,25 Ом หลังคาย 33,3 мА·ч และ ΔЭДС = −0,35 В
   ⇒ แบบจำลอง (ผู้เรียบเรียง): dЭДС/dQ = 0,35/33,3 = 0,0105 В/(мА·ч) · dR/dQ = −0,015 Ом/(мА·ч)
   ===================================================================== */
function eogOshAb(q) {
  /* คืน ЭДС และความต้านทานภายในของ АБ ที่ระดับประจุ q [мА·ч] */
  var E = 24.74 + 0.0105 * q - 6 * Math.exp(-q / 3);   // พังทลายอย่างรวดเร็วเมื่อคายลึก
  var R = 3.75 + 0.015 * (115 - q);
  return { E: E, R: R };
}

function eoLRosh(host) {
  var ST = { q: 95, q0: 95, tPrev: 0, on: false };   // สถานะประจุของเดโมตัวนี้
  buildDemo(host, {
    label: "ЛР · СЭС с ОШ · тренажёр СЭП КА «Янтарь» · рис. 1.5",
    title: "สั่งเปิดปิดแผงเซลล์และโหลดเหมือนอยู่หน้าแท่น แล้วดูแรงดันบัสรวมกับระดับประจุแบตเตอรี่เคลื่อนไปตามเวลาจริง",
    ratio: 0.95,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>ВАХ СБ  I_СБ(U)</span>' +
      '<span><i style="background:var(--crit)"></i>ВАХ АБ  I_АБ(U) — ประจุขวา คายซ้าย</span>' +
      '<span><i style="background:var(--accent-2)"></i>โหลด I_Н = U/R_Н</span>' +
      '<span><i style="background:var(--ok)"></i>จุดทำงานของบัสรวม</span>',
    controls: [
      { id: "E", label: "P_СВ, % — ความสว่างของโคมส่อง (0 = อยู่ในเงาโลก)", min: 0, max: 100, step: 5, value: 100, fmt: function (v) { return eogF(v, 0); } },
      { id: "Rn", label: "R_Н, Ом — реостат нагрузки (ซ้ายสุด = โหลดน้อยสุด)", min: 25, max: 2000, step: 5, value: 200, fmt: function (v) { return eogF(v, 0); } },
      { id: "q0", label: "q_АБ ตั้งต้น, мА·ч (ความจุ 115 мА·ч)", min: 5, max: 115, step: 1, value: 95, fmt: function (v) { return eogF(v, 0); } },
      { id: "spd", label: "เร่งเวลา ×", min: 0, max: 400, step: 10, value: 120, fmt: function (v) { return eogF(v, 0); } }
    ],
    buttons: [
      { id: "s1", label: "S1 — СБ подключена к ОШ", toggle: true, value: true },
      { id: "s2", label: "S2 — нагрузка подключена", toggle: true, value: true }
    ],
    draw: function (ctx, w, h, s, readout, t) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      /* ---- แบบจำลอง СБ ของ КА (40 เซลล์อนุกรม — ค่าสมมติ ให้ U_хх สูงพอชาร์จ АБ 21 เซลล์) ---- */
      var Ns = 40, A = 1.4, Ikz100 = 400, Uoc100 = 30.5, Tk = 293.15;
      var kB = 1.380649e-23, qe = 1.602176634e-19;
      var Ut = A * Ns * kB * Tk / qe;
      var I0 = Ikz100 / (Math.exp(Uoc100 / Ut) - 1);
      var Iph = Ikz100 * s.E / 100;
      var fSB = function (U) { return s.s1 ? Math.max(0, Iph - I0 * (Math.exp(U / Ut) - 1)) : 0; };

      /* ---- ระดับประจุสะสมตามเวลา (แอนิเมชัน) — เก็บสถานะไว้ในโคลเชอร์ของเดโมนี้เท่านั้น ---- */
      if (!ST.on || ST.q0 !== s.q0) { ST.q = s.q0; ST.q0 = s.q0; ST.tPrev = t || 0; ST.on = true; }
      var st = ST;
      var dt = Math.max(0, Math.min(0.2, (t || 0) - st.tPrev));
      st.tPrev = t || 0;

      /* ---- แก้จุดทำงานของบัส: I_СБ(U) = I_Н(U) + I_АБ(U) ---- */
      var solve = function (q) {
        var ab = eogOshAb(q), lo = 0, hi = 45, mid, i;
        var fn = function (U) {
          var In = s.s2 ? U / s.Rn * 1000 : 0;         // мА
          var Iab = (U - ab.E) / ab.R * 1000;          // мА (บวก = ประจุ)
          return fSB(U) - In - Iab;
        };
        for (i = 0; i < 70; i++) { mid = (lo + hi) / 2; if (fn(mid) > 0) lo = mid; else hi = mid; }
        return { U: lo, ab: ab };
      };
      var sol = solve(st.q);
      var ab = sol.ab, U = sol.U;
      var Iload = s.s2 ? U / s.Rn * 1000 : 0;
      var Iab = (U - ab.E) / ab.R * 1000;
      var Isb = fSB(U);
      /* บูรณาการประจุ: q [мА·ч] += I[мА]·dt[ч] × ตัวเร่งเวลา */
      st.q = Math.max(0, Math.min(115, st.q + Iab * (dt * s.spd / 3600)));
      var qPct = st.q / 115 * 100;
      var deep = U < 18;                                // ห้ามคายต่ำกว่า 18 В

      /* ---- เส้นโค้งสำหรับกราฟ ---- */
      var i, x, cSB = [], cAB = [], cLD = [], Umax = 34;
      for (i = 0; i <= 160; i++) {
        x = Umax * i / 160;
        cSB.push([x, fSB(x)]);
        cAB.push([x, (x - ab.E) / ab.R * 1000]);
        cLD.push([x, s.s2 ? x / s.Rn * 1000 : 0]);
      }
      /* กำลังของ СБ เพื่อชี้จุด P_M (สูตร 4.3/4.5) */
      var Pm = 0, Um = 0, Im = 0, P;
      for (i = 0; i <= 160; i++) {
        x = Umax * i / 160; P = x * fSB(x);
        if (P > Pm) { Pm = P; Um = x; Im = fSB(x); }
      }

      var g = eogPlots(w, h, 2, { gap: 34, bottom: 28, left: w < 430 ? 44 : 54 });
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 14, Umax, -600, 600);
      var p2 = { x: g[1].x, y: g[1].y, w: g[1].w, h: g[1].h };

      p1.frame(ticks(14, Umax, 5), eogTicksN(-600, 600, 6), "U, В","I, мА");
      eogRef(ctx, p1, 0, ink3, null, fs, [2, 3]);
      p1.clip(function () {
        p1.line(cSB, acc, 2.2);
        p1.line(cAB, crit, 2.2);
        p1.line(cLD, acc2, 2, [6, 3]);
      });
      eogVRef(ctx, p1, 18, crit, "18 В — ห้ามคายต่ำกว่านี้", fs, [4, 4]);
      eogVRef(ctx, p1, ab.E, ink3, "ЭДС = " + eogF(ab.E, 2) + " В", fs, [3, 3]);
      eogMark(ctx, p1, U, Isb, acc, "I_СБ = " + eogF(Isb, 0) + " мА", fs);
      eogMark(ctx, p1, U, Iab, crit, "I_АБ = " + eogF(Iab, 0) + " мА", fs, true);
      if (Pm > 0) eogMark(ctx, p1, Um, Im, ok, "P_M = " + eogF(Pm, 0) + " мВт", fs);
      eogTag(ctx, p1, "1) จุดตัดของ ВАХ สามเส้น = แรงดันบัสรวม  U = " + eogF(U, 2) + " В", ok, fs);

      /* ---- แผงที่ 2: แผงหน้าปัดของแท่น ---- */
      eogPanel(ctx, p2.x, p2.y, p2.w, p2.h, wash, CV("--line-2"));
      var bx = p2.x + 10, bw = p2.w - 20, by = p2.y + 12, bh = 16, gp = 8;
      eogBar(ctx, bx, by, bw, bh, qPct / 100, qPct > 25, "q_АБ — степень заряженности (Q = 115 мА·ч)", eogF(st.q, 1) + " мА·ч · " + eogF(qPct, 0) + " %", fs);
      eogBar(ctx, bx, by + bh + gp, bw, bh, (U - 14) / (Umax - 14), !deep, "U ОШ — แรงดันบัสรวม (ขีดล่างที่อนุญาต 18 В)", eogF(U, 2) + " В", fs);
      eogBar(ctx, bx, by + 2 * (bh + gp), bw, bh, s.E / 100, s.E > 0 && s.s1, "P_СВ — โคมส่อง (S1 " + (s.s1 ? "включён" : "отключён") + ")", eogF(s.E, 0) + " %", fs);
      eogBar(ctx, bx, by + 3 * (bh + gp), bw, bh, Math.min(1, Iload / 400), s.s2, "I_Н — กระแสโหลด (S2 " + (s.s2 ? "включён" : "отключён") + ")", eogF(Iload, 0) + " мА", fs);
      var mode = Iab > 8 ? "① ЗАРЯД — СБ จ่ายทั้งโหลดและประจุแบตเตอรี่" :
        (Iab < -8 ? "③ РАЗРЯД — СБ ไม่พอ แบตเตอรี่จ่ายเสริม" : "② БАЛАНС — I_АБ ≈ 0, СБ จ่ายโหลดพอดี");
      eogText(ctx, bx, by + 4 * (bh + gp) + 10, "Режим: " + mode, Iab > 8 ? ok : (Iab < -8 ? crit : acc2), fs, "left", true, bw);
      eogText(ctx, bx, by + 4 * (bh + gp) + 10 + fs + 8,
        "R_вн = " + eogF(ab.R, 2) + " Ом  ·  ЭДС = " + eogF(ab.E, 2) + " В  ·  P_СБ = " + eogF(U * Isb, 0) + " мВт  ·  P_АБ = " + eogF(U * Math.abs(Iab), 0) + " мВт",
        CV("--ink-2"), fs, "left", false, bw);
      if (deep) eogText(ctx, bx, by + 4 * (bh + gp) + 10 + 2 * (fs + 8),
        "ВНИМАНИЕ: U < 18 В — глубокий разряд ทำลายเซลล์ที่อ่อนที่สุดอย่างถาวร ให้เพิ่ม R_Н หรือเปิดโคม", crit, fs, "left", true, bw);

      readout.innerHTML =
        'U (ОШ) = <b class="' + (deep ? "bad" : "good") + '">' + eogF(U, 2) + ' В</b> · I<sub>СБ</sub> = <b>' + eogF(Isb, 0) + ' мА</b> · I<sub>АБ</sub> = <b>' + eogF(Iab, 0) + ' мА</b> (' + (Iab >= 0 ? "заряд" : "разряд") + ') · I<sub>Н</sub> = <b>' + eogF(Iload, 0) + ' мА</b>' +
        '<span>ตรวจกฎ Кирхгофа บนบัสรวม: I<sub>СБ</sub> = I<sub>Н</sub> + I<sub>АБ</sub> ⇒ ' + eogF(Isb, 0) + ' = ' + eogF(Iload, 0) + ' + (' + eogF(Iab, 0) + ') ✔ — <b>นี่คือสาระทั้งหมดของระบบบัสรวม</b> ไม่มีตัวแปลงรวมศูนย์ แรงดันจึงเป็นผลของการตัดกันของ ВАХ สามเส้น</span>' +
        '<span>P<sub>СБ</sub> = U·I<sub>СБ</sub> = <b>' + eogF(U * Isb, 0) + ' мВт</b> · P<sub>АБ</sub> = U·|I<sub>АБ</sub>| = <b>' + eogF(U * Math.abs(Iab), 0) + ' мВт</b> (สูตร 4.3 และ 4.4 — ใช้ค่าสัมบูรณ์เพราะกระแสมีสองทิศ) · P<sub>M</sub> ของ СБ ที่ความสว่างนี้ = <b>' + eogF(Pm, 0) + ' мВт</b> ที่ U = ' + eogF(Um, 1) + ' В</span>' +
        '<span>q<sub>АБ</sub> = <b>' + eogF(st.q, 1) + ' мА·ч</b> จาก 115 мА·ч = <b>' + eogF(qPct, 0) + ' %</b> · ЭДС = <b>' + eogF(ab.E, 2) + ' В</b> · R<sub>вн</sub> = <b>' + eogF(ab.R, 2) + ' Ом</b> — สังเกตว่า <b>คายมากขึ้น ⇒ ЭДС ลด และ R<sub>вн</sub> โต</b> ทั้งคู่พร้อมกัน</span>' +
        '<span>ตรวจกับตัวอย่างของบทเรียน: คาย 400 мА นาน 5 นาที ⇒ ΔQ = 0,400 × 5/60 = <b>33,3 мА·ч</b> ⇒ ΔЭДС ≈ <b>−0,35 В</b> และ R<sub>вн</sub> 3,75 → <b>4,25 Ом</b> (+13 %) — เร่งเวลา ×120 แล้วเฝ้าดูสองค่านี้จะเห็นตรงกัน</span>' +
        '<span>สามโหมดของระบบ ОШ: <b>① ЗАРЯД</b> I_СБ > I_Н (I_АБ > 0) · <b>② БАЛАНС</b> I_СБ = I_Н (I_АБ = 0 ตรงจุดที่ U = ЭДС พอดี — จุดตรวจสอบตัวเองที่ต้นฉบับระบุ) · <b>③ РАЗРЯД</b> I_СБ &lt; I_Н (I_АБ &lt; 0) เกิดตอนอยู่ในเงาโลกหรือเปิด потребители П2</span>' +
        '<span>ปิด S1 (จำลองเข้าเงาโลก) แล้วสังเกต: แรงดันบัสตกทันทีมาอยู่ที่ ЭДС − I_Н·R_вн และ q เริ่มไหลลง — นี่คือเหตุผลที่ БКиУ ต้องสับ К2 ตัด <b>мощные потребители П2</b> ออก ส่วน П1 (дежурный режим) ต่อค้างไว้เสมอ</span>' +
        '<span>ข้อจำกัดที่ต้องท่องให้ได้: <b>ห้ามคายต่ำกว่า 18 В</b> (= 0,86 В ต่อเซลล์จาก 21 เซลล์) — ต่ำกว่านั้นเซลล์ที่อ่อนที่สุดจะถูก<b>กลับขั้ว</b>โดยเซลล์ที่เหลือ เป็นความเสียหายถาวรที่กู้คืนไม่ได้ · และห้าม<b>เกินประจุ</b>เช่นกัน จึงต้องมี К1</span>' +
        '<span>СЭС แบบ ОШ ใช้กับ КА ที่ <b>среднесуточная мощность 0,5–1,0 кВт</b> และอายุใช้งาน 3–5 ปี (НОО) หรือ 5–7 ปี (ГСО) — ตัวอย่างจริง: «Прогноз», «Зонд», «Венера-9/10», «Фотон-М», «Бион-М»</span>' +
        '<span>⚠ พารามิเตอร์ของ СБ (40 เซลล์ · I<sub>кз</sub> = 400 мА · U<sub>хх</sub> = 30,5 В) และแบบจำลอง ЭДС(q)/R<sub>вн</sub>(q) เป็นของผู้เรียบเรียง ปรับให้ตรงกับตัวเลขตัวอย่างของบทเรียน — ต้นฉบับ <b>ไม่มีสูตรใดเลยนอกจาก P = U·I</b> และไม่ได้กำหนดวิธีคำนวณ q เชิงปริมาณ <b>ต้องถามอาจารย์</b></span>';
    }
  });
}


/* =====================================================================
   11) eoLRkza — ЛР № 9 «Коммутационно-защитная аппаратура (КЗА)»
                 испытание магнитного пускателя ПММ-1010 + тепловые реле КК1/КК2
   สูตรเดียวที่ต้นฉบับให้ (notes/LR-B.md § 5):
     (5.1)  t = 0,02·α       โดย α = จำนวนพัลส์ที่ электрический секундомер นับได้
            0,02 с = 1/50 Гц = หนึ่งคาบของแรงดันสาย ⇒ ความละเอียดของการวัดเวลา
   ผู้เรียบเรียงเสริม (ตามที่โน้ตแนะนำให้คำนวณเพิ่ม):
     кратность тока  k = I/I_ном.реле
     расхождение настройки  δ = |t_КК1 − t_КК2|/((t_КК1+t_КК2)/2)·100 %
   แบบจำลองความร้อนของแผ่นไบเมทัล (ผู้เรียบเรียง — ต้นฉบับ «ไม่มีสูตรประมวลผลอื่นเลย»):
     θ(t)/θ_уст = 1 − e^(−t/T_н) โดย θ_уст ∝ I²  ⇒ ทำงานเมื่อ θ ถึง θ_тр ∝ I_тр²
     ⇒ t_сраб = T_н·ln[ k²/(k² − k_тр²) ]   ⇒  k ≤ k_тр ⇒ t → ∞ (ไม่ทำงานเลย)
     k_тр = 1,35 มาจาก «ток трогания теплового реле ≈ 135 % I_н» (Л11 сл. 21)
   เส้นอ้างอิงที่วางทับไว้คือชุดข้อมูลตัวอย่างของระเบียบวิธี (4/5/7/10 А ⇒ 180/63/18/5 с)
   ซึ่ง «ชันกว่า» แบบจำลองเอกซ์โพเนนเชียล — จุดต่างนี้ถูกอธิบายไว้ในบรรทัดผลลัพธ์
   ===================================================================== */
function eoLRkza(host) {
  var ST = { th: 0, tPrev: 0, run: false, done: false, alpha: 0, on: false };
  buildDemo(host, {
    label: "ЛР № 9 · КЗА · магнитный пускатель ПММ-1010 · табл. 11.1",
    title: "กดปุ่ม ПУСК แล้วเร่งโหลดเกินพิกัด เฝ้าดูแผ่นไบเมทัลร้อนขึ้นและเครื่องนับเวลาเดิน จนคอนแทกเตอร์ตัดมอเตอร์ออกจากสาย",
    ratio: 0.95,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>АСХ แบบจำลองความร้อน t = T_н·ln[k²/(k²−k_тр²)]</span>' +
      '<span><i style="background:var(--ink-3)"></i>จุดตัวอย่างของระเบียบวิธี 180/63/18/5 с</span>' +
      '<span><i style="background:var(--crit)"></i>เส้น 6·I_н — กระแสสตาร์ตที่ต้องไม่ทำให้ตัด</span>' +
      '<span><i style="background:var(--ok)"></i>จุดทำงานปัจจุบัน</span>',
    controls: [
      { id: "I", label: "I, А — กระแสที่มอเตอร์ดึง (ปรับด้วยเบรก · ช่วงของงาน I_хх…10 А)", min: 2, max: 12, step: 0.1, value: 5, fmt: function (v) { return eogF(v, 1); } },
      { id: "U", label: "U, В — แรงดันที่ตั้งด้วยหม้อแปลงปรับค่า АТ (พิกัด 220 В)", min: 80, max: 240, step: 2, value: 220, fmt: function (v) { return eogF(v, 0); } },
      { id: "Inr", label: "I_ном.реле, А — กระแสพิกัดของรีเลย์ความร้อน (ตั้งใกล้ I_хх ของมอเตอร์)", min: 2, max: 5, step: 0.1, value: 3, fmt: function (v) { return eogF(v, 1); } },
      { id: "Tn", label: "T_н, с — ค่าคงตัวเวลาความร้อนของแผ่นไบเมทัล", min: 10, max: 200, step: 5, value: 60, fmt: function (v) { return eogF(v, 0); } },
      { id: "spd", label: "เร่งเวลา ×", min: 1, max: 60, step: 1, value: 20, fmt: function (v) { return eogF(v, 0); } }
    ],
    buttons: [
      { id: "run", label: "ПУСК / СТОП (SB1 / SB2)", toggle: true, value: false },
      { id: "sa", label: "SA — ชันต์แผ่นไบเมทัลและหยุดเครื่องนับ", toggle: true, value: false },
      { id: "qk", label: "QK1 — обрыв фазы (ทดสอบรีเลย์ตัวเดียว)", toggle: true, value: false }
    ],
    draw: function (ctx, w, h, s, readout, t) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink3 = CV("--ink-3"), wash = CV("--wash");
      var fs = eogFS(w);

      var ktr = 1.35;                                  // ток трогания ≈ 135 % I_н (Л11 сл. 21)
      var Uotp = 130;                                  // แรงดันที่คอนแทกเตอร์ปล่อย (0,5…0,7·U_н ⇒ 110…150 В)
      /* เฟสขาด ⇒ กระแสในสองเฟสที่เหลือโตราว 1,73 เท่า (โหลดเดิมกระจายบนสองเฟส) */
      var kPhase = s.qk ? 1.73 : 1.0;
      var I = s.I * kPhase * (s.U / 220);              // แรงดันต่ำลง โมเมนต์ตก กระแสในโหมดนี้ลดตามสัดส่วนโดยประมาณ
      var k = I / s.Inr;
      var tsr = k > ktr ? s.Tn * Math.log(k * k / (k * k - ktr * ktr)) : Infinity;

      /* ---- สถานะเชิงเวลา ---- */
      if (!ST.on) { ST.on = true; ST.tPrev = t || 0; }
      var dt = Math.max(0, Math.min(0.2, (t || 0) - ST.tPrev));
      ST.tPrev = t || 0;
      var dropped = s.U < Uotp;                        // самопроизвольное отключение
      var powered = s.run && !dropped && !ST.done;
      if (!s.run) { ST.th = 0; ST.done = false; ST.alpha = 0; }
      if (powered) {
        if (!s.sa) {                                   // SA เปิด ⇒ กระแสผ่านรีเลย์ + เครื่องนับเดิน
          var dtr = dt * s.spd;
          ST.th += (k * k - ST.th) * (dtr / s.Tn);     // ทำให้ร้อนแบบเอกซ์โพเนนเชียล
          ST.alpha += dtr / 0.02;                      // (5.1) หนึ่งพัลส์ = 0,02 с
          if (ST.th >= ktr * ktr) ST.done = true;      // รีเลย์ทำงาน ⇒ КМ ปล่อย ⇒ เครื่องนับหยุด
        }
      } else if (!s.run) { ST.th = 0; }
      var thFrac = ST.th / (ktr * ktr);
      var tCount = ST.alpha * 0.02;

      /* ---- เส้น АСХ ---- */
      var i, x, asx = [], Imax = 12;
      for (i = 0; i <= 200; i++) {
        x = 2 + (Imax - 2) * i / 200;
        var kk = x / s.Inr;
        asx.push([x, kk > ktr ? s.Tn * Math.log(kk * kk / (kk * kk - ktr * ktr)) : NaN]);
      }
      var ref = [[4, 180], [5, 63], [7, 18], [10, 5]];  // ชุดข้อมูลตัวอย่างของระเบียบวิธี

      var g = eogPlots(w, h, 2, { gap: 34, bottom: 28 });
      /* กล่องแผงล่างสูงเท่าที่เนื้อหาต้องการเท่านั้น — ที่เหลือยกให้กราฟด้านบน */
      var bhP = 16, gpP = 8;
      var need2 = 12 + 4 * (bhP + gpP) + 10 + 2 * (fs + 8) + 14;
      var extra2 = Math.max(0, g[1].h - need2);
      g[0].h += extra2; g[1].y += extra2; g[1].h -= extra2;
      var p1 = new Plot(ctx, g[0].x, g[0].y, g[0].w, g[0].h, 2, Imax, 0, 220);
      var p2 = { x: g[1].x, y: g[1].y, w: g[1].w, h: g[1].h };

      p1.frame(ticks(2, Imax, 5), eogTicksN(0, 220, 4), "I, А","t_сраб, с");
      p1.clip(function () { p1.line(asx, acc, 2.4); });
      p1.dots(ref, ink3, 3.4);
      eogVRef(ctx, p1, ktr * s.Inr, crit, "ток трогания = 1,35·I_ном.реле = " + eogF(ktr * s.Inr, 2) + " А ⇒ t → ∞", fs, [4, 4]);
      eogVRef(ctx, p1, 6 * s.Inr, acc2, "6·I_н — กระแสสตาร์ต (สั้นมาก จึงอยู่ใต้เส้น)", fs, [3, 3]);
      if (isFinite(tsr)) eogMark(ctx, p1, I, Math.min(tsr, 215), ok, "t = " + eogF(tsr, 1) + " с", fs);
      eogTag(ctx, p1, "1) Ампер-секундная характеристика — จุดเทาคือชุดตัวอย่างของระเบียบวิธี", acc, fs);

      /* ---- แผงที่ 2: แผงหน้าปัดของแท่น ---- */
      eogPanel(ctx, p2.x, p2.y, p2.w, p2.h, wash, CV("--line-2"));
      var bx = p2.x + 10, bw = p2.w - 20, by = p2.y + 12, bh = 16, gp = 8;
      eogBar(ctx, bx, by, bw, bh, thFrac, !ST.done, "нагрев биметалла  θ/θ_тр  (ทำงานเมื่อถึง 100 %)", eogF(thFrac * 100, 0) + " %", fs);
      eogBar(ctx, bx, by + bh + gp, bw, bh, Math.min(1, tCount / 200), !ST.done,
        "электрический секундомер:  α = " + eogF(ST.alpha, 0) + " имп.", "t = 0,02·α = " + eogF(tCount, 2) + " с", fs);
      eogBar(ctx, bx, by + 2 * (bh + gp), bw, bh, Math.min(1, k / 4), k <= 1.35,
        "кратность тока  k = I/I_ном.реле", eogF(k, 2), fs);
      eogBar(ctx, bx, by + 3 * (bh + gp), bw, bh, s.U / 240, !dropped,
        "U ที่ตั้งด้วย АТ (คอนแทกเตอร์ปล่อยที่ ≈ " + Uotp + " В)", eogF(s.U, 0) + " В", fs);
      var stTxt = dropped ? "КМ ОТПУСТИЛ — самопроизвольное отключение по пониженному напряжению"
        : (ST.done ? "СРАБОТАЛО ТЕПЛОВОЕ РЕЛЕ — КМ разомкнул силовые контакты и остановил счётчик"
          : (s.run ? (s.sa ? "РАБОТАЕТ · SA замкнут ⇒ биметалл зашунтирован, счётчик стоит" : "РАБОТАЕТ · идёт нагрев биметалла") : "ОСТАНОВЛЕН — нажмите ПУСК (SB1)"));
      eogText(ctx, bx, by + 4 * (bh + gp) + 10, stTxt,
        dropped || ST.done ? crit : (s.run ? ok : CV("--ink-2")), fs, "left", true, bw);
      eogText(ctx, bx, by + 4 * (bh + gp) + 10 + fs + 8,
        "цепь: SB2 «Стоп» → SB1 «Пуск» (шунтируется блок-контактом K) → контакты КК1, КК2 → катушка КМ" + (s.qk ? "   ·   QK1 разомкнут: ток в оставшихся фазах ×1,73" : ""),
        CV("--ink-2"), fs, "left", false, bw);

      readout.innerHTML =
        't = 0,02·α: α = <b>' + eogF(ST.alpha, 0) + ' имп.</b> ⇒ <b>t = ' + eogF(tCount, 2) + ' с</b>' + (ST.done ? ' — <b class="bad">รีเลย์ตัดแล้ว</b>' : (s.run ? ' — กำลังนับ' : '')) +
        '<span>I = <b>' + eogF(I, 2) + ' А</b> · k = I/I<sub>ном.реле</sub> = <b>' + eogF(k, 2) + '</b> ⇒ เวลาที่ทฤษฎีทำนาย t<sub>сраб</sub> = T<sub>н</sub>·ln[k²/(k² − 1,35²)] = <b>' + (isFinite(tsr) ? eogF(tsr, 1) + ' с' : '∞ — ไม่ทำงานเลย') + '</b></span>' +
        '<span>เหตุผลที่ <b>ไม่ตัดตอนสตาร์ต</b>: กระแสสตาร์ต ≈ 6·I<sub>н</sub> = ' + eogF(6 * s.Inr, 1) + ' А กินเวลาเพียงเสี้ยววินาที ซึ่งอยู่ <b>ใต้เส้น АСХ</b> ส่วนโหลดเกินต่อเนื่องกินเวลา 60–180 с ซึ่ง <b>เกินเส้น</b> ⇒ การป้องกัน «ฉลาด» ได้ด้วยรูปร่างของเส้นโค้งเพียงอย่างเดียว (รีเลย์ตอบตามพลังงานสะสม ∫I²dt ไม่ใช่ค่ากระแสขณะใดขณะหนึ่ง)</span>' +
        '<span>ค่าอ้างอิงเชิงทฤษฎี: ток трогания ≈ <b>135 % I<sub>н</sub></b> (Л11 сл. 21) · ток длительной перегрузки I<sub>ДП</sub> = <b>(1,5–2)·I<sub>н</sub></b> · ток перегрузки (สตาร์ต) = <b>6·I<sub>н</sub></b> · ток КЗ = <b>11·I<sub>н</sub></b> — สองค่าแรก<b>ไม่ใช่สิ่งเดียวกัน</b> อันแรกคือเกณฑ์เริ่มตอบสนองของอุปกรณ์ อันหลังคือระดับกระแสในตารางโหมดฉุกเฉิน</span>' +
        '<span>เปิด <b>QK1</b> (обрыв фазы): กระแสในสองเฟสที่เหลือโตราว <b>1,73 เท่า</b> เพราะโหลดเดิมกระจายบนสองเฟส ⇒ รีเลย์ตัดเร็วขึ้นมาก — นี่คือ<b>เหตุผลที่ 2 ตัวก็พอ</b> เพราะกระแสสามเฟสสมดุลรวมกันเป็นศูนย์ การเฝ้าสองเฟสจึงจับได้ทุกกรณีรวมทั้งเฟสขาด</span>' +
        '<span>ลดแรงดันด้วย АТ จนต่ำกว่า <b>≈ ' + Uotp + ' В</b> (0,5…0,7 ของพิกัด) ⇒ แรงดึงของแม่เหล็กไม่พอ <b>คอนแทกเตอร์ปล่อยเอง</b> — เป็นการป้องกัน «пониженное напряжение» ที่ได้มาฟรีจากโครงสร้าง และเป็นเหตุผลเดียวกับที่มอเตอร์ <b>ไม่สตาร์ตเองเมื่อไฟกลับมา</b> (защита от самозапуска)</span>' +
        '<span>ตรวจความเหมือนของ КК1/КК2 (ข้อ 4 ของระเบียบวิธี): ตั้งกระแส 5…6 А แล้วเทียบเวลาตัดของสองตัวโดยใช้ QK1/QK2 ตัดทีละเฟส ⇒ δ = |t₁ − t₂|/ค่าเฉลี่ย·100 % ควรต่างกัน<b>ไม่เกินไม่กี่เปอร์เซ็นต์</b></span>' +
        '<span><b>ประโยคปิดท้ายที่ต้องพูดให้ได้:</b> «Магнитный пускатель <b>всегда</b> устанавливается совместно с плавкими вставками или автоматическими выключателями» — เพราะรีเลย์ความร้อน<b>ไม่ป้องกันการลัดวงจร</b> มันมีความเฉื่อยทางความร้อน กว่าจะร้อนพอ วงจรก็พังไปแล้ว</span>' +
        '<span>⚠ ต้นฉบับมีสูตรเดียวคือ <b>t = 0,02·α</b> — แบบจำลอง t<sub>сраб</sub> = T<sub>н</sub>·ln[k²/(k²−k<sub>тр</sub>²)] เป็นของผู้เรียบเรียง · จุดเทาบนกราฟคือ<b>ชุดตัวอย่างสมมติของระเบียบวิธี</b> (4/5/7/10 А ⇒ 180/63/18/5 с) ซึ่ง<b>ชันกว่า</b>แบบจำลองเอกซ์โพเนนเชียลอย่างชัดเจน จึงต้องถามอาจารย์ว่าภาควิชาใช้แบบจำลองใด และ<b>ให้ยึดค่าที่วัดได้จริงบนแท่นเป็นหลัก</b></span>';
    }
  });
}


/* =====================================================================
   12) eoRGR — РГР-2 «РАСЧЕТ ИНВЕРТОРА» — ตัวคำนวณครบทั้ง 20 вариантов
   แหล่ง: notes/RGR.md — методика 10 ขั้น (หน้า 5–6 ของต้นฉบับ) + ตาราง 1,а และ 1,б
   ลำดับที่คำนวณ (ตามต้นฉบับเป๊ะ พร้อมกฎการปัดเศษ «รอบ → จำนวนเต็ม · กระแสและ
   ความต้านทาน → ทศนิยม 2 ตำแหน่ง»):
     (1)  I_К = I_1Н = U_2Н·I_2Н/(η_Н·U_ПН)
     (2)  n_Т = ⌈I_К/I⁽¹⁾_Кmax⌉ ; ถ้า I_К ≤ 10 А ⇒ n_Т = 1
     (3)  ΔU_1Н = U_ПН·Δf̄/(1 + Δf̄)
     (4)  W₁ = (U_ПН − ΔU_1Н)/(4·B_S·S_С·f_Н)
     (5)  W₂ = W₁·U_2Н·(1 + ΔŪ₂)/(U_ПН − ΔU_1Н)
     (6)  W₃ = W₄ = U_ЭБmax·W₁·(1 + ΔŪ₂)/(U_ПН − ΔU_1Н)
     (7)  R_БГР = B_СТ·U_ЭБmax·n_Т/I_К
     (8)  R_1ГР = R_БГР − h_11Э ; แท่นทดลองมีรีโอสตัต ⇒ R₁ = R₂ = R_1ГР
     (9)  I_Б = U_ЭБmax/(R₁ + h_11Э)
     (10) I⁽¹⁾_КИ = B_СТ·I_Б  ≤ I⁽¹⁾_КИmax = 12 А ? ไม่ผ่าน ⇒ เพิ่ม n_Т แล้วกลับไปขั้น (7)
   ตรวจความสมเหตุสมผล (ข้อ 6.4 ของโน้ต): f_факт · U_2факт · U_W3 · เงื่อนไขอิ่มตัว ·
     η_факт · สมดุลแรงดัน-วินาที
   ⭐ ตรวจกับ вариант 1 ได้ค่า: I_К = 4,22 · n_Т = 1 · ΔU_1Н = 2,45 · W1.1 = 36 · W2 = 62 ·
     W3 = 6 · R_БГР = 7,58 · R₁ = 4,08 · I_Б = 0,53 · I⁽¹⁾_КИ = 4,24  ✔ ตรงทุกค่า
   ===================================================================== */
/* Таблица 1,а — 20 вариантов: [U_2Н, В · f_Н, Гц · U_ПН, В · I_2Н, А] */
var EOG_RGR_VAR = [
  [38.7, 332, 27, 2], [31.0, 271, 22, 2], [39.1, 593, 27, 2], [31.4, 481, 22, 2],
  [38.7, 846, 27, 2], [31.0, 683, 22, 2], [32.3, 337, 27, 3], [32.7, 339, 27, 2],
  [18.4, 278, 22, 2], [18.0, 275, 22, 3], [16.0, 342, 27, 2], [13.0, 280, 22, 2],
  [46.7, 704, 22, 1], [22.95, 492, 22, 2], [27.65, 599, 27, 3], [28.0, 601, 27, 2],
  [32.3, 337, 27, 3], [38.7, 332, 27, 2], [22.9, 492, 22, 2], [39.3, 593, 27, 2]
];
/* Таблица 1,б — ค่าคงที่ร่วมทุก вариант */
var EOG_RGR_C = { dU2: 0.1, dF: 0.1, eta: 0.68, IKmax: 10, IKImax: 12,
  BST: 8, h11: 3.5, UEB: 4, SC: 3.05e-4, BS: 1.68 };

/* คำนวณครบทั้ง 10 ขั้นสำหรับข้อมูลตั้งต้นชุดหนึ่ง */
function eogRgrCalc(U2, fH, UP, I2) {
  var C = EOG_RGR_C, K = 4 * C.BS * C.SC;             // = 2,0496·10⁻³ Вб
  var IK = eogR2(U2 * I2 / (C.eta * UP));             // (1)
  var nT = IK <= C.IKmax ? 1 : Math.ceil(IK / C.IKmax); // (2)
  var dU1 = eogR2(UP * C.dF / (1 + C.dF));            // (3)
  var Ub = eogR2(UP - dU1);                           // แรงดันใช้งานจริงของครึ่งขดปฐมภูมิ
  var W1r = Ub / (K * fH), W1 = Math.round(W1r);      // (4)
  var W2r = W1 * U2 * (1 + C.dU2) / Ub, W2 = Math.round(W2r);   // (5)
  var W3r = C.UEB * W1 * (1 + C.dU2) / Ub, W3 = Math.round(W3r); // (6)
  var RB = eogR2(C.BST * C.UEB * nT / IK);            // (7)
  var R1 = eogR2(RB - C.h11);                         // (8)
  var IB = eogR2(C.UEB / (R1 + C.h11));               // (9)
  var IKI = eogR2(C.BST * IB);                        // (10)
  var IBid = eogR2(IK / (C.BST * nT));                // เอกลักษณ์ I_Б = I_К/(B_СТ·n_Т)
  /* --- การตรวจ (ข้อ 6.4) --- */
  var fF = Ub / (K * W1);
  var dfPct = (fF - fH) / fH * 100;
  var U2F = Ub * W2 / W1 / (1 + C.dU2);
  var du2Pct = (U2F - U2) / U2 * 100;
  var UW3 = Ub * W3 / W1;
  /* เงื่อนไขอิ่มตัว: B_СТ·I_Б ≥ I_К/n_Т — เมื่อเลือก R₁ = R_1ГР พอดี ทั้งสองข้างเท่ากันตามนิยาม
     ส่วนต่างที่เห็นจึงมาจากการปัดเศษ 2 ตำแหน่งเท่านั้น (ระดับ ±0,5 %) */
  var satM = (C.BST * IB) / (IK / nT) - 1;
  var sat = satM >= 0;
  var satEdge = !sat && satM > -0.015;
  var P2 = U2 * I2, P1 = UP * IK, etaF = P1 > 0 ? P2 / P1 : 0;
  var Vs = 2 * C.BS * C.SC * W1, VsRef = Ub / (2 * fF);
  return { U2: U2, fH: fH, UP: UP, I2: I2, IK: IK, nT: nT, dU1: dU1, Ub: Ub,
    W1r: W1r, W1: W1, W2r: W2r, W2: W2, W3r: W3r, W3: W3, RB: RB, R1: R1,
    IB: IB, IKI: IKI, IBid: IBid, fF: fF, dfPct: dfPct, U2F: U2F, du2Pct: du2Pct,
    UW3: UW3, sat: sat, satM: satM, satEdge: satEdge, P2: P2, P1: P1, etaF: etaF,
    dP: P1 - P2, Vs: Vs, VsRef: VsRef,
    okK: IK / nT <= C.IKmax, okKI: IKI <= C.IKImax };
}

/* ตัดข้อความให้พอดีความกว้างคอลัมน์ */
function eogClipTxt(ctx, txt, maxw) {
  if (ctx.measureText(txt).width <= maxw) return txt;
  var s = txt;
  while (s.length > 1 && ctx.measureText(s + "…").width > maxw) s = s.slice(0, -1);
  return s + "…";
}

function eoRGR(host) {
  buildDemo(host, {
    label: "РГР-2 «Расчет инвертора» · табл. 1,а / 1,б · методика 10 пунктов",
    title: "เลื่อนเลือก вариант ของตัวเอง แล้วอ่านการคำนวณครบทั้ง 10 ขั้นตามลำดับของระเบียบวิธี พร้อมบรรทัดตรวจความสมเหตุสมผลและเงื่อนไขบังคับสองข้อ",
    ratio: 1.02,
    legend: '<span><i style="background:var(--accent)"></i>ผลลัพธ์ที่ต้องรายงาน</span>' +
      '<span><i style="background:var(--ink-3)"></i>ค่าดิบก่อนปัดเศษ</span>' +
      '<span><i style="background:var(--ok)"></i>เงื่อนไขผ่าน</span>' +
      '<span><i style="background:var(--crit)"></i>เงื่อนไขไม่ผ่าน</span>',
    controls: [
      { id: "v", label: "№ варианта (= หมายเลขในสมุดกลุ่มเรียน)", min: 1, max: 20, step: 1, value: 1, fmt: function (v) { return eogF(v, 0); } },
      { id: "U2", label: "โหมดป้อนเอง: U_2Н, В", min: 10, max: 50, step: 0.1, value: 38.7, fmt: function (v) { return eogF(v, 1); } },
      { id: "fH", label: "โหมดป้อนเอง: f_Н, Гц", min: 200, max: 900, step: 1, value: 332, fmt: function (v) { return eogF(v, 0); } },
      { id: "UP", label: "โหมดป้อนเอง: U_ПН, В", min: 20, max: 30, step: 0.5, value: 27, fmt: function (v) { return eogF(v, 1); } },
      { id: "I2", label: "โหมดป้อนเอง: I_2Н, А", min: 0.5, max: 8, step: 0.1, value: 2, fmt: function (v) { return eogF(v, 1); } }
    ],
    buttons: [
      { id: "man", label: "ป้อนค่าเอง (ไม่ใช้ตาราง 1,а)", toggle: true, value: false }
    ],
    draw: function (ctx, w, h, s, readout) {
      var acc = CV("--accent"), acc2 = CV("--accent-2"), crit = CV("--crit"),
        ok = CV("--ok"), ink = CV("--ink"), ink2 = CV("--ink-2"), ink3 = CV("--ink-3"),
        line2 = CV("--line-2"), wash = CV("--wash"), wash2 = CV("--wash-2");
      var C = EOG_RGR_C;

      var vn = Math.round(s.v), V = EOG_RGR_VAR[vn - 1];
      var R = s.man ? eogRgrCalc(s.U2, s.fH, s.UP, s.I2) : eogRgrCalc(V[0], V[1], V[2], V[3]);

      /* ---- โครงตาราง ---- */
      var pad = 6, x0 = pad, tw = w - 2 * pad;
      var narrow = w < 560;
      var cNum = narrow ? 16 : 20;
      var cRes = narrow ? 74 : 104;
      var cFor = tw - cNum - cRes;
      /* ความสูงของแถวคำนวณจาก h จริง เพื่อให้ตารางเต็มผ้าใบ (ไม่เหลือพื้นที่ว่างท้ายภาพ)
         โครง: 14 แถวเทียบเท่า + 6 แถวตรวจ + ระยะขอบ ≈ 51 px */
      var rowH = Math.max(15, Math.min(narrow ? 19 : 40, (h - 33) / 20));
      var fs = w < 430 ? 8.5 : Math.max(9.5, Math.min(13, rowH * 0.42));
      var y = pad + 2;

      /* หัวเรื่อง: ข้อมูลตั้งต้น */
      eogPanel(ctx, x0, y, tw, rowH + 4, wash2, line2);
      eogText(ctx, x0 + 5, y + (rowH + 4) / 2,
        (s.man ? "Ручной ввод" : "Вариант № " + vn) + ":   U_2Н = " + eogF(R.U2, 2) +
        " В  ·  f_Н = " + eogF(R.fH, 0) + " Гц  ·  U_ПН = " + eogF(R.UP, 1) +
        " В  ·  I_2Н = " + eogF(R.I2, 1) + " А", ink, fs, "left", true, tw - 10);
      y += rowH + 8;

      /* หัวคอลัมน์ */
      ctx.save();
      ctx.font = eogFont(fs);
      eogText(ctx, x0 + 3, y + rowH / 2, "№", ink3, fs, "left");
      eogText(ctx, x0 + cNum + 3, y + rowH / 2, "Формула  →  подстановка", ink3, fs, "left");
      eogText(ctx, x0 + tw - 3, y + rowH / 2, "Результат", ink3, fs, "right");
      ctx.restore();
      y += rowH - 2;
      ctx.save(); ctx.strokeStyle = line2; ctx.lineWidth = 1;
      ctx.beginPath(); ctx.moveTo(x0, Math.round(y) + 0.5); ctx.lineTo(x0 + tw, Math.round(y) + 0.5); ctx.stroke();
      ctx.restore();
      y += 3;

      var rows = [
        ["1", "I_К = I_1Н = U_2Н·I_2Н/(η_Н·U_ПН) = (" + eogF(R.U2, 2) + "·" + eogF(R.I2, 1) + ")/(0,68·" + eogF(R.UP, 1) + ")",
          eogF(R.IK, 2) + " А", null],
        ["2", "n_Т: I_К = " + eogF(R.IK, 2) + " А " + (R.IK <= C.IKmax ? "≤" : ">") + " I⁽¹⁾_Кmax = 10 А",
          eogF(R.nT, 0) + " шт.", null],
        ["3", "ΔU_1Н = U_ПН·Δf̄/(1+Δf̄) = " + eogF(R.UP, 1) + "·0,1/1,1",
          eogF(R.dU1, 2) + " В", "U_ПН − ΔU_1Н = " + eogF(R.Ub, 2) + " В"],
        ["4", "W1.1 = W1.2 = (U_ПН−ΔU_1Н)/(4·B_S·S_С·f_Н) = " + eogF(R.Ub, 2) + "/(2,0496·10⁻³·" + eogF(R.fH, 0) + ")",
          eogF(R.W1, 0) + " вит.", "ค่าดิบ " + eogF(R.W1r, 2)],
        ["5", "W2 = W₁·U_2Н(1+ΔŪ₂)/(U_ПН−ΔU_1Н) = " + eogF(R.W1, 0) + "·" + eogF(R.U2 * 1.1, 2) + "/" + eogF(R.Ub, 2),
          eogF(R.W2, 0) + " вит.", "ค่าดิบ " + eogF(R.W2r, 2)],
        ["6", "W3 = W4 = U_ЭБmax·W₁(1+ΔŪ₂)/(U_ПН−ΔU_1Н) = " + eogF(4 * R.W1 * 1.1, 1) + "/" + eogF(R.Ub, 2),
          eogF(R.W3, 0) + " вит.", "ค่าดิบ " + eogF(R.W3r, 2)],
        ["7", "R_БГР = B_СТ·U_ЭБmax·n_Т/I_К = (8·4·" + eogF(R.nT, 0) + ")/" + eogF(R.IK, 2),
          eogF(R.RB, 2) + " Ом", null],
        ["8", "R_1ГР = R_БГР − h_11Э = " + eogF(R.RB, 2) + " − 3,5   ⇒   R₁ = R₂ (แท่นมีรีโอสตัต)",
          eogF(R.R1, 2) + " Ом", null],
        ["9", "I_Б = U_ЭБmax/(R₁ + h_11Э) = 4/(" + eogF(R.R1, 2) + " + 3,5)",
          eogF(R.IB, 2) + " А", "เทียบเอกลักษณ์ I_К/(B_СТ·n_Т) = " + eogF(R.IBid, 2)],
        ["10", "I⁽¹⁾_КИ = B_СТ·I_Б = 8·" + eogF(R.IB, 2) + "   ⇒   ต้อง ≤ 12 А",
          eogF(R.IKI, 2) + " А", null]
      ];

      var i, rw;
      for (i = 0; i < rows.length; i++) {
        rw = rows[i];
        if (i % 2 === 0) eogPanel(ctx, x0, y, tw, rowH, wash);
        eogText(ctx, x0 + 3, y + rowH / 2, rw[0], ink3, fs, "left");
        ctx.save(); ctx.font = eogFont(fs);
        var main = eogClipTxt(ctx, rw[1], cFor - 8);
        ctx.restore();
        eogText(ctx, x0 + cNum + 3, y + rowH / 2, main, ink2, fs, "left", false, cFor - 8);
        eogText(ctx, x0 + tw - 3, y + rowH / 2, rw[2], acc, fs, "right", true);
        y += rowH;
      }
      /* บรรทัดค่าดิบ (แสดงเมื่อกว้างพอ) */
      if (!narrow) {
        eogText(ctx, x0 + cNum + 3, y + 9,
          "ค่าดิบก่อนปัดเศษ:  W₁ = " + eogF(R.W1r, 2) + "  ·  W₂ = " + eogF(R.W2r, 2) +
          "  ·  W₃ = " + eogF(R.W3r, 2) + "   (กฎต้นฉบับ: รอบ → จำนวนเต็ม · Ом และ А → 2 ตำแหน่ง)",
          ink3, fs, "left", false, tw - cNum - 6);
        y += 18;
      } else { y += 4; }

      /* ---- แถบเงื่อนไขบังคับสองข้อ ---- */
      var bh = Math.max(14, rowH - 4);
      eogBar(ctx, x0, y, tw, bh, (R.IK / R.nT) / C.IKmax, R.okK,
        "п.2:  I_К/n_Т ≤ I⁽¹⁾_Кmax = 10 А", eogF(R.IK / R.nT, 2) + " А  (" + eogF((R.IK / R.nT) / C.IKmax * 100, 0) + " %)", fs);
      y += bh + 4;
      eogBar(ctx, x0, y, tw, bh, R.IKI / C.IKImax, R.okKI,
        "п.10:  I⁽¹⁾_КИ ≤ I⁽¹⁾_КИmax = 12 А", eogF(R.IKI, 2) + " А  (" + eogF(R.IKI / C.IKImax * 100, 0) + " %)", fs);
      y += bh + 6;

      /* ---- บล็อกตรวจความสมเหตุสมผล ---- */
      var chk = [
        ["f_факт = (U_ПН−ΔU_1Н)/(4·B_S·S_С·W₁) = " + eogF(R.fF, 1) + " Гц", "Δ = " + (R.dfPct >= 0 ? "+" : "") + eogF(R.dfPct, 2) + " %", Math.abs(R.dfPct) < 10],
        ["U_2факт = (U_ПН−ΔU_1Н)·W₂/W₁/(1+ΔŪ₂) = " + eogF(R.U2F, 2) + " В", "Δ = " + (R.du2Pct >= 0 ? "+" : "") + eogF(R.du2Pct, 2) + " %", Math.abs(R.du2Pct) < 10],
        ["U_W3 = (U_ПН−ΔU_1Н)·W₃/W₁ = " + eogF(R.UW3, 2) + " В  เทียบ U_ЭБmax = 4 В", (R.UW3 >= 4 ? "+" : "") + eogF((R.UW3 / 4 - 1) * 100, 1) + " %", Math.abs(R.UW3 / 4 - 1) < 0.25],
        ["เงื่อนไขอิ่มตัว: B_СТ·I_Б = " + eogF(C.BST * R.IB, 2) + " А  " + (R.sat ? "≥" : "<") + "  I_К/n_Т = " + eogF(R.IK / R.nT, 2) + " А",
          (R.satM >= 0 ? "+" : "") + eogF(R.satM * 100, 2) + " %" + (R.satEdge ? " (ปัดเศษ)" : ""), R.sat || R.satEdge],
        ["η_факт = U_2Н·I_2Н/(U_ПН·I_К) = " + eogF(R.P2, 2) + "/" + eogF(R.P1, 2), eogF(R.etaF, 4) + " (η_Н = 0,68)", Math.abs(R.etaF - 0.68) < 0.02],
        ["สมดุลแรงดัน-วินาที: 2·B_S·S_С·W₁ = " + eogF(R.Vs * 1000, 3) + " мВ·с  เทียบ (U_ПН−ΔU_1Н)·T/2 = " + eogF(R.VsRef * 1000, 3) + " мВ·с",
          eogF(Math.abs(R.Vs / R.VsRef - 1) * 100, 2) + " %", Math.abs(R.Vs / R.VsRef - 1) < 0.02]
      ];
      var ch = Math.max(12, Math.min(rowH - 3, (h - y - pad) / chk.length));
      if (!isFinite(ch) || ch <= 0) ch = 12;
      for (i = 0; i < chk.length; i++) {
        if (i % 2 === 0) eogPanel(ctx, x0, y, tw, ch, wash);
        ctx.save(); ctx.font = eogFont(fs);
        var tx = eogClipTxt(ctx, (chk[i][2] ? "✔ " : "✘ ") + chk[i][0], tw - cRes - 10);
        ctx.restore();
        eogText(ctx, x0 + 3, y + ch / 2, tx, chk[i][2] ? ink2 : crit, fs, "left", false, tw - cRes - 10);
        eogText(ctx, x0 + tw - 3, y + ch / 2, chk[i][1], chk[i][2] ? ok : crit, fs, "right", true);
        y += ch;
      }

      /* ---- บรรทัดผลลัพธ์ ---- */
      var ref = eogRgrCalc(38.7, 332, 27, 2);
      var refOk = ref.IK === 4.22 && ref.nT === 1 && ref.dU1 === 2.45 && ref.W1 === 36 &&
        ref.W2 === 62 && ref.W3 === 6 && ref.RB === 7.58 && ref.R1 === 4.08 &&
        ref.IB === 0.53 && ref.IKI === 4.24;

      readout.innerHTML =
        (s.man ? 'โหมดป้อนเอง' : 'Вариант № ' + vn) + ': I<sub>К</sub> = I<sub>1Н</sub> = <b>' + eogF(R.IK, 2) + ' А</b> · n<sub>Т</sub> = <b>' + eogF(R.nT, 0) + '</b> · ΔU<sub>1Н</sub> = <b>' + eogF(R.dU1, 2) + ' В</b> · W1.1 = W1.2 = <b>' + eogF(R.W1, 0) + '</b> · W2 = <b>' + eogF(R.W2, 0) + '</b> · W3 = W4 = <b>' + eogF(R.W3, 0) + '</b>' +
        '<span>R<sub>БГР</sub> = <b>' + eogF(R.RB, 2) + ' Ом</b> · R₁ = R₂ = <b>' + eogF(R.R1, 2) + ' Ом</b> · I<sub>Б</sub> = <b>' + eogF(R.IB, 2) + ' А</b> · I⁽¹⁾<sub>КИ</sub> = <b class="' + (R.okKI ? "good" : "bad") + '">' + eogF(R.IKI, 2) + ' А</b> ' + (R.okKI ? '≤ 12 А ✔ ผ่าน (ใช้ ' + eogF(R.IKI / 12 * 100, 0) + ' % ของขีดจำกัด)' : '&gt; 12 А ✘ ต้องเพิ่ม n_Т แล้วกลับไปคำนวณใหม่ตั้งแต่ขั้นที่ 7') + '</span>' +
        '<span>ตรวจ: f<sub>факт</sub> = <b>' + eogF(R.fF, 1) + ' Гц</b> (Δ = ' + (R.dfPct >= 0 ? "+" : "") + eogF(R.dfPct, 2) + ' % จากงบ 10 %) · U<sub>2факт</sub> = <b>' + eogF(R.U2F, 2) + ' В</b> (Δ = ' + (R.du2Pct >= 0 ? "+" : "") + eogF(R.du2Pct, 2) + ' %) · η<sub>факт</sub> = <b>' + eogF(R.etaF, 4) + '</b> · เงื่อนไขอิ่มตัว B<sub>СТ</sub>·I<sub>Б</sub> = ' + eogF(C.BST * R.IB, 2) + ' А เทียบ I<sub>К</sub>/n<sub>Т</sub> = ' + eogF(R.IK / R.nT, 2) + ' А ⇒ มาร์จิน <b class="' + (R.sat ? "good" : (R.satEdge ? "" : "bad")) + '">' + (R.satM >= 0 ? "+" : "") + eogF(R.satM * 100, 2) + ' %</b></span>' +
        '<span>มาร์จินของเงื่อนไขอิ่มตัวเล็กมากเสมอ (ระดับ ±0,5 %) เพราะการเลือก <b>R₁ = R_1ГР พอดี</b> คือการยืนบน<b>ขอบเขต</b>ตามนิยาม ส่วนต่างที่เห็นเกิดจาก<b>การปัดเศษ 2 ตำแหน่ง</b>ล้วน ๆ ไม่ใช่ความผิดพลาดของการคำนวณ · ถ้าต้องการเผื่อความปลอดภัยจริง ให้ลด R₁ ลง 10–20 % แล้วตรวจขั้นที่ 10 ซ้ำ</span>' +
        '<span>สมดุลกำลัง: P₂ = U<sub>2Н</sub>·I<sub>2Н</sub> = <b>' + eogF(R.P2, 2) + ' Вт</b> · P₁ = U<sub>ПН</sub>·I<sub>1Н</sub> = <b>' + eogF(R.P1, 2) + ' Вт</b> · ΔP = <b>' + eogF(R.dP, 2) + ' Вт</b> (' + eogF(R.dP / R.P1 * 100, 0) + ' % ของกำลังอินพุต — สูงตามธรรมชาติของอินเวอร์เตอร์ทรานซิสเตอร์ไบโพลาร์)</span>' +
        '<span><b>ตรวจกับ вариант 1 ของโน้ต:</b> I<sub>К</sub> = ' + eogF(ref.IK, 2) + ' · n<sub>Т</sub> = ' + ref.nT + ' · ΔU<sub>1Н</sub> = ' + eogF(ref.dU1, 2) + ' · W1.1 = ' + ref.W1 + ' · W2 = ' + ref.W2 + ' · W3 = ' + ref.W3 + ' · R<sub>БГР</sub> = ' + eogF(ref.RB, 2) + ' · R₁ = ' + eogF(ref.R1, 2) + ' · I<sub>Б</sub> = ' + eogF(ref.IB, 2) + ' · I⁽¹⁾<sub>КИ</sub> = ' + eogF(ref.IKI, 2) + ' ⇒ <b class="' + (refOk ? "good" : "bad") + '">' + (refOk ? "ตรงกับค่าอ้างอิงทุกค่า" : "ไม่ตรง") + '</b></span>' +
        '<span>เงื่อนไขเลือก вариант (ต้นฉบับ): «номер варианта <b>соответствует порядковому номеру в журнале учебной группы</b>» · กฎการปัดเศษ: <b>จำนวนรอบ → จำนวนเต็ม · ความต้านทานและกระแส → ทศนิยม 2 ตำแหน่ง</b></span>' +
        '<span>ที่มาของขั้นที่ 4: บนแกน ППГ ฟลักซ์ต้องกวาดจาก −B_S ถึง +B_S ในเวลา T/2 ⇒ U_ПН − ΔU_1Н = 4·W₁·S_С·B_S·f ⇒ ตัวส่วน <b>4·B_S·S_С = 2,0496·10⁻³ Вб คงที่ทุก вариант</b> ⇒ W₁ ยิ่งน้อย f ยิ่งสูง</span>' +
        '<span>ที่มาของขั้นที่ 7 (เงื่อนไขอิ่มตัว): ทรานซิสเตอร์ต้องอิ่มตัวตลอดช่วงนำ ⇒ B_СТ·I_Б ≥ I_К/n_Т และ I_Б = U_ЭБmax/R_Б ⇒ R_Б ≤ B_СТ·U_ЭБmax·n_Т/I_К · ถ้ากระแสฐานน้อยไป ทรานซิสเตอร์จะออกจากอิ่มตัว<b>ก่อน</b>ที่แกนจะอิ่มตัว ⇒ <b>ความถี่พุ่งขึ้นและแรงดันขาออกตก</b> ซึ่งตรงกับอาการข้อ 3 ของตาราง «Основные неисправности» ในงานทดลอง</span>' +
        '<span>เมื่อเลือก R₁ = R_1ГР พอดี (กรณีแท่นทดลอง) จะได้ <b>I⁽¹⁾_КИ = I_К/n_Т</b> เป๊ะ ๆ ⇒ การตรวจข้อ 10 จึง<b>ผ่านโดยอัตโนมัติเสมอ</b> เพราะขั้นที่ 2 บังคับ I_К/n_Т ≤ 10 А อยู่แล้ว · ลูปย้อนกลับจะทำงานได้ก็ต่อเมื่อเลือก R₁ จากอนุกรมมาตรฐานให้ต่ำกว่า R_1ГР เกิน 1,2 เท่า</span>' +
        '<span>ผู้เรียบเรียงตรวจครบทั้ง 20 вариантов แล้ว: <b>n_Т = 1 ทุก вариант</b> (I_К สูงสุด 5,28 А ที่ вар. 7/17 ยังห่างจาก 10 А มาก) · มีเพียง 4 ค่าของ W₁ คือ 14, 20, 35, 36 · вар. 1 = вар. 18 และ вар. 7 = вар. 17 ให้ผลเหมือนกันทุกบรรทัด (ตารางซ้ำจริง) · Δf สูงสุดหลังปัดเศษ +2,05 % ที่ вар. 6 และ ΔU₂ สูงสุด +1,33 % ที่ вар. 4 — <b>ทั้งคู่ต่ำกว่างบ 10 % สิบเท่า</b></span>' +
        '<span>⚠ ตาราง «สรุปผลทั้ง 20 вариантов» ในโน้ตเป็นของผู้เรียบเรียง ไม่ใช่เฉลยของภาควิชา — <b>คู่มือ РГР-2 ไม่มีตัวอย่างคำนวณใด ๆ เลย</b> · ค่า I_Б ของบาง вариант ต่างจากตารางนั้น ±0,01 А เพราะที่นี่คำนวณตามขั้นที่ 9 ตรง ๆ (I_Б = 4/(R₁+h_11Э)) ส่วนตารางบางแถวใช้เอกลักษณ์ I_К/(B_СТ·n_Т) — บรรทัดที่ 9 ของตารางแสดงทั้งสองค่าให้เทียบกันเอง</span>';
    }
  });
}


