/* ---- 1. วิถียิงขึ้นและโปรแกรมมุม Pitch ---- */
function demoSurnTraj(host) {
  buildDemo(host, {
    label: "Лекции 7 · 11 · линейный тангенс",
    title: "วิถีช่วงนอกบรรยากาศกับโปรแกรมมุม Pitch ϑ(t) = ϑ₀ − b·t",
    ratio: 0.6,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>วิถีจริง</span><span><i style="background:var(--accent-2)"></i>โปรแกรมมุม Pitch</span><span><i style="background:var(--line-2)"></i>วงโคจรเป้าหมาย 200 กม. · V<sub>x</sub> = 7,3 กม./с</span><span><i class="dot" style="background:var(--ink)"></i>ตำแหน่งจรวด</span>',
    controls: [
      { id: "th0", label: "ϑ₀ — มุม Pitch เริ่มต้นของช่วงนี้", min: 5, max: 70, step: 1, value: 55, fmt: v => v + "°" },
      { id: "b", label: "b — อัตราก้มหัว", min: 0, max: 0.16, step: 0.002, value: 0.12, fmt: v => v.toFixed(3) + " °/с" },
      { id: "T", label: "T — เวลาที่เหลือของช่วงมีแรงขับ", min: 200, max: 400, step: 2, value: 386, fmt: v => v + " с" }
    ],
    draw(ctx, w, h, s, readout, tAnim) {
      const c = 3200, tau = 420, g = 9.81, DR = Math.PI / 180;
      const N = 800, dt = s.T / N;
      let vx = 1500, vy = 900, x = 0, y = 50, hit = false;
      const traj = [[0, 50]], prog = [];
      for (let i = 1; i <= N; i++) {
        const t = i * dt;
        const th = s.th0 - s.b * t;
        prog.push([t, th]);
        if (hit) continue;
        const a = c / (tau - t);
        vx += a * Math.cos(th * DR) * dt;
        vy += (a * Math.sin(th * DR) - g) * dt;
        x += vx * dt / 1000;
        y += vy * dt / 1000;
        if (y <= 0) { y = 0; hit = true; }
        traj.push([x, y]);
      }
      const hk = y, thK = s.th0 - s.b * s.T;
      const ok = !hit && hk > 170 && hk < 240 && vx > 7200 && Math.abs(vy) < 250;

      const gap = 32, hA = (h - 46) * 0.6, hB = (h - 46) - hA - gap;
      const xmax = Math.max(400, Math.ceil(traj[traj.length - 1][0] / 200) * 200);
      const ymax = Math.max(260, Math.ceil(Math.max(...traj.map(q => q[1])) / 50) * 50 + 30);
      const p = new Plot(ctx, 56, 10, w - 72, hA, 0, xmax, 0, ymax);
      p.frame(ticks(0, xmax, 5).map(Math.round), ticks(0, ymax, 4).map(Math.round), "", "H, กม.", true);
      p.line([[0, 200], [xmax, 200]], CV("--line-2"), 1.3, [5, 4]);
      p.clip(() => p.line(traj, hit ? CV("--crit") : CV("--accent"), 2.4));
      const idx = Math.min(traj.length - 1, Math.floor((tAnim * 90) % (traj.length + 60)));
      if (idx < traj.length) {
        const q = traj[idx];
        ctx.save(); ctx.fillStyle = CV("--ink");
        ctx.beginPath(); ctx.arc(p.X(q[0]), p.Y(q[1]), 4.4, 0, 7); ctx.fill(); ctx.restore();
      }

      const pymin = Math.min(-10, Math.floor(thK / 10) * 10);
      const pp = new Plot(ctx, 56, 10 + hA + gap, w - 72, hB, 0, s.T, pymin, Math.max(40, s.th0 + 8));
      pp.frame(ticks(0, s.T, 5).map(Math.round), ticks(pymin, Math.max(40, s.th0 + 8), 3).map(Math.round), "t, с", "ϑ, °");
      pp.line([[0, 0], [s.T, 0]], CV("--line-2"), 1, [3, 3]);
      pp.clip(() => pp.line(prog, CV("--accent-2"), 2.2));

      readout.innerHTML =
        'ความสูงปลาย = <b class="' + (hk > 170 && hk < 240 ? "good" : "bad") + '">' + (hit ? "ตกกลับพื้น" : hk.toFixed(0) + " กม.") + '</b>' +
        '<span>V<sub>x</sub> = <b class="' + (vx > 7200 ? "good" : "bad") + '">' + (vx / 1000).toFixed(2) + ' กม./с</b></span>' +
        '<span>V<sub>y</sub> = <b class="' + (Math.abs(vy) < 250 ? "good" : "") + '">' + vy.toFixed(0) + ' м/с</b></span>' +
        '<span>ϑ ปลาย = <b>' + thK.toFixed(1) + '°</b></span>' +
        '<span class="' + (ok ? "good" : "bad") + '">' +
          (ok ? "เข้าวงโคจรได้ — ความสูงและความเร็วครบพร้อมกัน"
              : hit ? "ก้มเร็วเกินไป จรวดตกกลับพื้น"
              : hk > 240 ? "ก้มช้าเกินไป พุ่งสูงเกินและ V_x ยังไม่พอ"
              : vx < 7200 ? "V_x ยังไม่ถึงความเร็ววงโคจร"
              : "V_y ยังไม่เข้าใกล้ศูนย์ — วิถียังไม่ราบ") + '</span>';
    }
  });
}

/* ---- 2. เขตเสถียรภาพบนระนาบ Kϑ–Kϑ̇ ---- */
function demoSurnStab(host) {
  buildDemo(host, {
    label: "Лекция 18 · области устойчивости",
    title: "เขตเสถียรภาพของระบบทรงตัวเชิงมุมบนระนาบสัมประสิทธิ์",
    ratio: 0.62,
    legend: '<span><i style="background:var(--wash)"></i>เขตเสถียร</span><span><i style="background:var(--accent)"></i>ขอบจากอากาศพลศาสตร์</span><span><i style="background:var(--accent-2)"></i>ขอบจาก T<sub>РП1</sub></span><span><i style="background:#4F7FD0"></i>ขอบจาก T<sub>РП2</sub></span><span><i class="dot" style="background:var(--ink)"></i>จุดทำงาน Р.Т.</span>',
    controls: [
      { id: "aqq", label: "a<sub>ϑ</sub><sup>ϑ</sup> — เสถียรภาพสถิต", min: -1.2, max: 0.6, step: 0.02, value: -0.55, fmt: v => v.toFixed(2) + (v < 0 ? " (ไม่เสถียร)" : "") },
      { id: "aqd", label: "a<sub>ϑ</sub><sup>δ</sup> — ประสิทธิผลหาง", min: 0.15, max: 1.2, step: 0.01, value: 0.55, fmt: v => v.toFixed(2) },
      { id: "T1", label: "T<sub>РП1</sub> — ความเร็วของมอเตอร์ขับ", min: 0.06, max: 0.5, step: 0.005, value: 0.22, fmt: v => v.toFixed(3) + " с" },
      { id: "T2", label: "T<sub>РП2</sub> — ความเฉื่อยของภาระ", min: 0.02, max: 0.3, step: 0.005, value: 0.16, fmt: v => v.toFixed(3) + " с" },
      { id: "fq", label: "จุดทำงาน ตามแกน K<sub>ϑ</sub>", min: 0.02, max: 0.98, step: 0.01, value: 0.34, fmt: v => (v * 100).toFixed(0) + " % ของแกน" },
      { id: "fqd", label: "จุดทำงาน ตามแกน K<sub>ϑ̇</sub>", min: 0.02, max: 0.98, step: 0.01, value: 0.4, fmt: v => (v * 100).toFixed(0) + " % ของแกน" }
    ],
    draw(ctx, w, h, s, readout) {
      const aqq = s.aqq, aqd = s.aqd, T1 = s.T1, T2 = s.T2;
      const stable = (Kq, Kqd) => {
        const a0 = T2 * T2, a1 = T1, a2 = 1 + T2 * T2 * aqq,
              a3 = T1 * aqq + Kqd * aqd, a4 = Kq * aqd + aqq;
        if (a0 <= 0 || a1 <= 0 || a2 <= 0 || a3 <= 0 || a4 <= 0) return false;
        return a3 * (a1 * a2 - a0 * a3) - a4 * a1 * a1 > 0;
      };
      const Kmin = Math.max(0, -aqq / aqd);
      const slope = -(T2 * T2 / T1) * aqq + 1 / T1;
      const c2 = (T2 * T2 / (T1 * T1)) * aqd;
      const KdV = slope / (2 * c2);
      const KqV = slope * slope / (4 * c2);
      const xmax = Math.max(1.2 * Math.min(KqV, 60), Math.max(Kmin, 0.4) * 3, 2);
      const ymax = Math.max(1.35 * Math.min(KdV, 14), 0.5);
      const Kq = s.fq * xmax, Kqd = s.fqd * ymax;

      const p = new Plot(ctx, 58, 12, w - 76, h - 48, 0, xmax, 0, ymax);
      const nx = 168, ny = 100;
      ctx.save();
      ctx.fillStyle = CV("--wash");
      for (let i = 0; i < nx; i++) {
        for (let j = 0; j < ny; j++) {
          if (stable((i + 0.5) / nx * xmax, (j + 0.5) / ny * ymax)) {
            const x0 = p.X(i / nx * xmax), x1 = p.X((i + 1) / nx * xmax);
            const y0 = p.Y((j + 1) / ny * ymax), y1 = p.Y(j / ny * ymax);
            ctx.fillRect(x0, y0, x1 - x0 + 0.7, y1 - y0 + 0.7);
          }
        }
      }
      ctx.restore();
      p.frame(ticks(0, xmax, 5).map(v => +v.toFixed(1)), ticks(0, ymax, 4).map(v => +v.toFixed(2)), "K_ϑ", "K_ϑ̇");

      if (Kmin > 0 && Kmin < xmax) p.line([[Kmin, 0], [Kmin, ymax]], CV("--accent"), 2);
      p.clip(() => p.line([[0, 0], [xmax, T1 * xmax]], CV("--accent-2"), 2));
      const par = [];
      for (let i = 0; i <= 200; i++) {
        const kd = i / 200 * ymax;
        par.push([kd * slope - c2 * kd * kd, kd]);
      }
      p.clip(() => p.line(par, "#4F7FD0", 2));

      const inside = stable(Kq, Kqd);
      ctx.save();
      ctx.strokeStyle = CV("--panel"); ctx.lineWidth = 2.5;
      ctx.fillStyle = inside ? CV("--ink") : CV("--crit");
      ctx.beginPath(); ctx.arc(p.X(Kq), p.Y(Kqd), 6, 0, 7); ctx.fill(); ctx.stroke();
      ctx.font = '11px "IBM Plex Mono", monospace'; ctx.fillStyle = CV("--ink");
      ctx.fillText("Р.Т.", p.X(Kq) + 10, p.Y(Kqd) - 9);
      ctx.restore();

      let margin = 1;
      for (let d = 1; d <= 50; d++) {
        const r = d / 50;
        let bad = false;
        for (let a = 0; a < 20; a++) {
          const th = a / 20 * 2 * Math.PI;
          if (!stable(Kq + r * 0.22 * xmax * Math.cos(th), Kqd + r * 0.22 * ymax * Math.sin(th))) { bad = true; break; }
        }
        if (bad) { margin = r; break; }
      }
      const closed = KqV < xmax * 1.1;

      readout.innerHTML =
        'จุดทำงาน K<sub>ϑ</sub> = <b>' + Kq.toFixed(2) + '</b>' +
        '<span>K<sub>ϑ̇</sub> = <b>' + Kqd.toFixed(2) + '</b></span>' +
        '<span>K<sub>ϑ</sub> ต่ำสุด = <b>' + (Kmin > 0 ? Kmin.toFixed(2) : "0 · จรวดเสถียรเอง") + '</b></span>' +
        '<span>K<sub>ϑ̇</sub>/K<sub>ϑ</sub> = <b class="' + (Kqd / Math.max(Kq, 1e-6) > T1 ? "good" : "bad") + '">' + (Kqd / Math.max(Kq, 1e-6)).toFixed(3) + '</b> ต้อง &gt; T<sub>РП1</sub></span>' +
        '<span>ระยะถึงขอบใกล้สุด = <b class="' + (margin > 0.35 ? "good" : "bad") + '">' + (margin * 100).toFixed(0) + ' %</b></span>' +
        '<span class="' + (inside ? "good" : "bad") + '">' + (inside ? "จุดทำงานอยู่ในเขตเสถียร" : "จุดทำงานอยู่นอกเขต — ระบบไม่เสถียร") + '</span>' +
        (closed ? '' : '<span>ยอดพาราโบลาอยู่นอกกรอบ — ชุดขับเร็วมากจนขอบบนแทบไม่จำกัด</span>');
    }
  });
}

/* ---- 3. ผลตอบสนองของตัวควบคุมทรงตัว ---- */
function demoSurnAs(host) {
  buildDemo(host, {
    label: "Лекция 17 · ПД-закон",
    title: "ผลตอบสนองของช่อง Pitch เมื่อโดนโมเมนต์รบกวนกระแทกที่วินาทีที่ 0,5",
    ratio: 0.58,
    legend: '<span><i style="background:var(--accent)"></i>Δϑ(t)</span><span><i style="background:var(--ink-3)"></i>δ<sub>т</sub>(t) มุมเบนหาง</span><span><i style="background:var(--line-2)"></i>ขีดจำกัด ±30°</span>',
    controls: [
      { id: "Kq", label: "K<sub>ϑ</sub>", min: 0.1, max: 6, step: 0.05, value: 2.2, fmt: v => v.toFixed(2) },
      { id: "Kqd", label: "K<sub>ϑ̇</sub>", min: 0, max: 2.4, step: 0.02, value: 0.85, fmt: v => v.toFixed(2) },
      { id: "aqq", label: "a<sub>ϑ</sub><sup>ϑ</sup>", min: -1.2, max: 0.6, step: 0.02, value: -0.55, fmt: v => v.toFixed(2) },
      { id: "Trp", label: "T<sub>РП</sub>", min: 0.03, max: 0.36, step: 0.005, value: 0.1, fmt: v => v.toFixed(3) + " с" }
    ],
    draw(ctx, w, h, s, readout) {
      const aqd = 0.55, dt = 0.002, tmax = 12, N = Math.round(tmax / dt);
      let q = 0, qd = 0, d = 0;
      const ys = [], ds = [];
      let peak = 0, blown = false, last = 0;
      for (let i = 0; i <= N; i++) {
        const t = i * dt;
        const f = (t > 0.5 && t < 0.8) ? 0.5 : 0;
        const u = s.Kq * q + s.Kqd * qd;
        d += (u - d) / s.Trp * dt;
        const dc = Math.max(-30 * Math.PI / 180, Math.min(30 * Math.PI / 180, d));
        const qdd = -aqd * dc - s.aqq * q + f;
        qd += qdd * dt; q += qd * dt;
        if (!isFinite(q) || Math.abs(q) > 1.6) { blown = true; break; }
        if (t > 0.8 && Math.abs(q) > peak) peak = Math.abs(q);
        if (i % 12 === 0) { ys.push([t, q * 180 / Math.PI]); ds.push([t, dc * 180 / Math.PI]); }
        last = q;
      }
      let ts = 0;
      for (let i = ys.length - 1; i >= 0; i--) { if (Math.abs(ys[i][1]) > 0.15) { ts = ys[i][0]; break; } }

      const gap = 26, hA = (h - 46) * 0.6, hB = (h - 46) - hA - gap;
      const ymax = Math.max(3, peak * 180 / Math.PI * 1.25);
      const p = new Plot(ctx, 52, 10, w - 68, hA, 0, tmax, -ymax, ymax);
      p.frame(ticks(0, tmax, 6), ticks(-ymax, ymax, 4).map(v => +v.toFixed(1)), "", "Δϑ, °", true);
      p.line([[0, 0], [tmax, 0]], CV("--line-2"), 1, [3, 3]);
      p.clip(() => p.line(ys, blown ? CV("--crit") : CV("--accent"), 2));

      const pu = new Plot(ctx, 52, 10 + hA + gap, w - 68, hB, 0, tmax, -36, 36);
      pu.frame(ticks(0, tmax, 6), [-30, 0, 30], "t, с", "δ, °");
      pu.line([[0, 30], [tmax, 30]], CV("--line-2"), 1, [4, 3]);
      pu.line([[0, -30], [tmax, -30]], CV("--line-2"), 1, [4, 3]);
      pu.clip(() => pu.line(ds, CV("--ink-3"), 1.6));

      const need = s.Kq > (s.aqq < 0 ? -s.aqq / aqd : 0) && s.Kqd / Math.max(s.Kq, 1e-6) > s.Trp;
      readout.innerHTML = blown
        ? '<b class="bad">ระบบไม่เสถียร — มุมโตจนหลุดจากกรอบเชิงเส้น</b><span>ลองเพิ่ม K<sub>ϑ̇</sub> หรือ K<sub>ϑ</sub></span>'
        : 'มุมเบี่ยงสูงสุด = <b>' + (peak * 180 / Math.PI).toFixed(2) + '°</b>' +
          '<span>เวลาเข้าที่ = <b>' + (ts > 11.5 ? "> 12 с" : ts.toFixed(2) + " с") + '</b></span>' +
          '<span>ค่าค้าง = <b>' + (last * 180 / Math.PI).toFixed(3) + '°</b></span>' +
          '<span>K<sub>ϑ̇</sub>/K<sub>ϑ</sub> = <b class="' + (s.Kqd / Math.max(s.Kq, 1e-6) > s.Trp ? "good" : "bad") + '">' + (s.Kqd / Math.max(s.Kq, 1e-6)).toFixed(3) + '</b> ต้อง &gt; T<sub>РП</sub></span>' +
          '<span class="' + (need ? "good" : "bad") + '">' + (need ? "ผ่านทั้งเงื่อนไขจำเป็นและเพียงพอ" : "ยังไม่ผ่านเงื่อนไขของเฮอร์วิตซ์") + '</span>';
    }
  });
}

/* ---- 4. ของเหลวกระฉอกในถัง ---- */
function demoSurnSlosh(host) {
  buildDemo(host, {
    label: "Лекция 19 · колебания жидкости",
    title: "คลื่นในถังกับตำแหน่งของถังเทียบจุดศูนย์กลางมวล",
    ratio: 0.52,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>มุมจรวด Δϑ</span><span><i style="background:#4F7FD0"></i>คลื่นในถัง β</span><span>เลื่อนสไลเดอร์ x<sub>кж</sub> ข้ามศูนย์เพื่อสลับระหว่างถังล่างกับถังบน</span>',
    controls: [
      { id: "x", label: "x<sub>кж</sub> — ตำแหน่งถังเทียบ ц.м.", min: -1, max: 1, step: 0.02, value: 0.6, fmt: v => v > 0.03 ? "+" + v.toFixed(2) + " · ถังบน" : v < -0.03 ? v.toFixed(2) + " · ถังล่าง" : "0 · ตรง ц.м." },
      { id: "zb", label: "การหน่วงภายในของเหลว", min: 0.004, max: 0.09, step: 0.002, value: 0.012, fmt: v => v.toFixed(3) },
      { id: "mu", label: "สัดส่วนมวลของเหลวที่แกว่ง", min: 0.04, max: 0.34, step: 0.01, value: 0.16, fmt: v => (v * 100).toFixed(0) + " %" }
    ],
    draw(ctx, w, h, s, readout, tAnim) {
      const wb = 2.6, dt = 0.002, tmax = 40, N = Math.round(tmax / dt);
      const Kq = 2.2, Kqd = 0.85, aqd = 0.55, aqq = -0.3, ayq = -55, K4 = 0.35;
      const aqB = -0.9 * s.mu * s.x, ayB = -0.9 * s.mu, abY = -K4, abQ = -K4 * s.x;
      let q = 0.03, qd = 0, b = 0, bd = 0, qdd = 0, bdd = 0;
      const qs = [], bs = [];
      let diverge = false, amp0 = 0, ampN = 0;
      for (let i = 0; i <= N; i++) {
        const t = i * dt;
        const u = Kq * q + Kqd * qd;
        const ydd = -ayq * q - ayB * bdd;
        const bdd2 = -2 * s.zb * wb * bd - wb * wb * b - abY * ydd - abQ * qdd;
        const qdd2 = -aqd * u - aqq * q - aqB * bdd2;
        bdd = bdd2; qdd = qdd2;
        bd += bdd * dt; b += bd * dt;
        qd += qdd * dt; q += qd * dt;
        if (!isFinite(q) || Math.abs(q) > 5) { diverge = true; break; }
        if (t > 4 && t < 10) amp0 = Math.max(amp0, Math.abs(b));
        if (t > tmax - 8) ampN = Math.max(ampN, Math.abs(b));
        if (i % 40 === 0) { qs.push([t, q * 60]); bs.push([t, b * 12]); }
      }
      const grow = diverge || ampN > amp0 * 1.02;

      const rw = Math.min(190, w * 0.27);
      const cx = rw / 2 + 14, cy = h / 2;
      const ph = tAnim * wb;
      const tilt = 0.11 * Math.sin(ph);
      ctx.save();
      ctx.translate(cx, cy); ctx.rotate(tilt);
      ctx.strokeStyle = CV("--ink-2"); ctx.lineWidth = 1.6; ctx.fillStyle = CV("--panel");
      ctx.beginPath();
      ctx.moveTo(0, -112); ctx.lineTo(21, -72); ctx.lineTo(21, 108); ctx.lineTo(-21, 108); ctx.lineTo(-21, -72); ctx.closePath();
      ctx.fill(); ctx.stroke();
      const ty = -s.x * 64;
      ctx.strokeStyle = CV("--line-2");
      ctx.strokeRect(-17, ty - 27, 34, 54);
      const wl = ty + 5, tw = 9 * Math.sin(ph + 1.1);
      ctx.save();
      ctx.beginPath(); ctx.rect(-17, ty - 27, 34, 54); ctx.clip();
      ctx.beginPath();
      ctx.moveTo(-17, wl - tw); ctx.lineTo(17, wl + tw); ctx.lineTo(17, ty + 27); ctx.lineTo(-17, ty + 27); ctx.closePath();
      ctx.fillStyle = "#4F7FD0"; ctx.globalAlpha = 0.55; ctx.fill();
      ctx.restore();
      ctx.strokeStyle = CV("--accent-2"); ctx.setLineDash([3, 3]); ctx.lineWidth = 1.2;
      ctx.beginPath(); ctx.moveTo(-28, 0); ctx.lineTo(28, 0); ctx.stroke();
      ctx.restore();
      ctx.save();
      ctx.fillStyle = CV("--ink-3"); ctx.font = '10.5px "IBM Plex Mono", monospace'; ctx.textAlign = "center";
      ctx.fillText("ц.м.", cx + 44, cy + 4);
      ctx.fillStyle = grow ? CV("--crit") : CV("--ok");
      ctx.fillText(s.x > 0.03 ? "ถังบน" : s.x < -0.03 ? "ถังล่าง" : "ที่ ц.м.", cx, cy - s.x * 64 - 36);
      ctx.restore();

      const px = rw + 44;
      const ymax = Math.max(1.2, Math.max(...bs.map(v => Math.abs(v[1])), ...qs.map(v => Math.abs(v[1]))) * 1.12);
      const p = new Plot(ctx, px, 12, w - px - 20, h - 46, 0, tmax, -ymax, ymax);
      p.frame(ticks(0, tmax, 5), ticks(-ymax, ymax, 4).map(v => +v.toFixed(1)), "t, с", "");
      p.line([[0, 0], [tmax, 0]], CV("--line-2"), 1, [3, 3]);
      p.clip(() => { p.line(bs, "#4F7FD0", 1.5); p.line(qs, grow ? CV("--crit") : CV("--accent"), 2); });

      readout.innerHTML =
        'a<sub>ϑ</sub><sup>β̈</sup> ∝ <b class="' + (s.x > 0.03 ? "bad" : "good") + '">' + (s.x > 0.03 ? "ลบ (ถังบน)" : s.x < -0.03 ? "บวก (ถังล่าง)" : "ศูนย์") + '</b>' +
        '<span>แอมพลิจูดคลื่นช่วงต้น = <b>' + amp0.toFixed(3) + '</b></span>' +
        '<span>ช่วงท้าย = <b class="' + (grow ? "bad" : "good") + '">' + (diverge ? "ลู่ออก" : ampN.toFixed(3)) + '</b></span>' +
        '<span class="' + (grow ? "bad" : "good") + '">' + (diverge
          ? "ระบบลู่ออก — ถังบนป้อนพลังงานกลับเข้าไปในคลื่น"
          : grow ? "คลื่นกำลังโตขึ้น — ยืนยันว่าถังบนอันตรายที่สุด"
                 : "คลื่นลู่เข้า — ถังล่างทำให้การป้อนกลับช่วยหน่วง") + '</span>';
    }
  });
}

/* ---- 5. การงอตัวของลำตัวและตำแหน่งเซนเซอร์ ---- */
function demoSurnElastic(host) {
  buildDemo(host, {
    label: "Лекция 20 · упругие колебания корпуса",
    title: "โทนที่หนึ่งของการงอตัว กับตำแหน่งติดตั้งชุดอุปกรณ์คำสั่ง",
    ratio: 0.5,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>แอมพลิจูดการงอ</span><span><i class="dot" style="background:var(--accent-2)"></i>ชุดอุปกรณ์ ККП</span><span><i class="dot" style="background:var(--line-2)"></i>โหนดของการงอ</span>',
    controls: [
      { id: "xs", label: "ตำแหน่ง ККП ตามลำตัว", min: 0.02, max: 0.98, step: 0.01, value: 0.15, fmt: v => v < 0.5 ? "หัวจรวด (จุด I)" : "ท้ายจรวด (จุด II)" },
      { id: "Kqd", label: "K<sub>ϑ̇</sub>", min: 0, max: 2.4, step: 0.02, value: 0.85, fmt: v => v.toFixed(2) },
      { id: "dmp", label: "การหน่วงของโครงสร้าง", min: 0.002, max: 0.08, step: 0.002, value: 0.02, fmt: v => v.toFixed(3) }
    ],
    draw(ctx, w, h, s, readout, tAnim) {
      const NODE = 0.5;
      const shape = u => Math.cos(Math.PI * u);
      const phi = shape(s.xs);
      const adelta = -0.9 * phi;
      const wy = 9.0;
      const damp = s.dmp + adelta * s.Kqd * 0.11;
      const grow = damp < 0;

      const dt = 0.003, tmax = 9, N = Math.round(tmax / dt);
      let a = 0.02, ad = 0;
      const env = [];
      for (let i = 0; i <= N; i++) {
        const add = -2 * damp * wy * ad - wy * wy * a;
        ad += add * dt; a += ad * dt;
        if (!isFinite(a) || Math.abs(a) > 4) break;
        if (i % 12 === 0) env.push([i * dt, a]);
      }

      const rw = Math.min(250, w * 0.36);
      const x0 = 30, len = rw - 52;
      const cy = h / 2;
      const A = 26 * (grow ? 1 : 1) * Math.sin(tAnim * 5.2) * (grow ? Math.min(1.6, 0.7 + 0.35 * tAnim % 1.6) : 1);
      ctx.save();
      ctx.strokeStyle = CV("--line-2"); ctx.lineWidth = 1; ctx.setLineDash([4, 4]);
      ctx.beginPath(); ctx.moveTo(x0, cy); ctx.lineTo(x0 + len, cy); ctx.stroke();
      ctx.restore();
      const HW = u => 11 * Math.min(1, u / 0.12) * (u > 0.9 ? Math.max(0.25, (1 - u) / 0.1) : 1);
      ctx.save();
      ctx.beginPath();
      for (let i = 0; i <= 80; i++) {
        const u = i / 80, X = x0 + u * len, Y = cy + A * shape(u);
        i ? ctx.lineTo(X, Y - HW(u)) : ctx.moveTo(X, Y - HW(u));
      }
      for (let i = 80; i >= 0; i--) {
        const u = i / 80, X = x0 + u * len, Y = cy + A * shape(u);
        ctx.lineTo(X, Y + HW(u));
      }
      ctx.closePath();
      ctx.fillStyle = CV("--panel-2"); ctx.fill();
      ctx.strokeStyle = CV("--accent"); ctx.lineWidth = 1.8; ctx.lineJoin = "round"; ctx.stroke();
      ctx.restore();
      ctx.save();
      ctx.strokeStyle = CV("--accent"); ctx.lineWidth = 1.2; ctx.setLineDash([3, 3]);
      ctx.beginPath();
      for (let i = 0; i <= 60; i++) {
        const u = i / 60, X = x0 + u * len, Y = cy + A * shape(u);
        i ? ctx.lineTo(X, Y) : ctx.moveTo(X, Y);
      }
      ctx.stroke(); ctx.restore();
      ctx.save();
      ctx.fillStyle = CV("--line-2");
      ctx.beginPath(); ctx.arc(x0 + NODE * len, cy, 4, 0, 7); ctx.fill();
      ctx.fillStyle = CV("--accent-2");
      ctx.beginPath(); ctx.arc(x0 + s.xs * len, cy + A * phi, 5.5, 0, 7); ctx.fill();
      ctx.font = '10.5px "IBM Plex Mono", monospace'; ctx.fillStyle = CV("--ink-3"); ctx.textAlign = "center";
      ctx.fillText("โหนด", x0 + NODE * len, cy + 30);
      ctx.fillText("หัวจรวด", x0 + 4, cy + 62); ctx.fillText("ท้ายจรวด", x0 + len - 4, cy + 62);
      ctx.fillStyle = CV("--accent-2");
      ctx.fillText("ККП", x0 + s.xs * len, cy - 20);
      ctx.restore();

      const px = rw + 44;
      const ymax = Math.max(0.06, Math.max(...env.map(e => Math.abs(e[1]))) * 1.15);
      const p = new Plot(ctx, px, 12, w - px - 18, h - 46, 0, tmax, -ymax, ymax);
      p.frame(ticks(0, tmax, 5), ticks(-ymax, ymax, 4).map(v => +v.toFixed(2)), "t, с", "Δϑ_y");
      p.line([[0, 0], [tmax, 0]], CV("--line-2"), 1, [3, 3]);
      p.clip(() => p.line(env, grow ? CV("--crit") : CV("--accent"), 2));

      readout.innerHTML =
        'φ ที่ตำแหน่งเซนเซอร์ = <b>' + phi.toFixed(2) + '</b>' +
        '<span>a<sub>Δϑy</sub><sup>δ</sup> = <b class="' + (adelta < 0 ? "bad" : "good") + '">' + adelta.toFixed(2) + '</b></span>' +
        '<span>การหน่วงรวม = <b class="' + (grow ? "bad" : "good") + '">' + damp.toFixed(3) + '</b></span>' +
        '<span class="' + (grow ? "bad" : "good") + '">' + (grow ? "จุด I — พจน์ a^δ·K_ϑ̇ ลบการหน่วงออก ระบบขับตัวเองให้แกว่ง" : "จุด II — พจน์ a^δ·K_ϑ̇ เพิ่มการหน่วง ระบบสงบลง") + '</span>';
    }
  });
}

/* ---- 6. ระบบควบคุมการใช้เชื้อเพลิง ---- */
function demoSurnSurt(host) {
  buildDemo(host, {
    label: "Лекция 12 · СУРТ",
    title: "ถังสองใบต้องหมดพร้อมกัน — ผลของการเปิดและปิดระบบ",
    ratio: 0.52,
    animate: true,
    buttons: [{ label: "เปิด СУРТ", toggle: true, id: "on", value: true }],
    legend: '<span><i style="background:#4F7FD0"></i>สารออกซิไดเซอร์ (окислитель)</span><span><i style="background:var(--accent-2)"></i>เชื้อเพลิง (горючее)</span><span><i style="background:var(--ink-3)"></i>มุม дроссель δ<sub>др</sub></span><span><i style="background:var(--line-2)"></i>เวลาที่ตั้งใจจะดับเครื่อง</span>',
    controls: [
      { id: "dv", label: "ความคลาดของการเติม", min: -5, max: 5, step: 0.1, value: 2.6, fmt: v => (v > 0 ? "+" : "") + v.toFixed(1) + " %" },
      { id: "dm", label: "ความคลาดของอัตราไหล", min: -4, max: 4, step: 0.1, value: -1.6, fmt: v => (v > 0 ? "+" : "") + v.toFixed(1) + " %" },
      { id: "gain", label: "อัตราขยายของกฎควบคุม", min: 0.2, max: 5, step: 0.1, value: 2.2, fmt: v => v.toFixed(1) }
    ],
    draw(ctx, w, h, s, readout, tAnim) {
      const Tk = 300, tmax = 380, dt = 0.2, N = Math.round(tmax / dt);
      const V0o = 100 * (1 + s.dv / 100), V0g = 100;
      const q0o = (V0o / Tk) * (1 + s.dm / 100), q0g = V0g / Tk;
      let Vo = V0o, Vg = V0g, d = 0;
      const lo = [], lg = [], dd = [];
      let tO = -1, tG = -1, restAtFirst = 0;
      for (let i = 0; i <= N; i++) {
        const t = i * dt;
        const fo = Vo / V0o, fg = Vg / V0g;
        if (s.on) {
          const err = fo - fg;
          const target = Math.max(-0.3, Math.min(0.3, s.gain * err));
          d += (target - d) * dt / 5;
        }
        const qo = q0o * (1 + d), qg = q0g;
        if (Vo > 0) { Vo = Math.max(0, Vo - qo * dt); if (Vo <= 0) tO = t; }
        if (Vg > 0) { Vg = Math.max(0, Vg - qg * dt); if (Vg <= 0) tG = t; }
        if (tO >= 0 && tG < 0 && restAtFirst === 0) restAtFirst = Vg / V0g * 100;
        if (tG >= 0 && tO < 0 && restAtFirst === 0) restAtFirst = Vo / V0o * 100;
        if (i % 3 === 0) { lo.push([t, Vo / V0o * 100]); lg.push([t, Vg / V0g * 100]); dd.push([t, d * 60]); }
      }
      if (tO < 0) tO = tmax; if (tG < 0) tG = tmax;
      const dtEnd = tO - tG;
      if (Math.abs(dtEnd) < dt * 1.5) restAtFirst = 0;

      const bw = Math.min(150, w * 0.2);
      const idx = Math.min(lo.length - 1, Math.floor(((tAnim * 0.2) % 1) * lo.length));
      const drawTank = (x, val, col, lab) => {
        const th = h - 92, ty = 34;
        ctx.save();
        ctx.strokeStyle = CV("--line-2"); ctx.lineWidth = 1.4;
        ctx.strokeRect(x, ty, 42, th);
        const fh = Math.max(0, Math.min(1, val / 100)) * (th - 4);
        ctx.fillStyle = col; ctx.globalAlpha = 0.5;
        ctx.fillRect(x + 2, ty + th - 2 - fh, 38, fh);
        ctx.globalAlpha = 1;
        ctx.fillStyle = CV("--ink-3"); ctx.font = '10.5px "IBM Plex Mono", monospace'; ctx.textAlign = "center";
        ctx.fillText(lab, x + 21, ty - 10);
        ctx.fillText(val.toFixed(0) + "%", x + 21, ty + th + 16);
        ctx.restore();
      };
      drawTank(16, lo[idx][1], "#4F7FD0", "О");
      drawTank(16 + 60, lg[idx][1], CV("--accent-2"), "Г");

      const px = bw + 42;
      const p = new Plot(ctx, px, 12, w - px - 20, h - 46, 0, tmax, -20, 106);
      p.frame(ticks(0, tmax, 5).map(Math.round), [0, 25, 50, 75, 100], "t, с", "%");
      p.line([[0, 0], [tmax, 0]], CV("--line-2"), 1, [3, 3]);
      p.line([[Tk, -20], [Tk, 106]], CV("--line-2"), 1.4, [5, 4]);
      p.clip(() => { p.line(lo, "#4F7FD0", 2.2); p.line(lg, CV("--accent-2"), 2.2); p.line(dd, CV("--ink-3"), 1.4, [4, 3]); });

      const good = Math.abs(dtEnd) < 3;
      readout.innerHTML =
        'ระบบ <b>' + (s.on ? "เปิด" : "ปิด") + '</b>' +
        '<span>Δt ที่ปลาย = <b class="' + (good ? "good" : "bad") + '">' + dtEnd.toFixed(1) + ' с</b></span>' +
        '<span>อีกถังเหลือค้าง = <b class="' + (restAtFirst < 1 ? "good" : "bad") + '">' + restAtFirst.toFixed(2) + ' %</b></span>' +
        '<span>มุม дроссель สูงสุด = <b>' + Math.max(...dd.map(v => Math.abs(v[1]))).toFixed(1) + ' หน่วย</b></span>' +
        '<span class="' + (good ? "good" : "bad") + '">' + (good
          ? "หมดพร้อมกัน — ตัดเชื้อเพลิงสำรองรับประกันออกได้ กลายเป็นมวลบรรทุก"
          : "หมดไม่พร้อมกัน — ต้องบรรทุกเชื้อเพลิงสำรองเผื่อไว้เท่ากับส่วนที่เหลือค้าง") + '</span>';
    }
  });
}

Object.assign(DEMOS, {
  surnTraj: demoSurnTraj,
  surnStab: demoSurnStab,
  surnAs: demoSurnAs,
  surnSlosh: demoSurnSlosh,
  surnElastic: demoSurnElastic,
  surnSurt: demoSurnSurt
});

/* ================= СУ РН — ชุดสื่อเพิ่มเติม ================= */

/* ---- 7. เครื่องคิดเลขอัลกอริทึมนำวิถีจากสมการเต็ม (лек. 11) ---- */
function demoSurnCalc(host) {
  const c = 3200, tau = 420, g = 9.81, Vx0 = 1500, Vy0 = 900, y0 = 50000, Vz0 = 12;
  const left = (T, s) => Math.hypot(s.Vxk - Vx0, s.Vyk - Vy0 + g * T);
  const right = T => c * Math.log(tau / (tau - T));
  buildDemo(host, {
    label: "Лекция 11 · шаги 1—4",
    title: "เครื่องคิดเลขอัลกอริทึมนำวิถี — หา T → ϑ₀ → อินทิกรัล → k₁…k₄",
    ratio: 0.66,
    legend: '<span><i style="background:var(--accent)"></i>ด้านซ้าย √[(ΔV<sub>x</sub>)² + (ΔV<sub>y</sub>+gT)²] — อิมพัลส์ที่ต้องการ</span>' +
      '<span><i style="background:var(--accent-2)"></i>ด้านขวา c·ln[τ/(τ−T)] — อิมพัลส์ที่เครื่องยนต์ให้ได้</span>' +
      '<span><i class="dot" style="background:var(--ink)"></i>จุดตัด = คำตอบ T</span>' +
      '<span><i style="background:var(--ok)"></i>ϑ<sub>п</sub>(t)</span><span><i style="background:var(--crit)"></i>ψ<sub>п</sub>(t)</span>',
    controls: [
      { id: "Vxk", label: "V<sub>xк</sub> — ความเร็วแนวนอนที่ต้องการ", min: 6600, max: 7800, step: 20, value: 7300, fmt: v => (v / 1000).toFixed(2) + " กм./с" },
      { id: "Vyk", label: "V<sub>yк</sub> — ความเร็วแนวดิ่งที่ต้องการ", min: 0, max: 800, step: 10, value: 300, fmt: v => v + " м/с" },
      { id: "hk", label: "h<sub>к</sub> — ความสูงปลาย", min: 150, max: 400, step: 5, value: 200, fmt: v => v + " กм." },
      { id: "z0", label: "z₀ — ค่าเบี่ยงข้างตอนเริ่มคำนวณ", min: -1500, max: 1500, step: 50, value: 400, fmt: v => v + " м" }
    ],
    draw(ctx, w, h, s, readout) {
      /* --- ขั้นที่ 1: แก้สมการ (41) ด้วยวิธีแบ่งครึ่ง --- */
      const f = T => left(T, s) - right(T);
      let lo = 1, hi = tau - 1, T = NaN;
      if (f(lo) * f(hi) < 0) {
        for (let i = 0; i < 90; i++) { const m = (lo + hi) / 2; if (f(lo) * f(m) <= 0) hi = m; else lo = m; }
        T = (lo + hi) / 2;
      }
      const ok = isFinite(T);
      /* --- ขั้นที่ 2: (42) --- */
      const th0 = ok ? Math.atan2(s.Vyk - Vy0 + g * T, s.Vxk - Vx0) : 0;
      /* --- ขั้นที่ 3: อินทิกรัล (36)–(39) --- */
      const Ia = ok ? c * Math.log(tau / (tau - T)) : 0;
      const Iat = tau * Ia - c * T, I2a = T * Ia - Iat, I2at = tau * I2a - c * T * T / 2;
      const D = Ia * I2at - Iat * I2a;
      /* --- ขั้นที่ 4: (43) และ (44) --- */
      const dyk = -(1 / Math.cos(th0)) * (s.hk * 1000 - y0 - Vy0 * T + g * T * T / 2 - I2a * Math.sin(th0));
      const k1 = -Iat * dyk / D, k2 = Ia * dyk / D;
      const rz = -s.z0 - Vz0 * T;
      const k3 = ((-Vz0) * I2at - Iat * rz) / D, k4 = (Ia * rz - (-Vz0) * I2a) / D;

      const gap = 34, hA = (h - 48) * 0.54, hB = (h - 48) - hA - gap, DEG = 180 / Math.PI;
      /* แผงบน: สองข้างของสมการ (41) */
      const Lc = [], Rc = [];
      for (let i = 0; i <= 240; i++) { const t = 5 + (tau - 15) * i / 240; Lc.push([t, left(t, s)]); Rc.push([t, right(t)]); }
      const ymax = Math.max(9000, Math.ceil(left(tau - 15, s) / 2000) * 2000);
      const p = new Plot(ctx, 62, 8, w - 78, hA, 0, tau, 0, ymax);
      p.frame(ticks(0, tau, 6).map(Math.round), ticks(0, ymax, 4).map(Math.round), "T, с", "м/с");
      p.clip(() => { p.line(Lc, CV("--accent"), 2.2); p.line(Rc, CV("--accent-2"), 2.2); });
      if (ok) {
        ctx.save();
        ctx.strokeStyle = CV("--line-2"); ctx.lineWidth = 1.2; ctx.setLineDash([4, 4]);
        ctx.beginPath(); ctx.moveTo(p.X(T), p.y); ctx.lineTo(p.X(T), p.y + p.h); ctx.stroke();
        ctx.setLineDash([]); ctx.fillStyle = CV("--ink");
        ctx.beginPath(); ctx.arc(p.X(T), p.Y(Ia), 4.6, 0, 7); ctx.fill();
        ctx.font = '600 11px "IBM Plex Mono", monospace'; ctx.textAlign = "center"; ctx.textBaseline = "bottom";
        ctx.fillText("T = " + T.toFixed(1) + " с", p.X(T), p.Y(Ia) - 9);
        ctx.restore();
      }
      /* แผงล่าง: โปรแกรมมุม */
      if (ok) {
        const th = [], ps = [];
        for (let i = 0; i <= 200; i++) {
          const t = T * i / 200;
          th.push([t, (th0 - (k1 + k2 * t)) * DEG]);
          ps.push([t, (-k3 - k4 * t) * DEG]);
        }
        const all = th.concat(ps).map(q => q[1]);
        const lo2 = Math.floor(Math.min(...all, -5) / 10) * 10, hi2 = Math.ceil(Math.max(...all, 5) / 10) * 10;
        const pp = new Plot(ctx, 62, 8 + hA + gap, w - 78, hB, 0, T, lo2, hi2);
        pp.frame(ticks(0, T, 5).map(Math.round), ticks(lo2, hi2, 4).map(Math.round), "t, с", "°");
        pp.line([[0, 0], [T, 0]], CV("--line-2"), 1, [3, 3]);
        pp.clip(() => { pp.line(th, CV("--ok"), 2.2); pp.line(ps, CV("--crit"), 2.2); });
      }

      readout.innerHTML = ok
        ? 'T = <b>' + T.toFixed(1) + ' с</b>' +
          '<span>ϑ₀ = <b>' + (th0 * DEG).toFixed(2) + '°</b></span>' +
          '<span>I<sub>a</sub> = <b>' + Ia.toFixed(0) + ' м/с</b></span>' +
          '<span>k₁ = <b>' + (k1 * DEG).toFixed(2) + '°</b></span>' +
          '<span>k₂ = <b>' + (k2 * DEG).toFixed(4) + ' °/с</b></span>' +
          '<span>k₃ = <b>' + (k3 * DEG).toFixed(2) + '°</b></span>' +
          '<span>k₄ = <b>' + (k4 * DEG).toFixed(5) + ' °/с</b></span>' +
          '<span>ϑ<sub>п</sub>: <b>' + ((th0 - k1) * DEG).toFixed(1) + '° → ' + ((th0 - k1 - k2 * T) * DEG).toFixed(1) + '°</b></span>'
        : '<b class="bad">ไม่มีคำตอบ — เชื้อเพลิงไม่พอสำหรับอิมพัลส์ที่สั่ง (เส้นสองเส้นไม่ตัดกันก่อน T = τ)</b>';
    }
  });
}

/* ---- 8. มุมท่าทางสามมุมและระนาบอ้างอิง (лек. 3) ---- */
function demoSurnAng(host) {
  buildDemo(host, {
    label: "Лекция 3 · углы ориентации",
    title: "ϑ, ψ, φ — นิยามที่อ้าง «ระนาบ» คนละระนาบกัน",
    ratio: 0.44,
    legend: '<span><i style="background:var(--accent)"></i>แกนตามยาวของจรวด</span><span><i style="background:var(--line-2)"></i>ระนาบขอบฟ้า / ระนาบการยิง</span><span><i style="background:var(--accent-2)"></i>มุมที่กำลังวัด</span>',
    controls: [
      { id: "th", label: "ϑ — มุม Pitch (тангаж)", min: 0, max: 90, step: 1, value: 55, fmt: v => v + "°" },
      { id: "ps", label: "ψ — มุม Yaw (рыскание)", min: -30, max: 30, step: 1, value: 12, fmt: v => v + "°" },
      { id: "ph", label: "φ — มุม Roll (вращение)", min: -180, max: 180, step: 2, value: 30, fmt: v => v + "°" }
    ],
    draw(ctx, w, h, s, readout) {
      const DR = Math.PI / 180, pad = 12;
      const pw = (w - pad * 2) / 3, ph = h - 26;
      const titles = ["มองด้านข้าง — ระนาบขอบฟ้า", "มองจากด้านบน — ระนาบการยิง", "มองจากท้าย — แกนตามยาว"];
      const draws = [
        (cx, cy, R) => { /* side: pitch */
          ctx.strokeStyle = CV("--line-2"); ctx.lineWidth = 1.4; ctx.setLineDash([5, 4]);
          ctx.beginPath(); ctx.moveTo(cx - R, cy); ctx.lineTo(cx + R, cy); ctx.stroke(); ctx.setLineDash([]);
          arcAng(cx, cy, R * 0.52, 0, -s.th * DR, "ϑ = " + s.th + "°");
          rocket(cx, cy, R * 0.92, -s.th * DR);
          lab(cx, ph + 10, "плоскость горизонта", "center");
        },
        (cx, cy, R) => { /* top: yaw */
          ctx.strokeStyle = CV("--line-2"); ctx.lineWidth = 1.4; ctx.setLineDash([5, 4]);
          ctx.beginPath(); ctx.moveTo(cx - R, cy); ctx.lineTo(cx + R, cy); ctx.stroke(); ctx.setLineDash([]);
          arcAng(cx, cy, R * 0.52, 0, s.ps * DR, "ψ = " + s.ps + "°");
          rocket(cx, cy, R * 0.92, s.ps * DR);
          lab(cx, ph + 10, "плоскость стрельбы", "center");
        },
        (cx, cy, R) => { /* rear: roll */
          ctx.save(); ctx.strokeStyle = CV("--line"); ctx.lineWidth = 1.2;
          ctx.beginPath(); ctx.arc(cx, cy, R * 0.62, 0, 7); ctx.stroke();
          ctx.strokeStyle = CV("--line-2"); ctx.setLineDash([5, 4]);
          ctx.beginPath(); ctx.moveTo(cx, cy - R * 0.8); ctx.lineTo(cx, cy + R * 0.8); ctx.stroke();
          ctx.setLineDash([]); ctx.restore();
          arcAng(cx, cy, R * 0.40, -Math.PI / 2, -Math.PI / 2 + s.ph * DR, "φ = " + s.ph + "°");
          ctx.save(); ctx.translate(cx, cy); ctx.rotate(s.ph * DR);
          ctx.strokeStyle = CV("--accent"); ctx.lineWidth = 2.6; ctx.lineCap = "round";
          ctx.beginPath(); ctx.moveTo(0, -R * 0.62); ctx.lineTo(0, R * 0.62); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(-R * 0.30, 0); ctx.lineTo(R * 0.30, 0); ctx.stroke();
          ctx.fillStyle = CV("--accent-2");
          ctx.beginPath(); ctx.arc(0, -R * 0.62, 4.4, 0, 7); ctx.fill();
          ctx.restore();
          lab(cx, ph + 10, "แกน I ของลำตัว", "center");
        }
      ];
      function lab(x, y, t, al) {
        ctx.save(); ctx.fillStyle = CV("--ink-3"); ctx.font = '10.5px "IBM Plex Mono", monospace';
        ctx.textAlign = al || "left"; ctx.textBaseline = "top"; ctx.fillText(t, x, y); ctx.restore();
      }
      function arcAng(cx, cy, r, a0, a1, txt) {
        ctx.save(); ctx.strokeStyle = CV("--accent-2"); ctx.lineWidth = 1.8;
        ctx.beginPath(); ctx.arc(cx, cy, r, Math.min(a0, a1), Math.max(a0, a1)); ctx.stroke();
        const am = (a0 + a1) / 2;
        ctx.fillStyle = CV("--accent-2"); ctx.font = '600 11.5px "IBM Plex Mono", monospace';
        const lx = cx + Math.cos(am) * (r + 14), ly = cy + Math.sin(am) * (r + 14);
        ctx.textAlign = Math.cos(am) >= 0 ? "left" : "right";
        ctx.textBaseline = Math.sin(am) > 0.2 ? "top" : Math.sin(am) < -0.2 ? "bottom" : "middle";
        ctx.fillText(txt, lx, ly);
        ctx.restore();
      }
      function rocket(cx, cy, L, a) {
        ctx.save(); ctx.translate(cx, cy); ctx.rotate(a);
        ctx.fillStyle = CV("--accent"); ctx.strokeStyle = CV("--accent"); ctx.lineWidth = 1.4;
        const bw = 7;
        ctx.beginPath();
        ctx.moveTo(L, 0); ctx.lineTo(L - 22, -bw); ctx.lineTo(-L * 0.55, -bw);
        ctx.lineTo(-L * 0.55, -bw - 5); ctx.lineTo(-L * 0.72, -bw - 5);
        ctx.lineTo(-L * 0.72, bw + 5); ctx.lineTo(-L * 0.55, bw + 5);
        ctx.lineTo(-L * 0.55, bw); ctx.lineTo(L - 22, bw); ctx.closePath();
        ctx.globalAlpha = .18; ctx.fill(); ctx.globalAlpha = 1; ctx.stroke();
        ctx.setLineDash([4, 3]); ctx.lineWidth = 1.1;
        ctx.beginPath(); ctx.moveTo(-L * 0.8, 0); ctx.lineTo(L + 12, 0); ctx.stroke();
        ctx.restore();
      }
      for (let i = 0; i < 3; i++) {
        const cx = pad + pw * i + pw / 2, cy = 22 + ph / 2, R = Math.min(pw * 0.44, ph * 0.42);
        ctx.save(); ctx.fillStyle = CV("--ink-2"); ctx.font = '600 11.5px "IBM Plex Sans Thai", sans-serif';
        ctx.textAlign = "center"; ctx.textBaseline = "top"; ctx.fillText(titles[i], cx, 2); ctx.restore();
        draws[i](cx, cy, R);
      }
      readout.innerHTML =
        '<span><b>ϑ</b> = มุมระหว่างแกนตามยาวกับ <b>ระนาบขอบฟ้า</b></span>' +
        '<span><b>ψ</b> = มุมระหว่างแกนตามยาวกับ <b>ระนาบการยิง</b></span>' +
        '<span><b>φ</b> = การหมุนรอบแกนตามยาว</span>' +
        '<span class="bad">ตอบสลับ «ระนาบ» สองอันนี้คือผิดทันที</span>';
    }
  });
}

/* ---- 9. อิมพัลส์หางแรงขับและสามวิธีลด (лек. 9) ---- */
function demoSurnImp(host) {
  buildDemo(host, {
    label: "Лекция 9 · импульс последействия",
    title: "แรงขับไม่ดับทันที — อิมพัลส์หางกับสามวิธีลดผลของมัน",
    ratio: 0.5,
    legend: '<span><i style="background:var(--accent)"></i>P(t)</span><span><i style="background:var(--wash-2)"></i>อิมพัลส์หาง I<sub>пд</sub></span>' +
      '<span><i style="background:var(--ok)"></i>ค่าเฉลี่ยที่ชดเชยได้</span><span><i style="background:var(--crit)"></i>ความแปรปรวนที่เหลือ 3σ</span>',
    buttons: [
      { id: "two", label: "ดับสองขั้น", toggle: true, value: false },
      { id: "ptdu", label: "ПТДУ", toggle: true, value: false },
      { id: "comp", label: "ชดเชยค่าเฉลี่ย", toggle: true, value: true }
    ],
    controls: [
      { id: "dtp", label: "Δt<sub>p</sub> — เวลาที่แรงขับลดจนเป็นศูนย์", min: 0.2, max: 2.0, step: 0.05, value: 0.6, fmt: v => v.toFixed(2) + " с" },
      { id: "sig", label: "การกระจายของอิมพัลส์หาง (σ)", min: 2, max: 30, step: 1, value: 12, fmt: v => v + " %" }
    ],
    draw(ctx, w, h, s, readout) {
      const P0 = 300e3, m = 30000;
      const lvl = s.two ? 0.40 : 1.0;           // แรงขับตอนสั่งดับจริง
      const t1 = 1.2, tStep = s.two ? 0.8 : 0;  // ช่วงลดแรงขับขั้นแรก
      const tEnd = t1 + tStep + s.dtp + 0.6;
      const pts = [];
      const Pof = t => {
        if (t < t1) return P0;
        if (s.two && t < t1 + tStep) return P0 * lvl;
        const u = (t - t1 - tStep) / s.dtp;
        return u >= 1 ? 0 : P0 * lvl * (1 - u) * (1 - u);
      };
      for (let i = 0; i <= 400; i++) { const t = tEnd * i / 400; pts.push([t, Pof(t) / 1000]); }
      // I_пд = ∫ หลังคำสั่งดับสุดท้าย ; พาราโบลา → P·Δt/3
      let Ipd = P0 * lvl * s.dtp / 3;
      if (s.ptdu) Ipd *= 0.35;
      const dV = Ipd / m;
      const sd = dV * s.sig / 100;
      const resid = s.comp ? 3 * sd : dV + 3 * sd;

      const p = new Plot(ctx, 62, 8, w - 78, h - 74, 0, tEnd, 0, P0 / 1000 * 1.12);
      p.frame(ticks(0, tEnd, 5).map(v => +v.toFixed(1)), ticks(0, P0 / 1000 * 1.12, 4).map(Math.round), "t, с", "P, кН");
      // แรเงาอิมพัลส์หาง
      const t0 = t1 + tStep;
      const band = [];
      for (let i = 0; i <= 120; i++) { const t = t0 + s.dtp * i / 120; band.push([t, Pof(t) / 1000, 0]); }
      p.band(band, CV("--wash-2"));
      p.clip(() => p.line(pts, CV("--accent"), 2.4));
      ctx.save();
      ctx.strokeStyle = CV("--ink-3"); ctx.lineWidth = 1.2; ctx.setLineDash([4, 4]);
      ctx.beginPath(); ctx.moveTo(p.X(t1), p.y); ctx.lineTo(p.X(t1), p.y + p.h); ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = CV("--ink-3"); ctx.font = '10.5px "IBM Plex Mono", monospace';
      ctx.textAlign = "center"; ctx.textBaseline = "top";
      ctx.fillText("คำสั่งดับ", p.X(t1), p.y + 3);
      ctx.restore();
      // แถบผลลัพธ์ความเร็วส่วนเกิน
      const yb = h - 52, xb = 62, wb = w - 78;
      const scale = wb / Math.max(0.8, dV * 1.6);
      ctx.save();
      ctx.fillStyle = CV("--line"); ctx.fillRect(xb, yb, wb, 12);
      if (!s.comp) { ctx.fillStyle = CV("--ok"); ctx.fillRect(xb, yb, Math.min(wb, dV * scale), 12); }
      ctx.fillStyle = CV("--crit");
      const x0 = s.comp ? xb : xb + Math.min(wb, dV * scale);
      ctx.fillRect(x0, yb, Math.min(wb - (x0 - xb), 3 * sd * scale), 12);
      ctx.fillStyle = CV("--ink-3"); ctx.font = '10.5px "IBM Plex Mono", monospace';
      ctx.textAlign = "left"; ctx.textBaseline = "top";
      ctx.fillText("ค่าคลาดความเร็วปลายที่เหลือ = " + resid.toFixed(3) + " м/с", xb, yb + 16);
      ctx.restore();

      readout.innerHTML =
        'I<sub>пд</sub> = <b>' + (Ipd / 1000).toFixed(1) + ' кН·с</b>' +
        '<span>ΔV จากหางแรงขับ = <b>' + dV.toFixed(3) + ' м/с</b></span>' +
        '<span>σ = <b>' + sd.toFixed(3) + ' м/с</b></span>' +
        '<span>เหลือหลังมาตรการ = <b class="' + (resid < 0.8 ? "good" : "bad") + '">' + resid.toFixed(3) + ' м/с</b></span>' +
        '<span>' + (s.comp ? "ชดเชย ค่าคาดหมาย แล้ว — เหลือแต่ 3σ" : "ยังไม่ชดเชย — เหลือทั้งค่าเฉลี่ยและ 3σ") + '</span>';
    }
  });
}

/* ---- 10. วงในคุมมุม + วงนอกคุมจุดศูนย์กลางมวล (лек. 14 · 17) ---- */
function demoSurnLoop(host) {
  buildDemo(host, {
    label: "Лекции 14—17 · СУС + СС ЦМ",
    title: "สองวงซ้อน — วงในดับมุมเร็ว วงนอกดึงตำแหน่งกลับช้า ๆ",
    ratio: 0.62,
    legend: '<span><i style="background:var(--accent)"></i>Δϑ(t) — วงใน</span><span><i style="background:var(--accent-2)"></i>y(t) — วงนอก</span>' +
      '<span><i style="background:var(--line-2)"></i>ช่วงลมกระโชก</span>',
    buttons: [{ id: "outer", label: "เปิดวงนอก СС ЦМ", toggle: true, value: true }],
    controls: [
      { id: "Kq", label: "K<sub>ϑ</sub> — อัตราขยายตามมุม", min: 1.6, max: 8, step: 0.1, value: 3.0, fmt: v => v.toFixed(1) },
      { id: "Kqd", label: "K<sub>ϑ̇</sub> — อัตราขยายตามอัตราเชิงมุม", min: 0.2, max: 4, step: 0.05, value: 1.8, fmt: v => v.toFixed(2) + " с" },
      { id: "Ky", label: "K<sub>y</sub> — อัตราขยายตามตำแหน่ง", min: 0.0005, max: 0.02, step: 0.0005, value: 0.004, fmt: v => v.toFixed(4) },
      { id: "Kyd", label: "K<sub>ẏ</sub> — อัตราขยายตามความเร็วข้าง", min: 0.005, max: 0.4, step: 0.005, value: 0.12, fmt: v => v.toFixed(3) + " с" }
    ],
    draw(ctx, w, h, s, readout) {
      const aqq = -0.6, aqd = 0.4, ayAbs = 40, Trp = 0.1, KD = 1, KA = 1, DEG = 180 / Math.PI;
      /* --- วงใน: สมการ (60) + ชุดขับอันดับหนึ่ง — สเกลวินาที --- */
      const Ti = 24, dti = 0.002, Ni = Ti / dti;
      let q = 0, qd = 0, d = 0; const Q = []; let qmax = 0, blewI = false;
      for (let i = 0; i <= Ni; i++) {
        const t = i * dti;
        const fq = (t > 2 && t < 3) ? 0.2 : 0;
        const dcmd = s.Kq * q + s.Kqd * qd;
        d += (dcmd - d) / Trp * dti;
        const qdd = -aqd * d - aqq * q + fq;
        qd += qdd * dti; q += qd * dti;
        qmax = Math.max(qmax, Math.abs(q));
        if (!isFinite(q) || Math.abs(q) > 3) { blewI = true; break; }
        if (i % 25 === 0) Q.push([t, q * DEG]);
      }
      /* --- วงนอก: สมการ (81) ของบรรยายที่ 17 — สเกลสิบวินาที --- */
      const To = 140, dto = 0.01, No = To / dto;
      const Ky = s.outer ? s.Ky : 0, Kyd = s.outer ? s.Kyd : 0;
      let y = 0, yd = 0, ydd = 0; const Y = []; let blewO = false;
      for (let i = 0; i <= No; i++) {
        const t = i * dto;
        const F = (t > 20 && t < 26) ? 2.0 : 0;
        const yddd = (-KD * s.Kq * ydd - ayAbs * KA * Kyd * yd - ayAbs * KA * Ky * y + F) / (KD * s.Kqd);
        ydd += yddd * dto; yd += ydd * dto; y += yd * dto;
        if (!isFinite(y) || Math.abs(y) > 5e4) { blewO = true; break; }
        if (i % 20 === 0) Y.push([t, y]);
      }
      const gap = 30, hA = (h - 46) * 0.44, hB = (h - 46) - hA - gap;
      const qa = Math.max(0.5, Math.ceil(Math.max(...Q.map(v => Math.abs(v[1])), 0.5) * 1.25 * 10) / 10);
      const pA = new Plot(ctx, 62, 8, w - 78, hA, 0, Ti, -qa, qa);
      pA.frame(ticks(0, Ti, 6).map(Math.round), ticks(-qa, qa, 4).map(v => +v.toFixed(2)), "t, с (วงใน)", "Δϑ, °");
      pA.band([[2, qa, -qa], [3, qa, -qa]], CV("--line"));
      pA.line([[0, 0], [Ti, 0]], CV("--line-2"), 1, [3, 3]);
      pA.clip(() => pA.line(Q, blewI ? CV("--crit") : CV("--accent"), 2.2));
      const ya = Math.max(1, Math.ceil(Math.max(...Y.map(v => Math.abs(v[1])), 1) * 1.2));
      const pB = new Plot(ctx, 62, 8 + hA + gap, w - 78, hB, 0, To, -ya, ya);
      pB.frame(ticks(0, To, 7).map(Math.round), ticks(-ya, ya, 4).map(v => +v.toFixed(1)), "t, с (วงนอก)", "y, м");
      pB.band([[20, ya, -ya], [26, ya, -ya]], CV("--line"));
      pB.line([[0, 0], [To, 0]], CV("--line-2"), 1, [3, 3]);
      pB.clip(() => pB.line(Y, blewO ? CV("--crit") : CV("--accent-2"), 2.2));

      const Tq = s.Kqd / s.Kq, Ty = s.Kyd / Math.max(s.Ky, 1e-9);
      const hur = s.Kq * s.Kyd - s.Kqd * s.Ky;
      const yend = Y.length ? Y[Y.length - 1][1] : 0;
      readout.innerHTML =
        'Δϑ สูงสุด = <b>' + (blewI ? "ระบบแตก" : qmax * DEG < 0.01 ? "0" : (qmax * DEG).toFixed(2) + "°") + '</b>' +
        '<span>T<sub>ϑ</sub> = K<sub>ϑ̇</sub>/K<sub>ϑ</sub> = <b>' + Tq.toFixed(2) + ' с</b></span>' +
        '<span>T<sub>y</sub> = K<sub>ẏ</sub>/K<sub>y</sub> = <b>' + Ty.toFixed(0) + ' с</b> (ช้ากว่า ' + (Ty / Tq).toFixed(0) + ' เท่า)</span>' +
        '<span>K<sub>ϑ</sub>K<sub>ẏ</sub> − K<sub>ϑ̇</sub>K<sub>y</sub> = <b class="' + (hur > 0 ? "good" : "bad") + '">' + hur.toFixed(4) + '</b></span>' +
        '<span>y ที่ปลายช่วง = <b class="' + (!blewO && Math.abs(yend) < 3 ? "good" : "bad") + '">' + (blewO ? "ลู่ออก" : yend.toFixed(2) + " м") + '</b></span>' +
        (s.outer
          ? (hur > 0 ? '<span class="good">วงนอกช้ากว่าวงใน ⟹ ผ่านเงื่อนไข (83)</span>'
                     : '<span class="bad">วงนอกเร็วเกินวงใน ⟹ ผิดเงื่อนไข (83) — ตำแหน่งลู่ออก</span>')
          : '<span class="bad">ปิดวงนอกอยู่ — มุมกลับเข้าที่ได้ในไม่กี่วินาที แต่ตำแหน่งลอยออกไปเรื่อย ๆ</span>');
    }
  });
}

/* ---- 11. สัมประสิทธิ์แช่แข็งตามเวลาบิน (лек. 15 · 18) ---- */
function demoSurnFroz(host) {
  const T1 = 0.22, T2 = 0.16, tSep = 118, Tend = 175;
  const aqqOf = t => t < tSep ? -(0.05 + 0.95 * Math.exp(-Math.pow((t - 62) / 40, 2)))
                              : -(0.06 * Math.exp(-(t - tSep) / 45));
  const aqdOf = t => t < tSep ? 0.22 + 0.50 * Math.pow(t / tSep, 2)
                              : 0.34 + 0.75 * Math.pow((t - tSep) / (Tend - tSep), 2);
  buildDemo(host, {
    label: "Лекции 15 · 18 · «замороженные» коэффициенты",
    title: "สัมประสิทธิ์เปลี่ยนตลอดการบิน — เขตเสถียรภาพจึงขยายและจุดทำงานต้องลดลงตาม",
    ratio: 0.62,
    animate: true,
    legend: '<span><i style="background:var(--crit)"></i>|a<sub>ϑ</sub><sup>ϑ</sup>| — ความไม่เสถียรสถิต</span><span><i style="background:var(--accent)"></i>a<sub>ϑ</sub><sup>δ</sup> — ประสิทธิผลหาง</span>' +
      '<span><i style="background:var(--wash)"></i>เขตเสถียร ณ เวลาที่เลือก</span><span><i class="dot" style="background:var(--ink)"></i>Р.Т. ที่ปรับตามเวลา</span>',
    controls: [
      { id: "t", label: "เวลาบินหลัง «Контакт подъёма»", min: 5, max: 172, step: 1, value: 60, fmt: v => v + " с" },
      { id: "keep", label: "จุดทำงาน: 0 = ลดตามสูตร, 1 = ตรึงค่าตอน t = 5 с", min: 0, max: 1, step: 1, value: 0, fmt: v => v ? "ตรึงไว้" : "ลดตามสูตร" }
    ],
    draw(ctx, w, h, s, readout) {
      const t = s.t, aqq = aqqOf(t), aqd = aqdOf(t);
      const stable = (Kq, Kqd) => {
        const a0 = T2 * T2, a1 = T1, a2 = 1 + T2 * T2 * aqq,
              a3 = T1 * aqq + Kqd * aqd, a4 = Kq * aqd + aqq;
        if (a2 <= 0 || a3 <= 0 || a4 <= 0) return false;
        return a3 * (a1 * a2 - a0 * a3) - a4 * a1 * a1 > 0;
      };
      const gap = 30, hA = (h - 46) * 0.38, hB = (h - 46) - hA - gap;
      /* แผงบน: สัมประสิทธิ์ตามเวลา */
      const A = [], B = [];
      for (let i = 0; i <= 340; i++) { const tt = Tend * i / 340; A.push([tt, -aqqOf(tt)]); B.push([tt, aqdOf(tt)]); }
      const pA = new Plot(ctx, 58, 8, w - 74, hA, 0, Tend, 0, 1.3);
      pA.frame(ticks(0, Tend, 6).map(Math.round), ticks(0, 1.2, 3).map(v => +v.toFixed(1)), "", "с⁻²", true);
      pA.line([[tSep, 0], [tSep, 1.3]], CV("--line-2"), 1.2, [4, 4]);
      pA.clip(() => { pA.line(A, CV("--crit"), 2.1); pA.line(B, CV("--accent"), 2.1); });
      ctx.save();
      ctx.strokeStyle = CV("--ink"); ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.moveTo(pA.X(t), pA.y); ctx.lineTo(pA.X(t), pA.y + pA.h); ctx.stroke();
      ctx.fillStyle = CV("--ink-3"); ctx.font = '10px "IBM Plex Mono", monospace';
      ctx.textAlign = "center"; ctx.textBaseline = "top";
      ctx.fillText("t<sub>р</sub>".replace(/<[^>]+>/g, ""), pA.X(tSep), pA.y + 2);
      ctx.fillText("แยกท่อน", pA.X(tSep), pA.y + 14);
      ctx.restore();
      /* แผงล่าง: เขตเสถียรภาพ ณ เวลานั้น */
      const xmax = 5, ymax = 2.6;
      const pB = new Plot(ctx, 58, 8 + hA + gap, w - 74, hB, 0, xmax, 0, ymax);
      const nx = 150, ny = 90;
      ctx.save(); ctx.fillStyle = CV("--wash");
      for (let i = 0; i < nx; i++) for (let j = 0; j < ny; j++) {
        if (stable((i + .5) / nx * xmax, (j + .5) / ny * ymax)) {
          const x0 = pB.X(i / nx * xmax), x1 = pB.X((i + 1) / nx * xmax);
          const y0 = pB.Y((j + 1) / ny * ymax), y1 = pB.Y(j / ny * ymax);
          ctx.fillRect(x0, y0, x1 - x0 + .7, y1 - y0 + .7);
        }
      }
      ctx.restore();
      pB.frame(ticks(0, xmax, 5).map(v => +v.toFixed(1)), ticks(0, ymax, 4).map(v => +v.toFixed(1)), "K_ϑ", "K_ϑ̇");
      const Kmin = Math.max(0, -aqq / aqd);
      if (Kmin < xmax) pB.line([[Kmin, 0], [Kmin, ymax]], CV("--accent"), 2);
      pB.clip(() => pB.line([[0, 0], [xmax, T1 * xmax]], CV("--accent-2"), 2));
      const t0 = 5, K0 = 2.2 * Math.max(-aqqOf(t0) / aqdOf(t0), 0.3);
      const Kq = s.keep ? K0 : 2.2 * Math.max(Kmin, 0.12);
      const Kqd = 0.6 * Kq;
      const inside = stable(Kq, Kqd);
      ctx.save();
      ctx.strokeStyle = CV("--panel"); ctx.lineWidth = 2.5;
      ctx.fillStyle = inside ? CV("--ink") : CV("--crit");
      ctx.beginPath(); ctx.arc(pB.X(Math.min(Kq, xmax * .98)), pB.Y(Math.min(Kqd, ymax * .98)), 6, 0, 7);
      ctx.fill(); ctx.stroke(); ctx.restore();

      readout.innerHTML =
        't = <b>' + t + ' с</b>' +
        '<span>a<sub>ϑ</sub><sup>ϑ</sup> = <b>' + aqq.toFixed(3) + '</b> с⁻²</span>' +
        '<span>a<sub>ϑ</sub><sup>δ</sup> = <b>' + aqd.toFixed(3) + '</b> с⁻²</span>' +
        '<span>K<sub>ϑ</sub> ต่ำสุด = <b>' + Kmin.toFixed(2) + '</b></span>' +
        '<span>จุดทำงาน K<sub>ϑ</sub> = <b>' + Kq.toFixed(2) + '</b></span>' +
        '<span class="' + (inside ? "good" : "bad") + '">' + (inside ? "อยู่ในเขต" : "หลุดเขต — ต้องปรับสัมประสิทธิ์") + '</span>' +
        (s.keep ? '<span class="bad">ตรึงค่าไว้ตั้งแต่ต้น — พอ |a<sub>ϑ</sub><sup>ϑ</sup>| ลด อัตราขยายที่ค้างสูงจะไปปลุกการงอลำตัวและสัญญาณรบกวน</span>'
                : '<span>ลดตามสูตร — ตรงกับคำตอบสอบ «коэффициенты пропорционально уменьшаются»</span>');
    }
  });
}

/* ---- 12. ลักษณะเชิงสถิตและเชิงพลวัตของ АС (лек. 21) ---- */
function demoSurnStat(host) {
  buildDemo(host, {
    label: "Лекция 21 · характеристики АС",
    title: "กราฟเดียวที่ต้องวาดในห้องสอบ — ลักษณะสถิต และ АЧХ/ФЧХ สามจุด",
    ratio: 0.6,
    legend: '<span><i style="background:var(--accent)"></i>δ<sub>т</sub>(Δϑ) และ АЧХ</span><span><i style="background:var(--accent-2)"></i>ФЧХ</span>' +
      '<span><i style="background:var(--crit)"></i>ย่านอิ่มตัว</span><span><i style="background:var(--line-2)"></i>ความถี่ I ทอน / II ทอน</span>',
    controls: [
      { id: "KE", label: "K<sub>Э</sub> = k<sub>д</sub>·k<sub>ϑ</sub>·k<sub>рп</sub>", min: 4, max: 40, step: 1, value: 15, fmt: v => v.toFixed(0) },
      { id: "dmax", label: "δ<sub>т max</sub> — พิกัดกลของหาง", min: 10, max: 45, step: 1, value: 30, fmt: v => v + "°" },
      { id: "w1", label: "ω<sub>I тон</sub> — ความถี่งอลำตัวทอนแรก", min: 4, max: 20, step: 0.5, value: 9, fmt: v => v.toFixed(1) + " рад/с" },
      { id: "Tf", label: "T<sub>ф</sub> — ตัวกรองความถี่ต่ำ (สามขั้ว)", min: 0.02, max: 0.5, step: 0.005, value: 0.19, fmt: v => v.toFixed(3) + " с" }
    ],
    draw(ctx, w, h, s, readout) {
      const gap = 32, hA = (h - 46) * 0.42, hB = (h - 46) - hA - gap;
      const dq = s.dmax / s.KE;                    // มุมที่เริ่มอิ่มตัว
      /* --- แผงบน: ลักษณะสถิต --- */
      const xm = Math.max(3, dq * 2.2);
      const st = [];
      for (let i = -240; i <= 240; i++) {
        const x = xm * i / 240;
        st.push([x, Math.max(-s.dmax, Math.min(s.dmax, s.KE * x))]);
      }
      const pA = new Plot(ctx, 58, 8, w - 74, hA, -xm, xm, -s.dmax * 1.25, s.dmax * 1.25);
      pA.frame(ticks(-xm, xm, 4).map(v => +v.toFixed(1)), ticks(-s.dmax, s.dmax, 2).map(Math.round), "Δϑ, °", "δ_т, °");
      pA.line([[-xm, 0], [xm, 0]], CV("--line-2"), 1, [3, 3]);
      pA.line([[dq, -s.dmax * 1.25], [dq, s.dmax * 1.25]], CV("--crit"), 1.2, [4, 4]);
      pA.line([[-dq, -s.dmax * 1.25], [-dq, s.dmax * 1.25]], CV("--crit"), 1.2, [4, 4]);
      pA.clip(() => pA.line(st, CV("--accent"), 2.4));
      /* --- แผงล่าง: АЧХ + ФЧХ ในสเกลลอการิทึม --- */
      /* แบบจำลองของ АС: W(p) = K_Э / (T_ф·p + 1)³ — สามขั้ว จึงหมุนเฟสได้ถึง −270° */
      const w2 = s.w1 * 2.6;                        // II ทอนอยู่สูงกว่าราว 2,6 เท่า
      const magOf = om => s.KE / Math.pow(1 + Math.pow(om * s.Tf, 2), 1.5);
      const phOf = om => -3 * Math.atan(om * s.Tf) * 180 / Math.PI;
      const lo = -1.4, hi = Math.log10(w2 * 4);
      const AM = [], PH = [];
      for (let i = 0; i <= 320; i++) {
        const lw = lo + (hi - lo) * i / 320, om = Math.pow(10, lw);
        AM.push([lw, 20 * Math.log10(magOf(om))]);
        PH.push([lw, phOf(om)]);
      }
      const amin = Math.min(-60, Math.floor(AM[AM.length - 1][1] / 20) * 20);
      const pB = new Plot(ctx, 58, 8 + hA + gap, w - 74, hB, lo, hi, amin, 40);
      pB.frame([lo, Math.log10(s.w1), Math.log10(w2), hi].map(v => +v.toFixed(2)),
               ticks(amin, 40, 5).map(Math.round), "lg ω", "L, дБ  /  φ (สเกลขวา)");
      pB.line([[lo, 0], [hi, 0]], CV("--line-2"), 1, [3, 3]);
      [[s.w1, "I тон"], [w2, "II тон"]].forEach(([om, nm]) => {
        pB.line([[Math.log10(om), amin], [Math.log10(om), 40]], CV("--line-2"), 1.4, [5, 4]);
        ctx.save(); ctx.fillStyle = CV("--ink-3"); ctx.font = '10px "IBM Plex Mono", monospace';
        ctx.textAlign = "center"; ctx.textBaseline = "top";
        ctx.fillText(nm, pB.X(Math.log10(om)), pB.y + 3); ctx.restore();
      });
      /* เส้น −180° บนสเกลเฟส (แปลง −270…0° ให้พาดในกรอบเดียวกัน) */
      const pmap = ph => amin + (ph + 270) / 270 * (40 - amin);
      pB.line([[lo, pmap(-180)], [hi, pmap(-180)]], CV("--crit"), 1.2, [4, 4]);
      ctx.save(); ctx.fillStyle = CV("--crit"); ctx.font = '10px "IBM Plex Mono", monospace';
      ctx.textAlign = "left"; ctx.textBaseline = "bottom";
      ctx.fillText("φ = −180°", pB.X(lo) + 5, pB.Y(pmap(-180)) - 2); ctx.restore();
      pB.clip(() => { pB.line(AM, CV("--accent"), 2.2); pB.line(PH.map(v => [v[0], pmap(v[1])]), CV("--accent-2"), 2.2); });

      const L1 = 20 * Math.log10(magOf(s.w1)), P1 = phOf(s.w1);
      const L2 = 20 * Math.log10(magOf(w2));
      const Lsus = 20 * Math.log10(magOf(1));
      readout.innerHTML =
        'K<sub>Э</sub> = <b>' + s.KE.toFixed(0) + '</b>' +
        '<span>อิ่มตัวเมื่อ |Δϑ| &gt; <b>' + dq.toFixed(2) + '°</b></span>' +
        '<span>ย่าน СУС (ω ≈ 1): L = <b class="' + (Lsus > 12 ? "good" : "bad") + '">' + Lsus.toFixed(1) + ' дБ</b></span>' +
        '<span>I ทอน: φ = <b class="' + (Math.abs(P1 + 180) < 25 ? "good" : "bad") + '">' + P1.toFixed(0) + '°</b> (ต้องใกล้ −180° — фазовая)</span>' +
        '<span>II ทอน: L = <b class="' + (L2 < 0 ? "good" : "bad") + '">' + L2.toFixed(1) + ' дБ</b> (ต้องต่ำกว่า 0 — амплитудная)</span>' +
        '<span>สามเงื่อนไขบนกราฟเดียว: อัตราขยายพอที่ย่าน СУС · เฟส −180° ที่ I ทอน · กดแอมพลิจูดที่ II ทอน</span>';
    }
  });
}

/* ---- 13. อวัยวะควบคุมของจรวดจริงแต่ละแบบ (лек. 22) ---- */
function demoSurnOrg(host) {
  const RK = [
    { n: "14А14 «Союз-2»", st: ["I ступень", "II ступень", "III ступень"], nc: 4,
      note: ["4 รูเลวืยคาเมรา + аэродинамические рули", "4 รูเลวืยคาเมรา", "«2.1а» รูเลวืยคาเมรา · «2.1б» คาเมราของ МД"],
      aero: [true, false, false] },
    { n: "«Ангара»", st: ["I ступень", "II ступень"], nc: 1,
      note: ["คาเมราของ МД ตัวเดียว + аэродинамические рули + сопло крена แยกต่างหาก", "4 คาเมราของ МД"],
      aero: [true, false], soplo: [true, false], nc2: [1, 4] },
    { n: "8К82КМ «Протон-М»", st: ["I ступень", "II ступень", "III ступень"], nc: 6,
      note: ["เบนคาเมราของ 6 маршевых двигателей", "4 คาเมรา (จาก 4 МД)", "4 คาเมราของ рулевой двигатель"],
      aero: [false, false, false], nc2: [6, 4, 4] },
    { n: "11К65М «Космос-3М»", st: ["I ступень", "II ступень"], nc: 4,
      note: ["4 газовых руля", "4 сопла"], aero: [false, false] },
    { n: "11К77 «Зенит»", st: ["I ступень", "II ступень"], nc: 4,
      note: ["ทั้ง 4 คาเมราของ маршевый двигатель ทำงานทุกช่อง", "ทั้ง 4 คาเมราของ рулевой двигатель ทำงานทุกช่อง"],
      aero: [false, false], all: true }
  ];
  const CH = ["Т — тангаж (2 และ 4)", "Р — рыскание (1 และ 3)", "В — вращение (ทั้ง 4)"];
  buildDemo(host, {
    label: "Лекция 22 · управляющие органы",
    title: "ตารางหัวฉีดของจรวดจริง — กดเลือกแล้วดูว่าตัวไหนเบน",
    ratio: 0.46,
    controls: [
      { id: "r", label: "จรวด", min: 0, max: 4, step: 1, value: 0, fmt: v => RK[v].n },
      { id: "st", label: "ขั้นของจรวด", min: 0, max: 2, step: 1, value: 0, fmt: v => "ขั้นที่ " + (v + 1) },
      { id: "ch", label: "ช่องควบคุม", min: 0, max: 2, step: 1, value: 0, fmt: v => CH[v] }
    ],
    draw(ctx, w, h, s, readout) {
      const rk = RK[s.r], st = Math.min(s.st, rk.st.length - 1);
      const n = rk.nc2 ? rk.nc2[st] : rk.nc;
      const all = !!rk.all || n === 6;
      const cx = w * 0.30, cy = h / 2 + 4, R = Math.min(w * 0.20, h * 0.34);
      /* วงลำตัว */
      ctx.save();
      ctx.strokeStyle = CV("--line-2"); ctx.lineWidth = 1.6; ctx.fillStyle = CV("--panel-2");
      ctx.beginPath(); ctx.arc(cx, cy, R, 0, 7); ctx.fill(); ctx.stroke();
      ctx.setLineDash([4, 4]); ctx.strokeStyle = CV("--line");
      ctx.beginPath(); ctx.moveTo(cx - R, cy); ctx.lineTo(cx + R, cy);
      ctx.moveTo(cx, cy - R); ctx.lineTo(cx, cy + R); ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
      /* หัวฉีด */
      const act = [];
      for (let i = 0; i < n; i++) {
        const a = -i * 2 * Math.PI / n;   // 1 = ขวา · 2 = บน · 3 = ซ้าย · 4 = ล่าง
        const x = cx + Math.cos(a) * R * 0.72, y = cy + Math.sin(a) * R * 0.72;
        // เลข 1..4 เริ่มที่แกนขวาแล้วทวนเข็ม สำหรับกรณี 4 หัวฉีด
        const idx = i + 1;
        let on = all;
        if (!all && n === 4) {
          if (s.ch === 0) on = (idx === 2 || idx === 4);      // บน-ล่าง = ช่อง Т
          else if (s.ch === 1) on = (idx === 1 || idx === 3); // ซ้าย-ขวา = ช่อง Р
          else on = true;
        } else if (n === 1) on = (s.ch !== 2);
        ctx.save();
        ctx.beginPath(); ctx.arc(x, y, R * 0.20, 0, 7);
        ctx.fillStyle = on ? CV("--wash") : CV("--panel");
        ctx.strokeStyle = on ? CV("--accent") : CV("--line-2");
        ctx.lineWidth = on ? 2.2 : 1.2; ctx.fill(); ctx.stroke();
        ctx.fillStyle = on ? CV("--accent") : CV("--ink-3");
        ctx.font = '600 11px "IBM Plex Mono", monospace';
        ctx.textAlign = "center"; ctx.textBaseline = "middle";
        ctx.fillText(String(idx), x, y);
        if (on) {
          act.push(idx);
          // ลูกศรทิศการเบน
          let ax, ay;
          if (s.ch === 2) { ax = -Math.sin(a); ay = Math.cos(a); }        // แทนเจนต์ = ม้วน
          else if (s.ch === 0) { ax = 0; ay = 1; }                        // แรงข้างแนวดิ่ง = โมเมนต์ Pitch
          else { ax = 1; ay = 0; }                                        // แรงข้างแนวนอน = โมเมนต์ส่าย
          ctx.strokeStyle = CV("--accent-2"); ctx.lineWidth = 2.2; ctx.lineCap = "round";
          const L = R * 0.30;
          ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x + ax * L, y + ay * L); ctx.stroke();
          ctx.beginPath();
          ctx.moveTo(x + ax * L, y + ay * L);
          ctx.lineTo(x + ax * L - ax * 6 + ay * 4, y + ay * L - ay * 6 - ax * 4);
          ctx.lineTo(x + ax * L - ax * 6 - ay * 4, y + ay * L - ay * 6 + ax * 4);
          ctx.closePath(); ctx.fillStyle = CV("--accent-2"); ctx.fill();
        }
        ctx.restore();
      }
      if (rk.soplo && rk.soplo[st] && s.ch === 2) {
        const x = cx + R * 1.02, y = cy - R * 0.86;
        ctx.save();
        ctx.fillStyle = CV("--wash-2"); ctx.strokeStyle = CV("--accent-2"); ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(x, y, R * 0.15, 0, 7); ctx.fill(); ctx.stroke();
        ctx.fillStyle = CV("--accent-2"); ctx.font = '10px "IBM Plex Mono", monospace';
        ctx.textAlign = "left"; ctx.textBaseline = "middle";
        ctx.fillText("сопло крена", x + R * 0.22, y);
        ctx.restore();
      }
      /* ข้อความด้านขวา */
      const tx = w * 0.55;
      ctx.save();
      ctx.textAlign = "left"; ctx.textBaseline = "top";
      ctx.fillStyle = CV("--ink"); ctx.font = '600 14px "IBM Plex Sans Thai", sans-serif';
      ctx.fillText(rk.n, tx, 14);
      ctx.fillStyle = CV("--accent"); ctx.font = '600 12px "IBM Plex Mono", monospace';
      ctx.fillText(rk.st[st], tx, 38);
      ctx.fillStyle = CV("--ink-2"); ctx.font = '12.5px "IBM Plex Sans Thai", sans-serif';
      const words = rk.note[st].split(" ");
      let line = "", yy = 60;
      words.forEach(wd => {
        if (ctx.measureText(line + wd).width > w - tx - 16) { ctx.fillText(line, tx, yy); yy += 18; line = ""; }
        line += wd + " ";
      });
      ctx.fillText(line, tx, yy);
      ctx.fillStyle = CV("--accent-2"); ctx.font = '600 12px "IBM Plex Mono", monospace';
      ctx.fillText("ทำงาน: " + (act.length ? act.join(", ") : "—") + (rk.soplo && rk.soplo[st] && s.ch === 2 ? " + сопло крена" : ""), tx, yy + 26);
      ctx.restore();

      readout.innerHTML =
        '<span>กฎที่ใช้ได้เกือบทุกจรวด: <b>Т → 2 และ 4 · Р → 1 และ 3 · В → ทั้งสี่</b></span>' +
        '<span class="' + (s.r === 1 ? "bad" : "") + '">ข้อยกเว้น 1: «Ангара» ขั้นแรกมี МД ตัวเดียว จึงต้องมี <b>сопло крена</b> แยกสำหรับช่อง В</span>' +
        '<span class="' + (s.r === 4 ? "bad" : "") + '">ข้อยกเว้น 2: <b>11К77 «Зенит»</b> ใช้ทั้งสี่คาเมรากับทั้งสามช่อง</span>';
    }
  });
}

/* ---- 14. ไทม์ไลน์ циклограмма และข้อจำกัด 8 ข้อ (лек. 7) ---- */
function demoSurnCyc(host) {
  const EV = [
    [0, "КП — контакт подъёма"], [8, "เริ่ม управляемый разворот"], [42, "ผ่าน M = 1"],
    [62, "q สูงสุด — บังคับ α = 0"], [112, "หยุดหมุน ϑ = const ก่อนแยกท่อน"],
    [118, "разделение ступеней"], [150, "сброс головного обтекателя"], [175, "выключение ДУ"]
  ];
  const LIM = [
    [0, 8, "1 · ยิงขึ้นแนวดิ่งและช่วงต้นต้องดิ่ง"],
    [8, 42, "2 · จำกัดมุมปะทะสูงสุดช่วง управляемый разворот"],
    [36, 78, "3 · α = 0 ในย่านความเร็วเสียงและเหนือเสียง"],
    [0, 175, "4 · ฟังก์ชันต้องต่อเนื่องและมีขอบเขต"],
    [0, 175, "5 · โปรแกรมต้องเหมาะที่สุด (น้ำหนักบรรทุกสูงสุด)"],
    [112, 124, "6 · ชิ้นส่วนที่ทิ้งต้องตกในเขตที่กำหนด"],
    [112, 124, "7 · ϑ = const ตอนแยกท่อน / ทิ้งครอบ"],
    [40, 90, "8 · จำกัดโหลดแฟกเตอร์ q และอุณหภูมิผิว"]
  ];
  buildDemo(host, {
    label: "Лекция 7 · программа тангажа",
    title: "ไทม์ไลน์การบินกับข้อจำกัดแปดข้อ — ข้อไหนบังคับอยู่ตอนไหน",
    ratio: 0.58,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>ϑ<sub>п</sub>(t) สี่ช่วงตามสูตร (24)</span><span><i style="background:var(--accent-2)"></i>q(t) — แรงดันพลศาสตร์</span><span><i class="dot" style="background:var(--ink)"></i>เวลาปัจจุบัน</span>',
    controls: [
      { id: "t", label: "เวลาหลัง «Контакт подъёма»", min: 0, max: 175, step: 1, value: 62, fmt: v => v + " с" },
      { id: "run", label: "0 = หยุดที่เวลาที่ตั้ง, 1 = เดินอัตโนมัติ", min: 0, max: 1, step: 1, value: 1, fmt: v => v ? "เดินอัตโนมัติ" : "หยุดนิ่ง" }
    ],
    draw(ctx, w, h, s, readout, tAnim) {
      const t = s.run ? (tAnim * 14) % 176 : s.t;
      const thOf = tt => {
        if (tt < 8) return 90;
        if (tt < 62) return 90 - 62 * Math.pow((tt - 8) / 54, 1.35);
        if (tt < 112) return 28 - 12 * (tt - 62) / 50;
        if (tt < 124) return 16;
        return 16 - 9 * (tt - 124) / 51;
      };
      const qOf = tt => 34 * Math.exp(-Math.pow((tt - 62) / 26, 2));
      const P = [], Q = [];
      for (let i = 0; i <= 350; i++) { const tt = 175 * i / 350; P.push([tt, thOf(tt)]); Q.push([tt, qOf(tt)]); }
      const hA = h - 96;
      const p = new Plot(ctx, 56, 8, w - 72, hA, 0, 175, 0, 95);
      p.frame(ticks(0, 175, 7).map(Math.round), ticks(0, 90, 3).map(Math.round), "t, с", "ϑ, ° · q, кПа");
      p.clip(() => { p.line(Q, CV("--accent-2"), 1.8); p.line(P, CV("--accent"), 2.4); });
      EV.forEach(([te, nm]) => {
        p.line([[te, 0], [te, 95]], CV("--line"), 1, [3, 3]);
      });
      ctx.save();
      ctx.strokeStyle = CV("--ink"); ctx.lineWidth = 1.8;
      ctx.beginPath(); ctx.moveTo(p.X(t), p.y); ctx.lineTo(p.X(t), p.y + p.h); ctx.stroke();
      ctx.fillStyle = CV("--ink");
      ctx.beginPath(); ctx.arc(p.X(t), p.Y(thOf(t)), 5, 0, 7); ctx.fill();
      ctx.restore();
      /* แถบข้อจำกัด */
      const yb = hA + 26, bh = 8, gapb = 2;
      ctx.save();
      ctx.font = '9.5px "IBM Plex Mono", monospace'; ctx.textBaseline = "middle";
      LIM.forEach(([a, b, nm], i) => {
        const yy = yb + i * (bh + gapb);
        const on = t >= a && t <= b;
        ctx.fillStyle = CV("--line");
        ctx.fillRect(p.X(0), yy, p.X(175) - p.X(0), bh);
        ctx.fillStyle = on ? CV("--accent") : CV("--line-2");
        ctx.fillRect(p.X(a), yy, p.X(b) - p.X(a), bh);
        ctx.fillStyle = on ? CV("--accent") : CV("--ink-3");
        ctx.textAlign = "right";
        ctx.fillText(String(i + 1), p.X(0) - 8, yy + bh / 2);
      });
      ctx.restore();

      const active = LIM.filter(([a, b]) => t >= a && t <= b).map(([, , nm]) => nm);
      const ev = EV.filter(([te]) => te <= t).pop();
      readout.innerHTML =
        't = <b>' + t.toFixed(0) + ' с</b>' +
        '<span>ϑ<sub>п</sub> = <b>' + thOf(t).toFixed(1) + '°</b></span>' +
        '<span>q = <b>' + qOf(t).toFixed(1) + ' кПа</b></span>' +
        '<span>เหตุการณ์ล่าสุด: <b>' + (ev ? ev[1] : "—") + '</b></span>' +
        '<span>ข้อจำกัดที่บังคับอยู่: <b>' + active.map(x => x.split(" ·")[0]).join(", ") + '</b></span>' +
        '<span>' + active.slice(0, 2).join(" · ") + '</span>';
    }
  });
}

/* ---- 15. โหมดการงอตัว I/II ทอน กับตำแหน่ง ККП (лек. 20) ---- */
function demoSurnMode(host) {
  const B = [4.7300408, 7.8532046], SG = [0.9825022, 1.0007773];
  const phi = (x, k) => {
    const b = B[k] * x, s = SG[k];
    return Math.cosh(b) + Math.cos(b) - s * (Math.sinh(b) + Math.sin(b));
  };
  const dphi = (x, k) => {
    const b = B[k] * x, s = SG[k], B0 = B[k];
    return B0 * (Math.sinh(b) - Math.sin(b) - s * (Math.cosh(b) + Math.cos(b)));
  };
  buildDemo(host, {
    label: "Лекция 20 · упругие колебания корпуса",
    title: "โหมดการงอลำตัวและตำแหน่ง ККП — เครื่องหมายของ a<sub>Δϑy</sub><sup>δ</sup> มาจากตรงนี้",
    ratio: 0.34,
    animate: true,
    legend: '<span><i style="background:var(--accent)"></i>รูปร่างโหมด</span><span><i style="background:var(--line-2)"></i>แกนลำตัวตอนไม่งอ</span>' +
      '<span><i class="dot" style="background:var(--crit)"></i>โหนดการสั่น (узел)</span><span><i class="dot" style="background:var(--accent-2)"></i>ตำแหน่ง ККП</span>',
    controls: [
      { id: "xs", label: "ตำแหน่ง ККП ตามลำตัว (0 = หัว, 1 = ท้าย)", min: 0, max: 1, step: 0.01, value: 0.08, fmt: v => v < 0.22 ? v.toFixed(2) + " · т. I หัวจรวด" : v > 0.78 ? v.toFixed(2) + " · т. II ท้ายจรวด" : v.toFixed(2) },
      { id: "k", label: "ทอนการสั่น", min: 0, max: 1, step: 1, value: 0, fmt: v => v ? "II тон" : "I тон" },
      { id: "Kqd", label: "K<sub>ϑ̇</sub> ของกฎควบคุม", min: 0, max: 3, step: 0.05, value: 1.2, fmt: v => v.toFixed(2) }
    ],
    draw(ctx, w, h, s, readout, tAnim) {
      const k = s.k, amp = 34 * Math.sin(tAnim * 3.4);
      const x0 = 60, x1 = w - 24, cy = (h - 40) / 2 + 8;
      /* หา normalisation */
      let mx = 0;
      for (let i = 0; i <= 200; i++) mx = Math.max(mx, Math.abs(phi(i / 200, k)));
      const yOf = x => cy - amp * phi(x, k) / mx;
      /* แกนอ้างอิง */
      ctx.save();
      ctx.strokeStyle = CV("--line-2"); ctx.lineWidth = 1.2; ctx.setLineDash([5, 4]);
      ctx.beginPath(); ctx.moveTo(x0, cy); ctx.lineTo(x1, cy); ctx.stroke(); ctx.setLineDash([]);
      ctx.restore();
      /* ลำตัวที่งอ */
      ctx.save();
      ctx.strokeStyle = CV("--accent"); ctx.lineWidth = 3.2; ctx.lineCap = "round"; ctx.lineJoin = "round";
      ctx.beginPath();
      for (let i = 0; i <= 240; i++) {
        const x = i / 240, px = x0 + (x1 - x0) * x, py = yOf(x);
        i ? ctx.lineTo(px, py) : ctx.moveTo(px, py);
      }
      ctx.stroke();
      ctx.restore();
      /* โหนด */
      const nodes = [];
      for (let i = 1; i <= 400; i++) {
        const a = (i - 1) / 400, b = i / 400;
        if (phi(a, k) * phi(b, k) < 0) nodes.push((a + b) / 2);
      }
      ctx.save(); ctx.fillStyle = CV("--crit");
      nodes.forEach(nx => {
        ctx.beginPath(); ctx.arc(x0 + (x1 - x0) * nx, cy, 4.6, 0, 7); ctx.fill();
        ctx.font = '10px "IBM Plex Mono", monospace'; ctx.textAlign = "center"; ctx.textBaseline = "top";
        ctx.fillText(nx.toFixed(3), x0 + (x1 - x0) * nx, cy + 9);
      });
      ctx.restore();
      /* ККП */
      const sx = x0 + (x1 - x0) * s.xs, sy = yOf(s.xs);
      ctx.save();
      ctx.fillStyle = CV("--accent-2"); ctx.strokeStyle = CV("--panel"); ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(sx, sy, 6.4, 0, 7); ctx.fill(); ctx.stroke();
      ctx.fillStyle = CV("--accent-2"); ctx.font = '600 10.5px "IBM Plex Mono", monospace';
      ctx.textAlign = "center"; ctx.textBaseline = "bottom";
      ctx.fillText("ККП", sx, sy - 11);
      ctx.restore();
      /* ป้ายหัว-ท้าย */
      ctx.save();
      ctx.fillStyle = CV("--ink-3"); ctx.font = '10.5px "IBM Plex Sans Thai", sans-serif';
      ctx.textAlign = "left"; ctx.textBaseline = "top"; ctx.fillText("หัวจรวด (т. I)", x0, h - 26);
      ctx.textAlign = "right"; ctx.fillText("ท้ายจรวด · หัวฉีด (т. II)", x1, h - 26);
      ctx.restore();

      const gs = dphi(s.xs, k), gt = dphi(1, k);
      const sgn = gs * gt;                       // > 0 ⟹ a^δ > 0 (ช่วยหน่วง)
      const aDelta = sgn > 0 ? 0.45 : -0.45;
      const aDamp = 0.30;                        // การหน่วงตามธรรมชาติของโครงสร้าง
      const a1 = aDamp + aDelta * s.Kqd;
      readout.innerHTML =
        (k ? "II тон" : "I тон") + ' · โหนดที่ x/L = <b>' + nodes.map(v => v.toFixed(3)).join(", ") + '</b>' +
        '<span>ความชันที่ ККП × ความชันที่ท้าย = <b class="' + (sgn > 0 ? "good" : "bad") + '">' + (sgn > 0 ? "บวก" : "ลบ") + '</b></span>' +
        '<span>a<sub>Δϑy</sub><sup>δ</sup> <b class="' + (aDelta > 0 ? "good" : "bad") + '">' + (aDelta > 0 ? "> 0" : "< 0") + '</b></span>' +
        '<span>พจน์หน่วงของ D(p): a<sup>Δϑ̇</sup> + a<sup>δ</sup>K<sub>ϑ̇</sub> = <b class="' + (a1 > 0 ? "good" : "bad") + '">' + a1.toFixed(2) + '</b></span>' +
        '<span class="' + (a1 > 0 ? "good" : "bad") + '">' + (a1 > 0
          ? "เพิ่มการหน่วง — วางเซนเซอร์ถูกที่แล้ว"
          : "ลบการหน่วงตามธรรมชาติออก ⟹ ระบบขับตัวเองให้แกว่ง (นี่คือกรณี «Протон-М» 2013 ที่ БДУС ถูกติดกลับด้าน)") + '</span>';
    }
  });
}

/* ---- 16. ถังบนกับถังล่างวางเทียบกัน และผลของแผ่นกั้น (лек. 19) ---- */
function demoSurnTank(host) {
  buildDemo(host, {
    label: "Лекция 19 · способы демпфирования КЖ",
    title: "ถังบน vs ถังล่าง รันพร้อมกัน — และแผ่นกั้นช่วยได้แค่ไหน",
    ratio: 0.5,
    legend: '<span><i style="background:var(--crit)"></i>ถังบน x<sub>кж</sub> &gt; 0</span><span><i style="background:var(--ok)"></i>ถังล่าง x<sub>кж</sub> &lt; 0</span>' +
      '<span>เส้นคือแอมพลิจูดคลื่น β(t) ของทั้งสองกรณีที่พารามิเตอร์อื่นเท่ากันทุกอย่าง</span>',
    controls: [
      { id: "x", label: "|x<sub>кж</sub>| — ระยะถังจาก ц.м.", min: 0.2, max: 1, step: 0.02, value: 0.6, fmt: v => "±" + v.toFixed(2) },
      { id: "zb", label: "การหน่วง a<sub>β</sub><sup>β̇</sup> — เพิ่มด้วยแผ่นกั้น (диафрагмы)", min: 0.004, max: 0.12, step: 0.002, value: 0.012, fmt: v => v.toFixed(3) + (v > 0.05 ? " · ใส่แผ่นกั้นแล้ว" : " · ถังเปล่า") },
      { id: "mu", label: "สัดส่วนมวลของเหลวที่แกว่ง", min: 0.04, max: 0.34, step: 0.01, value: 0.18, fmt: v => (v * 100).toFixed(0) + " %" }
    ],
    draw(ctx, w, h, s, readout) {
      const wb = 2.6, dt = 0.002, tmax = 40, N = Math.round(tmax / dt);
      const Kq = 2.2, Kqd = 0.85, aqd = 0.55, aqq = -0.3, ayq = -55, K4 = 0.35;
      const run = X => {
        const aqB = -0.9 * s.mu * X, ayB = -0.9 * s.mu, abY = -K4, abQ = -K4 * X;
        let q = 0.03, qd = 0, b = 0, bd = 0, qdd = 0, bdd = 0;
        const bs = []; let div = false, a0 = 0, aN = 0;
        for (let i = 0; i <= N; i++) {
          const t = i * dt;
          const u = Kq * q + Kqd * qd;
          const ydd = -ayq * q - ayB * bdd;
          const b2 = -2 * s.zb * wb * bd - wb * wb * b - abY * ydd - abQ * qdd;
          const q2 = -aqd * u - aqq * q - aqB * b2;
          bdd = b2; qdd = q2;
          bd += bdd * dt; b += bd * dt; qd += qdd * dt; q += qd * dt;
          if (!isFinite(b) || Math.abs(b) > 5) { div = true; break; }
          if (t > 4 && t < 10) a0 = Math.max(a0, Math.abs(b));
          if (t > tmax - 8) aN = Math.max(aN, Math.abs(b));
          if (i % 40 === 0) bs.push([t, b]);
        }
        return { bs, div, a0, aN, grow: div || aN > a0 * 1.02 };
      };
      const up = run(+s.x), dn = run(-s.x);
      const ymax = Math.max(0.05, Math.max(
        ...up.bs.map(v => Math.abs(v[1])), ...dn.bs.map(v => Math.abs(v[1]))) * 1.15);
      const p = new Plot(ctx, 62, 10, w - 78, h - 48, 0, tmax, -ymax, ymax);
      p.frame(ticks(0, tmax, 5).map(Math.round), ticks(-ymax, ymax, 4).map(v => +v.toFixed(2)), "t, с", "β");
      p.line([[0, 0], [tmax, 0]], CV("--line-2"), 1, [3, 3]);
      p.clip(() => { p.line(dn.bs, CV("--ok"), 2); p.line(up.bs, CV("--crit"), 2.2); });

      readout.innerHTML =
        'ถังบน: <b class="' + (up.grow ? "bad" : "good") + '">' + (up.div ? "ลู่ออก" : up.grow ? "โตขึ้น" : "ลู่เข้า") + '</b>' +
        '<span>ถังล่าง: <b class="' + (dn.grow ? "bad" : "good") + '">' + (dn.div ? "ลู่ออก" : dn.grow ? "โตขึ้น" : "ลู่เข้า") + '</b></span>' +
        '<span>แอมพลิจูดท้ายช่วง ถังบน/ถังล่าง = <b>' + (up.div ? "∞" : up.aN.toFixed(3)) + ' / ' + (dn.div ? "∞" : dn.aN.toFixed(3)) + '</b></span>' +
        '<span>' + (s.zb > 0.05
          ? "เพิ่มการหน่วงด้วยแผ่นกั้นแล้ว — ถังบนสงบลงได้ แลกกับมวลโครงสร้างที่เพิ่ม"
          : "ยังไม่ใส่แผ่นกั้น — фазовая стабилизация ช่วยได้เฉพาะถังล่าง จึงต้องใช้วิธีโครงสร้างกับถังบน") + '</span>';
    }
  });
}

