/* ================= APP ================= */
const KEY = "atlas-sula-v1";
let DONE = new Set();
try { const r = localStorage.getItem(KEY); if (r) DONE = new Set(JSON.parse(r)); } catch (e) {}
const persist = () => { try { localStorage.setItem(KEY, JSON.stringify([...DONE])); } catch (e) {} };

/* v2: บุ๊กมาร์ก + ตำแหน่งอ่านล่าสุด + สี/ไอคอนประจำวิชา */
const BMKEY = "atlas-bm-v1";
let BM = new Set();
try { const r = localStorage.getItem(BMKEY); if (r) BM = new Set(JSON.parse(r)); } catch (e) {}
const persistBM = () => { try { localStorage.setItem(BMKEY, JSON.stringify([...BM])); } catch (e) {} };
const LASTKEY = "atlas-last-v1";
let LAST = null;
try { const r = localStorage.getItem(LASTKEY); if (r) LAST = JSON.parse(r); } catch (e) {}
const saveLast = () => { try { localStorage.setItem(LASTKEY, JSON.stringify(LAST)); } catch (e) {} };
const RAILKEY = "atlas-rail-v1";
let RAILOPEN = null;
try { const r = localStorage.getItem(RAILKEY); if (r) RAILOPEN = new Set(JSON.parse(r)); } catch (e) {}
if (!RAILOPEN) RAILOPEN = new Set([PROGRAM.current]);
const saveRail = () => { try { localStorage.setItem(RAILKEY, JSON.stringify([...RAILOPEN])); } catch (e) {} };
const BLKCLS = { "ГСЭ": "blk-gse", "МЕН": "blk-men", "ОПД": "blk-opd", "СД": "blk-sd", "ВПД": "blk-vpd" };
const ICONS = { elob: "🔋", tau: "🎛️", surn: "🚀", suka: "🛰️", nav: "🧭", toe: "🔌", teh_el: "⚡", asu: "📡", nadezh: "🛡️", ppo: "🔧" };

/* ---- v3: สองเล่ม — วิชาเนื้อหาเต็มถูกแบ่งไว้คนละหน้าเพราะเพดานขนาดไฟล์ ---- */
const VOL = 1;
const VOLS = {
  1: { url: "https://claude.ai/code/artifact/cafa6049-3eaa-4868-b97c-6875d66424b3", label: "เล่ม 1", note: "ТАУ · СН ЛА · ТОЭ · СУ РН · СУ КА · ТЭ · АСУ КА · НАС", subj: ["tau", "nav", "toe", "surn", "suka", "teh_el", "asu", "nadezh"] },
  2: { url: "https://claude.ai/code/artifact/666a1fe7-024d-4586-b16b-1738bb109276", label: "เล่ม 2", note: "ППО ЛА", subj: ["ppo"] }
};
const volOf = id => VOL;
const inOtherVol = id => volOf(id) !== VOL;
const openVol = (v, id) => { try { window.open(VOLS[v].url + (id ? "#s=" + id : ""), "_blank", "noopener"); } catch (e) {} };
function buildVolSw() {
  const el = document.getElementById("volsw");
  if (el) el.remove();
  return;
  if (!el) return;
  el.innerHTML = [1, 2].map(v =>
    '<button data-vol="' + v + '" class="' + (v === VOL ? "on" : "") + '" title="' + VOLS[v].note + '">' +
    '<b>' + VOLS[v].label + '</b><i>' + VOLS[v].subj.length + ' วิชาเต็ม</i></button>').join("");
  el.querySelectorAll("[data-vol]").forEach(b => b.addEventListener("click", () => {
    const v = +b.dataset.vol;
    if (v !== VOL) openVol(v);
  }));
}


const ALL_SUBJ = SUBJECTS;
const fmtZe = v => (v % 1 === 0 ? String(v) : String(v).replace(".", ","));
const view = document.getElementById("view");
const navEl = document.getElementById("nav");
const searchEl = document.getElementById("search");
let drill = false;
let MODE = "sum";
try { MODE = localStorage.getItem("atlas-mode-v1") || "sum"; } catch (e) {}

/* ---- keys ---- */
const subjKeys = s => DEEP[s.id]
  ? DEEP[s.id].topics.map(t => "k:" + t.id)
  : (s.topics || []).map((_, i) => "k:" + s.id + ":" + i);
const glossKeys = () => MODULES.flatMap(m => m.terms.map((_, i) => "g:" + m.id + "-" + i));
const TOTAL = ALL_SUBJ.reduce((n, s) => n + subjKeys(s).length, 0) + glossKeys().length;

function pct(keys) {
  if (!keys.length) return 0;
  return Math.round(100 * keys.filter(k => DONE.has(k)).length / keys.length);
}
function syncProgress() {
  const p = Math.round(100 * DONE.size / TOTAL);
  document.getElementById("allBar").style.width = p + "%";
  document.getElementById("allTxt").textContent = p + "%";
  navEl.querySelectorAll("[data-nav-subj]").forEach(el => {
    const s = ALL_SUBJ.find(x => x.id === el.dataset.navSubj);
    el.querySelector(".tag").textContent = pct(subjKeys(s)) + "%";
  });
  const g = navEl.querySelector('[data-nav="glossary"] .tag');
  if (g) g.textContent = pct(glossKeys()) + "%";
}
function toggleKey(k, el, cls) {
  if (DONE.has(k)) DONE.delete(k); else DONE.add(k);
  persist();
  if (el) el.classList.toggle(cls || "done", DONE.has(k));
  syncProgress();
  const bar = document.querySelector(".subj-bar-active");
  if (bar) bar.style.width = pct(subjKeys(ALL_SUBJ.find(s => s.id === state.id))) + "%";
}

/* ---- nav ---- */
const SEMKEY = "atlas-sem-v1";
let SEMOVR = {};
try { SEMOVR = JSON.parse(localStorage.getItem(SEMKEY) || "{}") || {}; } catch (e) {}
const saveSem = () => { try { localStorage.setItem(SEMKEY, JSON.stringify(SEMOVR)); } catch (e) {} };
const defSems = s => s.sems || [];
const semsOf = s => (SEMOVR[s.id] || defSems(s)).slice().sort((a, b) => a - b);
const semFirst = s => { const a = semsOf(s); return a.length ? a[0] : 99; };
const semLast = s => { const a = semsOf(s); return a.length ? a[a.length - 1] : 99; };
function semTxt(s) {
  const a = semsOf(s);
  if (!a.length) return "ยังไม่ระบุภาค";
  const runs = [];
  a.forEach(v => {
    const last = runs[runs.length - 1];
    if (last && v === last[1] + 1) last[1] = v; else runs.push([v, v]);
  });
  return "ภาค " + runs.map(r => r[0] === r[1] ? r[0] : r[0] + "–" + r[1]).join(", ");
}
const statusOf = s => {
  const a = semsOf(s);
  if (!a.length) return "next";
  if (semLast(s) < PROGRAM.current) return "done";
  if (a.includes(PROGRAM.current)) return PROGRAM.onBreak ? "next" : "now";
  return "next";
};
const STATUS_TH = { done: "ภาคเรียนที่ผ่านมา (ตามแผน)", now: "ภาคเรียนปัจจุบัน (ตามแผน)", next: "ภาคเรียนที่ยังไม่ถึง (ตามแผน)" };
const yearOf = s => YEARS.find(y => y.sems.includes(semFirst(s))) || YEARS[YEARS.length - 1];
const runningIn = n => SUBJECTS.filter(s => semsOf(s).includes(n));
const semZe = n => runningIn(n).reduce((a, s) => a + s.ze / Math.max(1, semsOf(s).length), 0);
const unassigned = () => SUBJECTS.filter(s => !semsOf(s).length);
const byNum = (a, b) => a.n - b.n;

function buildNav() {
  const mk = (label, tag, on, attrs, parent) => {
    const b = document.createElement("button");
    b.className = "nav-item";
    b.innerHTML = '<span>' + label + '</span><span class="tag">' + (tag || "") + '</span>';
    Object.entries(attrs || {}).forEach(([k, v]) => b.setAttribute(k, v));
    b.addEventListener("click", on);
    (parent || navEl).appendChild(b);
    return b;
  };
  const semRun = s => {
    const a = semsOf(s);
    if (a.length < 2) return "";
    const runs = [];
    a.forEach(v => {
      const last = runs[runs.length - 1];
      if (last && v === last[1] + 1) last[1] = v; else runs.push([v, v]);
    });
    return runs.map(r => r[0] === r[1] ? r[0] : r[0] + "–" + r[1]).join(",");
  };
  const navSubj = (s, parent) => {
    const run = semRun(s);
    const cont = run ? ' <span class="nnum span">' + run + '</span>' : '';
    const b = mk('<span class="nnum">' + s.n + '</span> ' + s.ru + cont, "0%",
      () => go({ v: "subject", id: s.id }), { "data-nav-subj": s.id, title: s.th + (run ? " · ภาค " + run : "") }, parent);
    if (DEEP[s.id]) b.classList.add("deep");
    else if (inOtherVol(s.id)) { b.classList.add("other"); b.querySelector(".tag").textContent = VOLS[volOf(s.id)].label; }
    return b;
  };
  const mkFold = (key, headHtml, cls) => {
    const open = RAILOPEN.has(key);
    const gs = document.createElement("button");
    gs.className = cls + (open ? " open" : "");
    gs.innerHTML = '<i class="rcaret">▸</i>' + headHtml;
    const body = document.createElement("div");
    body.className = "sem-body" + (open ? " open" : "");
    body.dataset.fold = key;
    gs.addEventListener("click", () => {
      const on = !body.classList.contains("open");
      body.classList.toggle("open", on);
      gs.classList.toggle("open", on);
      if (on) RAILOPEN.add(key); else RAILOPEN.delete(key);
      saveRail();
    });
    navEl.appendChild(gs);
    navEl.appendChild(body);
    return body;
  };
  mk("ภาพรวมหลักสูตร", "", () => go({ v: "overview" }), { "data-nav": "overview" });
  YEARS.forEach(y => {
    const g = document.createElement("div");
    g.className = "rail-group";
    g.textContent = y.year + " курс · ชั้นปีที่ " + y.year;
    navEl.appendChild(g);
    y.sems.forEach(n => {
      const list = runningIn(n).sort(byNum);
      const cont = list.filter(s => semFirst(s) < n).length;
      const body = mkFold(n, 'Семестр ' + n + '<span>ภาค ' + n + ' · ' + list.length + ' วิชา' +
        (cont ? ' (ต่อเนื่อง ' + cont + ')' : '') + '</span>', "rail-sem");
      list.forEach(s => navSubj(s, body));
    });
  });
  const un0 = unassigned().sort(byNum);
  if (un0.length) {
    const gu = document.createElement("div");
    gu.className = "rail-group"; gu.textContent = "ยังไม่ระบุภาคเรียน";
    navEl.appendChild(gu);
    const body = mkFold("un", 'Без семестра<span>' + un0.length + ' วิชา</span>', "rail-sem");
    un0.forEach(s => navSubj(s, body));
  }
  const g2 = document.createElement("div");
  g2.className = "rail-group"; g2.textContent = "Инструменты · เครื่องมือ";
  navEl.appendChild(g2);
  const un = unassigned().length;
  mk("ปรับภาคเรียน", un ? un + " ค้าง" : "", () => go({ v: "sem" }), { "data-nav": "sem" });
  mk("Словарь · คลังศัพท์", "0%", () => go({ v: "glossary" }), { "data-nav": "glossary" });
  mk("Карточки · Flashcard", "", () => go({ v: "flash" }), { "data-nav": "flash" });
  mk("Тренажёр · ควิซ", "", () => go({ v: "quiz" }), { "data-nav": "quiz" });
}

/* ---- overview ---- */
function subjCard(s) {
  const p = pct(subjKeys(s)), st = statusOf(s);
  return '<button class="subj ' + st + ' ' + (BLKCLS[s.block] || '') + '" data-go="' + s.id + '">' +
    '<span class="cardtop"><span class="num">' + s.n + '</span>' +
    '<span class="pill blk">' + s.block + '</span>' +
    (DEEP[s.id] ? '<span class="pill deep">เนื้อหาเต็ม</span>' : inOtherVol(s.id) ? '<span class="pill vol">เนื้อหาเต็ม · ' + VOLS[volOf(s.id)].label + '</span>' : '') +
    (st === "now" ? '<span class="pill now">กำลังเรียน</span>' : '') +
    (st === "next" && semsOf(s).includes(PROGRAM.current) ? '<span class="pill next">ภาคหน้า</span>' : '') +
    (ICONS[s.id] ? '<span class="icon">' + ICONS[s.id] + '</span>' : '') + '</span>' +
    '<span class="ru">' + s.ru + '</span>' +
    '<span class="th">' + s.th + '</span>' +
    '<span class="desc">' + s.desc + '</span>' +
    '<span class="meta"><span class="ze">' + fmtZe(s.ze) + ' з.е.</span>' +
    '<span>' + semTxt(s) + '</span>' +
    '<span class="ringwrap"><span class="ring" style="--p:' + p + '%"></span>' + p + '%</span></span>' +
    '<span class="bar"><span style="width:' + p + '%"></span></span></button>';
}

function renderOverview() {
  const now = runningIn(PROGRAM.current);
  const lastS = LAST && LAST.v === "subject" ? ALL_SUBJ.find(x => x.id === LAST.id) : null;
  let h = '<div class="wrap wide"><div class="page-head hero">' +
    '<p class="eyebrow">ВКА имени А.Ф. Можайского · г. Санкт-Петербург</p>' +
    '<h1 class="page-title">Атлас курса</h1>' +
    '<div class="page-title-th">Специализация: «' + PROGRAM.spec + '»</div>' +
    '<p class="lede">ชื่อวิชาและหน่วยกิตมาจากเอกสารหลักสูตรของกระทรวงกลาโหมรัสเซีย ส่วนการจัดภาคเรียนเป็นข้อมูลที่คุณยืนยันเอง ' +
    'ถ้ามีอะไรเปลี่ยน แก้ได้เองที่เมนู <b>ปรับภาคเรียน</b> แล้วทั้งแอปจะจัดเรียงใหม่ทันที</p>' +
    '<div class="statbar">' +
    '<div class="stat"><b>' + SUBJECTS.length + '</b><span>รายวิชา</span></div>' +
    '<div class="stat"><b>' + fmtZe(PROGRAM.listed) + '</b><span>з.е. รวม</span></div>' +
    '<div class="stat"><b>' + (PROGRAM.onBreak ? 'ปิดเทอม' : 'ภาค ' + PROGRAM.current) + '</b><span>' + (PROGRAM.onBreak ? 'ภาคหน้าคือภาค ' + PROGRAM.current : 'กำลังเรียน') + '</span></div>' +
    '<div class="stat"><b>' + PROGRAM.zeHour + '</b><span>ชั่วโมงต่อ 1 з.е.</span></div>' +
    '</div>' +
    (lastS ? '<button class="resume-chip" id="resumeBtn">▸ อ่านต่อจากครั้งก่อน — <b>' +
      (ICONS[lastS.id] ? ICONS[lastS.id] + ' ' : '') + lastS.ru + '</b></button>' : '') +
    '</div>';

  h += '<div class="nowstrip' + (PROGRAM.onBreak ? ' next' : '') + '"><div class="nowhead">' +
    '<span class="year-num">ภาคเรียนที่ ' + PROGRAM.current + '</span>' +
    '<h2>' + (PROGRAM.onBreak ? 'ภาคเรียนหน้า' : 'กำลังเรียนอยู่ตอนนี้') + '</h2>' +
    '<span class="year-note">' + (PROGRAM.onBreak ? 'ตอนนี้ปิดเทอมอยู่ · ' : '') + now.length + ' วิชา · ' + semZe(PROGRAM.current).toFixed(1) + ' з.е.</span></div>' +
    '<div class="subj-grid">' + now.map(subjCard).join("") + '</div></div>';

  YEARS.forEach(y => {
    const ys = SUBJECTS.filter(s => y.sems.includes(semFirst(s)));
    const ze = ys.reduce((a, s) => a + s.ze, 0);
    h += '<div class="year"><div class="year-head"><span class="year-num">' + y.year + ' курс</span>' +
      '<h2>ชั้นปีที่ ' + y.year + '</h2>' +
      '<span class="year-note">' + ys.length + ' วิชาเริ่มในปีนี้ · ' + fmtZe(ze) + ' з.е.</span></div>';
    y.sems.forEach(n => {
      const list = SUBJECTS.filter(s => semFirst(s) === n).sort(byNum);
      const cont = runningIn(n).filter(s => semFirst(s) < n);
      h += '<div class="sem-head"><b>Семестр ' + n + '</b><span>ภาคเรียนที่ ' + n + '</span>' +
        '<span class="sem-note">' + runningIn(n).length + ' วิชาที่เรียนพร้อมกัน · ' + semZe(n).toFixed(1) + ' з.е.' +
        (cont.length ? ' · ต่อเนื่องจากภาคก่อน ' + cont.length + ' วิชา' : '') + '</span></div>';
      h += list.length ? '<div class="subj-grid">' + list.map(subjCard).join("") + '</div>'
        : '<p class="empty" style="padding:8px 0">ไม่มีวิชาที่เริ่มในภาคนี้</p>';
    });
    h += '</div>';
  });
  const un = unassigned().sort(byNum);
  if (un.length) {
    h += '<div class="year"><div class="year-head"><span class="year-num">?</span>' +
      '<h2>ยังไม่ระบุภาคเรียน</h2><span class="year-note">' + un.length + ' วิชา — ไปติ๊กได้ที่เมนู ปรับภาคเรียน</span></div>' +
      '<div class="subj-grid">' + un.map(subjCard).join("") + '</div></div>';
  }
  h += '<footer class="foot">ตัดรายการ Тактика специальная การฝึกงานทั้งหมด และ ГИА ออกตามที่สั่งไว้ ส่วนพลศึกษาใส่กลับเข้ามาแล้ว (เรียนภาค 1–9) เหลือ ' +
    SUBJECTS.length + ' วิชา รวม ' + fmtZe(PROGRAM.listed) + ' з.е. · ' +
    'ตัวเลขมุมซ้ายของแต่ละการ์ดคือเลขอ้างอิงที่คงที่ ใช้บอกผมได้ว่าจะแก้วิชาไหน · ความคืบหน้าเก็บไว้ในเบราว์เซอร์เครื่องนี้เท่านั้น</footer></div>';
  view.innerHTML = h;
  view.querySelectorAll("[data-go]").forEach(b => b.addEventListener("click", () => go({ v: "subject", id: b.dataset.go })));
  const rb = document.getElementById("resumeBtn");
  if (rb) rb.addEventListener("click", () => {
    const y = (LAST && LAST.y) || 0;
    go({ v: "subject", id: LAST.id });
    setTimeout(() => window.scrollTo({ top: y, behavior: "instant" }), 90);
  });
}

/* ---- subject ---- */
const demoSlots = t => ((t.demos || (t.demo ? [t.demo] : []))
  .map(k => '<div data-demo="' + k + '"></div>').join(""));
let LAZYBODY = [], LAZY_IO = null, SPY_IO = null;
function lazyBody(t) {
  const i = LAZYBODY.push(t) - 1;
  return '<div class="tbody" data-lazy="' + i + '"><div class="tload">กำลังโหลดหัวข้อ…</div></div>';
}
async function fillBody(el) {
  if (!el || el.dataset.lazy === undefined) return;
  const t = LAZYBODY[el.dataset.lazy];
  const sid = (typeof state !== "undefined" && state && state.id) || "";
  delete el.dataset.lazy;
  let html = null;
  try { html = await topicHtml(sid, t); } catch (e) { html = null; }
  if (html === null) {
    const viaFile = location.protocol === "file:";
    el.innerHTML = '<div class="tload tfail">โหลดหัวข้อนี้ไม่สำเร็จ' +
      (viaFile
        ? ' — หน้านี้เปิดจากไฟล์ในเครื่องโดยตรง เบราว์เซอร์จึงไม่ยอมให้อ่านไฟล์เนื้อหาข้าง ๆ ต้องเปิดผ่านเซิร์ฟเวอร์แทน: ดับเบิลคลิก <b>preview.bat</b> ในโฟลเดอร์เดียวกันนี้ หรือเปิดจากเว็บที่เผยแพร่แล้ว'
        : ' — อ่านไฟล์เนื้อหาไม่ได้ ลองตรวจการเชื่อมต่ออินเทอร์เน็ตแล้วกดลองใหม่') +
      (viaFile ? '' : ' <button type="button" data-retry>ลองใหม่</button>') + '</div>';
    const b = el.querySelector("[data-retry]");
    if (b) b.addEventListener("click", () => {
      DBCACHE.delete("t/" + sid + "__" + t.id);
      el.dataset.lazy = LAZYBODY.indexOf(t);
      el.innerHTML = '<div class="tload">กำลังโหลดหัวข้อ…</div>';
      fillBody(el);
    });
    return;
  }
  el.innerHTML = html + demoSlots(t);
  el.querySelectorAll("[data-demo]").forEach(d => { if (d.dataset.demo && DEMOS[d.dataset.demo]) DEMOS[d.dataset.demo](d); });
  if (window.SUKAFIG) window.SUKAFIG(el);
}
function fillAllBodies() {
  return Promise.all([...document.querySelectorAll(".tbody[data-lazy]")].map(fillBody));
}
window.addEventListener("beforeprint", fillAllBodies);

function renderSubject() {
  LAZYBODY = [];
  if (LAZY_IO) { LAZY_IO.disconnect(); LAZY_IO = null; }
  if (SPY_IO) { SPY_IO.disconnect(); SPY_IO = null; }
  const s = ALL_SUBJ.find(x => x.id === state.id);
  const deep = DEEP[s.id];
  const y = yearOf(s), st = statusOf(s);
  let h = '<div class="wrap' + (deep ? ' hastoc' : '') + '">' +
    '<nav class="crumb"><button data-crumb-home>ภาพรวมหลักสูตร</button><span>›</span>' +
    (semsOf(s).length ? '<span>ชั้นปีที่ ' + y.year + ' · ' + semTxt(s) + '</span><span>›</span>' : '') +
    '<b>' + s.th + '</b></nav>' +
    '<div class="page-head">' +
    '<p class="eyebrow">№ ' + s.n + ' · ' + (semsOf(s).length ? 'ชั้นปีที่ ' + y.year + ' · ' + semTxt(s) + ' · ' + STATUS_TH[st] : 'ยังไม่ระบุภาคเรียน') +
    ' · ' + s.block + ' ' + BLOCKS[s.block] + (deep ? ' · เนื้อหาเต็ม' : ' · โครงร่าง') + '</p>' +
    '<h1 class="page-title">' + (ICONS[s.id] ? '<span class="ticon">' + ICONS[s.id] + '</span>' : '') + s.ru + '</h1>' +
    '<div class="page-title-th">' + s.th + ' · <span class="m">' + fmtZe(s.ze) + ' з.е. ≈ ' + Math.round(s.ze * PROGRAM.zeHour) + ' ак. ч.</span></div>' +
    '<p class="lede">' + (deep ? deep.lede : s.desc) + '</p>' +
    '<div style="margin-top:16px"><span class="track" style="width:180px;display:inline-block;vertical-align:middle"><span class="subj-bar-active" style="width:' + pct(subjKeys(s)) + '%"></span></span> <span class="m" style="font-size:11px;color:var(--ink-3)">ทำเครื่องหมายทบทวนแล้ว ' + pct(subjKeys(s)) + '%</span></div>' +
    '<p class="m">สถานะภาคเรียนอิงแผนการเรียน ส่วนเปอร์เซ็นต์อิงการทำเครื่องหมายของคุณในเครื่องนี้ ไม่ใช่ผลสอบหรือการประเมินความเข้าใจ</p>' +
    '</div>';

  if (deep) {
    const hasSum = !!(deep.summary && deep.summary.length);
    const mode = hasSum ? MODE : "full";
    if (hasSum) {
      h += '<div class="modebar">' +
        '<button data-mode="sum" class="' + (mode === "sum" ? "on" : "") + '">สรุปทบทวน</button>' +
        '<button data-mode="full" class="' + (mode === "full" ? "on" : "") + '">ฉบับเต็ม</button></div>' +
        '<p class="modehint">' + (mode === "sum"
          ? "หน้าเดียวจบก่อนสอบ — นิยาม สูตร แผนภาพ และคำถามที่ออกบ่อย"
          : "ฉบับเรียนจริง — อธิบายทีละหัวข้อ พร้อมที่มาของสูตร แบบจำลอง และแบบฝึกหัดมีเฉลย") + '</p>';
    }
    if (mode === "sum") {
      h += '<div class="topic-nav">' + deep.summary.map((t, i) => '<button data-jump="' + t.id + '">' + t.th + '</button>').join("") + '</div>';
      deep.summary.forEach(t => {
        h += '<section class="topic" id="' + t.id + '"><div class="topic-head">' +
          '<button class="fold" aria-label="ย่อ/ขยายหัวข้อ">▾</button><div>' +
          '<h2>' + t.ru + '</h2><div class="th">' + t.th + '</div></div></div>' +
          lazyBody(t) + '</section>';
      });
    } else {
      h += '<div class="topic-nav">' + deep.topics.map((t, i) => '<button data-jump="' + t.id + '">' + (i + 1) + '. ' + t.th + '</button>').join("") + '</div>';
      deep.topics.forEach((t, i) => {
        h += '<section class="topic" id="' + t.id + '"><div class="topic-head">' +
          '<button class="fold" aria-label="ย่อ/ขยายหัวข้อ">▾</button><div>' +
          '<h2>' + (i + 1) + '. ' + t.ru + '</h2><div class="th">' + t.th + '</div></div>' +
          '<button class="topic-check' + (DONE.has("k:" + t.id) ? " done" : "") + '" data-key="k:' + t.id + '" title="ทบทวนหัวข้อนี้แล้ว" aria-label="ทำเครื่องหมายว่าทบทวนแล้ว">✓</button></div>' +
          lazyBody(t) + '</section>';
      });
    }
    const tocItems = mode === "sum" ? deep.summary : deep.topics;
    h += '<aside class="toc" aria-label="สารบัญ"><div class="toc-h">สารบัญ · ' + tocItems.length + ' หัวข้อ</div>' +
      tocItems.map((t, i) => '<button data-toc="' + t.id + '">' + (mode === "full" ? (i + 1) + '. ' : '') + t.th + '</button>').join("") + '</aside>';
  } else {
    h += '<section class="topic"><div class="topic-head"><div><h2>Основные разделы</h2><div class="th">หัวข้อหลักของวิชา</div></div></div>' +
      '<p>ติ๊กหัวข้อที่ทบทวนแล้วเพื่อให้แถบความคืบหน้าเดิน วิชานี้ยังเป็นโครงร่าง — ถ้าอยากให้ทำเนื้อหาเต็มพร้อมภาพและแบบจำลองแบบวิชา ТАУ กับ Системы навигации ЛА บอกผมได้เลย</p><ul style="list-style:none;padding:0">';
    (s.topics || []).forEach((t, i) => {
      const k = "k:" + s.id + ":" + i;
      h += '<li style="display:flex;gap:10px;align-items:center;padding:9px 0;border-bottom:1px solid var(--line)">' +
        '<button class="topic-check' + (DONE.has(k) ? " done" : "") + '" data-key="' + k + '" style="margin-left:0;flex:none" aria-label="ทบทวนแล้ว">✓</button>' +
        '<span>' + t + '</span></li>';
    });
    h += '</ul></section>';
  }
  const same = semsOf(s).length ? runningIn(semFirst(s)).filter(x => x.id !== s.id).sort(byNum) : [];
  if (same.length) h += '<section class="topic"><div class="topic-head"><div><h2>เรียนพร้อมกันในภาค ' + semFirst(s) + '</h2>' +
    '<div class="th">' + same.length + ' วิชา</div></div></div><div class="chiprow">' +
    same.map(x => '<button class="chip" data-go="' + x.id + '"><b>' + x.n + '</b> ' + x.th + '</button>').join("") + '</div></section>';
  h += '<footer class="foot">' + (deep ? "เลื่อนสไลเดอร์ในแบบจำลองได้ทุกตัว ค่าที่แสดงคำนวณสด ๆ จากสมการจริง ไม่ใช่ภาพนิ่ง" : "") + '</footer></div>';
  view.innerHTML = h;

  view.querySelectorAll("[data-mode]").forEach(b => b.addEventListener("click", () => {
    MODE = b.dataset.mode;
    try { localStorage.setItem("atlas-mode-v1", MODE); } catch (e) {}
    clearDemos(); renderSubject();
  }));
  view.querySelectorAll("[data-key]").forEach(b => b.addEventListener("click", () => toggleKey(b.dataset.key, b)));
  view.querySelectorAll("[data-go]").forEach(b => b.addEventListener("click", () => go({ v: "subject", id: b.dataset.go })));
  const jumpTo = id => {
    const el = document.getElementById(id);
    if (el) {
      el.classList.remove("closed");
      fillBody(el.querySelector(".tbody[data-lazy]"));
      window.scrollTo({ top: el.offsetTop - 110, behavior: "smooth" });
    }
  };
  view.querySelectorAll("[data-jump]").forEach(b => b.addEventListener("click", () => jumpTo(b.dataset.jump)));
  view.querySelectorAll("[data-toc]").forEach(b => b.addEventListener("click", () => jumpTo(b.dataset.toc)));
  const ch = view.querySelector("[data-crumb-home]");
  if (ch) ch.addEventListener("click", () => go({ v: "overview" }));
  view.querySelectorAll("section.topic .topic-head").forEach(hd => hd.addEventListener("click", e => {
    if (e.target.closest(".topic-check")) return;
    hd.parentElement.classList.toggle("closed");
  }));
  const tocBtns = view.querySelectorAll("[data-toc]");
  if (tocBtns.length && window.IntersectionObserver) {
    SPY_IO = new IntersectionObserver(es => es.forEach(e => {
      if (e.isIntersecting) tocBtns.forEach(b => b.classList.toggle("on", b.dataset.toc === e.target.id));
    }), { rootMargin: "-15% 0px -70% 0px" });
    view.querySelectorAll("section.topic[id]").forEach(sec => SPY_IO.observe(sec));
  }
  view.querySelectorAll("[data-demo]").forEach(d => { if (d.dataset.demo && DEMOS[d.dataset.demo]) DEMOS[d.dataset.demo](d); });
  if (window.SUKAFIG) window.SUKAFIG(view);
  const lz = view.querySelectorAll(".tbody[data-lazy]");
  if (lz.length) {
    if (window.IntersectionObserver) {
      LAZY_IO = new IntersectionObserver(es => es.forEach(e => {
        if (e.isIntersecting) { LAZY_IO.unobserve(e.target); fillBody(e.target); }
      }), { rootMargin: "900px 0px" });
      lz.forEach(el => LAZY_IO.observe(el));
    } else fillAllBodies();
  }
}

/* ---- router ---- */
let state = { v: "overview" };
function go(st) {
  if (st.v === "subject" && inOtherVol(st.id)) { openVol(volOf(st.id), st.id); return; }
  state = st;
  clearDemos();
  navEl.querySelectorAll(".nav-item").forEach(b => {
    b.classList.toggle("active",
      (st.v === "subject" && b.dataset.navSubj === st.id) ||
      (st.v !== "subject" && b.dataset.nav === st.v));
  });
  if (st.v === "subject") {
    navEl.querySelectorAll(".sem-body").forEach(body => {
      if (!body.classList.contains("open") && body.querySelector('[data-nav-subj="' + st.id + '"]')) {
        body.classList.add("open");
        const gs = body.previousElementSibling;
        if (gs && gs.classList.contains("rail-sem")) gs.classList.add("open");
        const key = body.dataset.fold === "un" ? "un" : +body.dataset.fold;
        RAILOPEN.add(key); saveRail();
      }
    });
  }
  ({ overview: renderOverview, subject: renderSubject, glossary: renderGlossary, quiz: renderQuiz, search: renderSearch, sem: renderSemEditor, flash: renderFlash }[st.v] || renderOverview)();
  window.scrollTo({ top: 0, behavior: "instant" });
  syncProgress();
  if (st.v === "subject") { LAST = { v: "subject", id: st.id, y: 0 }; saveLast(); }
  document.querySelectorAll("#bbar [data-bb]").forEach(b => b.classList.toggle("on", b.dataset.bb === st.v));
}


/* ---- แบบสอบถามภาคเรียน ---- */
function renderSemEditor() {
  let tab = 1;
  const yearOfSem = n => YEARS.find(y => y.sems.includes(n)).year;
  view.innerHTML = '<div class="wrap wide"><div class="page-head">' +
    '<p class="eyebrow">Опрос · แบบสอบถาม</p>' +
    '<h1 class="page-title">ภาคเรียนไหนเรียนอะไรบ้าง</h1>' +
    '<div class="page-title-th">เลือกภาคเรียนด้านบน แล้วติ๊กวิชาที่เรียนในภาคนั้น — วิชาหนึ่งติ๊กได้หลายภาคถ้าเรียนต่อเนื่อง</div>' +
    '<p class="lede">ตอนนี้ติ๊กไว้ตามที่ผมเดา กดวิชาที่ผิดเพื่อเอาออก แล้วไปติ๊กในภาคที่ถูกต้อง ทุกอย่างบันทึกในเครื่องนี้ทันที ' +
    'และหน้าอื่นของแอปจะจัดเรียงตามที่คุณแก้เลย ถ้าแก้แล้วอยากให้ผมฝังลงในแอปถาวร กดปุ่มล่างสุดแล้วส่งสรุปมาให้ผม</p>' +
    '<div class="qbar"><button id="clearAll">ล้างทั้งหมด แล้วเริ่มติ๊กใหม่</button>' +
    '<button id="resetDraft">กลับไปใช้ค่าที่ยืนยันไว้</button>' +
    '<span class="m" id="unCount"></span></div>' +
    '</div><div class="semtabs" id="tabs"></div><div id="qbody"></div>' +
    '<div class="qsum"><h3>สรุปคำตอบ — ส่งข้อความนี้กลับมาให้ผม</h3>' +
    '<textarea id="sumBox" readonly rows="12" spellcheck="false"></textarea>' +
    '<div class="qbar"><button id="copyBtn">คัดลอก</button><span class="m" id="copyMsg"></span></div></div></div>';

  const tabsEl = document.getElementById("tabs"), body = document.getElementById("qbody");
  const sum = document.getElementById("sumBox"), unEl = document.getElementById("unCount");

  function setSem(s, n, on) {
    const cur = new Set(semsOf(s));
    if (on) cur.add(n); else cur.delete(n);
    SEMOVR[s.id] = [...cur].sort((a, b) => a - b);
    saveSem();
  }
  function summary() {
    let out = [];
    for (let n = 1; n <= 9; n++) {
      const list = runningIn(n).sort(byNum);
      out.push("ภาค " + n + ": " + (list.length ? list.map(s => s.n).join(", ") : "—"));
    }
    const un = unassigned().sort(byNum);
    if (un.length) out.push("ยังไม่ระบุ: " + un.map(s => s.n).join(", "));
    out.push("");
    out.push("(เลขอ้างอิงตามหมายเลขวิชาใน Study Program)");
    return out.join("\n");
  }
  function paintTabs() {
    tabsEl.innerHTML = "";
    for (let n = 1; n <= 9; n++) {
      const b = document.createElement("button");
      b.className = "semtab" + (n === tab ? " on" : "");
      b.innerHTML = '<b>ภาค ' + n + '</b><span>ปี ' + yearOfSem(n) + ' · ' + runningIn(n).length + ' วิชา</span>';
      b.addEventListener("click", () => { tab = n; paint(); });
      tabsEl.appendChild(b);
    }
  }
  function paint() {
    paintTabs();
    const ze = semZe(tab), cnt = runningIn(tab).length;
    let h = '<div class="sem-head"><b>Семестр ' + tab + '</b><span>ติ๊กวิชาที่เรียนในภาคเรียนที่ ' + tab + '</span>' +
      '<span class="sem-note">เลือกแล้ว ' + cnt + ' วิชา · ' + ze.toFixed(1) + ' з.е.</span></div><div class="qgrid">';
    ["ГСЭ", "МЕН", "ОПД", "СД", "ВПД"].forEach(bl => {
      const list = SUBJECTS.filter(s => s.block === bl).sort(byNum);
      h += '<div class="qblock"><div class="qblock-h">' + bl + ' · ' + BLOCKS[bl] + '</div>';
      list.forEach(s => {
        const on = semsOf(s).includes(tab);
        h += '<button class="qrow' + (on ? " on" : "") + '" data-id="' + s.id + '">' +
          '<span class="qbox">✓</span><span class="qn">' + s.n + '</span>' +
          '<span class="qtxt"><b>' + s.ru + '</b><i>' + s.th + '</i></span>' +
          '<span class="qmeta">' + fmtZe(s.ze) + ' з.е.<br><em>' + semTxt(s) + '</em></span></button>';
      });
      h += '</div>';
    });
    h += '</div>';
    body.innerHTML = h;
    body.querySelectorAll(".qrow").forEach(r => r.addEventListener("click", () => {
      const s = SUBJECTS.find(x => x.id === r.dataset.id);
      setSem(s, tab, !semsOf(s).includes(tab));
      paint();
    }));
    sum.value = summary();
    const un = unassigned();
    unEl.textContent = un.length ? "ยังไม่ระบุภาค " + un.length + " วิชา: " + un.sort(byNum).map(s => s.n).join(", ") : "ระบุครบทุกวิชาแล้ว";
    unEl.className = "m" + (un.length ? " warn" : " ok");
    const navTag = navEl.querySelector('[data-nav="sem"] .tag');
    if (navTag) navTag.textContent = un.length ? un.length + " ค้าง" : "";
  }
  document.getElementById("clearAll").addEventListener("click", () => {
    SUBJECTS.forEach(s => SEMOVR[s.id] = []);
    saveSem(); paint();
  });
  document.getElementById("resetDraft").addEventListener("click", () => {
    SEMOVR = {}; saveSem(); paint();
  });
  document.getElementById("copyBtn").addEventListener("click", async () => {
    const msg = document.getElementById("copyMsg");
    try {
      await navigator.clipboard.writeText(sum.value);
      msg.textContent = "คัดลอกแล้ว — วางในแชทได้เลย";
    } catch (e) {
      sum.focus(); sum.select();
      msg.textContent = "เลือกข้อความให้แล้ว กด Ctrl+C / Cmd+C เพื่อคัดลอก";
    }
  });
  paint();
}

/* ---- glossary ---- */
function renderGlossary() {
  let h = '<div class="wrap wide"><div class="page-head">' +
    '<p class="eyebrow">Словарь · ' + MODULES.reduce((n, m) => n + m.terms.length, 0) + ' คำ</p><h1 class="page-title">คลังศัพท์ СУЛА</h1>' +
    '<div class="page-title-th">รัสเซีย → ไทย พร้อมคำอธิบายและสูตร</div>' +
    '<p class="lede">ใช้ช่องค้นหาด้านบนกรองได้ทุกคำ กด ★ เพื่อบุ๊กมาร์กคำที่ยังไม่แม่น แล้วฝึกเฉพาะชุดนั้นในโหมด Flashcard ได้</p>' +
    '<div style="margin-top:14px;display:flex;gap:8px;flex-wrap:wrap"><button id="drillBtn" class="' + (drill ? "on" : "") + '">โหมดฝึกจำ</button>' +
    '<button id="unkBtn">เฉพาะที่ยังไม่ติ๊ก</button>' +
    '<button id="bmBtn">★ เฉพาะบุ๊กมาร์ก</button>' +
    '<button id="flashBtn">ฝึกแบบ Flashcard</button></div></div><div id="gloss" class="' + (drill ? "drill" : "") + '">';
  MODULES.forEach(m => {
    h += '<div class="modcap" data-mod="' + m.id + '"><h3>' + m.ru + '</h3><span class="th">' + m.th + '</span></div><div class="g-grid" data-grid="' + m.id + '">';
    m.terms.forEach((t, i) => {
      const k = "g:" + m.id + "-" + i;
      h += '<article class="card' + (DONE.has(k) ? " known" : "") + (BM.has(k) ? " bm" : "") + '" data-k="' + k + '" data-hay="' +
        (t.ru + " " + (t.abbr || "") + " " + t.th + " " + t.note).toLowerCase().replace(/"/g, "") + '">' +
        '<div class="ru">' + t.ru + (t.abbr ? ' <span class="abbr">' + t.abbr + '</span>' : '') + '</div>' +
        '<div class="th">' + t.th + '</div><div class="note">' + t.note + '</div>' +
        (t.f ? '<div class="f">' + t.f + '</div>' : '') +
        '<button class="bmark" aria-label="บุ๊กมาร์กคำนี้">★</button>' +
        '<button class="tick" aria-label="จำได้แล้ว">✓</button></article>';
    });
    h += '</div>';
  });
  h += '</div><p class="empty hidden" id="gEmpty">ไม่พบคำที่ตรงกับที่ค้นหา</p></div>';
  view.innerHTML = h;

  const gloss = document.getElementById("gloss");
  let onlyUnknown = false, onlyBM = false;
  view.querySelectorAll(".card").forEach(card => {
    card.querySelector(".tick").addEventListener("click", e => {
      e.stopPropagation();
      toggleKey(card.dataset.k, card, "known");
      if (onlyUnknown) filterGloss();
    });
    card.querySelector(".bmark").addEventListener("click", e => {
      e.stopPropagation();
      const k = card.dataset.k;
      if (BM.has(k)) BM.delete(k); else BM.add(k);
      persistBM();
      card.classList.toggle("bm", BM.has(k));
      if (onlyBM) filterGloss();
    });
    card.addEventListener("click", () => { if (drill) card.classList.toggle("rv"); });
  });
  document.getElementById("bmBtn").addEventListener("click", e => {
    onlyBM = !onlyBM;
    e.target.classList.toggle("on", onlyBM);
    filterGloss();
  });
  document.getElementById("flashBtn").addEventListener("click", () => go({ v: "flash" }));
  document.getElementById("drillBtn").addEventListener("click", e => {
    drill = !drill;
    e.target.classList.toggle("on", drill);
    gloss.classList.toggle("drill", drill);
    if (!drill) view.querySelectorAll(".card.rv").forEach(c => c.classList.remove("rv"));
  });
  const unk = document.getElementById("unkBtn");
  unk.addEventListener("click", () => { onlyUnknown = !onlyUnknown; unk.classList.toggle("on", onlyUnknown); filterGloss(); });

  function filterGloss() {
    const q = (searchEl.value || "").trim().toLowerCase();
    let shown = 0;
    MODULES.forEach(m => {
      let n = 0;
      view.querySelectorAll('[data-grid="' + m.id + '"] .card').forEach(c => {
        const ok = (!q || c.dataset.hay.includes(q)) && (!onlyUnknown || !DONE.has(c.dataset.k)) && (!onlyBM || BM.has(c.dataset.k));
        c.classList.toggle("hidden", !ok);
        if (ok) n++;
      });
      view.querySelector('[data-grid="' + m.id + '"]').classList.toggle("hidden", n === 0);
      view.querySelector('[data-mod="' + m.id + '"]').classList.toggle("hidden", n === 0);
      shown += n;
    });
    document.getElementById("gEmpty").classList.toggle("hidden", shown > 0);
  }
  renderGlossary.filter = filterGloss;
  filterGloss();
}

/* ---- search ---- */
const INDEX = [];
let INDEX_BUILT = false;
/* ข้อความสำหรับค้นหาก็อยู่ในฐานข้อมูล — ดึงเบื้องหลังหลังหน้าโหลดเสร็จ
   ระหว่างที่ยังมาไม่ถึง การค้นหาครอบคลุมชื่อวิชา ชื่อหัวข้อ และคลังศัพท์ */
const IXHAY = {};
let IX_LOADED = false;
async function loadIndex() {
  if (IX_LOADED) return;
  IX_LOADED = true;
  const man = await fetch("data/manifest.json").then(r => r.ok ? r.json() : null).catch(() => null);
  const subs = (man && man.subjects) || {};
  await Promise.all(Object.keys(subs).map(async sid => {
    const d = await dbGet("ix", sid);
    (d && d.rows || []).forEach(r => { IXHAY[sid + "__" + r.id] = r.hay; });
  }));
  INDEX.length = 0; INDEX_BUILT = false;
  // Refresh an early search once full-text content is available.
  if (state.v === "search") renderSearch();
}
window.addEventListener("load", () => setTimeout(loadIndex, 1200));
function buildIndex() {
  if (INDEX_BUILT) return;
  INDEX_BUILT = true;
  const strip = html => html.replace(/<[^>]*>/g, " ").replace(/&#?[a-z0-9]{1,8};/gi, " ").replace(/\s+/g, " ");
  ALL_SUBJ.forEach(s => {
    INDEX.push({ kind: "วิชา · " + semTxt(s), title: s.ru, sub: s.th + " — " + s.desc, hay: (s.ru + " " + s.th + " " + s.desc + " " + (s.topics || []).join(" ")).toLowerCase(), go: { v: "subject", id: s.id } });
    if (DEEP[s.id]) DEEP[s.id].topics.forEach(t => {
      INDEX.push({ kind: "หัวข้อ · " + s.th, title: t.ru, sub: t.th, hay: (t.ru + " " + t.th + " " + (IXHAY[s.id + "__" + t.id] || strip(t.html || ""))).toLowerCase(), go: { v: "subject", id: s.id }, jump: t.id });
    });
  });
  MODULES.forEach(m => m.terms.forEach(t => {
    INDEX.push({ kind: "ศัพท์ · " + m.th, title: t.ru, sub: t.th + " — " + t.note, hay: (t.ru + " " + (t.abbr || "") + " " + t.th + " " + t.note).toLowerCase(), go: { v: "glossary" } });
  }));
}
function searchAliases(query) {
  const q = query.trim().toLowerCase();
  const aliases = ["kalman", "калман", "кальман", "คาลมาน"];
  const found = aliases.find(a => q.includes(a));
  return found ? [...new Set(aliases.map(a => q.replaceAll(found, a)))] : [q];
}
function escapeText(value) {
  return String(value).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function renderSearch() {
  buildIndex();
  const q = state.q;
  const queries = searchAliases(q);
  const hits = INDEX.filter(x => queries.some(term => x.hay.includes(term))).slice(0, 60);
  let h = '<div class="wrap"><div class="page-head"><p class="eyebrow">Поиск</p>' +
    '<h1 class="page-title">ผลการค้นหา “' + escapeText(q) + '”</h1>' +
    '<div class="page-title-th">พบ ' + hits.length + ' รายการ' + (hits.length === 60 ? "+ (แสดง 60 แรก)" : "") + '</div></div><div class="res">';
  if (!hits.length) h += '<p class="empty">ไม่พบ ลองพิมพ์บางส่วนของคำรัสเซีย เช่น «устойч» หรือคำไทย เช่น «เสถียร»</p>';
  hits.forEach((x, i) => {
    h += '<button class="res-item" data-i="' + i + '"><span class="k">' + x.kind + '</span>' +
      '<span class="t">' + x.title + '</span><span class="s">' + x.sub.slice(0, 150) + '</span></button>';
  });
  h += '</div></div>';
  view.innerHTML = h;
  view.querySelectorAll(".res-item").forEach(b => b.addEventListener("click", () => {
    const x = hits[+b.dataset.i];
    if (x.jump) {
      MODE = "full";
      try { localStorage.setItem("atlas-mode-v1", MODE); } catch (e) {}
    }
    go(x.go);
    if (x.jump) setTimeout(() => { const el = document.getElementById(x.jump); if (el) window.scrollTo({ top: el.offsetTop - 110, behavior: "smooth" }); }, 60);
  }));
}

/* ---- flashcards ---- */
function renderFlash() {
  let src = "all", deck = [], idx = 0, flip = false, okCount = 0;
  const allCards = MODULES.flatMap(m => m.terms.map((t, i) => ({ t, mod: m.th, k: "g:" + m.id + "-" + i })));
  const build = () => {
    deck = allCards.filter(c => src === "all" ? true : src === "unk" ? !DONE.has(c.k) : BM.has(c.k));
    for (let i = deck.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [deck[i], deck[j]] = [deck[j], deck[i]];
    }
    idx = 0; flip = false; okCount = 0;
  };
  view.innerHTML = '<div class="wrap flash"><div class="page-head">' +
    '<p class="eyebrow">Карточки</p>' +
    '<h1 class="page-title">Flashcard คำศัพท์</h1>' +
    '<div class="page-title-th">แตะการ์ดเพื่อเปิดคำแปล — «จำได้» จะติ๊กเข้าคลังศัพท์ให้อัตโนมัติ</div>' +
    '<div class="fsrc"><button data-src="all" class="on">ทั้งหมด</button>' +
    '<button data-src="unk">ที่ยังไม่ติ๊ก</button>' +
    '<button data-src="bm">★ บุ๊กมาร์ก</button></div></div>' +
    '<div class="fmeta"><span id="fPos"></span><span id="fOk"></span></div><div id="fBox"></div></div>';
  const box = document.getElementById("fBox");
  function draw() {
    document.getElementById("fPos").textContent = deck.length ? Math.min(idx + 1, deck.length) + " / " + deck.length : "0 / 0";
    document.getElementById("fOk").textContent = "จำได้ " + okCount;
    if (!deck.length) {
      box.innerHTML = '<p class="empty">ไม่มีการ์ดในชุดนี้' + (src === "bm" ? " — กด ★ ในคลังศัพท์เพื่อบุ๊กมาร์กคำก่อน" : " — ติ๊กครบทุกคำแล้ว เก่งมาก") + '</p>';
      return;
    }
    if (idx >= deck.length) {
      box.innerHTML = '<div class="fcard" style="cursor:default"><div class="fru">จบชุดแล้ว</div>' +
        '<div class="fnote">จำได้ ' + okCount + ' จาก ' + deck.length + ' ใบ</div></div>' +
        '<div class="fbtns"><button id="fAgain">สับไพ่ใหม่อีกรอบ</button><button id="fGloss">ไปคลังศัพท์</button></div>';
      document.getElementById("fAgain").addEventListener("click", () => { build(); draw(); });
      document.getElementById("fGloss").addEventListener("click", () => go({ v: "glossary" }));
      return;
    }
    const c = deck[idx], t = c.t;
    box.innerHTML = '<div class="fcard" id="fc"><div class="fmod">' + c.mod + '</div>' +
      '<div class="fru">' + t.ru + (t.abbr ? ' <span class="fabbr">' + t.abbr + '</span>' : '') + '</div>' +
      (flip
        ? '<div class="fth">' + t.th + '</div><div class="fnote">' + t.note + '</div>' + (t.f ? '<div class="ff">' + t.f + '</div>' : '')
        : '') +
      '<div class="hint">' + (flip ? "แตะอีกครั้งเพื่อปิดคำแปล" : "แตะการ์ดเพื่อดูคำแปล") + '</div></div>' +
      '<div class="fbtns"><button id="fNo">ยังไม่แม่น</button><button id="fYes" class="yes">จำได้ ✓</button></div>';
    document.getElementById("fc").addEventListener("click", () => { flip = !flip; draw(); });
    document.getElementById("fNo").addEventListener("click", () => { flip = false; idx++; draw(); });
    document.getElementById("fYes").addEventListener("click", () => {
      if (!DONE.has(c.k)) { DONE.add(c.k); persist(); syncProgress(); }
      okCount++; flip = false; idx++; draw();
    });
  }
  view.querySelectorAll("[data-src]").forEach(b => b.addEventListener("click", () => {
    src = b.dataset.src;
    view.querySelectorAll("[data-src]").forEach(x => x.classList.toggle("on", x === b));
    build(); draw();
  }));
  build(); draw();
}

/* ---- quiz ---- */
const POOL = () => MODULES.flatMap(m => m.terms.map(t => ({ ru: t.ru, th: t.th, mod: m.th, note: t.note || "" })));
function renderQuiz() {
  const pool = POOL();
  let round = [], idx = 0, score = 0, streak = 0, best = 0;
  const pick = () => {
    round = [];
    const used = new Set();
    while (round.length < 10) {
      const i = Math.floor(Math.random() * pool.length);
      if (used.has(i)) continue;
      used.add(i);
      const right = pool[i];
      const opts = [right];
      while (opts.length < 4) {
        const c = pool[Math.floor(Math.random() * pool.length)];
        if (!opts.some(o => o.th === c.th)) opts.push(c);
      }
      opts.sort(() => Math.random() - .5);
      round.push({ q: right, opts });
    }
    idx = 0; score = 0; streak = 0;
  };
  view.innerHTML = '<div class="wrap"><div class="page-head"><p class="eyebrow">Тренажёр</p>' +
    '<h1 class="page-title">ควิซคำศัพท์</h1><div class="page-title-th">รัสเซีย → ไทย ครั้งละ 10 ข้อ</div></div>' +
    '<div class="quiz" id="quizBox"></div></div>';
  const box = document.getElementById("quizBox");

  function draw() {
    if (idx >= round.length) {
      box.innerHTML = '<div class="prompt">ได้ ' + score + ' / ' + round.length + '</div>' +
        '<p class="prompt-sub">ชุดยาวที่สุดที่ตอบถูกติดกัน: ' + best + ' ข้อ</p>' +
        '<div class="quiz-foot"><button id="again">เล่นอีกรอบ</button><button id="toGloss">ไปดูคลังศัพท์</button></div>';
      document.getElementById("again").addEventListener("click", () => { pick(); draw(); });
      document.getElementById("toGloss").addEventListener("click", () => go({ v: "glossary" }));
      return;
    }
    const it = round[idx];
    box.innerHTML = '<div class="q-meta"><span>ข้อ ' + (idx + 1) + ' / ' + round.length + '</span><span>ถูก ' + score + '</span>' +
      '<span>ต่อเนื่อง ' + streak + '</span><span>' + it.q.mod + '</span></div>' +
      '<div class="prompt">' + it.q.ru + '</div><div class="prompt-sub">แปลว่าอะไร</div>' +
      '<div class="opts">' + it.opts.map((o, i) => '<button class="opt" data-i="' + i + '">' + o.th + '</button>').join("") + '</div>' +
      '<div class="quiz-foot"></div>';
    box.querySelectorAll(".opt").forEach(b => b.addEventListener("click", () => {
      const chosen = it.opts[+b.dataset.i];
      const ok = chosen.th === it.q.th;
      box.querySelectorAll(".opt").forEach((x, i) => {
        x.disabled = true;
        if (it.opts[i].th === it.q.th) x.classList.add("right");
        else if (x === b) x.classList.add("wrong");
      });
      if (ok) { score++; streak++; best = Math.max(best, streak); } else streak = 0;
      const foot = box.querySelector(".quiz-foot");
      foot.innerHTML = '<span class="verdict ' + (ok ? "ok" : "no") + '">' + (ok ? "ถูกต้อง" : "คำตอบคือ: " + it.q.th) + '</span>';
      const explanation = document.createElement("div");
      explanation.className = "quiz-explanation";
      const meaning = document.createElement("p");
      meaning.textContent = it.q.ru + " — " + it.q.th + (it.q.note ? ": " + it.q.note : "");
      explanation.appendChild(meaning);
      if (!ok) {
        const contrast = document.createElement("p");
        contrast.textContent = "ตัวเลือกที่คุณตอบ «" + chosen.th + "» ตรงกับ «" + chosen.ru + "»" + (chosen.note ? ": " + chosen.note : "") + " — ไม่ใช่ความหมายของคำที่ถาม";
        explanation.appendChild(contrast);
      }
      box.insertBefore(explanation, foot);
      const review = document.createElement("button");
      review.textContent = "ค้นคำนี้ในบทเรียน (ออกจากควิซ)";
      review.addEventListener("click", () => {
        searchEl.value = it.q.ru;
        go({ v: "search", q: it.q.ru.toLowerCase() });
      });
      foot.appendChild(review);
      const nxt = document.createElement("button");
      nxt.textContent = idx === round.length - 1 ? "ดูผล" : "ข้อถัดไป";
      nxt.addEventListener("click", () => { idx++; draw(); });
      foot.appendChild(nxt);
      nxt.focus();
    }));
  }
  pick(); draw();
}

/* ---- search box ---- */
let searchTimer;
searchEl.addEventListener("input", () => {
  clearTimeout(searchTimer);
  searchTimer = setTimeout(() => {
    const q = searchEl.value.trim().toLowerCase();
    if (state.v === "glossary" && renderGlossary.filter) { renderGlossary.filter(); return; }
    if (q.length >= 2) go({ v: "search", q });
    else if (state.v === "search") go({ v: "overview" });
  }, 160);
});
document.addEventListener("keydown", e => {
  if (e.key === "/" && document.activeElement !== searchEl) { e.preventDefault(); searchEl.focus(); }
  else if (e.key === "Escape" && document.activeElement === searchEl) { searchEl.value = ""; searchEl.blur(); if (state.v === "search") go({ v: "overview" }); }
});
document.getElementById("quizBtn").addEventListener("click", () => go({ v: "quiz" }));
window.matchMedia("(prefers-color-scheme: dark)").addEventListener("change", () => LIVE.forEach(d => d.draw && d.draw()));
new MutationObserver(() => LIVE.forEach(d => d.draw && d.draw()))
  .observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });

/* ---- v2: แถบล่างมือถือ + ปุ่มขึ้นบน + จำตำแหน่งอ่าน ---- */
document.querySelectorAll("#bbar [data-bb]").forEach(b => b.addEventListener("click", () => {
  const v = b.dataset.bb;
  if (v === "find") {
    window.scrollTo({ top: 0, behavior: "smooth" });
    searchEl.focus();
    return;
  }
  go({ v });
}));
const topBtn = document.getElementById("topBtn");
topBtn.addEventListener("click", () => window.scrollTo({ top: 0, behavior: "smooth" }));
let scrollSaveTimer;
window.addEventListener("scroll", () => {
  topBtn.classList.toggle("show", window.scrollY > 650);
  clearTimeout(scrollSaveTimer);
  scrollSaveTimer = setTimeout(() => {
    if (state.v === "subject" && LAST && LAST.id === state.id) {
      LAST.y = window.scrollY;
      saveLast();
    }
  }, 300);
}, { passive: true });

